-- Migration: add_2022_summer_substantive_q1_to_q40
--
-- Source: 2024 winter substantive-law batch (פברואר 2024, חלק ג', דין מהותי).
-- Two .docx files from the LawPass Content Pipeline Drive folder:
--   * (דין מהותי) 1-20  JSON.docx
--   * (דין מהותי) 21-40.docx  (contains Q21–Q40, with one duplicate of Q23)
--
-- Pipeline: scripts/ingestion/{parse_docx,normalize,generate_migration}.py +
-- the per-batch classification at scripts/ingestion/classifications/
-- 2024_winter_substantive.json. Re-classifies every question against the
-- substantive taxonomy from migration 20260526000001 (the JSON's own
-- chapter/subtopic — procedural placeholders from a stale Nevo template —
-- is ignored). source_metadata is also derived from the folder path, not
-- from the JSON's stale 2019/summer default.
--
-- Drops:
--   * 2024-W-S-Q20 — exact-content dup of Q18 (same question_text + choices).
--   * 2024-W-S-Q27 — JSON structurally broken beyond automatic repair.
--   * one in-file Q23 duplicate (the second of two consecutive Q23 fences).
--
-- Idempotency: each DO $$ block early-returns (RAISE NOTICE) if its
-- external_id already exists. Safe to re-run.

-- ============================================================
-- Q01 — 2022-S-S-Q01 — chapter=corporate subtopic=fiduciary_duties
-- classifier_note: Public-company CFO who is also controlling shareholder; exemption from breach-of-care liability — officer duties + exemption regime
-- ============================================================
DO $$
DECLARE
  v_sq_id uuid := 'b0445e35-0ea4-45d6-8169-ce788c19438a'::uuid;
  v_group_id uuid := 'dedcd910-6ab0-4265-a56d-8ad8e29ce8e3'::uuid;
  v_chapter_id uuid;
  v_subtopic_id uuid;
  v_existing_id uuid;
  v_ang_0 uuid := 'b89e317e-822c-4d01-b9d9-d27a27afeba3'::uuid;
  v_ang_1 uuid := '15cc7a07-7522-4e70-8953-d8ad87d86979'::uuid;
  v_ang_2 uuid := 'aee28d47-24c1-40a6-ad0a-52b1b33c1344'::uuid;
  v_ang_3 uuid := '452c2b3d-8c4a-4678-8484-e66ca068fec2'::uuid;
BEGIN
  SELECT id INTO v_existing_id FROM public.source_questions WHERE external_id = '2022-S-S-Q01';
  IF v_existing_id IS NOT NULL THEN
    RAISE NOTICE 'Q% skipped: external_id % already exists', 1, '2022-S-S-Q01';
    RETURN;
  END IF;

  SELECT id INTO v_chapter_id FROM public.chapters WHERE code = 'corporate';
  IF v_chapter_id IS NULL THEN
    RAISE EXCEPTION 'Chapter code % not found', 'corporate';
  END IF;

  SELECT id INTO v_subtopic_id FROM public.subtopics WHERE code = 'fiduciary_duties' AND chapter_id = v_chapter_id;
  IF v_subtopic_id IS NULL THEN
    RAISE EXCEPTION 'Subtopic code % not found under chapter %', 'fiduciary_duties', 'corporate';
  END IF;

  INSERT INTO public.source_questions (
    id, question_group_id, version, is_current, external_id, chapter_id, subtopic_id, question_text, source_metadata, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list, notes_for_admin, status, created_by
  ) VALUES (
    v_sq_id, v_group_id, 1, true,
    '2022-S-S-Q01', v_chapter_id, v_subtopic_id, 'חברה ציבורית מעוניינת לפטור את סמנכ"ל הכספים שלה המנהל את ענייניה הכספיים, שהוא גם בעל שליטה, מאחריות בגין הפרת חובת הזהירות כלפי החברה. לחברה אין כיום הסדרים כלשהם להענקת פטור. מה הדין?',
    '{"exam_year": 2022, "exam_season": "summer", "exam_part": 2, "exam_question_number": 1}'::jsonb, 'שאלה זו עוסקת בתנאים למתן פטור מאחריות לנושא משרה בחברה ציבורית, כאשר נושא המשרה הוא גם בעל שליטה. היא בוחנת את הדרישות הפרוצדורליות והמהותיות הקבועות בחוק החברות לאישור הסדר כזה, תוך דגש על הצורך באישור מיוחד של האסיפה הכללית.', 'חוק החברות, בסעיף 259(א), מאפשר לחברה לפטור נושא משרה מאחריות בגין הפרת חובת זהירות, למעט במקרים מסוימים המפורטים בסעיף 259(ב). סעיף 270 קובע כי תנאי כהונה והעסקה של נושא משרה, לרבות פטור, שיפוי וביטוח, יאושרו בהתאם למדיניות התגמול של החברה. סעיף 275(א) קובע כי אישור תנאי כהונה והעסקה של נושא משרה שהוא בעל שליטה דורש אישור של ועדת התגמול, הדירקטוריון והאסיפה הכללית, כאשר באסיפה הכללית נדרש רוב מקרב בעלי המניות שאינם בעלי עניין אישי באישור.', 'הבלבול בין הדרישות למתן פטור לנושא משרה רגיל לבין הדרישות המחמירות יותר החלות על נושא משרה שהוא גם בעל שליטה, ובפרט אי ידיעת הצורך באישור האסיפה הכללית ברוב מיוחד.',
    '["חוק החברות", "פטור נושא משרה", "בעל שליטה", "חובת זהירות", "מדיניות תגמול", "אסיפה כללית", "עניין אישי"]'::jsonb, '**פטור לבעל שליטה נושא משרה:** מהם התנאים לפטור בעל שליטה שהוא גם נושא משרה? ← תקנון, מדיניות תגמול, אישור ועדת תגמול, דירקטוריון ואסיפה כללית ברוב מיוחד (סעיפים 259, 270, 275 לחוק החברות).
**הבחנה בין פטור לשיפוי:** מה ההבדל העיקרי בין פטור לשיפוי? ← פטור הוא מראש מאחריות, שיפוי הוא בדיעבד על הוצאות (סעיפים 259 ו-262 לחוק החברות).
**איסור פטור:** באילו מקרים אסור לפטור נושא משרה? ← הפרת חובת אמונים, הפרת חובת זהירות בכוונה/פזיזות, קבלת טובת הנאה אישית שלא כדין, או כל מעשה עבירה (סעיף 259(ב) לחוק החברות).', 'פטור לבעל שליטה נושא משרה ← דורש אישור מורכב (תקנון, מדיניות תגמול, ועדה, דירקטוריון, אסיפה כללית ברוב מיוחד) ← חוק החברות.', '["חוק החברות, התשנ\"ט-1999, סעיפים 1, 259, 262, 267א, 270, 275"]'::jsonb,
    'classification_review: original chapter=''סדר דין אזרחי'' subtopic=''הליכים'' → mapped chapter=''corporate'' subtopic=''fiduciary_duties'' | classifier_note: Public-company CFO who is also controlling shareholder; exemption from breach-of-care liability — officer duties + exemption regime | source_review_note: שאלה זו עוסקת בדיני חברות (מהותי) ואינה משתייכת לתחום הדין הדיוני. סווגה תחת ''סדר דין אזרחי - הליכים'' כהצבת מקום בלבד.', 'active', 'b9ecdde2-d07e-4761-96ab-05f0ad32d4e3'
  );

  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'א', 'לא ניתן לפטור בעל שליטה מאחריות בגין הפרת חובת הזהירות כלפי החברה.', false, 'טענה זו אינה נכונה. חוק החברות מאפשר מתן פטור לבעל שליטה שהוא נושא משרה, בכפוף לעמידה בתנאים מחמירים הקבועים בחוק.', 1);
  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'ב', 'לא ניתן לפטור את מנהל ענייניה הכספיים של החברה מאחריות בגין הפרת חובת הזהירות כלפי החברה.', false, 'טענה זו אינה נכונה. חוק החברות מאפשר מתן פטור לנושא משרה בגין הפרת חובת זהירות, בכפוף לתנאים הקבועים בחוק, ואין איסור גורף על כך.', 2);
  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'ג', 'על החברה לאמץ סעיף המאפשר מתן פטור בתקנון, לתקן את מדיניות התגמול של החברה, וכן לקבל אישור של ועדת התגמול ודירקטוריון החברה כדרך שבה מאשרים תנאי כהונה של נושאי משרה.', false, 'אפשרות זו מתארת את הדרישות למתן פטור לנושא משרה שאינו בעל שליטה. במקרה של בעל שליטה, נדרש אישור נוסף של האסיפה הכללית ברוב מיוחד.', 3);
  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'ד', 'על החברה לאמץ סעיף המאפשר מתן פטור בתקנון, לתקן את מדיניות התגמול של החברה, וכן לקבל אישור מאת ועדת התגמול, הדירקטוריון והאסיפה הכללית, לרבות רוב מקרב מי שאין לו עניין אישי.', true, 'זוהי התשובה הנכונה. סעיפים 259, 270 ו-275 לחוק החברות קובעים כי מתן פטור לנושא משרה שהוא גם בעל שליטה דורש אישור של ועדת התגמול, הדירקטוריון והאסיפה הכללית, ברוב מקרב בעלי המניות שאין להם עניין אישי באישור.', 4);

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_0, v_sq_id, 'א', 'פטור לנושא משרה שאינו בעל שליטה',
    1, 'חברה פרטית מעוניינת לפטור את סמנכ"ל התפעול שלה, שאינו בעל שליטה בחברה, מאחריות בגין הפרת חובת הזהירות כלפי החברה. לחברה אין כיום הסדרים כלשהם למתן פטור. מה הדין?', 'שאלה זו בוחנת את ההבנה בדרישות למתן פטור לנושא משרה שאינו בעל שליטה, בניגוד לדרישות המחמירות יותר החלות על בעל שליטה. היא מדגישה את ההבחנה בין סוגי נושאי המשרה בחברה לעניין אישור הסדרי פטור.', 'חוק החברות, בסעיפים 259, 270 ו-275, מאפשר לחברה לפטור נושא משרה מאחריות בגין הפרת חובת זהירות, למעט במקרים מסוימים. עבור נושא משרה שאינו בעל שליטה, נדרש כי הוראה כזו תהיה בתקנון החברה, כי מדיניות התגמול תתוקן בהתאם, וכי יתקבל אישור של ועדת התגמול והדירקטוריון. אין צורך באישור האסיפה הכללית ברוב מיוחד במקרה זה.',
    'הבלבול בין הדרישות למתן פטור לנושא משרה רגיל לבין הדרישות המחמירות יותר החלות על נושא משרה שהוא גם בעל שליטה.', '["חוק החברות", "פטור נושא משרה", "חובת זהירות", "מדיניות תגמול", "ועדת תגמול", "דירקטוריון"]'::jsonb, '**פטור לנושא משרה רגיל:** מהם התנאים לפטור נושא משרה שאינו בעל שליטה? ← תקנון, מדיניות תגמול, אישור ועדת תגמול ודירקטוריון (סעיפים 259, 270, 275 לחוק החברות).
**הבחנה מבעל שליטה:** מה ההבדל העיקרי בדרישות בין נושא משרה רגיל לבעל שליטה? ← לבעל שליטה נדרש בנוסף אישור האסיפה הכללית ברוב מיוחד (סעיף 275 לחוק החברות).
**איסור פטור:** האם יש מקרים בהם אסור לפטור נושא משרה? ← כן, למשל הפרת חובת אמונים או קבלת טובת הנאה אישית שלא כדין (סעיף 259(ב) לחוק החברות).', 'פטור לנושא משרה רגיל ← דורש תקנון, מדיניות תגמול, אישור ועדת תגמול ודירקטוריון ← חוק החברות.',
    '["חוק החברות, התשנ\"ט-1999, סעיפים 259, 270, 275"]'::jsonb
  );
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_0, 'א', 'לא ניתן לפטור נושא משרה שאינו בעל שליטה מאחריות בגין הפרת חובת הזהירות כלפי החברה.', false, 'טענה זו אינה נכונה. חוק החברות מאפשר מתן פטור לנושא משרה שאינו בעל שליטה, בכפוף לתנאים מסוימים.', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_0, 'ב', 'על החברה לאמץ סעיף המאפשר מתן פטור בתקנון, לתקן את מדיניות התגמול של החברה, וכן לקבל אישור של ועדת התגמול ודירקטוריון החברה.', true, 'זוהי התשובה הנכונה. סעיפים 259, 270 ו-275 לחוק החברות קובעים כי מתן פטור לנושא משרה שאינו בעל שליטה דורש אישור של ועדת התגמול והדירקטוריון, בנוסף לסעיף בתקנון ומדיניות תגמול מעודכנת.', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_0, 'ג', 'על החברה לאמץ סעיף המאפשר מתן פטור בתקנון, ולקבל אישור של האסיפה הכללית בלבד.', false, 'אפשרות זו אינה מלאה ואינה מדויקת. נדרשים אישורים נוספים (ועדת תגמול ודירקטוריון) וכן מדיניות תגמול, ואישור האסיפה הכללית אינו נדרש לנושא משרה שאינו בעל שליטה.', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_0, 'ד', 'ניתן לפטור את סמנכ"ל התפעול ללא צורך בהסדרים מוקדמים, שכן הוא אינו בעל שליטה.', false, 'טענה זו אינה נכונה. גם לנושא משרה שאינו בעל שליטה נדרשים הסדרים מוקדמים ואישורים מתאימים על פי חוק החברות.', 4);

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_1, v_sq_id, 'ב', 'תנאי השיפוי בחוק החברות',
    2, 'חברה ציבורית מעוניינת לשפות את המנכ"ל שלה, שאינו בעל שליטה, בגין הוצאות משפט סבירות שהוציא בהליך פלילי שהוגש נגדו על ידי צד שלישי, והוא זוכה ממנו. לחברה אין כיום הסדרים כלשהם לשיפוי. מהם התנאים המצטברים שעל החברה לעמוד בהם כדי לאשר את השיפוי?', 'שאלה זו מתמקדת בתנאים הנדרשים למתן שיפוי לנושא משרה שאינו בעל שליטה, ומבחינה בין שיפוי לפטור. היא בוחנת את הדרישות הפרוצדורליות לאישור הסדר שיפוי בחברה ציבורית.', 'חוק החברות, בסעיפים 262, 270 ו-275, מאפשר לחברה לשפות נושא משרה בגין הוצאות מסוימות, לרבות הוצאות משפט סבירות בהליך פלילי שזוכה ממנו. לשם כך, נדרש כי הוראה כזו תהיה בתקנון החברה, כי מדיניות התגמול תתוקן בהתאם, וכי יתקבל אישור של ועדת התגמול והדירקטוריון. במקרה של נושא משרה שאינו בעל שליטה, אין צורך באישור האסיפה הכללית.',
    'הבלבול בין דרישות הפטור לדרישות השיפוי, או אי הבחנה בין נושא משרה רגיל לבעל שליטה בהקשר של שיפוי.', '["חוק החברות", "שיפוי נושא משרה", "הוצאות משפט", "מדיניות תגמול", "ועדת תגמול", "דירקטוריון"]'::jsonb, '**שיפוי לנושא משרה רגיל:** מהם התנאים לשיפוי נושא משרה שאינו בעל שליטה? ← תקנון, מדיניות תגמול, אישור ועדת תגמול ודירקטוריון (סעיפים 262, 270, 275 לחוק החברות).
**הבחנה בין פטור לשיפוי:** מה ההבדל העיקרי בין פטור לשיפוי? ← פטור הוא מראש מאחריות, שיפוי הוא בדיעבד על הוצאות (סעיפים 259 ו-262 לחוק החברות).

**מגבלות שיפוי:** באילו מקרים אסור לשפות נושא משרה? ← למשל, הפרת חובת אמונים, קבלת טובת הנאה אישית שלא כדין, קנס או כופר (סעיף 263(ב) לחוק החברות).', 'שיפוי לנושא משרה רגיל ← דורש תקנון, מדיניות תגמול, אישור ועדת תגמול ודירקטוריון ← חוק החברות.',
    '["חוק החברות, התשנ\"ט-1999, סעיפים 262, 270, 275"]'::jsonb
  );
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_1, 'א', 'על החברה לאמץ סעיף המאפשר שיפוי בתקנון, ולקבל אישור של הדירקטוריון בלבד.', false, 'אפשרות זו אינה מלאה. נדרש גם אישור ועדת התגמול וכן מדיניות תגמול מעודכנת, בנוסף לסעיף בתקנון ואישור הדירקטוריון.', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_1, 'ב', 'על החברה לאמץ סעיף המאפשר שיפוי בתקנון, לתקן את מדיניות התגמול של החברה, וכן לקבל אישור של ועדת התגמול והדירקטוריון.', true, 'זוהי התשובה הנכונה. סעיפים 262, 270 ו-275 לחוק החברות קובעים כי מתן שיפוי לנושא משרה דורש סעיף בתקנון, מדיניות תגמול מעודכנת, ואישור של ועדת התגמול והדירקטוריון.', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_1, 'ג', 'ניתן לשפות את המנכ"ל ללא צורך בהסדרים מוקדמים, שכן הוא זוכה מההליך הפלילי.', false, 'טענה זו אינה נכונה. גם במקרה של זיכוי, נדרשים הסדרים מוקדמים ואישורים מתאימים על פי חוק החברות כדי לאשר שיפוי.', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_1, 'ד', 'על החברה לאמץ סעיף המאפשר שיפוי בתקנון, ולקבל אישור של האסיפה הכללית, לרבות רוב מקרב מי שאין לו עניין אישי.', false, 'אישור האסיפה הכללית ברוב מיוחד נדרש רק כאשר מדובר בשיפוי לבעל שליטה, ולא לנושא משרה שאינו בעל שליטה.', 4);

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_2, v_sq_id, 'ג', 'מקרים בהם אסור לתת פטור או שיפוי',
    3, 'באילו מהמקרים הבאים חוק החברות אוסר על חברה להעניק פטור או שיפוי לנושא משרה?', 'שאלה זו בוחנת את המגבלות והאיסורים הקבועים בחוק החברות על מתן פטור ושיפוי לנושאי משרה. היא מדגישה את המקרים החמורים בהם החוק אינו מאפשר לחברה להגן על נושאי המשרה שלה מפני אחריות או הוצאות.', 'חוק החברות קובע רשימה סגורה של מקרים בהם חברה אינה רשאית להעניק פטור או שיפוי לנושא משרה. סעיף 259(ב) אוסר פטור בגין הפרת חובת אמונים, הפרת חובת זהירות שנעשתה בכוונה או בפזיזות, קבלת טובת הנאה אישית שלא כדין, או כל מעשה עבירה. סעיף 263(ב) אוסר שיפוי בגין הפרת חובת אמונים, הפרת חובת זהירות שנעשתה בכוונה או בפזיזות, קבלת טובת הנאה אישית שלא כדין, או קנס/כופר שהוטל על נושא המשרה.',
    'אי ידיעת המקרים הספציפיים בהם חל איסור מוחלט על מתן פטור או שיפוי, ובלבול בינם לבין מקרים בהם הפטור או השיפוי מותרים.', '["חוק החברות", "פטור נושא משרה", "שיפוי נושא משרה", "חובת אמונים", "חובת זהירות", "קבלת טובת הנאה אישית שלא כדין"]'::jsonb, '**איסור פטור:** באילו מקרים אסור לפטור נושא משרה? ← הפרת חובת אמונים, הפרת חובת זהירות בכוונה/פזיזות, טובת הנאה שלא כדין, עבירה (סעיף 259(ב) לחוק החברות).
**איסור שיפוי:** באילו מקרים אסור לשפות נושא משרה? ← הפרת חובת אמונים, הפרת חובת זהירות בכוונה/פזיזות, טובת הנאה שלא כדין, קנס/כופר (סעיף 263(ב) לחוק החברות).
**הבחנה בין חובות:** האם ניתן לפטור מהפרת חובת זהירות שאינה מכוונת? ← כן, בכפוף לתנאים, אך לא מהפרת חובת אמונים (סעיף 259 לחוק החברות).', 'איסור פטור/שיפוי ← חובת אמונים, כוונה/פזיזות, טובת הנאה שלא כדין, קנס/עבירה ← חוק החברות.',
    '["חוק החברות, התשנ\"ט-1999, סעיפים 259(ב), 263(ב)"]'::jsonb
  );
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_2, 'א', 'הפרת חובת זהירות שאינה מכוונת.', false, 'חוק החברות מאפשר פטור ושיפוי בגין הפרת חובת זהירות שאינה מכוונת, בכפוף לתנאים הקבועים בחוק.', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_2, 'ב', 'הפרת חובת אמונים, קבלת טובת הנאה אישית שלא כדין, או קנס שהוטל על נושא המשרה.', true, 'זוהי התשובה הנכונה. סעיפים 259(ב) ו-263(ב) לחוק החברות אוסרים על מתן פטור או שיפוי במקרים אלו, שכן הם נחשבים חמורים ופוגעים בטובת החברה.', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_2, 'ג', 'הוצאות משפט סבירות בהליך אזרחי שבו נושא המשרה חויב בתשלום פיצויים.', false, 'חוק החברות מאפשר שיפוי בגין הוצאות משפט סבירות בהליך אזרחי, גם אם נושא המשרה חויב בפיצויים, כל עוד לא מדובר בהפרת חובת אמונים או קבלת טובת הנאה אישית שלא כדין.', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_2, 'ד', 'כל הפרה של חובת זהירות, ללא קשר לאופייה.', false, 'טענה זו אינה נכונה. חוק החברות מבחין בין סוגי הפרות חובת זהירות ומאפשר פטור או שיפוי במקרים מסוימים, למשל כאשר ההפרה אינה מכוונת.', 4);

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_3, v_sq_id, 'ד', 'ביטוח אחריות נושאי משרה',
    4, 'חברה ציבורית מעוניינת לרכוש ביטוח אחריות לנושאי המשרה שלה. המנכ"ל הוא גם בעל שליטה בחברה. מהם התנאים המצטברים שעל החברה לעמוד בהם כדי לאשר את רכישת הביטוח?', 'שאלה זו עוסקת בתנאים הנדרשים לרכישת ביטוח אחריות לנושאי משרה, ובפרט כאשר נושא המשרה הוא גם בעל שליטה. היא מדגישה את הדמיון בדרישות האישור בין ביטוח, פטור ושיפוי.', 'חוק החברות, בסעיפים 259, 270 ו-275, מאפשר לחברה לרכוש ביטוח אחריות לנושאי משרה. הדרישות לאישור רכישת ביטוח דומות לדרישות למתן פטור ושיפוי. כאשר מדובר בנושא משרה שהוא גם בעל שליטה, נדרש כי הוראה כזו תהיה בתקנון החברה, כי מדיניות התגמול תתוקן בהתאם, וכי יתקבל אישור של ועדת התגמול, הדירקטוריון והאסיפה הכללית, ברוב מקרב בעלי המניות שאין להם עניין אישי באישור.',
    'הנחה שביטוח אחריות אינו כפוף לאותן דרישות אישור מחמירות כמו פטור ושיפוי, או אי הבחנה בין נושא משרה רגיל לבעל שליטה בהקשר של ביטוח.', '["חוק החברות", "ביטוח אחריות נושאי משרה", "מדיניות תגמול", "ועדת תגמול", "דירקטוריון", "אסיפה כללית", "בעל שליטה"]'::jsonb, '**ביטוח לבעל שליטה:** מהם התנאים לביטוח אחריות לבעל שליטה שהוא נושא משרה? ← תקנון, מדיניות תגמול, אישור ועדת תגמול, דירקטוריון ואסיפה כללית ברוב מיוחד (סעיפים 259, 270, 275 לחוק החברות).
**הבחנה מנושא משרה רגיל:** מה ההבדל בדרישות לביטוח בין נושא משרה רגיל לבעל שליטה? ← לבעל שליטה נדרש בנוסף אישור האסיפה הכללית ברוב מיוחד.
**מגבלות ביטוח:** באילו מקרים אסור לבטח נושא משרה? ← למשל, הפרת חובת אמונים, קבלת טובת הנאה אישית שלא כדין, או קנס/כופר (סעיף 259(ב) לחוק החברות).', 'ביטוח אחריות לבעל שליטה נושא משרה ← דורש אישור מורכב (תקנון, מדיניות תגמול, ועדה, דירקטוריון, אסיפה כללית ברוב מיוחד) ← חוק החברות.',
    '["חוק החברות, התשנ\"ט-1999, סעיפים 259, 270, 275"]'::jsonb
  );
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_3, 'א', 'על החברה לאמץ סעיף המאפשר ביטוח בתקנון, ולקבל אישור של הדירקטוריון בלבד.', false, 'אפשרות זו אינה מלאה. נדרש גם אישור ועדת התגמול וכן מדיניות תגמול מעודכנת, ובמקרה של בעל שליטה, גם אישור האסיפה הכללית ברוב מיוחד.', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_3, 'ב', 'על החברה לאמץ סעיף המאפשר ביטוח בתקנון, לתקן את מדיניות התגמול של החברה, וכן לקבל אישור של ועדת התגמול והדירקטוריון.', false, 'אפשרות זו מתארת את הדרישות לביטוח נושא משרה שאינו בעל שליטה. במקרה של בעל שליטה, נדרש אישור נוסף של האסיפה הכללית ברוב מיוחד.', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_3, 'ג', 'על החברה לאמץ סעיף המאפשר ביטוח בתקנון, לתקן את מדיניות התגמול של החברה, וכן לקבל אישור מאת ועדת התגמול, הדירקטוריון והאסיפה הכללית, לרבות רוב מקרב מי שאין לו עניין אישי.', true, 'זוהי התשובה הנכונה. סעיפים 259, 270 ו-275 לחוק החברות קובעים כי רכישת ביטוח אחריות לנושא משרה שהוא גם בעל שליטה דורשת אישור של ועדת התגמול, הדירקטוריון והאסיפה הכללית, ברוב מקרב בעלי המניות שאין להם עניין אישי באישור.', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_3, 'ד', 'ניתן לרכוש ביטוח אחריות לנושאי משרה ללא צורך בהסדרים מוקדמים, שכן מדובר בביטוח ולא בפטור או שיפוי ישיר.', false, 'טענה זו אינה נכונה. גם רכישת ביטוח אחריות לנושאי משרה כפופה לדרישות אישור והסדרים מוקדמים בחוק החברות, בדומה לפטור ושיפוי.', 4);

  RAISE NOTICE 'Q% inserted: external_id %', 1, '2022-S-S-Q01';
END
$$;

-- ============================================================
-- Q02 — 2022-S-S-Q02 — chapter=contracts subtopic=standard_contracts
-- classifier_note: Builder's apartment sale, contractual delay clause ('65 days excluded') — unfair-term review under standard-form contracts law
-- ============================================================
DO $$
DECLARE
  v_sq_id uuid := '653fb265-5494-4d4c-8480-9d390e497c47'::uuid;
  v_group_id uuid := 'f43ee00b-146d-4685-96de-05d335b00f7d'::uuid;
  v_chapter_id uuid;
  v_subtopic_id uuid;
  v_existing_id uuid;
  v_ang_0 uuid := 'eff3ed00-a8c3-424e-ac11-b579fbbd639c'::uuid;
  v_ang_1 uuid := '125ea3ec-02f5-4ea3-9bbd-67f787fae6e1'::uuid;
  v_ang_2 uuid := '35ccee61-691f-4f4c-83ee-c4084a0b721b'::uuid;
  v_ang_3 uuid := '55a37756-3ff8-4988-b47a-c4cfb6ee061f'::uuid;
BEGIN
  SELECT id INTO v_existing_id FROM public.source_questions WHERE external_id = '2022-S-S-Q02';
  IF v_existing_id IS NOT NULL THEN
    RAISE NOTICE 'Q% skipped: external_id % already exists', 2, '2022-S-S-Q02';
    RETURN;
  END IF;

  SELECT id INTO v_chapter_id FROM public.chapters WHERE code = 'contracts';
  IF v_chapter_id IS NULL THEN
    RAISE EXCEPTION 'Chapter code % not found', 'contracts';
  END IF;

  SELECT id INTO v_subtopic_id FROM public.subtopics WHERE code = 'standard_contracts' AND chapter_id = v_chapter_id;
  IF v_subtopic_id IS NULL THEN
    RAISE EXCEPTION 'Subtopic code % not found under chapter %', 'standard_contracts', 'contracts';
  END IF;

  INSERT INTO public.source_questions (
    id, question_group_id, version, is_current, external_id, chapter_id, subtopic_id, question_text, source_metadata, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list, notes_for_admin, status, created_by
  ) VALUES (
    v_sq_id, v_group_id, 1, true,
    '2022-S-S-Q02', v_chapter_id, v_subtopic_id, 'איגור מציג בפניך הסכם מכר לרכישת דירה מקבלן עם מועד מסירת חזקה ביום 1.1.2021. הקבלן איחר במועד מסירת הדירה, ובפועל מסר את הדירה ביום 31.5.2021. בהסכם המכר נכתב כי "65 הימים הראשונים לא ייחשבו במניין הימים לשם תחשיב הפיצוי בגין האיחור במסירה". החל מאיזה תאריך ייקבע תחשיב הפיצוי עבור דמי השכירות החודשיים שלו זכאי איגור?',
    '{"exam_year": 2022, "exam_season": "summer", "exam_part": 2, "exam_question_number": 2}'::jsonb, 'שאלה זו עוסקת במנגנון הפיצוי הסטטוטורי בגין איחור במסירת דירה לפי סעיף 5א לחוק המכר (דירות), התשל"ג-1973. היא בוחנת את הבנת תקופת החסד (גרייס) ואת אופיו הקוגנטי של החוק, המונע מהמוכר להתנות על הוראותיו לרעת הקונה, ובפרט את חישוב הפיצויים רטרואקטיבית מהמועד החוזי המקורי במקרה של איחור העולה על תקופת החסד הסטטוטורית.', 'סעיף 5א לחוק המכר (דירות), בנוסחו הרלוונטי למועד חתימת ההסכם (1.1.2021, לפני תיקון מס'' 9), קבע תקופת חסד של 60 ימים. אם האיחור במסירה עולה על 60 ימים, הקונה זכאי לפיצויים, ללא הוכחת נזק, החל מהמועד החוזי המקורי (ולא רק מתום תקופת החסד). הוראות החוק הן קוגנטיות (סעיף 7א), וניתן להתנות עליהן רק לטובת הקונה. לכן, תניית 65 הימים בחוזה, שהיא לרעת הקונה (ארוכה מתקופת החסד הסטטוטורית), בטלה. מאחר שהדירה נמסרה באיחור של 5 חודשים (מ-1.1.2021 עד 31.5.2021), האיחור עולה על 60 הימים, ולכן הפיצוי מחושב רטרואקטיבית מיום 1.1.2021. הלכה זו נפסקה בפסיקת בית המשפט העליון, לרבות ב''הלכת שמש'' (רע"א 6605/15).', 'הבלבול בין תקופת החסד הסטטוטורית לבין תניות חוזיות המנסות להאריך אותה לרעת הקונה, ואי הבנה של עקרון הרטרואקטיביות בחישוב הפיצויים לאחר חלוף תקופת החסד.',
    '["חוק המכר (דירות)", "סעיף 5א", "פיצוי בגין איחור במסירה", "תקופת חסד (גרייס)", "הוראה קוגנטית", "הלכת שמש", "חישוב רטרואקטיבי"]'::jsonb, '**וריאציה 1 — תקופת חסד:** מהי תקופת החסד הקבועה בחוק המכר (דירות) לפני תיקון 9? ← 60 יום (סעיף 5א לחוק המכר (דירות) בנוסחו לפני תיקון 9).

**וריאציה 2 — קוגנטיות:** האם ניתן להתנות על תקופת החסד לרעת הקונה? ← לא, החוק קוגנטי וניתן להתנות עליו רק לטובת הקונה (סעיף 7א לחוק המכר (דירות)).
**וריאציה 3 — חישוב רטרואקטיבי:** מתי מתחיל חישוב הפיצוי אם האיחור עולה על תקופת החסד? ← מהמועד החוזי המקורי (הלכת שמש, סעיף 5א לחוק המכר (דירות)).', 'איחור במסירת דירה ← תקופת חסד סטטוטורית (60 יום לפני תיקון 9) ← אם האיחור עולה על תקופת החסד ← פיצוי רטרואקטיבי מהמועד החוזי המקורי ← הוראות החוק קוגנטיות לטובת הקונה.', '["חוק המכר (דירות), התשל\"ג-1973, סעיף 5א", "רע\"א 6605/15 אילנה שמש נ'' ספייס בניה ויזמות בע\"מ (21.2.2016)", "ע\"א (מחוזי ת\"א) 2176-06-21 ס.י. אבן יזמות בע\"מ נ'' נסים חדד (14.04.2022)", "ת\"א (שלום חי'') 40152-12-20 חסקי אלון חיזוק ושיקום מבנים בע\"מ נ'' אסף כדורי (21.04.2025)"]'::jsonb,
    'classification_review: original chapter=''סדר דין אזרחי'' subtopic=''הליכים'' → mapped chapter=''contracts'' subtopic=''standard_contracts'' | classifier_note: Builder''s apartment sale, contractual delay clause (''65 days excluded'') — unfair-term review under standard-form contracts law | source_review_note: שאלה זו עוסקת בדיני מקרקעין/חוזים (מהותי) ואינה משתייכת לתחום הדין הדיוני. סווגה תחת ''סדר דין אזרחי - הליכים'' כהצבת מקום בלבד.', 'active', 'b9ecdde2-d07e-4761-96ab-05f0ad32d4e3'
  );

  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'א', 'מיום 1.3.2021.', false, 'תשובה זו מתעלמת מכך שתניית הפטור החוזית בטלה, וכי הפיצוי מחושב רטרואקטיבית מהמועד החוזי המקורי.', 1);
  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'ב', 'מיום 1.1.2021.', true, 'זוהי התשובה הנכונה. מאחר שההסכם נחתם לפני תיקון מס'' 9 לחוק המכר (דירות), תקופת החסד הסטטוטורית היא 60 יום. תניית 65 הימים בחוזה בטלה כיוון שהיא לרעת הקונה. האיחור בפועל (5 חודשים) עולה על 60 יום, ולכן הפיצוי מחושב רטרואקטיבית מהמועד החוזי המקורי.', 2);
  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'ג', 'מיום 28.2.2021.', false, 'תשובה זו מניחה תקופת חסד של חודשיים (60 יום) ומתחילה את הפיצוי לאחריה, אך מתעלמת מהרטרואקטיביות של הפיצוי.', 3);
  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'ד', 'מיום 7.3.2021.', false, 'תשובה זו מנסה ליישם את תניית 65 הימים החוזית, שהיא בטלה, ומתעלמת מהרטרואקטיביות של הפיצוי.', 4);

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_0, v_sq_id, 'א', 'חישוב פיצויים לאחר תיקון 9 לחוק המכר (דירות)',
    1, 'ראובן רכש דירה מקבלן בהסכם שנחתם ביום 1.1.2023, ומועד המסירה החוזי נקבע ליום 1.7.2024. הקבלן איחר במסירה, והדירה נמסרה בפועל ביום 1.9.2024. בהסכם המכר נקבע כי "35 הימים הראשונים לא ייחשבו במניין הימים לשם תחשיב הפיצוי בגין האיחור במסירה". החל מאיזה תאריך ייקבע תחשיב הפיצוי עבור דמי השכירות החודשיים שלו זכאי ראובן?', 'שאלה זו בוחנת את הבנת תיקון מס'' 9 לחוק המכר (דירות) משנת 2022, שקיצר את תקופת החסד הסטטוטורית לחודש אחד. היא מדגישה את עקרון הקוגנטיות של החוק ואת חישוב הפיצויים רטרואקטיבית מהמועד החוזי המקורי אם האיחור עולה על תקופת החסד.', 'תיקון מס'' 9 לחוק המכר (דירות), שנכנס לתוקף ב-7.7.2022, שינה את תקופת החסד הסטטוטורית מ-60 יום לחודש אחד. מאחר שההסכם נחתם ב-1.1.2023, חל עליו הנוסח המתוקן. תניית 35 הימים בחוזה בטלה, שכן היא לרעת הקונה (ארוכה יותר מתקופת החסד הסטטוטורית של חודש). האיחור בפועל הוא חודשיים (מ-1.7.2024 עד 1.9.2024). מאחר שהאיחור עולה על חודש אחד, הפיצויים מחושבים רטרואקטיבית מהמועד החוזי המקורי, קרי 1.7.2024.',
    'אי ידיעת השינוי בתקופת החסד בעקבות תיקון מס'' 9, או יישום שגוי של עקרון הקוגנטיות.', '["חוק המכר (דירות) (תיקון מס'' 9)", "תקופת חסד", "קוגנטיות", "פיצוי רטרואקטיבי"]'::jsonb, '**וריאציה 1 — תיקון 9:** מהי תקופת החסד לאחר תיקון 9? ← חודש אחד (סעיף 5א לחוק המכר (דירות) בנוסחו המתוקן).
**וריאציה 2 — תנייה חוזית:** האם תניית 35 יום תקפה? ← לא, היא לרעת הקונה ולכן בטלה (סעיף 7א לחוק המכר (דירות)).
**וריאציה 3 — חישוב:** מתי מתחיל הפיצוי? ← מהמועד החוזי המקורי, 1.7.2024, כיוון שהאיחור עולה על חודש (סעיף 5א לחוק המכר (דירות)).', 'חוזה לאחר תיקון 9 ← תקופת חסד חודש ← איחור מעל חודש ← פיצוי רטרואקטיבי מהמועד החוזי.',
    '["חוק המכר (דירות), התשל\"ג-1973, סעיף 5א"]'::jsonb
  );
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_0, 'א', 'מיום 1.8.2024.', false, 'תשובה זו מתעלמת מכך שתניית הפטור החוזית בטלה, וכי הפיצוי מחושב רטרואקטיבית מהמועד החוזי המקורי.', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_0, 'ב', 'מיום 1.7.2024.', true, 'זוהי התשובה הנכונה. החוזה נחתם לאחר תיקון מס'' 9, ולכן תקופת החסד הסטטוטורית היא חודש אחד. האיחור בפועל (חודשיים) עולה על חודש זה, ולכן הפיצוי מחושב רטרואקטיבית מהמועד החוזי המקורי. תניית 35 הימים בחוזה בטלה כיוון שהיא לרעת הקונה.', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_0, 'ג', 'מיום 5.8.2024.', false, 'תשובה זו מנסה ליישם את תניית 35 הימים החוזית, שהיא בטלה, ומתעלמת מהרטרואקטיביות של הפיצוי.', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_0, 'ד', 'מיום 1.9.2024.', false, 'תשובה זו מתעלמת לחלוטין מהאיחור ומתחילה את הפיצוי רק ממועד המסירה בפועל.', 4);

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_1, v_sq_id, 'ב', 'התנייה על סעיף 5א לחוק המכר (דירות)',
    2, 'האם ניתן להתנות על הוראות סעיף 5א לחוק המכר (דירות) הקובע את מנגנון הפיצוי בגין איחור במסירה?', 'שאלה זו בוחנת את עקרון הקוגנטיות של חוק המכר (דירות), ובפרט של סעיף 5א העוסק בפיצויים בגין איחור במסירה. היא מדגישה את ההגנה המיוחדת שהמחוקק מעניק לרוכשי דירות.', 'סעיף 7א(א) לחוק המכר (דירות) קובע מפורשות כי "אין להתנות על הוראות חוק זה, אלא לטובת הקונה או קונה המשנה". משמעות הדבר היא שהוראות סעיף 5א, המפרטות את מנגנון הפיצוי בגין איחור במסירה, הן קוגנטיות. כלומר, הצדדים אינם רשאים לקבוע בהסכם תנאים הגורעים מזכויות הקונה לפי החוק, אלא אם התנאים המוסכמים מיטיבים עם הקונה יותר מהוראות החוק. פסיקת בתי המשפט, לרבות הלכת שמש, מדגישה את חשיבות ההגנה על רוכשי דירות ואת אופיו הקוגנטי של החוק.',
    'הנחה שגויה כי הצדדים חופשיים להתנות על כל הוראה בחוזה, או אי הבנה של משמעות המונח ''קוגנטי'' בהקשר של חוק המכר (דירות).', '["חוק המכר (דירות)", "הוראה קוגנטית", "חופש החוזים", "הגנת הצרכן", "סעיף 7א"]'::jsonb, '**וריאציה 1 — עקרון הקוגנטיות:** מהי המשמעות של הוראה קוגנטית בחוק המכר (דירות)? ← לא ניתן להתנות עליה אלא לטובת הקונה (סעיף 7א לחוק המכר (דירות)).
**וריאציה 2 — תכלית החוק:** מדוע חוק המכר (דירות) קוגנטי? ← להגן על רוכשי דירות שהם הצד החלש בעסקה (הלכת שמש).
**וריאציה 3 — דוגמה להתניה מותרת:** האם ניתן לקבוע פיצוי גבוה יותר מהקבוע בחוק? ← כן, אם הוא לטובת הקונה (סעיף 5א(א) לחוק המכר (דירות)).', 'התניה על חוק המכר (דירות) ← מותרת רק לטובת הקונה ← סעיף 7א.',
    '["חוק המכר (דירות), התשל\"ג-1973, סעיף 7א", "רע\"א 6605/15 אילנה שמש נ'' ספייס בניה ויזמות בע\"מ (21.2.2016)"]'::jsonb
  );
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_1, 'א', 'כן, הצדדים חופשיים להתנות על הוראות החוק כרצונם, כחלק מחופש החוזים.', false, 'טענה זו אינה נכונה. חוק המכר (דירות) הוא חוק קוגנטי, המגביל את חופש החוזים במטרה להגן על רוכשי דירות.', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_1, 'ב', 'לא, הוראות סעיף 5א הן קוגנטיות ולא ניתן להתנות עליהן כלל.', false, 'טענה זו אינה מדויקת. ניתן להתנות על הוראות החוק, אך רק לטובת הקונה.', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_1, 'ג', 'כן, אך רק אם ההתניה היא לטובת הקונה.', true, 'זוהי התשובה הנכונה. סעיף 7א לחוק המכר (דירות) קובע כי אין להתנות על הוראות החוק אלא לטובת הקונה.', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_1, 'ד', 'כן, אם ההתניה אושרה על ידי בית הדין לחוזים אחידים.', false, 'אישור בית הדין לחוזים אחידים רלוונטי לתניות מקפחות בחוזים אחידים, אך אינו מבטל את עקרון הקוגנטיות של סעיף 5א לחוק המכר (דירות).', 4);

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_2, v_sq_id, 'ג', 'איחור במסירה עקב נסיבות שאינן בשליטת המוכר',
    3, 'קבלן איחר במסירת דירה עקב סגרים שהוטלו בעקבות מגפת הקורונה, ובהסכם המכר נכלל סעיף כללי הפוטר את הקבלן מפיצוי במקרה של ''כוח עליון''. האם הקבלן יהיה פטור מתשלום פיצויים בגין האיחור?', 'שאלה זו עוסקת בסייג לאחריות הקבלן לפי סעיף 5א לחוק המכר (דירות), במקרים של איחור במסירה שנגרם מנסיבות שאינן בשליטתו. היא בוחנת את הדרישה להוכחה קונקרטית ואת פרשנות תניות ''כוח עליון'' בחוזים אחידים.', 'סעיף 5א(ג) לחוק המכר (דירות) (בנוסחו לפני תיקון 9, וסעיף 5א(ג)(2) בנוסח המתוקן) קובע כי הצדדים רשאים להסכים שהוראות הפיצוי לא יחולו על איחור במסירה שנגרם כתוצאה מנסיבות שאינן בשליטת המוכר ושהסיכון להתרחשותן ולתוצאותיהן אינו מוטל עליו. הפסיקה קבעה כי הנטל להוכיח את התקיימות התנאים הללו מוטל על הקבלן, וכי נדרשת הוכחה קונקרטית ומפורטת, ולא די בסעיף כללי של ''כוח עליון'' בחוזה. הקבלן צריך להראות כיצד הנסיבות הספציפיות (כגון סגרים) השפיעו ישירות על לוחות הזמנים וכיצד הוא פעל לצמצום האיחור.',
    'הנחה שגויה כי סעיף כללי של ''כוח עליון'' בחוזה מספיק כדי לפטור את הקבלן מאחריות, ללא צורך בהוכחה קונקרטית.', '["חוק המכר (דירות)", "כוח עליון", "נסיבות שאינן בשליטת המוכר", "נטל ההוכחה", "תניות פטור"]'::jsonb, '**וריאציה 1 — תנאי הפטור:** מהם התנאים לפטור קבלן מפיצוי עקב נסיבות שאינן בשליטתו? ← הנסיבות אינן בשליטתו והסיכון לא מוטל עליו (סעיף 5א(ג) לחוק המכר (דירות)).
**וריאציה 2 — נטל ההוכחה:** מי נושא בנטל ההוכחה? ← הקבלן, ועליו להוכיח באופן קונקרטי (ע"א (מחוזי חי'') 50008-12-23 ליאור אשכנזי נ'' פ.א. אריה פרידמן (2006) בע"מ).
**וריאציה 3 — תנייה כללית:** האם תניית ''כוח עליון'' כללית מספיקה? ← לא, נדרשת הוכחה קונקרטית ולא הסתמכות על תנייה גורפת (פסק דין שמש, איל זמיר, חוק המכר - פירוש לחוקי החוזים - כרך א, עמ'' 33).', 'פטור מפיצוי עקב נסיבות שאינן בשליטת המוכר ← דורש הוכחה קונקרטית של הקבלן ← סעיף 5א(ג) לחוק המכר (דירות).',
    '["חוק המכר (דירות), התשל\"ג-1973, סעיף 5א(ג)", "ע\"א (מחוזי חי'') 50008-12-23 ליאור אשכנזי נ'' פ.א. אריה פרידמן (2006) בע\"מ (04.06.2024)", "איל זמיר, חוק המכר - פירוש לחוקי החוזים - כרך א (2023), עמ'' 33"]'::jsonb
  );
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_2, 'א', 'כן, סגרים עקב מגפה נחשבים לכוח עליון, והסעיף בחוזה פוטר את הקבלן.', false, 'טענה זו אינה נכונה. סעיף 5א(ג) לחוק המכר (דירות) דורש שהנסיבות לא יהיו בשליטת המוכר ושהסיכון להתרחשותן לא יוטל עליו, ופסיקת בתי המשפט דורשת הוכחה קונקרטית ולא הסתמכות על סעיף כללי.', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_2, 'ב', 'לא, אלא אם הקבלן יוכיח באופן קונקרטי שהאיחור נגרם ישירות מהסגרים ושהסיכון לא הוטל עליו.', true, 'זוהי התשובה הנכונה. סעיף 5א(ג) לחוק המכר (דירות) מאפשר פטור רק אם האיחור נגרם מנסיבות שאינן בשליטת המוכר ושהסיכון להתרחשותן אינו מוטל עליו, ונדרשת הוכחה קונקרטית לכך.', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_2, 'ג', 'כן, אם הסעיף בחוזה אושר על ידי בית הדין לחוזים אחידים.', false, 'אישור בית הדין לחוזים אחידים אינו פוטר את הקבלן מהצורך להוכיח את התקיימות התנאים הקבועים בסעיף 5א(ג) לחוק המכר (דירות).', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_2, 'ד', 'לא, חוק המכר (דירות) אינו מאפשר פטור מפיצויים בשום מקרה של איחור במסירה.', false, 'טענה זו אינה נכונה. סעיף 5א(ג) לחוק המכר (דירות) (או 5א(ג)(2) בנוסח המתוקן) כן מאפשר פטור במקרים מסוימים של נסיבות שאינן בשליטת המוכר.', 4);

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_3, v_sq_id, 'ד', 'הוכחת דמי שכירות ראויים',
    4, 'קונה דירה תובע פיצויים בגין איחור במסירה לפי סעיף 5א לחוק המכר (דירות). הקונה טוען לדמי שכירות חודשיים בסך 8,000 ש"ח, בעוד הקבלן טוען ל-6,000 ש"ח. כיצד ייקבע בית המשפט את גובה דמי השכירות הראויים לצורך חישוב הפיצוי?', 'שאלה זו עוסקת בהיבט המעשי של חישוב הפיצויים לפי סעיף 5א לחוק המכר (דירות), ובפרט בקביעת רכיב ''דמי שכירות של דירה דומה''. היא בוחנת את הדרך המקובלת בבתי המשפט להכרעה במחלוקות בנושא זה.', 'סעיף 5א לחוק המכר (דירות) קובע כי הפיצוי בגין איחור במסירה ייקבע, בין היתר, לפי ''סכום השווה לדמי שכירות של דירה דומה בגודלה ובמיקומה''. כאשר קיימת מחלוקת בין הצדדים לגבי גובה דמי השכירות הראויים, בית המשפט נוהג למנות שמאי מקרקעין מטעמו כמומחה ניטרלי. חוות דעתו של השמאי תשמש בסיס לקביעת דמי השכירות הראויים, אלא אם כן קיימות נסיבות מיוחדות המצדיקות סטייה ממנה. על הצדדים מוטל הנטל להוכיח את טענותיהם לגבי גובה דמי השכירות, לרוב באמצעות חוות דעת שמאיות מטעמם.',
    'הנחה שגויה כי בית המשפט יקבל את טענת אחד הצדדים ללא בחינה, או אי ידיעת התפקיד של מומחה מטעם בית המשפט בקביעת דמי שכירות.', '["חוק המכר (דירות)", "דמי שכירות ראויים", "שמאי מקרקעין", "מומחה מטעם בית המשפט", "נטל ההוכחה"]'::jsonb, '**וריאציה 1 — קביעת דמי שכירות:** כיצד נקבעים דמי שכירות ראויים במחלוקת? ← על ידי מינוי שמאי מומחה מטעם בית המשפט (ת"א (שלום ת"א) 22707-07-22 ליאור ריחן נ'' גן השיקמים בע"מ).
**וריאציה 2 — נטל הוכחה:** מי נושא בנטל להוכיח את דמי השכירות? ← הקונה, אך בית המשפט יסתמך על מומחה מטעמו (ת"א (שלום חי'') 40152-12-20 חסקי אלון חיזוק ושיקום מבנים בע"מ נ'' אסף כדורי).
**וריאציה 3 — תכלית הפיצוי:** מהי תכלית הפיצוי לפי סעיף 5א? ← פיצוי ללא הוכחת נזק, אך יש להוכיח את בסיס החישוב (דמי שכירות) (רע"א 6605/15 אילנה שמש נ'' ספייס בניה ויזמות בע"מ).', 'קביעת דמי שכירות ראויים ← במחלוקת ← מינוי שמאי מטעם בית המשפט ← סעיף 5א לחוק המכר (דירות).',
    '["חוק המכר (דירות), התשל\"ג-1973, סעיף 5א", "ת\"א (שלום ת\"א) 22707-07-22 ליאור ריחן נ'' גן השיקמים בע\"מ (16.01.2025)", "ת\"א (שלום חי'') 40152-12-20 חסקי אלון חיזוק ושיקום מבנים בע\"מ נ'' אסף כדורי (21.04.2025)"]'::jsonb
  );
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_3, 'א', 'בית המשפט יקבע את הסכום לפי שיקול דעתו הבלעדי, ללא צורך בראיות נוספות.', false, 'טענה זו אינה נכונה. בית המשפט יסתמך על ראיות שהוגשו לו, ולא יקבע סכום באופן שרירותי.', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_3, 'ב', 'בית המשפט ימנה שמאי מטעמו שיעריך את דמי השכירות הראויים לדירה דומה.', true, 'זוהי התשובה הנכונה. במקרים של מחלוקת על גובה דמי השכירות הראויים, בית המשפט נוהג למנות מומחה מטעמו (שמאי) כדי להכריע בסוגיה.', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_3, 'ג', 'בית המשפט יקבל את טענת הקונה, שכן חוק המכר (דירות) נועד להגן על הקונה.', false, 'טענה זו אינה נכונה. למרות שהחוק מגן על הקונה, עליו להוכיח את גובה דמי השכירות הראויים, ובית המשפט לא יקבל אוטומטית את טענתו ללא בחינה.', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_3, 'ד', 'בית המשפט יקבל את טענת הקבלן, שכן נטל ההוכחה מוטל על הקונה.', false, 'טענה זו אינה נכונה. למרות שנטל ההוכחה על הקונה, בית המשפט לא יקבל אוטומטית את טענת הקבלן, אלא יבחן את הראיות ויכריע בהתאם.', 4);

  RAISE NOTICE 'Q% inserted: external_id %', 2, '2022-S-S-Q02';
END
$$;

