-- Q03 — 2022-S-S-Q03 — chapter=torts subtopic=negligence
-- classifier_note: The three auxiliary tests for legal causation in negligence — core תורת הסיבתיות
-- ============================================================
DO $$
DECLARE
  v_sq_id uuid := '3a4caa82-eb80-4230-8a2f-bcccb49600c2'::uuid;
  v_group_id uuid := '0537c790-6553-48a0-9991-c314098b4cdc'::uuid;
  v_chapter_id uuid;
  v_subtopic_id uuid;
  v_existing_id uuid;
  v_ang_0 uuid := '8ba30a04-f458-4931-9335-14b78a483bd9'::uuid;
  v_ang_1 uuid := 'a2d54cd8-1615-43e9-9b4e-edfca071d10d'::uuid;
  v_ang_2 uuid := '451727c7-8d8f-469a-bf96-e7edf28436f9'::uuid;
  v_ang_3 uuid := '84cf2d00-570f-490b-9c79-9516987c5e67'::uuid;
BEGIN
  SELECT id INTO v_existing_id FROM public.source_questions WHERE external_id = '2022-S-S-Q03';
  IF v_existing_id IS NOT NULL THEN
    RAISE NOTICE 'Q% skipped: external_id % already exists', 3, '2022-S-S-Q03';
    RETURN;
  END IF;

  SELECT id INTO v_chapter_id FROM public.chapters WHERE code = 'torts';
  IF v_chapter_id IS NULL THEN
    RAISE EXCEPTION 'Chapter code % not found', 'torts';
  END IF;

  SELECT id INTO v_subtopic_id FROM public.subtopics WHERE code = 'negligence' AND chapter_id = v_chapter_id;
  IF v_subtopic_id IS NULL THEN
    RAISE EXCEPTION 'Subtopic code % not found under chapter %', 'negligence', 'torts';
  END IF;

  INSERT INTO public.source_questions (
    id, question_group_id, version, is_current, external_id, chapter_id, subtopic_id, question_text, source_metadata, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list, notes_for_admin, status, created_by
  ) VALUES (
    v_sq_id, v_group_id, 1, true,
    '2022-S-S-Q03', v_chapter_id, v_subtopic_id, 'שלושת מבחני העזר לקביעת קיומו של קשר סיבתי משפטי בתביעת רשלנות בנזיקין הם:',
    '{"exam_year": 2022, "exam_season": "summer", "exam_part": 2, "exam_question_number": 3}'::jsonb, 'שאלה זו עוסקת בקשר הסיבתי המשפטי בתביעות רשלנות בנזיקין, שהוא אחד מיסודות עוולת הרשלנות. היא בוחנת את שלושת מבחני העזר המרכזיים שפותחו בפסיקה הישראלית לצורך קביעת קשר זה: מבחן הצפיות, מבחן הסיכון ומבחן השכל הישר, כפי שנקבעו בסעיף 64 לפקודת הנזיקין ובפסיקת בתי המשפט.', 'קשר סיבתי משפטי הוא השלב השני בבחינת הקשר הסיבתי, לאחר שנקבע קשר סיבתי עובדתי. הוא נועד לצמצם את מעגל האחריות של המזיק לנזקים שניתן לייחס לו מבחינה משפטית. הפסיקה הישראלית, בהתבסס על סעיף 64 לפקודת הנזיקין, אימצה שלושה מבחני עזר חלופיים לקביעת קשר סיבתי משפטי: 1. מבחן הצפיות: האם אדם סביר יכול היה לצפות את סוג הנזק שנגרם. 2. מבחן הסיכון: האם הנזק שנגרם הוא מסוג הסיכונים שההתנהגות הרשלנית יצרה. 3. מבחן השכל הישר: האם מבחינה הגיונית ומוסרית, יש לייחס את הנזק למעשה הרשלנות. די בכך שאחד ממבחנים אלו מתקיים כדי שייקבע קשר סיבתי משפטי. ראו לעניין זה ע"א 576/81 אילן בן שמעון נ'' אלי ברדה.', 'הבלבול בין קשר סיבתי עובדתי לקשר סיבתי משפטי, או אי ידיעת שלושת מבחני העזר הספציפיים לקשר סיבתי משפטי וההבחנה ביניהם.',
    '["קשר סיבתי משפטי", "רשלנות", "מבחן הצפיות", "מבחן הסיכון", "מבחן השכל הישר", "פקודת הנזיקין", "אחריות בנזיקין"]'::jsonb, '**וריאציה 1 — שלושת המבחנים:** מהם שלושת מבחני הקשר הסיבתי המשפטי? ← צפיות, סיכון, שכל ישר (סעיף 64 לפקודת הנזיקין).
**וריאציה 2 — הבחנה מעובדתי:** מה ההבדל בין קשר סיבתי עובדתי למשפטי? ← עובדתי: ''סיבה-בלעדיה-אין''; משפטי: צמצום האחריות לנזקים צפויים/קרובים (ע"א 576/81 אילן בן שמעון נ'' אלי ברדה).
**וריאציה 3 — תפקיד:** מה תפקידו של הקשר הסיבתי המשפטי? ← לקבוע את גבולות האחריות של המזיק לנזקים שנגרמו בפועל.', 'קשר סיבתי משפטי ← צפיות, סיכון, שכל ישר ← צמצום אחריות המזיק ← פקודת הנזיקין.', '["פקודת הנזיקין [נוסח חדש], סעיף 64", "ע\"א 576/81 אילן בן שמעון נ'' אלי ברדה, פ\"ד לח(1) 1 (1984)"]'::jsonb,
    'classification_review: original chapter=''סדר דין אזרחי'' subtopic=''הליכים'' → mapped chapter=''torts'' subtopic=''negligence'' | classifier_note: The three auxiliary tests for legal causation in negligence — core תורת הסיבתיות | source_review_note: שאלה זו עוסקת בדיני נזיקין (מהותי) ואינה משתייכת לתחום הדין הדיוני. סווגה תחת ''סדר דין אזרחי - הליכים'' כהצבת מקום בלבד.', 'active', 'b9ecdde2-d07e-4761-96ab-05f0ad32d4e3'
  );

  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'א', 'מבחן הסיכון, מבחן הסיבתיות ומבחן השכל הישר.', false, 'מבחן הסיבתיות אינו אחד משלושת מבחני העזר המקובלים לקשר סיבתי משפטי, אלא הוא מושג כללי יותר.', 1);
  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'ב', 'מבחן הסיבה-בלעדיה-אין, מבחן האדם הסביר, מבחן הצפיות.', false, 'מבחן הסיבה-בלעדיה-אין הוא מבחן לקשר סיבתי עובדתי, ולא משפטי. מבחן האדם הסביר הוא מבחן לקביעת חובת זהירות והפרתה, ולא לקשר סיבתי משפטי.', 2);
  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'ג', 'מבחן הצפיות, מבחן הסיכון, מבחן השכל הישר.', true, 'זוהי התשובה הנכונה. אלו הם שלושת מבחני העזר המקובלים בפסיקה הישראלית לקביעת קשר סיבתי משפטי בתביעות רשלנות בנזיקין, כפי שנקבעו בסעיף 64 לפקודת הנזיקין ובפסיקה.', 3);
  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'ד', 'מבחן האדם הסביר, מבחן הסיבה-בלעדיה-אין, מבחן הסיבתיות הנורמטיבית.', false, 'מבחן האדם הסביר ומבחן הסיבה-בלעדיה-אין אינם מבחנים לקשר סיבתי משפטי. ''סיבתיות נורמטיבית'' הוא מושג כללי, אך לא אחד משלושת מבחני העזר הספציפיים.', 4);

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_0, v_sq_id, 'א', 'קשר סיבתי עובדתי',
    1, 'ראובן נפגע בתאונת דרכים שנגרמה עקב נהיגה רשלנית של שמעון. ראובן טוען כי לולא נהיגתו הרשלנית של שמעון, הנזק לא היה נגרם לו. איזה מבחן משפטי בוחן טענה זו?', 'שאלה זו עוסקת בקשר הסיבתי העובדתי, שהוא השלב הראשון וההכרחי בקביעת אחריות בנזיקין. היא מדגישה את ההבחנה בין קשר סיבתי עובדתי לקשר סיבתי משפטי.', 'קשר סיבתי עובדתי הוא תנאי הכרחי לקיומה של אחריות בנזיקין. הוא נבחן באמצעות ''מבחן הסיבה-בלעדיה-אין'' (או ''מבחן האלמלא''), הקבוע בסעיף 36 לפקודת הנזיקין. מבחן זה שואל האם הנזק היה נגרם אלמלא מעשה הרשלנות של הנתבע. אם התשובה היא שלילית (כלומר, הנזק לא היה נגרם אלמלא המעשה), אזי קיים קשר סיבתי עובדתי. רק לאחר שנקבע קשר סיבתי עובדתי, עוברים לבחון את הקשר הסיבתי המשפטי.',
    'בלבול בין קשר סיבתי עובדתי לקשר סיבתי משפטי, או אי הבנה של תפקידו של כל אחד מהם בתביעת נזיקין.', '["קשר סיבתי עובדתי", "סיבה-בלעדיה-אין", "מבחן האלמלא", "רשלנות", "נזק", "פקודת הנזיקין"]'::jsonb, '**וריאציה 1 — הגדרה:** מהו קשר סיבתי עובדתי? ← האם הנזק היה נגרם אלמלא מעשה הנתבע (סעיף 36 לפקודת הנזיקין).
**וריאציה 2 — תפקיד:** מה תפקידו של קשר סיבתי עובדתי? ← תנאי הכרחי לאחריות בנזיקין, שלב ראשון לפני קשר סיבתי משפטי.
**וריאציה 3 — ריבוי גורמים:** מה קורה כשיש מספר גורמים? ← המבחן מתקשה, לעיתים משתמשים במבחן ''הגורם היעיל'' או ''הסיכון'' (ע"א 248/86 עזבון חננשוילי נ'' רותם חברה לביטוח בע"מ).', 'קשר סיבתי עובדתי ← מבחן הסיבה-בלעדיה-אין ← תנאי הכרחי לאחריות בנזיקין.',
    '["פקודת הנזיקין [נוסח חדש], סעיף 36", "ע\"א 248/86 עזבון חננשוילי נ'' רותם חברה לביטוח בע\"מ, פ\"ד מה(2) 529 (1991)"]'::jsonb
  );
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_0, 'א', 'מבחן הצפיות.', false, 'מבחן הצפיות הוא אחד ממבחני הקשר הסיבתי המשפטי, ולא העובדתי.', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_0, 'ב', 'מבחן הסיבה-בלעדיה-אין.', true, 'זוהי התשובה הנכונה. מבחן הסיבה-בלעדיה-אין (או ''מבחן האלמלא'') הוא המבחן לקביעת קשר סיבתי עובדתי, הבוחן האם הנזק היה נגרם אלמלא מעשה הרשלנות.', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_0, 'ג', 'מבחן הסיכון.', false, 'מבחן הסיכון הוא אחד ממבחני הקשר הסיבתי המשפטי, ולא העובדתי.', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_0, 'ד', 'מבחן השכל הישר.', false, 'מבחן השכל הישר הוא אחד ממבחני הקשר הסיבתי המשפטי, ולא העובדתי.', 4);

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_1, v_sq_id, 'ב', 'מבחן הצפיות',
    2, 'מהו מבחן הצפיות בקביעת קשר סיבתי משפטי בתביעת רשלנות?', 'שאלה זו מתמקדת במבחן הצפיות, שהוא אחד ממבחני הקשר הסיבתי המשפטי המרכזיים בדיני נזיקין. היא מדגישה את אופיו האובייקטיבי של המבחן ואת ההבחנה בין צפיית סוג הנזק לאופן התרחשותו.', 'מבחן הצפיות הוא מבחן אובייקטיבי הבוחן האם אדם סביר בנעלי המזיק יכול היה לצפות, במועד ביצוע מעשה הרשלנות, את התרחשותו של נזק מסוג הנזק שנגרם. אין דרישה לצפות את אופן התרחשותו המדויק של הנזק או את היקפו המלא. מבחן זה משמש ככלי לצמצום מעגל האחריות של המזיק, כך שלא יחוב על נזקים רחוקים ובלתי צפויים. הוא קבוע בסעיף 64 לפקודת הנזיקין ונדון בהרחבה בפסיקה, למשל בע"א 145/80 ועקנין נ'' בית החולים ''הדסה''.',
    'הנחה שגויה כי מבחן הצפיות דורש צפייה של כל פרטי הנזק או אופן התרחשותו, ולא רק את סוג הנזק.', '["מבחן הצפיות", "קשר סיבתי משפטי", "רשלנות", "אדם סביר", "סוג הנזק", "פקודת הנזיקין"]'::jsonb, '**וריאציה 1 — מהות המבחן:** מה בוחן מבחן הצפיות? ← האם אדם סביר יכול היה לצפות את סוג הנזק (סעיף 64 לפקודת הנזיקין).

**וריאציה 2 — היקף הצפייה:** האם נדרשת צפייה של אופן התרחשות הנזק? ← לא, רק סוג הנזק (ע"א 145/80 ועקנין נ'' בית החולים ''הדסה'').
**וריאציה 3 — תפקיד:** מה תפקידו של מבחן הצפיות? ← לצמצם את מעגל האחריות של המזיק לנזקים צפויים סבירים.', 'מבחן הצפיות ← צפיית סוג הנזק ע"י אדם סביר ← לא אופן התרחשותו ← קשר סיבתי משפטי.',
    '["פקודת הנזיקין [נוסח חדש], סעיף 64", "ע\"א 145/80 ועקנין נ'' בית החולים ''הדסה'', פ\"ד לה(2) 113 (1981)"]'::jsonb
  );
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_1, 'א', 'האם הנתבע צפה בפועל את הנזק שנגרם.', false, 'מבחן הצפיות אינו דורש צפייה בפועל, אלא צפייה סבירה של אדם מן היישוב.', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_1, 'ב', 'האם אדם סביר יכול היה לצפות את סוג הנזק שנגרם, גם אם לא את אופן התרחשותו המדויק.', true, 'זוהי התשובה הנכונה. מבחן הצפיות בוחן האם אדם סביר היה יכול לצפות את התרחשותו של נזק מסוג הנזק שנגרם, ולאו דווקא את פרטי התרחשותו או היקפו המדויק.', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_1, 'ג', 'האם הנזק היה בלתי נמנע, ללא קשר למעשה הנתבע.', false, 'טענה זו אינה רלוונטית למבחן הצפיות, אלא עשויה להיות רלוונטית לשאלת הקשר הסיבתי העובדתי או לטענת הגנה של הנתבע.', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_1, 'ד', 'האם הנתבע התכוון לגרום לנזק שנגרם.', false, 'כוונת הנתבע רלוונטית לעוולות מכוונות, אך לא לעוולת הרשלנות, שבה נבחנת סבירות ההתנהגות ולא הכוונה.', 4);

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_2, v_sq_id, 'ג', 'התערבות גורם זר מתערב',
    3, 'ראובן נפגע ברשלנות על ידי שמעון. בדרכו לבית החולים, האמבולנס שבו נסע התנגש ברכב אחר עקב נהיגה רשלנית של נהג האמבולנס, וראובן נפגע פגיעה נוספת. האם שמעון אחראי גם לפגיעה הנוספת?', 'שאלה זו עוסקת בהשפעת גורם זר מתערב על הקשר הסיבתי המשפטי. היא בוחנת מתי התערבות של גורם נוסף לאחר מעשה הרשלנות המקורי מנתקת את שרשרת הסיבתיות ומפחיתה או מבטלת את אחריותו של המזיק המקורי.', 'התערבותו של גורם זר מתערב עשויה לנתק את הקשר הסיבתי המשפטי בין מעשה המזיק המקורי לנזק הסופי. הפסיקה קבעה כי גורם זר ינתק את הקשר הסיבתי אם הוא בלתי צפוי באופן סביר, בלתי רגיל, ואינו בגדר הסיכונים שהמזיק המקורי יצר. נהיגה רשלנית של נהג אמבולנס, שגרמה לתאונה נוספת, נחשבת בדרך כלל לגורם מתערב בלתי צפוי וחריג, המנתק את הקשר הסיבתי בין התאונה הראשונה לפגיעה הנוספת. לכן, שמעון לא יהיה אחראי לפגיעה הנוספת. ראו לעניין זה סעיף 64 לפקודת הנזיקין והפסיקה הרלוונטית, כגון ע"א 23/61 סימון נ'' מנשה.',
    'הנחה שגויה כי כל אירוע עוקב מנתק את הקשר הסיבתי, או לחלופין, ששום אירוע עוקב אינו מנתק אותו. יש לבחון את מידת הצפיות והחריגות של הגורם המתערב.', '["גורם זר מתערב", "קשר סיבתי משפטי", "ניתוק קשר סיבתי", "צפיות", "רשלנות", "שרשרת סיבתית"]'::jsonb, '**וריאציה 1 — תנאי הניתוק:** מתי גורם זר מתערב מנתק קשר סיבתי? ← כשהוא בלתי צפוי, בלתי רגיל ואינו בגדר הסיכון (סעיף 64 לפקודת הנזיקין).
**וריאציה 2 — דוגמה:** האם רשלנות רפואית מנתקת קשר סיבתי? ← תלוי בנסיבות, אך לרוב לא תנתק אם היא בגדר הסיכון הצפוי (ע"א 23/61 סימון נ'' מנשה).
**וריאציה 3 — אחריות משותפת:** מה קורה אם הגורם המתערב לא ניתק את הקשר? ← המזיקים יהיו אחראים במשותף (סעיפים 11 ו-64 לפקודת הנזיקין).', 'גורם זר מתערב ← מנתק קשר סיבתי ← אם בלתי צפוי וחריג ← פוטר מאחריות לנזק הנוסף.',
    '["פקודת הנזיקין [נוסח חדש], סעיף 64", "ע\"א 23/61 סימון נ'' מנשה, פ\"ד טז 105 (1962)"]'::jsonb
  );
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_2, 'א', 'כן, שמעון אחראי לכל הנזקים שנגרמו לראובן כתוצאה ישירה או עקיפה ממעשיו הראשוניים.', false, 'טענה זו רחבה מדי. אחריות בנזיקין אינה בלתי מוגבלת, וגורם זר מתערב עשוי לנתק את הקשר הסיבתי.', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_2, 'ב', 'לא, נהיגתו הרשלנית של נהג האמבולנס מהווה גורם זר מתערב המנתק את הקשר הסיבתי בין מעשי שמעון לפגיעה הנוספת.', true, 'זוהי התשובה הנכונה. כאשר גורם זר מתערב באופן בלתי צפוי וחריג, הוא עשוי לנתק את הקשר הסיבתי המשפטי בין מעשה המזיק המקורי לנזק הסופי, ובכך לפטור את המזיק המקורי מאחריות לנזק הנוסף.', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_2, 'ג', 'כן, אם הפגיעה הנוספת הייתה צפויה באופן סביר כתוצאה מהתאונה הראשונה.', false, 'אף שהצפיות היא מבחן מרכזי, נהיגה רשלנית של נהג אמבולנס נחשבת בדרך כלל לגורם מתערב בלתי צפוי המנתק את הקשר הסיבתי, אלא אם כן הוכח אחרת.', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_2, 'ד', 'לא, אלא אם נהג האמבולנס פעל בכוונה לגרום נזק לראובן.', false, 'כוונת נהג האמבולנס אינה התנאי היחיד לניתוק הקשר הסיבתי. גם רשלנות חמורה ובלתי צפויה יכולה לנתק אותו.', 4);

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_3, v_sq_id, 'ד', 'קשר סיבתי בנזק ראייתי',
    4, 'במקרה שבו נגרם נזק ראייתי לתובע, המונע ממנו להוכיח קשר סיבתי בין מעשה הנתבע לנזקיו, מהי הגישה המשפטית המקובלת בישראל לגבי נטל ההוכחה של הקשר הסיבתי?', 'שאלה זו עוסקת בדוקטרינת הנזק הראייתי, שהתפתחה בפסיקה הישראלית כדי להתמודד עם קשיים בהוכחת קשר סיבתי כאשר הנתבע עצמו גרם לאובדן או להסתרת ראיות. היא בוחנת את ההשלכות של דוקטרינה זו על נטל ורף ההוכחה.', 'דוקטרינת הנזק הראייתי מאפשרת לבית המשפט להתמודד עם מצבים שבהם מעשה או מחדל של הנתבע גרמו לכך שהתובע אינו יכול להוכיח את הקשר הסיבתי בין מעשה הנתבע לנזקיו. במקרים אלו, הפסיקה הכירה בשתי חלופות עיקריות: האחת, העברת נטל השכנוע לגבי הקשר הסיבתי לנתבע (ע"א 291/98 דגני נ'' פרידמן), והשנייה, הפחתת רף ההוכחה הנדרש מהתובע (ע"א 9328/02 מאיר נ'' ד"ר לאור). מטרת הדוקטרינה היא למנוע מצב שבו מזיק יצא פטור בלא כלום רק משום שמעשיו מנעו מהניזוק להוכיח את תביעתו.',
    'אי ידיעת דוקטרינת הנזק הראייתי והשלכותיה על נטל ורף ההוכחה, או בלבול בינה לבין כללי ראיות רגילים.', '["נזק ראייתי", "קשר סיבתי", "נטל ההוכחה", "רף ההוכחה", "רשלנות", "עקרון הצדק"]'::jsonb, '**וריאציה 1 — מהות הנזק הראייתי:** מהו נזק ראייתי? ← מצב שבו הנתבע גרם לקושי בהוכחת הקשר הסיבתי (ע"א 291/98 דגני נ'' פרידמן).
**וריאציה 2 — השלכות על נטל ההוכחה:** מה קורה לנטל ההוכחה? ← עובר לנתבע, או שרף ההוכחה מופחת (ע"א 9328/02 מאיר נ'' ד"ר לאור).

**וריאציה 3 — תכלית הדוקטרינה:** מהי מטרת דוקטרינת הנזק הראייתי? ← למנוע מצב שבו מזיק יצא פטור בלא כלום עקב מעשיו שלו.', 'נזק ראייתי ← קושי בהוכחת קשר סיבתי ← העברת נטל/הפחתת רף הוכחה ← צדק.',
    '["ע\"א 291/98 דגני נ'' פרידמן, פ\"ד נה(2) 496 (2001)", "ע\"א 9328/02 מאיר נ'' ד\"ר לאור, פ\"ד נח(5) 54 (2004)"]'::jsonb
  );
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_3, 'א', 'נטל ההוכחה נשאר על התובע, אך בית המשפט יקל עליו בדרישות הראייתיות.', false, 'אף שיש הקלה בדרישות, הגישה המקובלת היא להעביר את נטל השכנוע או להפחית את רף ההוכחה, ולא רק להקל בדרישות הראייתיות.', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_3, 'ב', 'נטל השכנוע לגבי הקשר הסיבתי עובר לנתבע, או שרף ההוכחה המוטל על התובע מופחת.', true, 'זוהי התשובה הנכונה. במקרים של נזק ראייתי שנגרם על ידי הנתבע, הפסיקה הכירה באפשרות להעביר את נטל השכנוע לנתבע או להפחית את רף ההוכחה הנדרש מהתובע.', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_3, 'ג', 'התביעה תידחה אוטומטית, שכן התובע לא עמד בנטל ההוכחה הבסיסי.', false, 'טענה זו אינה נכונה. דוקטרינת הנזק הראייתי נועדה למנוע מצב זה ולאפשר לתובע להיפרע גם במקרים של קושי ראייתי שנגרם על ידי הנתבע.', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_3, 'ד', 'בית המשפט ימנה מומחה מטעמו שיקבע את הקשר הסיבתי, ללא קשר לראיות הצדדים.', false, 'מינוי מומחה יכול לסייע, אך הוא אינו פותר את שאלת נטל ההוכחה או רף ההוכחה במקרים של נזק ראייתי מהותי.', 4);

  RAISE NOTICE 'Q% inserted: external_id %', 3, '2022-S-S-Q03';
END
$$;

-- ============================================================
-- Q04 — 2022-S-S-Q04 — chapter=contracts subtopic=general_part
-- classifier_note: Letter outlining sale, two-week deadline to decide — offer + acceptance rules
-- ============================================================
DO $$
DECLARE
  v_sq_id uuid := '2f4d764f-ddf7-40be-98bd-5504d9616503'::uuid;
  v_group_id uuid := '6b1befcd-5cd5-403c-be31-4b3a21053073'::uuid;
  v_chapter_id uuid;
  v_subtopic_id uuid;
  v_existing_id uuid;
  v_ang_0 uuid := '1ecef301-26dc-4393-8323-52ae1f19e0be'::uuid;
  v_ang_1 uuid := '8e05f00b-8907-470a-9b4d-1abd17fd9f84'::uuid;
  v_ang_2 uuid := '7c24673f-3e54-437c-b0c9-7680027655a5'::uuid;
  v_ang_3 uuid := 'e057b7a4-a94b-475d-b4c0-26ec69e06fce'::uuid;
BEGIN
  SELECT id INTO v_existing_id FROM public.source_questions WHERE external_id = '2022-S-S-Q04';
  IF v_existing_id IS NOT NULL THEN
    RAISE NOTICE 'Q% skipped: external_id % already exists', 4, '2022-S-S-Q04';
    RETURN;
  END IF;

  SELECT id INTO v_chapter_id FROM public.chapters WHERE code = 'contracts';
  IF v_chapter_id IS NULL THEN
    RAISE EXCEPTION 'Chapter code % not found', 'contracts';
  END IF;

  SELECT id INTO v_subtopic_id FROM public.subtopics WHERE code = 'general_part' AND chapter_id = v_chapter_id;
  IF v_subtopic_id IS NULL THEN
    RAISE EXCEPTION 'Subtopic code % not found under chapter %', 'general_part', 'contracts';
  END IF;

  INSERT INTO public.source_questions (
    id, question_group_id, version, is_current, external_id, chapter_id, subtopic_id, question_text, source_metadata, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list, notes_for_admin, status, created_by
  ) VALUES (
    v_sq_id, v_group_id, 1, true,
    '2022-S-S-Q04', v_chapter_id, v_subtopic_id, 'ראובן סיפר לשמעון חברו שהוא מעוניין למכור את דירתו, ושמעון הביע התעניינות בדירה. ראובן שלח לשמעון מכתב ובו מתווה מפורט של עסקת מכירה אפשרית. במכתבו כתב ראובן כי הוא נותן לשמעון שבועיים להחליט אם הוא מעוניין ברצינות בדירה, ולאחריהם יראה עצמו חופשי לפרסם את הדירה למכירה ולנהל משא ומתן עם קונים פוטנציאלים. את מכתבו חתם ראובן במילים: "אבהיר כי מבחינת תנאי מכירת הדירה הכול בינינו פתוח, למעט העובדה שאני מתחייב לתת לך בכל מקרה שבועיים להחליט אם אתה רוצה לקנות או לא ובאילו תנאים". שמעון קיבל את המכתב. לאחר שבוע פנה ישראל לראובן והציע לו מחיר גבוה בהרבה מהמחיר שבו נקב ראובן במכתבו לשמעון. מה הדין?',
    '{"exam_year": 2022, "exam_season": "summer", "exam_part": 2, "exam_question_number": 4}'::jsonb, 'שאלה זו עוסקת בהבחנה בין הצעה רגילה להצעה בלתי חוזרת, ובפרט במקרה שבו המציע קובע מועד לקיבול ההצעה. היא בוחנת את היקף הכבילות של המציע במצב כזה, ואת ההשלכות של ניסוח ההצעה על גמירת הדעת והמסוימות של תנאי החוזה העתידי.', 'סעיף 3(ב) לחוק החוזים (חלק כללי), התשל"ג-1973, קובע כי אם המציע קבע מועד לקיבול הצעתו, אין הוא רשאי לחזור בו ממנה לאחר שנמסרה לניצע. במקרה זה, ראובן קבע מועד של שבועיים לשמעון להחליט, ולכן מדובר בהצעה בלתי חוזרת. משמעות הדבר היא שראובן כבול להצעתו למשך שבועיים ואינו יכול למכור את הדירה לאחר (ישראל) בתקופה זו. עם זאת, ראובן גם ציין במפורש כי ''הכול בינינו פתוח, למעט העובדה שאני מתחייב לתת לך בכל מקרה שבועיים להחליט אם אתה רוצה לקנות או לא ובאילו תנאים''. ניסוח זה מלמד כי המתווה המפורט ששלח אינו מהווה הצעה סופית ומחייבת מבחינת תנאי המכירה (כגון מחיר), אלא בסיס למשא ומתן. לכן, ראובן חייב להמתין לתשובת שמעון עד תום השבועיים, אך אינו מחויב למכור לו בתנאים שנקב במתווה, אלא לנהל עמו משא ומתן בתום לב. ראו לעניין זה ע"א 258/93 סופר פארם נ'' חבס.', 'הבלבול בין הצעה בלתי חוזרת לבין חוזה אופציה, וכן אי הבחנה בין התחייבות לקיים משא ומתן לבין התחייבות למכור בתנאים ספציפיים.',
    '["הצעה בלתי חוזרת", "חוק החוזים", "מועד לקיבול", "גמירת דעת", "מסוימות", "משא ומתן", "חזרה מהצעה"]'::jsonb, '**וריאציה 1 — הצעה בלתי חוזרת:** האם ההצעה של ראובן היא בלתי חוזרת? ← כן, כי קבע מועד לקיבול (שבועיים) (סעיף 3(ב) לחוק החוזים).
**וריאציה 2 — היקף הכבילות:** האם ראובן כבול לתנאי המתווה? ← לא, כי ציין ''הכול בינינו פתוח'' למעט תקופת ההתחייבות (ע"א 258/93 סופר פארם נ'' חבס).
**וריאציה 3 — חזרה מהצעה:** האם ראובן יכול למכור לישראל לפני תום השבועיים? ← לא, כי אינו רשאי לחזור בו מהצעה בלתי חוזרת (סעיף 3(ב) לחוק החוזים).', 'הצעה עם מועד לקיבול ← הצעה בלתי חוזרת ← המציע כבול לא לחזור בו ← אך לא בהכרח לתנאים סופיים אם צוין אחרת ← סעיף 3(ב) לחוק החוזים.', '["חוק החוזים (חלק כללי), התשל\"ג-1973, סעיף 3", "ע\"א (מחוזי תל אביב-יפו) 258/93 סופר פארם (ישראל) בע\"מ נ'' ברוך חבס (10.04.1994)", "דניאל פרידמן ונילי כהן, חוזים כרך א (2018) | חזרה מהצעה", "גבריאלה שלו ואפי צמח, דיני חוזים (2019) | פרק 7 ההצעה"]'::jsonb,
    'classification_review: original chapter=''סדר דין אזרחי'' subtopic=''הליכים'' → mapped chapter=''contracts'' subtopic=''general_part'' | classifier_note: Letter outlining sale, two-week deadline to decide — offer + acceptance rules | source_review_note: שאלה זו עוסקת בדיני חוזים (מהותי) ואינה משתייכת לתחום הדין הדיוני. סווגה תחת ''סדר דין אזרחי - הליכים'' כהצבת מקום בלבד.', 'active', 'b9ecdde2-d07e-4761-96ab-05f0ad32d4e3'
  );

  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'א', 'ראובן יכול למכור מייד את הדירה לישראל, שכן שמעון לא השיב למכתב ולא נכרת חוזה.', false, 'טענה זו אינה נכונה. ראובן קבע מועד לקיבול ההצעה, ולכן מדובר בהצעה בלתי חוזרת ממנה אינו רשאי לחזור עד תום המועד.', 1);
  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'ב', 'ראובן חייב להמתין לתשובת שמעון עד תום השבועיים, אך אינו חייב למכור לו בתנאים שהציע במתווה ששלח לו.', true, 'זוהי התשובה הנכונה. ראובן קבע מועד לקיבול ההצעה (שבועיים), ולכן זוהי הצעה בלתי חוזרת ממנה אינו רשאי לחזור. עם זאת, המתווה המפורט אינו מהווה הצעה סופית ומחייבת, שכן ראובן הבהיר כי ''הכול בינינו פתוח'' למעט תקופת ההתחייבות.', 2);
  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'ג', 'ראובן חייב להמתין עד תום השבועיים לתשובת שמעון, ואם שמעון יענה שהוא מעוניין, יהיה חייב למכור לו בתנאים שהציע במתווה ששלח לו.', false, 'טענה זו אינה נכונה. אף שראובן חייב להמתין, הוא אינו מחויב למכור בתנאים שהוצגו במתווה, שכן הוא הבהיר כי ''הכול בינינו פתוח'' למעט תקופת ההתחייבות.', 3);
  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'ד', 'ראובן רשאי לדרוש משמעון תשובה מיידית, ואם לא ישיב מייד יהיה רשאי ראובן למכור את הדירה לישראל.', false, 'טענה זו אינה נכונה. ראובן קבע מועד של שבועיים, ואינו רשאי לדרוש תשובה מיידית או לחזור בו מהצעתו הבלתי חוזרת לפני תום המועד.', 4);

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_0, v_sq_id, 'א', 'חזרה מהצעה רגילה',
    1, 'ראובן הציע לשמעון למכור לו את רכבו במחיר מסוים. שמעון אמר שיחשוב על כך. למחרת, לפני ששמעון השיב, ראובן התחרט והודיע לשמעון כי הוא חוזר בו מהצעתו. מה הדין?', 'שאלה זו בוחנת את הכלל הבסיסי בחוק החוזים לגבי חזרה מהצעה רגילה. היא מדגישה את עקרון ''אדנות המציע'' על הצעתו ואת המועד האחרון שבו הוא רשאי לחזור בו.', 'סעיף 3(א) לחוק החוזים (חלק כללי), התשל"ג-1973, קובע כי המציע רשאי לחזור בו מן ההצעה בהודעה לניצע, ובלבד שהודעת החזרה נמסרה לניצע לפני שנתן הודעת קיבול. במקרה זה, ראובן חזר בו מהצעתו לפני ששמעון נתן הודעת קיבול, ולכן החזרה תקפה. הצעה רגילה אינה כובלת את המציע עד למועד הקיבול, אלא רק עד למתן הודעת הקיבול על ידי הניצע.',
    'הבלבול בין הצעה רגילה להצעה בלתי חוזרת, והנחה שגויה כי כל הצעה כובלת את המציע עד תום המועד שניתן לניצע לחשוב עליה.', '["הצעה רגילה", "חזרה מהצעה", "הודעת קיבול", "חוק החוזים", "אדנות המציע"]'::jsonb, '**וריאציה 1 — מועד החזרה:** עד מתי ניתן לחזור מהצעה רגילה? ← עד שהודעת הקיבול נמסרה לניצע (סעיף 3(א) לחוק החוזים).
**וריאציה 2 — אדנות המציע:** מהו העיקרון המנחה בחזרה מהצעה רגילה? ← המציע הוא ''אדון הצעתו'' ויכול לחזור בו (ע"א 258/93 סופר פארם נ'' חבס).
**וריאציה 3 — הודעת חזרה:** כיצד צריכה להימסר הודעת החזרה? ← בהודעה לניצע (סעיף 3(א) לחוק החוזים).', 'הצעה רגילה ← ניתנת לחזרה ← עד למתן הודעת קיבול ← סעיף 3(א) לחוק החוזים.',
    '["חוק החוזים (חלק כללי), התשל\"ג-1973, סעיף 3(א)", "ע\"א (מחוזי תל אביב-יפו) 258/93 סופר פארם (ישראל) בע\"מ נ'' ברוך חבס (10.04.1994)", "גבריאלה שלו ואפי צמח, דיני חוזים (2019) | פרק 7 ההצעה"]'::jsonb
  );
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_0, 'א', 'ראובן אינו רשאי לחזור בו מהצעתו, שכן היא כבר נמסרה לשמעון.', false, 'טענה זו אינה נכונה. הצעה רגילה ניתנת לחזרה כל עוד לא ניתנה הודעת קיבול.', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_0, 'ב', 'ראובן רשאי לחזור בו מהצעתו, שכן הודעת החזרה נמסרה לשמעון לפני שנתן הודעת קיבול.', true, 'זוהי התשובה הנכונה. סעיף 3(א) לחוק החוזים קובע כי המציע רשאי לחזור בו מהצעה רגילה, ובלבד שהודעת החזרה נמסרה לניצע לפני שנתן הודעת קיבול.', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_0, 'ג', 'ראובן רשאי לחזור בו מהצעתו רק אם שמעון הסכים לכך.', false, 'טענה זו אינה נכונה. הסכמת הניצע אינה תנאי לחזרה מהצעה רגילה, כל עוד לא ניתנה הודעת קיבול.', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_0, 'ד', 'ראובן אינו רשאי לחזור בו מהצעתו, שכן היא הייתה הצעה מסוימת ועם גמירת דעת.', false, 'טענה זו אינה נכונה. גם הצעה מסוימת ועם גמירת דעת ניתנת לחזרה אם היא הצעה רגילה.', 4);

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_1, v_sq_id, 'ב', 'הבחנה בין הצעה בלתי חוזרת לאופציה',
    2, 'מהו ההבדל המהותי בין ''הצעה בלתי חוזרת'' לבין ''חוזה אופציה''?', 'שאלה זו עוסקת בהבחנה קריטית בין שני מנגנונים חוזיים דומים אך שונים במהותם: הצעה בלתי חוזרת וחוזה אופציה. ההבחנה חשובה להבנת שלבי כריתת החוזה וההתחייבויות הנובעות מכל אחד מהם.', 'הצעה בלתי חוזרת היא שלב טרום חוזי, הצעה רגילה שהמציע כבל עצמו מלחזור ממנה למשך תקופה מסוימת או עד מועד מסוים (סעיף 3(ב) לחוק החוזים). לעומתה, חוזה אופציה הוא כבר חוזה מחייב, המורכב משני חוזים: חוזה עיקרי (העסקה העתידית) וחוזה משני (האופציה) המעניק למקבל האופציה זכות בחירה אם להתקשר בחוזה העיקרי או לא. נותן האופציה כבול להתחייבותו, ומקבל האופציה חופשי להחליט. ההבחנה הודגשה בפסיקה, למשל בע"א 7824/95 תשובה נ'' בר נתן ובת"א (מחוזי חיפה) 697/02 חוסייסי נ'' מרכוס.',
    'הבלבול בין הצעה בלתי חוזרת לחוזה אופציה, והנחה שגויה כי מדובר במונחים זהים או בעלי משמעות משפטית זהה.', '["הצעה בלתי חוזרת", "חוזה אופציה", "חוק החוזים", "גמירת דעת", "מסוימות", "שלב טרום חוזי"]'::jsonb, '**וריאציה 1 — הגדרה:** מהי הצעה בלתי חוזרת? ← הצעה שהמציע קבע שהיא ללא חזרה או קבע מועד לקיבולה (סעיף 3(ב) לחוק החוזים).
**וריאציה 2 — הגדרת אופציה:** מהו חוזה אופציה? ← חוזה המעניק זכות בחירה להתקשר בחוזה אחר, מורכב מחוזה עיקרי וחוזה משני (ע"א 839/21 הקר נ'' קלמטיס).
**וריאציה 3 — השלכות:** מה ההבדל המעשי? ← הצעה בלתי חוזרת היא עדיין הצעה, אופציה היא כבר חוזה מחייב (ת"א (מחוזי חיפה) 697/02 חוסייסי נ'' מרכוס).', 'הצעה בלתי חוזרת ← שלב טרום חוזי, המציע כבול. חוזה אופציה ← חוזה מחייב, מקבל האופציה בעל זכות בחירה.',
    '["חוק החוזים (חלק כללי), התשל\"ג-1973, סעיף 3(ב)", "ע\"א 7824/95 יצחק תשובה נ'' ארנון בר נתן (11.11.1998)", "ת\"א (מחוזי חיפה) 697/02 תחסין חוסייסי נ'' גרהרד מרכוס (20.03.2005)", "ע\"א 839/21 חיה הקר נ'' חברת קלמטיס אוברסיז בע\"מ (06.03.2024)", "גבריאלה שלו ואפי צמח, דיני חוזים (2019) | פרק 7 ההצעה"]'::jsonb
  );
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_1, 'א', 'הצעה בלתי חוזרת ניתנת ללא תמורה, בעוד שחוזה אופציה דורש תמורה.', false, 'טענה זו אינה נכונה. הצעה בלתי חוזרת יכולה להינתן גם ללא תמורה, וחוזה אופציה יכול להינתן גם ללא תמורה נפרדת עבור האופציה עצמה.', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_1, 'ב', 'הצעה בלתי חוזרת היא שלב טרום חוזי, בעוד שחוזה אופציה הוא כבר חוזה מחייב המורכב משני חוזים.', true, 'זוהי התשובה הנכונה. הצעה בלתי חוזרת היא עדיין הצעה, שלב במשא ומתן. חוזה אופציה הוא כבר חוזה תקף, המורכב מחוזה עיקרי וחוזה משני (האופציה) המעניק זכות בחירה.', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_1, 'ג', 'המציע אינו רשאי לחזור בו מהצעה בלתי חוזרת, אך רשאי לחזור בו מחוזה אופציה.', false, 'טענה זו אינה נכונה. בשני המקרים המציע/נותן האופציה כבול להתחייבותו ואינו רשאי לחזור בו.', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_1, 'ד', 'הצעה בלתי חוזרת פוקעת במות המציע, בעוד שחוזה אופציה אינו פוקע במות נותן האופציה.', false, 'טענה זו אינה נכונה. סעיף 4(2) לחוק החוזים קובע כי הצעה (כולל בלתי חוזרת) פוקעת במות המציע, וגם חוזה אופציה יכול לפקוע במות הצדדים, אם כי יש ביקורת על כך.', 4);

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_2, v_sq_id, 'ג', 'דחיית הצעה בלתי חוזרת',
    3, 'ראובן הציע לשמעון הצעה בלתי חוזרת למכירת רכבו למשך שבוע. לאחר יומיים, שמעון הודיע לראובן במפורש כי הוא דוחה את ההצעה. למחרת, שמעון התחרט והודיע לראובן כי הוא מקבל את ההצעה. מה הדין?', 'שאלה זו בוחנת את אחד מאירועי הפקיעה של הצעה, ובפרט את השפעת דחיית הצעה בלתי חוזרת על תוקפה. היא מדגישה כי גם הצעה בלתי חוזרת יכולה לפקוע לפני תום המועד שנקבע לקיבולה.', 'סעיף 4(1) לחוק החוזים (חלק כללי) קובע כי הצעה פוקעת כשדחה אותה הניצע או עבר המועד לקיבולה. כלומר, גם הצעה בלתי חוזרת, שהמציע כבול אליה ואינו רשאי לחזור בו ממנה, פוקעת אם הניצע דוחה אותה במפורש. דחייה זו יכולה להיות מפורשת או אקטיבית. מרגע שההצעה נדחתה, היא פקעה ולא ניתן לקבלה מחדש, אלא אם המציע יגיש הצעה חדשה. ראו לעניין זה ע"א 379/82 נוה-עם נ'' יעקובסון.',
    'הנחה שגויה כי הצעה בלתי חוזרת אינה יכולה לפקוע לפני תום המועד שנקבע לקיבולה, גם אם הניצע דחה אותה.', '["הצעה בלתי חוזרת", "פקיעת הצעה", "דחיית הצעה", "חוק החוזים", "הודעה מפורשת"]'::jsonb, '**וריאציה 1 — פקיעת הצעה:** מתי פוקעת הצעה בלתי חוזרת? ← כשדחה אותה הניצע או עבר המועד לקיבולה (סעיף 4(1) לחוק החוזים).
**וריאציה 2 — דחייה מפורשת:** האם דחייה מפורשת מפקיעה הצעה בלתי חוזרת? ← כן, דחייה מפורשת או אקטיבית מפקיעה אותה (ע"א 379/82 נוה-עם נ'' יעקובסון).
**וריאציה 3 — חזרה מדחייה:** האם ניתן לחזור מדחייה? ← לא, מרגע שנדחתה, ההצעה פקעה (ת"א (מחוזי תל אביב-יפו) 1202/02 אלימלך צחי נ'' אייל דן).', 'הצעה בלתי חוזרת ← פוקעת בדחייה מפורשת/אקטיבית ← גם לפני תום המועד ← סעיף 4(1) לחוק החוזים.',
    '["חוק החוזים (חלק כללי), התשל\"ג-1973, סעיף 4(1)", "ע\"א 379/82 נוה-עם ברמת-גן בע\"מ (פירוק מרצון) נ'' ד\"ר יוסף יעקובסון (28.03.1984)", "ת\"א (מחוזי תל אביב-יפו) 1202/02 אלימלך צחי נ'' אייל דן (29.11.2005)"]'::jsonb
  );
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_2, 'א', 'ההצעה פקעה עם דחייתה על ידי שמעון, ולכן לא נכרת חוזה.', true, 'זוהי התשובה הנכונה. סעיף 4(1) לחוק החוזים קובע כי הצעה פוקעת כשדחה אותה הניצע, גם אם מדובר בהצעה בלתי חוזרת.', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_2, 'ב', 'ההצעה עדיין בתוקף, שכן מדובר בהצעה בלתי חוזרת וטרם חלף המועד לקיבולה.', false, 'טענה זו אינה נכונה. דחיית הצעה, גם בלתי חוזרת, מפקיעה אותה באופן מיידי.', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_2, 'ג', 'ההצעה פקעה רק אם ראובן הודיע לשמעון כי הוא מקבל את הדחייה.', false, 'טענה זו אינה נכונה. דחיית הצעה על ידי הניצע מפקיעה אותה באופן חד-צדדי, ללא צורך באישור המציע.', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_2, 'ד', 'הודעת הקיבול של שמעון תקפה, שכן הוא חזר בו מהדחייה לפני תום המועד.', false, 'טענה זו אינה נכונה. מרגע שההצעה נדחתה, היא פקעה ולא ניתן לקבלה מחדש, אלא אם המציע יגיש הצעה חדשה.', 4);

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_3, v_sq_id, 'ד', 'חוסר תום לב בחזרה מהצעה בלתי חוזרת',
    4, 'ראובן הציע לשמעון הצעה בלתי חוזרת למכירת רכבו למשך שבוע. לאחר יומיים, ראובן התחרט והודיע לשמעון כי הוא חוזר בו מההצעה. שמעון, שהסתמך על ההצעה, כבר ביטל עסקה אחרת לרכישת רכב. מה הסעד העיקרי ששמעון יכול לדרוש מראובן?', 'שאלה זו עוסקת בהשלכות המשפטיות של חזרה שלא כדין מהצעה בלתי חוזרת, ובסעדים העומדים לניצע במקרה כזה. היא מדגישה את ההגנה על הסתמכות הניצע ואת האפשרות לאכיפת החוזה.', 'כאשר מציע חוזר בו מהצעה בלתי חוזרת לפני תום המועד שנקבע לקיבולה, חזרתו חסרת תוקף (סעיף 3(ב) לחוק החוזים). המשמעות היא שההצעה ממשיכה לעמוד בתוקפה, והניצע רשאי לקבלה ולהביא לכריתת חוזה מחייב. במקרה כזה, הסעד העיקרי העומד לניצע הוא אכיפת החוזה שנכרת. בנוסף, ניתן לתבוע פיצויים בגין הפרת חובת תום הלב במשא ומתן (סעיף 12 לחוק החוזים), שיכולים לכלול גם פיצויי קיום במקרים חריגים בהם חוסר תום הלב מנע את שכלול החוזה. עם זאת, הגישה המקובלת היא שחזרה בלתי מורשית מהצעה בלתי חוזרת היא חסרת תוקף, והניצע יכול לקשור חוזה למרות זאת. ראו פרידמן וכהן, חוזים, עמ'' 133.',
    'הנחה שגויה כי חזרה מהצעה בלתי חוזרת מבטלת את ההצעה, וכי הסעד היחיד הוא פיצויים בגין חוסר תום לב, ולא אכיפה.', '["הצעה בלתי חוזרת", "חזרה שלא כדין", "אכיפת חוזה", "פיצויים שליליים", "פיצויים חיוביים", "חוסר תום לב", "הסתמכות"]'::jsonb, '**וריאציה 1 — תוקף החזרה:** האם חזרה מהצעה בלתי חוזרת תקפה? ← לא, היא חסרת תוקף (סעיף 3(ב) לחוק החוזים).
**וריאציה 2 — סעד עיקרי:** מהו הסעד העיקרי לניצע? ← אכיפת החוזה, שכן ההצעה עדיין בתוקף (פרידמן וכהן, חוזים, עמ'' 133).
**וריאציה 3 — פיצויים:** האם ניתן לתבוע פיצויים? ← כן, בגין הפרת חובת תום הלב, ולעיתים גם פיצויי קיום (ע"א 829/80 שיכון עובדים נ'' זפניק).', 'חזרה מהצעה בלתי חוזרת ← חסרת תוקף ← הניצע יכול לאכוף את החוזה ← סעיף 3(ב) לחוק החוזים.',
    '["חוק החוזים (חלק כללי), התשל\"ג-1973, סעיף 3(ב)", "דניאל פרידמן ונילי כהן, חוזים כרך א (2018) | חזרה מהצעה", "ע\"א 829/80 שכון עובדים בע\"מ נ'' שרה זפניק (13.03.1983)"]'::jsonb
  );
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_3, 'א', 'אכיפת החוזה, שכן ראובן אינו רשאי לחזור בו מהצעה בלתי חוזרת.', true, 'זוהי התשובה הנכונה. חזרה מהצעה בלתי חוזרת היא חסרת תוקף, והניצע רשאי לקבל את ההצעה ולהביא לכריתת חוזה, שניתן לאכוף אותו.', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_3, 'ב', 'פיצויים שליליים בלבד, בגין הנזקים שנגרמו לו עקב הסתמכותו על ההצעה.', false, 'טענה זו אינה נכונה. במקרה של חזרה שלא כדין מהצעה בלתי חוזרת, הסעד העיקרי הוא אכיפה, ולא רק פיצויים שליליים.', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_3, 'ג', 'פיצויים חיוביים בלבד, בגין אובדן הרווחים מהעסקה.', false, 'טענה זו אינה נכונה. הסעד העיקרי הוא אכיפה, ואם לא ניתן לאכוף, אז פיצויים חיוביים, אך לא רק פיצויים חיוביים.', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_3, 'ד', 'שמעון אינו זכאי לסעד כלשהו, שכן לא נכרת חוזה מחייב.', false, 'טענה זו אינה נכונה. חזרה מהצעה בלתי חוזרת היא חסרת תוקף, והניצע רשאי לקבל את ההצעה ולהביא לכריתת חוזה.', 4);

  RAISE NOTICE 'Q% inserted: external_id %', 4, '2022-S-S-Q04';
END
$$;

