-- Q05 — 2022-S-S-Q05 — chapter=family_inheritance subtopic=inheritance_will
-- classifier_note: Moshe asks lawyer to write down his oral will (immoral & charitable provisions) — will formation + content limits
-- ============================================================
DO $$
DECLARE
  v_sq_id uuid := '37047756-ddca-4810-9468-e9a5c3bd4e59'::uuid;
  v_group_id uuid := 'ff158cd5-74ec-4ee1-82a7-2e80b0120388'::uuid;
  v_chapter_id uuid;
  v_subtopic_id uuid;
  v_existing_id uuid;
  v_ang_0 uuid := '9d4b2686-2e41-4a59-969b-803949ea5ff8'::uuid;
  v_ang_1 uuid := 'd3de084e-c7f0-479b-9b67-ad588884b049'::uuid;
  v_ang_2 uuid := '5328a1b6-571f-4e37-80a6-10729dd3f1aa'::uuid;
  v_ang_3 uuid := '3744d337-4456-481d-a59f-203a9b9ae66b'::uuid;
BEGIN
  SELECT id INTO v_existing_id FROM public.source_questions WHERE external_id = '2022-S-S-Q05';
  IF v_existing_id IS NOT NULL THEN
    RAISE NOTICE 'Q% skipped: external_id % already exists', 5, '2022-S-S-Q05';
