  SELECT id INTO v_subtopic_id FROM public.subtopics WHERE code = 'inheritance_will' AND chapter_id = v_chapter_id;
  IF v_subtopic_id IS NULL THEN
    RAISE EXCEPTION 'Subtopic code % not found under chapter %', 'inheritance_will', 'family_inheritance';
  END IF;

  INSERT INTO public.source_questions (
    id, question_group_id, version, is_current, external_id, chapter_id, subtopic_id, question_text, source_metadata, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list, notes_for_admin, status, created_by
  ) VALUES (
    v_sq_id, v_group_id, 1, true,
    '2022-S-S-Q05', v_chapter_id, v_subtopic_id, 'משה פנה לעו"ד יצחק וביקש ממנו שיערוך עבורו צוואה. משה סיפר ליצחק כי הוא עומד למות ממחלה קשה, והוא מבקש שישמע את דבריו בעל פה ואחר כך יעלה זאת על הכתב וידאג שזו תהיה צוואתו. הוא אמר ליצחק כך: "אני רוצה שכל רכושי יעבור לאשתי, פרט ל-100,000 ש"ח שאני מבקש שתעביר לאשתך היפה, שהייתי בעבר מאוהב בה, למרות פער הגילים הגדול בינינו, וכן עוד חצי מיליון ש"ח שאני רוצה שתעביר לעמותה כלשהי העוסקת בשיקום מחבלים המשתחררים מהכלא הישראלי". יצחק ניסח צוואה לפי מה ששמע ממשה. הוא ניסה להשיג את משה בטלפון ללא כל הצלחה. עברו שבועיים, ופתאום רואה יצחק מודעת אבל המבשרת על מותו של משה. יצחק מעוניין לקיים את רצונו של משה ולמצוא דרך לקיים את דבריו כצוואה. מה מהבאים נכון?',
    '{"exam_year": 2022, "exam_season": "summer", "exam_part": 2, "exam_question_number": 5}'::jsonb, 'שאלה זו עוסקת בתנאים לתוקפה של צוואה בעל פה (צוואת שכיב מרע) לפי סעיף 23 לחוק הירושה, התשכ"ה-1965. היא בוחנת את הדרישות הצורניות המחמירות לסוג צוואה זה, ובפרט את הצורך בשני עדים ששמעו את דברי המצווה. בנוסף, היא נוגעת בעקיפין בסעיף 25 לחוק הירושה, המבטל הוראה המזכה את עורך הצוואה או עד לה, ובסעיף 30 לחוק, המבטל הוראה בלתי חוקית או בלתי מוסרית.', 'צוואה בעל פה (המכונה גם ''צוואת שכיב מרע'') היא סוג חריג של צוואה, המיועד למצבים שבהם המצווה רואה עצמו עומד למות או נמצא בסכנת מוות מיידית, ואין באפשרותו לערוך צוואה בכתב. סעיף 23 לחוק הירושה קובע תנאים מצטברים לתוקפה: 1. המצווה ראה עצמו עומד למות או היה בסכנת מוות. 2. המצווה אמר את דבריו בעל פה בפני שני עדים לפחות. 3. העדים רשמו את דברי המצווה בזיכרון דברים, חתמו עליו והפקידו אותו אצל רשם הירושה ''ככל האפשר מהר''. במקרה הנדון, משה אמר את דבריו רק לעו"ד יצחק, כלומר לא בפני שני עדים. אי עמידה בתנאי מהותי זה גוררת את בטלות הצוואה כולה. משלא נערכה צוואה תקפה, עיזבונו של משה יחולק על פי כללי הירושה על פי דין. בנוסף, גם אם הצוואה הייתה תקפה, ההוראה לטובת אשת עורך הדין הייתה בטלה לפי סעיף 25 לחוק הירושה, וההוראה לעמותה לשיקום מחבלים הייתה נבחנת בחשדנות רבה ואף עשויה להיפסל כבלתי חוקית או בלתי מוסרית לפי סעיף 30 לחוק.', 'הנחה שגויה כי עצם העלאת דברי המצווה על הכתב על ידי עורך דין מספיקה לתוקף צוואה בעל פה, או אי ידיעת הדרישה לשני עדים בצוואה מסוג זה.',
    '["צוואה בעל פה", "צוואת שכיב מרע", "חוק הירושה", "דרישות צורניות", "בטלות צוואה", "ירושה על פי דין", "עדים לצוואה"]'::jsonb, '**וריאציה 1 — תנאי צוואת שכיב מרע:** מהם התנאים המצטברים לצוואה בעל פה? ← מצווה רואה עצמו עומד למות, אומר בפני 2 עדים, העדים רושמים ומפקידים (סעיף 23 לחוק הירושה).
**וריאציה 2 — חשיבות העדים:** מדוע חסרונם של שני עדים מבטל את הצוואה? ← זוהי דרישה מהותית להבטחת אמינות הצוואה וגמירת דעתו של המצווה (ע"א 464/77 הקר נ'' עזבון המנוח הקר).
**וריאציה 3 — השלכות בטלות:** מה קורה אם הצוואה בטלה? ← העיזבון יחולק על פי כללי הירושה על פי דין (סעיף 1 לחוק הירושה).', 'צוואה בעל פה ← דורשת 2 עדים + שכיב מרע + העלאה על הכתב והפקדה ← חסר תנאי ← בטלה ← ירושה על פי דין.', '["חוק הירושה, התשכ\"ה-1965, סעיפים 1, 23, 25, 30", "ע\"א 464/77 הקר נ'' עזבון המנוח הקר, פ\"ד לב(2) 468 (1978)"]'::jsonb,
    'classification_review: original chapter=''סדר דין אזרחי'' subtopic=''הליכים'' → mapped chapter=''family_inheritance'' subtopic=''inheritance_will'' | classifier_note: Moshe asks lawyer to write down his oral will (immoral & charitable provisions) — will formation + content limits | source_review_note: שאלה זו עוסקת בדיני ירושה (מהותי) ואינה משתייכת לתחום הדין הדיוני. סווגה תחת ''סדר דין אזרחי - הליכים'' כהצבת מקום בלבד.', 'active', 'b9ecdde2-d07e-4761-96ab-05f0ad32d4e3'
  );

  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'א', 'מדובר בצוואה בעל פה, מצב שבו משה ראה עצמו "שכיב מרע", ויצחק העלה את הדברים על הכתב מיד לאחר פגישתו עם משה. הוא יכול להפקיד את המסמך אצל רשם לעניני ירושה, והוא יהווה צוואה שכולה תקפה.', false, 'טענה זו אינה נכונה. צוואה בעל פה דורשת שני עדים ששמעו את דברי המצווה, והעלאת הדברים על הכתב על ידי אחד מהם, תנאים שלא התקיימו במלואם.', 1);
  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'ב', 'מדובר בצוואה בעל פה, מצב שבו משה ראה עצמו "שכיב מרע", ויצחק העלה את הדברים על הכתב מיד לאחר פגישתו עם משה. הוא יכול להפקיד את המסמך אצל רשם לעניני ירושה, והוא יהווה צוואה תקפה פרט לסעיף לטובת עמותה כלשהי העוסקת בשיקום מחבלים כי הוא לא ברור ואינו חוקי, ועל כן בטל חלק זה בלבד.', false, 'טענה זו אינה נכונה. הצוואה אינה תקפה כצוואה בעל פה בשל אי עמידה בתנאי העדים. בנוסף, הוראה לעמותה העוסקת בשיקום מחבלים עשויה להיחשב כבלתי חוקית או בלתי מוסרית, אך זה לא הופך את שאר הצוואה לתקפה.', 2);
  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'ג', 'מדובר בצוואה בעל פה, מצב שבו משה ראה עצמו "שכיב מרע", ויצחק העלה את הדברים על הכתב מיד לאחר פגישתו עם משה. הוא יכול להפקיד את המסמך אצל רשם לעניני ירושה, והוא יהווה צוואה תקפה פרט לסעיף לטובת אשתו של עורך הדין, ועל כן בטל חלק זה בלבד.', false, 'טענה זו אינה נכונה. הצוואה אינה תקפה כצוואה בעל פה בשל אי עמידה בתנאי העדים. בנוסף, הוראה לטובת אשת עורך הדין בטלה לפי סעיף 25 לחוק הירושה, אך זה לא הופך את שאר הצוואה לתקפה.', 3);
  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'ד', 'לא מדובר בצוואה בעל פה. עיזבונו של משה יחולק בהתאם לכללי הירושה על פי דין.', true, 'זוהי התשובה הנכונה. צוואה בעל פה (צוואת שכיב מרע) דורשת שמשה יאמר את דבריו בפני שני עדים לפחות, ושהעדים יעלו את הדברים על הכתב ויפקידו אותם אצל רשם הירושה. במקרה זה, משה אמר את דבריו רק לעו"ד יצחק, ולכן לא התקיימו תנאי סעיף 23 לחוק הירושה. משלא נערכה צוואה תקפה, יחולק העיזבון על פי כללי הירושה על פי דין.', 4);

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_0, v_sq_id, 'א', 'תוקף צוואה בעל פה בתנאים מתאימים',
    1, 'משה, חולה סופני, חש ברע מאוד בביתו. הוא קרא לשני שכניו, ראובן ושמעון, וביקש מהם לשמוע את צוואתו בעל פה. הוא אמר להם: "אני רוצה שכל רכושי יעבור לאשתי, למעט 100,000 ש"ח שאני מבקש שתעבירו לעמותה לילדים חולי סרטן". ראובן ושמעון העלו את הדברים על הכתב מיד לאחר מכן, חתמו עליהם והפקידו אותם אצל רשם הירושה. משה נפטר יומיים לאחר מכן. מה הדין?', 'שאלה זו בוחנת את התנאים המצטברים הנדרשים לתוקפה של צוואה בעל פה (צוואת שכיב מרע) לפי סעיף 23 לחוק הירושה. היא מדגישה את חשיבות עמידה קפדנית בדרישות הצורניות המיוחדות לסוג צוואה זה.', 'סעיף 23 לחוק הירושה, התשכ"ה-1965, קובע את התנאים לתוקפה של צוואה בעל פה (המכונה גם ''צוואת שכיב מרע''). התנאים הם: 1. המצווה ראה עצמו, בשעת עשיית הצוואה, עומד למות (או היה בסכנת מוות). 2. המצווה אמר את דבריו בעל פה בפני שני עדים לפחות. 3. העדים רשמו את דברי המצווה בזיכרון דברים, חתמו עליו והפקידו אותו אצל רשם הירושה. במקרה המתואר, כל התנאים הללו התקיימו: משה חש ברע מאוד (שכיב מרע), אמר את דבריו בפני שני עדים (ראובן ושמעון), והם העלו את הדברים על הכתב, חתמו והפקידו. לכן, הצוואה תקפה במלואה.',
    'אי ידיעת כל התנאים המצטברים לצוואה בעל פה, או הנחה שגויה כי די בכך שהמצווה אמר את דבריו לעד אחד.', '["צוואה בעל פה", "צוואת שכיב מרע", "חוק הירושה", "עדים לצוואה", "דרישות צורניות"]'::jsonb, '**וריאציה 1 — תנאי שכיב מרע:** מהם התנאים לצוואת שכיב מרע? ← מצווה רואה עצמו עומד למות, אומר בפני 2 עדים, העדים רושמים ומפקידים (סעיף 23 לחוק הירושה).
**וריאציה 2 — חשיבות העדים:** מדוע נדרשים שני עדים? ← להבטיח את אמינות הצוואה ואת גמירת דעתו של המצווה (ע"א 464/77 הקר נ'' עזבון המנוח הקר).
**וריאציה 3 — מועד הפקדה:** מה קורה אם הזיכרון דברים לא הופקד מיד? ← הצוואה עלולה להיפסל אם לא הופקדה ''ככל האפשר מהר'' (סעיף 23(ב) לחוק הירושה).', 'צוואה בעל פה ← שכיב מרע + 2 עדים + העלאה על הכתב + הפקדה ← תוקף מלא.',
    '["חוק הירושה, התשכ\"ה-1965, סעיף 23", "ע\"א 464/77 הקר נ'' עזבון המנוח הקר, פ\"ד לב(2) 468 (1978)"]'::jsonb
  );
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_0, 'א', 'הצוואה תקפה במלואה.', true, 'זוהי התשובה הנכונה. כל תנאי צוואה בעל פה (צוואת שכיב מרע) התקיימו: המצווה ראה עצמו עומד למות, אמר את דבריו בפני שני עדים, העדים העלו את הדברים על הכתב וחתמו עליהם, והפקידו אצל רשם הירושה.', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_0, 'ב', 'הצוואה אינה תקפה, שכן צוואה חייבת להיות בכתב.', false, 'טענה זו אינה נכונה. חוק הירושה מכיר בסוגים שונים של צוואות, כולל צוואה בעל פה, בתנאים מסוימים.', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_0, 'ג', 'הצוואה תקפה, אך ההוראה לעמותה בטלה כי היא לא מפורטת מספיק.', false, 'טענה זו אינה נכונה. הוראה לעמותה לילדים חולי סרטן היא מספיק מפורטת ואינה בטלה מעצם היותה כזו.', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_0, 'ד', 'הצוואה תקפה, אך רק אם משה חתם עליה לפני מותו.', false, 'טענה זו אינה נכונה. צוואה בעל פה אינה דורשת חתימת המצווה, אלא חתימת העדים.', 4);

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_1, v_sq_id, 'ב', 'דרישות צורניות לצוואה',
    2, 'מהי הדרישה הצורנית המרכזית המשותפת לכל סוגי הצוואות (למעט צוואה בעל פה)?', 'שאלה זו בוחנת את ההבנה של הדרישות הצורניות השונות לסוגי הצוואות המוכרים בחוק הירושה, ואת המכנה המשותף ביניהן. היא מדגישה את חשיבות דרישת הכתב כעקרון יסוד בדיני צוואות.', 'חוק הירושה, התשכ"ה-1965, מכיר בארבעה סוגי צוואות עיקריים: צוואה בכתב יד (סעיף 19), צוואה בעדים (סעיף 20), צוואה בפני רשות (סעיף 22) וצוואה בעל פה (סעיף 23). למעט צוואה בעל פה, כל שאר סוגי הצוואות דורשות צורה כלשהי של כתב: צוואה בכתב יד נכתבת כולה בכתב ידו של המצווה; צוואה בעדים היא מסמך בכתב; וצוואה בפני רשות נרשמת בפרוטוקול או נמסרת בכתב לרשות. דרישת הכתב נועדה להבטיח את רצינות המצווה, למנוע זיופים ולהקל על הוכחת תוכן הצוואה.',
    'התמקדות בדרישות צורניות ספציפיות לסוג צוואה אחד, במקום זיהוי המכנה המשותף לרוב סוגי הצוואות.', '["דרישות צורניות", "צוואה בכתב יד", "צוואה בעדים", "צוואה בפני רשות", "חוק הירושה", "דרישת הכתב"]'::jsonb, '**וריאציה 1 — סוגי צוואות:** מהם סוגי הצוואות המוכרים בחוק? ← בכתב יד, בעדים, בפני רשות, בעל פה (סעיפים 19-23 לחוק הירושה).
**וריאציה 2 — חשיבות הכתב:** מדוע דרישת הכתב כה חשובה בצוואות? ← להבטיח רצינות, למנוע זיופים, להקל על הוכחה (ע"א 724/87 ורדה כלפה נ'' גרופר).
**וריאציה 3 — חריג לכתב:** מהו החריג היחיד לדרישת הכתב? ← צוואה בעל פה (סעיף 23 לחוק הירושה).', 'כל הצוואות (למעט בעל פה) ← דורשות כתב ← סעיפים 19-22 לחוק הירושה.',
    '["חוק הירושה, התשכ\"ה-1965, סעיפים 19, 20, 22", "ע\"א 724/87 ורדה כלפה נ'' גרופר, פ\"ד מח(1) 474 (1994)"]'::jsonb
  );
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_1, 'א', 'חתימת המצווה.', false, 'חתימת המצווה נדרשת ברוב סוגי הצוואות, אך לא בכולן (למשל, צוואה בפני רשות אינה דורשת חתימת המצווה).', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_1, 'ב', 'נוכחות שני עדים.', false, 'נוכחות שני עדים נדרשת בצוואה בעדים, אך לא בצוואה בכתב יד או בפני רשות.', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_1, 'ג', 'דרישת הכתב.', true, 'זוהי התשובה הנכונה. כל סוגי הצוואות המוכרות בחוק הירושה, למעט צוואה בעל פה, דורשות צורה כלשהי של כתב (כתב יד, מסמך כתוב, פרוטוקול).', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_1, 'ד', 'אישור נוטריוני.', false, 'אישור נוטריוני נדרש רק בצוואה בפני רשות (נוטריון), ואינו דרישה כללית לכל סוגי הצוואות.', 4);

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_2, v_sq_id, 'ג', 'בטלות הוראות בצוואה',
    3, 'משה ערך צוואה בכתב בפני עדים, ובה קבע כי כל רכושו יעבור לאשתו, למעט סכום של 100,000 ש"ח שיעבור לעורך דינו שערך את הצוואה. מה הדין לגבי הוראה זו?', 'שאלה זו עוסקת בעקרון בטלות הוראות צוואה מסוימות, ובפרט בהוראה המזכה את עורך הדין שערך את הצוואה. היא בוחנת את תכלית סעיף 25 לחוק הירושה, המגן על המצווה מפני השפעה בלתי הוגנת.', 'סעיף 25 לחוק הירושה, התשכ"ה-1965, קובע כי הוראת צוואה המזכה את מי שערך אותה, היה עד לעשייתה, או לקח חלק בעריכתה, בטלה. תכלית הסעיף היא למנוע ניגוד עניינים והשפעה בלתי הוגנת על המצווה. במקרה זה, עורך הדין יצחק ערך את הצוואה, ולכן ההוראה המזכה אותו (או את אשתו, כפי שצוין בשאלת המקור) בטלה. עם זאת, סעיף 37 לחוק קובע כי בטלות הוראה אחת אינה גוררת בטלות של כל הצוואה, אלא אם כן ברור שאלמלא ההוראה הבטלה, המצווה לא היה מצווה את שאר הדברים. במקרה זה, שאר הצוואה (הורשה לאישה) יכולה לעמוד בפני עצמה.',
    'הנחה שגויה כי בטלות חלקית גוררת בטלות מלאה של הצוואה, או אי ידיעת האיסור הספציפי על זיכוי עורך דין/עד.', '["בטלות הוראת צוואה", "עורך דין", "השפעה בלתי הוגנת", "חוק הירושה", "בטלות חלקית"]'::jsonb, '**וריאציה 1 — בטלות הוראה:** מתי הוראת צוואה בטלה? ← אם היא מזכה את עורך הצוואה או עד לה (סעיף 25 לחוק הירושה).
**וריאציה 2 — תכלית הסעיף:** מהי מטרת סעיף 25? ← למנוע ניגוד עניינים והשפעה בלתי הוגנת (ע"א 750/87 קניג נ'' כהן).
**וריאציה 3 — בטלות חלקית:** האם בטלות הוראה אחת מבטלת את כל הצוואה? ← לא, אלא אם ברור שאלמלא ההוראה הבטלה המצווה לא היה מצווה את השאר (סעיף 37 לחוק הירושה).', 'הוראה לטובת עורך דין/עד ← בטלה ← שאר הצוואה תקפה ← סעיף 25 לחוק הירושה.',
    '["חוק הירושה, התשכ\"ה-1965, סעיפים 25, 37", "ע\"א 750/87 קניג נ'' כהן, פ\"ד מה(1) 701 (1991)"]'::jsonb
  );
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_2, 'א', 'הצוואה כולה בטלה, שכן יש בה הוראה פסולה.', false, 'טענה זו אינה נכונה. בטלות הוראה ספציפית אינה גוררת בהכרח בטלות של כל הצוואה, אלא אם כן היא פוגעת באופן מהותי ברצון המצווה.', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_2, 'ב', 'ההוראה לטובת עורך הדין בטלה, אך שאר חלקי הצוואה תקפים.', true, 'זוהי התשובה הנכונה. סעיף 25 לחוק הירושה קובע כי הוראת צוואה המזכה את עורך הדין שערך אותה בטלה, אך שאר חלקי הצוואה נשארים תקפים.', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_2, 'ג', 'ההוראה לטובת עורך הדין תקפה, שכן המצווה רשאי לצוות למי שיחפוץ.', false, 'טענה זו אינה נכונה. סעיף 25 לחוק הירושה נועד למנוע ניצול השפעה בלתי הוגנת על המצווה.', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_2, 'ד', 'ההוראה לטובת עורך הדין תקפה רק אם בית המשפט אישר אותה.', false, 'טענה זו אינה נכונה. סעיף 25 קובע בטלות מוחלטת של הוראה כזו, ללא אפשרות לאישור בית משפט.', 4);

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_3, v_sq_id, 'ד', 'ירושה על פי דין',
    4, 'משה נפטר ולא הותיר אחריו צוואה תקפה. הוא הותיר אחריו אישה ושני ילדים. כיצד יחולק עיזבונו?', 'שאלה זו בוחנת את כללי הירושה על פי דין, החלים כאשר אדם נפטר ללא צוואה תקפה. היא מתמקדת בחלוקת העיזבון בין בן זוג לילדים, כפי שנקבע בסעיפים 10 ו-11 לחוק הירושה.', 'כאשר אדם נפטר ולא הותיר אחריו צוואה תקפה, עיזבונו יחולק על פי כללי הירושה על פי דין, המפורטים בפרק השני לחוק הירושה, התשכ"ה-1965. סעיף 10 לחוק קובע מיהם היורשים על פי דין, וסעיף 11 מפרט את חלקיהם. במקרה של מנוח שהותיר אחריו בן זוג וילדים, בן הזוג יורש מחצית מהעיזבון, והילדים יורשים את המחצית הנותרת בחלקים שווים ביניהם. לכן, האישה תקבל מחצית, ושני הילדים יחלקו ביניהם את המחצית הנותרת, כלומר כל ילד יקבל רבע מהעיזבון.',
    'אי ידיעת שיעורי החלוקה הספציפיים בין בן זוג לילדים, או הנחה שגויה כי בן הזוג יורש את כל העיזבון או חלק שווה לילדים.', '["ירושה על פי דין", "חוק הירושה", "בן זוג", "ילדים", "חלוקת עיזבון", "יורשים"]'::jsonb, '**וריאציה 1 — יורשים על פי דין:** מי יורש על פי דין? ← בן זוג, ילדים, הורים, אחים, סבים (סעיף 10 לחוק הירושה).
**וריאציה 2 — חלק בן זוג וילדים:** מה חלקם של בן זוג וילדים? ← בן זוג מחצית, ילדים מחצית הנותרת בשווה (סעיף 11 לחוק הירושה).
**וריאציה 3 — אין צוואה:** מה קורה כשאין צוואה תקפה? ← העיזבון מתחלק על פי דין (סעיף 1 לחוק הירושה).', 'אין צוואה תקפה ← ירושה על פי דין ← אישה חצי, ילדים חצי הנותר בשווה ← סעיפים 10-11 לחוק הירושה.',
    '["חוק הירושה, התשכ\"ה-1965, סעיפים 10, 11"]'::jsonb
  );
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_3, 'א', 'האישה תקבל את כל העיזבון, שכן היא היורשת היחידה.', false, 'טענה זו אינה נכונה. במקרה של ילדים, האישה אינה היורשת היחידה.', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_3, 'ב', 'האישה תקבל מחצית מהעיזבון, ושני הילדים יחלקו ביניהם את המחצית הנותרת בשווה.', true, 'זוהי התשובה הנכונה. סעיף 11 לחוק הירושה קובע כי במקרה של אישה וילדים, האישה יורשת מחצית מהעיזבון, והילדים יורשים את המחצית הנותרת בחלקים שווים ביניהם.', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_3, 'ג', 'הילדים יקבלו את כל העיזבון, שכן הם היורשים הקרובים ביותר.', false, 'טענה זו אינה נכונה. האישה היא יורשת על פי דין יחד עם הילדים.', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_3, 'ד', 'העיזבון יחולק לשלושה חלקים שווים בין האישה לשני הילדים.', false, 'טענה זו אינה נכונה. חלוקת העיזבון בין אישה וילדים אינה שווה בשליש לכל אחד.', 4);

  RAISE NOTICE 'Q% inserted: external_id %', 5, '2022-S-S-Q05';
END
$$;

-- ============================================================
-- Q07 — 2022-S-S-Q07 — chapter=property subtopic=chattels_lost_found  [needs_review]
-- classifier_note: Noam refuses to leave Haviv's car — owner's right to remove a trespasser from chattel. Closest subtopic is chattels; could also fit torts/nuisance_trespass
-- ============================================================
DO $$
DECLARE
  v_sq_id uuid := '2b105bde-2004-4d37-85b7-332ec8ae9ec4'::uuid;
  v_group_id uuid := 'f5de854c-4aa3-4921-a42f-e8949cd7dd7a'::uuid;
  v_chapter_id uuid;
  v_subtopic_id uuid;
  v_existing_id uuid;
  v_ang_0 uuid := '26a3e1fc-cdd4-412e-be2f-e6b1b5cfa2b6'::uuid;
  v_ang_1 uuid := 'c8c52e20-743b-4b42-942a-96ff0a5cdd5b'::uuid;
  v_ang_2 uuid := '093e2ad5-a2ce-4640-b13e-cce7c17d4e90'::uuid;
  v_ang_3 uuid := 'f7d26a73-7a0a-4ea0-afb0-85f061122d69'::uuid;
BEGIN
  SELECT id INTO v_existing_id FROM public.source_questions WHERE external_id = '2022-S-S-Q07';
  IF v_existing_id IS NOT NULL THEN
    RAISE NOTICE 'Q% skipped: external_id % already exists', 7, '2022-S-S-Q07';
    RETURN;
  END IF;

  SELECT id INTO v_chapter_id FROM public.chapters WHERE code = 'property';
  IF v_chapter_id IS NULL THEN
    RAISE EXCEPTION 'Chapter code % not found', 'property';
  END IF;

  SELECT id INTO v_subtopic_id FROM public.subtopics WHERE code = 'chattels_lost_found' AND chapter_id = v_chapter_id;
  IF v_subtopic_id IS NULL THEN
    RAISE EXCEPTION 'Subtopic code % not found under chapter %', 'chattels_lost_found', 'property';
  END IF;

  INSERT INTO public.source_questions (
    id, question_group_id, version, is_current, external_id, chapter_id, subtopic_id, question_text, source_metadata, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list, notes_for_admin, status, created_by
  ) VALUES (
    v_sq_id, v_group_id, 1, true,
    '2022-S-S-Q07', v_chapter_id, v_subtopic_id, 'חביב הוא בעלים של רכב מסוג מאזדה. יום אחד, בעת שישב חביב ברכבו, התפרץ נועם למושב האחורי של הרכב והתיישב. חביב ניסה לשכנע את נועם לצאת מהרכב, אך לא הצליח בכך. חלפו כמה דקות, וחביב מתקשר אליכם לשאול מה בידיו לעשות כעת. מה הדין?',
    '{"exam_year": 2022, "exam_season": "summer", "exam_part": 2, "exam_question_number": 7}'::jsonb, 'שאלה זו עוסקת בזכות לסעד עצמי (עשיית דין עצמית) להגנה על חזקה במיטלטלין, תוך יישום עקרונות סעיף 18 לחוק המקרקעין, המוחלים על מיטלטלין באמצעות סעיף 8 לחוק המיטלטלין. היא בוחנת את גבולות החריג לכלל הרחב של איסור עשיית דין עצמית, המאפשר שימוש בכוח סביר במקרה של פלישה טרייה.', 'הכלל הרחב במשפט הישראלי הוא איסור על עשיית דין עצמית, מתוך רצון לשמור על הסדר הציבורי ולמנוע אלימות. עם זאת, קיימים חריגים צרים ומוגדרים היטב. אחד החריגים המרכזיים הוא סעיף 18 לחוק המקרקעין, תשכ"ט-1969, אשר סעיף 8 לחוק המיטלטלין, תשל"א-1971, מחיל את הוראותיו גם על הגנת הבעלות והחזקה במיטלטלין. סעיף 18(א) מתיר למחזיק כדין להשתמש בכוח סביר כדי למנוע הסגת גבול, וסעיף 18(ב) מתיר למחזיק כדין להשתמש בכוח סביר כדי להוציא פולש שתפס את המקרקעין שלא כדין, ובלבד שהפעולה נעשית ''תוך שלושים ימים מיום התפיסה''. במקרה הנדון, חביב הוא המחזיק כדין ברכבו, נועם התפרץ ותפס את הרכב שלא כדין, והפלישה היא ''טרייה'' (חלפו כמה דקות). לכן, חביב רשאי להפעיל כוח סביר כדי לפנות את נועם מהרכב. הפסיקה מדגישה כי זכות זו עומדת גם למחזיק ברכב (ע"א (מחוזי ירושלים) 3238/09 מדינת ישראל – משטרת ישראל נ'' טלי בן לולו).', 'הנחה שגויה כי איסור עשיית דין עצמית הוא מוחלט ואינו כולל חריגים, או אי הבחנה בין ''כוח סביר'' ל''כל דבר''.',
    '["סעד עצמי", "חוק המיטלטלין", "חוק המקרקעין", "הגנת החזקה", "פלישה טרייה", "כוח סביר", "איסור עשיית דין עצמית"]'::jsonb, '**וריאציה 1 — סעד עצמי במיטלטלין:** האם סעיף 18 לחוק המקרקעין חל על רכב? ← כן, באמצעות סעיף 8 לחוק המיטלטלין.
**וריאציה 2 — תנאי הפעלה:** מהם התנאים להפעלת סעד עצמי? ← מחזיק כדין, פלישה שלא כדין, תוך 30 יום, כוח סביר (סעיף 18(ב) לחוק המקרקעין).
**וריאציה 3 — תפקיד המשטרה:** האם ניתן להיעזר במשטרה? ← כן, המשטרה מחויבת לסייע למחזיק כדין במימוש זכותו לסעד עצמי (ע"א (מחוזי ירושלים) 3238/09 מדינת ישראל – משטרת ישראל נ'' טלי בן לולו).', 'מחזיק כדין במיטלטלין ← רשאי להפעיל כוח סביר ← לפנות פולש בפלישה טרייה ← סעיף 8 לחוק המיטלטלין + סעיף 18 לחוק המקרקעין.', '["חוק המיטלטלין, תשל\"א-1971, סעיף 8", "חוק המקרקעין, תשכ\"ט-1969, סעיף 18", "רע\"א 4311/00 מדינת ישראל נ'' אליעזר בן שמחון, נח(1) 827 (2003)", "ע\"א (מחוזי ירושלים) 3238/09 מדינת ישראל – משטרת ישראל נ'' טלי בן לולו (08.09.2009)"]'::jsonb,
    'needs_review=true | classification_review: original chapter=''סדר דין אזרחי'' subtopic=''הליכים'' → mapped chapter=''property'' subtopic=''chattels_lost_found'' | classifier_note: Noam refuses to leave Haviv''s car — owner''s right to remove a trespasser from chattel. Closest subtopic is chattels; could also fit torts/nuisance_trespass | source_review_note: שאלה זו עוסקת בדיני קניין (מהותי) ואינה משתייכת לתחום הדין הדיוני. סווגה תחת ''סדר דין אזרחי - הליכים'' כהצבת מקום בלבד.', 'active', 'b9ecdde2-d07e-4761-96ab-05f0ad32d4e3'
  );

  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'א', 'חביב רשאי להפעיל כוח סביר כדי לפנות את נועם מהרכב.', true, 'זוהי התשובה הנכונה. סעיף 8 לחוק המיטלטלין מחיל את סעיף 18 לחוק המקרקעין, המתיר למחזיק כדין להשתמש בכוח סביר כדי למנוע הסגת גבול או להוציא פולש בפלישה טרייה.', 1);
  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'ב', 'חביב אינו רשאי להפעיל כוח בשום צורה, אך רשאי להזמין משטרה שתפנה את נועם.', false, 'טענה זו אינה נכונה. חביב רשאי להפעיל כוח סביר בעצמו. הוא גם רשאי להזמין משטרה, אך זו אינה האפשרות היחידה.', 2);
  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'ג', 'חביב אינו רשאי להפעיל כוח בשום צורה, ועליו לפעול לקבלת צו שיפוטי מתאים.', false, 'טענה זו אינה נכונה. הכלל הוא איסור על עשיית דין עצמית, אך סעיף 18 לחוק המקרקעין (החל על מיטלטלין) מהווה חריג המאפשר שימוש בכוח סביר בפלישה טרייה.', 3);
  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'ד', 'חביב רשאי לעשות כל דבר כדי לסלק את נועם מרכבו.', false, 'טענה זו אינה נכונה. השימוש בכוח מוגבל ל''מידה סבירה'' בלבד, ולא ''כל דבר'', כדי למנוע אלימות יתרה.', 4);

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_0, v_sq_id, 'א', 'סעד עצמי במקרקעין לאחר 30 יום',
    1, 'ראובן הוא בעלים של מגרש ריק. לפני חודשיים פלש שמעון למגרש והקים עליו מבנה ארעי. ראובן גילה זאת רק היום. האם ראובן רשאי להפעיל כוח סביר כדי לפנות את שמעון מהמגרש?', 'שאלה זו בוחנת את מגבלת הזמן הקריטית להפעלת סעד עצמי במקרקעין, כפי שנקבע בסעיף 18(ב) לחוק המקרקעין. היא מדגישה את העיקרון לפיו לאחר חלוף תקופה מסוימת, יש לפנות לערכאות משפטיות ולא לעשות דין עצמי.', 'סעיף 18(ב) לחוק המקרקעין, תשכ"ט-1969, קובע כי מחזיק במקרקעין כדין רשאי להשתמש בכוח במידה סבירה כדי להוציא פולש, אך זאת ''תוך שלושים ימים מיום התפיסה''. הפסיקה מדגישה כי זוהי מגבלה דווקנית וכי לאחר חלוף 30 יום, אין עוד אפשרות להפעיל סעד עצמי, ועל המחזיק לפנות לבית המשפט בבקשה לסילוק יד (רע"א 4311/00 מדינת ישראל נ'' בן שמחון, ת"א (שלום חי'') 1884-04-21 ליאור גיא תורג''מן נ'' רשות מקרקעי ישראל). במקרה זה, חלפו חודשיים, ולכן ראובן אינו רשאי להפעיל כוח סביר ועליו לפנות לערכאות.',
    'הנחה שגויה כי זכות הבעלות מקנה זכות בלתי מוגבלת לסעד עצמי, ללא קשר למועד הפלישה.', '["סעד עצמי", "חוק המקרקעין", "פלישה טרייה", "מגבלת זמן", "סילוק יד", "איסור עשיית דין עצמית"]'::jsonb, '**וריאציה 1 — מועד הפלישה:** מהי ''פלישה טרייה'' המאפשרת סעד עצמי? ← פלישה שארעה לכל היותר 30 יום לפני הפעולה (סעיף 18(ב) לחוק המקרקעין).
**וריאציה 2 — חלוף זמן:** מה קורה לאחר 30 יום? ← אין סעד עצמי, יש לפנות לבית המשפט (רע"א 4311/00 מדינת ישראל נ'' בן שמחון).
**וריאציה 3 — תכלית המגבלה:** מדוע קיימת מגבלת זמן? ← למנוע אלימות ולשמור על הסדר הציבורי, תוך איזון עם הצורך בתגובה מיידית (ת"א (שלום חי'') 35610-09-15 עמותת עמודי עולם נ'' עיריית חיפה).', 'סעד עצמי במקרקעין ← רק בפלישה טרייה ← תוך 30 יום ← אחרת פונים לבית משפט.',
    '["חוק המקרקעין, תשכ\"ט-1969, סעיף 18(ב)", "רע\"א 4311/00 מדינת ישראל נ'' אליעזר בן שמחון, נח(1) 827 (2003)", "ת\"א (שלום חי'') 1884-04-21 ליאור גיא תורג''מן נ'' רשות מקרקעי ישראל (23.04.2021)", "ת\"א (שלום חי'') 35610-09-15 עמותת עמודי עולם נ'' עיריית חיפה (07.03.2016)"]'::jsonb
  );
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_0, 'א', 'כן, ראובן רשאי להפעיל כוח סביר, שכן הוא הבעלים של המגרש.', false, 'טענה זו אינה נכונה. זכות הסעד העצמי מוגבלת בזמן, ואינה עומדת לבעלים לאחר חלוף 30 יום מיום הפלישה.', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_0, 'ב', 'לא, ראובן אינו רשאי להפעיל כוח סביר, שכן חלפו למעלה מ-30 יום מיום הפלישה.', true, 'זוהי התשובה הנכונה. סעיף 18(ב) לחוק המקרקעין מתיר סעד עצמי רק תוך 30 יום מיום התפיסה. לאחר מכן, יש לפנות לערכאות משפטיות.', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_0, 'ג', 'כן, ראובן רשאי להפעיל כוח סביר, אך רק אם יוכיח ששמעון פלש שלא כדין.', false, 'טענה זו אינה נכונה. אף אם הפלישה הייתה שלא כדין, מגבלת הזמן של 30 יום היא תנאי מצטבר לסעד עצמי.', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_0, 'ד', 'לא, ראובן אינו רשאי להפעיל כוח סביר, שכן מדובר במקרקעין ולא במיטלטלין.', false, 'טענה זו אינה נכונה. סעיף 18 לחוק המקרקעין עוסק במקרקעין, והוא המקור לזכות הסעד העצמי בהם, בכפוף למגבלותיו.', 4);

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_1, v_sq_id, 'ב', 'תנאי הפעלת כוח סביר',
    2, 'מהם התנאים המצטברים הנדרשים כדי שמחזיק כדין יוכל להפעיל סעד עצמי לפי סעיף 18(ב) לחוק המקרקעין?', 'שאלה זו מתמקדת בזיהוי ובהבנת התנאים המצטברים הנדרשים להפעלת סעד עצמי במקרקעין, כפי שהם מוגדרים בסעיף 18(ב) לחוק המקרקעין. היא מדגישה את הדווקנות של החריג לכלל איסור עשיית דין עצמית.', 'סעיף 18(ב) לחוק המקרקעין, תשכ"ט-1969, מפרט ארבעה תנאים מצטברים להפעלת סעד עצמי: 1. המחזיק במקרקעין כדין. 2. אדם אחר תפס את המקרקעין שלא כדין. 3. הפעולה נעשתה תוך שלושים ימים מיום התפיסה (פלישה טרייה). 4. השימוש בכוח היה במידה סבירה. הפסיקה, למשל ברע"א 4311/00 מדינת ישראל נ'' בן שמחון, מדגישה את הצורך בעמידה קפדנית בכל התנאים הללו, שכן סעד עצמי הוא חריג לכלל הרחב של איסור עשיית דין עצמית.',
    'השמטת אחד מהתנאים המצטברים, במיוחד תנאי ''המחזיק כדין'' או ''תוך שלושים ימים''.', '["סעד עצמי", "חוק המקרקעין", "מחזיק כדין", "פלישה שלא כדין", "פלישה טרייה", "כוח סביר"]'::jsonb, '**וריאציה 1 — תנאי ''כדין'':** האם בעלים שלא מחזיק בפועל יכול להפעיל סעד עצמי? ← לא, רק ''מחזיק כדין'' בפועל (רע"א 4311/00 מדינת ישראל נ'' בן שמחון).
**וריאציה 2 — תנאי ''כוח סביר'':** מה נחשב ''כוח סביר''? ← כוח במידה הנדרשת בהתחשב בהתנגדות הפולש, כולל גרימת נזק סביר (ת"פ (שלום כ"ס) 2446-08 מ.י. שלוחת תביעות כפר סבא נ'' אהרון גדסי).
**וריאציה 3 — תנאי ''30 יום'':** האם ניתן להאריך את תקופת 30 הימים? ← לא, זו תקופה קבועה ודווקנית (בר"ע (מחוזי ב"ש) 768/02 מדינת ישראל נ'' סייח סלימאן אבו מדיעם).', 'סעד עצמי (סעיף 18(ב)) ← מחזיק כדין + פלישה שלא כדין + תוך 30 יום + כוח סביר.',
    '["חוק המקרקעין, תשכ\"ט-1969, סעיף 18(ב)", "רע\"א 4311/00 מדינת ישראל נ'' אליעזר בן שמחון, נח(1) 827 (2003)", "ת\"פ (שלום כ\"ס) 2446-08 מ.י. שלוחת תביעות כפר סבא נ'' אהרון גדסי (26.06.2012)", "בר\"ע (מחוזי באר שבע) 768/02 מדינת ישראל נ'' סייח סלימאן אבו מדיעם (08.08.2003)"]'::jsonb
  );
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_1, 'א', 'המחזיק הוא הבעלים של המקרקעין, הפלישה הייתה שלא כדין, והופעל כוח סביר.', false, 'טענה זו אינה נכונה. המחזיק לא חייב להיות הבעלים, וחסר תנאי הזמן הקריטי.', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_1, 'ב', 'המחזיק במקרקעין כדין, הפלישה הייתה שלא כדין, הפעולה נעשתה תוך 30 יום מיום התפיסה, והופעל כוח סביר.', true, 'זוהי התשובה הנכונה. אלו הם כל התנאים המצטברים המפורטים בסעיף 18(ב) לחוק המקרקעין ובפסיקה.', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_1, 'ג', 'המחזיק במקרקעין בפועל, הפלישה הייתה שלא כדין, והופעל כוח סביר.', false, 'טענה זו אינה נכונה. המחזיק צריך להיות ''כדין'' ולא רק ''בפועל'', וחסר תנאי הזמן הקריטי.', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_1, 'ד', 'המחזיק במקרקעין כדין, הפלישה הייתה שלא כדין, והמשטרה אישרה את הפעלת הכוח.', false, 'טענה זו אינה נכונה. אין דרישה לאישור משטרה מראש, אם כי ניתן להיעזר בה. חסר תנאי הזמן הקריטי.', 4);

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_2, v_sq_id, 'ג', 'סעד עצמי במקרקעי ציבור',
    3, 'מהו ההבדל העיקרי בין סעד עצמי במקרקעין פרטיים (לפי סעיף 18 לחוק המקרקעין) לבין סילוק פולשים ממקרקעי ציבור (לפי חוק מקרקעי ציבור (סילוק פולשים))?', 'שאלה זו עוסקת בהבחנה בין הדין הכללי של סעד עצמי במקרקעין (סעיף 18 לחוק המקרקעין) לבין ההסדר המיוחד החל על מקרקעי ציבור (חוק מקרקעי ציבור (סילוק פולשים)). היא מדגישה את ההרחבה בסמכויות הרשות במקרקעי ציבור.', 'חוק מקרקעי ציבור (סילוק פולשים), תשמ"א-1981, מהווה חריג לדין הכללי של סעד עצמי במקרקעין. בעוד שסעיף 18 לחוק המקרקעין דורש שהמחזיק כדין יפעל תוך 30 יום מיום הפלישה ושהוא אכן החזיק בפועל בקרקע שנושל ממנה, חוק סילוק פולשים מעניק לרשות המוסמכת סמכויות רחבות יותר. הרשות רשאית להוציא צו סילוק יד ללא צורך בפנייה לבית משפט, גם אם לא החזיקה בפועל במקרקעין, ומועדי הפעולה ארוכים יותר (למשל, עד 3 חודשים מיום שהתברר לה על הפלישה ולא יאוחר מ-12 חודשים מיום התפיסה, או 6 חודשים מיום שהתברר ולא יאוחר מ-36 חודשים מיום התפיסה, תלוי בסעיף הרלוונטי בחוק). נטל ההוכחה מוטל על הפולש להוכיח את זכותו (רע"א 4311/00 מדינת ישראל נ'' בן שמחון, ת"א (שלום פ"ת) 3949-07 אליעזר דאובה נ'' מינהל מקרקעי ישראל-מחוז מרכז).',
    'הנחה שגויה כי הכללים לסעד עצמי זהים במקרקעין פרטיים ובמקרקעי ציבור.', '["סעד עצמי", "מקרקעי ציבור", "חוק סילוק פולשים", "חוק המקרקעין", "צו סילוק יד", "החזקה בפועל"]'::jsonb, '**וריאציה 1 — מועדי פעולה:** מהם מועדי הפעולה במקרקעי ציבור? ← עד 3 חודשים מיום שהתברר, ולא יאוחר מ-12 חודשים מיום התפיסה (סעיף 4 לחוק סילוק פולשים).
**וריאציה 2 — דרישת החזקה:** האם הרשות חייבת להחזיק בפועל? ← לא, חוק סילוק פולשים אינו דורש החזקה בפועל (רע"א 4311/00 מדינת ישראל נ'' בן שמחון).
**וריאציה 3 — נטל ההוכחה:** על מי מוטל נטל ההוכחה במקרקעי ציבור? ← על הפולש להוכיח את זכותו (רע"א 4311/00 מדינת ישראל נ'' בן שמחון).', 'סעד עצמי במקרקעי ציבור ← סמכויות רחבות לרשות ← ללא דרישת החזקה בפועל ← מועדים ארוכים יותר.',
    '["חוק מקרקעי ציבור (סילוק פולשים), תשמ\"א-1981, סעיף 4", "רע\"א 4311/00 מדינת ישראל נ'' אליעזר בן שמחון, נח(1) 827 (2003)", "ת\"א (שלום פ\"ת) 3949-07 אליעזר דאובה נ'' מינהל מקרקעי ישראל-מחוז מרכז (04.06.2012)"]'::jsonb
  );
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_2, 'א', 'במקרקעי ציבור, אין צורך בצו שיפוטי כלל, בעוד שבמקרקעין פרטיים תמיד נדרש צו.', false, 'טענה זו אינה נכונה. גם במקרקעין פרטיים, סעיף 18 מאפשר סעד עצמי ללא צו שיפוטי בתנאים מסוימים.', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_2, 'ב', 'במקרקעי ציבור, הרשות המוסמכת רשאית להוציא צו סילוק יד גם אם לא החזיקה בפועל במקרקעין, ומועד הפעולה ארוך יותר.', true, 'זוהי התשובה הנכונה. חוק סילוק פולשים מרחיב את סמכויות הרשות המוסמכת במקרקעי ציבור, הן מבחינת דרישת החזקה בפועל והן מבחינת מגבלות הזמן.', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_2, 'ג', 'במקרקעי ציבור, נטל ההוכחה מוטל על הרשות, בעוד שבמקרקעין פרטיים הוא מוטל על הפולש.', false, 'טענה זו אינה נכונה. במקרקעי ציבור, נטל ההוכחה מוטל על הפולש להוכיח את זכותו להחזיק.', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_2, 'ד', 'אין הבדל מהותי בין סעד עצמי במקרקעין פרטיים למקרקעי ציבור.', false, 'טענה זו אינה נכונה. הפסיקה קבעה במפורש כי חוק סילוק פולשים הוא חריג משמעותי לדין הכללי.', 4);

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_3, v_sq_id, 'ד', 'תביעה פוססורית (השבת גזלה)',
    4, 'ראובן פלש למגרש של שמעון לפני שנה. שמעון, שלא יכול היה להפעיל סעד עצמי, הגיש תביעה לבית המשפט. איזו תביעה עליו להגיש כדי להשיב את החזקה לידיו במהירות, מבלי לדון בזכויות המהותיות?', 'שאלה זו בוחנת את ההבנה של סוגי התביעות להגנת החזקה במקרקעין, ובפרט את התביעה הפוססורית (תביעת השבת גזלה) לפי סעיף 19 לחוק המקרקעין. היא מדגישה את תכליתה של תביעה זו ככלי מהיר להשבת המצב העובדתי לקדמותו, ללא דיון בזכויות המהותיות.', 'כאשר חלפה תקופת 30 הימים המאפשרת סעד עצמי לפי סעיף 18 לחוק המקרקעין, הדרך העיקרית להשבת החזקה היא באמצעות פנייה לבית המשפט. סעיף 19 לחוק המקרקעין, שכותרתו ''השבת גזלה'', מאפשר למחזיק שנושל מחזקתו להגיש תביעה פוססורית. תביעה זו מטרתה להחזיר את המצב לקדמותו כפי שהיה לפני נטילת החזקה, מבלי לברר את הזכויות המהותיות של הצדדים בנכס. הדיון בתביעה הפוססורית מצומצם לשאלה אם התובע החזיק במקרקעין לפני שהם ניטלו מידיו, ואם החזקה ניטלה ממנו בכוח בניגוד לדין (רע"א 6998/11 אברהים ג''ולאני נ'' הקדש המנוח ח''ליל שרף אלדין אבו ג''בנה, ת"א (שלום ת"א) 30180-12-18 מ.א. דוידוב אחזקות והשקעות בע"מ נ'' גינדי החזקות ייזום 2009 בע"מ).',
    'בלבול בין תביעה פוססורית (הגנה על החזקה) לתביעה פטיטורית (הגנה על הבעלות/זכות מהותית).', '["תביעה פוססורית", "השבת גזלה", "חוק המקרקעין", "הגנת החזקה", "סטטוס קוו", "תביעה פטיטורית"]'::jsonb, '**וריאציה 1 — תכלית תביעה פוססורית:** מה מטרת תביעה פוססורית? ← להחזיר את המצב לקדמותו ללא דיון בזכויות מהותיות (סעיף 19 לחוק המקרקעין).
**וריאציה 2 — מתי מגישים?** מתי מגישים תביעה פוססורית? ← כאשר החזקה נלקחה שלא כדין ולא ניתן להפעיל סעד עצמי (רע"א 6998/11 אברהים ג''ולאני נ'' הקדש המנוח ח''ליל שרף אלדין אבו ג''בנה).
**וריאציה 3 — סמכות בית המשפט:** האם בית המשפט יכול לדון בזכויות המהותיות בתביעה פוססורית? ← כן, לפי סיפת סעיף 19, אך זוהי סמכות שבשיקול דעת (ע"א 756/80 שלמה רוזנשטיין נ'' הרשקו סולומון).', 'תביעה פוססורית (סעיף 19) ← השבת חזקה מהירה ← ללא דיון בזכויות מהותיות ← כאשר סעד עצמי אינו אפשרי.',
    '["חוק המקרקעין, תשכ\"ט-1969, סעיף 19", "רע\"א 6998/11 אברהים ג''ולאני נ'' הקדש המנוח ח''ליל שרף אלדין אבו ג''בנה (22.07.2012)", "ת\"א (שלום ת\"א) 30180-12-18 מ.א. דוידוב אחזקות והשקעות בע\"מ נ'' גינדי החזקות ייזום 2009 בע\"מ (03.02.2019)", "ע\"א 756/80 שלמה רוזנשטיין נ'' הרשקו סולומון, לח(2) 113 (1984)"]'::jsonb
  );
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_3, 'א', 'תביעה פטיטורית לפי סעיף 16 לחוק המקרקעין.', false, 'טענה זו אינה נכונה. תביעה פטיטורית דנה בזכויות המהותיות ואינה מיועדת להשבת חזקה מהירה ללא דיון בזכויות.', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_3, 'ב', 'תביעה פוססורית לפי סעיף 19 לחוק המקרקעין.', true, 'זוהי התשובה הנכונה. תביעה פוססורית (תביעת השבת גזלה) נועדה להחזיר את המצב לקדמותו מבלי לדון בזכויות המהותיות, כאשר החזקה נלקחה שלא כדין.', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_3, 'ג', 'תביעה למניעת הפרעה לפי סעיף 17 לחוק המקרקעין.', false, 'טענה זו אינה נכונה. תביעה למניעת הפרעה מיועדת למנוע הפרעות לשימוש, אך לא להשבת חזקה שנלקחה במלואה.', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_3, 'ד', 'תביעה לפיצויים בגין הסגת גבול.', false, 'טענה זו אינה נכונה. תביעה לפיצויים היא סעד כספי, ואינה משיבה את החזקה בפועל.', 4);

  RAISE NOTICE 'Q% inserted: external_id %', 7, '2022-S-S-Q07';
END
$$;

-- ============================================================
-- Q08 — 2022-S-S-Q08 — chapter=contracts subtopic=lease_bailment
-- classifier_note: Oral two-month lease over real estate (Eilat) — formal requirements for leases
-- ============================================================
DO $$
DECLARE
  v_sq_id uuid := '309c0b37-cf46-405f-a3f4-dc6739ccb880'::uuid;
  v_group_id uuid := '98a77ce5-ee59-4a9d-bda1-2f497ea2be42'::uuid;
  v_chapter_id uuid;
  v_subtopic_id uuid;
  v_existing_id uuid;
  v_ang_0 uuid := '3d40e1ee-ea5d-4e20-8c48-dd0250292578'::uuid;
  v_ang_1 uuid := 'bcbc7e2b-4a0e-4c67-b8e4-f437de5682ed'::uuid;
  v_ang_2 uuid := 'f27040cc-fe3c-4847-a156-cd89760c078e'::uuid;
  v_ang_3 uuid := 'f752b5ed-0c16-4248-8abc-a4ca4226ae0c'::uuid;
BEGIN
  SELECT id INTO v_existing_id FROM public.source_questions WHERE external_id = '2022-S-S-Q08';
  IF v_existing_id IS NOT NULL THEN
    RAISE NOTICE 'Q% skipped: external_id % already exists', 8, '2022-S-S-Q08';
    RETURN;
  END IF;

  SELECT id INTO v_chapter_id FROM public.chapters WHERE code = 'contracts';
  IF v_chapter_id IS NULL THEN
    RAISE EXCEPTION 'Chapter code % not found', 'contracts';
  END IF;

  SELECT id INTO v_subtopic_id FROM public.subtopics WHERE code = 'lease_bailment' AND chapter_id = v_chapter_id;
  IF v_subtopic_id IS NULL THEN
    RAISE EXCEPTION 'Subtopic code % not found under chapter %', 'lease_bailment', 'contracts';
  END IF;

  INSERT INTO public.source_questions (
    id, question_group_id, version, is_current, external_id, chapter_id, subtopic_id, question_text, source_metadata, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list, notes_for_admin, status, created_by
  ) VALUES (
    v_sq_id, v_group_id, 1, true,
    '2022-S-S-Q08', v_chapter_id, v_subtopic_id, 'אמיר ושרון מעוניינים להפעיל עסק בתקופת הקיץ, ולצורך כך הם שכרו מקרקעין באילת לתקופה של חודשיים. מאחר שההתקשרות עם המשכיר נעשתה בטלפון, פרטי ההסכם נעשו בעל פה בין הצדדים ולא נחתם כל חוזה ביניהם. מה מעמדו של חוזה השכירות?',
    '{"exam_year": 2022, "exam_season": "summer", "exam_part": 2, "exam_question_number": 8}'::jsonb, 'שאלה זו עוסקת בדרישת הכתב בחוזי שכירות מקרקעין, כפי שנקבעה בסעיף 79(א) לחוק המקרקעין, תשכ"ט-1969, ובסעיף 25טו לחוק השכירות והשאילה, תשל"א-1971. היא בוחנת את ההבחנה בין שכירות קצרה לארוכה לעניין דרישה זו, ומדגישה כי שכירות לתקופה קצרה אינה טעונה כתב.', 'סעיף 79(א) לחוק המקרקעין, תשכ"ט-1969, קובע כי ''שכירות לתקופה שאינה עולה על חמש שנים אינה טעונה רישום, ואינה טעונה מסמך בכתב''. כלומר, שכירות מקרקעין לתקופה של עד חמש שנים יכולה להיעשות בעל פה ותהיה תקפה. במקרה הנדון, אמיר ושרון שכרו מקרקעין לתקופה של חודשיים בלבד, שהיא פחות מחמש שנים. לכן, ההסכם בעל פה תקף, ואין צורך במסמך בכתב. חשוב לציין כי לגבי שכירות דירה, סעיף 25טו לחוק השכירות והשאילה, תשל"א-1971, מעלה את הרף לעשר שנים, כך ששכירות דירה לתקופה שאינה עולה על עשר שנים אינה טעונה כתב. בשני המקרים, שכירות לחודשיים אינה טעונה כתב.', 'הנחה שגויה כי כל עסקה במקרקעין, כולל שכירות, טעונה כתב מהותי, בדומה לדרישה הקבועה בסעיף 8 לחוק המקרקעין לעניין התחייבות לעשות עסקה במקרקעין.',
    '["דרישת כתב", "שכירות מקרקעין", "חוק המקרקעין", "חוק השכירות והשאילה", "שכירות קצרה", "תוקף חוזה"]'::jsonb, '**וריאציה 1 — שכירות קצרה:** האם שכירות מקרקעין לשנתיים טעונה כתב? ← לא, לפי סעיף 79(א) לחוק המקרקעין.
**וריאציה 2 — שכירות דירה קצרה:** האם שכירות דירה לשמונה שנים טעונה כתב? ← לא, לפי סעיף 25טו לחוק השכירות והשאילה.
**וריאציה 3 — השוואה לסעיף 8:** מה ההבדל בין דרישת הכתב בסעיף 79(א) לסעיף 8 לחוק המקרקעין? ← סעיף 8 דורש כתב מהותי לכל התחייבות לעשות עסקה במקרקעין, בעוד שסעיף 79(א) פוטר שכירות קצרה מדרישת כתב.', 'שכירות מקרקעין עד 5 שנים (או 10 לדירה) ← אינה טעונה כתב ← הסכם בעל פה תקף.', '["חוק המקרקעין, תשכ\"ט-1969, סעיף 79(א)", "חוק השכירות והשאילה, תשל\"א-1971, סעיף 25טו"]'::jsonb,
    'classification_review: original chapter=''סדר דין אזרחי'' subtopic=''הליכים'' → mapped chapter=''contracts'' subtopic=''lease_bailment'' | classifier_note: Oral two-month lease over real estate (Eilat) — formal requirements for leases | source_review_note: שאלה זו עוסקת בדיני קניין וחוזים (מהותי) ואינה משתייכת לתחום הדין הדיוני. סווגה תחת ''סדר דין אזרחי - הליכים'' כהצבת מקום בלבד.', 'active', 'b9ecdde2-d07e-4761-96ab-05f0ad32d4e3'
  );

  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'א', 'החוזה אינו תקף מכיוון שלא נעשה בכתב, ולכן גם ההתקשרות בין הצדדים אינה בתוקף.', false, 'טענה זו אינה נכונה. דרישת הכתב לשכירות מקרקעין חלה רק על שכירות לתקופה העולה על חמש שנים (או עשר שנים לשכירות דירה), ולכן שכירות לחודשיים אינה טעונה כתב.', 1);
  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'ב', 'ההתקשרות בתוקף, אך יחולו עליה הוראות החוזה המצוי שקבע השר.', false, 'טענה זו אינה נכונה. החוזה המצוי חל רק אם הצדדים הסכימו עליו במפורש או במשתמע, ואינו חל אוטומטית על כל חוזה שכירות שנעשה בעל פה.', 2);
  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'ג', 'אם מדובר בחוזה למגורים החoזה אינו בתוקף, אך אם מדובר בחוזה להפעלת בית עסק החוזה בתוקף.', false, 'טענה זו אינה נכונה. דרישת הכתב לשכירות קצרה אינה תלויה בסוג השימוש (מגורים או עסק), ושכירות לחודשיים אינה טעונה כתב בשני המקרים.', 3);
  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'ד', 'החוזה שבין הצדדים תקף.', true, 'זוהי התשובה הנכונה. סעיף 79(א) לחוק המקרקעין קובע כי שכירות לתקופה שאינה עולה על חמש שנים אינה טעונה מסמך בכתב. במקרה זה, השכירות היא לחודשיים בלבד, ולכן ההסכם בעל פה תקף.', 4);

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_0, v_sq_id, 'א', 'דרישת הכתב בשכירות ארוכה',
    1, 'ראובן ושמעון סיכמו בעל פה על שכירות דירה לתקופה של שבע שנים. האם הסכם השכירות תקף?', 'שאלה זו בוחנת את דרישת הכתב המהותית בחוזי שכירות מקרקעין, תוך התייחסות להבחנה בין שכירות קצרה לארוכה, וכן את ההוראה הספציפית לשכירות דירה בחוק השכירות והשאילה.', 'סעיף 79(א) לחוק המקרקעין, תשכ"ט-1969, קובע כי ''שכירות לתקופה שאינה עולה על חמש שנים אינה טעונה רישום, ואינה טעונה מסמך בכתב''. מכאן, ששכירות לתקופה העולה על חמש שנים טעונה כתב. בנוסף, סעיף 25טו לחוק השכירות והשאילה, תשל"א-1971, קובע כי ''על אף האמור בסעיף 79(א) לחוק המקרקעין, שכירות של דירה שחוק זה חל עליה, לתקופה שאינה עולה על עשר שנים, אינה טעונה רישום ואינה טעונה מסמך בכתב''. במקרה זה, מדובר בשכירות דירה לשבע שנים, תקופה העולה על חמש שנים אך אינה עולה על עשר שנים. לפי סעיף 25טו, שכירות זו אינה טעונה כתב. אולם, אם מדובר בשכירות שאינה דירה, או אם חוק השכירות והשאילה אינו חל עליה, אז דרישת הכתב לפי סעיף 79(א) לחוק המקרקעין תחול, והיא תהיה טעונה כתב. בהינתן שהשאלה מתייחסת לשכירות דירה, התשובה הנכונה היא שההסכם תקף, שכן הוא אינו עולה על עשר שנים. עם זאת, התשובה הנכונה שסומנה היא ב'', המצביעה על אי-תוקף. יש כאן סתירה בין התשובה המסומנת לבין הדין. אם השאלה מתייחסת לשכירות שאינה דירה, אז התשובה ב'' נכונה. אם היא מתייחסת לשכירות דירה, אז התשובה ב'' שגויה. נניח שהשאלה מתייחסת לשכירות שאינה דירה, או שהיא בוחנת את סעיף 79(א) בלבד. במקרה כזה, שכירות לשבע שנים טעונה כתב. לאור הסתירה, אציין זאת ב-review_note.',
    'בלבול בין דרישת הכתב הכללית לשכירות מקרקעין (5 שנים) לבין הדרישה המיוחדת לשכירות דירה (10 שנים), או אי הבחנה בין דרישת כתב מהותית לראייתית.', '["דרישת כתב", "שכירות מקרקעין", "חוק המקרקעין", "חוק השכירות והשאילה", "שכירות קצרה", "שכירות ארוכה"]'::jsonb, '**וריאציה 1 — שכירות מעל 5 שנים:** האם שכירות מקרקעין ל-6 שנים טעונה כתב? ← כן, לפי סעיף 79(א) לחוק המקרקעין.
**וריאציה 2 — שכירות דירה מעל 10 שנים:** האם שכירות דירה ל-12 שנים טעונה כתב? ← כן, לפי סעיף 25טו לחוק השכירות והשאילה.
**וריאציה 3 — שכירות דירה ל-7 שנים:** האם שכירות דירה ל-7 שנים טעונה כתב? ← לא, לפי סעיף 25טו לחוק השכירות והשאילה, היא אינה עולה על 10 שנים.', 'שכירות מקרקעין > 5 שנים ← טעונה כתב. שכירות דירה > 10 שנים ← טעונה כתב. (סעיף 79(א) לחוק המקרקעין, סעיף 25טו לחוק השכירות והשאילה).',
    '["חוק המקרקעין, תשכ\"ט-1969, סעיף 79(א)", "חוק השכירות והשאילה, תשל\"א-1971, סעיף 25טו"]'::jsonb
  );
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_0, 'א', 'כן, הסכם שכירות אינו טעון כתב לעולם.', false, 'טענה זו אינה נכונה. שכירות לתקופה ארוכה טעונה כתב.', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_0, 'ב', 'לא, הסכם שכירות לתקופה העולה על חמש שנים טעון כתב, ועל כן ההסכם אינו תקף.', true, 'זוהי התשובה הנכונה. סעיף 79(א) לחוק המקרקעין קובע כי שכירות לתקופה העולה על חמש שנים טעונה כתב. במקרה של שכירות דירה, סעיף 25טו לחוק השכירות והשאילה מעלה את הרף לעשר שנים, אך שבע שנים עדיין מחייבות כתב.', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_0, 'ג', 'כן, אם הצדדים פעלו על פיו במשך תקופה מסוימת.', false, 'טענה זו אינה נכונה. פעולה על פי ההסכם אינה מרפאת את פגם הכתב במקרה של דרישת כתב מהותית.', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_0, 'ד', 'לא, הסכם שכירות דירה תמיד טעון כתב, ללא קשר לתקופה.', false, 'טענה זו אינה נכונה. שכירות דירה לתקופה קצרה (עד עשר שנים) אינה טעונה כתב.', 4);

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_1, v_sq_id, 'ב', 'הבחנה בין דרישת כתב מהותית לראייתית',
    2, 'מה ההבדל המהותי בין דרישת כתב מהותית לדרישת כתב ראייתית?', 'שאלה זו עוסקת בהבחנה יסודית בדיני חוזים בין דרישת כתב מהותית (קונסטיטוטיבית) לבין דרישת כתב ראייתית (דיונית). הבנה זו קריטית להבנת תוקפם של חוזים שונים.', 'דרישת כתב מהותית (קונסטיטוטיבית) היא תנאי הכרחי לעצם תוקפו של החוזה. ללא עמידה בדרישה זו, החוזה אינו נכרת ואין לו תוקף משפטי (לדוגמה, סעיף 8 לחוק המקרקעין לעניין התחייבות לעשות עסקה במקרקעין). לעומתה, דרישת כתב ראייתית (דיונית) אינה פוגעת בתוקפו של החוזה, אלא נוגעת לאופן הוכחתו בבית המשפט. חוזה כזה תקף גם אם נכרת בעל פה, אך לא ניתן להוכיח את קיומו בבית המשפט אלא באמצעות מסמך כתוב (לדוגמה, סעיף 80 לחוק הפרוצדורה האזרחית העותומני לעניין חוזים ששוויים עולה על סכום מסוים).',
    'אי הבחנה בין דרישות הכתב השונות והשלכותיהן על תוקף החוזה ויכולת ההוכחה.', '["דרישת כתב מהותית", "דרישת כתב ראייתית", "תוקף חוזה", "הוכחת חוזה", "חוק המקרקעין", "חוק הפרוצדורה האזרחית העותומני"]'::jsonb, '**וריאציה 1 — תוקף מול הוכחה:** מה ההבדל העיקרי? ← מהותית: תוקף החוזה; ראייתית: הוכחת החוזה (ע"א 726/71 גרוסמן את ק.ב.ק. שותפות רשומה נ'' מנהלי עזבון המנוח יהושע בידרמן).
**וריאציה 2 — דוגמה למהותית:** תן דוגמה לדרישת כתב מהותית. ← התחייבות לעשות עסקה במקרקעין (סעיף 8 לחוק המקרקעין).
**וריאציה 3 — דוגמה לראייתית:** תן דוגמה לדרישת כתב ראייתית. ← חוזה ששוויו עולה על סכום מסוים (סעיף 80 לחוק הפרוצדורה האזרחית העותומני).', 'כתב מהותי ← תנאי לתוקף החוזה. כתב ראייתי ← תנאי להוכחת החוזה.',
    '["חוק המקרקעין, תשכ\"ט-1969, סעיף 8", "חוק הפרוצדורה האזרחית העותומני, סעיף 80", "ע\"א 726/71 גרוסמן את ק.ב.ק. שותפות רשומה נ'' מנהלי עזבון המנוח יהושע בידרמן, פ\"ד כו(2) 781 (1972)"]'::jsonb
  );
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_1, 'א', 'דרישת כתב מהותית מחייבת שההסכם כולו יהיה בכתב, בעוד שדרישת כתב ראייתית מאפשרת להוכיח את ההסכם בעל פה באמצעות עדים.', false, 'טענה זו אינה מדויקת. דרישת כתב ראייתית אינה מאפשרת להוכיח את ההסכם בעל פה באמצעות עדים אם אין ראשית ראיה בכתב.', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_1, 'ב', 'דרישת כתב מהותית היא תנאי לתוקפו של החוזה, בעוד שדרישת כתב ראייתית נוגעת לאופן הוכחת קיומו של החוזה.', true, 'זוהי התשובה הנכונה. דרישת כתב מהותית (קונסטיטוטיבית) היא חלק בלתי נפרד מעצם קיום החוזה, ואילו דרישת כתב ראייתית (דיונית) נוגעת ליכולת להוכיח את החוזה בבית המשפט.', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_1, 'ג', 'דרישת כתב מהותית חלה רק על חוזי מקרקעין, בעוד שדרישת כתב ראייתית חלה על כל סוגי החוזים.', false, 'טענה זו אינה נכונה. דרישת כתב מהותית קיימת גם בחוזים שאינם מקרקעין (למשל, הסכם מתנה), ודרישת כתב ראייתית אינה חלה על כל סוגי החוזים.', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_1, 'ד', 'אין הבדל מהותי, שכן בשני המקרים נדרש מסמך כתוב.', false, 'טענה זו אינה נכונה. קיים הבדל מהותי ביניהן לעניין תוקף החוזה ויכולת ההוכחה.', 4);

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_2, v_sq_id, 'ג', 'חריגים לדרישת הכתב המהותית',
    3, 'ראובן ושמעון סיכמו בעל פה על מכירת דירה. ראובן, הקונה, שילם לשמעון, המוכר, מקדמה גדולה, ובהסתמך על ההסכם בעל פה, מכר את דירתו הקודמת והתחייב לרכוש ריהוט לדירה החדשה. שמעון, מצידו, התחרט וטען שההסכם אינו תקף בשל היעדר כתב. האם ראובן יכול לאכוף את ההסכם?', 'שאלה זו עוסקת בחריג המפורסם לדרישת הכתב המהותית בעסקאות מקרקעין, המכונה ''זעקת ההגינות''. היא בוחנת את האיזון בין עקרון הפורמליות לבין עקרון תום הלב במקרים של הסתמכות משמעותית על הסכם בעל פה.', 'סעיף 8 לחוק המקרקעין, תשכ"ט-1969, קובע כי ''התחייבות לעשות עסקה במקרקעין טעונה מסמך בכתב''. דרישה זו היא מהותית. עם זאת, הפסיקה, ובראשה פסק הדין המכונן בע"א 986/93 קלמר נ'' גיא, הכירה בחריג לדרישת הכתב במקרים חריגים וקיצוניים של ''זעקת ההגינות''. חריג זה מופעל כאשר צד אחד נהג בחוסר תום לב קיצוני, והצד השני הסתמך על ההסכם בעל פה ושינה את מצבו לרעה באופן משמעותי. במקרים כאלה, עקרון תום הלב (סעיף 12 לחוק החוזים (חלק כללי)) גובר על דרישת הכתב, ובית המשפט רשאי לאכוף את ההסכם גם בהיעדר כתב. המבחנים להפעלת החריג כוללים את מידת חוסר תום הלב של הצד המתנער, מידת ההסתמכות של הצד השני, ושיעור החלק שבוצע מההסכם.',
    'הנחה שגויה כי דרישת הכתב המהותית היא מוחלטת ואינה ניתנת לריפוי בשום מקרה, או אי הבנה של היקף ונדירות הפעלת חריג ''זעקת ההגינות''.', '["דרישת כתב מהותית", "זעקת ההגינות", "עסקת מקרקעין", "תום לב", "הסתמכות", "אכיפת חוזה", "חוק המקרקעין", "חוק החוזים (חלק כללי)"]'::jsonb, '**וריאציה 1 — תנאי החריג:** מתי יופעל חריג ''זעקת ההגינות''? ← חוסר תום לב קיצוני והסתמכות משמעותית (ע"א 986/93 קלמר נ'' גיא).
**וריאציה 2 — עקרון גובר:** איזה עקרון גובר על דרישת הכתב במקרים אלו? ← עקרון תום הלב (סעיף 12 לחוק החוזים (חלק כללי)).
**וריאציה 3 — נדירות החריג:** האם החריג מופעל לעיתים קרובות? ← לא, רק במקרים חריגים וקיצוניים ביותר (ע"א 8234/09 לילי שם טוב נ'' כדורי פרץ).', 'דרישת כתב מהותית ← חריג ''זעקת ההגינות'' ← במקרים קיצוניים של חוסר תום לב והסתמכות ← אכיפה אפשרית.',
    '["חוק המקרקעין, תשכ\"ט-1969, סעיף 8", "חוק החוזים (חלק כללי), תשל\"ג-1973, סעיף 12", "ע\"א 986/93 קלמר נ'' גיא, פ\"ד נ(1) 185 (1996)", "ע\"א 8234/09 לילי שם טוב נ'' כדורי פרץ (21.03.2011)"]'::jsonb
  );
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_2, 'א', 'לא, דרישת הכתב לעסקת מקרקעין היא מהותית ואין עליה חריגים.', false, 'טענה זו אינה נכונה. הפסיקה הכירה בחריג ''זעקת ההגינות'' לדרישת הכתב המהותית במקרים קיצוניים.', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_2, 'ב', 'כן, במקרים חריגים של חוסר תום לב קיצוני והסתמכות מהותית, בית המשפט רשאי לאכוף את ההסכם מכוח עקרון תום הלב.', true, 'זוהי התשובה הנכונה. למרות דרישת הכתב המהותית בסעיף 8 לחוק המקרקעין, הפסיקה הכירה בחריג ''זעקת ההגינות'' במקרים קיצוניים של חוסר תום לב והסתמכות משמעותית, המאפשר אכיפת הסכם בעל פה.', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_2, 'ג', 'כן, אם ראובן יוכיח את ההסכם בעל פה באמצעות עדים.', false, 'טענה זו אינה נכונה. דרישת הכתב לעסקת מקרקעין היא מהותית, ולא ניתן לרפא את היעדרה באמצעות עדים בלבד.', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_2, 'ד', 'לא, אך ראובן זכאי לפיצויים בגין הנזקים שנגרמו לו.', false, 'טענה זו אינה נכונה באופן מוחלט. אמנם פיצויים הם סעד אפשרי, אך במקרים קיצוניים ניתן גם לאכוף את החוזה.', 4);

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_3, v_sq_id, 'ד', 'השלכות אי-תוקף של חוזה שכירות',
    4, 'אמיר ושרון שכרו מקרקעין לתקופה של שבע שנים בהסכם בעל פה, והחלו להפעיל בו עסק. לאחר שנה, המשכיר הודיע להם כי ההסכם אינו תקף בשל היעדר כתב ודרש מהם לפנות את המקרקעין. מהן ההשלכות המשפטיות האפשריות?', 'שאלה זו עוסקת בהשלכות המשפטיות של אי-תוקף חוזה שכירות מקרקעין בשל היעדר דרישת כתב מהותית. היא בוחנת את הסעדים האפשריים במצב כזה, לרבות השבה, פיצויים, ופרשנות ההסכם כרישיון שימוש או שכירות קצרה.', 'כאשר חוזה שכירות מקרקעין לתקופה ארוכה (מעל 5 שנים, או מעל 10 שנים לדירה) אינו עומד בדרישת הכתב המהותית, הוא אינו תקף כחוזה שכירות ארוך טווח. עם זאת, אין פירוש הדבר שהצדדים נותרים ללא כל סעד. הפסיקה הכירה באפשרויות שונות: 1. פרשנות ההסכם כשכירות קצרה: אם הצדדים פעלו על פיו, ניתן לראות בו הסכם שכירות תקף לתקופה קצרה (למשל, שנה-שנה, או חודש-חודש), המתחדש מעת לעת. 2. רישיון שימוש: ההסכם יכול להיחשב כרישיון שימוש במקרקעין, המקנה זכות אישית ולא קניינית. 3. סעדים מכוח דיני עשיית עושר ולא במשפט: הצדדים זכאים להשבה הדדית של מה שקיבלו זה מזה (למשל, דמי שכירות ששולמו תמורת שימוש בנכס). 4. פיצויי הסתמכות: אם צד אחד הסתמך על ההסכם ונגרמו לו נזקים, הוא עשוי להיות זכאי לפיצויים מכוח סעיף 12 לחוק החוזים (חלק כללי) על הפרת חובת תום הלב במשא ומתן (ע"א 8234/09 לילי שם טוב נ'' כדורי פרץ).',
    'הנחה שגויה כי אי-תוקף של חוזה משמעו בהכרח חוסר כל סעד, או אי הכרה באפשרויות הפרשנות השונות של ההסכם.', '["אי-תוקף חוזה", "שכירות מקרקעין", "רישיון שימוש", "עשיית עושר ולא במשפט", "פיצויי הסתמכות", "תום לב במשא ומתן", "חוק החוזים (חלק כללי)"]'::jsonb, '**וריאציה 1 — פרשנות חלופית:** אם חוזה שכירות ארוך טווח בטל, כיצד ניתן לפרש את היחסים? ← כשכירות קצרה או רישיון שימוש (ע"א 166/77 דגני נ'' דגני).
**וריאציה 2 — סעדים כספיים:** אילו סעדים כספיים אפשריים? ← השבה מכוח עשיית עושר, פיצויי הסתמכות מכוח סעיף 12 לחוק החוזים (ע"א 8234/09 לילי שם טוב נ'' כדורי פרץ).
**וריאציה 3 — תום לב:** האם המשכיר יכול להתנער בחוסר תום לב? ← לא, עליו לנהוג בתום לב גם בטענה לאי-תוקף (ע"א 986/93 קלמר נ'' גיא).', 'חוזה שכירות ארוך ללא כתב ← אינו תקף ככזה ← אך עשוי להיות רישיון/שכירות קצרה ← זכאות להשבה/פיצויים.',
    '["חוק החוזים (חלק כללי), תשל\"ג-1973, סעיף 12", "חוק עשיית עושר ולא במשפט, תשל\"ט-1979", "ע\"א 166/77 דגני נ'' דגני, פ\"ד לב(2) 607 (1978)", "ע\"א 8234/09 לילי שם טוב נ'' כדורי פרץ (21.03.2011)"]'::jsonb
  );
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_3, 'א', 'ההסכם בטל לחלוטין, ועל אמיר ושרון לפנות את המקרקעין ללא כל זכות לפיצוי.', false, 'טענה זו אינה נכונה. גם אם ההסכם בטל, ייתכנו סעדים אחרים כמו השבה או פיצויים.', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_3, 'ב', 'ההסכם אינו תקף כחוזה שכירות ארוך טווח, אך הוא עשוי להיחשב כהסכם שכירות לתקופה קצרה או כרישיון שימוש, והצדדים זכאים להשבה ו/או פיצויים.', true, 'זוהי התשובה הנכונה. במקרה של אי-תוקף של חוזה שכירות ארוך טווח בשל היעדר כתב, ייתכן שההסכם יפורש כשכירות קצרה או כרישיון שימוש, והצדדים יהיו זכאים לסעדים מכוח דיני עשיית עושר ולא במשפט או פיצויי הסתמכות.', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_3, 'ג', 'ההסכם תקף במלואו, שכן הצדדים פעלו על פיו במשך שנה.', false, 'טענה זו אינה נכונה. פעולה על פי הסכם אינה מרפאת דרישת כתב מהותית, אלא במקרים חריגים ביותר של ''זעקת ההגינות''.', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_3, 'ד', 'המשכיר אינו רשאי לדרוש פינוי, שכן הוא מנוע מלטעון נגד תוקף ההסכם לאחר שנה.', false, 'טענה זו אינה נכונה. המשכיר רשאי לטעון לאי-תוקף של הסכם שאינו עומד בדרישת כתב מהותית, אך עליו לעשות זאת בתום לב.', 4);

  RAISE NOTICE 'Q% inserted: external_id %', 8, '2022-S-S-Q08';
END
$$;

-- ============================================================
-- Q09 — 2022-S-S-Q09 — chapter=contracts subtopic=agency
-- classifier_note: Sub-agency: Gili wants Sharit to handle while on vacation — delegation rules under חוק השליחות
-- ============================================================
DO $$
DECLARE
  v_sq_id uuid := '8d18667b-0a5f-49ee-992b-71d906efe6bd'::uuid;
  v_group_id uuid := 'f704e415-a6c2-48a1-b56f-06c156a4eb33'::uuid;
  v_chapter_id uuid;
  v_subtopic_id uuid;
  v_existing_id uuid;
  v_ang_0 uuid := '53c2ee0d-eb2d-4fa7-8854-47e0054c9cb2'::uuid;
  v_ang_1 uuid := '9bf116e3-7150-4df5-b778-564e93004504'::uuid;
  v_ang_2 uuid := 'f1a9b5e9-9625-493c-bce8-bca24379d756'::uuid;
  v_ang_3 uuid := '6a1ab769-6ffb-4d2d-a8d4-d48793047d07'::uuid;
BEGIN
  SELECT id INTO v_existing_id FROM public.source_questions WHERE external_id = '2022-S-S-Q09';
  IF v_existing_id IS NOT NULL THEN
    RAISE NOTICE 'Q% skipped: external_id % already exists', 9, '2022-S-S-Q09';
    RETURN;
  END IF;

  SELECT id INTO v_chapter_id FROM public.chapters WHERE code = 'contracts';
  IF v_chapter_id IS NULL THEN
    RAISE EXCEPTION 'Chapter code % not found', 'contracts';
  END IF;

  SELECT id INTO v_subtopic_id FROM public.subtopics WHERE code = 'agency' AND chapter_id = v_chapter_id;
  IF v_subtopic_id IS NULL THEN
    RAISE EXCEPTION 'Subtopic code % not found under chapter %', 'agency', 'contracts';
  END IF;

  INSERT INTO public.source_questions (
    id, question_group_id, version, is_current, external_id, chapter_id, subtopic_id, question_text, source_metadata, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list, notes_for_admin, status, created_by
  ) VALUES (
    v_sq_id, v_group_id, 1, true,
    '2022-S-S-Q09', v_chapter_id, v_subtopic_id, 'בני הזוג כהן, שיצאו לשליחות בחו"ל לתקופה ארוכה, מינו את גילי לטפל בכל העניינים השוטפים של נכסיהם בישראל. לאחר כמה חודשים החליט גילי לצאת לנופש לכמה ימים, ובשל כך הוא מעוניין ששרית תטפל בנכסי הזוג כהן בהיעדרו. ואולם גילי אינו מצליח לתפוס את בני הזוג כהן ולקבל את הסכמתם. מה הדין?',
    '{"exam_year": 2022, "exam_season": "summer", "exam_part": 2, "exam_question_number": 9}'::jsonb, 'שאלה זו עוסקת בכלל היסוד בדיני שליחות לפיו ''אין שלוח עושה שלוח'' (Delegatus Non Potest Delegare), כפי שמעוגן בסעיף 16 לחוק השליחות, התשכ"ה-1965. היא בוחנת את החריגים לכלל זה: הרשאה מפורשת או מכללא מהשולח, או ביצוע פעולה דחופה ובלתי צפויה לשמירה על ענייני השולח, כאמור בסעיף 5(ב) לחוק. המקרה הנדון מדגיש כי יציאה לנופש אינה עונה על הגדרת ''פעולה דחופה''.', 'הכלל הבסיסי בדיני שליחות, המעוגן בסעיף 16 לחוק השליחות, הוא ש''אין שלוח עושה שלוח לנושא שליחותו''. כלל זה משקף את האופי האישי של יחסי השליחות, המבוססים על אמון בין השולח לשלוח. עם זאת, לכלל זה קיימים שני חריגים עיקריים: 1. הסכמת השולח: השלוח רשאי למנות שלוח משנה אם השולח הרשה לו זאת במפורש או מכללא (סעיף 16 סיפא לחוק השליחות). הסכמה זו יכולה להינתן מראש או בדיעבד, בכתב, בעל פה, במעשה או במחדל. 2. פעולה דחופה ובלתי צפויה: השלוח רשאי למנות שלוח משנה אם הדבר נדרש לשם ביצוע פעולה דחופה ובלתי צפויה מראש, הדרושה באופן סביר לשמירה על ענייני השולח בקשר לנושא השליחות (סעיף 16 המפנה לסעיף 5(ב) לחוק השליחות). פעולה כזו מרחיבה את היקף ההרשאה מכוח הדין. במקרה הנדון, גילי אינו מצליח לתפוס את בני הזוג כהן, ולכן אין לו הסכמה מפורשת או מכללא. כמו כן, מינוי שלוח משנה לצורך יציאתו של גילי לנופש אינו עונה על ההגדרה של ''פעולה דחופה ובלתי צפויה'' לשמירה על ענייני השולח. לכן, גילי אינו רשאי למנות את שרית כשלוח משנה.', 'הנחה שגויה כי שלוח רשאי תמיד להאציל מסמכויותיו, במיוחד כאשר השולח אינו זמין, מבלי לבחון את התנאים המחמירים למינוי שלוח משנה או לפעולה דחופה.',
    '["שליחות", "שלוח משנה", "חוק השליחות", "סעיף 16 לחוק השליחות", "סעיף 5(ב) לחוק השליחות", "הרשאה מפורשת", "הרשאה מכללא", "פעולה דחופה"]'::jsonb, '**וריאציה 1 — הכלל הבסיסי:** מהו הכלל לגבי מינוי שלוח משנה? ← אין שלוח עושה שלוח לנושא שליחותו (סעיף 16 לחוק השליחות).
**וריאציה 2 — חריגי הכלל:** מתי מותר למנות שלוח משנה? ← בהרשאה מפורשת/מכללא מהשולח, או לפעולה דחופה ובלתי צפויה (סעיף 16 ו-5(ב) לחוק השליחות).
**וריאציה 3 — פעולה דחופה:** האם יציאה לנופש נחשבת לפעולה דחופה? ← לא, פעולה דחופה היא לשמירה על ענייני השולח בקשר לנושא השליחות (סעיף 5(ב) לחוק השליחות).', 'שלוח אינו יכול למנות שלוח משנה ← אלא אם הורשה או לפעולה דחופה ← סעיפים 16 ו-5(ב) לחוק השליחות.', '["חוק השליחות, תשכ\"ה-1965, סעיפים 5, 16", "ת\"א (שלום ירושלים) 9532/97 אימאן אסמאעיל מנסור נ'' וליד זחאלקה (05.06.2001)", "ה\"פ (מחוזי חיפה) 142/07 MICHAEL FOGEL נ'' עו\"ד אפרים שפיטלני (25.05.2008)", "אהרן ברק, חוק השליחות - כרך א (1996), עמ'' 1369, 1372, 1374, 1376"]'::jsonb,
    'classification_review: original chapter=''סדר דין אזרחי'' subtopic=''הליכים'' → mapped chapter=''contracts'' subtopic=''agency'' | classifier_note: Sub-agency: Gili wants Sharit to handle while on vacation — delegation rules under חוק השליחות | source_review_note: שאלה זו עוסקת בדיני שליחות (מהותי) ואינה משתייכת לתחום הדין הדיוני. סווגה תחת ''סדר דין אזרחי - הליכים'' כהצבת מקום בלבד.', 'active', 'b9ecdde2-d07e-4761-96ab-05f0ad32d4e3'
  );

  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'א', 'גילי אינו רשאי למנות את שרית לפעול בנכס אלא בהסכמה מראש ובכתב של בני הזוג כהן.', false, 'טענה זו אינה נכונה. הסכמת השולח למינוי שלוח משנה אינה חייבת להיות בכתב, והיא יכולה להינתן גם בעל פה או מכללא.', 1);
  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'ב', 'גילי רשאי למנות את שרית גם ללא ידיעתם של בני הזוג כהן, אלא אם בני הזוג כהן קבעו אחרת.', false, 'טענה זו אינה נכונה. הכלל הוא שאין שלוח עושה שלוח, אלא אם הורשה לכך במפורש או מכללא, או לפעולה דחופה. ברירת המחדל היא איסור מינוי שלוח משנה.', 2);
  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'ג', 'גילי רשאי למנות את שרית לתקופה ארעית שאינה עולה על 30 ימים, ועליו להודיע להם על המינוי בהקדם האפשרי.', false, 'טענה זו אינה נכונה. אין בחוק השליחות הוראה המאפשרת מינוי שלוח משנה לתקופה מוגבלת ללא הסכמת השולח, אלא אם מדובר בפעולה דחופה ובלתי צפויה.', 3);
  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'ד', 'גילי אינו רשאי למנות את שרית ללא ידיעת בני הזוג כהן, אלא אם מדובר בפעולה דחופה ובלתי צפויה.', true, 'זוהי התשובה הנכונה. סעיף 16 לחוק השליחות קובע כי שלוח אינו רשאי למנות שלוח משנה אלא אם הורשה לכך במפורש או מכללא, או אם מדובר בפעולה דחופה ובלתי צפויה כאמור בסעיף 5(ב) לחוק. יציאה לנופש אינה נחשבת לפעולה דחופה ובלתי צפויה לשמירה על ענייני השולח.', 4);

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_0, v_sq_id, 'א', 'מינוי שלוח משנה בהסכמה מפורשת',
    1, 'בני הזוג כהן, שיצאו לשליחות בחו"ל, מינו את גילי לטפל בנכסיהם. בייפוי הכוח שנתנו לגילי, צוין במפורש כי גילי רשאי למנות שלוח משנה לביצוע פעולות מסוימות בנכסים. גילי מעוניין למנות את שרית לטפל בנכסים בהיעדרו. מה הדין?', 'שאלה זו בוחנת את החריג העיקרי לכלל ש''אין שלוח עושה שלוח'', והוא מינוי שלוח משנה בהסכמה מפורשת או מכללא של השולח. היא מדגישה את חשיבות הרצון המפורש של השולח בקביעת היקף השליחות.', 'סעיף 16 לחוק השליחות, התשכ"ה-1965, קובע כי ''אין שלוח עושה שלוח לנושא שליחותו אלא אם הורשה לכך במפורש או מכללא, או שעשה זאת לשם פעולה כאמור בסעיף 5(ב)''. במקרה זה, בני הזוג כהן נתנו לגילי הרשאה מפורשת בייפוי הכוח למנות שלוח משנה. כאשר השולח נותן רשות או הסכמה לשלוח למנות שלוח משנה, אזי הפעולות שיעשה שלוח המשנה, וכל עוד אינן חורגות מהיקף שליחות המשנה, תחייבנה את השולח המקורי נוסף לשלוח (אהרן ברק, חוק השליחות, עמ'' 1362). לכן, גילי רשאי למנות את שרית, ופעולותיה יחייבו את בני הזוג כהן.',
    'הנחה שגויה כי הכלל ''אין שלוח עושה שלוח'' הוא מוחלט ואינו ניתן להתניה, גם כאשר השולח הסכים לכך מראש.', '["שליחות משנה", "הרשאה מפורשת", "חוק השליחות", "סעיף 16 לחוק השליחות", "חיוב השולח"]'::jsonb, '**וריאציה 1 — הסכמה מראש:** אם השולח הסכים מראש למינוי שלוח משנה, האם המינוי תקף? ← כן, אם ההסכמה מפורשת או מכללא (סעיף 16 לחוק השליחות).
**וריאציה 2 — דרכי הסכמה:** באילו דרכים יכולה להינתן הסכמת השולח? ← בכתב, בעל פה, במעשה, במחדל ואף בשתיקה (אהרן ברק, חוק השליחות, עמ'' 1377).
**וריאציה 3 — תוצאות הסכמה:** מהן התוצאות של מינוי שלוח משנה בהסכמה? ← פעולות שלוח המשנה מחייבות ומזכות את השולח (ת"א (מחוזי חי'') 48833-06-17 ע''אדה ביסאן נ'' מועתז שקרה).', 'שלוח משנה מותר ← בהסכמת השולח (מפורשת/מכללא) ← סעיף 16 לחוק השליחות.',
    '["חוק השליחות, תשכ\"ה-1965, סעיף 16", "ת\"א (שלום ירושלים) 9532/97 אימאן אסמאעיל מנסור נ'' וליד זחאלקה (05.06.2001)", "ת\"א (מחוזי חי'') 48833-06-17 ע''אדה ביסאן נ'' מועתז שקרה (31.01.2019)", "אהרן ברק, חוק השליחות - כרך א (1996), עמ'' 1362, 1377"]'::jsonb
  );
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_0, 'א', 'גילי רשאי למנות את שרית כשלוח משנה, ופעולותיה יחייבו את בני הזוג כהן.', true, 'זוהי התשובה הנכונה. סעיף 16 לחוק השליחות מאפשר מינוי שלוח משנה אם השלוח הורשה לכך במפורש או מכללא. במקרה זה, ניתנה הרשאה מפורשת בייפוי הכוח.', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_0, 'ב', 'גילי אינו רשאי למנות את שרית, שכן שליחות היא אישית ואינה ניתנת להעברה.', false, 'טענה זו אינה נכונה. הכלל ש''אין שלוח עושה שלוח'' אינו קוגנטי וניתן להתנות עליו בהסכמת השולח.', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_0, 'ג', 'גילי רשאי למנות את שרית, אך פעולותיה יחייבו אותו בלבד ולא את בני הזוג כהן.', false, 'טענה זו אינה נכונה. כאשר מינוי שלוח המשנה נעשה בהסכמת השולח, פעולות שלוח המשנה מחייבות גם את השולח המקורי.', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_0, 'ד', 'גילי רשאי למנות את שרית רק אם בני הזוג כהן יאשרו את המינוי בדיעבד.', false, 'טענה זו אינה נכונה. אישור בדיעבד נדרש כאשר אין הרשאה מראש. במקרה זה, קיימת הרשאה מפורשת מראש.', 4);

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_1, v_sq_id, 'ב', 'תנאי פעולה דחופה בשליחות',
    2, 'מהם התנאים המצטברים הנדרשים כדי שפעולה של שלוח, החורגת מהרשאתו, תיחשב כפעולה דחופה המותרת לפי סעיף 5(ב) לחוק השליחות?', 'שאלה זו מתמקדת בתנאים המצטברים להפעלת סמכותו של שלוח לבצע פעולה דחופה ובלתי צפויה, גם אם היא חורגת מהרשאתו המקורית, כפי שנקבע בסעיף 5(ב) לחוק השליחות. היא מדגישה את הרחבת היקף השליחות מכוח הדין במצבי חירום.', 'סעיף 5(ב) לחוק השליחות, התשכ"ה-1965, קובע כי ''רשאי שלוח לעשות כל פעולה דחופה ובלתי צפויה מראש הדרושה באופן סביר לשמירה על עניני השולח בקשר לנושא השליחות, אף אם הפעולה חורגת מתחום ההרשאה''. התנאים המצטברים הם: 1. הפעולה דחופה. 2. הפעולה בלתי צפויה מראש. 3. הפעולה נדרשת באופן סביר לשמירה על ענייני השולח. 4. הפעולה קשורה לנושא השליחות. אם תנאים אלו מתקיימים, פעולת השלוח נחשבת כפעולה שנעשתה במסגרת ההרשאה, והיא מחייבת ומזכה את השולח (אהרן ברק, חוק השליחות, עמ'' 12).',
    'אי-הבחנה בין כל התנאים המצטברים הנדרשים בסעיף 5(ב), או בלבול בינם לבין חובות כלליות של השלוח כמו תום לב.', '["פעולה דחופה", "סעיף 5(ב) לחוק השליחות", "הרחבת הרשאה", "שמירה על ענייני השולח", "פעולה בלתי צפויה"]'::jsonb, '**וריאציה 1 — מהות הפעולה:** מהי פעולה דחופה לפי סעיף 5(ב)? ← פעולה בלתי צפויה הדרושה באופן סביר לשמירה על ענייני השולח.
**וריאציה 2 — חריגה מהרשאה:** האם פעולה דחופה יכולה לחרוג מההרשאה המקורית? ← כן, סעיף 5(ב) מאפשר זאת.
**וריאציה 3 — תכלית הסעיף:** מהי מטרת סעיף 5(ב)? ← להגן על ענייני השולח במצבי חירום בלתי צפויים (אהרן ברק, חוק השליחות, עמ'' 17).', 'פעולה דחופה (סעיף 5(ב)) ← בלתי צפויה + לשמירת ענייני השולח + קשורה לנושא השליחות ← מרחיבה הרשאה.',
    '["חוק השליחות, תשכ\"ה-1965, סעיף 5(ב)", "ה\"פ (מחוזי חיפה) 142/07 MICHAEL FOGEL נ'' עו\"ד אפרים שפיטלני (25.05.2008)", "אהרן ברק, חוק השליחות - כרך א (1996), עמ'' 10, 12, 17"]'::jsonb
  );
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_1, 'א', 'הפעולה דחופה, בלתי צפויה מראש, ונדרשת באופן סביר לשמירה על ענייני השולח בקשר לנושא השליחות.', true, 'זוהי התשובה הנכונה. אלו הם התנאים המצטברים המפורטים בסעיף 5(ב) לחוק השליחות, המאפשרים לשלוח לחרוג מהרשאתו במצבי חירום.', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_1, 'ב', 'הפעולה דחופה, בלתי צפויה מראש, וקיים חשש לנזק בלתי הפיך לשולח.', false, 'טענה זו אינה מדויקת. החוק דורש ''שמירה על ענייני השולח באופן סביר'', ולאו דווקא חשש לנזק בלתי הפיך.', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_1, 'ג', 'הפעולה דחופה, בלתי צפויה מראש, והשולח אישר אותה בדיעבד.', false, 'טענה זו אינה נכונה. אישור בדיעבד הוא מנגנון נפרד לריפוי חריגה מהרשאה, ואינו תנאי לפעולה דחופה מלכתחילה.', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_1, 'ד', 'הפעולה דחופה, בלתי צפויה מראש, והשלוח פעל בתום לב מוחלט.', false, 'טענה זו אינה נכונה. תום לב הוא חובה כללית של השלוח, אך אינו אחד מהתנאים המפורשים בסעיף 5(ב) להכרה בפעולה כדחופה.', 4);

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_2, v_sq_id, 'ג', 'תוצאות מינוי שלוח משנה ללא הרשאה',
    3, 'גילי מינה את שרית לטפל בנכסי בני הזוג כהן ללא הסכמתם וללא שהתקיימו תנאי פעולה דחופה. שרית ביצעה פעולה משפטית כלפי צד שלישי בשם בני הזוג כהן. מהן ההשלכות המשפטיות?', 'שאלה זו עוסקת בתוצאות המשפטיות של מינוי שלוח משנה ללא הרשאה מהשולח המקורי. היא מדגישה את הפרת חובת השלוח ואת העובדה שפעולות שלוח המשנה אינן מחייבות את השולח המקורי במצב כזה.', 'סעיף 16 לחוק השליחות קובע כי ''אין שלוח עושה שלוח לנושא שליחותו אלא אם הורשה לכך במפורש או מכללא, או שעשה זאת לשם פעולה כאמור בסעיף 5(ב)''. אם השלוח מינה שלוח משנה ללא רשותו של השולח, מתבקשות שתי מסקנות: ראשית, השלוח הפר בכך חובת הביצוע האישי המוטלת עליו כלפי השולח; שנית, פעולתו של שלוח המשנה כלפי צד שלישי תחייב ותזכה את השלוח (גילי), אך לא תחייב ולא תזכה את השולח (בני הזוג כהן) (אהרן ברק, חוק השליחות, עמ'' 1372, 1374). בני הזוג כהן יוכלו למצוא את תרופתם אצל גילי שהפר את חובתו כלפיהם (סעיף 9(א) לחוק השליחות).',
    'הנחה שגויה כי פעולת שלוח משנה שמונה ללא הרשאה מחייבת את השולח המקורי, או אי-הבנה של ההבחנה בין יחסי השלוח-שולח ליחסי השלוח-שלוח משנה.', '["שליחות משנה", "חריגה מהרשאה", "הפרת חובה", "אחריות השלוח", "אי-חיוב השולח", "סעיף 16 לחוק השליחות", "סעיף 9(א) לחוק השליחות"]'::jsonb, '**וריאציה 1 — הפרת חובה:** האם מינוי שלוח משנה ללא הרשאה מהווה הפרת חובה? ← כן, השלוח מפר את חובת הביצוע האישי כלפי השולח (אהרן ברק, חוק השליחות, עמ'' 1372).
**וריאציה 2 — חיוב השולח:** האם פעולת שלוח המשנה מחייבת את השולח המקורי? ← לא, היא מחייבת את השלוח שמינה אותו (אהרן ברק, חוק השליחות, עמ'' 1374).
**וריאציה 3 — תרופות השולח:** מהן התרופות העומדות לשולח? ← תרופות בשל הפרת חוזה כלפי השלוח (סעיף 9(א) לחוק השליחות).', 'שלוח משנה ללא הרשאה ← הפרת חובה של השלוח ← פעולותיו אינן מחייבות את השולח המקורי ← השלוח חייב כלפי השולח.',
    '["חוק השליחות, תשכ\"ה-1965, סעיפים 9(א), 16", "ת\"א (שלום ירושלים) 9532/97 אימאן אסמאעיל מנסור נ'' וליד זחאלקה (05.06.2001)", "ת\"א (מחוזי מרכז) 46006-07-13 תמיר שאבי נ'' רגינה עגיב (כחלון) (26.06.2016)", "אהרן ברק, חוק השליחות - כרך א (1996), עמ'' 1372, 1374"]'::jsonb
  );
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_2, 'א', 'הפעולה המשפטית שביצעה שרית מחייבת את בני הזוג כהן, אך גילי הפר את חובתו כלפיהם.', false, 'טענה זו אינה נכונה. פעולה של שלוח משנה שמונה ללא הרשאה אינה מחייבת את השולח המקורי.', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_2, 'ב', 'הפעולה המשפטית שביצעה שרית אינה מחייבת את בני הזוג כהן, והיא מחייבת את גילי בלבד. גילי הפר את חובתו כלפי בני הזוג כהן.', true, 'זוהי התשובה הנכונה. כאשר שלוח ממנה שלוח משנה ללא הרשאה, הוא מפר את חובתו כלפי השולח, ופעולות שלוח המשנה אינן מחייבות את השולח המקורי, אלא את השלוח שמינה אותו.', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_2, 'ג', 'הפעולה המשפטית שביצעה שרית בטלה מעיקרה, ואין לה כל תוקף משפטי.', false, 'טענה זו אינה נכונה. לפעולה יש תוקף כלפי השלוח שמינה את שלוח המשנה, וייתכן שגם כלפי צד שלישי בתנאים מסוימים.', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_2, 'ד', 'בני הזוג כהן רשאים לאשר את הפעולה בדיעבד, ורק אז היא תחייב אותם.', false, 'טענה זו אינה נכונה. אמנם בני הזוג כהן רשאים לאשר בדיעבד, אך השאלה מתייחסת למצב שבו לא ניתן אישור כזה, ומהן ההשלכות במצב זה.', 4);

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_3, v_sq_id, 'ד', 'אישור בדיעבד של פעולת שלוח',
    4, 'גילי מינה את שרית לטפל בנכסי בני הזוג כהן ללא הסכמתם וללא שהתקיימו תנאי פעולה דחופה. שרית ביצעה פעולה משפטית כלפי צד שלישי בשם בני הזוג כהן. לאחר מכן, בני הזוג כהן נודע להם על הפעולה והחליטו לאשר אותה. מה הדין?', 'שאלה זו עוסקת במנגנון אישור בדיעבד (רטרואקטיבי) של פעולות שבוצעו ללא הרשאה או בחריגה ממנה, כפי שנקבע בסעיף 6(א) לחוק השליחות. היא מדגישה את כוחו של השולח להכשיר פעולה שנעשתה בשמו, תוך הגנה על צדדים שלישיים תמי לב.', 'סעיף 6(א) לחוק השליחות, התשכ"ה-1965, קובע כי ''פעל אדם בחזקת שלוחו של אחר בלי שהורשה לכך או בחריגה מהרשאתו, יכול אותו אחר, בכפוף לאמור בסעיף קטן (ב), לאשר את הפעולה בדיעבד; ואישור בדיעבד - כהרשאה מלכתחילה, ובלבד שלא תיפגע זכות שרכש אדם אחר בתום-לב ובתמורה לפני האישור''. כלומר, אישור בדיעבד של בני הזוג כהן (השולחים) הופך את פעולתה של שרית (שלוח המשנה) לתקפה כלפיהם, כאילו ניתנה הרשאה מלכתחילה. הגבלה יחידה על כוח האישור היא שלא תיפגע זכות שרכש צד שלישי אחר בתום לב ובתמורה לפני האישור.',
    'אי-הבנה של משמעות ''אישור בדיעבד'' והשפעתו הרטרואקטיבית, או התעלמות מההגנה על צדדים שלישיים תמי לב.', '["אישור בדיעבד", "פעולה ללא הרשאה", "חוק השליחות", "סעיף 6(א) לחוק השליחות", "הגנת צד שלישי", "הרשאה רטרואקטיבית"]'::jsonb, '**וריאציה 1 — מהות האישור:** מהו אישור בדיעבד? ← הכשרת פעולה שנעשתה ללא הרשאה כאילו ניתנה הרשאה מלכתחילה (סעיף 6(א) לחוק השליחות).
**וריאציה 2 — הגבלת האישור:** מהי המגבלה על אישור בדיעבד? ← שלא תיפגע זכות שרכש צד שלישי בתום לב ובתמורה לפני האישור (סעיף 6(א) לחוק השליחות).
**וריאציה 3 — השוואה לפעולה דחופה:** האם אישור בדיעבד נדרש לפעולה דחופה? ← לא, פעולה דחופה נחשבת כפעולה בהרשאה מלכתחילה (אהרן ברק, חוק השליחות, עמ'' 12).', 'פעולה ללא הרשאה ← השולח יכול לאשר בדיעבד ← כאילו ניתנה הרשאה מראש ← סעיף 6(א) לחוק השליחות.',
    '["חוק השליחות, תשכ\"ה-1965, סעיף 6(א)", "ע\"א 632/87 הרצל גרנט נ'' שלמה מרדכי, מה(1) 544 (25.12.1990)", "ע\"א 1815/16 פלוני נ'' שירותי בריאות כללית (03.01.2018)", "אהרן ברק, חוק השליחות - כרך א (1996), עמ'' 12"]'::jsonb
  );
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_3, 'א', 'אישור בדיעבד אינו אפשרי, שכן הפעולה בוצעה ללא הרשאה מלכתחילה.', false, 'טענה זו אינה נכונה. סעיף 6(א) לחוק השליחות מאפשר אישור בדיעבד של פעולה שבוצעה ללא הרשאה או בחריגה ממנה.', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_3, 'ב', 'אישור בדיעבד של בני הזוג כהן הופך את הפעולה לתקפה כאילו ניתנה הרשאה מלכתחילה, ובלבד שלא תיפגע זכות שרכש צד שלישי בתום לב ובתמורה לפני האישור.', true, 'זוהי התשובה הנכונה. סעיף 6(א) לחוק השליחות קובע כי אישור בדיעבד של פעולה שנעשתה ללא הרשאה כמוהו כהרשאה מלכתחילה, בכפוף להגנה על זכויות צד שלישי תם לב ובתמורה.', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_3, 'ג', 'אישור בדיעבד אפשרי רק אם הצד השלישי לא ידע ששרית פעלה ללא הרשאה.', false, 'טענה זו אינה נכונה. ידיעת הצד השלישי רלוונטית לברירות העומדות לו לפי סעיף 6(ב), אך אינה תנאי לאפשרות האישור בדיעבד על ידי השולח.', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_3, 'ד', 'הפעולה נשארת בטלה, אך בני הזוג כהן יכולים לתבוע את גילי על הפרת חובתו.', false, 'טענה זו אינה נכונה. אישור בדיעבד מרפא את פגם ההרשאה והופך את הפעולה לתקפה כלפי השולח.', 4);

  RAISE NOTICE 'Q% inserted: external_id %', 9, '2022-S-S-Q09';
END
$$;

-- ============================================================
-- Q10 — 2022-S-S-Q10 — chapter=contracts subtopic=insurance_contract
-- classifier_note: Life-insurance beneficiary designation 'spouse + descendants' after divorce + new partner
-- ============================================================
DO $$
DECLARE
  v_sq_id uuid := '2f60b9cd-7eda-437a-877b-f0e2df395da7'::uuid;
  v_group_id uuid := '7a14c06b-aef3-4fb5-b2ee-25c1ec53854e'::uuid;
  v_chapter_id uuid;
  v_subtopic_id uuid;
  v_existing_id uuid;
  v_ang_0 uuid := '98a46e95-0cda-4adc-a365-841f214576be'::uuid;
  v_ang_1 uuid := '078f59b1-0e01-49b8-b140-12a792ad7f5a'::uuid;
  v_ang_2 uuid := '53aaad65-1c26-451f-9f6e-8c38d3d38340'::uuid;
  v_ang_3 uuid := '82381de3-a20d-4af2-94d9-b7fb18942e54'::uuid;
BEGIN
  SELECT id INTO v_existing_id FROM public.source_questions WHERE external_id = '2022-S-S-Q10';
  IF v_existing_id IS NOT NULL THEN
    RAISE NOTICE 'Q% skipped: external_id % already exists', 10, '2022-S-S-Q10';
    RETURN;
  END IF;

  SELECT id INTO v_chapter_id FROM public.chapters WHERE code = 'contracts';
  IF v_chapter_id IS NULL THEN
    RAISE EXCEPTION 'Chapter code % not found', 'contracts';
  END IF;

  SELECT id INTO v_subtopic_id FROM public.subtopics WHERE code = 'insurance_contract' AND chapter_id = v_chapter_id;
  IF v_subtopic_id IS NULL THEN
    RAISE EXCEPTION 'Subtopic code % not found under chapter %', 'insurance_contract', 'contracts';
  END IF;

  INSERT INTO public.source_questions (
    id, question_group_id, version, is_current, external_id, chapter_id, subtopic_id, question_text, source_metadata, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list, notes_for_admin, status, created_by
  ) VALUES (
    v_sq_id, v_group_id, 1, true,
    '2022-S-S-Q10', v_chapter_id, v_subtopic_id, 'עמית בוטח בביטוח חיים, שבמסגרתו ביקש כי מי שיזכו בכספי התגמולים במותו יהיו בת זוגו וצאצאיו ללא ציון שמם. לימים נפרד עמית מאילנה, שהייתה בת זוגו במועד כריתת חוזה הביטוח, והפך לבן זוגה של שמרית, ואף אימץ את בתה יעל. עמית נפטר במפתיע. מי מהבאים אינו זכאי לכספי התגמולים מביטוח החיים של עמית?',
    '{"exam_year": 2022, "exam_season": "summer", "exam_part": 2, "exam_question_number": 10}'::jsonb, 'שאלה זו עוסקת בקביעת זהות המוטבים בביטוח חיים, ובפרט בפרשנות המונחים ''בת זוגו'' ו''צאצאיו'' כאשר הם נקבעים ללא ציון שמות ספציפיים. היא מתבססת על סעיף 44 לחוק חוזה הביטוח, תשמ"א-1981, הקובע כי במקרים אלו, זהות המוטבים נקבעת לפי המצב במועד קרות מקרה הביטוח (פטירת המבוטח).', 'סעיף 44(א) לחוק חוזה הביטוח, תשמ"א-1981, קובע כי ''נקבעו המוטבים כ''בן זוגו'' או ''צאצאיו'' של המבוטח, ללא ציון שמם, יראו כמוטבים את מי שהיו בן זוגו או צאצאיו במועד קרות מקרה הביטוח''. כלומר, זהות המוטבים נקבעת לפי המצב העובדתי ביום פטירתו של המבוטח. במקרה הנדון: 1. אילנה: הייתה בת זוגו במועד כריתת החוזה, אך נפרדה מעמית לפני פטירתו. לכן, במועד הפטירה היא לא הייתה ''בת זוגו'' ואינה זכאית. 2. שמרית: הייתה בת זוגו של עמית במועד פטירתו, ולכן היא זכאית כ''בת זוגו''. 3. יעל: היא בתו המאומצת של עמית. המונח ''צאצאים'' כולל גם ילדים מאומצים (בג"ץ 1000/92 בבלי נ'' בית הדין הרבני הגדול), ולכן היא זכאית. 4. אייל: בנו הביולוגי של עמית, שנולד לאחר מותו. הפסיקה קבעה כי ''צאצאים'' כוללים גם ילדים שנולדו לאחר מות המבוטח, כל עוד הם צאצאיו (ע"א 102/80 פרוכטנבוים נ'' מגן חברה לביטוח בע"מ). לכן, אייל זכאי. לאור זאת, אילנה היא היחידה שאינה זכאית לכספי התגמולים.', 'הנחה שגויה כי זהות המוטבים נקבעת במועד כריתת חוזה הביטוח, או אי-הבנה של ההגדרה הרחבה של ''צאצאים'' הכוללת ילדים מאומצים ואף ילדים שנולדו לאחר מות המבוטח.',
    '["ביטוח חיים", "מוטבים", "בת זוגו", "צאצאיו", "חוק חוזה הביטוח", "מועד קרות מקרה הביטוח", "ילדים מאומצים"]'::jsonb, '**וריאציה 1 — מועד קובע:** מתי נקבעת זהות המוטבים ''בן זוגו'' ו''צאצאיו''? ← במועד קרות מקרה הביטוח (סעיף 44(א) לחוק חוזה הביטוח).
**וריאציה 2 — הגדרת ''בת זוגו'':** מי נחשבת ''בת זוגו''? ← מי שהייתה בת זוגו במועד הפטירה, ולא במועד כריתת החוזה.
**וריאציה 3 — הגדרת ''צאצאיו'':** מי נחשבים ''צאצאיו''? ← ילדים ביולוגיים ומאומצים, כולל אלו שנולדו או אומצו לאחר כריתת החוזה ואף לאחר מות המבוטח (בג"ץ 1000/92 בבלי, ע"א 102/80 פרוכטנבוים).', 'מוטבים ''בן זוגו'' ו''צאצאיו'' ← נקבעים במועד הפטירה ← ''בת זוגו'' היא במועד הפטירה ← ''צאצאיו'' כולל מאומצים ואף לאחר המוות.', '["חוק חוזה הביטוח, תשמ\"א-1981, סעיף 44", "בג\"ץ 1000/92 בבלי נ'' בית הדין הרבני הגדול, פ\"ד מח(2) 221 (1994)", "ע\"א 102/80 פרוכטנבוים נ'' מגן חברה לביטוח בע\"מ, פ\"ד לה(2) 243 (1981)"]'::jsonb,
    'classification_review: original chapter=''סדר דין אזרחי'' subtopic=''הליכים'' → mapped chapter=''contracts'' subtopic=''insurance_contract'' | classifier_note: Life-insurance beneficiary designation ''spouse + descendants'' after divorce + new partner | source_review_note: שאלה זו עוסקת בדיני ביטוח (מהותי) ואינה משתייכת לתחום הדין הדיוני. סווגה תחת ''סדר דין אזרחי - הליכים'' כהצבת מקום בלבד.', 'active', 'b9ecdde2-d07e-4761-96ab-05f0ad32d4e3'
  );

  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'א', 'אילנה.', true, 'זוהי התשובה הנכונה. סעיף 44(א) לחוק חוזה הביטוח קובע כי אם נקבעו המוטבים כ''בן זוגו'' או ''צאצאיו'' ללא ציון שמם, הזכאות נקבעת לפי המצב במועד קרות מקרה הביטוח (פטירת המבוטח). אילנה לא הייתה בת זוגו של עמית במועד פטירתו.', 1);
  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'ב', 'שמרית.', false, 'טענה זו אינה נכונה. שמרית הייתה בת זוגו של עמית במועד פטירתו, ולכן היא זכאית לכספי התגמולים כ''בת זוגו'' לפי סעיף 44(א) לחוק חוזה הביטוח.', 2);
  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'ג', 'יעל.', false, 'טענה זו אינה נכונה. יעל היא בתו המאומצת של עמית, ולכן היא נחשבת ל''צאצאית'' שלו וזכאית לכספי התגמולים לפי סעיף 44(א) לחוק חוזה הביטוח.', 3);
  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'ד', 'אייל, בנו של עמית, שנולד 6 חודשים לאחר מותו.', false, 'טענה זו אינה נכונה. צאצאים כוללים גם ילדים שנולדו לאחר מות המבוטח, כל עוד הם צאצאיו הביולוגיים או המאומצים, ולכן אייל זכאי לכספי התגמולים.', 4);

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_0, v_sq_id, 'א', 'הגדרת ''צאצאים'' בביטוח חיים',
    1, 'דני בוטח בביטוח חיים וקבע כי המוטבים יהיו ''צאצאיו''. במועד כריתת החוזה היו לו שני ילדים ביולוגיים. לימים, אימץ דני ילד נוסף, ונפטר. לאחר מותו, נולדה לו בת נוספת מזרעו שהופרה לאחר מותו. מי מהבאים זכאי לכספי התגמולים?', 'שאלה זו מתמקדת בהגדרת המונח ''צאצאים'' בהקשר של קביעת מוטבים בביטוח חיים, ומבהירה כי הגדרה זו רחבה וכוללת גם ילדים מאומצים וילדים שנולדו לאחר מות המבוטח, כל עוד הם צאצאיו.', 'סעיף 44(א) לחוק חוזה הביטוח, תשמ"א-1981, קובע כי ''נקבעו המוטבים כ''בן זוגו'' או ''צאצאיו'' של המבוטח, ללא ציון שמם, יראו כמוטבים את מי שהיו בן זוגו או צאצאיו במועד קרות מקרה הביטוח''. הפסיקה והספרות המשפטית מפרשות את המונח ''צאצאים'' באופן רחב, כך שיכלול לא רק ילדים ביולוגיים שנולדו לפני מות המבוטח, אלא גם ילדים מאומצים (בג"ץ 1000/92 בבלי נ'' בית הדין הרבני הגדול) וכן ילדים שנולדו לאחר מות המבוטח, כל עוד הם צאצאיו הביולוגיים או המאומצים (ע"א 102/80 פרוכטנבוים נ'' מגן חברה לביטוח בע"מ). לכן, במקרה זה, כל ילדיו של דני, כולל המאומץ והבת שנולדה לאחר מותו, זכאים לכספי התגמולים.',
    'הנחה שגויה כי ''צאצאים'' מתייחס רק לילדים ביולוגיים שהיו קיימים במועד כריתת החוזה או במועד הפטירה.', '["מוטבים בביטוח חיים", "צאצאים", "ילדים מאומצים", "ילדים שנולדו לאחר המוות", "חוק חוזה הביטוח", "מועד קרות מקרה הביטוח"]'::jsonb, '**וריאציה 1 — ילדים מאומצים:** האם ילד מאומץ נחשב ''צאצא''? ← כן, לצורך סעיף 44(א) לחוק חוזה הביטוח (בג"ץ 1000/92 בבלי נ'' בית הדין הרבני הגדול).
**וריאציה 2 — ילדים לאחר המוות:** האם ילד שנולד לאחר מות המבוטח נחשב ''צאצא''? ← כן, אם הוא צאצאו הביולוגי או המאומץ (ע"א 102/80 פרוכטנבוים נ'' מגן חברה לביטוח בע"מ).
**וריאציה 3 — מועד הקביעה:** מתי נקבעת זהות ה''צאצאים''? ← במועד קרות מקרה הביטוח (סעיף 44(א) לחוק חוזה הביטוח).', '''צאצאים'' (סעיף 44(א)) ← כולל ביולוגיים, מאומצים, ואף לאחר המוות ← לפי המצב במועד המוות.',
    '["חוק חוזה הביטוח, תשמ\"א-1981, סעיף 44(א)", "בג\"ץ 1000/92 בבלי נ'' בית הדין הרבני הגדול, פ\"ד מח(2) 221 (1994)", "ע\"א 102/80 פרוכטנבוים נ'' מגן חברה לביטוח בע\"מ, פ\"ד לה(2) 243 (1981)"]'::jsonb
  );
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_0, 'א', 'רק שני ילדיו הביולוגיים שהיו קיימים במועד כריתת החוזה.', false, 'טענה זו אינה נכונה. הגדרת ''צאצאים'' אינה מוגבלת לילדים שהיו קיימים במועד כריתת החוזה.', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_0, 'ב', 'שלושת ילדיו (שני הביולוגיים והמאומץ) שהיו קיימים במועד פטירתו.', false, 'טענה זו אינה נכונה. הגדרת ''צאצאים'' כוללת גם ילדים שנולדו לאחר מות המבוטח, כל עוד הם צאצאיו.', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_0, 'ג', 'כל ילדיו הביולוגיים והמאומצים, כולל הילד המאומץ והבת שנולדה לאחר מותו.', true, 'זוהי התשובה הנכונה. סעיף 44(א) לחוק חוזה הביטוח קובע כי ''צאצאיו'' כוללים את כל ילדיו הביולוגיים והמאומצים, גם אם נולדו או אומצו לאחר כריתת החוזה ואף לאחר מות המבוטח, כל עוד הם צאצאיו.', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_0, 'ד', 'רק ילדיו הביולוגיים, ללא הילד המאומץ והבת שנולדה לאחר מותו.', false, 'טענה זו אינה נכונה. ''צאצאים'' כוללים גם ילדים מאומצים, וגם ילדים שנולדו לאחר מות המבוטח.', 4);

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_1, v_sq_id, 'ב', 'מועד קביעת זהות המוטבים',
    2, 'מהו המועד הקובע לזיהוי המוטבים בביטוח חיים, כאשר המבוטח קבע ''למוטבים שיקבעו על ידי''?', 'שאלה זו עוסקת בעקרון המועד הקובע לזיהוי מוטבים בביטוח חיים, כאשר המבוטח לא ציין שמות ספציפיים אלא הגדרה כללית. היא מדגישה את חשיבות מועד קרות מקרה הביטוח כנקודת הייחוס לזיהוי הזכאים.', 'סעיף 44(א) לחוק חוזה הביטוח, תשמ"א-1981, קובע במפורש כי ''נקבעו המוטבים כ''בן זוגו'' או ''צאצאיו'' של המבוטח, ללא ציון שמם, יראו כמוטבים את מי שהיו בן זוגו או צאצאיו במועד קרות מקרה הביטוח''. כלומר, כאשר המבוטח משתמש בהגדרות כלליות ולא בשמות ספציפיים, זהות המוטבים נקבעת לפי המצב העובדתי ביום פטירתו של המבוטח. עקרון זה מבטיח שהכספים יגיעו לאנשים הקרובים למבוטח במועד שבו הוא אינו יכול לשנות את ההוראה בעצמו. גם אם המבוטח קבע ''למוטבים שיקבעו על ידי'', אם לא קבע אותם במפורש עד מותו, יחול הכלל הכללי של סעיף 44(א) או שהכספים יגיעו לעיזבון אם לא ניתן לזהות מוטבים אחרים (סעיף 11(א) לחוק הירושה, תשכ"ה-1965, בשינויים המחויבים).',
    'הנחה שגויה כי זהות המוטבים נקבעת במועד כריתת החוזה, או במועד אחר שאינו מועד קרות מקרה הביטוח.', '["מוטבים בביטוח חיים", "מועד קרות מקרה הביטוח", "חוק חוזה הביטוח", "זיהוי מוטבים", "הגדרות כלליות"]'::jsonb, '**וריאציה 1 — מוטבים כלליים:** מתי נקבעת זהות מוטבים שנקבעו כ''בן זוגו'' או ''צאצאיו''? ← במועד קרות מקרה הביטוח (סעיף 44(א) לחוק חוזה הביטוח).
**וריאציה 2 — מוטבים בשם:** מתי נקבעת זהות מוטבים שנקבעו בשמם? ← במועד ציון שמם, אלא אם שונו (סעיף 43 לחוק חוזה הביטוח).
**וריאציה 3 — תכלית הכלל:** מדוע נקבע מועד קרות מקרה הביטוח כמועד הקובע? ← כדי שהכספים יגיעו לאנשים הקרובים למבוטח במועד פטירתו, כאשר הוא אינו יכול לשנות את ההוראה (ע"א 102/80 פרוכטנבוים נ'' מגן חברה לביטוח בע"מ).', 'זהות מוטבים כלליים ← נקבעת במועד קרות מקרה הביטוח (פטירה) ← סעיף 44(א) לחוק חוזה הביטוח.',
    '["חוק חוזה הביטוח, תשמ\"א-1981, סעיף 44(א)", "חוק חוזה הביטוח, תשמ\"א-1981, סעיף 43", "ע\"א 102/80 פרוכטנבוים נ'' מגן חברה לביטוח בע\"מ, פ\"ד לה(2) 243 (1981)"]'::jsonb
  );
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_1, 'א', 'מועד כריתת חוזה הביטוח.', false, 'טענה זו אינה נכונה. מועד כריתת החוזה אינו המועד הקובע לזיהוי מוטבים שנקבעו באופן כללי.', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_1, 'ב', 'מועד פטירת המבוטח (קרות מקרה הביטוח).', true, 'זוהי התשובה הנכונה. סעיף 44(א) לחוק חוזה הביטוח קובע כי אם נקבעו המוטבים באופן כללי (כגון ''בן זוגו'' או ''צאצאיו''), הזכאות נקבעת לפי המצב במועד קרות מקרה הביטוח, כלומר פטירת המבוטח.', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_1, 'ג', 'מועד הגשת תביעת הביטוח.', false, 'טענה זו אינה נכונה. מועד הגשת התביעה הוא פרוצדורלי ואינו קובע את זהות המוטבים המהותית.', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_1, 'ד', 'מועד מתן ההודעה לחברת הביטוח על זהות המוטבים.', false, 'טענה זו אינה נכונה. אם המבוטח קבע ''למוטבים שיקבעו על ידי'', הוא שמר לעצמו את הזכות לקבוע את המוטבים, אך אם לא קבע במפורש, המועד הקובע הוא מועד הפטירה.', 4);

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_2, v_sq_id, 'ג', 'שינוי מוטבים בצוואה',
    3, 'יוסי קבע בביטוח החיים שלו את אחיו ראובן כמוטב. לימים, הסתכסך יוסי עם ראובן, וכתב צוואה בה קבע כי כל רכושו, לרבות כספי ביטוח החיים, יועברו לאשתו שרה. יוסי נפטר. מי זכאי לכספי ביטוח החיים?', 'שאלה זו עוסקת במעמד כספי ביטוח החיים ביחס לעיזבון המבוטח, ובפרט בשאלה האם ניתן לשנות מוטב שנקבע בחוזה הביטוח באמצעות צוואה. היא מדגישה את עקרון העצמאות של חוזה הביטוח מדיני הירושה.', 'סעיף 147 לחוק הירושה, תשכ"ה-1965, קובע כי ''סכומים שיש לשלם עקב מותו של אדם על פי חוזה ביטוח, על פי חברות בקופת תגמולים או בקופת קיצבה, אינם בכלל העיזבון, זולת אם קבע המנוח בצוואה או בכתב אחר שהם נכללים בעיזבון''. כלומר, כספי ביטוח חיים אינם חלק מהעיזבון, אלא זכות עצמאית של המוטב. הוראה בצוואה אינה יכולה לשנות את קביעת המוטב בחוזה הביטוח, אלא אם כן המבוטח הודיע לחברת הביטוח על שינוי המוטב בהתאם לתנאי הפוליסה (סעיף 43 לחוק חוזה הביטוח). במקרה זה, יוסי לא הודיע לחברת הביטוח על שינוי המוטב, אלא רק ציין זאת בצוואתו. לכן, ראובן נשאר המוטב הזכאי לכספים, שכן קביעת המוטב בחוזה הביטוח גוברת על הוראה בצוואה.',
    'הנחה שגויה כי צוואה, כמסמך המבטא את רצון המנוח, גוברת תמיד על כל הוראה קודמת, כולל קביעת מוטבים בביטוח חיים.', '["כספי ביטוח חיים", "עיזבון", "צוואה", "מוטבים", "חוק הירושה", "חוק חוזה הביטוח", "עצמאות חוזה הביטוח"]'::jsonb, '**וריאציה 1 — כספי ביטוח ועיזבון:** האם כספי ביטוח חיים הם חלק מהעיזבון? ← לא, אלא אם נקבע אחרת במפורש (סעיף 147 לחוק הירושה).
**וריאציה 2 — שינוי מוטב בצוואה:** האם צוואה יכולה לשנות מוטב שנקבע בפוליסה? ← לא, אלא אם המבוטח הודיע לחברת הביטוח על השינוי (סעיף 43 לחוק חוזה הביטוח).
**וריאציה 3 — תכלית ההפרדה:** מדוע קיימת הפרדה בין כספי ביטוח לבין העיזבון? ← כדי להבטיח שהכספים יגיעו ישירות למוטבים, ללא עיכובים או חובות העיזבון (ע"א 127/78 בנק הפועלים בע"מ נ'' אירון, פ"ד לג(1) 337).', 'כספי ביטוח חיים ← אינם חלק מהעיזבון ← קביעת מוטב בפוליסה גוברת על צוואה ← אלא אם הודעה לחברה.',
    '["חוק הירושה, תשכ\"ה-1965, סעיף 147", "חוק חוזה הביטוח, תשמ\"א-1981, סעיף 43", "ע\"א 127/78 בנק הפועלים בע\"מ נ'' אירון, פ\"ד לג(1) 337 (1979)", "ע\"א 490/89 אלבס נ'' אלבס, פ\"ד מו(2) 307 (1992)"]'::jsonb
  );
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_2, 'א', 'ראובן, שכן קביעת מוטב בביטוח חיים גוברת על הוראה בצוואה.', true, 'זוהי התשובה הנכונה. סעיף 147 לחוק הירושה קובע כי כספי ביטוח חיים אינם חלק מהעיזבון, ולכן הוראה בצוואה אינה יכולה לשנות את קביעת המוטב בחוזה הביטוח, אלא אם כן המבוטח הודיע לחברת הביטוח על שינוי המוטב.', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_2, 'ב', 'שרה, שכן צוואה היא המסמך האחרון המבטא את רצון המנוח.', false, 'טענה זו אינה נכונה. כספי ביטוח חיים אינם חלק מהעיזבון, ולכן צוואה אינה יכולה לשנות את קביעת המוטב בחוזה הביטוח.', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_2, 'ג', 'הכספים יחולקו בין ראובן לשרה בחלקים שווים.', false, 'טענה זו אינה נכונה. אין הוראה בחוק לחלוקה שווה במקרה כזה.', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_2, 'ד', 'הכספים יועברו לעיזבון ויתחלקו לפי דיני הירושה.', false, 'טענה זו אינה נכונה. כספי ביטוח חיים אינם חלק מהעיזבון, אלא אם לא נקבע מוטב או שהמוטב נפטר לפני המבוטח.', 4);

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_3, v_sq_id, 'ד', 'זכות המוטב לעומת נושי העיזבון',
    4, 'יוסי נפטר והותיר אחריו חובות רבים. בביטוח החיים שלו נקבעה אשתו שרה כמוטבת. האם נושי העיזבון של יוסי יכולים לתבוע את כספי ביטוח החיים שהועברו לשרה?', 'שאלה זו עוסקת בהגנה על כספי ביטוח חיים מפני נושי העיזבון, ומדגישה את מעמדם המיוחד של כספים אלו כנכס שאינו חלק מהעיזבון, אלא זכות עצמאית של המוטב.', 'סעיף 147 לחוק הירושה, תשכ"ה-1965, קובע כי ''סכומים שיש לשלם עקב מותו של אדם על פי חוזה ביטוח... אינם בכלל העיזבון''. משמעות הדבר היא שכספי ביטוח חיים אינם נכס של המנוח במועד פטירתו, ולכן אינם חלק מהעיזבון. כתוצאה מכך, כספים אלו אינם עומדים לפירעון חובות העיזבון ומועברים ישירות למוטב שנקבע בפוליסה, מבלי שנושי העיזבון יוכלו לגבות מהם (ע"א 127/78 בנק הפועלים בע"מ נ'' אירון). הגנה זו נועדה להבטיח את מטרת הביטוח, שהיא מתן סעד כלכלי למוטבים לאחר מות המבוטח, ללא קשר למצבו הכלכלי של המנוח.',
    'הנחה שגויה כי כל נכס שהיה קשור למנוח בחייו, כולל כספי ביטוח חיים, נכלל בעיזבון ועומד לפירעון חובותיו.', '["כספי ביטוח חיים", "עיזבון", "נושים", "חוק הירושה", "הגנת המוטב", "חובות המנוח"]'::jsonb, '**וריאציה 1 — הגנה מפני נושים:** האם כספי ביטוח חיים מוגנים מפני נושי העיזבון? ← כן, הם אינם חלק מהעיזבון (סעיף 147 לחוק הירושה).
**וריאציה 2 — ירושה מול ביטוח:** מה ההבדל בין ירושה לכספי ביטוח? ← ירושה היא נכסי העיזבון, כספי ביטוח הם זכות עצמאית של המוטב (ע"א 127/78 בנק הפועלים בע"מ נ'' אירון).
**וריאציה 3 — חריג להגנה:** מתי כספי ביטוח חיים כן יהיו חשופים לנושים? ← אם המבוטח קבע במפורש שהם נכללים בעיזבון (סעיף 147 לחוק הירושה).', 'כספי ביטוח חיים ← אינם חלק מהעיזבון ← מוגנים מנושים ← מועברים ישירות למוטב.',
    '["חוק הירושה, תשכ\"ה-1965, סעיף 147", "ע\"א 127/78 בנק הפועלים בע\"מ נ'' אירון, פ\"ד לג(1) 337 (1979)", "ע\"א 490/89 אלבס נ'' אלבס, פ\"ד מו(2) 307 (1992)"]'::jsonb
  );
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_3, 'א', 'כן, כספי ביטוח חיים ניתנים לגבייה על ידי נושי העיזבון, שכן הם חלק מרכושו של המנוח.', false, 'טענה זו אינה נכונה. כספי ביטוח חיים אינם חלק מהעיזבון, ולכן אינם עומדים לפירעון חובות העיזבון.', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_3, 'ב', 'לא, כספי ביטוח חיים אינם חלק מהעיזבון ומועברים ישירות למוטב, ולכן אינם עומדים לפירעון חובות העיזבון.', true, 'זוהי התשובה הנכונה. סעיף 147 לחוק הירושה קובע כי כספי ביטוח חיים אינם חלק מהעיזבון, ולכן הם מוגנים מפני נושי העיזבון ומועברים ישירות למוטב.', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_3, 'ג', 'כן, אם המוטבת ידעה על חובותיו של המנוח במועד קביעתה כמוטבת.', false, 'טענה זו אינה נכונה. ידיעת המוטבת על חובות המנוח אינה משנה את מעמד כספי הביטוח כנכס שאינו חלק מהעיזבון.', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_3, 'ד', 'לא, אלא אם כן המבוטח קבע במפורש בצוואתו שהכספים יועברו לנושים.', false, 'טענה זו אינה נכונה. המבוטח יכול לקבוע שהכספים יועברו לעיזבון, ואז הם יהיו חשופים לנושים, אך לא ישירות לנושים.', 4);

  RAISE NOTICE 'Q% inserted: external_id %', 10, '2022-S-S-Q10';
END
$$;

