-- classifier_note: Lawyer suing another lawyer for malpractice without prior notification — duty to notify
-- ============================================================
DO $$
DECLARE
  v_sq_id uuid := '337fe6da-6061-4203-bc4b-e9d3e209d416'::uuid;
  v_group_id uuid := '206880d5-95cc-4449-82d4-d9f89ecec926'::uuid;
  v_chapter_id uuid;
  v_subtopic_id uuid;
  v_existing_id uuid;
  v_ang_0 uuid := 'b8dc4745-a08e-4b09-9b54-c108dbffbcf0'::uuid;
  v_ang_1 uuid := '50716f47-e7fe-49af-9739-ee663c1acb01'::uuid;
  v_ang_2 uuid := 'b2334f30-3967-4aa7-85b3-bb3b280c8fdf'::uuid;
  v_ang_3 uuid := '40c9e8d5-c080-4f38-9268-106294bd879a'::uuid;
BEGIN
  SELECT id INTO v_existing_id FROM public.source_questions WHERE external_id = '2022-S-S-Q11';
  IF v_existing_id IS NOT NULL THEN
    RAISE NOTICE 'Q% skipped: external_id % already exists', 11, '2022-S-S-Q11';
    RETURN;
  END IF;

  SELECT id INTO v_chapter_id FROM public.chapters WHERE code = 'ethics';
  IF v_chapter_id IS NULL THEN
    RAISE EXCEPTION 'Chapter code % not found', 'ethics';
  END IF;

  SELECT id INTO v_subtopic_id FROM public.subtopics WHERE code = 'disciplinary_law' AND chapter_id = v_chapter_id;
  IF v_subtopic_id IS NULL THEN
    RAISE EXCEPTION 'Subtopic code % not found under chapter %', 'disciplinary_law', 'ethics';
  END IF;

  INSERT INTO public.source_questions (
    id, question_group_id, version, is_current, external_id, chapter_id, subtopic_id, question_text, source_metadata, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list, notes_for_admin, status, created_by
  ) VALUES (
    v_sq_id, v_group_id, 1, true,
    '2022-S-S-Q11', v_chapter_id, v_subtopic_id, 'עו"ד יוני הגיש בשם לקוחתו תביעה נגד עו"ד אריאל בגין רשלנות מקצועית בלי לפנות אליו. התביעה הוגשה לאחר שהלקוחה הגישה נגד עו"ד אריאל תלונה לוועדת האתיקה, וזו נגנזה משום שהיא נובעת מרשלנות מקצועית. בהודעה שקיבלו הלקוחה ועו"ד אריאל מוועדת האתיקה צוין כי מדובר בסכסוך אזרחי שבגינו ניתן להגיש תביעה נגד עו"ד אריאל. מה הדין?',
    '{"exam_year": 2022, "exam_season": "summer", "exam_part": 2, "exam_question_number": 11}'::jsonb, 'שאלה זו עוסקת בחובת עורך דין לפנות לעורך דין אחר בטרם הגשת הליך משפטי נגדו, כפי שנקבע בסעיף 31 לכללי לשכת עורכי הדין (אתיקה מקצועית), תשמ"ו-1986. הכלל נועד לנסות וליישב סכסוכים בדרכי שלום בין עורכי דין, ואי-קיומו מהווה עבירת משמעת אתית. השאלה בוחנת את תחולת הכלל גם כאשר קדמה לו תלונה אתית שנגנזה.', 'סעיף 31 לכללי לשכת עורכי הדין (אתיקה מקצועית), תשמ"ו-1986, קובע כי ''בטרם יפתח עורך דין בשם לקוחו בהליך משפטי נגד עורך דין אחר, יפנה אל אותו עורך דין בכתב, ואם קיימת אפשרות - אף בעל פה, כדי לנסות וליישב את הסכסוך בדרכי שלום, ובלבד שפנייה כאמור לא תגרום נזק ללקוח''. סעיף 31 לכללי לשכת עורכי הדין (אתיקה מקצועית), תשמ"ו-1986 | מחלוקת עם עורך דין נבו - המתמחה, אתיקה מקצועית - כללי האתיקה (2026) | מחלוקת עם עורך דין חובה זו היא חובה אתית קולגיאלית, שמטרתה למנוע התדיינויות מיותרות ולשמור על כבוד המקצוע. תפ"מ (שלום חי'') 40856-08-23 נטע שלי נ'' לואי לובאני (06.12.2023) אי-קיום חובה זו מהווה עבירת משמעת אתית של עורך הדין. ת"א (שלום נצרת) 34028-06-25 ראני בדיר נ'' מדינת ישראל (25.02.2026) העובדה שהלקוחה הגישה תלונה לוועדת האתיקה, וזו נגנזה תוך ציון כי מדובר בסכסוך אזרחי, אינה פוטרת את עו"ד יוני מחובתו האתית לפנות לעו"ד אריאל בטרם הגשת התביעה. החריג היחיד לחובה זו הוא כאשר פנייה כאמור עלולה לגרום נזק ללקוח, נבו - המתמחה, אתיקה מקצועית - כללי האתיקה (2026) | מחלוקת עם עורך דין ונתון כזה אינו עולה מהשאלה. לכן, עו"ד יוני הפר את כללי האתיקה. ת"א (שלום ת"א) 16585-11-16 פלוני נ'' עו"ד יובל צלטנר (27.01.2021)', 'הנחה שגויה כי הליך קודם בוועדת האתיקה, או המלצתה להגיש תביעה אזרחית, מבטלים את החובה האתית של עורך הדין לפנות לחברו בטרם הגשת התביעה האזרחית.',
    '["כללי אתיקה", "סעיף 31", "חובת פנייה מוקדמת", "עבירת משמעת", "קולגיאליות", "רשלנות מקצועית"]'::jsonb, '**וריאציה 1 — חובת פנייה:** האם עו"ד חייב לפנות לעו"ד אחר לפני תביעה נגדו? ← כן, לפי סעיף 31 לכללי האתיקה.
**וריאציה 2 — תלונה קודמת:** האם תלונה קודמת לוועדת האתיקה פוטרת מחובה זו? ← לא, החובה נשארת בעינה.
**וריאציה 3 — חריג:** מתי אין חובה לפנות? ← אם הפנייה עלולה לגרום נזק ללקוח (סעיף 31 לכללי האתיקה).', 'עו"ד תובע עו"ד ← חובה לפנות מראש (כלל 31) ← גם אם הייתה תלונה אתית קודמת ← אלא אם נזק ללקוח.', '["כללי לשכת עורכי הדין (אתיקה מקצועית), תשמ\"ו-1986, סעיף 31", "ת\"א (שלום נצרת) 34028-06-25 ראני בדיר נ'' מדינת ישראל (25.02.2026)", "ת\"א (שלום ת\"א) 16585-11-16 פלוני נ'' עו\"ד יובל צלטנר (27.01.2021)", "תפ\"מ (שלום חי'') 40856-08-23 נטע שלי נ'' לואי לובאני (06.12.2023)", "נבו - המתמחה, אתיקה מקצועית - כללי האתיקה (2026) | מחלוקת עם עורך דין"]'::jsonb,
    'classification_review: original chapter=''סדר דין אזרחי'' subtopic=''הליכים'' → mapped chapter=''ethics'' subtopic=''disciplinary_law'' | classifier_note: Lawyer suing another lawyer for malpractice without prior notification — duty to notify | source_review_note: שאלה זו עוסקת בדיני אתיקה מקצועית של עורכי דין (דין מהותי), ואינה משתייכת לתחום הדין הדיוני. סווגה תחת ''סדר דין אזרחי - הליכים'' כהצבת מקום בלבד, בהתאם להנחיות.', 'active', 'b9ecdde2-d07e-4761-96ab-05f0ad32d4e3'
  );

  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'א', 'עו"ד יוני עבר על כללי אתיקה, שכן לא נתן לעו"ד אריאל התראה לפני הגשת תביעה.', true, 'זוהי התשובה הנכונה. סעיף 31 לכללי לשכת עורכי הדין (אתיקה מקצועית) מחייב עורך דין לפנות לעורך דין אחר בכתב (ואף בעל פה אם אפשר) בטרם הגשת הליך משפטי נגדו, וזאת כדי לנסות ליישב את הסכסוך בדרכי שלום. העובדה שוועדת האתיקה ציינה כי מדובר בסכסוך אזרחי אינה פוטרת את עו"ד יוני מחובה זו.', 1);
  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'ב', 'עו"ד יוני לא עבר על כללי האתיקה, שכן התביעה הוגשה בשם לקוחתו.', false, 'טענה זו אינה נכונה. כלל 31 חל כאשר עורך דין פותח בהליך משפטי נגד עורך דין אחר, בין אם בשם לקוחו ובין אם בשם עצמו.', 0);
  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'ג', 'עו"ד יוני לא עבר על כללי האתיקה, שכן ועדת האתיקה ציינה במכתב ההחלטה כי על הלקוחה להגיש תביעה אזרחית, ועל כן על עו"ד אריאל היה לדעת כי צפויה להיות מוגשת נגדו תביעה אזרחית.', false, 'טענה זו אינה נכונה. המלצת ועדת האתיקה אינה מבטלת את החובה האתית של עו"ד יוני לפנות לעו"ד אריאל בטרם הגשת התביעה, שכן מטרת הכלל היא ניסיון ליישוב הסכסוך בדרכי שלום.', 0);
  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'ד', 'עו"ד יוני עבר על כללי האתיקה בכך שלא וידא כי עו"ד אריאל קיבל את מכתב הגניזה מוועדת האתיקה בטרם הגיש נגדו תביעה אזרחית.', false, 'טענה זו אינה נכונה. חובתו של עו"ד יוני היא לפנות ישירות לעו"ד אריאל בכתב, ולא לוודא קבלת מסמכים מוועדת האתיקה. קבלת מכתב הגניזה אינה מהווה תחליף לפנייה המוקדמת הנדרשת לפי כלל 31.', 0);

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_0, v_sq_id, 'א', 'חריג לחובת הפנייה המוקדמת',
    1, 'עו"ד שירן מייצגת לקוח בתביעה דחופה נגד עו"ד דניאל, כאשר קיים חשש ממשי כי עו"ד דניאל יבריח נכסים אם יקבל התראה מוקדמת. האם עו"ד שירן חייבת לפנות לעו"ד דניאל בטרם הגשת התביעה?', 'שאלה זו בוחנת את החריג המפורש לכלל 31 לכללי לשכת עורכי הדין (אתיקה מקצועית), המאפשר לעורך דין שלא לפנות לחברו בטרם הגשת תביעה, אם פנייה כזו עלולה לגרום נזק ללקוח. חריג זה מבטא את עדיפות חובת הנאמנות ללקוח על פני החובה הקולגיאלית.', 'סעיף 31 לכללי לשכת עורכי הדין (אתיקה מקצועית), תשמ"ו-1986, קובע חובה לפנות לעורך דין אחר בטרם הגשת הליך משפטי נגדו, ''ובלבד שפנייה כאמור לא תגרום נזק ללקוח''. חריג זה נועד להגן על האינטרסים של הלקוח, שהם בראש סדר העדיפויות של עורך הדין. כאשר קיים חשש ממשי כי פנייה מוקדמת תאפשר לצד שכנגד (עורך הדין במקרה זה) לבצע פעולות שיפגעו בלקוח, כגון הברחת נכסים, עורך הדין רשאי ואף חייב שלא לפנות אליו מראש. חובתו של עורך הדין ללקוחו קודמת לחובה הקולגיאלית כלפי חברו למקצוע. נבו - המתמחה, אתיקה מקצועית - כללי האתיקה (2026) | מחלוקת עם עורך דין',
    'אי-הבנה של היקף החריג לכלל 31, והנחה שגויה כי החובה הקולגיאלית גוברת תמיד על חובת הנאמנות ללקוח.', '["כללי אתיקה", "סעיף 31", "חובת פנייה מוקדמת", "חריג", "נזק ללקוח", "חובת נאמנות"]'::jsonb, '**וריאציה 1 — מתי חל החריג?** ← כאשר פנייה מוקדמת עלולה לגרום נזק ללקוח (סעיף 31 לכללי האתיקה).
**וריאציה 2 — דוגמה לנזק:** מהי דוגמה לנזק המצדיק אי-פנייה? ← חשש מהברחת נכסים על ידי עורך הדין הנתבע.
**וריאציה 3 — עדיפות חובות:** איזו חובה גוברת במקרה של התנגשות? ← חובת הנאמנות ללקוח גוברת על החובה הקולגיאלית (נבו - המתמחה, אתיקה מקצועית - כללי האתיקה, עמ'' 68).', 'חובת פנייה מוקדמת (כלל 31) ← חריג: אם גורמת נזק ללקוח ← חובת נאמנות קודמת.',
    '["כללי לשכת עורכי הדין (אתיקה מקצועית), תשמ\"ו-1986, סעיף 31", "נבו - המתמחה, אתיקה מקצועית - כללי האתיקה (2026) | מחלוקת עם עורך דין"]'::jsonb
  );
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_0, 'א', 'כן, חובת הפנייה המוקדמת היא מוחלטת ואינה ניתנת לחריגה.', false, 'טענה זו אינה נכונה. לכלל 31 קיים חריג מפורש כאשר הפנייה עלולה לגרום נזק ללקוח.', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_0, 'ב', 'לא, שכן פנייה מוקדמת עלולה לגרום נזק ללקוח, וזו מהווה חריג לחובה.', true, 'זוהי התשובה הנכונה. סעיף 31 לכללי לשכת עורכי הדין (אתיקה מקצועית) קובע חריג לחובת הפנייה המוקדמת, והוא כאשר פנייה כאמור עלולה לגרום נזק ללקוח. חשש מהברחת נכסים הוא דוגמה מובהקת לנזק כזה.', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_0, 'ג', 'כן, אך עליה להודיע על כך לבית המשפט בעת הגשת התביעה.', false, 'טענה זו אינה נכונה. אם מתקיים החריג, אין חובה לפנות כלל, ואין צורך בהודעה מיוחדת לבית המשפט בעניין זה.', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_0, 'ד', 'לא, אך עליה להגיש תלונה לוועדת האתיקה נגד עו"ד דניאל במקביל להגשת התביעה.', false, 'טענה זו אינה נכונה. הגשת תלונה לוועדת האתיקה אינה מהווה תחליף לחובת הפנייה המוקדמת או לחריג ממנה, ואינה קשורה ישירות לעניין.', 4);

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_1, v_sq_id, 'ב', 'מעמד כלל 31 בהליך אזרחי',
    2, 'עו"ד יוני הגיש תביעה נגד עו"ד אריאל בשם לקוחתו מבלי לפנות אליו מראש, ובכך הפר את כלל 31. עו"ד אריאל מבקש מבית המשפט למחוק את התביעה על הסף בשל הפרה זו. מהי עמדת בית המשפט?', 'שאלה זו עוסקת בהבחנה בין הפרה אתית לבין השלכותיה על ההליך האזרחי. היא מדגישה כי הפרת כלל 31 לכללי האתיקה, אף שהיא עבירת משמעת, אינה מהווה כשלעצמה עילה לסילוק תביעה על הסף, אלא במקרים חריגים של שימוש לרעה חמור בהליכי משפט.', 'הפסיקה קבעה כי אי-קיום חובת הפנייה המוקדמת לפי סעיף 31 לכללי לשכת עורכי הדין (אתיקה מקצועית) מהווה עבירת משמעת אתית של עורך הדין. ת"א (שלום נצרת) 34028-06-25 ראני בדיר נ'' מדינת ישראל (25.02.2026) ת"א (שלום ת"א) 16585-11-16 פלוני נ'' עו"ד יובל צלטנר (27.01.2021) ת"א (שלום חי'') 55673-03-20 שמואל סלומון נ'' רונן מתניה משה (29.11.2022) תפ"מ (שלום חי'') 40856-08-23 נטע שלי נ'' לואי לובאני (06.12.2023) סעיף 31 לכללי לשכת עורכי הדין (אתיקה מקצועית), תשמ"ו-1986 | מחלוקת עם עורך דין ואולם, הפרה של חובה אתית זו אינה מהווה, כשלעצמה, עילה למחיקה על הסף של כתב התביעה, אלא אם היא עולה כדי שימוש לרעה חמור ובוטה בהליכי משפט, המצדיק פגיעה בזכות הגישה לערכאות. ת"א (שלום נצרת) 34028-06-25 ראני בדיר נ'' מדינת ישראל (25.02.2026) ת"א (שלום נצרת) 34028-06-25 ראני בדיר נ'' מדינת ישראל (25.02.2026) אי שליחת מכתב התראה מקדים לעורך דין יריב, אף שהיא הפרה אתית, אינה עולה כדי שימוש לרעה חמור בהליכי משפט המצדיק פגיעה בזכות הגישה לערכאות של הלקוח. ת"א (שלום נצרת) 34028-06-25 ראני בדיר נ'' מדינת ישראל (25.02.2026)',
    'הנחה שגויה כי כל הפרה של כללי האתיקה גוררת סילוק על הסף של ההליך המשפטי, מבלי להבחין בין מישור המשמעת למישור האזרחי.', '["כלל 31", "עבירת משמעת", "סילוק על הסף", "זכות גישה לערכאות", "שימוש לרעה בהליכי משפט", "אתיקה מקצועית"]'::jsonb, '**וריאציה 1 — הפרה אתית:** האם הפרת כלל 31 היא עבירת משמעת? ← כן, היא מהווה עבירת משמעת אתית (ת"א (שלום נצרת) 34028-06-25).
**וריאציה 2 — סילוק על הסף:** האם הפרת כלל 31 מובילה לסילוק על הסף? ← לא, אלא אם מדובר בשימוש לרעה חמור ובוטה בהליכי משפט (ת"א (שלום נצרת) 34028-06-25).
**וריאציה 3 — תכלית הכלל:** מהי תכלית כלל 31? ← לנסות ליישב את הסכסוך בדרכי שלום לפני פתיחת הליך משפטי (סעיף 31 לכללי האתיקה).', 'הפרת כלל 31 ← עבירת משמעת ← לא עילה לסילוק על הסף (לרוב) ← אלא אם שימוש לרעה חמור.',
    '["כללי לשכת עורכי הדין (אתיקה מקצועית), תשמ\"ו-1986, סעיף 31", "ת\"א (שלום נצרת) 34028-06-25 ראני בדיר נ'' מדינת ישראל (25.02.2026)", "ת\"א (שלום ת\"א) 16585-11-16 פלוני נ'' עו\"ד יובל צלטנר (27.01.2021)", "ת\"א (שלום חי'') 55673-03-20 שמואל סלומון נ'' רונן מתניה משה (29.11.2022)", "תפ\"מ (שלום חי'') 40856-08-23 נטע שלי נ'' לואי לובאני (06.12.2023)"]'::jsonb
  );
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_1, 'א', 'בית המשפט ימחק את התביעה על הסף, שכן הפרת כלל אתיקה מהותי פוגעת בסדרי הדין.', false, 'טענה זו אינה נכונה. הפרת כלל 31 אינה מהווה, כשלעצמה, עילה למחיקה על הסף של כתב התביעה.', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_1, 'ב', 'בית המשפט לא ימחק את התביעה על הסף, שכן הפרת כלל 31 מהווה עבירת משמעת אתית אך אינה יוצרת מחסום דיוני, אלא אם מדובר בשימוש לרעה חמור בהליכי משפט.', true, 'זוהי התשובה הנכונה. הפסיקה קבעה כי אי-קיום חובת הפנייה המוקדמת לפי כלל 31 מהווה עבירת משמעת אתית, אך אינו מהווה, כשלעצמו, עילה למחיקה על הסף של כתב התביעה, אלא אם מדובר בשימוש לרעה חמור ובוטה בהליכי משפט.', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_1, 'ג', 'בית המשפט ימחק את התביעה על הסף, אך יאפשר ללקוחה להגישה מחדש לאחר שעו"ד יוני יפנה לעו"ד אריאל.', false, 'טענה זו אינה נכונה. בית המשפט לא ימחק את התביעה על הסף רק בשל הפרת כלל 31, ואין צורך בהגשה מחדש.', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_1, 'ד', 'בית המשפט יחייב את עו"ד יוני בתשלום הוצאות משפט גבוהות לעו"ד אריאל, אך לא ימחק את התביעה.', false, 'טענה זו אינה נכונה. חיוב בהוצאות הוא סעד אפשרי, אך אינו התגובה הבלעדית או העיקרית להפרת כלל 31, ואינו שולל את האפשרות של סילוק על הסף במקרים חמורים של שימוש לרעה.', 4);

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_2, v_sq_id, 'ג', 'חובת פנייה כשעורך הדין מייצג את עצמו',
    3, 'עו"ד דניאל הגיש תביעה בשמו נגד עו"ד שירן, מבלי לפנות אליה מראש. האם עו"ד דניאל הפר את כלל 31 לכללי לשכת עורכי הדין (אתיקה מקצועית)?', 'שאלה זו בוחנת את היקף תחולת כלל 31 לכללי לשכת עורכי הדין (אתיקה מקצועית) במקרים בהם עורך הדין הוא בעל הדין בעצמו. היא מדגישה את העיקרון לפיו עורך דין כפוף לכללי האתיקה גם כאשר הוא מייצג את עצמו.', 'הפסיקה קבעה כי עורך דין כפוף לכללי האתיקה המקצועית גם כשהוא מייצג את עצמו בהליך. נבו - המתמחה, אתיקה מקצועית - כללי האתיקה (2026) | מחלוקת עם עורך דין נבו - המתמחה, אתיקה מקצועית - כללי האתיקה (2026) | מגע עם אדם מיוצג לפיכך, אם עורך דין הגיש בשם עצמו תביעה נגד עורך דין אחר מבלי לפנות אליו קודם לכן, הוא עבר עבירת משמעת. נבו - המתמחה, אתיקה מקצועית - כללי האתיקה (2026) | מחלוקת עם עורך דין כלל 31 נועד לנסות וליישב סכסוכים בדרכי שלום בין עורכי דין, ואין הבדל אם עורך הדין הוא התובע בעצמו או מייצג לקוח. עת"מ (מינהליים י-ם) 17988-03-22 אליחי פרי נ'' לשכת עורכי הדין בישראל (31.05.2022)',
    'הנחה שגויה כי כללי האתיקה חלים רק על עורך דין המייצג לקוח, ולא על עורך דין הפועל בשמו ובשביל עצמו.', '["כלל 31", "ייצוג עצמי", "חובות אתיות", "לשכת עורכי הדין", "קולגיאליות"]'::jsonb, '**וריאציה 1 — תחולת הכלל:** האם כלל 31 חל על עורך דין המייצג את עצמו? ← כן (על"ע 6/88 קובלר, נבו - המתמחה, אתיקה מקצועית - כללי האתיקה, עמ'' 68).
**וריאציה 2 — מטרת הכלל:** מהי מטרת כלל 31? ← לנסות ליישב סכסוכים בדרכי שלום בין עורכי דין.
**וריאציה 3 — הפרה:** מהי ההשלכה של אי-ציות לכלל? ← עבירת משמעת אתית.', 'עו"ד המייצג עצמו ← כפוף לכלל 31 ← חייב לפנות מראש לעו"ד יריב.',
    '["כללי לשכת עורכי הדין (אתיקה מקצועית), תשמ\"ו-1986, סעיף 31", "נבו - המתמחה, אתיקה מקצועית - כללי האתיקה (2026) | מחלוקת עם עורך דין", "נבו - המתמחה, אתיקה מקצועית - כללי האתיקה (2026) | מגע עם אדם מיוצג", "עת\"מ (מינהליים י-ם) 17988-03-22 אליחי פרי נ'' לשכת עורכי הדין בישראל (31.05.2022)"]'::jsonb
  );
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_2, 'א', 'לא, כלל 31 חל רק כאשר עורך דין מייצג לקוח, ולא כאשר הוא מייצג את עצמו.', false, 'טענה זו אינה נכונה. הפסיקה קבעה כי כלל 31 חל גם כאשר עורך דין מייצג את עצמו.', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_2, 'ב', 'כן, עורך דין כפוף לכללי האתיקה המקצועית גם כשהוא מייצג את עצמו, ולכן חלה עליו חובת הפנייה המוקדמת.', true, 'זוהי התשובה הנכונה. הפסיקה קבעה כי עורך דין כפוף לכללי האתיקה המקצועית גם כשהוא מייצג את עצמו בהליך, ולכן חובת הפנייה המוקדמת לפי כלל 31 חלה עליו גם במקרה זה.', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_2, 'ג', 'לא, אלא אם כן עו"ד דניאל הוא עורך דין ותיק בעל ניסיון רב.', false, 'טענה זו אינה נכונה. ותק או ניסיון אינם משנים את תחולת כלל 31.', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_2, 'ד', 'כן, אך רק אם התביעה עוסקת בעניין מקצועי ולא בעניין אישי.', false, 'טענה זו אינה נכונה. כלל 31 חל על הליך משפטי נגד עורך דין אחר, ללא הבחנה בין עניין מקצועי לאישי.', 4);

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_3, v_sq_id, 'ד', 'סמכות בית המשפט לדון בענייני אתיקה',
    4, 'האם בית משפט אזרחי מוסמך לדון בטענות על הפרת כללי אתיקה של עורכי דין, או שסמכות זו נתונה באופן בלעדי ללשכת עורכי הדין?', 'שאלה זו עוסקת בחלוקת הסמכויות בין לשכת עורכי הדין לבין בתי המשפט האזרחיים בכל הנוגע לטיפול בהפרות אתיות. היא מדגישה את סמכותו של בית המשפט להתערב בענייני אתיקה כאשר יש לכך השלכה ישירה על זכויות בעלי הדין או על הגינות ההליך המשפטי.', 'הן במסגרת כללי האתיקה והן במסגרת חוק לשכת עורכי הדין נקבע כי בית המשפט יהיה רשאי להכריע בעצמו בסוגיות אתיות מסוימות, אשר יש בהעברתן לדיון אצל לשכת עורכי הדין כדי להכביד על ההליך שלא לצורך, ואשר מתעוררים תוך כדי דיון. ת"א (מחוזי ת"א) 45320-07-19 טיטאן בניה בע"מ נ'' ירון דיסקין (06.12.2020) כך, מוסמך בית המשפט להכריע בטענות על אודות הפרת כללי האתיקה, כאשר אחד מבעלי הדין טוען כי ההפרה פוגעת בו ואף יכול ליתן צו בדבר הפסקת ייצוג, וזאת על מנת להגן על הלקוח. ת"א (מחוזי ת"א) 45320-07-19 טיטאן בניה בע"מ נ'' ירון דיסקין (06.12.2020) כלומר, אף שכללי האתיקה אינם יוצרים מחסום דיוני כשלעצמם, בית המשפט יכול להתערב כאשר הפרה אתית משפיעה על הגינות ההליך או גורמת נזק לבעל דין. ת"א (שלום נצרת) 34028-06-25 ראני בדיר נ'' מדינת ישראל (25.02.2026)',
    'הנחה שגויה כי ענייני אתיקה הם בסמכות בלעדית של לשכת עורכי הדין, וכי בתי המשפט האזרחיים אינם רשאים להתערב בהם כלל.', '["סמכות עניינית", "כללי אתיקה", "לשכת עורכי הדין", "בית משפט אזרחי", "הגינות ההליך", "פגיעה בלקוח"]'::jsonb, '**וריאציה 1 — סמכות בלעדית:** האם לשכת עורכי הדין היא בעלת סמכות בלעדית בענייני אתיקה? ← לא תמיד, בית המשפט יכול להתערב (ת"א (מחוזי ת"א) 45320-07-19).
**וריאציה 2 — מתי יתערב בית המשפט?** ← כאשר ההפרה האתית פוגעת בבעל דין או מכבידה על ההליך (ת"א (מחוזי ת"א) 45320-07-19).
**וריאציה 3 — סעדים אפשריים:** אילו סעדים יכול בית המשפט ליתן? ← צו בדבר הפסקת ייצוג, או התייחסות להפרה במסגרת פסיקת הוצאות (ת"א (מחוזי ת"א) 45320-07-19, ת"א (שלום נצרת) 34028-06-25).', 'ענייני אתיקה ← לרוב ללשכה ← ביהמ"ש יתערב אם פוגע בבעל דין/הליך ← להגנת הלקוח.',
    '["ת\"א (מחוזי ת\"א) 45320-07-19 טיטאן בניה בע\"מ נ'' ירון דיסקין (06.12.2020)", "ת\"א (שלום נצרת) 34028-06-25 ראני בדיר נ'' מדינת ישראל (25.02.2026)"]'::jsonb
  );
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_3, 'א', 'סמכות זו נתונה באופן בלעדי ללשכת עורכי הדין, ובית המשפט האזרחי אינו רשאי לדון בה.', false, 'טענה זו אינה נכונה. קיימים מקרים בהם בית המשפט האזרחי מוסמך לדון בסוגיות אתיות.', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_3, 'ב', 'בית המשפט האזרחי מוסמך לדון בטענות על הפרת כללי אתיקה, כאשר ההפרה פוגעת באחד מבעלי הדין או משפיעה על הגינות ההליך, ואף יכול ליתן צו בדבר הפסקת ייצוג.', true, 'זוהי התשובה הנכונה. הפסיקה קבעה כי בית המשפט רשאי להכריע בסוגיות אתיות מסוימות, במיוחד כאשר ההפרה פוגעת באחד מבעלי הדין או מכבידה על ההליך, וזאת על מנת להגן על הלקוח ועל הגינות ההליך.', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_3, 'ג', 'בית המשפט האזרחי מוסמך לדון בטענות על הפרת כללי אתיקה רק אם לשכת עורכי הדין העבירה אליו את הטיפול בעניין.', false, 'טענה זו אינה נכונה. סמכות בית המשפט אינה תלויה בהעברה מלשכת עורכי הדין, אלא בנסיבות המקרה והשפעת ההפרה על ההליך.', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_3, 'ד', 'בית המשפט האזרחי מוסמך לדון בטענות על הפרת כללי אתיקה רק אם מדובר בעבירה פלילית.', false, 'טענה זו אינה נכונה. סמכות בית המשפט לדון בענייני אתיקה אינה מוגבלת למקרים של עבירה פלילית, אלא חלה גם על הפרות אתיות המשפיעות על ההליך האזרחי.', 4);

  RAISE NOTICE 'Q% inserted: external_id %', 11, '2022-S-S-Q11';
END
$$;

-- ============================================================
-- Q12 — 2022-S-S-Q12 — chapter=administrative subtopic=constitutional_rights
-- classifier_note: Knesset amending Basic Law: State Economy via temporary provision — abuse-of-constituent-power doctrine
-- ============================================================
DO $$
DECLARE
  v_sq_id uuid := '60c4adbc-1ad7-4acf-a36e-3a1895109b09'::uuid;
  v_group_id uuid := '98e18836-2b2d-4a62-91e8-19f417222a27'::uuid;
  v_chapter_id uuid;
  v_subtopic_id uuid;
  v_existing_id uuid;
  v_ang_0 uuid := 'ce3800e0-7466-4aaa-a266-f53c09592f7a'::uuid;
  v_ang_1 uuid := '7d5f9002-4553-4369-831c-ae133309f6d7'::uuid;
  v_ang_2 uuid := '757406db-eb79-4710-8981-460102d6fcaa'::uuid;
  v_ang_3 uuid := '8ade893a-14ee-4e13-9349-b153dc850d7c'::uuid;
BEGIN
  SELECT id INTO v_existing_id FROM public.source_questions WHERE external_id = '2022-S-S-Q12';
  IF v_existing_id IS NOT NULL THEN
    RAISE NOTICE 'Q% skipped: external_id % already exists', 12, '2022-S-S-Q12';
    RETURN;
  END IF;

  SELECT id INTO v_chapter_id FROM public.chapters WHERE code = 'administrative';
  IF v_chapter_id IS NULL THEN
    RAISE EXCEPTION 'Chapter code % not found', 'administrative';
  END IF;

  SELECT id INTO v_subtopic_id FROM public.subtopics WHERE code = 'constitutional_rights' AND chapter_id = v_chapter_id;
  IF v_subtopic_id IS NULL THEN
    RAISE EXCEPTION 'Subtopic code % not found under chapter %', 'constitutional_rights', 'administrative';
  END IF;

  INSERT INTO public.source_questions (
    id, question_group_id, version, is_current, external_id, chapter_id, subtopic_id, question_text, source_metadata, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list, notes_for_admin, status, created_by
  ) VALUES (
    v_sq_id, v_group_id, 1, true,
    '2022-S-S-Q12', v_chapter_id, v_subtopic_id, 'בכוונת כנסת ישראל לתקן את חוק יסוד: משק המדינה באמצעות הוראת שעה. מה הדין?',
    '{"exam_year": 2022, "exam_season": "summer", "exam_part": 2, "exam_question_number": 12}'::jsonb, 'שאלה זו עוסקת בביקורת שיפוטית על חוקי יסוד, ובפרט בדוקטרינת ה''שימוש לרעה בסמכות המכוננת'' (Misuse of Constituent Power) כאשר הכנסת מתקנת חוק יסוד באמצעות הוראת שעה. היא בוחנת את גבולות סמכותה המכוננת של הכנסת ואת התנאים שבהם בית המשפט העליון יתערב בחקיקת יסוד.', 'הכלל הוא שחוק יסוד שנחקק כהוראת שעה אינו נפסל מעיקרו, אך השימוש בו אינו טבעי ודורש ריסון והצדקה מיוחדת (Reference 16, 24). בית המשפט העליון, בבג"ץ 5969/20 סתיו שפיר נ'' הכנסת (Reference 1, 25), קבע מבחן דו-שלבי לבחינת שימוש לרעה בסמכות המכוננת. השלב הראשון הוא ''שלב הזיהוי'', הבוחן אם חוק היסוד נושא מאפיינים צורניים וסימני היכר של נורמות חוקתיות, כגון יציבות, כלליות והתאמה למארג החוקתי (Reference 25). אם החוק אינו עומד במבחנים אלו, עובר הנטל בשלב השני, ''שלב הצידוק'', אל המשיבים להצביע על הצדקה מיוחדת לקביעת הסדר שאינו חוקתי באופיו במסגרת חוק יסוד (Reference 25). הפסיקה הדגישה כי הוראת שעה בחוק יסוד פוגעת במעמדם של חוקי היסוד ומוטב שייעשה בה שימוש במשורה, אם בכלל (Reference 16, 24, 28). במקרה שלפנינו, הכוונה לתקן את חוק יסוד: משק המדינה באמצעות הוראת שעה מחייבת עמידה במבחנים אלו, ודורשת הצדקה מיוחדת ושימוש במשורה, כדי שלא תיחשב כשימוש לרעה בסמכות המכוננת.', 'הנחה שגויה כי כל תיקון לחוק יסוד באמצעות הוראת שעה הוא פסול אוטומטית, או לחלופין, שהוא תמיד מותר ללא כל מגבלה או הצדקה.',
    '["חוק יסוד", "הוראת שעה", "סמכות מכוננת", "שימוש לרעה בסמכות המכוננת", "ביקורת שיפוטית", "מבחני זיהוי", "מבחן הצידוק", "התראת בטלות"]'::jsonb, '**וריאציה 1 — כלל הוראת שעה בחוק יסוד:** האם הוראת שעה יכולה להיות חלק מחוק יסוד? ← כן, אך השימוש בה אינו טבעי ודורש ריסון והצדקה מיוחדת (בג"ץ 5969/20 שפיר, פסקה 16 לחיות).
**וריאציה 2 — מטרת הוראת שעה:** מהי מטרת הוראת שעה בחוק יסוד? ← לתת מענה לנסיבות חריגות וזמניות, ולא לפתור קשיים פוליטיים קוניונקטורליים (בג"ץ 5969/20 שפיר, פסקה 49 לחיות).
**וריאציה 3 — תוצאות שימוש לרעה:** מה קורה במקרה של שימוש לרעה בהוראת שעה? ← בית המשפט יכול להוציא ''התראת בטלות'' או אף לבטל את התיקון (בג"ץ 5969/20 שפיר, פסקה 1 לחיות).', 'תיקון חוק יסוד בהוראת שעה ← אפשרי אך חריג ← דורש ריסון והצדקה מיוחדת ← אחרת שימוש לרעה בסמכות המכוננת.', '["חוק יסוד: משק המדינה", "בג\"ץ 5969/20 סתיו שפיר נ'' הכנסת (23.5.2021)", "בג\"ץ 8260/16 המרכז האקדמי למשפט ולעסקים נ'' כנסת ישראל (6.9.2017)", "בג\"ץ 4908/10 ח\"כ רוני בר-און נ'' כנסת ישראל, סד(3) 275 (7.4.2011)"]'::jsonb,
    'classification_review: original chapter=''חוקתי + בינלאומי פרטי'' subtopic=''ביטול סמכות בג"ץ'' → mapped chapter=''administrative'' subtopic=''constitutional_rights'' | classifier_note: Knesset amending Basic Law: State Economy via temporary provision — abuse-of-constituent-power doctrine | source_review_note: שאלה זו עוסקת בביקורת שיפוטית על חוקי יסוד ובדוקטרינת השימוש לרעה בסמכות המכוננת, תחום השייך למשפט חוקתי. סווגה תחת ''חוקתי + בינלאומי פרטי - ביטול סמכות בג"ץ'' כהצבת מקום בלבד, בהיעדר תת-נושא מדויק יותר ברשימה הקיימת.', 'active', 'b9ecdde2-d07e-4761-96ab-05f0ad32d4e3'
  );

  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'א', 'לא ניתן לתקן את חוק יסוד: משק המדינה באמצעות הוראת שעה.', false, 'טענה זו אינה נכונה. הפסיקה קבעה כי תיקון חוק יסוד באמצעות הוראת שעה אינו נפסל מעיקרו, אך השימוש בו צריך להיעשות במשורה ובהצדקה מיוחדת.', 1);
  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'ב', 'ניתן לתקן את חוק יסוד: משק המדינה באמצעות הוראת שעה גם אם אין הצדקה מיוחדת לתיקון משום שחוק יסוד: משק המדינה אינו משוריין ואינו כולל פסקת הגבלה.', false, 'טענה זו אינה נכונה. גם אם חוק יסוד אינו משוריין, השימוש בהוראת שעה לתיקונו דורש הצדקה מיוחדת, אחרת הוא עלול להיחשב כשימוש לרעה בסמכות המכוננת.', 2);
  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'ג', 'ניתן לתקן את חוק יסוד: משק המדינה באמצעות הוראת שעה גם אם אין הצדקה מיוחדת לתיקון, ובלבד שהוראת השעה תוגבל לפרק זמן של 12 חודשים.', false, 'טענה זו אינה נכונה. אין בחוק או בפסיקה קביעה גורפת המאפשרת תיקון חוק יסוד בהוראת שעה ללא הצדקה מיוחדת, גם אם היא מוגבלת בזמן. משך הזמן אינו התנאי היחיד.', 3);
  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'ד', 'ניתן לתקן סעיף בחוק יסוד: משק המדינה באמצעות הוראת שעה, ובלבד שהשימוש בה ייעשה במשורה ותהא לכך הצדקה מיוחדת.', true, 'זוהי התשובה הנכונה. הפסיקה קבעה כי תיקון חוק יסוד באמצעות הוראת שעה אינו נפסל מעיקרו, אך הוא חריג ודורש ריסון ו''הצדקה מיוחדת'' כדי שלא ייחשב כ''שימוש לרעה בסמכות המכוננת''.', 4);

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_0, v_sq_id, 'א', 'מבחני הזיהוי לשימוש לרעה בסמכות המכוננת',
    1, 'הכנסת חוקקה חוק יסוד חדש בשם "חוק יסוד: הסדרת ענייני הממשלה הזמנית", הקובע הוראות מפורטות ופרסונליות לגבי הרכב ממשלה מסוימת ותקופת כהונתה. מהי עמדת בית המשפט העליון לגבי חוק יסוד זה?', 'שאלה זו בוחנת את שלב ה''זיהוי'' במבחן הדו-שלבי לביקורת שיפוטית על חוקי יסוד מכוח דוקטרינת השימוש לרעה בסמכות המכוננת. היא מדגישה את חשיבות המאפיינים הצורניים והמהותיים של נורמה חוקתית, כגון כלליות ויציבות.', 'בבג"ץ 5969/20 סתיו שפיר נ'' הכנסת (Reference 1, 25), בית המשפט העליון קבע מבחן דו-שלבי לזיהוי שימוש לרעה בסמכות המכוננת. השלב הראשון, ''שלב הזיהוי'', בוחן אם חוק היסוד נושא את המאפיינים הצורניים וסימני ההיכר של נורמות חוקתיות. מבחני העזר כוללים: (1) **מבחן היציבות**: האם מדובר בהסדר קבע יציב הצופה פני עתיד? (2) **מבחן הכלליות**: האם מדובר בנורמה בעלת תחולה כללית ומופשטת, המתייחסת לקבוצה בלתי מסוימת, להבדיל מנורמה פרסונלית? (3) **מבחן ההתאמה למארג החוקתי**. חוק יסוד שהוא פרסונלי וזמני, כמו במקרה זה, אינו עומד במבחני הכלליות והיציבות (Reference 3, 20, 25). לכן, בית המשפט יקבע כי מדובר בשימוש לרעה בסמכות המכוננת.',
    'הנחה שגויה כי עצם הכותרת ''חוק יסוד'' מקנה חסינות מביקורת שיפוטית, או אי-הבחנה בין המבחן הצורני למבחני הזיהוי המהותיים יותר.', '["שימוש לרעה בסמכות המכוננת", "מבחני זיהוי", "כלליות", "יציבות", "מארג חוקתי", "חוק יסוד", "ביקורת שיפוטית"]'::jsonb, '**וריאציה 1 — מבחני זיהוי:** מהם מבחני הזיהוי לשימוש לרעה בסמכות המכוננת? ← יציבות, כלליות והתאמה למארג החוקתי (בג"ץ 5969/20 שפיר, פסקה 25 לחיות).
**וריאציה 2 — חוק פרסונלי:** האם חוק יסוד פרסונלי עומד במבחני הזיהוי? ← לא, הוא אינו עומד במבחן הכלליות (בג"ץ 5969/20 שפיר, פסקה 25 לחיות, פסקה 20 לברק-ארז בבג"ץ 2412/23).
**וריאציה 3 — חוק זמני:** האם חוק יסוד זמני עומד במבחני הזיהוי? ← לא, הוא אינו עומד במבחן היציבות (בג"ץ 5969/20 שפיר, פסקה 25 לחיות).', 'שימוש לרעה בסמכות המכוננת ← מבחן דו-שלבי ← שלב זיהוי: יציבות, כלליות, התאמה למארג החוקתי.',
    '["בג\"ץ 5969/20 סתיו שפיר נ'' הכנסת (23.5.2021)", "בג\"ץ 2412/23 התנועה למען איכות השלטון בישראל נ'' הכנסת (3.1.2024)"]'::jsonb
  );
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_0, 'א', 'בית המשפט יקבע כי החוק תקף, שכן הכנסת מוסמכת לחוקק חוקי יסוד בכל נושא שתבחר.', false, 'טענה זו אינה נכונה. סמכותה המכוננת של הכנסת אינה בלתי מוגבלת, והיא כפופה לביקורת שיפוטית מכוח דוקטרינת השימוש לרעה בסמכות המכוננת.', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_0, 'ב', 'בית המשפט יקבע כי החוק תקף, אך ימליץ לכנסת להימנע מחקיקה פרסונלית בעתיד.', false, 'טענה זו אינה נכונה. במקרה של חוק יסוד פרסונלי וזמני, בית המשפט לא יסתפק בהמלצה אלא יקבע כי מדובר בשימוש לרעה בסמכות המכוננת.', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_0, 'ג', 'בית המשפט יקבע כי מדובר בשימוש לרעה בסמכות המכוננת, שכן החוק אינו עומד במבחני הכלליות והיציבות הנדרשים מחוק יסוד.', true, 'זוהי התשובה הנכונה. לפי בג"ץ שפיר, חוק יסוד צריך לעמוד במבחני זיהוי הכוללים יציבות, כלליות והתאמה למארג החוקתי. חוק פרסונלי וזמני אינו עומד במבחנים אלו.', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_0, 'ד', 'בית המשפט יבטל את החוק באופן מיידי, שכן הוא פוגע בעקרון הפרדת הרשויות.', false, 'טענה זו אינה נכונה. אף אם מדובר בשימוש לרעה, הסעד אינו בהכרח ביטול מיידי, ולעיתים ניתן סעד של ''התראת בטלות''.', 4);

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_1, v_sq_id, 'ב', 'דוקטרינת התיקון החוקתי שאינו חוקתי',
    2, 'הכנסת חוקקה חוק יסוד חדש הקובע כי מדינת ישראל אינה מדינה דמוקרטית. האם בית המשפט העליון מוסמך לבטל חוק יסוד זה?', 'שאלה זו עוסקת בדוקטרינת ה''תיקון החוקתי שאינו חוקתי'' (Unconstitutional Constitutional Amendment), המאפשרת ביקורת שיפוטית על חוקי יסוד הפוגעים בליבת הדמוקרטיה או בערכי היסוד של השיטה. היא מבחינה בין ביקורת צורנית לביקורת מהותית על חוקי יסוד.', 'הפסיקה בישראל הכירה באפשרות להפעיל ביקורת שיפוטית ''תוכנית'' על חוקי יסוד מכוח דוקטרינת ה''תיקון החוקתי שאינו חוקתי'' (Reference 12, 32, 33). דוקטרינה זו קובעת כי תיקון חוקתי הפוגע במבנה הבסיסי של החוקה אינו חוקתי. הנשיא (בדימ'') אהרן ברק קבע כי הגבלה זו על כוחו של המחוקק חלה במקרים מיוחדים ויוצאי דופן שבהם השינוי החוקתי פוגע בליבת הדמוקרטיה ושולל את תכונות המינימום הדרושות למשטר דמוקרטי (Reference 32, 33). בית המשפט הבהיר כי הוא מוסמך לבחון אם תיקון לחוק יסוד שולל את אופייה של ישראל כמדינה יהודית או דמוקרטית, שכן העם, הריבון, לא הסמיך לכך את הכנסת (Reference 32, 33). במקרה זה, חוק יסוד הקובע שישראל אינה דמוקרטית פוגע בליבת הדמוקרטיה, ולכן בית המשפט מוסמך לבטלו.',
    'הנחה שגויה כי חוקי יסוד חסינים מביקורת שיפוטית מהותית, או בלבול בין דוקטרינה זו לבין דוקטרינת השימוש לרעה בסמכות המכוננת.', '["תיקון חוקתי שאינו חוקתי", "ביקורת שיפוטית", "חוק יסוד", "ליבת הדמוקרטיה", "ערכי יסוד", "סמכות מכוננת"]'::jsonb, '**וריאציה 1 — מהות הדוקטרינה:** מהי דוקטרינת התיקון החוקתי שאינו חוקתי? ← תיקון חוקתי הפוגע במבנה הבסיסי של החוקה אינו חוקתי (בג"ץ 5555/18 חסון, פסקה 11).
**וריאציה 2 — מתי תופעל?** ← במקרים מיוחדים ויוצאי דופן בהם השינוי פוגע בליבת הדמוקרטיה או שולל את תכונות המינימום הדרושות למשטר דמוקרטי (בג"ץ 5555/18 חסון, פסקה 11).
**וריאציה 3 — הבדל משימוש לרעה:** מה ההבדל בינה לבין שימוש לרעה בסמכות המכוננת? ← שימוש לרעה מתמקד בצורה ובתהליך, תיקון לא חוקתי בתוכן המהותי ובערכי היסוד (בג"ץ 5555/18 חסון, פסקה 11, 32).', 'תיקון חוקתי שאינו חוקתי ← ביקורת מהותית על חוקי יסוד ← פגיעה בליבת הדמוקרטיה/ערכי יסוד ← סמכות ביטול לביהמ"ש.',
    '["בג\"ץ 5555/18 ח\"כ אכרם חסון ו-11 אח'' נ'' כנסת ישראל (8.7.2021)", "בג\"ץ 6427/02 התנועה לאיכות השלטון בישראל נ'' הכנסת (11.5.2006)", "אהרן ברק, מבחר כתבים כרך ג עיונים חוקתיים (2017), עמ'' 157"]'::jsonb
  );
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_1, 'א', 'כן, מכוח דוקטרינת התיקון החוקתי שאינו חוקתי, המאפשרת ביקורת שיפוטית על תיקונים הפוגעים בליבת הדמוקרטיה או בערכי היסוד של השיטה.', true, 'זוהי התשובה הנכונה. הפסיקה הכירה באפשרות להפעיל ביקורת שיפוטית ''תוכנית'' על חוקי יסוד מכוח דוקטרינת התיקון החוקתי שאינו חוקתי, במקרים נדירים וקיצוניים של פגיעה בליבת הדמוקרטיה או בערכי היסוד של השיטה.', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_1, 'ב', 'לא, שכן חוק יסוד הוא הנורמה העליונה בשיטה המשפטית ואינו כפוף לביקורת שיפוטית מהותית.', false, 'טענה זו אינה נכונה. אף שחוק יסוד הוא נורמה עליונה, הפסיקה הכירה בסמכות בית המשפט לבקר אותו במקרים קיצוניים של פגיעה בערכי יסוד.', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_1, 'ג', 'לא, אלא אם כן חוק היסוד כולל פסקת הגבלה המאפשרת ביקורת שיפוטית.', false, 'טענה זו אינה נכונה. דוקטרינת התיקון החוקתי שאינו חוקתי אינה תלויה בקיומה של פסקת הגבלה בחוק היסוד הספציפי.', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_1, 'ד', 'כן, אך רק אם חוק היסוד נחקק ברוב רגיל ולא ברוב מיוחס.', false, 'טענה זו אינה נכונה. דוקטרינת התיקון החוקתי שאינו חוקתי מתייחסת לתוכן המהותי של התיקון, ולא לרוב שבו נחקק.', 4);

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_2, v_sq_id, 'ג', 'סעד ''התראת בטלות''',
    3, 'בית המשפט העליון קבע כי תיקון לחוק יסוד מהווה שימוש לרעה בסמכות המכוננת, אך במקום לבטל את התיקון באופן מיידי, הוא הוציא ''התראת בטלות''. מהי המשמעות של סעד זה?', 'שאלה זו עוסקת בסעד ה''התראת בטלות'' (Warning of Invalidity), שהוא סעד ייחודי שבית המשפט העליון נוקט במקרים של שימוש לרעה בסמכות המכוננת. היא מדגישה את אופיו הצופה פני עתיד של הסעד ואת מטרתו להרתיע מפני חזרה על הפרות חוקתיות.', 'סעד ה''התראת בטלות'' הוא סעד שבית המשפט העליון נוקט במקרים בהם הוא קובע כי נעשה שימוש לרעה בסמכות המכוננת, אך נמנע מלבטל את התיקון באופן מיידי (Reference 1, 4, 17, 24, 25). סעד זה צופה פני עתיד ומשמעותו היא שהתיקון הקיים נשאר בתוקפו, אך בית המשפט מזהיר כי אם הכנסת תחזור על תיקון דומה בעתיד, הוא צפוי להתבטל על פי ההתראה הנוכחית (Reference 1, 4, 25). סעד זה ניתן במיוחד במקרים של עתירות תיאורטיות, או כאשר מדובר בדפוס חוזר ונשנה של תיקונים זהים (כמו במקרה של התקציב הדו-שנתי), במטרה להבהיר את עמדת בית המשפט ולהרתיע מפני חזרה על הפרות חוקתיות (Reference 4, 17, 24).',
    'הנחה שגויה כי ''התראת בטלות'' משמעותה ביטול מיידי או ביטול עתידי מוחלט, מבלי להבין את אופיו המותנה והצופה פני עתיד של הסעד.', '["התראת בטלות", "שימוש לרעה בסמכות המכוננת", "סעד חוקתי", "ביקורת שיפוטית", "חוק יסוד", "עתירה תיאורטית"]'::jsonb, '**וריאציה 1 — מהות הסעד:** מהי ''התראת בטלות''? ← אזהרה שתיקון חוקתי דומה בעתיד יבוטל, מבלי לבטל את התיקון הקיים (בג"ץ 5969/20 שפיר, פסקה 1 לחיות).
**וריאציה 2 — מתי ניתן?** ← במקרים של שימוש לרעה בסמכות המכוננת, במיוחד בעתירות תיאורטיות או דפוס חוזר (בג"ץ 5969/20 שפיר, פסקה 4 למינץ).
**וריאציה 3 — תכלית הסעד:** מהי מטרת ''התראת בטלות''? ← להבהיר את עמדת בית המשפט ולהרתיע מפני חזרה על הפרות חוקתיות (בג"ץ 5969/20 שפיר, פסקה 4 למינץ).', '''התראת בטלות'' ← סעד צופה פני עתיד ← אזהרה מפני ביטול תיקון דומה ← במקרה של שימוש לרעה בסמכות המכוננת.',
    '["בג\"ץ 5969/20 סתיו שפיר נ'' הכנסת (23.5.2021)", "בג\"ץ 8260/16 המרכז האקדמי למשפט ולעסקים נ'' כנסת ישראל (6.9.2017)"]'::jsonb
  );
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_2, 'א', 'התיקון בטל באופן מיידי, אך הביטול נכנס לתוקף רק בעתיד.', false, 'טענה זו אינה נכונה. ''התראת בטלות'' אינה מבטלת את התיקון באופן מיידי, אלא מזהירה מפני ביטול עתידי אם יחזור על עצמו.', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_2, 'ב', 'התיקון נשאר בתוקפו, אך אם הכנסת תחזור על תיקון דומה בעתיד, הוא יבוטל באופן מיידי.', true, 'זוהי התשובה הנכונה. ''התראת בטלות'' היא סעד הצופה פני עתיד, המזהיר את הכנסת מפני ביטול תיקון דומה אם יחזור על עצמו, מבלי לבטל את התיקון הקיים.', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_2, 'ג', 'התיקון בטל, אך בית המשפט מאפשר לכנסת לתקן את הפגם בתוך פרק זמן מוגדר.', false, 'טענה זו אינה נכונה. ''התראת בטלות'' אינה מבטלת את התיקון ואינה קובעת פרק זמן לתיקון הפגם, אלא מזהירה מפני חזרה על המעשה.', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_2, 'ד', 'התיקון נשאר בתוקפו, ובית המשפט אינו מוסמך להתערב בו בעתיד.', false, 'טענה זו אינה נכונה. ''התראת בטלות'' היא אזהרה מפורשת מפני התערבות עתידית, והיא אינה שוללת את סמכות בית המשפט.', 4);

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_3, v_sq_id, 'ד', 'ביקורת שיפוטית על חוקים רגילים',
    4, 'הכנסת חוקקה חוק רגיל המגביל את חופש הביטוי. האם בית המשפט העליון מוסמך לבטל חוק זה, ומהם המבחנים שיפעיל?', 'שאלה זו עוסקת בהבחנה בין ביקורת שיפוטית על חוקי יסוד לבין ביקורת שיפוטית על חוקים רגילים. היא מתמקדת במבחנים החוקתיים המופעלים על חוקים רגילים הפוגעים בזכויות יסוד, ובפרט בפסקת ההגבלה ובמבחן המידתיות.', 'בית המשפט העליון מוסמך לבטל חוקים רגילים הפוגעים בזכויות יסוד המעוגנות בחוקי יסוד, כגון חוק יסוד: כבוד האדם וחירותו. ביקורת זו נעשית באמצעות ''פסקת ההגבלה'' הקבועה בסעיף 8 לחוק יסוד: כבוד האדם וחירותו (ובסעיף 4 לחוק יסוד: חופש העיסוק). פסקת ההגבלה קובעת כי אין פוגעים בזכויות אלו אלא בחוק ההולם את ערכיה של מדינת ישראל, שנועד לתכלית ראויה, ובמידה שאינה עולה על הנדרש (מבחן המידתיות). בג"ץ 5969/20 סתיו שפיר נ'' הכנסת (23.5.2021) דוקטרינת השימוש לרעה בסמכות המכוננת, לעומת זאת, חלה על חוקי יסוד, והמבחנים שונים (Reference 21).',
    'בלבול בין המבחנים החלים על ביקורת שיפוטית של חוקי יסוד (שימוש לרעה בסמכות המכוננת, תיקון חוקתי שאינו חוקתי) לבין המבחנים החלים על חוקים רגילים (פסקת ההגבלה, מידתיות).', '["ביקורת שיפוטית", "חוק רגיל", "פסקת ההגבלה", "מידתיות", "חוק יסוד: כבוד האדם וחירותו", "זכויות יסוד"]'::jsonb, '**וריאציה 1 — סמכות ביטול:** האם בית המשפט מוסמך לבטל חוק רגיל? ← כן, אם הוא פוגע בזכויות יסוד המעוגנות בחוקי יסוד (ע"א 6821/93 בנק המזרחי).
**וריאציה 2 — מבחני הביקורת:** מהם המבחנים לביטול חוק רגיל? ← עמידה בתנאי פסקת ההגבלה (הולם את ערכי ישראל, תכלית ראויה, מידתיות) (סעיף 8 לחוק יסוד: כבוד האדם וחירותו).
**וריאציה 3 — הבדל מחוק יסוד:** מה ההבדל בביקורת בין חוק רגיל לחוק יסוד? ← חוק רגיל נבחן לפי פסקת ההגבלה, חוק יסוד לפי דוקטרינת השימוש לרעה בסמכות המכוננת או התיקון החוקתי שאינו חוקתי (בג"ץ 2412/23 התנועה למען איכות השלטון, פסקה 30).', 'ביקורת על חוק רגיל ← פגיעה בזכויות יסוד ← מבחני פסקת ההגבלה ← מידתיות.',
    '["חוק יסוד: כבוד האדם וחירותו, סעיף 8", "ע\"א 6821/93 בנק המזרחי המאוחד בע\"מ נ'' מגדל כפר שיתופי, פ\"ד מט(4) 221 (1995)", "בג\"ץ 2412/23 התנועה למען איכות השלטון בישראל נ'' הכנסת (3.1.2024)"]'::jsonb
  );
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_3, 'א', 'לא, בית המשפט אינו מוסמך לבטל חוקים רגילים, אלא רק חוקי יסוד.', false, 'טענה זו אינה נכונה. בית המשפט מוסמך לבטל חוקים רגילים הפוגעים בזכויות יסוד המעוגנות בחוקי יסוד.', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_3, 'ב', 'כן, בית המשפט יבחן אם החוק עומד בתנאי פסקת ההגבלה שבחוק יסוד: כבוד האדם וחירותו, ובכלל זה מבחן המידתיות.', true, 'זוהי התשובה הנכונה. ביקורת שיפוטית על חוקים רגילים הפוגעים בזכויות יסוד נעשית באמצעות פסקת ההגבלה, הכוללת את מבחן המידתיות.', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_3, 'ג', 'כן, בית המשפט יבחן אם החוק מהווה שימוש לרעה בסמכות המחוקקת, בדומה לשימוש לרעה בסמכות המכוננת.', false, 'טענה זו אינה נכונה. דוקטרינת השימוש לרעה בסמכות המחוקקת שונה וצרה בהרבה מזו של הסמכות המכוננת, והמבחנים שונים.', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_3, 'ד', 'לא, אלא אם כן החוק פוגע בליבת אופייה של ישראל כמדינה יהודית ודמוקרטית.', false, 'טענה זו מתייחסת לדוקטרינת התיקון החוקתי שאינו חוקתי, החלה על חוקי יסוד, ולא על חוקים רגילים.', 4);

  RAISE NOTICE 'Q% inserted: external_id %', 12, '2022-S-S-Q12';
END
$$;

