-- classifier_note: Criminal compensation order for ₪300,000 to victim under פקודת העונשין
-- ============================================================
DO $$
DECLARE
  v_sq_id uuid := 'cdf7275d-ed3e-411a-bcb4-f894eeda73c1'::uuid;
  v_group_id uuid := 'd0351113-608a-4c2c-8de7-7a8d7f341004'::uuid;
  v_chapter_id uuid;
  v_subtopic_id uuid;
  v_existing_id uuid;
  v_ang_0 uuid := '3ff90cbc-8bd1-4da0-8199-3ed1ee3f5a54'::uuid;
  v_ang_1 uuid := 'e9b6812d-3742-46d2-9094-7b434f0823c1'::uuid;
  v_ang_2 uuid := 'e6c6ef30-733d-44e8-964f-e517943ac755'::uuid;
  v_ang_3 uuid := '99ab739a-19d7-420f-ac04-51fc2e8875d7'::uuid;
BEGIN
  SELECT id INTO v_existing_id FROM public.source_questions WHERE external_id = '2022-S-S-Q14';
  IF v_existing_id IS NOT NULL THEN
    RAISE NOTICE 'Q% skipped: external_id % already exists', 14, '2022-S-S-Q14';
    RETURN;
  END IF;

  SELECT id INTO v_chapter_id FROM public.chapters WHERE code = 'criminal_substantive';
  IF v_chapter_id IS NULL THEN
    RAISE EXCEPTION 'Chapter code % not found', 'criminal_substantive';
  END IF;

  SELECT id INTO v_subtopic_id FROM public.subtopics WHERE code = 'sentencing' AND chapter_id = v_chapter_id;
  IF v_subtopic_id IS NULL THEN
    RAISE EXCEPTION 'Subtopic code % not found under chapter %', 'sentencing', 'criminal_substantive';
  END IF;

  INSERT INTO public.source_questions (
    id, question_group_id, version, is_current, external_id, chapter_id, subtopic_id, question_text, source_metadata, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list, notes_for_admin, status, created_by
  ) VALUES (
    v_sq_id, v_group_id, 1, true,
    '2022-S-S-Q14', v_chapter_id, v_subtopic_id, 'פלוני הורשע בתקיפת קטינה, גרימת חבלה חמורה וסחיטה שלה. בגזר הדין נקבע כי עליו לשלם לקטינה פיצוי בסך מצטבר של 300,000 ש"ח. האם רשאי היה בית המשפט לעשות כן?',
    '{"exam_year": 2022, "exam_season": "summer", "exam_part": 2, "exam_question_number": 14}'::jsonb, 'שאלה זו עוסקת בסמכות בית המשפט לפסוק פיצויים לנפגעי עבירה בהליך הפלילי, ובפרט בשאלת תקרת הפיצויים לפי סעיף 77 לחוק העונשין, כאשר נאשם הורשע במספר עבירות. היא בוחנת את הפרשנות של הביטוי "בשל כל אחת מן העבירות שהורשע בהן" ומבהירה כי במקרה של ריבוי עבירות, ניתן לפסוק פיצוי עד התקרה הסטטוטורית בגין כל עבירה בנפרד.', 'סעיף 77(א) לחוק העונשין, תשל"ז-1977, קובע כי "הורשע אדם, רשאי בית המשפט לחייבו, בשל כל אחת מן העבירות שהורשע בהן, לשלם לאדם שניזוק על ידי העבירה סכום שלא יעלה על 258,000 שקלים חדשים לפיצוי הנזק או הסבל שנגרם לו". סעיף 77(א) לחוק העונשין, תשל"ז-1977 | פיצוי הפסיקה מפרשת לשון זו כך שהתקרה הסטטוטורית של 258,000 ש"ח חלה על כל עבירה בנפרד. כלומר, אם נאשם הורשע במספר עבירות, ניתן לפסוק פיצוי עד התקרה בגין כל אחת מהעבירות, ולכן סכום הפיצוי הכולל יכול לעלות על 258,000 ש"ח. דנ"פ 5625/16 אסרף קארין נ'' אבנר טווק בוקובזה (13.09.2017) תפ"ח (מחוזי ת"א) 6256-07-16 מדינת ישראל נ'' חאלד מחאמרה (29.11.2017) תפ"ח (מחוזי ת"א) 34198-06-18 מדינת ישראל נ'' פאדי מאלוק (14.12.2023) במקרה הנדון, פלוני הורשע בשלוש עבירות נפרדות (תקיפה, גרימת חבלה חמורה וסחיטה). לכן, בית המשפט רשאי היה לפסוק פיצוי עד 258,000 ש"ח בגין כל אחת מהעבירות, ובסך הכל סכום מצטבר של 300,000 ש"ח (לדוגמה, 100,000 ש"ח לכל עבירה).', 'הנחה שגויה כי תקרת הפיצוי בסעיף 77 לחוק העונשין היא סכום מקסימלי כולל לנאשם, ללא קשר למספר העבירות בהן הורשע.',
    '["פיצויים לנפגעי עבירה", "סעיף 77 לחוק העונשין", "תקרת פיצוי", "ריבוי עבירות", "גזר דין", "הליך פלילי"]'::jsonb, '**וריאציה 1 — ריבוי עבירות:** האם תקרת הפיצוי חלה על כל עבירה בנפרד? ← כן, לפי לשון סעיף 77(א) לחוק העונשין (דנ"פ 5625/16 טווק).
**וריאציה 2 — סכום מצטבר:** האם ניתן לפסוק סכום מצטבר העולה על 258,000 ש"ח? ← כן, אם הנאשם הורשע במספר עבירות (תפ"ח (מחוזי ת"א) 6256-07-16).
**וריאציה 3 — תכלית הפיצוי:** מהי תכלית הפיצוי במקרה של ריבוי עבירות? ← מתן סעד הולם לנפגע בגין כל נזק שנגרם לו כתוצאה מכל עבירה בנפרד (דנ"פ 5625/16 טווק).', 'פיצוי סעיף 77 ← תקרת 258,000 ש"ח ← לכל עבירה בנפרד ← סכום מצטבר יכול לעלות על התקרה.', '["חוק העונשין, תשל\"ז-1977, סעיף 77", "דנ\"פ 5625/16 אסרף קארין נ'' אבנר טווק בוקובזה (13.09.2017)", "תפ\"ח (מחוזי ת\"א) 6256-07-16 מדינת ישראל נ'' חאלד מחאמרה (29.11.2017)", "תפ\"ח (מחוזי ת\"א) 34198-06-18 מדינת ישראל נ'' פאדי מאלוק (14.12.2023)"]'::jsonb,
    'classification_review: original chapter=''סדר דין פלילי'' subtopic=''הליכים'' → mapped chapter=''criminal_substantive'' subtopic=''sentencing'' | classifier_note: Criminal compensation order for ₪300,000 to victim under פקודת העונשין', 'active', 'b9ecdde2-d07e-4761-96ab-05f0ad32d4e3'
  );

  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'א', 'לא, מכיוון שסכום המקסימום לפיצוי נפגע בהליך פלילי הוא 258,000 ש"ח.', false, 'טענה זו אינה נכונה. סעיף 77(א) לחוק העונשין קובע תקרת פיצוי של 258,000 ש"ח לכל עבירה בנפרד, ולכן במקרה של ריבוי עבירות, ניתן לפסוק סכום מצטבר העולה על תקרה זו.', 1);
  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'ב', 'כן, רק במקרה שההצמדה והריבית מיום ביצוע העבירה עולות על סכום של 42,000 ש"ח.', false, 'טענה זו אינה נכונה. סכום הפיצוי המצטבר יכול לעלות על התקרה בשל ריבוי עבירות, ללא קשר להצמדה וריבית, אם כי אלו נלקחים בחשבון בקביעת ערך הנזק.', 2);
  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'ג', 'לא, מכיוון שסכום המקסימום מתייחס לסכום שמוטל על נאשם.', false, 'טענה זו אינה נכונה. סעיף 77(א) לחוק העונשין קובע תקרת פיצוי לכל עבירה בנפרד, ולא סכום כולל לנאשם אחד בגין כל העבירות.', 3);
  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'ד', 'כן.', true, 'זוהי התשובה הנכונה. סעיף 77(א) לחוק העונשין מאפשר לבית המשפט לחייב נאשם בפיצוי "בשל כל אחת מן העבירות שהורשע בהן" בסכום שלא יעלה על 258,000 ש"ח. במקרה זה, הנאשם הורשע בשלוש עבירות נפרדות (תקיפה, חבלה חמורה, סחיטה), ולכן ניתן לפסוק פיצוי עד 258,000 ש"ח לכל עבירה, ובסך הכל סכום מצטבר העולה על 258,000 ש"ח.', 4);

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_0, v_sq_id, 'א', 'תקרת פיצוי לריבוי ניזוקים מעבירה אחת',
    1, 'נאשם הורשע בעבירת המתה אחת שגרמה למותה של אישה. לאישה היו שלושה ילדים. בית המשפט קבע כי על הנאשם לשלם פיצוי בסך 100,000 ש"ח לכל אחד מהילדים, ובסך הכל 300,000 ש"ח. האם רשאי היה בית המשפט לעשות כן?', 'שאלה זו בוחנת את הלכת דנ"פ 5625/16 אסרף קארין נ'' אבנר טווק בוקובזה, אשר קבעה כי במקרה של ריבוי ניזוקים עקיפים מעבירת המתה אחת, תקרת הפיצוי לפי סעיף 77 לחוק העונשין חלה על כלל הניזוקים יחד, ולא על כל אחד מהם בנפרד. זאת, בניגוד למצב של ריבוי עבירות.', 'הלכת דנ"פ 5625/16 אסרף קארין נ'' אבנר טווק בוקובזה (2017) קבעה כי כאשר מדובר בריבוי ניזוקים עקיפים (כגון בני משפחה של קורבן עבירת המתה) מעבירה אחת, סכום הפיצוי הכולל שניתן לפסוק לכולם יחד מוגבל לתקרה הסטטוטורית הקבועה בסעיף 77 לחוק העונשין (258,000 ש"ח). השופטת חיות (בדעת הרוב) נימקה זאת בכך שהתקרה נסבה על האדם הניזוק, אך לניזוקים עקיפים, כולם יחד, סכום שאינו עולה על התקרה. השופטת ברק-ארז (בדעת הרוב) הוסיפה כי התקרה מגבילה את סכום הפיצוי שניתן לפסוק לקרוביו של הקורבן שהיה הניזוק הישיר מהעבירה. לכן, במקרה זה, בית המשפט לא היה רשאי לפסוק סכום כולל של 300,000 ש"ח, אלא היה עליו להגביל את סך הפיצוי ל-258,000 ש"ח לכל הילדים יחד. דנ"פ 5625/16 אסרף קארין נ'' אבנר טווק בוקובזה (13.09.2017) ע"פ 1076/15 אבנר טווק נ'' מדינת ישראל (07.06.2016)',
    'הנחה שגויה כי תקרת הפיצוי חלה על כל ניזוק בנפרד גם במקרה של ריבוי ניזוקים עקיפים מעבירה אחת, בדומה לריבוי עבירות.', '["פיצויים לנפגעי עבירה", "סעיף 77 לחוק העונשין", "תקרת פיצוי", "ריבוי ניזוקים עקיפים", "עבירת המתה", "הלכת טווק"]'::jsonb, '**וריאציה 1 — ריבוי עבירות מול ריבוי ניזוקים:** האם תקרת הפיצוי זהה לריבוי עבירות ולריבוי ניזוקים מעבירה אחת? ← לא. לריבוי עבירות התקרה לכל עבירה, לריבוי ניזוקים עקיפים מעבירה אחת התקרה לכולם יחד (דנ"פ 5625/16 טווק).
**וריאציה 2 — ניזוקים עקיפים:** מי נחשבים ניזוקים עקיפים? ← בני משפחה של קורבן עבירת המתה (דנ"פ 5625/16 טווק).
**וריאציה 3 — סכום כולל:** מהו הסכום המקסימלי שניתן לפסוק לריבוי ניזוקים עקיפים מעבירה אחת? ← 258,000 ש"ח לכולם יחד (סעיף 77(א) לחוק העונשין, דנ"פ 5625/16 טווק).', 'ריבוי ניזוקים עקיפים (מעבירה אחת) ← תקרת פיצוי לכולם יחד ← 258,000 ש"ח (דנ"פ טווק).',
    '["חוק העונשין, תשל\"ז-1977, סעיף 77(א)", "דנ\"פ 5625/16 אסרף קארין נ'' אבנר טווק בוקובזה (13.09.2017)", "ע\"פ 1076/15 אבנר טווק נ'' מדינת ישראל (07.06.2016)"]'::jsonb
  );
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_0, 'א', 'כן, שכן כל ילד הוא ניזוק בפני עצמו וזכאי לפיצוי עד התקרה.', false, 'טענה זו אינה נכונה. הלכת דנ"פ טווק קבעה כי במקרה של ריבוי ניזוקים עקיפים מעבירת המתה אחת, סכום הפיצוי הכולל לכולם יחד מוגבל לתקרה הסטטוטורית.', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_0, 'ב', 'לא, שכן במקרה של ריבוי ניזוקים עקיפים מעבירת המתה אחת, סכום הפיצוי הכולל לכולם יחד מוגבל לתקרה הסטטוטורית של 258,000 ש"ח.', true, 'זוהי התשובה הנכונה. הלכת דנ"פ 5625/16 אסרף קארין נ'' אבנר טווק בוקובזה קבעה כי במקרה של ריבוי ניזוקים עקיפים מעבירת המתה אחת, סכום הפיצוי הכולל לכולם יחד מוגבל לתקרה הסטטוטורית הקבועה בסעיף 77 לחוק העונשין.', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_0, 'ג', 'כן, אך רק אם הילדים הם קטינים.', false, 'טענה זו אינה נכונה. גיל הניזוקים אינו משנה את תחולת הכלל לגבי תקרת הפיצוי לריבוי ניזוקים עקיפים מעבירה אחת.', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_0, 'ד', 'לא, אלא אם כן הילדים הוכיחו נזק ממוני העולה על 258,000 ש"ח.', false, 'טענה זו אינה נכונה. הפיצוי לפי סעיף 77 אינו דורש הוכחת נזק מדויקת, והמגבלה נובעת מהיותם ניזוקים עקיפים מאותה עבירה.', 4);

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_1, v_sq_id, 'ב', 'אופי הפיצוי לפי סעיף 77 ותכליותיו',
    2, 'מהו אופיו העיקרי של הפיצוי הנפסק לפי סעיף 77 לחוק העונשין, ומהן תכליותיו המרכזיות?', 'שאלה זו מתמקדת באופי ובתכליות הפיצוי לנפגעי עבירה בהליך הפלילי, כפי שנקבע בסעיף 77 לחוק העונשין. היא מדגישה את ההבחנה בין אופיו האזרחי המהותי של הפיצוי לבין היבטיו העונשיים והחברתיים, ואת מטרתו כסעד ראשוני ומהיר.', 'הפסיקה קבעה כי הפיצוי לפי סעיף 77 לחוק העונשין הוא בעל אופי אזרחי במהותו, אף שהוא ניתן במסגרת הליך פלילי. ת"א (שלום ת"א) 18218-08-13 עזבון המנוח ליו קאולין נ'' מ.י. דביר בע"מ (05.10.2016) ת"פ (שלום ת"א) 41095-10-16 פרקליטות מחוז תל אביב פלילי נ'' שרונה קלדרון (26.06.2022) תכליותיו המרכזיות הן מתן סעד מהיר ויעיל לנפגע העבירה, הכרה חברתית בסבלו, חיסכון בהליכים אזרחיים ארוכים ויקרים, ואף יסוד של היטהרות לעבריין. ת"פ (שלום ת"א) 63858-06-17 מדינת ישראל נ'' אריאל ברוכים (17.02.2019) תפ"ח (מחוזי ב"ש) 21274-12-15 מדינת ישראל נ'' יוסף אל מראוין (27.09.2016) ת"פ (שלום ב"ש) 55039-11-13 מדינת ישראל תביעות נגב נ'' פהמי בן עבדאללה אבו סריחאן (20.09.2015) תפח"ע (מחוזי מרכז) 40299-01-21 מדינת ישראל נ'' פלוני (11.01.2022)',
    'התייחסות לפיצוי לפי סעיף 77 כאל עונש בלבד, או כאל פיצוי מלא וממצה, מבלי להבין את אופיו המעורב והראשוני.', '["פיצויים לנפגעי עבירה", "סעיף 77 לחוק העונשין", "אופי אזרחי", "תכליות הפיצוי", "סעד מהיר", "היטהרות העבריין"]'::jsonb, '**וריאציה 1 — אופי הפיצוי:** מהו אופיו של הפיצוי לפי סעיף 77? ← אזרחי במהותו, אך עם היבטים עונשיים וחברתיים (דנ"פ 5625/16 טווק, ת"פ (שלום ת"א) 41095-10-16).
**וריאציה 2 — תכלית מרכזית:** מהי התכלית המרכזית של הפיצוי? ← מתן סעד מהיר ויעיל לנפגע, הכרה בסבלו וחיסכון בהליכים אזרחיים (דנ"פ 5625/16 טווק, ת"פ (שלום ת"א) 63858-06-17).
**וריאציה 3 — פיצוי מלא?** האם הפיצוי נועד להיות מלא? ← לא, הוא פיצוי ראשוני וחלקי, ואינו ממצה את הסעדים האזרחיים (ע"פ 7186/19 קטמור טובי, ת"פ (מחוזי מרכז) 40299-01-21).', 'פיצוי סעיף 77 ← אופי אזרחי (עם היבטים עונשיים) ← סעד מהיר, הכרה בסבל, חיסכון בהליכים ← אינו פיצוי מלא.',
    '["חוק העונשין, תשל\"ז-1977, סעיף 77", "דנ\"פ 5625/16 אסרף קארין נ'' אבנר טווק בוקובזה (13.09.2017)", "ת\"פ (שלום ת\"א) 63858-06-17 מדינת ישראל נ'' אריאל ברוכים (17.02.2019)", "תפח\"ע (מחוזי מרכז) 40299-01-21 מדינת ישראל נ'' פלוני (11.01.2022)", "ת\"פ (שלום ב\"ש) 55039-11-13 מדינת ישראל תביעות נגב נ'' פהמי בן עבדאללה אבו סריחאן (20.09.2015)", "ת\"פ (שלום ת\"א) 18218-08-13 עזבון המנוח ליו קאולין נ'' מ.י. דביר בע\"מ (05.10.2016)", "ע\"פ 7186/19 קטמור טובי נ'' מדינת ישראל (08.01.2020)"]'::jsonb
  );
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_1, 'א', 'אופי עונשי בלבד, שמטרתו להעניש את העבריין ולהרתיע עבריינים אחרים.', false, 'טענה זו אינה נכונה. אף שלפיצוי יש היבטים עונשיים, אופיו העיקרי הוא אזרחי, והוא נועד לפצות את הנפגע.', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_1, 'ב', 'אופי אזרחי במהותו, שמטרתו העיקרית היא מתן סעד מהיר ויעיל לנפגע העבירה, הכרה בסבלו וחיסכון בהליכים אזרחיים.', true, 'זוהי התשובה הנכונה. הפסיקה קבעה כי הפיצוי לפי סעיף 77 הוא בעל אופי אזרחי במהותו, ונועד להעניק סעד מהיר ויעיל לנפגע, להכיר בסבלו ולחסוך ממנו את הצורך בהליך אזרחי נפרד.', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_1, 'ג', 'אופי מעורב (אזרחי ועונשי), אך מטרתו העיקרית היא להבטיח פיצוי מלא לנפגע העבירה.', false, 'טענה זו אינה נכונה. הפיצוי לפי סעיף 77 אינו נועד להבטיח פיצוי מלא, אלא פיצוי ראשוני וחלקי, ואינו ממצה את הסעדים האזרחיים.', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_1, 'ד', 'אופי אזרחי, אך הוא ניתן רק במקרים בהם הנפגע אינו יכול להגיש תביעה אזרחית.', false, 'טענה זו אינה נכונה. הפיצוי לפי סעיף 77 ניתן גם אם הנפגע יכול להגיש תביעה אזרחית, והוא אינו חוסם את האפשרות לתביעה אזרחית.', 4);

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_2, v_sq_id, 'ג', 'התחשבות ביכולת כלכלית של הנאשם',
    3, 'בית המשפט דן בגזר דינו של נאשם שהורשע בעבירת אלימות חמורה. הנאשם טוען כי מצבו הכלכלי קשה ביותר וכי חיובו בפיצוי בסכום גבוה יפגע קשות ביכולתו לשיקום. האם בית המשפט רשאי להתחשב במצבו הכלכלי של הנאשם בעת קביעת גובה הפיצוי לפי סעיף 77 לחוק העונשין?', 'שאלה זו עוסקת בשיקולים לקביעת גובה הפיצוי לפי סעיף 77 לחוק העונשין, ובפרט בשאלה האם יש להתחשב במצבו הכלכלי של הנאשם. הפסיקה קבעה באופן עקבי כי שיקול זה אינו רלוונטי לקביעת גובה הפיצוי, אלא רק לערך הנזק שנגרם לנפגע.', 'הפסיקה קבעה באופן עקבי כי מצבו ויכולתו הכלכלית של הנאשם אינם מהווים שיקול בקביעת שיעור הפיצוי לפי סעיף 77 לחוק העונשין. ת"פ (שלום ת"א) 63858-06-17 מדינת ישראל נ'' אריאל ברוכים (17.02.2019) ת"פ (שלום ב"ש) 55039-11-13 מדינת ישראל תביעות נגב נ'' פהמי בן עבדאללה אבו סריחאן (20.09.2015) ת"פ (מחוזי מרכז) 53824-12-16 מדינת ישראל נ'' יחיאל פרץ (28.06.2018) זאת, משום שאופי הפיצוי הוא אזרחי, וגובהו נגזר מערך הנזק או הסבל שנגרמו לנפגע, ולא מיכולת התשלום של העבריין. תפ"ח (מחוזי ב"ש) 21274-12-15 מדינת ישראל נ'' יוסף אל מראוין (27.09.2016) דנ"פ 5625/16 אסרף קארין נ'' אבנר טווק בוקובזה (13.09.2017) עם זאת, מצבו הכלכלי של הנאשם יכול להילקח בחשבון בהקשר של הסדרי גבייה, כגון פריסת תשלומים, אך לא בקביעת עצם גובה הפיצוי. תפ"ח (מחוזי ב"ש) 21274-12-15 מדינת ישראל נ'' יוסף אל מראוין (27.09.2016)',
    'הנחה שגויה כי יש להתחשב ביכולת הכלכלית של הנאשם בקביעת גובה הפיצוי, בדומה לשיקולים אחרים בגזר הדין.', '["פיצויים לנפגעי עבירה", "סעיף 77 לחוק העונשין", "מצב כלכלי של נאשם", "גובה פיצוי", "אופי אזרחי", "שיקולי גבייה"]'::jsonb, '**וריאציה 1 — שיקול כלכלי:** האם מצב כלכלי של נאשם רלוונטי לקביעת גובה הפיצוי? ← לא, הפיצוי נגזר מהנזק לנפגע (דנ"פ 5625/16 טווק, ת"פ (שלום ב"ש) 55039-11-13).
**וריאציה 2 — גבייה מול קביעה:** מתי מצב כלכלי רלוונטי? ← בהסדרי גבייה (פריסת תשלומים), לא בקביעת הסכום עצמו (תפ"ח (מחוזי ב"ש) 21274-12-15).
**וריאציה 3 — אופי הפיצוי:** מדוע אין מתחשבים במצב כלכלי? ← כי הפיצוי הוא אזרחי במהותו, ולא עונשי (ת"פ (שלום ת"א) 63858-06-17).', 'מצב כלכלי של נאשם ← אינו שיקול בקביעת גובה פיצוי סעיף 77 ← רלוונטי רק לגבייה.',
    '["חוק העונשין, תשל\"ז-1977, סעיף 77", "דנ\"פ 5625/16 אסרף קארין נ'' אבנר טווק בוקובזה (13.09.2017)", "ת\"פ (שלום ת\"א) 63858-06-17 מדינת ישראל נ'' אריאל ברוכים (17.02.2019)", "תפ\"ח (מחוזי ב\"ש) 21274-12-15 מדינת ישראל נ'' יוסף אל מראוין (27.09.2016)", "ת\"פ (שלום ב\"ש) 55039-11-13 מדינת ישראל תביעות נגב נ'' פהמי בן עבדאללה אבו סריחאן (20.09.2015)", "ת\"פ (מחוזי מרכז) 53824-12-16 מדינת ישראל נ'' יחיאל פרץ (28.06.2018)"]'::jsonb
  );
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_2, 'א', 'כן, מצבו הכלכלי של הנאשם הוא שיקול מרכזי בקביעת גובה הפיצוי, שכן יש לו השלכה על יכולת הגבייה ועל שיקום הנאשם.', false, 'טענה זו אינה נכונה. הפסיקה קבעה כי מצבו הכלכלי של הנאשם אינו שיקול בקביעת גובה הפיצוי, שכן הפיצוי הוא אזרחי במהותו ונגזר מהנזק שנגרם לנפגע.', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_2, 'ב', 'לא, הפסיקה קבעה באופן עקבי כי מצבו הכלכלי של הנאשם אינו שיקול בקביעת שיעור הפיצוי, אלא גובה הנזק שנגרם לנפגע.', true, 'זוהי התשובה הנכונה. הפסיקה קבעה כי הפיצוי לפי סעיף 77 הוא אזרחי במהותו, ולכן גובהו נגזר מערך הנזק או הסבל שנגרמו לנפגע, ולא מיכולתו הכלכלית של הנאשם.', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_2, 'ג', 'כן, אך רק אם הנאשם הציג ראיות מוצקות למצבו הכלכלי הקשה.', false, 'טענה זו אינה נכונה. גם אם יוצגו ראיות, מצבו הכלכלי של הנאשם אינו שיקול בקביעת גובה הפיצוי, אלא לכל היותר בהסדרי הגבייה.', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_2, 'ד', 'לא, אלא אם כן מדובר בפיצוי סמלי בלבד.', false, 'טענה זו אינה נכונה. הכלל לפיו אין מתחשבים במצב הכלכלי של הנאשם חל על כל סכום פיצוי, ולא רק על פיצוי סמלי.', 4);

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_3, v_sq_id, 'ד', 'יחס בין פיצוי פלילי לתביעה אזרחית',
    4, 'נפגע עבירה קיבל פיצוי בסך 200,000 ש"ח במסגרת ההליך הפלילי לפי סעיף 77 לחוק העונשין. האם הוא רשאי להגיש תביעה אזרחית נגד העבריין בגין אותם נזקים?', 'שאלה זו עוסקת ביחס שבין פיצוי שנפסק בהליך פלילי לפי סעיף 77 לחוק העונשין לבין זכותו של נפגע העבירה להגיש תביעה אזרחית. היא מדגישה כי הפיצוי הפלילי הוא סעד ראשוני וחלקי, ואינו חוסם את הדרך לתביעה אזרחית מלאה.', 'הפיצוי הנפסק לפי סעיף 77 לחוק העונשין הוא פיצוי ראשוני וחלקי, ואינו ממצה את הסעדים האזרחיים. תפח"ע (מחוזי מרכז) 40299-01-21 מדינת ישראל נ'' פלוני (11.01.2022) ע"פ 7186/19 קטמור טובי נ'' מדינת ישראל (08.01.2020) נפגע העבירה רשאי להגיש תביעה אזרחית בגין מלוא נזקיו, תוך ניכוי הסכום שכבר קיבל בהליך הפלילי. ע"פ 2796/23 שמעון לוי נ'' מדינת ישראל (17.04.2024) ע"א 6485/18 מדינת ישראל נ'' פלוני (26.12.2019) תפ"ח (מחוזי ב"ש) 35903-08-19 מדינת ישראל נ'' סנאד אלקאדי (24.03.2021) הפיצוי הפלילי נועד לספק ''עזרה ראשונה'' לנפגע, ולא למנוע ממנו את זכותו לפיצוי מלא בהליך האזרחי. ת"פ (שלום ת"א) 63858-06-17 מדינת ישראל נ'' אריאל ברוכים (17.02.2019)',
    'הנחה שגויה כי קבלת פיצוי בהליך הפלילי מהווה ויתור על הזכות לתבוע פיצויים נוספים בהליך אזרחי.', '["פיצויים לנפגעי עבירה", "סעיף 77 לחוק העונשין", "תביעה אזרחית", "פיצוי ראשוני", "ניכוי", "כפל פיצוי"]'::jsonb, '**וריאציה 1 — פיצוי ממצה:** האם פיצוי פלילי ממצה את הנזק? ← לא, הוא פיצוי ראשוני וחלקי (ע"פ 7186/19 קטמור טובי).
**וריאציה 2 — תביעה אזרחית:** האם ניתן להגיש תביעה אזרחית לאחר פיצוי פלילי? ← כן, בגין מלוא הנזקים, בניכוי הסכום שכבר נפסק (ע"פ 2796/23 שמעון לוי).
**וריאציה 3 — מטרת ההפרדה:** מדוע קיימת הפרדה בין הפיצויים? ← כדי להבטיח סעד מהיר לנפגע בהליך הפלילי, מבלי לפגוע בזכותו לפיצוי מלא בהליך האזרחי (ע"א 6485/18 מדינת ישראל נ'' פלוני).', 'פיצוי פלילי (סעיף 77) ← ראשוני וחלקי ← אינו מונע תביעה אזרחית ← בניכוי הסכום שכבר התקבל.',
    '["חוק העונשין, תשל\"ז-1977, סעיף 77", "ע\"פ 2796/23 שמעון לוי נ'' מדינת ישראל (17.04.2024)", "תפח\"ע (מחוזי מרכז) 40299-01-21 מדינת ישראל נ'' פלוני (11.01.2022)", "ע\"פ 7186/19 קטמור טובי נ'' מדינת ישראל (08.01.2020)", "ע\"א 6485/18 מדינת ישראל נ'' פלוני (26.12.2019)", "תפ\"ח (מחוזי ב\"ש) 35903-08-19 מדינת ישראל נ'' סנאד אלקאדי (24.03.2021)", "ת\"פ (שלום ת\"א) 63858-06-17 מדינת ישראל נ'' אריאל ברוכים (17.02.2019)"]'::jsonb
  );
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_3, 'א', 'לא, הפיצוי בהליך הפלילי ממצה את זכותו לפיצוי בגין אותם נזקים.', false, 'טענה זו אינה נכונה. הפיצוי לפי סעיף 77 הוא פיצוי ראשוני וחלקי, ואינו ממצה את הסעדים האזרחיים.', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_3, 'ב', 'כן, הפיצוי בהליך הפלילי הוא פיצוי ראשוני וחלקי, ואינו מונע הגשת תביעה אזרחית בגין מלוא הנזקים, בניכוי הסכום שכבר נפסק.', true, 'זוהי התשובה הנכונה. הפיצוי לפי סעיף 77 אינו ממצה את הסעדים האזרחיים, והנפגע רשאי להגיש תביעה אזרחית בגין מלוא נזקיו, תוך ניכוי הסכום שכבר קיבל בהליך הפלילי.', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_3, 'ג', 'לא, אלא אם כן הפיצוי בהליך הפלילי היה נמוך מ-50,000 ש"ח.', false, 'טענה זו אינה נכונה. אין קשר בין סכום הפיצוי שנפסק בהליך הפלילי לבין הזכות להגיש תביעה אזרחית, למעט ניכוי הסכום שכבר התקבל.', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_3, 'ד', 'כן, אך רק אם התביעה האזרחית תוגש בתוך 30 יום מיום מתן גזר הדין הפלילי.', false, 'טענה זו אינה נכונה. אין מגבלת זמן מיוחדת להגשת תביעה אזרחית לאחר פיצוי פלילי, למעט תקופת ההתיישנות הרגילה.', 4);

  RAISE NOTICE 'Q% inserted: external_id %', 14, '2022-S-S-Q14';
END
$$;

-- ============================================================
-- Q15 — 2022-S-S-Q15 — chapter=criminal_substantive subtopic=general_part_elements  [needs_review]
-- classifier_note: Criminal statute of limitations on prosecution (Almoni at 33 alleging assault at 15) — no dedicated 'criminal limitation' subtopic; general_part is the closest
-- ============================================================
DO $$
DECLARE
  v_sq_id uuid := '634b9bfc-7a15-4ea4-8a5a-f189260a5ad3'::uuid;
  v_group_id uuid := 'a094ab30-760d-4e99-885e-c6c108d37a6d'::uuid;
  v_chapter_id uuid;
  v_subtopic_id uuid;
  v_existing_id uuid;
  v_ang_0 uuid := 'f1b7ba1c-4a60-49a8-809e-0e77bce982c7'::uuid;
  v_ang_1 uuid := '9012260e-01c1-4eaa-b50d-b5919e0521fc'::uuid;
  v_ang_2 uuid := '51e41d9c-09c7-4cae-b91a-9df75c510aba'::uuid;
  v_ang_3 uuid := '03bb196f-b559-462a-99d4-ce21a024bc54'::uuid;
BEGIN
  SELECT id INTO v_existing_id FROM public.source_questions WHERE external_id = '2022-S-S-Q15';
  IF v_existing_id IS NOT NULL THEN
    RAISE NOTICE 'Q% skipped: external_id % already exists', 15, '2022-S-S-Q15';
    RETURN;
  END IF;

  SELECT id INTO v_chapter_id FROM public.chapters WHERE code = 'criminal_substantive';
  IF v_chapter_id IS NULL THEN
    RAISE EXCEPTION 'Chapter code % not found', 'criminal_substantive';
  END IF;

  SELECT id INTO v_subtopic_id FROM public.subtopics WHERE code = 'general_part_elements' AND chapter_id = v_chapter_id;
  IF v_subtopic_id IS NULL THEN
    RAISE EXCEPTION 'Subtopic code % not found under chapter %', 'general_part_elements', 'criminal_substantive';
  END IF;

  INSERT INTO public.source_questions (
    id, question_group_id, version, is_current, external_id, chapter_id, subtopic_id, question_text, source_metadata, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list, notes_for_admin, status, created_by
  ) VALUES (
    v_sq_id, v_group_id, 1, true,
    '2022-S-S-Q15', v_chapter_id, v_subtopic_id, 'אלמוני הגיש בגיל 33 תלונה, ולפיה בהיותו בן 15 ביצע בו בן משפחה בגיר מעשה סדום. 3 חודשים אחר כך מבקשת הפרקליטות להגיש כתב אישום בעבירה לפי סעיף 351(א) לחוק העונשין. האם ניתן לעשות זאת?',
    '{"exam_year": 2022, "exam_season": "summer", "exam_part": 2, "exam_question_number": 15}'::jsonb, 'שאלה זו עוסקת בהוראות ההתיישנות המיוחדות לעבירות מין שבוצעו בקטינים, כפי שנקבעו בסעיף 354 לחוק העונשין. היא מתמקדת במקרה של עבירה שבוצעה על ידי בן משפחה, ומחייבת הבנה של מועד תחילת מניין תקופת ההתיישנות (גיל 28) וכן את הדרישה לאישור היועץ המשפטי לממשלה כאשר חלפו למעלה מעשר שנים מיום ביצוע העבירה בפועל.', 'סעיף 354(א) לחוק העונשין, תשל"ז-1977, קובע כי בעבירות מין המנויות בו (ובכללן מעשה סדום), שנעברו בקטין על ידי בן משפחתו או האחראי עליו, יחל מניין תקופת ההתיישנות ביום שמלאו לקטין עשרים ושמונה שנים. ע"פ 7015/09 פלוני נ'' מדינת ישראל (18.11.2012) ע"פ 5582/09 פלוני נ'' מדינת ישראל (20.10.2010) תקופת ההתיישנות לעבירת פשע היא 10 שנים (סעיף 9(א)(2) לחוק סדר הדין הפלילי). במקרה הנדון, אלמוני היה בן 15 בעת ביצוע העבירה, ולכן הגיע לגיל 28 שלוש עשרה שנים לאחר מכן (בגיל 28). ממועד זה ועד הגשת התלונה בגיל 33 חלפו 5 שנים בלבד (33-28=5). מאחר שטרם חלפו 10 שנים ממועד תחילת מניין ההתיישנות המיוחד (גיל 28), העבירה לא התיישנה. ע"פ 2790/13 פלוני נ'' מדינת ישראל (08.09.2014) עם זאת, סעיף 354(א) קובע סייג נוסף: "ואולם אם חלפו עשר שנים מיום ביצוע העבירה לא יוגש כתב אישום אלא באישור היועץ המשפטי לממשלה". במקרה זה, מיום ביצוע העבירה (גיל 15) ועד הגשת התלונה (גיל 33) חלפו 18 שנים. מאחר שחלפו למעלה מעשר שנים מיום ביצוע העבירה בפועל, הגשת כתב אישום דורשת את אישור היועץ המשפטי לממשלה. ע"פ 6734/16 פלוני נ'' מדינת ישראל (25.10.2017)', 'אי-הבחנה בין מועד תחילת מניין תקופת ההתיישנות המוארכת (גיל 28) לבין הדרישה לאישור היועץ המשפטי לממשלה כאשר חלפו 10 שנים מיום ביצוע העבירה בפועל.',
    '["התיישנות עבירות מין", "סעיף 354 לחוק העונשין", "קטין", "בן משפחה", "אישור היועץ המשפטי לממשלה", "חישוב תקופות"]'::jsonb, '**וריאציה 1 — מועד תחילת התיישנות:** מתי מתחילה תקופת ההתיישנות בעבירת מין בקטין על ידי בן משפחה? ← ביום שמלאו לקטין 28 שנים (סעיף 354(א) לחוק העונשין).
**וריאציה 2 — דרישת אישור:** מתי נדרש אישור היועץ המשפטי לממשלה? ← אם חלפו עשר שנים מיום ביצוע העבירה בפועל (סעיף 354(א) לחוק העונשין).
**וריאציה 3 — חישוב משולב:** עבירה בגיל 15, תלונה בגיל 33. האם התיישנה? ← לא, חלפו 5 שנים מיום שהגיע לגיל 28, אך נדרש אישור היועמ"ש כי חלפו 18 שנים מיום ביצוע העבירה (סעיף 354(א) לחוק העונשין).', 'עבירת מין (בן משפחה) ← התיישנות מתחילה בגיל 28 ← נדרש אישור יועמ"ש אם חלפו 10 שנים מיום ביצוע העבירה בפועל.', '["חוק העונשין, תשל\"ז-1977, סעיף 354(א)", "חוק סדר הדין הפלילי [נוסח משולב], תשמ\"ב-1982, סעיף 9(א)(2)", "ע\"פ 7015/09 פלוני נ'' מדינת ישראל (18.11.2012)", "ע\"פ 5582/09 פלוני נ'' מדינת ישראל (20.10.2010)", "ע\"פ 2790/13 פלוני נ'' מדינת ישראל (08.09.2014)", "ע\"פ 6734/16 פלוני נ'' מדינת ישראל (25.10.2017)"]'::jsonb,
    'needs_review=true | classification_review: original chapter=''סדר דין פלילי'' subtopic=''הליכים'' → mapped chapter=''criminal_substantive'' subtopic=''general_part_elements'' | classifier_note: Criminal statute of limitations on prosecution (Almoni at 33 alleging assault at 15) — no dedicated ''criminal limitation'' subtopic; general_part is the closest | source_review_note: השאלה עוסקת בהתיישנות עבירות פליליות, תחום השייך לסדר דין פלילי. עם זאת, אף אחד מתת-הנושאים הקיימים תחת ''סדר דין פלילי'' אינו מתאים באופן ישיר ל''התיישנות עבירות''. ''הליכים'' הוא תת-הנושא הכללי ביותר תחת ''סדר דין אזרחי'', אך השאלה היא פלילית. בחרתי ב''הליכים'' תחת ''סדר דין פלילי'' כהצבת מקום, למרות ש''הליכים'' אינו תת-נושא מפורש ברשימה עבור סדר דין פלילי, וזאת כדי לשמור על הקטגוריה הנכונה של דין פלילי. יש לשקול הוספת תת-נושא ''התיישנות עבירות'' או ''הליכים כלליים'' תחת סדר דין פלילי.', 'active', 'b9ecdde2-d07e-4761-96ab-05f0ad32d4e3'
  );

  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'א', 'לא, העבירה התיישנה.', false, 'טענה זו אינה נכונה. לפי סעיף 354(א) לחוק העונשין, מניין תקופת ההתיישנות בעבירות מין שבוצעו בקטין על ידי בן משפחה יחל רק ביום שמלאו לקטין 28 שנים. במקרה זה, חלפו 5 שנים בלבד ממועד זה, וטרם חלפו 10 שנות ההתיישנות.', 1);
  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'ב', 'לא, מכיוון שעברו למעלה מ-7 שנים מיום שהפך אלמוני לבגיר.', false, 'טענה זו אינה נכונה. תקופת ההתיישנות המיוחדת לעבירות מין בקטינים על ידי בן משפחה מתחילה בגיל 28, ולא בגיל 18 (בגרות).', 2);
  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'ג', 'כן, בכפוף לאישור היועץ המשפטי לממשלה.', true, 'זוהי התשובה הנכונה. לפי סעיף 354(א) לחוק העונשין, מניין תקופת ההתיישנות יחל ביום שמלאו לקטין 28 שנים. במקרה זה, אלמוני בן 33, כך שחלפו 5 שנים ממועד תחילת ההתיישנות המיוחדת, וטרם חלפו 10 שנים. עם זאת, מאחר שחלפו למעלה מעשר שנים מיום ביצוע העבירה בפועל (33-15=18 שנים), הגשת כתב אישום דורשת את אישור היועץ המשפטי לממשלה.', 3);
  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'ד', 'כן, ללא מגבלות.', false, 'טענה זו אינה נכונה. אף שהעבירה לא התיישנה, חלפו למעלה מעשר שנים מיום ביצועה בפועל, ולכן נדרש אישור היועץ המשפטי לממשלה להגשת כתב האישום.', 4);

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_0, v_sq_id, 'א', 'התיישנות עבירות מין בקטין שלא בן משפחה',
    1, 'אלמוני הגיש בגיל 33 תלונה, ולפיה בהיותו בן 15 ביצע בו אדם זר מעשה סדום. 3 חודשים אחר כך מבקשת הפרקליטות להגיש כתב אישום בעבירה לפי סעיף 351(א) לחוק העונשין. האם ניתן לעשות זאת?', 'שאלה זו בוחנת את ההבחנה בין הוראות ההתיישנות המיוחדות לעבירות מין בקטינים, כאשר העבירה בוצעה על ידי בן משפחה/אחראי (סעיף 354(א) לחוק העונשין) לבין כאשר בוצעה על ידי אדם שאינו בן משפחה/אחראי (סעיף 354(ג) לחוק העונשין). ההבדל המהותי הוא במועד תחילת מניין תקופת ההתיישנות.', 'סעיף 354 לחוק העונשין קובע הוראות התיישנות מיוחדות לעבירות מין בקטינים. סעיף 354(ג)(1) לחוק העונשין, הרלוונטי למקרה זה (כאשר הפוגע אינו בן משפחה או אחראי), קובע כי מניין תקופת ההתיישנות יחל ביום שמלאו לקטין שמונה עשרה שנים. תקופת ההתיישנות לעבירת פשע היא 10 שנים (סעיף 9(א)(2) לחוק סדר הדין הפלילי). במקרה הנדון, אלמוני היה בן 15 בעת ביצוע העבירה, ולכן הגיע לגיל 18 שלוש שנים לאחר מכן, בגיל 18. ממועד זה ועד הגשת התלונה בגיל 33 חלפו 15 שנים (33-18=15). מאחר שחלפו למעלה מ-10 שנים ממועד תחילת מניין ההתיישנות המיוחד (גיל 18), העבירה התיישנה. ע"פ 7211/13 פלוני נ'' מדינת ישראל (13.12.2015) ע"פ 2790/13 פלוני נ'' מדינת ישראל (08.09.2014)',
    'בלבול בין הוראות ההתיישנות השונות בסעיף 354 לחוק העונשין, והחלת הוראת סעיף 354(א) (גיל 28) גם על מקרים שבהם הפוגע אינו בן משפחה או אחראי.', '["התיישנות עבירות מין", "סעיף 354 לחוק העונשין", "קטין", "בן משפחה", "אחראי", "אישור היועץ המשפטי לממשלה"]'::jsonb, '**וריאציה 1 — פוגע זר:** מתי מתחילה ההתיישנות בעבירת מין בקטין על ידי אדם זר? ← בגיל 18 (סעיף 354(ג) לחוק העונשין).
**וריאציה 2 — חישוב התיישנות:** אם העבירה בוצעה בגיל 15 והתלונה בגיל 33, האם התיישנה? ← כן, חלפו 15 שנים מיום שהגיע לגיל 18, יותר מ-10 שנות ההתיישנות לפשע.
**וריאציה 3 — אישור יועמ"ש:** האם אישור היועמ"ש יכול להחיות עבירה שהתיישנה? ← לא, אישור היועמ"ש רלוונטי רק אם טרם חלפה תקופת ההתיישנות המוארכת (סעיף 354(ג) לחוק העונשין).', 'עבירת מין בקטין (פוגע זר) ← התיישנות מתחילה בגיל 18 ← תקופה 10 שנים ← במקרה זה התיישנה.',
    '["חוק העונשין, תשל\"ז-1977, סעיף 354(ג)", "חוק סדר הדין הפלילי [נוסח משולב], תשמ\"ב-1982, סעיף 9(א)(2)", "ע\"פ 7211/13 פלוני נ'' מדינת ישראל (13.12.2015)", "ע\"פ 2790/13 פלוני נ'' מדינת ישראל (08.09.2014)"]'::jsonb
  );
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_0, 'א', 'לא, העבירה התיישנה.', true, 'זוהי התשובה הנכונה. במקרה של עבירות מין בקטין שלא על ידי בן משפחה או אחראי, לפי סעיף 354(ג) לחוק העונשין, מניין תקופת ההתיישנות יחל ביום שמלאו לקטין 18 שנים. במקרה זה, חלפו 15 שנים ממועד זה (33-18=15), ולכן העבירה התיישנה, שכן תקופת ההתיישנות לפשע היא 10 שנים.', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_0, 'ב', 'כן, בכפוף לאישור היועץ המשפטי לממשלה.', false, 'טענה זו אינה נכונה. אישור היועץ המשפטי לממשלה נדרש אם חלפו 10 שנים מיום ביצוע העבירה אך טרם חלפה תקופת ההתיישנות המוארכת. במקרה זה, תקופת ההתיישנות כבר חלפה.', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_0, 'ג', 'כן, ללא מגבלות.', false, 'טענה זו אינה נכונה. העבירה התיישנה, ולכן לא ניתן להגיש כתב אישום.', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_0, 'ד', 'לא, מכיוון שסעיף 351(א) לחוק העונשין אינו חל על עבירות שבוצעו על ידי אדם זר.', false, 'טענה זו אינה נכונה. סעיף 351(א) אכן מתייחס לעבירות מין במשפחה, אך השאלה מתמקדת בהתיישנות. גם אם סעיף אחר היה חל, העבירה הייתה מתיישנת לפי סעיף 354(ג).', 4);

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_1, v_sq_id, 'ב', 'קטיעת מירוץ ההתיישנות',
    2, 'אלמוני הגיש תלונה על מעשה סדום שבוצע בו על ידי בן משפחה בגיל 15. חקירה נפתחה בגין עבירה זו. במהלך החקירה, נחשפו עובדות נוספות המצביעות על מעשים מגונים שבוצעו באלמוני על ידי אותו בן משפחה כשהיה בן 12. האם פתיחת החקירה בגין מעשה הסדום קטעה את מירוץ ההתיישנות גם לגבי המעשים המגונים?', 'שאלה זו עוסקת בדוקטרינת קטיעת מירוץ ההתיישנות בהליך הפלילי, ובפרט בהחלתה על עבירות מין בקטינים. היא מדגישה את הגישה המרחיבה של הפסיקה, לפיה פתיחת חקירה בגין עבירה אחת יכולה לקטוע את מירוץ ההתיישנות גם לעבירות קשורות שנחשפות במהלכה, וזאת לאור אופיין המיוחד של עבירות מין והקושי בדיווח מוקדם.', 'סעיף 9(ג) לחוק סדר הדין הפלילי קובע כי מירוץ ההתיישנות נקטע עם פתיחת חקירה. הפסיקה הרחיבה את תחולת כלל זה וקבעה כי פתיחת חקירה נגד נאשם על בסיס חשד לביצוע עבירה אחת, אשר במהלכה נחשפות עובדות נוספות המחשידות אותו בביצוע עבירה אחרת הקשורה לעבירה בגינה נפתחה החקירה, קוטעת את מירוץ ההתיישנות גם לעניין העבירה האחרת. ע"פ 7015/09 פלוני נ'' מדינת ישראל (18.11.2012) זאת, כדי לאפשר את בירור האמת וכדי להתמודד עם אופי עבירות המין בקטינים והדיווח המאוחר עליהן. ע"פ 7015/09 פלוני נ'' מדינת ישראל (18.11.2012) במקרה זה, המעשים המגונים נחשפו במהלך החקירה בגין מעשה הסדום, והם קשורים לאותו פוגע ולאותו נפגע, ולכן פתיחת החקירה קטעה את מירוץ ההתיישנות גם לגביהם.',
    'הנחה שגויה כי קטיעת מירוץ ההתיישנות חלה רק על העבירה הספציפית שבגינה נפתחה החקירה, מבלי להבין את הגישה המרחיבה של הפסיקה בעבירות מין.', '["קטיעת מירוץ התיישנות", "התיישנות עבירות מין", "חוק סדר הדין הפלילי", "חקירה פלילית", "עבירות קשורות", "דיווח מאוחר"]'::jsonb, '**וריאציה 1 — היקף הקטיעה:** האם חקירה על עבירה אחת קוטעת התיישנות לעבירות קשורות? ← כן, אם הן נחשפות במהלכה (ע"פ 7015/09 פלוני נ'' מדינת ישראל).
**וריאציה 2 — רציונל:** מדוע הכלל רחב? ← כדי להתמודד עם אופי עבירות המין והדיווח המאוחר (ע"פ 7015/09 פלוני נ'' מדינת ישראל).
**וריאציה 3 — סעיף רלוונטי:** איזה סעיף בחוק סדר הדין הפלילי עוסק בקטיעת התיישנות? ← סעיף 9(ג) לחוק סדר הדין הפלילי.', 'פתיחת חקירה ← קוטעת התיישנות ← גם לעבירות קשורות שנחשפות ← במיוחד בעבירות מין.',
    '["חוק סדר הדין הפלילי [נוסח משולב], תשמ\"ב-1982, סעיף 9(ג)", "ע\"פ 7015/09 פלוני נ'' מדינת ישראל (18.11.2012)"]'::jsonb
  );
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_1, 'א', 'לא, קטיעת מירוץ ההתיישנות חלה רק על העבירה שבגינה נפתחה החקירה במקור.', false, 'טענה זו אינה נכונה. הפסיקה קבעה כי פתיחת חקירה קוטעת את מירוץ ההתיישנות גם לעבירות קשורות שנחשפות במהלכה.', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_1, 'ב', 'כן, פתיחת חקירה בגין עבירה אחת קוטעת את מירוץ ההתיישנות גם לעניין עבירות אחרות הקשורות אליה ונחשפות במהלכה.', true, 'זוהי התשובה הנכונה. לפי הפסיקה, פתיחת חקירה נגד נאשם על בסיס חשד לביצוע עבירה אחת, אשר במהלכה נחשפות עובדות נוספות המחשידות אותו בביצוע עבירה אחרת הקשורה לעבירה בגינה נפתחה החקירה, קוטעת את מירוץ ההתיישנות גם לעניין העבירה האחרת.', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_1, 'ג', 'לא, אלא אם כן המעשים המגונים בוצעו באותה מסכת עובדתית כמו מעשה הסדום.', false, 'טענה זו אינה נכונה. הכלל רחב יותר ואינו מוגבל לאותה מסכת עובדתית, אלא לעבירות קשורות שנחשפות במהלך החקירה.', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_1, 'ד', 'כן, אך רק אם המעשים המגונים הם מסוג פשע ולא עוון.', false, 'טענה זו אינה נכונה. סעיף 9(ג) לחוק סדר הדין הפלילי חל הן על פשע והן על עוון.', 4);

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_2, v_sq_id, 'ג', 'התיישנות עבירות מין שבוצעו לפני תיקון 47',
    3, 'אלמוני הגיש בגיל 33 תלונה, ולפיה בהיותו בן 10, בשנת 1990, ביצע בו בן משפחה בגיר מעשה סדום. 3 חודשים אחר כך מבקשת הפרקליטות להגיש כתב אישום בעבירה לפי סעיף 351(א) לחוק העונשין. האם ניתן לעשות זאת?', 'שאלה זו בוחנת את תחולתם הרטרואקטיבית של תיקוני החקיקה בסעיף 354 לחוק העונשין, שהאריכו את תקופת ההתיישנות בעבירות מין בקטינים. היא מדגישה את העיקרון לפיו הוראות התיישנות, בהיותן דיוניות, חלות על עבירות שטרם התיישנו במועד כניסתן לתוקף, ומחייבת חישוב מדויק של תקופות הזמן הרלוונטיות.', 'העבירה בוצעה בשנת 1990, כאשר אלמוני היה בן 10. לפני תיקון 47 (1996), תקופת ההתיישנות לפשע הייתה 10 שנים מיום ביצוע העבירה, כלומר עד שנת 2000. תיקון 47 (1996) קבע כי מניין תקופת ההתיישנות יחל בגיל 18. תיקון זה חל על עבירות שטרם התיישנו במועד כניסתו לתוקף (19.1.1996). מאחר שעד 1996 חלפו 6 שנים בלבד מיום ביצוע העבירה (1990), העבירה לא התיישנה, ותיקון 47 חל עליה. לפי תיקון 47, מניין ההתיישנות יחל בגיל 18 (בשנת 1998). תיקון 72 (2002) האריך את מניין תקופת ההתיישנות לגיל 28. תיקון זה חל על עבירות שטרם התיישנו במועד כניסתו לתוקף (20.11.2002). מאחר שעד 2002 חלפו 4 שנים בלבד מיום שהגיע אלמוני לגיל 18 (1998), העבירה לא התיישנה, ותיקון 72 חל עליה. לפי תיקון 72, מניין ההתיישנות יחל בגיל 28 (בשנת 2008). התלונה הוגשה בשנת 2020, כלומר 12 שנים לאחר שהגיע אלמוני לגיל 28. תקופת ההתיישנות לפשע היא 10 שנים, ולכן העבירה לא התיישנה (היא תתיישן בגיל 38, כלומר בשנת 2018). עם זאת, מאחר שחלפו למעלה מעשר שנים מיום ביצוע העבירה בפועל (1990-2020 = 30 שנים), הגשת כתב אישום דורשת את אישור היועץ המשפטי לממשלה. ע"פ 7015/09 פלוני נ'' מדינת ישראל (18.11.2012) ע"פ 5582/09 פלוני נ'' מדינת ישראל (20.10.2010) ע"פ 10189/02 פלוני נ'' מדינת ישראל (19.09.2005)',
    'אי-הבנה של תחולתם הרטרואקטיבית של תיקוני חוק העונשין בעניין התיישנות עבירות מין, או חישוב שגוי של תקופות הזמן הרלוונטיות.', '["התיישנות עבירות מין", "תיקוני חקיקה", "רטרואקטיביות", "סעיף 354 לחוק העונשין", "אישור היועץ המשפטי לממשלה", "חישוב תקופות"]'::jsonb, '**וריאציה 1 — תחולת תיקונים:** האם תיקוני חוק העונשין בעניין התיישנות חלים רטרואקטיבית? ← כן, על עבירות שטרם התיישנו במועד כניסתם לתוקף (ע"פ 7097/08 פלוני נ'' מדינת ישראל, פסקה 6).
**וריאציה 2 — חישוב התיישנות:** עבירה ב-1990 (גיל 10), תלונה ב-2020 (גיל 33). האם התיישנה? ← לא, מניין ההתיישנות מתחיל בגיל 28 (2008), ועד 2020 חלפו 12 שנים, פחות מ-10 שנות ההתיישנות המוארכת (סעיף 354(א) לחוק העונשין).
**וריאציה 3 — אישור יועמ"ש:** האם נדרש אישור היועמ"ש? ← כן, כי חלפו למעלה מ-10 שנים מיום ביצוע העבירה בפועל (30 שנה) (סעיף 354(א) לחוק העונשין).', 'עבירת מין (בן משפחה) לפני תיקונים ← חלים תיקונים רטרואקטיבית ← התיישנות מתחילה בגיל 28 ← נדרש אישור יועמ"ש אם חלפו 10 שנים מיום ביצוע העבירה.',
    '["חוק העונשין, תשל\"ז-1977, סעיף 354(א)", "ע\"פ 7015/09 פלוני נ'' מדינת ישראל (18.11.2012)", "ע\"פ 5582/09 פלוני נ'' מדינת ישראל (20.10.2010)", "ע\"פ 10189/02 פלוני נ'' מדינת ישראל (19.09.2005)", "ע\"פ 7097/08 פלוני נ'' מדינת ישראל (06.09.2010)"]'::jsonb
  );
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_2, 'א', 'לא, העבירה התיישנה, שכן חלפו למעלה מ-10 שנים מיום שהגיע אלמוני לגיל 28.', false, 'טענה זו אינה נכונה. אלמוני הגיע לגיל 28 בשנת 2008 (1990+18), והתלונה הוגשה בשנת 2020. חלפו 12 שנים ממועד זה, אך תקופת ההתיישנות המוארכת היא 10 שנים מיום שהגיע לגיל 28, כלומר עד גיל 38. לכן, העבירה לא התיישנה.', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_2, 'ב', 'כן, בכפוף לאישור היועץ המשפטי לממשלה.', true, 'זוהי התשובה הנכונה. העבירה בוצעה בשנת 1990. תיקון 47 (1996) ותיקון 72 (2002) האריכו את תקופת ההתיישנות לעבירות מין בקטינים על ידי בן משפחה, כך שמניין התקופה יחל בגיל 28. אלמוני הגיע לגיל 28 בשנת 2008. התלונה הוגשה בשנת 2020, כלומר 12 שנים לאחר שהגיע לגיל 28. מאחר שחלפו למעלה מ-10 שנים מיום ביצוע העבירה בפועל (1990-2020 = 30 שנים), נדרש אישור היועץ המשפטי לממשלה.', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_2, 'ג', 'לא, מכיוון שתיקוני החקיקה בעניין התיישנות עבירות מין אינם חלים רטרואקטיבית.', false, 'טענה זו אינה נכונה. תיקוני החקיקה בעניין התיישנות עבירות מין חלים רטרואקטיבית על עבירות שטרם התיישנו במועד כניסתם לתוקף.', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_2, 'ד', 'כן, ללא מגבלות.', false, 'טענה זו אינה נכונה. אף שהעבירה לא התיישנה, חלפו למעלה מ-10 שנים מיום ביצועה בפועל, ולכן נדרש אישור היועץ המשפטי לממשלה.', 4);

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_3, v_sq_id, 'ד', 'השפעת חלוף הזמן על הענישה',
    4, 'נאשם הורשע בעבירות מין חמורות שביצע בבן משפחה קטין. העבירות בוצעו לפני 20 שנה, והנאשם טוען כי חלוף הזמן הרב מאז ביצוע העבירות צריך להוות שיקול משמעותי לקולא בגזר דינו. מהי עמדת בית המשפט העליון בעניין זה?', 'שאלה זו עוסקת בשיקולי הענישה בעבירות מין בקטינים, ובפרט במשקל שיש ליתן לחלוף הזמן הרב ממועד ביצוע העבירה. הפסיקה מדגישה כי אף שחלוף הזמן יכול להוות שיקול לקולא, משקלו מוגבל מאוד בעבירות אלו, וזאת לאור תכלית הארכת תקופת ההתיישנות והחומרה היתרה של הפגיעה בקורבנות.', 'בית המשפט העליון קבע באופן עקבי כי בעבירות מין בקטינים, ובמיוחד בתוך המשפחה, יש ליתן משקל מוגבל בלבד לשיקול בדבר חלוף השנים מאז בוצעו העבירות. ע"פ 5167/22 פלוני נ'' מדינת ישראל (26.01.2023) ע"פ 4327/12 פלוני נ'' מדינת ישראל (05.06.2013) תפ"ח (מחוזי באר שבע) 69430-07-20 מדינת ישראל נ'' פלוני (02.05.2022) הרציונל לכך הוא שהמחוקק עצמו נתן דעתו לתופעת הדיווח המאוחר של קורבנות קטינים על מעשים אלו, ומשום כך האריך באופן חריג את תקופת ההתיישנות. הימנעות מהטלת עונש מאסר בפועל או הקלה משמעותית בעונש רק משום חלוף הזמן אינה עולה בקנה אחד עם מטרת הארכה זו. ע"פ 5167/22 פלוני נ'' מדינת ישראל (26.01.2023) ע"פ 6092/10 פלוני נ'' מדינת ישראל (18.07.2012)',
    'הנחה שגויה כי חלוף הזמן הוא שיקול משמעותי לקולא בעבירות מין, בדומה לעבירות אחרות, מבלי להבין את המדיניות השיפוטית הייחודית בתחום זה.', '["שיקולי ענישה", "חלוף זמן", "עבירות מין בקטינים", "עבירות מין במשפחה", "התיישנות", "עדות כבושה"]'::jsonb, '**וריאציה 1 — משקל חלוף הזמן:** מה משקל חלוף הזמן בענישה על עבירות מין בקטינים? ← משקל מוגבל בלבד (ע"פ 5167/22 פלוני נ'' מדינת ישראל, פסקה 32).
**וריאציה 2 — רציונל המחוקק:** מדוע משקל חלוף הזמן מוגבל? ← המחוקק האריך את תקופת ההתיישנות מתוך הכרה בקושי בדיווח המאוחר (ע"פ 5167/22 פלוני נ'' מדינת ישראל, פסקה 32).
**וריאציה 3 — מסר חברתי:** מה המסר החברתי בעניין זה? ← ''עבר זמנו לא בטל קרבנו'' (ע"פ 6092/10 פלוני נ'' מדינת ישראל, פסקה 2).', 'עבירות מין בקטינים ← חלוף זמן ← שיקול מוגבל לקולא ← לאור הארכת התיישנות ותכליתה.',
    '["ע\"פ 5167/22 פלוני נ'' מדינת ישראל (26.01.2023)", "ע\"פ 4327/12 פלוני נ'' מדינת ישראל (05.06.2013)", "ע\"פ 6092/10 פלוני נ'' מדינת ישראל (18.07.2012)", "תפ\"ח (מחוזי באר שבע) 69430-07-20 מדינת ישראל נ'' פלוני (02.05.2022)"]'::jsonb
  );
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_3, 'א', 'חלוף הזמן הוא שיקול מכריע לקולא, שכן הוא פוגע ביכולת הנאשם להתגונן ומהווה סבל בפני עצמו.', false, 'טענה זו אינה נכונה. הפסיקה קבעה כי לחלוף הזמן משקל מוגבל בלבד בעבירות מין בקטינים, ואינו שיקול מכריע.', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_3, 'ב', 'לחלוף הזמן משקל מוגבל בלבד, שכן המחוקק האריך את תקופת ההתיישנות בעבירות אלו מתוך הכרה בתופעת הדיווח המאוחר, ואין בכך כדי להפחית מחומרת המעשים.', true, 'זוהי התשובה הנכונה. הפסיקה קבעה כי בעבירות מין בקטינים, ובמיוחד במשפחה, לחלוף הזמן משקל מוגבל בלבד בגזירת העונש, וזאת לאור תכלית הארכת תקופת ההתיישנות והחומרה היתרה של עבירות אלו.', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_3, 'ג', 'חלוף הזמן אינו רלוונטי כלל לענישה, שכן הפיצוי לנפגע הוא הסעד העיקרי.', false, 'טענה זו אינה נכונה. חלוף הזמן יכול להילקח בחשבון כשיקול לקולא, אך משקלו מוגבל, והוא אינו קשור לפיצוי לנפגע.', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_3, 'ד', 'חלוף הזמן הוא שיקול לקולא רק אם הנאשם הביע חרטה ולקח אחריות על מעשיו.', false, 'טענה זו אינה נכונה. חרטה ולקיחת אחריות הם שיקולים נפרדים לקולא, שאינם תלויים בחלוף הזמן, אם כי הם יכולים לחזק את המשקל המוגבל של חלוף הזמן.', 4);

  RAISE NOTICE 'Q% inserted: external_id %', 15, '2022-S-S-Q15';
END
$$;

