-- classifier_note: Lawyer witnessed bank robbery, robber spoke to her personally — privilege scope vs duty to testify
-- ============================================================
DO $$
DECLARE
  v_sq_id uuid := 'b8e22004-fbd5-4e0e-afc1-a8d5663caa1a'::uuid;
