  INSERT INTO public.source_questions (
    id, question_group_id, version, is_current, external_id, chapter_id, subtopic_id, question_text, source_metadata, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list, notes_for_admin, status, created_by
  ) VALUES (
    v_sq_id, v_group_id, 1, true,
    '2022-S-S-Q16', v_chapter_id, v_subtopic_id, 'עורכת דין נקלעה לשוד בנק כשהלכה לפתוח חשבון נאמנות עבור לקוח. במהלך השוד אמר לה השודד כמה דברים באופן אישי. כעת זימנה המשטרה את עורכת הדין לתת עדות במסגרת החקירה. האם היא רשאית להעיד על הדברים שאמר לה השודד?',
    '{"exam_year": 2022, "exam_season": "summer", "exam_part": 2, "exam_question_number": 16}'::jsonb, 'שאלה זו עוסקת בהיקף תחולתו של חיסיון עורך דין-לקוח, כפי שמעוגן בסעיף 48 לפקודת הראיות ובסעיף 90 לחוק לשכת עורכי הדין. היא בוחנת את התנאים המצטברים לתחולת החיסיון, ובפרט את הדרישה לקשר ענייני לשירות המקצועי ואת העובדה שהמידע צריך להיות מוחלף בין עורך הדין ללקוחו או למי מטעמו.', 'חיסיון עורך דין-לקוח הוא חיסיון סטטוטורי המעוגן בסעיף 48(א) לפקודת הראיות [נוסח חדש], תשל"א-1971, ובסעיף 90 לחוק לשכת עורכי הדין, תשכ"א-1961. פקודת הראיות [נוסח חדש], תשל"א-1971 | עדות עורך דין 48 סעיף חוק לשכת עורכי הדין, תשכ"א-1961 | סוד מקצועי 90 סעיף תכליתו של החיסיון היא לאפשר תקשורת פתוחה וגלויה בין עורך דין ללקוחו, ובכך ליצור מערכת יחסים מקצועית ויחסי אמון המבטיחים ייצוג הולם והוגן. ת"א (מחוזי מרכז) 30195-04-19 בועז בנרוש נ'' שי לבנת (24.05.2020) החיסיון חל על "דברים ומסמכים שהוחלפו בין עורך דין לבין לקוחו או לבין אדם אחר מטעם הלקוח ויש להם קשר ענייני לשירות המקצועי שניתן על ידי עורך הדין ללקוח". ת"א (מחוזי ת"א) 45320-07-19 טיטאן בניה בע"מ נ'' ירון דיסקין (01.01.2023) במקרה הנדון, השודד אינו הלקוח של עורכת הדין, וגם אינו אדם אחר הפועל מטעם הלקוח. דבריו של השודד לעורכת הדין אינם חלק מהשירות המקצועי שהיא מעניקה ללקוחה. לכן, אין קשר ענייני בין דברי השודד לשירות המקצועי הניתן ללקוח, וחיסיון עורך דין-לקוח אינו חל על דברים אלו. עורכת הדין רשאית להעיד עליהם. ת"א (שלום קריות) 717-03-14 פלוני נ'' מקאם נביא זכריה - הקדש דתי (ווקף) (25.06.2019)', 'הנחה שגויה כי כל מידע שעורך דין נחשף אליו במהלך פעילות מקצועית, גם אם ממקור חיצוני שאינו הלקוח, חוסה תחת חיסיון עורך דין-לקוח.',
    '["חיסיון עורך דין-לקוח", "פקודת הראיות", "חוק לשכת עורכי הדין", "קשר ענייני לשירות המקצועי", "צד שלישי", "זהות הלקוח"]'::jsonb, '**וריאציה 1 — מקור המידע:** האם מידע שהתקבל מצד שלישי שאינו הלקוח חסוי? ← לא, אלא אם הצד השלישי פועל מטעם הלקוח (סעיף 48(א) לפקודת הראיות).
**וריאציה 2 — תנאי החיסיון:** מהם התנאים לתחולת חיסיון עורך דין-לקוח? ← דברים/מסמכים שהוחלפו בין עו"ד ללקוח (או מטעמו) + קשר ענייני לשירות המקצועי (סעיף 48(א) לפקודת הראיות).
**וריאציה 3 — תכלית החיסיון:** מהי תכלית חיסיון עורך דין-לקוח? ← לאפשר תקשורת פתוחה וגלויה בין עו"ד ללקוח לייצוג הולם (רע"פ 751/15 אברג''יל, פסקה 23).', 'חיסיון עו"ד-לקוח ← חל על מידע שהוחלף בין עו"ד ללקוח (או מטעמו) ← קשר ענייני לשירות מקצועי ← לא חל על מידע מצד שלישי שאינו הלקוח.', '["פקודת הראיות [נוסח חדש], תשל\"א-1971, סעיף 48", "חוק לשכת עורכי הדין, תשכ\"א-1961, סעיף 90", "רע\"פ 751/15 יצחק אברג''יל נ'' מדינת ישראל (09.12.2015)", "ת\"א (מחוזי מרכז) 30195-04-19 בועז בנרוש נ'' שי לבנת (24.05.2020)", "ת\"א (שלום קריות) 717-03-14 פלוני נ'' מקאם נביא זכריה - הקדש דתי (ווקף) (25.06.2019)", "ת\"א (מחוזי ת\"א) 45320-07-19 טיטאן בניה בע\"מ נ'' ירון דיסקין (01.01.2023)"]'::jsonb,
    'needs_review=true | classification_review: original chapter=''דיני ראיות'' subtopic=''קבילות ראיות'' → mapped chapter=''ethics'' subtopic=''fiduciary_privilege_conflict'' | classifier_note: Lawyer witnessed bank robbery, robber spoke to her personally — privilege scope vs duty to testify', 'active', 'b9ecdde2-d07e-4761-96ab-05f0ad32d4e3'
  );

  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'א', 'כן, ובלבד שהשודד אינו לקוח שלה.', true, 'זוהי התשובה הנכונה. חיסיון עורך דין-לקוח חל על דברים ומסמכים שהוחלפו בין עורך דין ללקוחו או לבין אדם אחר מטעם הלקוח, ושיש להם קשר ענייני לשירות המקצועי. השודד אינו לקוח ואינו פועל מטעמו, ולכן דבריו אינם חסויים.', 1);
  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'ב', 'לא, מכיוון שהיא שהתה בבנק במסגרת ביצוע שירות מקצועי.', false, 'טענה זו אינה נכונה. עצם היותה של עורכת הדין במסגרת שירות מקצועי אינו הופך כל מידע שהיא קולטת מצד שלישי שאינו הלקוח לחסוי. החיסיון חל על חילופי דברים עם הלקוח או מי מטעמו.', 2);
  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'ג', 'כן, מכיוון שמדובר בפשע חמור.', false, 'טענה זו אינה נכונה. חומרת העבירה אינה משפיעה על תחולת חיסיון עורך דין-לקוח, אלא על חריגים אחרים לחיסיון (כגון ייעוץ לביצוע עבירה עתידית), שאינם רלוונטיים למקרה זה.', 3);
  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'ד', 'לא, כי השודד נתן בה אמון.', false, 'טענה זו אינה נכונה. חיסיון עורך דין-לקוח נועד להגן על יחסי האמון בין עורך הדין ללקוחו, ולא על אמון שניתן על ידי צד שלישי שאינו הלקוח.', 4);

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_0, v_sq_id, 'א', 'חיסיון עורך דין-לקוח במסמכים שהוכנו לקראת משפט',
    1, 'עורך דין הכין מסמך אסטרטגי לקראת תביעה צפויה עבור לקוחו. המסמך הודלף לעיתונאי ופורסם. האם המסמך עדיין חסוי מכוח חיסיון עורך דין-לקוח?', 'שאלה זו בוחנת את אופיו של חיסיון עורך דין-לקוח כחיסיון תוכני (חפצי) ולא רק אישי, ואת השלכותיו על מסמכים שהגיעו לידי צד שלישי. היא מדגישה את ההגנה הרחבה שהחיסיון מעניק למידע עצמו, גם כאשר הוא יוצא מחזקת הלקוח או עורך הדין שלא בהסכמה.', 'הפסיקה, ובמיוחד השופט עמית, קבעה כי חיסיון עורך דין-לקוח הוא חיסיון מעורב אישי-תוכני, כלומר, המידע עצמו הוא שנהנה מחיסיון. לכן, חיסיון זה עומד בתוקפו גם כאשר גילוי המסמך מתבקש מצד שלישי אליו התגלגל המסמך, ואין הימצאותו של מסמך בידי צד חיצוני להליך משנה את היותו חסוי. רע"א 6171/17 פלוני נ'' קופת חולים מאוחדת (04.09.2017) רע"א 400/21 מושב נהלל איחוד עוסקים נ'' מס ערך מוסף נצרת (26.09.2021) זאת, אלא אם הלקוח ויתר על החיסיון במפורש או במשתמע, למשל על ידי מסירה בידיעתו ובהסכמתו לצד שלישי שאינו איש סודו. במקרה של הדלפה שלא בידיעת הלקוח, החיסיון נשמר. רע"א 6171/17 פלוני נ'' קופת חולים מאוחדת (04.09.2017)',
    'הנחה שגויה כי חיסיון עורך דין-לקוח הוא חיסיון אישי בלבד, שפוקע ברגע שהמידע יוצא מידי עורך הדין או הלקוח, גם אם שלא בהסכמתם.', '["חיסיון עורך דין-לקוח", "חיסיון תוכני", "חיסיון חפצי", "ויתור על חיסיון", "צד שלישי", "הדלפה"]'::jsonb, '**וריאציה 1 — מסמך שהודלף:** האם מסמך חסוי שהודלף לצד שלישי נשאר חסוי? ← כן, החיסיון הוא תוכני ואינו מאבד מתוקפו (רע"א 6171/17 פלוני, פסקה 13).
**וריאציה 2 — ויתור משתמע:** מתי ייחשב ויתור משתמע על חיסיון? ← הגעת המסמך לצד שלישי בידיעת הלקוח ובהסכמתו (רע"א 6171/17 פלוני, פסקה 10).
**וריאציה 3 — תכלית:** מדוע החיסיון נשמר גם בהדלפה? ← כדי למנוע עקיפת חסיונות על ידי הדלפה ופרסום (רע"א 6171/17 פלוני, פסקה 13).', 'חיסיון עו"ד-לקוח ← חיסיון תוכני ← נשמר גם אם מסמך הודלף ← אלא אם הלקוח ויתר במפורש/משתמע.',
    '["רע\"א 6171/17 פלוני נ'' קופת חולים מאוחדת (04.09.2017)", "רע\"א 400/21 מושב נהלל איחוד עוסקים נ'' מס ערך מוסף נצרת (26.09.2021)"]'::jsonb
  );
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_0, 'א', 'לא, מכיוון שהמסמך הגיע לידי צד שלישי ופורסם, החיסיון פוקע.', false, 'טענה זו אינה נכונה. הפסיקה קבעה כי חיסיון עורך דין-לקוח הוא חיסיון תוכני, והימצאות מסמך בידי צד שלישי אינה מבטלת את החיסיון, אלא אם הלקוח ויתר עליו במפורש או במשתמע.', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_0, 'ב', 'כן, חיסיון עורך דין-לקוח הוא חיסיון תוכני ש"צמוד" למסמך ואינו מאבד מתוקפו גם אם הגיע לידי צד שלישי.', true, 'זוהי התשובה הנכונה. הפסיקה קבעה כי חיסיון עורך דין-לקוח הוא חיסיון תוכני (חפצי) ולא רק אישי, ולכן המידע עצמו נהנה מחיסיון. הימצאותו של מסמך חסוי בידי צד שלישי, שלא בידיעת הלקוח ובהסכמתו, אינה מבטלת את החיסיון.', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_0, 'ג', 'לא, אלא אם כן הלקוח נקט בכל האמצעים הסבירים למנוע את ההדלפה.', false, 'טענה זו אינה נכונה. אף שאי-נקיטת אמצעי זהירות עלולה לפגוע בטענת החיסיון, הכלל הוא שהחיסיון נשמר גם אם המסמך הגיע לצד שלישי שלא בהסכמת הלקוח.', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_0, 'ד', 'כן, אך רק אם העיתונאי מחויב בסודיות מכוח חיסיון עיתונאי.', false, 'טענה זו אינה נכונה. חיסיון עיתונאי הוא חיסיון נפרד השייך לעיתונאי, ואינו משפיע על תחולת חיסיון עורך דין-לקוח על המסמך המקורי.', 4);

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_1, v_sq_id, 'ב', 'תנאי תחולת חיסיון עורך דין-לקוח',
    2, 'מהם התנאים המצטברים הנדרשים לתחולת חיסיון עורך דין-לקוח לפי סעיף 48 לפקודת הראיות?', 'שאלה זו מפרטת את התנאים המהותיים והפרוצדורליים הנדרשים להחלת חיסיון עורך דין-לקוח, כפי שמעוגנים בסעיף 48 לפקודת הראיות ובפסיקה. היא מדגישה את הצורך בקשר ענייני לשירות המקצועי ואת העובדה שהחיסיון שייך ללקוח.', 'סעיף 48(א) לפקודת הראיות קובע שלושה תנאים מצטברים לתחולת חיסיון עורך דין-לקוח: 1. דברים ומסמכים שהוחלפו בין עורך דין לבין לקוחו (או אדם אחר מטעם הלקוח). 2. יש להם קשר ענייני לשירות המקצועי שניתן על ידי עורך הדין ללקוח. 3. הלקוח לא ויתר על החיסיון. פקודת הראיות [נוסח חדש], תשל"א-1971 | עדות עורך דין 48 סעיף מ"י (שלום ראשל"צ) 46647-02-18 מדינת ישראל היחידה הארצית לחקירות הונאה במשטרת ישראל, להב 433 נ'' רוני פלוך (02.10.2018) החיסיון הוא מוחלט ובית המשפט אינו רשאי להסירו, אלא אם הלקוח ויתר עליו. ת"א (מחוזי ת"א) 45320-07-19 טיטאן בניה בע"מ נ'' ירון דיסקין (01.01.2023)',
    'בלבול בין התנאים המהותיים לתחולת החיסיון לבין חריגים או סייגים לו, או הנחה שגויה כי בית המשפט יכול להסירו.', '["חיסיון עורך דין-לקוח", "פקודת הראיות", "קשר ענייני", "שירות מקצועי", "ויתור על חיסיון", "חיסיון מוחלט"]'::jsonb, '**וריאציה 1 — תנאים מצטברים:** מהם התנאים לתחולת חיסיון עו"ד-לקוח? ← חילופי דברים/מסמכים בין עו"ד ללקוח (או מטעמו) + קשר ענייני לשירות מקצועי + הלקוח לא ויתר (סעיף 48(א) לפקודת הראיות).
**וריאציה 2 — מי בעל החיסיון?** ← הלקוח בלבד (רע"פ 751/15 אברג''יל, פסקה 16).
**וריאציה 3 — אופי החיסיון:** האם החיסיון מוחלט או יחסי? ← מוחלט, בית המשפט אינו רשאי להסירו (רע"א 6171/17 פלוני, פסקה 8).', 'חיסיון עו"ד-לקוח ← 3 תנאים מצטברים (חילופי דברים, קשר ענייני, אי-ויתור) ← חיסיון מוחלט של הלקוח.',
    '["פקודת הראיות [נוסח חדש], תשל\"א-1971, סעיף 48(א)", "רע\"פ 751/15 יצחק אברג''יל נ'' מדינת ישראל (09.12.2015)", "רע\"א 6171/17 פלוני נ'' קופת חולים מאוחדת (04.09.2017)", "מ\"י (שלום ראשל\"צ) 46647-02-18 מדינת ישראל היחידה הארצית לחקירות הונאה במשטרת ישראל, להב 433 נ'' רוני פלוך (02.10.2018)", "ת\"א (מחוזי ת\"א) 45320-07-19 טיטאן בניה בע\"מ נ'' ירון דיסקין (01.01.2023)"]'::jsonb
  );
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_1, 'א', 'קיומם של יחסי עורך דין-לקוח, קשר ענייני לשירות המקצועי, והלקוח לא ויתר על החיסיון.', true, 'זוהי התשובה הנכונה. סעיף 48(א) לפקודת הראיות קובע כי החיסיון חל על דברים ומסמכים שהוחלפו בין עורך דין ללקוחו (או אדם מטעמו), שיש להם קשר ענייני לשירות המקצועי, ושהלקוח לא ויתר עליהם.', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_1, 'ב', 'קיומם של יחסי עורך דין-לקוח, קשר ענייני לשירות המקצועי, ואישור בית המשפט.', false, 'טענה זו אינה נכונה. חיסיון עורך דין-לקוח הוא חיסיון מוחלט, ובית המשפט אינו רשאי להסירו. אישור בית המשפט אינו תנאי לתחולתו.', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_1, 'ג', 'קיומם של יחסי עורך דין-לקוח, והמידע לא הגיע לידי צד שלישי.', false, 'טענה זו אינה נכונה. כפי שפורט באנגל א'', חיסיון עורך דין-לקוח הוא תוכני ואינו פוקע אוטומטית עם הגעת המידע לידי צד שלישי, אלא אם הלקוח ויתר עליו.', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_1, 'ד', 'קיומם של יחסי עורך דין-לקוח, והמידע אינו נוגע לעבירה פלילית.', false, 'טענה זו אינה נכונה. אי-קשר לעבירה פלילית הוא חריג לאי-תחולת החיסיון, ולא תנאי לתחולתו הראשונית. החיסיון חל גם על מידע הנוגע לעבירות שבוצעו, כל עוד לא מדובר בייעוץ לביצוע עבירה עתידית.', 4);

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_2, v_sq_id, 'ג', 'חריג: ייעוץ לביצוע עבירה עתידית',
    3, 'לקוח פנה לעורך דין וביקש ייעוץ כיצד לבצע עבירת הלבנת הון עתידית באופן שלא ייתפס. האם המידע שהוחלף בין הלקוח לעורך הדין חוסה תחת חיסיון עורך דין-לקוח?', 'שאלה זו עוסקת באחד החריגים המרכזיים לתחולת חיסיון עורך דין-לקוח: ייעוץ לביצוע עבירה עתידית. היא מדגישה את העיקרון לפיו החיסיון נועד להגן על זכות הלקוח לייצוג הולם, אך אינו יכול לשמש כ''עיר מקלט'' לביצוע מעשים פליליים.', 'הפסיקה קבעה באופן עקבי כי חיסיון עורך דין-לקוח אינו חל כאשר ההתקשרות בין עורך הדין ללקוח נסובה על ייעוץ לביצוע עבירה עתידית, או כאשר הלקוח מודיע לעורך הדין על כוונתו לבצע עבירה עתידית. בש"פ 7064/08 מדינת ישראל נ'' ליאורה ברקו, סג(2) 453 (13.08.2009) מ"י (שלום ראשל"צ) 46647-02-18 מדינת ישראל היחידה הארצית לחקירות הונאה במשטרת ישראל, להב 433 נ'' רוני פלוך (02.10.2018) זאת, משום שייעוץ כזה אינו נחשב ל''שירות מקצועי'' שעורך דין אמור לספק, והחיסיון לא נועד להגן על פעילות עבריינית. ב"ש (מחוזי ירושלים) 4301/08 ליאורה ברקו נ'' מדינת ישראל (23.07.2008) ת"פ (מחוזי י-ם) 28759-05-15 מדינת ישראל נ'' ערן מלכה (27.12.2016)',
    'הנחה שגויה כי חיסיון עורך דין-לקוח הוא מוחלט בכל מצב, גם כאשר מדובר בייעוץ לביצוע עבירה עתידית.', '["חיסיון עורך דין-לקוח", "ייעוץ לביצוע עבירה", "שירות מקצועי", "חריגים לחיסיון", "עיר מקלט"]'::jsonb, '**וריאציה 1 — ייעוץ לעבירה עתידית:** האם ייעוץ לביצוע עבירה עתידית חסוי? ← לא, אין מדובר בשירות מקצועי (בש"פ 7064/08 ברקו, פסקה 32).
**וריאציה 2 — תכלית החריג:** מדוע החיסיון אינו חל במקרה זה? ← החיסיון לא נועד לשמש ''עיר מקלט'' לביצוע עבירות (בש"פ 7064/08 ברקו, פסקה 32).
**וריאציה 3 — עורך דין שותף:** מה הדין אם עורך הדין שותף לעבירה? ← החיסיון אינו חל, שכן אין מדובר בשירות מקצועי (רע"פ 751/15 אברג''יל, פסקה 17).', 'חיסיון עו"ד-לקוח ← אינו חל על ייעוץ לביצוע עבירה עתידית ← לא ''עיר מקלט'' לעבריינים.',
    '["בש\"פ 7064/08 מדינת ישראל נ'' ליאורה ברקו, פ\"ד סג(2) 453 (13.08.2009)", "רע\"פ 751/15 יצחק אברג''יל נ'' מדינת ישראל (09.12.2015)", "מ\"י (שלום ראשל\"צ) 46647-02-18 מדינת ישראל היחידה הארצית לחקירות הונאה במשטרת ישראל, להב 433 נ'' רוני פלוך (02.10.2018)", "ב\"ש (מחוזי ירושלים) 4301/08 ליאורה ברקו נ'' מדינת ישראל (23.07.2008)", "ת\"פ (מחוזי י-ם) 28759-05-15 מדינת ישראל נ'' ערן מלכה (27.12.2016)"]'::jsonb
  );
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_2, 'א', 'כן, כל מידע שהוחלף בין עורך דין ללקוחו במסגרת יחסי עורך דין-לקוח חסוי.', false, 'טענה זו אינה נכונה. חיסיון עורך דין-לקוח אינו מוחלט באופן גורף, וישנם חריגים לתחולתו, במיוחד כאשר מדובר בייעוץ לביצוע עבירה עתידית.', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_2, 'ב', 'לא, חיסיון עורך דין-לקוח אינו חל כאשר ההתקשרות נסובה על ייעוץ לביצוע עבירה עתידית, שכן אין מדובר בשירות מקצועי.', true, 'זוהי התשובה הנכונה. הפסיקה קבעה באופן חד משמעי כי חיסיון עורך דין-לקוח אינו נועד לשמש ''עיר מקלט'' לביצוע עבירות, ולכן אינו חל על ייעוץ לביצוע עבירה עתידית.', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_2, 'ג', 'כן, אלא אם כן עורך הדין עצמו נחשד כשותף לעבירה.', false, 'טענה זו אינה נכונה. גם אם עורך הדין אינו שותף לעבירה, ייעוץ לביצוע עבירה עתידית אינו נחשב לשירות מקצועי חסוי.', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_2, 'ד', 'לא, אלא אם כן מדובר בעבירה מסוג פשע ולא עוון.', false, 'טענה זו אינה נכונה. חומרת העבירה אינה משפיעה על תחולת החריג של ייעוץ לביצוע עבירה עתידית.', 4);

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_3, v_sq_id, 'ד', 'חיסיון עורך דין-לקוח מול חובת סודיות אתית',
    4, 'מהו ההבדל המהותי בין חיסיון עורך דין-לקוח הקבוע בסעיף 48 לפקודת הראיות לבין חובת הסודיות האתית הקבועה בסעיף 90 לחוק לשכת עורכי הדין?', 'שאלה זו עוסקת בהבחנה בין שני המקורות הנורמטיביים לחיסיון עורך דין-לקוח: סעיף 48 לפקודת הראיות (הפן הראייתי) וסעיף 90 לחוק לשכת עורכי הדין (הפן האתי). היא מדגישה את תפקידו הייחודי של כל סעיף ואת היחסים המשלימים ביניהם.', 'הפסיקה מבחינה בין סעיף 48 לפקודת הראיות לבין סעיף 90 לחוק לשכת עורכי הדין. סעיף 48 מופנה לבית המשפט ולרשויות החקירה, ומגביל אותם בגביית ראיות ועדויות מעורך הדין, ובכך קובע חיסיון ראייתי. ת"א (מחוזי מרכז) 30195-04-19 בועז בנרוש נ'' שי לבנת (24.05.2020) ת"א (שלום ת"א) 20167-11-12 עו"ד ברק רון נ'' קטרזינה סיקורה (19.03.2015) לעומת זאת, סעיף 90 פונה לציבור עורכי הדין, ומעגן את הפן האתי, בכך שהוא מטיל עליהם חובת סודיות ואוסר עליהם לחשוף את המידע החסוי, והפרתו מהווה עבירה משמעתית. חוק לשכת עורכי הדין, תשכ"א-1961 | סוד מקצועי 90 סעיף צ"א (מחוזי תל אביב-יפו) 36336-11-20 מדינת ישראל- רשות המסים נ'' עו״ד דורון לוי (04.02.2021)',
    'אי-הבחנה בין הפן הראייתי (סעיף 48) לפן האתי (סעיף 90), והתייחסות לשניהם כאל זהים לחלוטין.', '["חיסיון עורך דין-לקוח", "חובת סודיות אתית", "פקודת הראיות", "חוק לשכת עורכי הדין", "פן ראייתי", "פן אתי"]'::jsonb, '**וריאציה 1 — סעיף 48:** למי מופנה סעיף 48 לפקודת הראיות? ← לבית המשפט ולרשויות החקירה, וקובע חיסיון ראייתי (רע"פ 751/15 אברג''יל, פסקה 16).
**וריאציה 2 — סעיף 90:** למי מופנה סעיף 90 לחוק לשכת עורכי הדין? ← לעורך הדין, וקובע חובת סודיות אתית (רע"פ 751/15 אברג''יל, פסקה 16).
**וריאציה 3 — הפרה:** מהי ההשלכה של הפרת סעיף 90? ← עבירה משמעתית (רע"פ 751/15 אברג''יל, פסקה 16).', 'חיסיון עו"ד-לקוח ← סעיף 48 (ראייתי, לביהמ"ש) ← סעיף 90 (אתי, לעו"ד) ← משלימים זה את זה.',
    '["פקודת הראיות [נוסח חדש], תשל\"א-1971, סעיף 48", "חוק לשכת עורכי הדין, תשכ\"א-1961, סעיף 90", "רע\"פ 751/15 יצחק אברג''יל נ'' מדינת ישראל (09.12.2015)", "ת\"א (מחוזי מרכז) 30195-04-19 בועז בנרוש נ'' שי לבנת (24.05.2020)", "צ\"א (מחוזי תל אביב-יפו) 36336-11-20 מדינת ישראל- רשות המסים נ'' עו״ד דורון לוי (04.02.2021)"]'::jsonb
  );
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_3, 'א', 'סעיף 48 מופנה לבית המשפט וקובע חיסיון ראייתי, בעוד סעיף 90 מופנה לעורך הדין וקובע חובת סודיות אתית.', true, 'זוהי התשובה הנכונה. הפסיקה מבחינה בין שני הסעיפים: סעיף 48 הוא דיוני-ראייתי ומופנה לבית המשפט, ואילו סעיף 90 הוא אתי ומופנה לעורך הדין, ומטיל עליו חובת סודיות.', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_3, 'ב', 'סעיף 48 קובע חיסיון מוחלט, בעוד סעיף 90 קובע חיסיון יחסי.', false, 'טענה זו אינה נכונה. שני הסעיפים מתייחסים לחיסיון מוחלט, ואין הבחנה ביניהם לעניין זה.', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_3, 'ג', 'סעיף 48 חל רק בהליכים פליליים, בעוד סעיף 90 חל גם בהליכים אזרחיים.', false, 'טענה זו אינה נכונה. שני הסעיפים חלים הן בהליכים פליליים והן באזרחיים, כל עוד מתקיימים תנאי החיסיון.', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_3, 'ד', 'סעיף 48 חל על דברים ומסמכים, בעוד סעיף 90 חל רק על מסמכים.', false, 'טענה זו אינה נכונה. שני הסעיפים מתייחסים ל''דברים ומסמכים'' שהוחלפו בין עורך דין ללקוח.', 4);

  RAISE NOTICE 'Q% inserted: external_id %', 16, '2022-S-S-Q16';
END
$$;

