  INSERT INTO public.source_questions (
    id, question_group_id, version, is_current, external_id, chapter_id, subtopic_id, question_text, source_metadata, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list, notes_for_admin, status, created_by
  ) VALUES (
    v_sq_id, v_group_id, 1, true,
    '2022-S-S-Q17', v_chapter_id, v_subtopic_id, 'בריאיון לחדשות סיפרה דינה ששוטר היכה אותה בסיום הפגנה בלי כל סיבה. לאחר שהשוטר הגיש נגדה תביעת לשון הרע היא מבקשת לתבוע אותו בתביעה שכנגד. מה עליה לעשות?',
    '{"exam_year": 2022, "exam_season": "summer", "exam_part": 2, "exam_question_number": 17}'::jsonb, 'שאלה זו עוסקת בחובת ההודעה הפרוצדורלית החלה על תובע המגיש תביעת נזיקין נגד עובד ציבור, כפי שנקבעה בתקנות הנזיקין (אחריות עובדי ציבור), התשס"ו-2006. היא מדגישה את ההבחנה בין עובד מדינה (כמו שוטר) לבין עובד רשות ציבורית, ואת הגורם המשפטי הרלוונטי אליו יש להפנות את ההודעה בכל מקרה.', 'סעיף 7א לפקודת הנזיקין [נוסח חדש] קובע חסינות דיונית לעובד ציבור מפני תביעות נזיקין אישיות בגין מעשה שנעשה תוך כדי מילוי תפקידו השלטוני, למעט אם המעשה נעשה ביודעין מתוך כוונה לגרום נזק או בשוויון נפש לאפשרות גרימתו. רע"א 775/11 אברהם פלקסר נ'' מדינת ישראל - משטרת ישראל, סז(1) 353 (11.08.2014) ת"א (מחוזי ת"א) 51661-03-16 דוד ברונר נ'' חנוך זייברט (20.08.2019) תקנות הנזיקין (אחריות עובדי ציבור), התשס"ו-2006, מסדירות את הפרוצדורה להפעלת חסינות זו. תקנה 2(א) קובעת כי כאשר מוגשת תובענה נגד עובד ציבור שהוא עובד מדינה (כמו שוטר), על התובע להודיע על הגשתה למשרד פרקליט המחוז שבו נמצא מקום מושבו של בית המשפט הדן בתובענה, בצירוף העתק כתב התביעה. תקנות הנזיקין (אחריות עובדי ציבור), תשס"ו-2006 | חובת הודעה על הגשת תובענה נגד עובד ציבור 2 תקנה מטרת חובת ההודעה היא לאפשר למדינה (או לרשות הציבורית) לשקול את עמדתה בנוגע לחסינות העובד וליטול על עצמה את האחריות, ובכך למנוע הטרדה של עובדי ציבור בתביעות אישיות. רע"א 775/11 אברהם פלקסר נ'' מדינת ישראל - משטרת ישראל, סז(1) 353 (11.08.2014)', 'אי-הכרת חובת ההודעה הספציפית בעת תביעת עובד ציבור, או בלבול בין הגורם אליו יש להפנות את ההודעה (פרקליט המחוז לעובד מדינה מול יועץ משפטי של רשות ציבורית לעובד רשות ציבורית).',
    '["חסינות עובד ציבור", "פקודת הנזיקין", "תקנות הנזיקין (אחריות עובדי ציבור)", "חובת הודעה", "עובד מדינה", "פרקליט המחוז", "תביעה שכנגד"]'::jsonb, '**וריאציה 1 — סוג העובד:** שוטר הוא עובד מדינה. למי מוגשת הודעה בתביעה נגדו? ← לפרקליט המחוז (תקנה 2(א) לתקנות הנזיקין).
**וריאציה 2 — מטרת ההודעה:** מהי מטרת חובת ההודעה? ← לאפשר למדינה לשקול הכרה בחסינות העובד וליטול על עצמה את האחריות (רע"א 775/11 פלקסר, פסקה 27).
**וריאציה 3 — מועד ההודעה:** מתי יש להמציא את ההודעה? ← באותו מועד שבו מומצא כתב התביעה לעובד (תקנה 3 לתקנות הנזיקין).', 'תביעה נגד שוטר (עובד מדינה) ← חובת הודעה לפרקליט המחוז ← בצירוף כתב תביעה ← באותו מועד כמו לעובד.', '["תקנות הנזיקין (אחריות עובדי ציבור), תשס\"ו-2006, תקנה 2", "פקודת הנזיקין [נוסח חדש], סעיף 7א", "רע\"א 775/11 אברהם פלקסר נ'' מדינת ישראל - משטרת ישראל, סז(1) 353 (11.08.2014)", "ת\"ק (תביעות קטנות י-ם) 1465-08-22 מימון אברג''ל נ'' תחנת משטרה - מרחב מוריה (10.12.2022)"]'::jsonb,
    'classification_review: original chapter=''סדר דין אזרחי'' subtopic=''הליכים'' → mapped chapter=''torts'' subtopic=''defamation'' | classifier_note: Defamation counter-claim — TV interview about police officer + lawsuit + counter-claim', 'active', 'b9ecdde2-d07e-4761-96ab-05f0ad32d4e3'
  );

  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'א', 'להגיש תביעה שכנגד ולהמציא אותה לשוטר.', false, 'טענה זו אינה נכונה. הגשת תביעה נגד עובד ציבור מחייבת המצאת הודעה לפרקליט המחוז הרלוונטי, בנוסף להמצאה לעובד הציבור עצמו.', 1);
  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'ב', 'להגיש תביעה שכנגד ולהמציא אותה לשוטר ולפרקליט המחוז הרלוונטי.', true, 'זוהי התשובה הנכונה. שוטר הוא עובד מדינה. לפי תקנה 2(א) לתקנות הנזיקין (אחריות עובדי ציבור), התשס"ו-2006, כאשר מוגשת תובענה נגד עובד מדינה, על התובע להודיע על הגשתה למשרד פרקליט המחוז שבו נמצא מקום מושבו של בית המשפט הדן בתובענה, בצירוף העתק כתב התביעה.', 2);
  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'ג', 'להגיש תביעה שכנגד ולהמציא אותה למשטרה.', false, 'טענה זו אינה נכונה. ההודעה אינה מוגשת למשטרה כגוף, אלא למשרד פרקליט המחוז הרלוונטי, שהוא הגורם המייצג את המדינה בהליכים אזרחיים.', 3);
  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'ד', 'לא ניתן להגיש תביעה שכנגד, שכן הנתבעת הנכונה היא משטרת ישראל והיא אינה בעלת דין בהליך המקורי.', false, 'טענה זו אינה נכונה. ניתן להגיש תביעה נגד עובד ציבור באופן אישי, בכפוף לתנאי החסינות. כמו כן, תביעה שכנגד מוגשת נגד התובע המקורי, במקרה זה השוטר.', 4);

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_0, v_sq_id, 'א', 'חובת הודעה בתביעה נגד עובד רשות מקומית',
    1, 'ראובן מבקש להגיש תביעת נזיקין נגד מהנדס עיריית אשדוד, בטענה שמעשיו גרמו לו נזק. מה עליו לעשות בנוגע להמצאת כתב התביעה?', 'שאלה זו בוחנת את ההבחנה בין חובת ההודעה בעת הגשת תביעת נזיקין נגד עובד מדינה לבין חובת ההודעה בעת הגשת תביעה נגד עובד רשות ציבורית (כגון עירייה). היא מדגישה את הצורך להפנות את ההודעה לגורם המשפטי המתאים בכל מקרה.', 'תקנה 2 לתקנות הנזיקין (אחריות עובדי ציבור), התשס"ו-2006, מבחינה בין עובד מדינה לעובד רשות ציבורית. בעוד שלגבי עובד מדינה (כמו שוטר), ההודעה נמסרת למשרד פרקליט המחוז (תקנה 2(א)), הרי שלגבי עובד רשות ציבורית (כמו מהנדס עירייה), ההודעה נמסרת ליועץ המשפטי של הרשות הציבורית (תקנה 2(ב)). תקנות הנזיקין (אחריות עובדי ציבור), תשס"ו-2006 | חובת הודעה על הגשת תובענה נגד עובד ציבור 2 תקנה מטרת ההודעה היא לאפשר לרשות לשקול את עמדתה בנוגע לחסינות העובד וליטול על עצמה את ההגנה. ת"א (שלום חד'') 20051-09-11 ע.ע. ענבר אחזקות ונדל"ן בע"מ נ'' עיריית חיפה (21.11.2012) ת"א (מחוזי ת"א) 51661-03-16 דוד ברונר נ'' חנוך זייברט (20.08.2019)',
    'בלבול בין הגורם המשפטי אליו יש להפנות את ההודעה - פרקליט המחוז לעובדי מדינה מול יועץ משפטי של רשות ציבורית לעובדי רשות ציבורית.', '["חסינות עובד ציבור", "עובד מדינה", "עובד רשות ציבורית", "תקנות הנזיקין (אחריות עובדי ציבור)", "חובת הודעה", "פרקליט המחוז", "יועץ משפטי של רשות"]'::jsonb, '**וריאציה 1 — עובד מדינה:** למי מוגשת הודעה בתביעה נגד שוטר? ← לפרקליט המחוז (תקנה 2(א) לתקנות הנזיקין).
**וריאציה 2 — עובד רשות מקומית:** למי מוגשת הודעה בתביעה נגד מהנדס עירייה? ← ליועץ המשפטי של הרשות הציבורית (תקנה 2(ב) לתקנות הנזיקין).
**וריאציה 3 — מטרת ההודעה:** מהי מטרת חובת ההודעה? ← לאפשר לרשות לשקול הכרה בחסינות העובד וליטול על עצמה את האחריות (רע"א 775/11 פלקסר, פסקה 27).', 'תביעה נגד עובד ציבור ← חובת הודעה לגורם המשפטי הרלוונטי (פרקליט מחוז/יועמ"ש רשות) ← לפי סוג העובד.',
    '["תקנות הנזיקין (אחריות עובדי ציבור), תשס\"ו-2006, תקנה 2", "רע\"א 775/11 אברהם פלקסר נ'' מדינת ישראל - משטרת ישראל, סז(1) 353 (11.08.2014)", "ת\"א (מחוזי ת\"א) 51661-03-16 דוד ברונר נ'' חנוך זייברט (20.08.2019)", "ת\"א (שלום חד'') 20051-09-11 ע.ע. ענבר אחזקות ונדל\"ן בע\"מ נ'' עיריית חיפה (21.11.2012)"]'::jsonb
  );
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_0, 'א', 'להגיש את התביעה ולהמציא אותה למהנדס העיר בלבד.', false, 'טענה זו אינה נכונה. מהנדס עיר הוא עובד רשות ציבורית, ולכן חלה חובת הודעה ליועץ המשפטי של הרשות הציבורית.', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_0, 'ב', 'להגיש את התביעה ולהמציא אותה למהנדס העיר ולפרקליט המחוז הרלוונטי.', false, 'טענה זו אינה נכונה. פרקליט המחוז רלוונטי לעובדי מדינה. לעובדי רשות ציבורית, ההודעה מוגשת ליועץ המשפטי של הרשות הציבורית.', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_0, 'ג', 'להגיש את התביעה ולהמציא אותה למהנדס העיר ולייעוץ המשפטי של עיריית אשדוד.', true, 'זוהי התשובה הנכונה. מהנדס עיר הוא עובד רשות ציבורית. לפי תקנה 2(ב) לתקנות הנזיקין (אחריות עובדי ציבור), התשס"ו-2006, כאשר מוגשת תובענה נגד עובד רשות ציבורית, על התובע להודיע על הגשתה ליועץ המשפטי של הרשות הציבורית, בצירוף העתק כתב התביעה.', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_0, 'ד', 'לא ניתן להגיש תביעה נגד מהנדס העיר באופן אישי.', false, 'טענה זו אינה נכונה. ניתן להגיש תביעה נגד עובד ציבור באופן אישי, בכפוף לתנאי החסינות, אך יש לעמוד בדרישות הפרוצדורליות.', 4);

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_1, v_sq_id, 'ב', 'תנאי החסינות לעובד ציבור',
    2, 'מהם התנאים המצטברים הנדרשים לקיומה של חסינות עובד ציבור מפני תביעת נזיקין אישית, לפי סעיף 7א(א) לפקודת הנזיקין?', 'שאלה זו מתמקדת בתנאים המהותיים לקיומה של חסינות עובד ציבור מפני תביעות נזיקין אישיות, כפי שנקבעו בסעיף 7א(א) לפקודת הנזיקין. היא מדגישה את האיזון בין הצורך להגן על עובדי ציבור לבין הצורך למנוע פגיעה בזדון.', 'סעיף 7א(א) לפקודת הנזיקין [נוסח חדש] קובע את שלושת התנאים המצטברים להחלת חסינות עובד ציבור: 1. הנתבע הוא עובד ציבור. 2. המעשה נשוא התובענה נעשה תוך כדי מילוי תפקידו השלטוני כעובד ציבור. 3. המעשה לא נעשה ביודעין מתוך כוונה לגרום נזק או בשוויון נפש לאפשרות גרימתו. רע"א 775/11 אברהם פלקסר נ'' מדינת ישראל - משטרת ישראל, סז(1) 353 (11.08.2014) ת"ק (תביעות קטנות י-ם) 1465-08-22 מימון אברג''ל נ'' תחנת משטרה - מרחב מוריה (10.12.2022) סע"ש (אזורי י-ם) 53638-06-16 פלונית - פלוני (11.12.2016) רק בהתקיים כל שלושת התנאים תוענק לעובד הציבור חסינות מפני תביעה אישית. תכלית החסינות היא לאפשר לעובדי ציבור למלא את תפקידם ללא מורא, תוך איזון עם הצורך למנוע פגיעה בזדון. ת"א (מחוזי ת"א) 51661-03-16 דוד ברונר נ'' חנוך זייברט (20.08.2019)',
    'התעלמות מאחד התנאים או בלבול בין התנאים המהותיים לבין שיקולים דיוניים או אחרים.', '["חסינות עובד ציבור", "פקודת הנזיקין", "מעשה שלטוני", "יסוד נפשי", "כוונה לגרום נזק", "שוויון נפש"]'::jsonb, '**וריאציה 1 — שלושת התנאים:** מהם התנאים המצטברים לחסינות עובד ציבור? ← עובד ציבור, מעשה בתפקיד שלטוני, ללא כוונה/שוויון נפש לנזק (סעיף 7א(א) לפקודת הנזיקין).
**וריאציה 2 — חריג היסוד הנפשי:** מתי לא תחול החסינות? ← אם המעשה נעשה ביודעין מתוך כוונה לגרום נזק או בשוויון נפש לאפשרות גרימתו (סעיף 7א(א) לפקודת הנזיקין).
**וריאציה 3 — תכלית החסינות:** מדוע ניתנת חסינות לעובדי ציבור? ← כדי לאפשר להם למלא תפקידם ללא מורא מפני תביעות אישיות (רע"א 775/11 פלקסר, פסקה 17).', 'חסינות עובד ציבור ← 3 תנאים מצטברים ← עובד ציבור, מעשה שלטוני, ללא כוונה/שוויון נפש לנזק.',
    '["פקודת הנזיקין [נוסח חדש], סעיף 7א(א)", "רע\"א 775/11 אברהם פלקסר נ'' מדינת ישראל - משטרת ישראל, סז(1) 353 (11.08.2014)", "ת\"ק (תביעות קטנות י-ם) 1465-08-22 מימון אברג''ל נ'' תחנת משטרה - מרחב מוריה (10.12.2022)", "ת\"א (מחוזי ת\"א) 51661-03-16 דוד ברונר נ'' חנוך זייברט (20.08.2019)", "סע\"ש (אזורי י-ם) 53638-06-16 פלונית - פלוני (11.12.2016)"]'::jsonb
  );
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_1, 'א', 'היותו עובד ציבור, שהמעשה נעשה תוך כדי מילוי תפקידו השלטוני, ושלא נעשה ביודעין מתוך כוונה לגרום נזק או בשוויון נפש לאפשרות גרימתו.', true, 'זוהי התשובה הנכונה. סעיף 7א(א) לפקודת הנזיקין קובע שלושה תנאים מצטברים להחלת החסינות: 1. הנתבע הוא עובד ציבור. 2. המעשה נעשה תוך כדי מילוי תפקידו השלטוני. 3. המעשה לא נעשה ביודעין מתוך כוונה לגרום נזק או בשוויון נפש לאפשרות גרימתו.', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_1, 'ב', 'היותו עובד ציבור, שהמעשה נעשה תוך כדי מילוי תפקידו השלטוני, ושהרשות הציבורית אישרה את מעשיו.', false, 'טענה זו אינה נכונה. אישור הרשות אינו תנאי מהותי לחסינות, אלא חלק מההליך הדיוני להכרה בה.', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_1, 'ג', 'היותו עובד ציבור, שהמעשה נעשה בתום לב, ושהתובע לא הוכיח נזק.', false, 'טענה זו אינה נכונה. תום לב הוא חלק מהיסוד הנפשי השולל את החריג לחסינות, אך אינו תנאי בפני עצמו. הוכחת נזק היא יסוד בעוולה הנזיקית, לא בתנאי החסינות.', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_1, 'ד', 'היותו עובד ציבור, שהמעשה נעשה תוך כדי מילוי תפקידו השלטוני, ושהתביעה הוגשה לאחר חלוף תקופת ההתיישנות.', false, 'טענה זו אינה נכונה. חלוף תקופת ההתיישנות היא טענת הגנה נפרדת, ואינה קשורה לתנאי החסינות לפי סעיף 7א(א).', 4);

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_2, v_sq_id, 'ג', 'נטל ההוכחה לסתירת החסינות',
    3, 'המדינה הגישה הודעה לבית המשפט המכירה בחסינותו של עובד מדינה, וביקשה לדחות את התביעה נגדו. התובע מתנגד להודעה וטוען כי העובד פעל מתוך כוונה לגרום נזק. על מי מוטל נטל ההוכחה בעניין זה?', 'שאלה זו עוסקת בנטל ההוכחה לגבי החריג לחסינות עובד ציבור (כוונה לגרום נזק או שוויון נפש), במיוחד כאשר הרשות (המדינה או רשות ציבורית) מכירה בחסינות. היא מדגישה את הכלל לפיו הנטל עובר לתובע לסתור את החסינות.', 'הפסיקה קבעה כי כאשר המדינה (לגבי עובד מדינה) או הרשות הציבורית (לגבי עובד רשות ציבורית) מכירה בחסינות העובד, נטל ההוכחה לסתירת החסינות, כלומר להוכחת התקיימות החריג של מעשה שנעשה ביודעין מתוך כוונה לגרום נזק או בשוויון נפש לאפשרות גרימתו, מוטל על התובע. ת"א (מחוזי ת"א) 51661-03-16 דוד ברונר נ'' חנוך זייברט (20.08.2019) פ"ה (אזורי ת"א) 55832-04-19 בתיה יהודה - עיריית הרצליה (13.04.2020) ת"א (שלום י-ם) 38366-03-15 עו"ד אחמד עבידאת נ'' פאתנה מכול (06.09.2015) זאת, מתוך תכלית החוק להגן על עובדי ציבור מפני תביעות סרק והטרדה. רע"א 775/11 אברהם פלקסר נ'' מדינת ישראל - משטרת ישראל, סז(1) 353 (11.08.2014)',
    'הנחה שגויה כי הנטל להוכחת תנאי החסינות או היעדר החריג מוטל על העובד או הרשות, במקום על התובע המתנגד לחסינות.', '["חסינות עובד ציבור", "נטל הוכחה", "חריג לחסינות", "כוונה לגרום נזק", "שוויון נפש", "הודעת הכרה"]'::jsonb, '**וריאציה 1 — נטל הוכחה (מדינה):** אם המדינה מכירה בחסינות עובד מדינה, על מי נטל ההוכחה לסתור? ← על התובע (רע"א 775/11 פלקסר, פסקה 35).
**וריאציה 2 — נטל הוכחה (רשות ציבורית):** אם רשות ציבורית מכירה בחסינות עובד שלה, על מי נטל ההוכחה לסתור? ← על התובע (ת"א (מחוזי ת"א) 51661-03-16 ברונר, פסקה 35).
**וריאציה 3 — תכלית הכלל:** מדוע הנטל על התובע? ← כדי למנוע תביעות סרק והטרדה של עובדי ציבור (רע"א 775/11 פלקסר, פסקה 17).', 'הודעת הכרה בחסינות ← נטל הוכחה לסתירה ← על התובע ← להוכיח כוונה/שוויון נפש לנזק.',
    '["פקודת הנזיקין [נוסח חדש], סעיף 7א(א)", "רע\"א 775/11 אברהם פלקסר נ'' מדינת ישראל - משטרת ישראל, סז(1) 353 (11.08.2014)", "ת\"א (מחוזי ת\"א) 51661-03-16 דוד ברונר נ'' חנוך זייברט (20.08.2019)", "פ\"ה (אזורי ת\"א) 55832-04-19 בתיה יהודה - עיריית הרצליה (13.04.2020)", "ת\"א (שלום י-ם) 38366-03-15 עו\"ד אחמד עבידאת נ'' פאתנה מכול (06.09.2015)"]'::jsonb
  );
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_2, 'א', 'על המדינה, להוכיח שהעובד לא פעל מתוך כוונה לגרום נזק.', false, 'טענה זו אינה נכונה. לאחר שהמדינה מכירה בחסינות, נטל ההוכחה עובר לתובע לסתור זאת.', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_2, 'ב', 'על העובד, להוכיח שלא פעל מתוך כוונה לגרום נזק.', false, 'טענה זו אינה נכונה. במקרה של עובד מדינה, המדינה היא זו שמכירה בחסינות, והנטל עובר לתובע.', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_2, 'ג', 'על התובע, להוכיח שהעובד פעל ביודעין מתוך כוונה לגרום נזק או בשוויון נפש לאפשרות גרימתו.', true, 'זוהי התשובה הנכונה. הפסיקה קבעה כי כאשר המדינה מכירה בחסינות עובד מדינה, נטל ההוכחה לסתירת החסינות (קרי, להוכחת התקיימות החריג של כוונה/שוויון נפש) מוטל על התובע.', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_2, 'ד', 'על בית המשפט, לברר את העובדות באופן יזום.', false, 'טענה זו אינה נכונה. בית המשפט מכריע על בסיס הראיות המובאות בפניו, ואינו מברר עובדות באופן יזום במקום הצדדים.', 4);

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_3, v_sq_id, 'ד', 'השלכות אי-מתן הודעה על הגשת תביעה',
    4, 'דינה הגישה תביעת נזיקין נגד שוטר, אך שכחה להמציא הודעה על הגשת התביעה לפרקליט המחוז הרלוונטי, כנדרש בתקנות. מה תהיה לרוב השלכת מחדל זה?', 'שאלה זו עוסקת בהשלכות אי-קיום חובת ההודעה על הגשת תביעה נגד עובד ציבור, כפי שנקבעה בתקנות הנזיקין (אחריות עובדי ציבור). היא מדגישה את הגישה הפרשנית של בתי המשפט, הנוטה לאפשר תיקון פגמים דיוניים ולא לדחות תביעות על הסף בשל מחדלים פרוצדורליים הניתנים לריפוי.', 'הפסיקה קבעה כי אי-המצאת הודעה על הגשת תביעה נגד עובד ציבור לפרקליט המחוז (או ליועץ המשפטי של הרשות הציבורית) היא פגם דיוני הניתן לתיקון, ואינה עילה לדחייה על הסף של התביעה. ת"א (שלום חי'') 43798-05-11 שאול יצחק נ'' מני גלס (05.12.2011) ס"ע (אזורי ת"א) 17809-01-12 סילביה חרבי נ'' מועצה מקומית אליכין (23.07.2014) סע"ש (אזורי נצ'') 14277-10-14 יוסי לוי נ'' עיריית צפת (18.01.2015) מטרת התקנה היא ליידע את הרשות ולאפשר לה לשקול את עמדתה, ואם מטרה זו הושגה בדרך אחרת (למשל, הרשות צורפה כנתבעת או ידעה על התביעה), או אם האיחור קל, בית המשפט יורה על תיקון הפגם. תע"א (אזורי נצ'') 2666-08 עלוית פרוינד נ'' מאיר קטן (17.02.2011)',
    'הנחה שגויה כי מחדל פרוצדורלי של אי-מתן הודעה יוביל בהכרח לדחיית התביעה על הסף, מבלי להתחשב בגישת בתי המשפט המאפשרת תיקון פגמים.', '["חובת הודעה", "תקנות הנזיקין (אחריות עובדי ציבור)", "פגם דיוני", "דחייה על הסף", "תיקון פגם", "מטרת התקנה"]'::jsonb, '**וריאציה 1 — תוצאת אי-הודעה:** האם אי-מתן הודעה לפרקליט המחוז מוביל לדחייה על הסף? ← לרוב לא, בית המשפט יורה על תיקון הפגם (ת"א (שלום חי'') 43798-05-11 שאול יצחק, פסקה 9).
**וריאציה 2 — מטרת ההודעה:** מהי מטרת חובת ההודעה? ← ליידע את הרשות ולאפשר לה לשקול הכרה בחסינות (סע"ש (אזורי ת"א) 17809-01-12 סילביה חרבי, פסקה 29).
**וריאציה 3 — תיקון הפגם:** מתי ייחשב הפגם כמתוקן? ← אם הרשות ידעה על התביעה בדרך אחרת, או אם האיחור קל (תע"א (אזורי נצ'') 2666-08 עלוית פרוינד, פסקה 15).', 'אי-מתן הודעה (תקנה 2) ← פגם דיוני ← לרוב ניתן לתיקון ← לא מוביל לדחייה על הסף.',
    '["תקנות הנזיקין (אחריות עובדי ציבור), תשס\"ו-2006, תקנה 2", "ת\"א (שלום חי'') 43798-05-11 שאול יצחק נ'' מני גלס (05.12.2011)", "ס\"ע (אזורי ת\"א) 17809-01-12 סילביה חרבי נ'' מועצה מקומית אליכין (23.07.2014)", "סע\"ש (אזורי נצ'') 14277-10-14 יוסי לוי נ'' עיריית צפת (18.01.2015)", "תע\"א (אזורי נצ'') 2666-08 עלוית פרוינד נ'' מאיר קטן (17.02.2011)"]'::jsonb
  );
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_3, 'א', 'התביעה תידחה על הסף באופן מיידי, ללא אפשרות לתיקון.', false, 'טענה זו אינה נכונה. בתי המשפט נוטים לאפשר תיקון הפגם, במיוחד אם מטרת ההודעה הושגה בדרך אחרת או אם האיחור קל.', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_3, 'ב', 'בית המשפט יורה על תיקון הפגם, לרוב באמצעות המצאת ההודעה באיחור, ולא ידחה את התביעה על הסף.', true, 'זוהי התשובה הנכונה. הפסיקה נוטה לראות באי-המצאת ההודעה פגם דיוני הניתן לתיקון, ולא עילה לדחייה על הסף, במיוחד אם מטרת ההודעה הושגה בדרך אחרת או אם האיחור קל.', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_3, 'ג', 'השוטר יאבד את זכותו לחסינות, והתביעה נגדו תתברר כרגיל.', false, 'טענה זו אינה נכונה. אי-המצאת ההודעה על ידי התובע אינה שוללת את זכותו המהותית של השוטר לחסינות, אלא משפיעה על הפרוצדורה.', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_3, 'ד', 'התביעה תועבר אוטומטית נגד המדינה, והשוטר יסולק מההליך.', false, 'טענה זו אינה נכונה. העברת התביעה למדינה מתרחשת רק לאחר שהמדינה מכירה בחסינות העובד, ולא כתוצאה אוטומטית מאי-מתן הודעה.', 4);

  RAISE NOTICE 'Q% inserted: external_id %', 17, '2022-S-S-Q17';
END
$$;

