  v_ang_0 uuid := 'a193720a-7f77-43b4-9d7c-799d22295135'::uuid;
  v_ang_1 uuid := '4ba48c92-4899-4f3c-bca6-5106b3c59b8f'::uuid;
  v_ang_2 uuid := 'c23de80e-55d8-4389-9811-0b5b561ce9e0'::uuid;
  v_ang_3 uuid := '6e90eb6d-023e-4ea0-b03a-bc0ecaa6f36b'::uuid;
BEGIN
  SELECT id INTO v_existing_id FROM public.source_questions WHERE external_id = '2022-S-S-Q18';
