  INSERT INTO public.source_questions (
    id, question_group_id, version, is_current, external_id, chapter_id, subtopic_id, question_text, source_metadata, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list, notes_for_admin, status, created_by
  ) VALUES (
    v_sq_id, v_group_id, 1, true,
    '2022-S-S-Q18', v_chapter_id, v_subtopic_id, '7 ילדים בני 11-13 יידו יחד אבנים על בית, וכתוצאה מכך נגרם נזק ניכר לרכוש. דיירי הבית מבקשים לתבוע את שבעת הילדים. האם הם יכולים לעשות זאת?',
    '{"exam_year": 2022, "exam_season": "summer", "exam_part": 2, "exam_question_number": 18}'::jsonb, 'שאלה זו עוסקת בגיל האחריות הנזיקית של קטינים ובאחריותם כמעוולים במשותף. היא דורשת הבנה של סעיף 9 לפקודת הנזיקין [נוסח חדש] הקובע את גיל האחריות (12 שנים), וכן את סעיף 11 לפקודה הדן באחריותם של מעוולים במשותף, במיוחד כאשר הנזק שנגרם הוא אחד ובלתי ניתן לחלוקה.', 'השאלה עוסקת באחריות נזיקית של קטינים. לפי סעיף 9 לפקודת הנזיקין [נוסח חדש], "אדם שלא מלאו לו שתים עשרה שנים, אינו אחראי בנזיקין". ע"א 326/88 עידו צימרמן, קטין באמצעות אביו נ'' דוד גבריאלוב (19.12.1991) מכאן, שילדים בני 11 אינם נושאים באחריות נזיקית ואינם ניתנים לתביעה. לעומת זאת, ילדים בני 12 ו-13 חצו את גיל האחריות הנזיקית, ולכן הם יכולים להיתבע. מאחר שהילדים פעלו יחד וגרמו לנזק אחד בלתי ניתן לחלוקה (יידוי אבנים על בית), חל עליהם הכלל של מעוולים במשותף הקבוע בסעיף 11 לפקודת הנזיקין. ע"א 7436/12 כלל חברה לביטוח בע"מ נ'' ב.י.מ חברה לבניה בע"מ (06.07.2017) ע"א 326/88 עידו צימרמן, קטין באמצעות אביו נ'' דוד גבריאלוב (19.12.1991) במקרים אלו, המעוולים מחויבים בפיצויים על מלוא הנזק ביחד ולחוד כלפי הניזוק. ע"א 7436/12 כלל חברה לביטוח בע"מ נ'' ב.י.מ חברה לבניה בע"מ (06.07.2017) לכן, ניתן לתבוע רק את הילדים שחצו את גיל 12, והם יישאו באחריות ביחד ולחוד לנזק. רע"א 3089/16 נמרוד יוסף מועדי נ'' עזבון ראדי חרבאוי ז"ל (09.08.2016)', 'בלבול בין גיל האחריות הפלילית לגיל האחריות הנזיקית, או אי-הבחנה בין ילדים שחצו את גיל 12 לאלה שלא, והחלת אחריות על כולם או על אף אחד מהם.',
    '["אחריות נזיקית של קטינים", "גיל אחריות נזיקית", "מעוולים במשותף", "אחריות ביחד ולחוד", "נזק בלתי ניתן לחלוקה", "פקודת הנזיקין"]'::jsonb, '**וריאציה 1 — גיל האחריות:** מהו גיל האחריות הנזיקית? ← 12 שנים (סעיף 9 לפקודת הנזיקין).
**וריאציה 2 — מעוולים במשותף:** אם ילדים מעל גיל 12 פעלו יחד וגרמו נזק בלתי ניתן לחלוקה, מהי אחריותם? ← ביחד ולחוד (סעיף 11 לפקודת הנזיקין; ע"א 7436/12 כלל חברה לביטוח).
**וריאציה 3 — חישוב:** 7 ילדים בני 11-13. מי ניתן לתבוע? ← רק הילדים בני 12 ו-13 (סעיף 9 לפקודת הנזיקין).', 'קטין מתחת לגיל 12 ← אינו אחראי בנזיקין. קטין מעל גיל 12 ← אחראי בנזיקין. מעוולים במשותף + נזק בלתי ניתן לחלוקה ← אחריות ביחד ולחוד.', '["פקודת הנזיקין [נוסח חדש], סעיפים 9, 11", "ע\"א 7436/12 כלל חברה לביטוח בע\"מ נ'' ב.י.מ חברה לבניה בע\"מ (06.07.2017)", "ע\"א 326/88 עידו צימרמן, קטין באמצעות אביו נ'' דוד גבריאלוב, פ\"ד מו(1) 353 (19.12.1991)", "רע\"א 3089/16 נמרוד יוסף מועדי נ'' עזבון ראדי חרבאוי ז\"ל (09.08.2016)"]'::jsonb,
    'needs_review=true | classification_review: original chapter=''סדר דין אזרחי'' subtopic=''הליכים'' → mapped chapter=''torts'' subtopic=''negligence'' | classifier_note: Minor liability + joint tortfeasors (7 kids throwing stones). ''Joint tortfeasor'' isn''t a dedicated subtopic; negligence is the closest | source_review_note: השאלה עוסקת באחריות נזיקית של קטינים ובמעוולים במשותף, שהם נושאים מהותיים בדיני נזיקין. דיני נזיקין אינם מופיעים כפרק או תת-נושא מפורש ברשימה הסגורה. בחרתי ב''הליכים'' תחת ''סדר דין אזרחי'' כהצבת מקום, מכיוון שהשאלה עוסקת ביכולת לתבוע (הליך) ומי ניתן לתבוע (צדדים להליך), אך יש לשקול הוספת פרק ''דיני נזיקין'' או תת-נושא רחב יותר תחת ''סדר דין אזרחי'' שיכלול נושאים מהותיים בעלי השלכות דיוניות.', 'active', 'b9ecdde2-d07e-4761-96ab-05f0ad32d4e3'
  );

  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'א', 'לא, מכיוון שגיל האחריות הפלילית הוא 14 שנים.', false, 'טענה זו אינה נכונה. גיל האחריות הפלילית בישראל הוא 12 שנים (סעיף 34ו לחוק העונשין), אך השאלה עוסקת באחריות נזיקית, שגיל האחריות לגביה הוא גם 12 שנים (סעיף 9 לפקודת הנזיקין).', 1);
  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'ב', 'לא, מכיוון שחלק מהילדים לא חצו את גיל 12.', false, 'טענה זו אינה נכונה. אף שילדים מתחת לגיל 12 אינם נושאים באחריות נזיקית, ילדים שחצו את גיל 12 כן יכולים להיתבע.', 2);
  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'ג', 'ניתן לתבוע רק את הילדים שחצו את גיל 12.', true, 'זוהי התשובה הנכונה. לפי סעיף 9 לפקודת הנזיקין [נוסח חדש], אדם שלא מלאו לו 12 שנים אינו אחראי בנזיקין. לכן, רק הילדים בני 12 ו-13 יכולים להיתבע.', 3);
  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'ד', 'כן, מכיוון שחלק מהילדים חצו את גיל 12 והם פעלו יחד.', false, 'טענה זו אינה נכונה. אף שחלק מהילדים חצו את גיל 12 ופעלו יחד, לא ניתן לתבוע את כל הילדים, שכן אלה שמתחת לגיל 12 אינם נושאים באחריות נזיקית.', 4);

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_0, v_sq_id, 'א', 'אחריות קטין מתחת לגיל 12',
    1, 'ילד בן 10 שבר בטעות חלון של בית השכנים בזמן משחק כדורגל. האם ניתן לתבוע אותו בגין הנזק שנגרם?', 'שאלה זו בוחנת את גיל האחריות הנזיקית של קטינים בישראל. היא מדגישה את הכלל הקבוע בסעיף 9 לפקודת הנזיקין [נוסח חדש], לפיו קטין שלא מלאו לו 12 שנים אינו אחראי בנזיקין, וזאת ללא קשר לנסיבות המעשה או למודעותו של הקטין.', 'סעיף 9 לפקודת הנזיקין [נוסח חדש] קובע במפורש כי "אדם שלא מלאו לו שתים עשרה שנים, אינו אחראי בנזיקין". ע"א 326/88 עידו צימרמן, קטין באמצעות אביו נ'' דוד גבריאלוב (19.12.1991) משמעות הדבר היא שקטין מתחת לגיל זה נהנה מחסינות מוחלטת מפני תביעות נזיקין, ואין אפשרות להטיל עליו אחריות אישית בגין נזקים שגרם. הטעם לכך הוא ההנחה כי קטין בגיל זה אינו מסוגל להעריך ולצפות כי יגרום נזק לאחרים על ידי מעשיו. ע"א 326/88 עידו צימרמן, קטין באמצעות אביו נ'' דוד גבריאלוב (19.12.1991) במקרה הנדון, הילד בן 10, ולכן אינו נושא באחריות נזיקית, ודיירי הבית אינם יכולים לתבוע אותו באופן אישי.',
    'בלבול בין גיל האחריות הפלילית (12) לגיל האחריות הנזיקית (12), או הנחה שגויה כי קטין מתחת לגיל 12 יכול להיתבע אם פעל בזדון או במודעות.', '["אחריות נזיקית", "קטינים", "גיל אחריות נזיקית", "פקודת הנזיקין", "חסינות מוחלטת"]'::jsonb, '**וריאציה 1 — גיל האחריות:** מהו גיל האחריות הנזיקית בישראל? ← 12 שנים (סעיף 9 לפקודת הנזיקין).
**וריאציה 2 — קטין בן 10:** האם ילד בן 10 שגרם נזק יכול להיתבע? ← לא, הוא מתחת לגיל האחריות הנזיקית (סעיף 9 לפקודת הנזיקין).
**וריאציה 3 — רציונל:** מדוע קטין מתחת לגיל 12 אינו אחראי? ← אינו מסוגל להעריך ולצפות נזק (ע"א 326/88 צימרמן).', 'קטין מתחת לגיל 12 ← אינו אחראי בנזיקין ← לפי סעיף 9 לפקודת הנזיקין.',
    '["פקודת הנזיקין [נוסח חדש], סעיף 9", "ע\"א 326/88 עידו צימרמן, קטין באמצעות אביו נ'' דוד גבריאלוב, פ\"ד מו(1) 353 (19.12.1991)"]'::jsonb
  );
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_0, 'א', 'כן, אם הוכח שהיה מודע למעשיו.', false, 'טענה זו אינה נכונה. המודעות למעשים אינה רלוונטית כאשר הקטין מתחת לגיל האחריות הנזיקית הקבוע בחוק.', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_0, 'ב', 'לא, מכיוון שאדם שלא מלאו לו 12 שנים אינו אחראי בנזיקין.', true, 'זוהי התשובה הנכונה. לפי סעיף 9 לפקודת הנזיקין [נוסח חדש], ילד מתחת לגיל 12 אינו נושא באחריות נזיקית, ללא קשר למודעותו או לנסיבות המעשה.', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_0, 'ג', 'כן, אך רק אם הוריו יסרבו לשלם את הפיצויים.', false, 'טענה זו אינה נכונה. אחריות ההורים היא נפרדת ואינה תלויה באחריותו הישירה של הקטין מתחת לגיל 12, שאינו אחראי כלל.', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_0, 'ד', 'לא, אלא אם כן מדובר בנזק מכוון.', false, 'טענה זו אינה נכונה. סעיף 9 לפקודת הנזיקין קובע חסינות מוחלטת לקטין מתחת לגיל 12, ללא קשר לסוג הנזק או לכוונה.', 4);

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_1, v_sq_id, 'ב', 'מבחן האחריות של קטין מעל גיל 12',
    2, 'ילדה בת 13 טיפסה על שיש במטבח כדי להגיע למיחם רותח, נפלה ונכוותה. האם ניתן לייחס לה אשם תורם בגין התנהגותה?', 'שאלה זו עוסקת במבחן האחריות הנזיקית של קטינים שחצו את גיל 12, ובפרט ביכולת לייחס להם אשם תורם. היא מדגישה כי אף שקטינים אינם נבחנים באותה מידה כמו בגירים, הם עדיין נדרשים לסטנדרט זהירות מסוים המותאם לגילם ולבגרותם.', 'קטין שחצה את גיל 12 יכול לשאת באחריות נזיקית, וניתן לייחס לו אשם תורם. המבחן לייחוס אשם תורם לקטין אינו זהה למבחן המוחלט של האדם הסביר, אלא הוא מותאם לגילו, בגרותו וניסיונו של הקטין הספציפי. ע"פ 6123/23 מדינת ישראל נ'' פלוני (22.02.2024) בג"ץ 5933/23 באסל זלבאני נ'' מפקד פיקוד העורף (24.08.2023) הפסיקה מכירה בכך שקטינים אינם מחזיקים באותם מנגנוני הגנה ושיקול דעת כמו בגירים, אך עדיין מצופה מהם רמת זהירות מסוימת. ע"פ 8863/15 פלוני נ'' מדינת ישראל (07.06.2016) במקרה הנדון, הילדה בת 13, ולכן ניתן לייחס לה אשם תורם, תוך התחשבות בגילה ובגרותה. ע"א 405/23 AIG ישראל חברה לביטוח בע"מ נ'' פלונית (קטינה) (07.08.2025)',
    'הנחה שגויה כי קטינים פטורים לחלוטין מאחריות או מאשם תורם, או לחלופין, החלת מבחן האדם הסביר באופן מוחלט על קטינים.', '["אחריות נזיקית של קטינים", "אשם תורם", "מבחן הקטין הסביר", "גיל אחריות נזיקית", "פקודת הנזיקין"]'::jsonb, '**וריאציה 1 — גיל האחריות:** האם קטין בן 13 יכול לשאת באחריות נזיקית? ← כן, הוא מעל גיל 12 (סעיף 9 לפקודת הנזיקין).
**וריאציה 2 — מבחן האשם התורם:** באיזה מבחן נבחן אשם תורם של קטין? ← מבחן אובייקטיבי-סובייקטיבי, המותאם לגילו ובגרותו של הקטין הסביר (ע"א 405/23 AIG).
**וריאציה 3 — דוגמה:** האם טיפוס על שיש למיחם יכול להקים אשם תורם לקטינה בת 13? ← כן, הפסיקה הכירה באשם תורם במקרה דומה (ע"א 405/23 AIG).', 'קטין מעל גיל 12 ← אחראי בנזיקין ← נבחן לפי קטין סביר בגילו ובגרותו ← ניתן לייחס אשם תורם.',
    '["פקודת הנזיקין [נוסח חדש], סעיף 9", "ע\"א 405/23 AIG ישראל חברה לביטוח בע\"מ נ'' פלונית (קטינה) (07.08.2025)", "ע\"פ 6123/23 מדינת ישראל נ'' פלוני (22.02.2024)", "בג\"ץ 5933/23 באסל זלבאני נ'' מפקד פיקוד העורף (24.08.2023)", "ע\"פ 8863/15 פלוני נ'' מדינת ישראל (07.06.2016)"]'::jsonb
  );
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_1, 'א', 'לא, מכיוון שקטינים אינם נושאים באחריות נזיקית.', false, 'טענה זו אינה נכונה. קטינים מעל גיל 12 כן נושאים באחריות נזיקית, וניתן לייחס להם אשם תורם.', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_1, 'ב', 'כן, וזאת על פי מבחן האדם הסביר, בשינויים המחויבים לגילה ובגרותה.', true, 'זוהי התשובה הנכונה. קטין מעל גיל 12 נבחן לפי אמת מידה אובייקטיבית-סובייקטיבית של ''קטין סביר'' בגילו ובגרותו, וניתן לייחס לו אשם תורם.', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_1, 'ג', 'לא, אלא אם כן הוכח שהוריה לא פיקחו עליה כראוי.', false, 'טענה זו אינה נכונה. אשם תורם של הקטינה נבחן בנפרד מאחריות הוריה, אם כי פיקוח הורים יכול להשפיע על מידת האשם הכוללת.', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_1, 'ד', 'כן, אך רק אם מדובר בנזק מכוון.', false, 'טענה זו אינה נכונה. אשם תורם יכול לחול גם על מעשים רשלניים, ולא רק על נזק מכוון.', 4);

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_2, v_sq_id, 'ג', 'אחריות הורים בגין מעשי קטינים',
    3, 'האם ניתן להטיל אחריות נזיקית על הורי הילדים בני ה-12 וה-13 שיידו אבנים וגרמו נזק, גם אם לא היו נוכחים בעת האירוע?', 'שאלה זו עוסקת באחריות נזיקית של הורים למעשי ילדיהם הקטינים. היא מדגישה כי אחריות זו אינה אחריות שילוחית מוחלטת, אלא אחריות המבוססת על רשלנותם של ההורים עצמם בהפרת חובת הפיקוח והחינוך על ילדיהם, אשר תרמה להתרחשות הנזק.', 'הדין הישראלי אינו מטיל אחריות שילוחית מוחלטת על הורים למעשי ילדיהם הקטינים בנזיקין. עם זאת, הורים יכולים לשאת באחריות נזיקית בגין מעשי ילדיהם אם הוכח שהם התרשלו בחובת הפיקוח והחינוך על ילדיהם, ורשלנות זו תרמה להתרחשות הנזק. ע"א 326/88 עידו צימרמן, קטין באמצעות אביו נ'' דוד גבריאלוב (19.12.1991) ע"א 405/23 AIG ישראל חברה לביטוח בע"מ נ'' פלונית (קטינה) (07.08.2025) חובת הפיקוח של ההורים נובעת מסעיף 15 לחוק הכשרות המשפטית והאפוטרופסות, התשכ"ב-1962, הקובע כי ההורים הם האפוטרופוסים הטבעיים של ילדיהם וחובתם לדאוג לכל צרכיהם, לרבות חינוכם. בג"ץ 3390/16 עדאלה - המרכז המשפטי לזכויות המיעוט הערבי בישראל נ'' הכנסת (08.07.2021) במקרה זה, אם יוכח שהורי הילדים בני ה-12 וה-13 התרשלו בפיקוח על ילדיהם, ורשלנות זו תרמה ליידוי האבנים ולנזק, ניתן יהיה להטיל עליהם אחריות נזיקית. בג"ץ 3390/16 עדאלה - המרכז המשפטי לזכויות המיעוט הערבי בישראל נ'' הכנסת (08.07.2021)',
    'הנחה שגויה כי הורים אחראים אוטומטית למעשי ילדיהם (אחריות שילוחית), או לחלופין, שהם פטורים לחלוטין מאחריות אם לא היו נוכחים בעת האירוע.', '["אחריות הורים", "רשלנות הורים", "חובת פיקוח", "חוק הכשרות המשפטית והאפוטרופסות", "אחריות נזיקית"]'::jsonb, '**וריאציה 1 — בסיס האחריות:** על איזה בסיס מוטלת אחריות נזיקית על הורים למעשי ילדיהם? ← על בסיס רשלנותם שלהם בהפרת חובת הפיקוח (ע"א 326/88 צימרמן).
**וריאציה 2 — נוכחות ההורים:** האם נוכחות ההורים בעת האירוע היא תנאי לאחריותם? ← לא, אחריות יכולה לקום גם ממחדל בפיקוח (ע"א 326/88 צימרמן).
**וריאציה 3 — אחריות שילוחית:** האם קיימת אחריות שילוחית מוחלטת של הורים למעשי ילדיהם? ← לא, האחריות היא בגין רשלנותם העצמית (בג"ץ 3390/16 עדאלה).', 'אחריות הורים ← מבוססת על רשלנותם בפיקוח ← לא אחריות שילוחית מוחלטת.',
    '["פקודת הנזיקין [נוסח חדש]", "חוק הכשרות המשפטית והאפוטרופסות, תשכ\"ב-1962, סעיף 15", "ע\"א 326/88 עידו צימרמן, קטין באמצעות אביו נ'' דוד גבריאלוב, פ\"ד מו(1) 353 (19.12.1991)", "בג\"ץ 3390/16 עדאלה - המרכז המשפטי לזכויות המיעוט הערבי בישראל נ'' הכנסת (08.07.2021)", "ע\"א 405/23 AIG ישראל חברה לביטוח בע\"מ נ'' פלונית (קטינה) (07.08.2025)"]'::jsonb
  );
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_2, 'א', 'לא, הורים אינם אחראים למעשי ילדיהם אלא אם היו נוכחים ופעלו ברשלנות.', false, 'טענה זו אינה נכונה. אחריות הורים יכולה לקום גם במקרים של מחדל בפיקוח, ללא נוכחות פיזית בעת האירוע.', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_2, 'ב', 'כן, אם הוכח שההורים התרשלו בחובת הפיקוח על ילדיהם.', true, 'זוהי התשובה הנכונה. הורים יכולים לשאת באחריות נזיקית בגין מעשי ילדיהם אם הוכח שהם התרשלו בחובת הפיקוח עליהם, ורשלנות זו תרמה לנזק.', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_2, 'ג', 'לא, מכיוון שהאחריות מוטלת על הילדים עצמם בלבד.', false, 'טענה זו אינה נכונה. אחריות הילדים אינה שוללת אחריות מקבילה או נפרדת של ההורים בגין רשלנותם שלהם.', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_2, 'ד', 'כן, מכוח אחריות שילוחית מוחלטת של הורים למעשי ילדיהם.', false, 'טענה זו אינה נכונה. אין בישראל אחריות שילוחית מוחלטת של הורים למעשי ילדיהם בנזיקין. האחריות נבחנת על בסיס רשלנות ההורים עצמם.', 4);

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_3, v_sq_id, 'ד', 'אחריות מעוולים במשותף בנזק בלתי ניתן לחלוקה',
    4, 'במקרה של יידוי האבנים, אם רק 4 מתוך 7 הילדים היו מעל גיל 12, ונגרם נזק אחד בלתי ניתן לחלוקה, כיצד תחולק האחריות בין הילדים הניתנים לתביעה?', 'שאלה זו עוסקת בדוקטרינת ''מעוולים במשותף'' ובאחריותם כלפי הניזוק, במיוחד כאשר הנזק שנגרם הוא אחד ובלתי ניתן לחלוקה. היא מדגישה את הכלל של ''ביחד ולחוד'' הקבוע בסעיף 11 לפקודת הנזיקין, ואת העדפת הניזוק על פני המעוולים.', 'סעיף 11 לפקודת הנזיקין [נוסח חדש] קובע כי "היה כל אחד משני בני-אדם או יותר חבים לפי הוראות פקודה זו, על מעשה פלוני, והמעשה הוא עוולה, יהיו חבים יחד על אותו מעשה כמעוולים יחד וניתנים להיתבע עליה יחד ולחוד". ע"א 7436/12 כלל חברה לביטוח בע"מ נ'' ב.י.מ חברה לבניה בע"מ (06.07.2017) ע"א 326/88 עידו צימרמן, קטין באמצעות אביו נ'' דוד גבריאלוב (19.12.1991) הפסיקה מבחינה בין שלושה סוגי אירועים בהם שותף יותר ממעוול אחד: מעוולים במשותף, מעוולים בנפרד שגרמו נזק אחד בלתי ניתן לחלוקה, ומעוולים בנפרד שגרמו נזקים נפרדים. בשני המקרים הראשונים, המעוולים מחויבים בפיצויים על מלוא הנזק ביחד ולחוד. ע"א 7436/12 כלל חברה לביטוח בע"מ נ'' ב.י.מ חברה לבניה בע"מ (06.07.2017) ע"א 6894/15 משה זלצר נ'' יעקב אבירם (07.09.2017) במקרה הנדון, הילדים בני ה-12 וה-13 הם מעוולים במשותף שגרמו נזק אחד בלתי ניתן לחלוקה (יידוי אבנים על בית). לכן, הם יחויבו בפיצויים על מלוא הנזק ביחד ולחוד כלפי דיירי הבית. רע"א 3089/16 נמרוד יוסף מועדי נ'' עזבון ראדי חרבאוי ז"ל (09.08.2016)',
    'הנחה שגויה כי האחריות בין מעוולים במשותף מתחלקת תמיד באופן יחסי כלפי הניזוק, במקום להבחין בין היחסים החיצוניים (ביחד ולחוד) ליחסים הפנימיים (חלוקה לפי אשם).', '["מעוולים במשותף", "אחריות ביחד ולחוד", "נזק בלתי ניתן לחלוקה", "פקודת הנזיקין", "חלוקת אחריות פנימית"]'::jsonb, '**וריאציה 1 — סוג הנזק:** אם מספר מעוולים גרמו נזק אחד בלתי ניתן לחלוקה, מהי אחריותם כלפי הניזוק? ← ביחד ולחוד (סעיף 11 לפקודת הנזיקין; ע"א 7436/12 כלל חברה לביטוח).
**וריאציה 2 — יחסים פנימיים:** כיצד מתחלקת האחריות בין המעוולים עצמם? ← לפי חלקו היחסי של כל אחד בנזק (ע"א 6894/15 זלצר).
**וריאציה 3 — תכלית הכלל:** מהי תכלית הכלל ''ביחד ולחוד''? ← להבטיח שהניזוק יקבל פיצוי מלא, ולהעדיף את הניזוק על פני המעוולים (רע"א 3089/16 מועדי).', 'מעוולים במשותף + נזק בלתי ניתן לחלוקה ← אחריות ביחד ולחוד כלפי הניזוק ← חלוקה פנימית לפי אשם.',
    '["פקודת הנזיקין [נוסח חדש], סעיף 11", "ע\"א 7436/12 כלל חברה לביטוח בע\"מ נ'' ב.י.מ חברה לבניה בע\"מ (06.07.2017)", "ע\"א 6894/15 משה זלצר נ'' יעקב אבירם (07.09.2017)", "רע\"א 3089/16 נמרוד יוסף מועדי נ'' עזבון ראדי חרבאוי ז\"ל (09.08.2016)", "ע\"א 878/06 דב טרויהפט נ'' דוד עטיה (04.01.2009)"]'::jsonb
  );
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_3, 'א', 'כל אחד מהילדים הניתנים לתביעה יישא בחלק יחסי מהנזק, לפי מידת אשמתו.', false, 'טענה זו אינה נכונה. במקרה של נזק בלתי ניתן לחלוקה שנגרם על ידי מעוולים במשותף, האחריות כלפי הניזוק היא ''ביחד ולחוד''.', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_3, 'ב', 'הילדים הניתנים לתביעה יחויבו בפיצויים על מלוא הנזק, ביחד ולחוד.', true, 'זוהי התשובה הנכונה. כאשר מספר מעוולים גורמים לנזק אחד בלתי ניתן לחלוקה, הם חבים בפיצויים על מלוא הנזק ביחד ולחוד כלפי הניזוק, בהתאם לסעיף 11 לפקודת הנזיקין.', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_3, 'ג', 'הילדים הניתנים לתביעה יחויבו רק בחלקם היחסי בנזק, שכן הם לא פעלו בתיאום מלא.', false, 'טענה זו אינה נכונה. גם אם לא פעלו בתיאום מלא, אם גרמו לנזק אחד בלתי ניתן לחלוקה, האחריות היא ''ביחד ולחוד''.', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_3, 'ד', 'האחריות תחולק באופן שווה בין כל 7 הילדים, ללא קשר לגילם.', false, 'טענה זו אינה נכונה. ילדים מתחת לגיל 12 אינם נושאים באחריות נזיקית, ולכן לא ניתן לחלק ביניהם אחריות.', 4);

  RAISE NOTICE 'Q% inserted: external_id %', 18, '2022-S-S-Q18';
END
$$;

