-- ============================================================
DO $$
DECLARE
  v_sq_id uuid := 'b9143faf-6ed6-48ac-996e-41346a9b46af'::uuid;
  v_group_id uuid := 'd0fecf6c-e340-4f2c-86b4-83817a93d7e2'::uuid;
  v_chapter_id uuid;
  v_subtopic_id uuid;
  v_existing_id uuid;
  v_ang_0 uuid := '94d1d134-bbb4-4cf2-9493-92e49437dc7d'::uuid;
  v_ang_1 uuid := '424c4769-d92c-4ea6-8e98-09cddac6a3a8'::uuid;
  v_ang_2 uuid := 'e7eeb717-bb1d-4bc3-a3e9-01c79c4a87ce'::uuid;
  v_ang_3 uuid := '61b78809-60a5-431b-aeb8-4a4ed54790ee'::uuid;
BEGIN
  SELECT id INTO v_existing_id FROM public.source_questions WHERE external_id = '2022-S-S-Q19';
  IF v_existing_id IS NOT NULL THEN
    RAISE NOTICE 'Q% skipped: external_id % already exists', 19, '2022-S-S-Q19';
    RETURN;
  END IF;

  SELECT id INTO v_chapter_id FROM public.chapters WHERE code = 'torts';
  IF v_chapter_id IS NULL THEN
    RAISE EXCEPTION 'Chapter code % not found', 'torts';
  END IF;

  SELECT id INTO v_subtopic_id FROM public.subtopics WHERE code = 'strict_liability_torts' AND chapter_id = v_chapter_id;
  IF v_subtopic_id IS NULL THEN
    RAISE EXCEPTION 'Subtopic code % not found under chapter %', 'strict_liability_torts', 'torts';
  END IF;

  INSERT INTO public.source_questions (
    id, question_group_id, version, is_current, external_id, chapter_id, subtopic_id, question_text, source_metadata, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list, notes_for_admin, status, created_by
  ) VALUES (
    v_sq_id, v_group_id, 1, true,
    '2022-S-S-Q19', v_chapter_id, v_subtopic_id, 'נורית ננשכה על ידי סוס, נפצעה והגישה תביעה נזיקית נגד דני הבעלים של הסוס. דני טען כי הוא פטור מאחריות מכיוון שבידו להוכיח שנורית נכנסה לאורווה ללא היתר והתגרתה בסוס. מה הדין?',
    '{"exam_year": 2022, "exam_season": "summer", "exam_part": 2, "exam_question_number": 19}'::jsonb, 'שאלה זו עוסקת באחריות נזיקית לנזקים הנגרמים על ידי חיות, ובפרט בהוראת סעיף 40 לפקודת הנזיקין [נוסח חדש], המעבירה את נטל הראיה להתרשלות לנתבע בתנאים מסוימים. היא בוחנת את התנאים להפעלת סעיף זה ואת ההבחנה בינו לבין אחריות מוגברת לנזקי כלב (סעיף 41א) או הכלל ''הדבר מעיד על עצמו'' (סעיף 41).', 'סעיף 40 לפקודת הנזיקין [נוסח חדש] קובע כי בתובענה שהוגשה על נזק שנגרם על ידי חיה, אם הוכח שהנזק נגרם על ידי חיית בר, או על ידי חיה שאינה חיית בר אלא שהנתבע ידע, או חזקה עליו שידע, כי היא מועדת לעשות את המעשה שגרם את הנזק, ושהנתבע היה בעל החיה או ממונה עליה – אזי על הנתבע הראיה שלא הייתה לגביה התרשלות שיחוב עליה. פקודת הנזיקין [נוסח חדש] | חובת הראיה ברשלנות לגבי חיה 40 סעיף במקרה הנדון, נורית ננשכה על ידי סוס. סוס אינו חיית בר. לכן, כדי להעביר את נטל הראיה לדני, על נורית להוכיח שדני היה בעל הסוס (או ממונה עליו), שהסוס היה מועד לעשות את המעשה שגרם לנזק (נשיכה), וכי דני ידע או חזקה עליו שידע זאת. ע"א 801/89 אהרון כהן נ'' יוסף שבאם (18.03.1992) ת"א (שלום ראשון לציון) 28048-07-20 פלוני נ'' יפה שיבק (16.03.2025) אם נורית תצליח להוכיח תנאים אלו, נטל הראיה יעבור לדני, ויהיה עליו להוכיח שלא התרשל במאום. טענותיו של דני בדבר הסגת גבול והתגרות של נורית אינן פוטרות אותו אוטומטית מאחריות לפי סעיף 40, אלא הן טענות הגנה שעליו להוכיח במסגרת נטל הראיה שהועבר אליו, כדי להראות שלא התרשל. עת"מ (מינהליים י-ם) 45297-09-22 סתיו חנס נ'' לשכת עורכי הדין בישראל (15.11.2022)', 'בלבול בין אחריות מוגברת לנזקי כלב (סעיף 41א) לבין העברת נטל הראיה לנזקי חיות אחרות (סעיף 40), והנחה שגויה כי הגנות כמו התגרות או הסגת גבול פוטרות אוטומטית מאחריות לפי סעיף 40.',
    '["פקודת הנזיקין", "סעיף 40 לפקודת הנזיקין", "נטל הראיה", "חיה מועדת", "ידיעה/חזקה על ידיעה", "התגרות", "הסגת גבול"]'::jsonb, '**וריאציה 1 — סוס:** האם סוס נחשב ל''כלב'' לצורך סעיף 41א? ← לא, סעיף 41א חל רק על כלבים.
**וריאציה 2 — נטל הראיה:** אם נורית הוכיחה את תנאי סעיף 40, על מי נטל הראיה? ← על דני להוכיח שלא התרשל (סעיף 40 לפקודת הנזיקין).
**וריאציה 3 — הגנות:** האם טענות דני להתגרות והסגת גבול פוטרות אותו אוטומטית? ← לא, עליו להוכיח שלא התרשל, וטענות אלו יכולות לשמש כחלק מהגנתו (עת"מ (מינהליים י-ם) 45297-09-22 סתיו חנס).', 'נזק מסוס ← סעיף 40 לפקודת הנזיקין ← נטל הראיה עובר לבעלים להוכיח אי-רשלנות ← טענות התגרות/הסגת גבול אינן פטור אוטומטי.', '["פקודת הנזיקין [נוסח חדש], סעיף 40", "ע\"א 801/89 אהרון כהן נ'' יוסף שבאם, פ\"ד מו(2) 136 (18.03.1992)", "ע\"א 448/83 ורדה קורנהויזר נ'' שמואל מלך, פ\"ד מב(2) 573 (26.06.1988)", "ת\"א (שלום ראשון לציון) 28048-07-20 פלוני נ'' יפה שיבק (16.03.2025)", "עת\"מ (מינהליים י-ם) 45297-09-22 סתיו חנס נ'' לשכת עורכי הדין בישראל (15.11.2022)"]'::jsonb,
    'classification_review: original chapter=''דיני ראיות'' subtopic=''קבילות ראיות'' → mapped chapter=''torts'' subtopic=''strict_liability_torts'' | classifier_note: Horse owner''s liability for bite — strict-liability animal torts under פקודת הנזיקין | source_review_note: השאלה עוסקת באחריות נזיקית לנזקים הנגרמים על ידי חיות, שהיא נושא מהותי בדיני נזיקין. דיני נזיקין אינם מופיעים כפרק או תת-נושא מפורש ברשימה הסגורה. בחרתי ב''קבילות ראיות'' תחת ''דיני ראיות'' כהצבת מקום, מכיוון שהשאלה מתמקדת בהעברת נטל הראיה, שהוא כלל ראייתי. עם זאת, יש לשקול הוספת פרק ''דיני נזיקין'' או תת-נושא רחב יותר תחת ''סדר דין אזרחי'' שיכלול נושאים מהותיים בעלי השלכות דיוניות.', 'active', 'b9ecdde2-d07e-4761-96ab-05f0ad32d4e3'
  );

  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'א', 'דני פטור מאחריות מכיוון שמספיק שהנזק נגרם לנורית כתוצאה מהתגרות שלה בסוס.', false, 'טענה זו אינה נכונה. התגרות בסוס אינה פוטרת אוטומטית מאחריות לפי סעיף 40 לפקודת הנזיקין, אלא אם הנתבע יוכיח שלא התרשל.', 1);
  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'ב', 'דני פטור מאחריות אם האורווה היא מקרקעין בבעלותו ונורית הסיגה גבול.', false, 'טענה זו אינה נכונה. הסגת גבול אינה פוטרת אוטומטית מאחריות לפי סעיף 40 לפקודת הנזיקין, אלא אם הנתבע יוכיח שלא התרשל. הגנות אלו רלוונטיות בעיקר לאחריות מוגברת לנזקי כלב לפי סעיף 41א, שאינו חל על סוסים.', 2);
  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'ג', 'דני פטור מאחריות רק מכיוון שנורית גם הסיגה גבול וגם התגרתה בסוס.', false, 'טענה זו אינה נכונה. שילוב של התגרות והסגת גבול אינו פוטר אוטומטית מאחריות לפי סעיף 40 לפקודת הנזיקין. על הנתבע עדיין להוכיח שלא התרשל.', 3);
  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'ד', 'כדי להיפטר מאחריות על דני להוכיח שלא התרשל במאום.', true, 'זוהי התשובה הנכונה. לפי סעיף 40 לפקודת הנזיקין, אם התובע הוכיח שהנתבע הוא בעל חיה שאינה חיית בר, ושהיא מועדת לעשות את המעשה שגרם לנזק, ושהנתבע ידע או חזקה עליו שידע זאת, אזי עובר נטל הראיה לנתבע להוכיח שלא התרשל.', 4);

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_0, v_sq_id, 'א', 'נזק שנגרם על ידי חיית בר',
    1, 'רשות הטבע והגנים הלאומיים נתבעה בגין נזק שנגרם למטע דגים על ידי שקנאים. האם ניתן להחיל את סעיף 40 לפקודת הנזיקין ולהעביר את נטל הראיה לרשות?', 'שאלה זו בוחנת את תחולתו של סעיף 40 לפקודת הנזיקין על נזקים הנגרמים על ידי חיות בר, ובפרט את התנאי בדבר ''בעלות'' או ''פיקוח'' על החיה. היא מדגישה כי חובת הגנה על חיות בר אינה הופכת גוף ציבורי ל''ממונה'' עליהן לצורך העברת נטל הראיה.', 'סעיף 40 לפקודת הנזיקין [נוסח חדש] קובע כי נטל הראיה להתרשלות עובר לנתבע אם הוכח שהנזק נגרם על ידי חיית בר, ושהנתבע היה בעל החיה או ממונה עליה. פקודת הנזיקין [נוסח חדש] | חובת הראיה ברשלנות לגבי חיה 40 סעיף הפסיקה קבעה כי רשות הטבע והגנים, אף שחובתה להגן על חיות בר, אינה נחשבת ל''בעלים'' או ''ממונה'' על חיות בר כגון שקנאים, שאינן בשליטתה הישירה או בבעלותה. ת"א (מחוזי חי'') 19011-07-14 דג-און אגודה שיתופית חקלאית בע"מ נ'' רשות הטבע והגנים הלאומיים (07.03.2019) לכן, התנאי השני בסעיף 40 אינו מתקיים, ונטל הראיה אינו עובר לרשות. ת"א (מחוזי חי'') 19011-07-14 דג-און אגודה שיתופית חקלאית בע"מ נ'' רשות הטבע והגנים הלאומיים (07.03.2019)',
    'הנחה שגויה כי כל גוף האחראי על שמירת חיות בר נחשב אוטומטית ל''ממונה'' עליהן לצורך סעיף 40, ללא בחינת מידת השליטה והפיקוח בפועל.', '["סעיף 40 לפקודת הנזיקין", "חיית בר", "בעלים", "ממונה", "נטל הראיה", "רשות הטבע והגנים"]'::jsonb, '**וריאציה 1 — חיית בר:** האם שקנאים הם חיות בר? ← כן.
**וריאציה 2 — ממונה:** האם רשות הטבע והגנים נחשבת ל''ממונה'' על שקנאים לצורך סעיף 40? ← לא, חובת הגנה אינה הופכת אותה לממונה (ת"א (מחוזי חי'') 19011-07-14 דג-און).
**וריאציה 3 — נטל הראיה:** האם נטל הראיה עובר לרשות במקרה כזה? ← לא, כי תנאי ה''ממונה'' לא מתקיים (ת"א (מחוזי חי'') 19011-07-14 דג-און).', 'סעיף 40 ← חיית בר ← דורש בעלות/פיקוח ← רט"ג אינה ממונה על שקנאים ← נטל הראיה לא עובר.',
    '["פקודת הנזיקין [נוסח חדש], סעיף 40", "ת\"א (מחוזי חי'') 19011-07-14 דג-און אגודה שיתופית חקלאית בע\"מ נ'' רשות הטבע והגנים הלאומיים (07.03.2019)"]'::jsonb
  );
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_0, 'א', 'כן, מכיוון ששקנאים הם חיות בר, ורשות הטבע והגנים ממונה עליהם.', false, 'טענה זו אינה נכונה. אף ששקנאים הם חיות בר, הרשות אינה נחשבת ל''ממונה'' עליהם במובן של סעיף 40, שכן היא אינה אחראית להגעתם לישראל ואינה בעליהם.', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_0, 'ב', 'לא, מכיוון שסעיף 40 חל רק על חיות שאינן חיות בר.', false, 'טענה זו אינה נכונה. סעיף 40 חל גם על חיות בר, אך דורש שהנתבע יהיה בעל החיה או ממונה עליה.', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_0, 'ג', 'לא, מכיוון שרשות הטבע והגנים אינה הבעלים של השקנאים ואינה ממונה עליהם במובן סעיף 40.', true, 'זוהי התשובה הנכונה. סעיף 40 דורש שהנתבע יהיה בעל החיה או ממונה עליה. הרשות אינה בעלת השקנאים ואינה נחשבת ל''ממונה'' עליהם רק מעצם חובתה להגן עליהם, ולכן התנאי השני בסעיף 40 אינו מתקיים.', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_0, 'ד', 'כן, אם הוכח שהרשות התרשלה במניעת הנזק.', false, 'טענה זו אינה נכונה. אם הוכחה רשלנות, ניתן לתבוע בעוולת הרשלנות הכללית. סעיף 40 עוסק בהעברת נטל הראיה, ולא בעצם קיום הרשלנות.', 4);

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_1, v_sq_id, 'ב', 'תנאים להעברת נטל הראיה לפי סעיף 40',
    2, 'מהם התנאים המצטברים שעל התובע להוכיח כדי להעביר את נטל הראיה לנתבע לפי סעיף 40 לפקודת הנזיקין?', 'שאלה זו מפרטת את התנאים המדויקים והמצטברים הנדרשים להפעלת סעיף 40 לפקודת הנזיקין, המעביר את נטל הראיה להתרשלות לנתבע. היא מדגישה את ההבחנה בין חיית בר לחיה שאינה חיית בר, ואת חשיבות ידיעת הנתבע על מועדות החיה.', 'סעיף 40 לפקודת הנזיקין [נוסח חדש] קובע כי על מנת להעביר את נטל הראיה להתרשלות לנתבע, על התובע להוכיח שלושה תנאים מצטברים: 1. הנזק נגרם על ידי חיית בר, או על ידי חיה שאינה חיית בר אלא שהנתבע ידע, או חזקה עליו שידע, כי היא מועדת לעשות את המעשה שגרם את הנזק. 2. הנתבע היה בעל אחת החיות האמורות או היה ממונה עליה. פקודת הנזיקין [נוסח חדש] | חובת הראיה ברשלנות לגבי חיה 40 סעיף ע"א 801/89 אהרון כהן נ'' יוסף שבאם (18.03.1992) ת"א (שלום ראשון לציון) 28048-07-20 פלוני נ'' יפה שיבק (16.03.2025) רק בהתקיים כל התנאים הללו עובר נטל הראיה לנתבע להוכיח שלא התרשל. ת"א (מחוזי נצרת) 1169/85 הסנה - חברה לביטוח בע"מ נ'' שלמה ציון ועוד 23אחרים (04.06.1989)',
    'בלבול בין התנאים השונים או השמטת אחד מהם, או ערבוב עם תנאים מסעיפים אחרים בפקודת הנזיקין.', '["סעיף 40 לפקודת הנזיקין", "נטל הראיה", "חיית בר", "חיה מועדת", "ידיעה", "בעלות/ממונה"]'::jsonb, '**וריאציה 1 — תנאים מצטברים:** מהם התנאים להעברת נטל הראיה לפי סעיף 40? ← נזק מחיית בר או חיה מועדת + ידיעה/חזקה על ידיעה + בעלות/ממונה (סעיף 40 לפקודת הנזיקין).
**וריאציה 2 — חיה שאינה חיית בר:** מה צריך להוכיח לגבי חיה שאינה חיית בר? ← שהיא מועדת ושהנתבע ידע או חזקה עליו שידע זאת (סעיף 40 לפקודת הנזיקין).
**וריאציה 3 — מועדות:** האם צריך להוכיח שהחיה כבר גרמה נזק בעבר? ← לא, די בניסיונות קודמים או אופי תוקפני (ע"א 448/83 קורנהויזר).', 'סעיף 40 ← נטל ראיה עובר לנתבע ← אם הוכחו 3 תנאים מצטברים: נזק מחיה (בר/מועדת), ידיעה/חזקה על ידיעה, בעלות/ממונה.',
    '["פקודת הנזיקין [נוסח חדש], סעיף 40", "ע\"א 801/89 אהרון כהן נ'' יוסף שבאם, פ\"ד מו(2) 136 (18.03.1992)", "ע\"א 448/83 ורדה קורנהויזר נ'' שמואל מלך, פ\"ד מב(2) 573 (26.06.1988)", "ת\"א (שלום ראשון לציון) 28048-07-20 פלוני נ'' יפה שיבק (16.03.2025)", "ת\"א (מחוזי נצרת) 1169/85 הסנה - חברה לביטוח בע\"מ נ'' שלמה ציון ועוד 23אחרים, תש\"ן(2) 411 (04.06.1989)"]'::jsonb
  );
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_1, 'א', 'הנזק נגרם על ידי חיית בר, והנתבע היה בעל החיה או ממונה עליה.', false, 'טענה זו חלקית. אם החיה אינה חיית בר, יש להוכיח גם מועדות וידיעה/חזקה על ידיעה של הנתבע.', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_1, 'ב', 'הנזק נגרם על ידי חיה, הנתבע היה בעל החיה או ממונה עליה, והחיה הייתה מועדת לעשות את המעשה שגרם לנזק.', false, 'טענה זו חלקית. חסר התנאי של ידיעת הנתבע או חזקה על ידיעה לגבי מועדות החיה, אם אינה חיית בר.', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_1, 'ג', 'הנזק נגרם על ידי חיית בר, או על ידי חיה שאינה חיית בר שהנתבע ידע או חזקה עליו שידע כי היא מועדת לעשות את המעשה שגרם לנזק, ושהנתבע היה בעל החיה או ממונה עליה.', true, 'זוהי התשובה הנכונה. סעיף 40 לפקודת הנזיקין קובע שלושה תנאים מצטברים להעברת נטל הראיה: 1. הנזק נגרם על ידי חיית בר, או חיה שאינה חיית בר שהנתבע ידע או חזקה עליו שידע כי היא מועדת. 2. הנתבע היה בעל החיה או ממונה עליה.', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_1, 'ד', 'הנזק נגרם על ידי חיה, הנתבע היה בעל החיה או ממונה עליה, והתובע לא יכול היה לדעת את נסיבות המקרה.', false, 'טענה זו מערבת תנאים מסעיף 41 לפקודת הנזיקין (הדבר מעיד על עצמו), שאינם רלוונטיים לסעיף 40.', 4);

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_2, v_sq_id, 'ג', 'אחריות מוגברת לנזקי כלב (סעיף 41א)',
    3, 'נורית ננשכה על ידי כלב של דני. דני טוען כי נורית התגרתה בכלב. מה הדין לעניין אחריותו של דני?', 'שאלה זו עוסקת באחריות המוגברת המוטלת על בעלי כלבים לפי סעיף 41א לפקודת הנזיקין, ובחריגים לה הקבועים בסעיף 41ב. היא מדגישה את ההבחנה בין אחריות מוחלטת לבין הגנות הקשורות להתנהגות הניזוק, ואת השלכותיהן על בחינת הרשלנות ואשם תורם.', 'סעיף 41א לפקודת הנזיקין [נוסח חדש] מטיל אחריות מוגברת (כמעט מוחלטת) על בעליו של כלב או מחזיק בו דרך קבע, בגין נזק גוף שנגרם על ידי הכלב, וזאת ללא צורך בהוכחת רשלנות. ת"א (שלום ראשון לציון) 28048-07-20 פלוני נ'' יפה שיבק (16.03.2025) ת"א (שלום נצ'') 5588-01-17 פלונית נ'' אסף בק (28.11.2019) עם זאת, סעיף 41ב לפקודה קובע שלוש הגנות לבעלים, שאחת מהן היא התגרות של הניזוק בכלב. ת"א (שלום ראשון לציון) 28048-07-20 פלוני נ'' יפה שיבק (16.03.2025) אם הוכחה התגרות, אחריות לפי סעיף 41א לא תכונן, והדיון יחזור לכללי הרשלנות הרגילים, בהם ניתן לבחון אשם תורם של הניזוק. ת"א (שלום חי'') 10141-11-13 חנה ידגאר נ'' חיים בן עמי (12.04.2015)',
    'הנחה שגויה כי אחריות בעלי כלבים היא מוחלטת ללא כל הגנה, או לחלופין, שהגנות סעיף 41ב פוטרות מאחריות באופן מוחלט ולא רק מעבירות את הדיון לכללי הרשלנות.', '["סעיף 41א לפקודת הנזיקין", "סעיף 41ב לפקודת הנזיקין", "אחריות מוגברת", "הגנות", "התגרות בכלב", "אשם תורם"]'::jsonb, '**וריאציה 1 — אחריות כלב:** מהי אחריות בעל כלב לנזק גוף? ← אחריות מוגברת לפי סעיף 41א לפקודת הנזיקין.
**וריאציה 2 — הגנת התגרות:** אם הניזוק התגרה בכלב, האם הבעלים פטור? ← לא תכונן אחריות לפי 41א, והדיון יעבור לכללי הרשלנות הרגילים (סעיף 41ב(1) לפקודת הנזיקין).
**וריאציה 3 — אשם תורם:** האם ניתן לייחס אשם תורם לניזוק שהתגרה? ← כן, במסגרת כללי הרשלנות הרגילים (ת"א (שלום חי'') 10141-11-13 ידגאר).', 'נזק גוף מכלב ← אחריות מוגברת (41א) ← הגנות (41ב) ← התגרות ← מעבר לכללי רשלנות רגילים + אשם תורם.',
    '["פקודת הנזיקין [נוסח חדש], סעיפים 41א, 41ב", "ת\"א (שלום ראשון לציון) 28048-07-20 פלוני נ'' יפה שיבק (16.03.2025)", "ת\"א (שלום נצ'') 5588-01-17 פלונית נ'' אסף בק (28.11.2019)", "ת\"א (שלום חי'') 10141-11-13 חנה ידגאר נ'' חיים בן עמי (12.04.2015)"]'::jsonb
  );
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_2, 'א', 'דני פטור מאחריות באופן מוחלט, מכיוון שהתגרות היא הגנה מלאה.', false, 'טענה זו אינה נכונה. התגרות היא הגנה לפי סעיף 41ב, אך היא אינה פוטרת אוטומטית מאחריות, אלא מעבירה את הדיון לכללי הרשלנות הרגילים, בהם ניתן לבחון אשם תורם.', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_2, 'ב', 'דני חייב באחריות מוחלטת, שכן סעיף 41א לפקודת הנזיקין מטיל אחריות ללא קשר לרשלנות.', false, 'טענה זו אינה נכונה. אף שסעיף 41א מטיל אחריות מוגברת, סעיף 41ב קובע הגנות, ביניהן התגרות, המאפשרות לבעלים להתגונן.', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_2, 'ג', 'אם הוכחה התגרות, לא תכונן אחריות לפי סעיף 41א, והדיון יעבור לכללי הרשלנות הרגילים, בהם ניתן לייחס אשם תורם לנורית.', true, 'זוהי התשובה הנכונה. סעיף 41א קובע אחריות מוגברת לנזקי כלב, אך סעיף 41ב קובע הגנות, ביניהן התגרות. אם הגנה זו מתקיימת, אחריות לפי 41א לא תכונן, והדיון יחזור לכללי הרשלנות הרגילים, בהם ניתן לייחס אשם תורם.', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_2, 'ד', 'דני פטור מאחריות רק אם יוכיח שהתגרות נורית הייתה הסיבה הבלעדית לנזק.', false, 'טענה זו אינה נכונה. התגרות היא אחת ההגנות המפורטות בסעיף 41ב, ואין צורך להוכיח שהיא הסיבה הבלעדית, אלא שהנזק נגרם ''עקב'' ההתגרות.', 4);

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_3, v_sq_id, 'ד', 'נטל הראיה ברשלנות כשהדבר מעיד על עצמו (סעיף 41)',
    4, 'נורית נפלה מסוס בחווה במהלך רכיבה, אך אינה יודעת מה היו הנסיבות המדויקות שגרמו לנפילה. היא טוענת שהחווה התרשלה. האם ניתן להעביר את נטל הראיה לחווה מכוח סעיף 41 לפקודת הנזיקין?', 'שאלה זו בוחנת את תחולתו של סעיף 41 לפקודת הנזיקין (הכלל ''הדבר מעיד על עצמו'') במקרים של נזק הנגרם על ידי חיות. היא מדגישה כי סעיף זה יכול לשמש כעילה חלופית או משלימה לסעיף 40, ומפרטת את התנאים המצטברים להפעלתו.', 'סעיף 41 לפקודת הנזיקין [נוסח חדש] קובע את הכלל ''הדבר מעיד על עצמו'', המעביר את נטל הראיה לנתבע אם התובע הוכיח שלושה תנאים מצטברים: 1. לתובע לא הייתה ידיעה או יכולת לדעת מה היו למעשה הנסיבות שגרמו לנזק. 2. הנזק נגרם על ידי נכס שלנתבע הייתה שליטה מלאה עליו. 3. אירוע הנזק מתיישב יותר עם המסקנה שהנתבע לא נקט זהירות סבירה מאשר עם המסקנה שהוא נקט זהירות סבירה. ת"א (שלום ראשון לציון) 632/98 ענת מנדר נ'' קיבוץ יסעור (07.06.2004) הפסיקה קבעה כי סעיף 41 יכול לחול גם על נזקים הנגרמים על ידי חיות, שכן חיה נחשבת ל''נכס'' לעניין זה. ת"א (מחוזי תל אביב-יפו) 772/82 שמואל מלך נ'' ורדה וריצ''רד קורנהאוזר, תשמ"ד(1) 192 (28.07.1983) סעיף 40 וסעיף 41 אינם דוחים זה את זה, והתובע יכול לנסות להסתמך על שניהם. ת"א (מחוזי תל אביב-יפו) 772/82 שמואל מלך נ'' ורדה וריצ''רד קורנהאוזר, תשמ"ד(1) 192 (28.07.1983) במקרה של נפילה מסוס בחווה, אם התובע אינו יודע את נסיבות הנפילה, הסוס היה בשליטת החווה, והנפילה מתיישבת יותר עם רשלנות החווה (למשל, אי-הדרכה מספקת, סוס לא מתאים), ניתן להעביר את נטל הראיה לחווה. ת"א (שלום י-ם) 2588/02 מלכה טננבוים (ארז) נ'' חווית הרוכבים-בית אורן בע"מ (26.10.2005)',
    'הנחה שגויה כי סעיף 41 אינו רלוונטי לנזקים הנגרמים על ידי חיות, או בלבול בין תנאיו לבין תנאי סעיף 40.', '["סעיף 41 לפקודת הנזיקין", "הדבר מעיד על עצמו", "נטל הראיה", "שליטה מלאה", "נכס", "רשלנות"]'::jsonb, '**וריאציה 1 — תנאי סעיף 41:** מהם התנאים להעברת נטל הראיה לפי סעיף 41? ← חוסר ידיעה של התובע, שליטה מלאה של הנתבע על הנכס, והתיישבות עם רשלנות הנתבע (סעיף 41 לפקודת הנזיקין).
**וריאציה 2 — חיה כנכס:** האם סוס נחשב ל''נכס'' לצורך סעיף 41? ← כן (ת"א (מחוזי ת"א) 772/82 מלך).
**וריאציה 3 — יחס לסעיף 40:** האם סעיף 40 דוחה את סעיף 41? ← לא, הם יכולים לחול במקביל או לחלופין (ת"א (מחוזי ת"א) 772/82 מלך).', 'נזק מחיה + חוסר ידיעה של התובע ← ניתן להפעיל סעיף 41 (''הדבר מעיד על עצמו'') ← אם מתקיימים תנאיו.',
    '["פקודת הנזיקין [נוסח חדש], סעיף 41", "ת\"א (מחוזי תל אביב-יפו) 772/82 שמואל מלך נ'' ורדה וריצ''רד קורנהאוזר, פ\"ד תשמ\"ד(1) 192 (28.07.1983)", "ת\"א (שלום ראשון לציון) 632/98 ענת מנדר נ'' קיבוץ יסעור (07.06.2004)", "ת\"א (שלום י-ם) 2588/02 מלכה טננבוים (ארז) נ'' חווית הרוכבים-בית אורן בע\"מ (26.10.2005)"]'::jsonb
  );
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_3, 'א', 'לא, מכיוון שסעיף 41 אינו חל על נזקים הנגרמים על ידי חיות.', false, 'טענה זו אינה נכונה. הפסיקה קבעה שסעיף 41 יכול לחול גם על נזקים הנגרמים על ידי חיות, שכן חיה נחשבת ל''נכס''.', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_3, 'ב', 'כן, אם נורית תוכיח שלא הייתה לה ידיעה או יכולת לדעת את נסיבות המקרה, שהנזק נגרם על ידי נכס (הסוס) שהיה בשליטה מלאה של החווה, ושאירוע הנזק מתיישב יותר עם רשלנות החווה.', true, 'זוהי התשובה הנכונה. סעיף 41 לפקודת הנזיקין קובע שלושה תנאים מצטברים להעברת נטל הראיה בטענת ''הדבר מעיד על עצמו'', והם יכולים לחול גם במקרים של נזק שנגרם על ידי חיה.', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_3, 'ג', 'לא, מכיוון שסעיף 40 לפקודת הנזיקין הוא הסעיף הספציפי לנזקים הנגרמים על ידי חיות, ולכן סעיף 41 נדחה מפניו.', false, 'טענה זו אינה נכונה. סעיפים 40 ו-41 יכולים לחול במקביל או לחלופין, וסעיף 40 אינו דוחה את תחולת סעיף 41.', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_3, 'ד', 'כן, אך רק אם החווה לא סיפקה לנורית הדרכה כלשהי לפני הרכיבה.', false, 'טענה זו אינה נכונה. אי-מתן הדרכה הוא עילה לרשלנות בפני עצמה, אך אינו תנאי בלעדי להחלת סעיף 41.', 4);

  RAISE NOTICE 'Q% inserted: external_id %', 19, '2022-S-S-Q19';
END
$$;

