  INSERT INTO public.source_questions (
    id, question_group_id, version, is_current, external_id, chapter_id, subtopic_id, question_text, source_metadata, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list, notes_for_admin, status, created_by
  ) VALUES (
    v_sq_id, v_group_id, 1, true,
    '2022-S-S-Q20', v_chapter_id, v_subtopic_id, 'רחל חתמה על הסכם עם לאה, ולפיו היא תשכור ממנה חנות למשך 5 שנים. לאחר החתימה, בטרם קבלת המפתח, הזמינה רחל ריהוט המותאם באופן ספציפי לחנות בסך של 150,000 ש"ח. לאחר שיעקב המתווך שמע על כך הוא שכנע את לאה להודיע לרחל שההסכם מבוטל כדי שלאה תחתום דרכו הסכם חדש עם שוכר שמוכן לשלם יותר. האם רחל יכולה לתבוע פיצוי מיעקב?',
    '{"exam_year": 2022, "exam_season": "summer", "exam_part": 2, "exam_question_number": 20}'::jsonb, 'שאלה זו עוסקת בעוולת גרם הפרת חוזה שלא כדין, הקבועה בסעיף 62 לפקודת הנזיקין [נוסח חדש]. היא בוחנת את יכולתו של צד שלישי, שאינו צד לחוזה, לשאת באחריות נזיקית בגין גרימת הפרת חוזה, תוך התמקדות ביסוד נזק הממון הנדרש לצורך קבלת פיצויים.', 'עוולת גרם הפרת חוזה שלא כדין מעוגנת בסעיף 62(א) לפקודת הנזיקין [נוסח חדש], הקובע כי "מי שביודעין ובלי צידוק מספיק גורם לאדם שיפר חוזה מחייב כדין שבינו לבין אדם שלישי, הריהו עושה עוולה כלפי אותו אדם שלישי, אולם האדם השלישי לא יוכל להיפרע פיצויים בעד עוולה זו אלא אם סבל על ידי כך נזק ממון". פקודת הנזיקין [נוסח חדש] | גרם הפרת חוזה שלא כדין 62 סעיף הפסיקה מנתה חמישה יסודות מצטברים לעוולה זו: קיומו של חוזה תקף, הפרת החוזה, גרימת ההפרה, ידיעת הצד השלישי (יסוד ''ביודעין''), והיעדר צידוק מספיק. ע"א 1137/23 אליהו דרעי נ'' קרן קיימת לישראל (05.05.2025) ע"א 8191/16 דיאליט בע"מ נ'' אברהם הרר (17.06.2019) במקרה הנדון, רחל ולאה חתמו על הסכם שכירות תקף. לאה הפרה את ההסכם בעקבות שכנועו של יעקב המתווך, שידע על קיום ההסכם ופעל ללא צידוק מספיק (מניע של רווח אישי). בנוסף, רחל סבלה נזק ממון בדמות הזמנת הריהוט. כל היסודות מתקיימים, ולכן רחל יכולה לתבוע פיצויים מיעקב. ת"א (מחוזי חי'') 6107-09-13 ענבר אמאדו נ'' הבונים, מושב שיתופי להתיישבות חיילים משוחררים בע"מ (26.04.2021)', 'אי-הבחנה בין עילת תביעה חוזית נגד המפר לבין עילת תביעה נזיקית נגד הצד השלישי, או אי-הכרת יסודות עוולת גרם הפרת חוזה, ובפרט דרישת נזק הממון.',
    '["גרם הפרת חוזה שלא כדין", "פקודת הנזיקין", "יסודות העוולה", "נזק ממון", "צד שלישי", "אחריות נזיקית"]'::jsonb, '**וריאציה 1 — יסודות העוולה:** מהם היסודות של גרם הפרת חוזה? ← חוזה, הפרה, גרימה, ידיעה, היעדר צידוק (סעיף 62 לפקודת הנזיקין).
**וריאציה 2 — נזק ממון:** האם נזק ממון הוא תנאי לפיצויים? ← כן, סעיף 62(א) לפקודת הנזיקין דורש זאת.
**וריאציה 3 — מתווך:** האם מתווך שמשכנע להפר חוזה יכול להיתבע? ← כן, אם מתקיימים יסודות העוולה, כולל נזק ממון (כמו במקרה זה).', 'רחל יכולה לתבוע את יעקב בגין גרם הפרת חוזה שלא כדין, שכן התקיימו כל יסודות העוולה, כולל נזק ממון.', '["פקודת הנזיקין [נוסח חדש], סעיף 62", "ע\"א 1137/23 אליהו דרעי נ'' קרן קיימת לישראל (05.05.2025)", "ע\"א 8191/16 דיאליט בע\"מ נ'' אברהם הרר (17.06.2019)", "ת\"א (מחוזי חי'') 6107-09-13 ענבר אמאדו נ'' הבונים, מושב שיתופי להתיישבות חיילים משוחררים בע\"מ (26.04.2021)", "בג\"ץ 5239/11 אורי אבנרי נ'' הכנסת (15.04.2015)"]'::jsonb,
    'needs_review=true | classification_review: original chapter=''סדר דין אזרחי'' subtopic=''הליכים'' → mapped chapter=''torts'' subtopic=''negligence'' | classifier_note: Inducement of breach of contract (matchmaker convincing Leah to break lease). Inducement-of-breach isn''t a dedicated subtopic; closest substantive home is torts/negligence | source_review_note: השאלה עוסקת בעוולת גרם הפרת חוזה, שהיא נושא מהותי בדיני נזיקין. דיני נזיקין אינם מופיעים כפרק או תת-נושא מפורש ברשימה הסגורה. בחרתי ב''הליכים'' תחת ''סדר דין אזרחי'' כהצבת מקום, מכיוון שהשאלה עוסקת ביכולת לתבוע (הליך) ומי ניתן לתבוע (צדדים להליך), אך יש לשקול הוספת פרק ''דיני נזיקין'' או תת-נושא רחב יותר תחת ''סדר דין אזרחי'' שיכלול נושאים מהותיים בעלי השלכות דיוניות.', 'active', 'b9ecdde2-d07e-4761-96ab-05f0ad32d4e3'
  );

  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'א', 'כן, מכיוון שנגרם לה נזק ממון.', true, 'זוהי התשובה הנכונה. עוולת גרם הפרת חוזה שלא כדין (סעיף 62 לפקודת הנזיקין) מאפשרת לתבוע פיצויים מצד שלישי שגרם להפרת חוזה, בתנאי שנגרם נזק ממון.', 1);
  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'ב', 'לא, מכיוון שיעקב אינו צד להסכם.', false, 'טענה זו אינה נכונה. עוולת גרם הפרת חוזה שלא כדין מיועדת בדיוק למקרים בהם צד שלישי, שאינו צד לחוזה, גורם להפרתו.', 2);
  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'ג', 'כן, אף אם נגרמה לה עוגמת נפש בלבד.', false, 'טענה זו אינה נכונה. סעיף 62(א) לפקודת הנזיקין קובע במפורש כי פיצויים בגין עוולה זו יינתנו רק אם סבל התובע ''נזק ממון''.', 3);
  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'ד', 'לא, עילת התביעה של לאה היא נגד רחל בלבד.', false, 'טענה זו אינה נכונה. עילת התביעה של רחל היא נגד לאה בגין הפרת חוזה, אך בנוסף קיימת לה עילת תביעה נזיקית נגד יעקב בגין גרם הפרת חוזה.', 4);

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_0, v_sq_id, 'א', 'גרם הפרת חוזה ללא נזק ממון',
    1, 'ראובן שכנע את שמעון להפר חוזה עם לוי. לוי סבל עוגמת נפש רבה כתוצאה מההפרה, אך לא נגרם לו כל נזק ממון. האם לוי יכול לתבוע פיצויים מראובן בגין גרם הפרת חוזה?', 'שאלה זו מתמקדת ביסוד ''נזק ממון'' הנדרש לצורך קבלת פיצויים בעוולת גרם הפרת חוזה שלא כדין, כפי שקבוע בסעיף 62(א) לפקודת הנזיקין. היא מדגישה כי גם אם כל יתר יסודות העוולה מתקיימים, היעדר נזק ממון ימנע פסיקת פיצויים.', 'סעיף 62(א) לפקודת הנזיקין [נוסח חדש] קובע במפורש כי "האדם השלישי לא יוכל להיפרע פיצויים בעד עוולה זו אלא אם סבל על ידי כך נזק ממון". פקודת הנזיקין [נוסח חדש] | גרם הפרת חוזה שלא כדין 62 סעיף ת"א (מחוזי חי'') 6107-09-13 ענבר אמאדו נ'' הבונים, מושב שיתופי להתיישבות חיילים משוחררים בע"מ (26.04.2021) צפורה כהן בעלי מניות בחברה - זכויות תביעה ותרופות - חלק ג'' (2010) | פרק חמישי גרם הפרת חוזה משמעות הדבר היא כי גם אם כל יתר יסודות העוולה (קיום חוזה, הפרה, גרימה, ידיעה והיעדר צידוק) מתקיימים, ללא הוכחת נזק ממון, לא ניתן יהיה לפסוק פיצויים. עוגמת נפש, בהיותה נזק לא ממוני, אינה מספקת לצורך סעיף זה. בג"ץ 5239/11 אורי אבנרי נ'' הכנסת (15.04.2015)',
    'הנחה שגויה כי די בקיום יסודות העוולה האחרים כדי לזכות בפיצויים, מבלי להתייחס לדרישת נזק הממון הספציפית של סעיף 62(א).', '["גרם הפרת חוזה שלא כדין", "פקודת הנזיקין", "נזק ממון", "פיצויים", "עוגמת נפש", "יסודות העוולה"]'::jsonb, '**וריאציה 1 — נזק ממון:** האם נזק ממון הוא תנאי לפיצויים בגרם הפרת חוזה? ← כן, סעיף 62(א) לפקודת הנזיקין דורש זאת.
**וריאציה 2 — עוגמת נפש:** האם עוגמת נפש מספיקה לפיצויים? ← לא, נדרש נזק ממון (סעיף 62(א) לפקודת הנזיקין).
**וריאציה 3 — סעדים אחרים:** האם ניתן לתבוע סעדים אחרים (כמו צו מניעה) ללא נזק ממון? ← סעיף 62(א) מתייחס לפיצויים, אך ייתכנו סעדים אחרים שאינם תלויים בנזק ממון (כגון צו מניעה), אם כי הפסיקה מתייחסת בעיקר לפיצויים (ע"א 1137/23 דרעי, פסקה 180).', 'גרם הפרת חוזה ← פיצויים רק בגין נזק ממון ← עוגמת נפש אינה מספיקה.',
    '["פקודת הנזיקין [נוסח חדש], סעיף 62", "ע\"א 1137/23 אליהו דרעי נ'' קרן קיימת לישראל (05.05.2025)", "בג\"ץ 5239/11 אורי אבנרי נ'' הכנסת (15.04.2015)", "ת\"א (מחוזי חי'') 6107-09-13 ענבר אמאדו נ'' הבונים, מושב שיתופי להתיישבות חיילים משוחררים בע\"מ (26.04.2021)", "צפורה כהן בעלי מניות בחברה - זכויות תביעה ותרופות - חלק ג'' (2010) | פרק חמישי גרם הפרת חוזה"]'::jsonb
  );
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_0, 'א', 'כן, מכיוון שראובן פעל בזדון.', false, 'טענה זו אינה נכונה. אף שפעולה בזדון היא יסוד בעוולה, סעיף 62(א) לפקודת הנזיקין דורש נזק ממון כתנאי לפיצויים.', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_0, 'ב', 'לא, מכיוון שסעיף 62(א) לפקודת הנזיקין דורש נזק ממון כתנאי לפיצויים.', true, 'זוהי התשובה הנכונה. סעיף 62(א) לפקודת הנזיקין קובע במפורש כי ''האדם השלישי לא יוכל להיפרע פיצויים בעד עוולה זו אלא אם סבל על ידי כך נזק ממון''.', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_0, 'ג', 'כן, אך רק אם יוכיח שראובן פעל ללא צידוק מספיק.', false, 'טענה זו אינה נכונה. היעדר צידוק מספיק הוא יסוד בעוולה, אך אינו פוטר מהדרישה לנזק ממון לצורך קבלת פיצויים.', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_0, 'ד', 'לא, מכיוון שראובן אינו צד לחוזה.', false, 'טענה זו אינה נכונה. עוולת גרם הפרת חוזה מיועדת בדיוק למקרים בהם צד שלישי, שאינו צד לחוזה, גורם להפרתו.', 4);

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_1, v_sq_id, 'ב', 'יסודות עוולת גרם הפרת חוזה',
    2, 'מהם היסודות המצטברים הנדרשים לקיומה של עוולת גרם הפרת חוזה שלא כדין, לפי סעיף 62 לפקודת הנזיקין?', 'שאלה זו בוחנת את ההבנה של היסודות המצטברים המרכיבים את עוולת גרם הפרת חוזה שלא כדין, כפי שפורשו בפסיקה ובספרות המשפטית. היא מדגישה את חמשת התנאים ההכרחיים להוכחת העוולה, בטרם ייבחנו סעדים.', 'הפסיקה והספרות המשפטית מנו חמישה יסודות מצטברים לקיומה של עוולת גרם הפרת חוזה שלא כדין, הקבועה בסעיף 62(א) לפקודת הנזיקין [נוסח חדש]: פקודת הנזיקין [נוסח חדש] | גרם הפרת חוזה שלא כדין 62 סעיף (א) קיומו של חוזה מחייב כדין; (ב) הפרה של החוזה; (ג) גרימה – קשר סיבתי בין פעולת הגורם המתערב לבין מעשה ההפרה; (ד) ידיעת הגורם המתערב לגבי החוזה ולכך שמעשיו עלולים להביא להפרתו (יסוד ''ביודעין''); (ה) חוסר צידוק למעשיו של הגורם המתערב (''בלי צידוק מספיק''). ע"א 1137/23 אליהו דרעי נ'' קרן קיימת לישראל (05.05.2025) ע"א 8191/16 דיאליט בע"מ נ'' אברהם הרר (17.06.2019) בנוסף, לצורך קבלת פיצויים, נדרש גם נזק ממון. ת"א (מחוזי חי'') 6107-09-13 ענבר אמאדו נ'' הבונים, מושב שיתופי להתיישבות חיילים משוחררים בע"מ (26.04.2021)',
    'השמטת אחד מיסודות העוולה או בלבול בינם לבין דרישת נזק הממון, שהוא תנאי לסעד הפיצויים ולא ליסוד העוולה עצמה.', '["גרם הפרת חוזה שלא כדין", "פקודת הנזיקין", "יסודות העוולה", "חוזה תקף", "הפרה", "גרימה", "ידיעה", "היעדר צידוק"]'::jsonb, '**וריאציה 1 — חמשת היסודות:** מהם חמשת היסודות של גרם הפרת חוזה? ← חוזה, הפרה, גרימה, ידיעה, היעדר צידוק (סעיף 62 לפקודת הנזיקין; ע"א 1137/23 דרעי).
**וריאציה 2 — נזק ממון:** האם נזק ממון הוא יסוד בעוולה? ← לא, הוא תנאי לקבלת פיצויים (סעיף 62(א) לפקודת הנזיקין).
**וריאציה 3 — הפרת חובת אמון:** האם גרם הפרת חובת אמון יכול להיחשב כגרם הפרת חוזה? ← כן, הפרת חובת אמון כמוה כהפרת חוזה לעניין זה (ע"א 1137/23 דרעי, פסקה 177).', 'גרם הפרת חוזה ← 5 יסודות מצטברים: חוזה, הפרה, גרימה, ידיעה, היעדר צידוק.',
    '["פקודת הנזיקין [נוסח חדש], סעיף 62", "ע\"א 1137/23 אליהו דרעי נ'' קרן קיימת לישראל (05.05.2025)", "ע\"א 8191/16 דיאליט בע\"מ נ'' אברהם הרר (17.06.2019)", "ת\"א (מחוזי חי'') 6107-09-13 ענבר אמאדו נ'' הבונים, מושב שיתופי להתיישבות חיילים משוחררים בע\"מ (26.04.2021)", "בג\"ץ 5239/11 אורי אבנרי נ'' הכנסת (15.04.2015)"]'::jsonb
  );
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_1, 'א', 'קיומו של חוזה תקף, הפרת החוזה, גרימת ההפרה, ידיעת הצד השלישי, והיעדר צידוק מספיק.', true, 'זוהי התשובה הנכונה. אלו הם חמשת היסודות המצטברים של עוולת גרם הפרת חוזה שלא כדין, כפי שנקבעו בפסיקה ובספרות המשפטית.', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_1, 'ב', 'קיומו של חוזה תקף, הפרת החוזה, גרימת ההפרה, ידיעת הצד השלישי, והוכחת נזק ממון.', false, 'טענה זו אינה נכונה. חסר היסוד של ''היעדר צידוק מספיק'', ונזק ממון הוא תנאי לפיצויים ולא ליסוד העוולה עצמה.', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_1, 'ג', 'קיומו של חוזה תקף, הפרת החוזה, גרימת ההפרה, והוכחת כוונת זדון של הצד השלישי.', false, 'טענה זו אינה נכונה. היסוד הנפשי הנדרש הוא ''ביודעין'' (ידיעה), ולא בהכרח ''כוונת זדון''. חסר גם היסוד של ''היעדר צידוק מספיק''.', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_1, 'ד', 'קיומו של חוזה תקף, גרימת ההפרה, ידיעת הצד השלישי, והיעדר צידוק מספיק.', false, 'טענה זו אינה נכונה. חסר היסוד המהותי של ''הפרת החוזה'' עצמה.', 4);

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_2, v_sq_id, 'ג', 'צידוק מספיק בגרם הפרת חוזה',
    3, 'עורך דין ייעץ ללקוחו להפר חוזה עם צד שלישי, מכיוון שלדעתו החוזה פוגע באופן קשה באינטרסים לגיטימיים של הלקוח. האם ייעוץ זה יכול להיחשב כ''צידוק מספיק'' לעניין עוולת גרם הפרת חוזה שלא כדין?', 'שאלה זו עוסקת ביסוד ''היעדר צידוק מספיק'' בעוולת גרם הפרת חוזה שלא כדין, שהוא היסוד המורכב ביותר בעוולה. היא בוחנת את שיקול הדעת הרחב המוקנה לבית המשפט בקביעת צידוק, ואת האפשרות שייעוץ משפטי לגיטימי ייחשב כצידוק מספיק.', 'היסוד של ''היעדר צידוק מספיק'' הוא המורכב ביותר בעוולת גרם הפרת חוזה שלא כדין, ומוקנה לבית המשפט שיקול דעת רחב בקביעה אם היה צידוק מספיק לגרום להפרה. ע"א 1137/23 אליהו דרעי נ'' קרן קיימת לישראל (05.05.2025) צידוק יכול להיות מושתת על אינטרס עצמי (כגון צורך, הגנה על זכות קניינית או חוזית) או אינטרס ציבורי אחר. על האינטרס להיתפס כעדיף, או לכל הפחות מקביל בחשיבותו, לאינטרס שבהגנת הקשר החוזי. ע"א 8191/16 דיאליט בע"מ נ'' אברהם הרר (17.06.2019) נבו - המתמחה דיני נזיקין (2026) | גרם הפרת חוזה שלא כדין ייעוץ של עורך דין ללקוחו, שנועד להגן על אינטרסים לגיטימיים של הלקוח, יכול להיחשב כצידוק מספיק, במיוחד לאור יחסי הקרבה המיוחדים בין עורך דין ללקוחו. נבו - המתמחה דיני נזיקין (2026) | גרם הפרת חוזה שלא כדין',
    'הנחה שגויה כי כל התערבות בחוזה היא אסורה, או אי-הבנה של המורכבות והשיקולים הרחבים הנבחנים בקביעת ''צידוק מספיק''.', '["גרם הפרת חוזה שלא כדין", "צידוק מספיק", "איזון אינטרסים", "שיקול דעת שיפוטי", "ייעוץ משפטי", "פקודת הנזיקין"]'::jsonb, '**וריאציה 1 — הגדרת צידוק:** מהו ''צידוק מספיק''? ← אינטרס עצמי (כגון הגנה על זכות) או ציבורי, העדיף או מקביל בחשיבותו להגנת הקשר החוזי (ע"א 8191/16 דיאליט).
**וריאציה 2 — ייעוץ עו"ד:** האם ייעוץ עו"ד ללקוח להפר חוזה יכול להיות צידוק? ← כן, אם נועד להגן על אינטרס לגיטימי של הלקוח, לאור יחסי הקרבה (נבו - המתמחה, דיני נזיקין).
**וריאציה 3 — שיקול דעת:** מי קובע אם קיים צידוק מספיק? ← בית המשפט, בשיקול דעת רחב (ע"א 1137/23 דרעי).', 'צידוק מספיק ← אינטרס עדיף/מקביל ← שיקול דעת ביהמ"ש ← ייעוץ עו"ד יכול להוות צידוק.',
    '["פקודת הנזיקין [נוסח חדש], סעיף 62", "ע\"א 1137/23 אליהו דרעי נ'' קרן קיימת לישראל (05.05.2025)", "ע\"א 8191/16 דיאליט בע\"מ נ'' אברהם הרר (17.06.2019)", "נבו - המתמחה דיני נזיקין (2026) | גרם הפרת חוזה שלא כדין"]'::jsonb
  );
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_2, 'א', 'לא, מכיוון שייעוץ להפרת חוזה תמיד נחשב לפעולה פסולה.', false, 'טענה זו אינה נכונה. קיימים מקרים בהם ייעוץ משפטי להפרת חוזה יכול להיחשב כצידוק מספיק, במיוחד כאשר הוא נועד להגן על אינטרס לגיטימי של הלקוח.', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_2, 'ב', 'כן, אם האינטרס של הלקוח עדיף או מקביל בחשיבותו לאינטרס שבהגנת הקשר החוזי, ובהתחשב ביחסי הקרבה המיוחדים בין עורך דין ללקוחו.', true, 'זוהי התשובה הנכונה. הפסיקה מכירה בכך שצידוק מספיק יכול להיות מושתת על אינטרס עצמי או ציבורי, וכי יש להתחשב ביחסי הקרבה המיוחדים, כמו בין עורך דין ללקוחו.', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_2, 'ג', 'כן, אך רק אם החוזה המופר אינו תקף מבחינה משפטית.', false, 'טענה זו אינה נכונה. אם החוזה אינו תקף, ממילא לא מתקיים היסוד הראשון של העוולה, ואין צורך לדון בצידוק.', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_2, 'ד', 'לא, אלא אם כן עורך הדין פעל בתום לב מוחלט.', false, 'טענה זו אינה נכונה. תום לב הוא שיקול, אך הקריטריון המרכזי הוא איזון האינטרסים והאם האינטרס המוגן עדיף או מקביל בחשיבותו.', 4);

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_3, v_sq_id, 'ד', 'ידיעה קונסטרוקטיבית ועצימת עיניים',
    4, 'חברה א'' התקשרה בחוזה עם חברה ב'', ביודעה שחברה ב'' התחייבה בחוזה קודם לחברה ג'' שלא להתקשר בחוזים מתחרים. חברה א'' טוענת שלא ידעה את פרטי החוזה הקודם ולכן לא התקיים יסוד ה''ביודעין''. האם טענתה תתקבל?', 'שאלה זו עוסקת בפרשנות יסוד ה''ביודעין'' בעוולת גרם הפרת חוזה שלא כדין. היא מדגישה את הרחבת היסוד בפסיקה כך שיכלול לא רק ידיעה בפועל על פרטי החוזה, אלא גם ידיעה כללית, ידיעה קונסטרוקטיבית או עצימת עיניים, במיוחד כאשר המתערב מודע לאפשרות קיומו של חוזה קודם.', 'יסוד ה''ביודעין'' בעוולת גרם הפרת חוזה שלא כדין אינו דורש ידיעה מדויקת של כל פרטי החוזה המופר. די בכך שהצד השלישי ידע על עצם קיומו של החוזה ועל כך שהתנהלותו עלולה להוביל להפרתו. ע"א (מחוזי ת"א) 1985-11-11 הרצל לוויאני נ'' פוליבה בע"מ (08.07.2013) הפסיקה הרחיבה את יסוד זה כך שיכלול גם ידיעה קונסטרוקטיבית או ''עצימת עיניים'', כלומר מצב שבו אדם ידע עובדות שאדם סביר היה מסיק מהן דבר קיומו של חוזה, אך העדיף לעצום עיניים ולא לברר. ע"א 1137/23 אליהו דרעי נ'' קרן קיימת לישראל (05.05.2025) ת"א (מחוזי חי'') 928-98 סאפד דיבילופמנטס (ג''רסי) לימיטד נ'' יפתח סוכנויות דלקים בע"מ (13.10.2013) ע"א (מחוזי ת"א) 1985-11-11 הרצל לוויאני נ'' פוליבה בע"מ (08.07.2013)',
    'הנחה שגויה כי נדרשת ידיעה מפורטת ומלאה של כל תנאי החוזה, או אי-הכרת דוקטרינת עצימת העיניים בהקשר זה.', '["גרם הפרת חוזה שלא כדין", "יסוד ביודעין", "ידיעה קונסטרוקטיבית", "עצימת עיניים", "פקודת הנזיקין", "חובת בירור"]'::jsonb, '**וריאציה 1 — היקף הידיעה:** האם נדרשת ידיעה על כל פרטי החוזה? ← לא, די בידיעה כללית על קיומו ועל כך שהמעשה יגרום להפרתו (ע"א 2835566 לוויאני).
**וריאציה 2 — עצימת עיניים:** מהי ''עצימת עיניים''? ← ידיעה על עובדות שאדם סביר היה מסיק מהן קיום חוזה, אך העדפה לא לברר (ע"א 1137/23 דרעי).
**וריאציה 3 — חובת בירור:** מתי קמה חובת בירור? ← כאשר המתערב יודע על קיום חוזה קודם, מוטלת עליו חובה לברר שאין בכריתת ההסכם החדש כדי לגרום להפרת הקודם (ע"א 2835566 לוויאני).', 'יסוד ''ביודעין'' ← כולל ידיעה כללית, קונסטרוקטיבית ועצימת עיניים ← אין צורך בידיעה מפורטת.',
    '["פקודת הנזיקין [נוסח חדש], סעיף 62", "ע\"א 1137/23 אליהו דרעי נ'' קרן קיימת לישראל (05.05.2025)", "ע\"א (מחוזי ת\"א) 1985-11-11 הרצל לוויאני נ'' פוליבה בע\"מ (08.07.2013)", "ת\"א (מחוזי חי'') 928-98 סאפד דיבילופמנטס (ג''רסי) לימיטד נ'' יפתח סוכנויות דלקים בע\"מ (13.10.2013)"]'::jsonb
  );
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_3, 'א', 'כן, מכיוון שידיעה על פרטי החוזה היא תנאי הכרחי לקיום יסוד ה''ביודעין''.', false, 'טענה זו אינה נכונה. הפסיקה הכירה בכך שדי בידיעה כללית על קיום החוזה, ואין צורך בידיעה על כל פרטיו.', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_3, 'ב', 'לא, מכיוון שיסוד ה''ביודעין'' כולל גם ידיעה קונסטרוקטיבית או עצימת עיניים, ודי בידיעה כללית על קיום החוזה והפרתו.', true, 'זוהי התשובה הנכונה. הפסיקה הרחיבה את יסוד ה''ביודעין'' כך שיכלול גם מצבים של עצימת עיניים או ידיעה קונסטרוקטיבית, ואין צורך בידיעה מדויקת של כל פרטי החוזה.', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_3, 'ג', 'כן, אלא אם כן חברה ג'' הוכיחה שחברה א'' פעלה בזדון מוחלט.', false, 'טענה זו אינה נכונה. יסוד ה''ביודעין'' אינו דורש הוכחת זדון מוחלט, אלא ידיעה או עצימת עיניים.', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_3, 'ד', 'לא, מכיוון שחברה א'' הייתה צריכה לברר את פרטי החוזה הקודם.', false, 'טענה זו אינה נכונה. אף שקיימת חובה לברר במקרים מסוימים, הטענה המדויקת יותר היא שהידיעה אינה חייבת להיות על כל הפרטים, ודי בעצימת עיניים.', 4);

  RAISE NOTICE 'Q% inserted: external_id %', 20, '2022-S-S-Q20';
END
$$;

