  v_ang_1 uuid := '09ad5c19-3428-4cc8-816b-1b3b06bd3512'::uuid;
  v_ang_2 uuid := 'bbb98d13-f5b6-45e3-9b98-6ef55bbb19de'::uuid;
  v_ang_3 uuid := 'cc00f7b2-e1c0-44c4-b335-562d8028822c'::uuid;
