  INSERT INTO public.source_questions (
    id, question_group_id, version, is_current, external_id, chapter_id, subtopic_id, question_text, source_metadata, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list, notes_for_admin, status, created_by
  ) VALUES (
    v_sq_id, v_group_id, 1, true,
    '2022-S-S-Q21', v_chapter_id, v_subtopic_id, 'משה סיים את התמחותו במקצוע עריכת הדין, עמד בהצלחה במבחני ההסמכה ופתח משרד עצמאי בתל אביב. כדי לשווק את עצמו החל משה להתקשר לחברות שונות שמצא באינטרנט והציע להן את שירותיו במבצע חד-פעמי וחסר תקדים שבו יהיו זכאים לתיק ראשון בחינם. בשלב מסוים שמע משה מחבר אחר שהיה איתו בהתמחות שאסור לו לעשות את זה, ולכן החליט להעסיק מזכירה במשרדו שתעשה זאת במקומו. האם משה היה רשאי לפעול כפי שפעל?',
    '{"exam_year": 2022, "exam_season": "summer", "exam_part": 2, "exam_question_number": 21}'::jsonb, 'שאלה זו עוסקת באיסור השידול על עורכי דין, כפי שנקבע בסעיף 56 לחוק לשכת עורכי הדין, התשכ"א-1961, ובכללי האתיקה המקצועית. היא בוחנת את ההגדרה הרחבה של ''שידול'', הכוללת פנייה יזומה במישרין או בעקיפין, ואת העובדה שהאיסור חל גם כאשר הפעולה נעשית ''על ידי אחר''. בנוסף, היא נוגעת לאיסור מתן טובת הנאה כדי לקבל עבודה.', 'סעיף 56 לחוק לשכת עורכי הדין, התשכ"א-1961, קובע במפורש כי "לא ישדל עורך דין, בעצמו או על ידי אחר, כל אדם למסור לידיו עבודה מקצועית". סעיף 56 לחוק לשכת עורכי הדין, תשכ"א-1961 | איסור שידול לשם השגת עבודה הגדרת ה''שידול'' היא רחבה ביותר וכוללת כל פנייה יזומה של עורך הדין ללקוח פוטנציאלי, במישרין או בעקיפין, מתוך כוונה שזה ימסור לידיו עבודה. נבו - המתמחה אתיקה מקצועית - כללי האתיקה (2026) | סיום חברות והגבלתה במקרה של משה, התקשרות יזומה לחברות והצעת ''תיק ראשון בחינם'' מהווה שידול אסור. בנוסף, הצעת ''תיק ראשון בחינם'' נחשבת למתן טובת הנאה כדי לקבל עבודה, האסורה גם היא לפי כללי האתיקה (סעיף 43 לכללי האתיקה, המוזכר בתוכן). נבו - המתמחה אתיקה מקצועית - כללי האתיקה (2026) | סיום חברות והגבלתה העסקת מזכירה שתבצע את אותן פעולות אינה פוטרת את משה מאחריות, שכן האיסור חל גם על שידול שנעשה ''על ידי אחר''. נבו - המתמחה אתיקה מקצועית - כללי האתיקה (2026) | סיום חברות והגבלתה לכן, אסור היה למשה לפעול כפי שפעל, לא בעצמו ולא באמצעות מזכירתו.', 'הנחה שגויה כי ניתן לעקוף את איסור השידול באמצעות צד שלישי (כמו מזכירה), או אי-הבחנה בין שידול לבין פרסומת מותרת, וכן אי-הכרת האיסור על מתן טובות הנאה לשם השגת עבודה.',
    '["איסור שידול", "אתיקה מקצועית", "חוק לשכת עורכי הדין", "פנייה יזומה", "שידול על ידי אחר", "טובת הנאה"]'::jsonb, '**וריאציה 1 — שידול עצמי:** האם משה רשאי להתקשר לחברות ולהציע מבצעים? ← לא, זו פנייה יזומה הנחשבת לשידול אסור (סעיף 56 לחוק לשכת עורכי הדין; אתיקה מקצועית: 30).
**וריאציה 2 — שידול על ידי אחר:** האם משה רשאי להעסיק מזכירה שתעשה זאת במקומו? ← לא, האיסור חל גם על שידול ''על ידי אחר'' (סעיף 56 לחוק לשכת עורכי הדין; אתיקה מקצועית: 30).
**וריאציה 3 — מבצע ''תיק בחינם'':** האם הצעת ''תיק ראשון בחינם'' מותרת? ← לא, זו נחשבת למתן טובת הנאה כדי לקבל עבודה, האסורה לפי כללי האתיקה (אתיקה מקצועית: 30, סעיף 43 לכללי האתיקה).', 'משה לא היה רשאי לשדל לקוחות, לא בעצמו ולא באמצעות מזכירתו, והצעת ''תיק בחינם'' אסורה כטובת הנאה לשם השגת עבודה.', '["חוק לשכת עורכי הדין, תשכ\"א-1961, סעיף 56", "נבו - המתמחה אתיקה מקצועית - כללי האתיקה (2026) | סיום חברות והגבלתה"]'::jsonb,
    'classification_review: original chapter=''סדר דין פלילי'' subtopic=''משמעת עורכי דין'' → mapped chapter=''ethics'' subtopic=''fees_client_funds_advertising'' | classifier_note: Lawyer cold-calling companies + special-offer pricing — advertising and soliciting rules | source_review_note: השאלה עוסקת באתיקה מקצועית של עורכי דין, שהיא נושא מהותי בדיני לשכת עורכי הדין. בחרתי ב''משמעת עורכי דין'' תחת ''סדר דין פלילי'' כהצבת מקום, מכיוון שזו הקטגוריה הקרובה ביותר ברשימה הסגורה העוסקת בהתנהגות עורכי דין. עם זאת, אתיקה מקצועית היא תחום רחב יותר שאינו מוגבל רק להיבטים פליליים או משמעתיים, וייתכן שיהיה צורך להוסיף קטגוריה ייעודית לאתיקה מקצועית תחת פרק ''סדר דין אזרחי'' או פרק נפרד.', 'active', 'b9ecdde2-d07e-4761-96ab-05f0ad32d4e3'
  );

  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'א', 'כן. אין מניעה חוקית לבצע את הפעולות שמשה ביצע, בין בעצמו ובין באמצעות מזכירתו.', false, 'טענה זו אינה נכונה. פעולותיו של משה, הן בעצמו והן באמצעות מזכירתו, מהוות שידול אסור לפי כללי האתיקה המקצועית.', 1);
  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'ב', 'למשה אסור היה לשווק את עצמו כפי שעשה, אך מותר היה לו לעשות כן באמצעות מזכירתו.', false, 'טענה זו אינה נכונה. איסור השידול חל גם כאשר עורך הדין פועל ''על ידי אחר'', ולכן גם פעולת המזכירה אסורה.', 2);
  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'ג', 'מאחר שמשה מצא את החברות באינטרנט מותר היה לו להתקשר אליהן ולהציע את שירותיו, וגם למזכירה שלו מותר היה לעשות כן.', false, 'טענה זו אינה נכונה. מקור המידע על הלקוחות הפוטנציאליים אינו משנה את מהות הפעולה כשידול אסור, בין אם נעשה על ידי עורך הדין עצמו ובין אם על ידי אחר מטעמו.', 3);
  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'ד', 'אסור היה למשה להתקשר ללקוחות ולהציע להם מבצעים, לא בעצמו ולא באמצעות מזכירתו.', true, 'זוהי התשובה הנכונה. סעיף 56 לחוק לשכת עורכי הדין אוסר על עורך דין לשדל, בעצמו או על ידי אחר, כל אדם למסור לידיו עבודה מקצועית. הצעת ''תיק ראשון בחינם'' נחשבת גם למתן טובת הנאה כדי לקבל עבודה, האסורה לפי כללי האתיקה.', 4);

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_0, v_sq_id, 'א', 'שידול באמצעות חלוקת כרטיסי ביקור',
    1, 'עורך דין מסיים הרצאה בפני קהל רב בנושא זכויות עובדים. בסיום ההרצאה הוא מחלק לכל המשתתפים כרטיסי ביקור שלו. האם פעולה זו מותרת על פי כללי האתיקה המקצועית?', 'שאלה זו בוחנת את היקף איסור השידול על עורכי דין, ובפרט את הפרשנות הרחבה של המונח ''שידול'' בכללי האתיקה המקצועית. היא מדגישה כי גם פעולות הנראות תמימות, כמו חלוקת כרטיסי ביקור יזומה, יכולות להיחשב כשידול אסור.', 'סעיף 56 לחוק לשכת עורכי הדין, התשכ"א-1961, קובע כי "לא ישדל עורך דין, בעצמו או על ידי אחר, כל אדם למסור לידיו עבודה מקצועית". סעיף 56 לחוק לשכת עורכי הדין, תשכ"א-1961 | איסור שידול לשם השגת עבודה הגדרת ה''שידול'' היא רחבה ביותר וכוללת כל פנייה יזומה של עורך הדין ללקוח פוטנציאלי, במישרין או בעקיפין, מתוך כוונה שזה ימסור לידיו עבודה. נבו - המתמחה אתיקה מקצועית - כללי האתיקה (2026) | סיום חברות והגבלתה חלוקת כרטיסי ביקור יזומה בסיום הרצאה נחשבת לדוגמה מובהקת לשידול אסור, שכן היא מהווה ניסיון של עורך הדין לשכנע אדם אחר למסור לו עבודה. נבו - המתמחה אתיקה מקצועית - כללי האתיקה (2026) | סיום חברות והגבלתה',
    'הנחה שגויה כי חלוקת כרטיסי ביקור היא פעולה שיווקית לגיטימית בכל מצב, מבלי להבחין בין חלוקה יזומה לבין מתן כרטיס ביקור לבקשת לקוח פוטנציאלי.', '["איסור שידול", "אתיקה מקצועית", "חוק לשכת עורכי הדין", "פנייה יזומה", "כרטיס ביקור"]'::jsonb, '**וריאציה 1 — הגדרת שידול:** מהו שידול אסור? ← כל פנייה יזומה של עו"ד ללקוח פוטנציאלי, במישרין או בעקיפין, מתוך כוונה לקבל עבודה (אתיקה מקצועית: 30).
**וריאציה 2 — חלוקת כרטיסים:** האם חלוקת כרטיסי ביקור בסיום הרצאה היא שידול? ← כן, זו דוגמה מובהקת לשידול אסור (אתיקה מקצועית: 30).
**וריאציה 3 — בסיס חוקי:** איזה סעיף אוסר על שידול? ← סעיף 56 לחוק לשכת עורכי הדין, התשכ"א-1961.', 'חלוקת כרטיסי ביקור יזומה בסיום הרצאה ← שידול אסור ← לפי סעיף 56 לחוק לשכת עורכי הדין וכללי האתיקה.',
    '["חוק לשכת עורכי הדין, תשכ\"א-1961, סעיף 56", "נבו - המתמחה אתיקה מקצועית - כללי האתיקה (2026) | סיום חברות והגבלתה"]'::jsonb
  );
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_0, 'א', 'כן, מכיוון שחלוקת כרטיסי ביקור היא דרך לגיטימית לפרסום.', false, 'טענה זו אינה נכונה. אף שפרסום מותר בדרכים מסוימות, חלוקת כרטיסי ביקור יזומה בסיום הרצאה נחשבת לשידול אסור.', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_0, 'ב', 'לא, מכיוון שזוהי פנייה יזומה הנחשבת לשידול אסור.', true, 'זוהי התשובה הנכונה. הגדרת השידול רחבה וכוללת כל פנייה יזומה של עורך הדין ללקוח פוטנציאלי, במישרין או בעקיפין, מתוך כוונה לקבל עבודה, וחלוקת כרטיסי ביקור יזומה נכללת בכך.', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_0, 'ג', 'כן, כל עוד כרטיס הביקור אינו מכיל דברי שבח או הבטחות.', false, 'טענה זו אינה נכונה. תוכן כרטיס הביקור אינו משנה את מהות הפעולה כשידול אסור, אם היא פנייה יזומה.', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_0, 'ד', 'לא, אלא אם כן המשתתפים ביקשו במפורש לקבל את כרטיס הביקור.', false, 'טענה זו אינה נכונה. גם אם המשתתפים ביקשו, חלוקה יזומה לכלל הקהל עדיין יכולה להיחשב לשידול. הפנייה צריכה להיות לא יזומה מצד עורך הדין.', 4);

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_1, v_sq_id, 'ב', 'הגדרת שידול ופנייה יזומה',
    2, 'מהם המאפיינים העיקריים של ''שידול'' אסור על פי כללי האתיקה המקצועית של עורכי הדין?', 'שאלה זו מתמקדת בהגדרת המונח ''שידול'' בהקשר של אתיקה מקצועית של עורכי דין. היא דורשת הבנה של היסודות המרכיבים את האיסור על שידול, כפי שפורשו בספרות המשפטית ובכללי האתיקה.', 'הגדרת ה''שידול'' בכללי האתיקה המקצועית היא רחבה ביותר וכוללת כל פנייה יזומה של עורך הדין ללקוח פוטנציאלי, במישרין או בעקיפין, מתוך כוונה שזה ימסור לידיו עבודה. נבו - המתמחה אתיקה מקצועית - כללי האתיקה (2026) | סיום חברות והגבלתה איסור זה מעוגן בסעיף 56 לחוק לשכת עורכי הדין, התשכ"א-1961. סעיף 56 לחוק לשכת עורכי הדין, תשכ"א-1961 | איסור שידול לשם השגת עבודה המטרה היא למנוע מעורכי דין לנצל מצוקה או חוסר ידע של הציבור כדי להשיג עבודה, ולשמור על כבוד המקצוע. נבו - המתמחה אתיקה מקצועית - כללי האתיקה (2026) | סיום חברות והגבלתה',
    'בלבול בין שידול לבין פרסומת מותרת, או אי-הבנה של היקף הפעולות הנכללות בהגדרת ''פנייה יזומה''.', '["שידול אסור", "אתיקה מקצועית", "פנייה יזומה", "חוק לשכת עורכי הדין", "לקוח פוטנציאלי"]'::jsonb, '**וריאציה 1 — הגדרת שידול:** מהי ההגדרה הרחבה של שידול? ← כל פנייה יזומה של עו"ד ללקוח פוטנציאלי, במישרין או בעקיפין, מתוך כוונה לקבל עבודה (אתיקה מקצועית: 30).
**וריאציה 2 — יסודות:** מהם היסודות העיקריים של שידול? ← פנייה יזומה, כוונה לקבל עבודה, במישרין או בעקיפין.
**וריאציה 3 — מטרה:** מהי מטרת איסור השידול? ← למנוע ניצול מצוקה ולשמור על כבוד המקצוע.', 'שידול אסור ← פנייה יזומה (במישרין/עקיפין) ← מתוך כוונה לקבל עבודה.',
    '["חוק לשכת עורכי הדין, תשכ\"א-1961, סעיף 56", "נבו - המתמחה אתיקה מקצועית - כללי האתיקה (2026) | סיום חברות והגבלתה"]'::jsonb
  );
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_1, 'א', 'פנייה יזומה של עורך הדין ללקוח פוטנציאלי, במישרין או בעקיפין, מתוך כוונה שזה ימסור לידיו עבודה.', true, 'זוהי התשובה הנכונה. הגדרה זו משקפת במדויק את המאפיינים העיקריים של שידול אסור כפי שנקבעו בכללי האתיקה המקצועית.', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_1, 'ב', 'כל פרסומת שאינה עומדת בכללים שנקבעו על ידי המועצה הארצית.', false, 'טענה זו אינה נכונה. פרסומת אסורה היא עבירה אתית נפרדת משידול, אף שיש חפיפה מסוימת. שידול מתמקד בפנייה יזומה לקבלת עבודה.', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_1, 'ג', 'הצעת שירותים משפטיים במחיר נמוך מהמקובל בשוק.', false, 'טענה זו אינה נכונה. תמחור שירותים אינו מהווה שידול כשלעצמו, אלא אם הוא חלק מפנייה יזומה שמטרתה לקבל עבודה.', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_1, 'ד', 'מתן ייעוץ משפטי ראשוני ללא תשלום.', false, 'טענה זו אינה נכונה. מתן ייעוץ ראשוני ללא תשלום אינו בהכרח שידול, אלא אם הוא חלק מפנייה יזומה שמטרתה לקבל עבודה.', 4);

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_2, v_sq_id, 'ג', 'שידול על ידי צד שלישי',
    3, 'עורך דין מקבל לטיפולו לקוח שהגיע אליו באמצעות עלון שפורסם על ידי ''הקליניקה לזכויות החולה'' (גוף שאינו למטרת רווח). האם עורך הדין עבר עבירת שידול?', 'שאלה זו בוחנת את היקף איסור השידול כאשר הפעולה נעשית ''על ידי אחר''. היא מדגישה כי עורך דין אינו יכול להתחמק מאחריות לשידול באמצעות שימוש בצד שלישי, גם אם אותו צד שלישי אינו פועל למטרת רווח, אם הוא פועל מטעמו של עורך הדין.', 'סעיף 56 לחוק לשכת עורכי הדין קובע כי "לא ישדל עורך דין, בעצמו או על ידי אחר, כל אדם למסור לידיו עבודה מקצועית". סעיף 56 לחוק לשכת עורכי הדין, תשכ"א-1961 | איסור שידול לשם השגת עבודה הגדרת השידול כוללת כל פנייה יזומה, במישרין או בעקיפין, מתוך כוונה לקבל עבודה. נבו - המתמחה אתיקה מקצועית - כללי האתיקה (2026) | סיום חברות והגבלתה דוגמה ו'' בכללי האתיקה מציינת כי עורך דין המקבל לטיפולו לקוח שהגיע אליו באמצעות עלון שפורסם על ידי צד שלישי (כמו קליניקה לזכויות החולה) עשוי להיחשב למי שביצע שידול. נבו - המתמחה אתיקה מקצועית - כללי האתיקה (2026) | סיום חברות והגבלתה זאת, אם הצד השלישי פעל מטעמו של עורך הדין או בתיאום עמו, מתוך כוונה להפנות אליו לקוחות. יש להבחין בין שידול על ידי אחר לבין איסור מתן שירותים משפטיים ללקוח שהופנה על ידי גוף למטרת רווח (סעיף 11ב לכללי האתיקה), שכן אלו עבירות נפרדות. נבו - המתמחה אתיקה מקצועית - כללי האתיקה (2026) | פרק ה'' - עורך הדין והלקוח',
    'הנחה שגויה כי שידול על ידי אחר מותר אם הצד השלישי אינו למטרת רווח, או בלבול בין איסור שידול לבין איסור מתן שירותים משפטיים ללקוח שהופנה על ידי גוף למטרת רווח.', '["שידול על ידי אחר", "אתיקה מקצועית", "חוק לשכת עורכי הדין", "פנייה עקיפה", "גוף שאינו למטרת רווח"]'::jsonb, '**וריאציה 1 — שידול על ידי אחר:** האם שידול על ידי צד שלישי אסור? ← כן, סעיף 56 לחוק לשכת עורכי הדין אוסר שידול ''בעצמו או על ידי אחר''.
**וריאציה 2 — קליניקה לזכויות החולה:** האם קבלת לקוח מקליניקה לזכויות החולה יכולה להיחשב לשידול? ← כן, אם הקליניקה פועלת מטעמו של עו"ד (אתיקה מקצועית: 30, דוגמה ו'').
**וריאציה 3 — גוף למטרת רווח:** האם יש הבדל אם הגוף למטרת רווח או לא? ← לעניין שידול, אם פועל מטעמו של עו"ד, זה אסור. לעניין סעיף 11ב לכללי האתיקה, יש הבדל (אתיקה מקצועית: 59).', 'שידול אסור גם ''על ידי אחר'' ← גם אם הצד השלישי אינו למטרת רווח ← אם פועל מטעמו של עו"ד.',
    '["חוק לשכת עורכי הדין, תשכ\"א-1961, סעיף 56", "נבו - המתמחה אתיקה מקצועית - כללי האתיקה (2026) | סיום חברות והגבלתה", "נבו - המתמחה אתיקה מקצועית - כללי האתיקה (2026) | פרק ה'' - עורך הדין והלקוח"]'::jsonb
  );
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_2, 'א', 'לא, מכיוון שהקליניקה אינה פועלת למטרת רווח.', false, 'טענה זו אינה נכונה. אף שאיסור מתן שירותים משפטיים ללקוח שהופנה על ידי גוף למטרת רווח הוא עבירה נפרדת (סעיף 11ב לכללי האתיקה), שידול על ידי אחר אסור גם אם הצד השלישי אינו למטרת רווח, אם הוא פועל מטעמו של עורך הדין.', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_2, 'ב', 'כן, אם הקליניקה פעלה מטעמו של עורך הדין, זה ייחשב לשידול על ידי אחר.', true, 'זוהי התשובה הנכונה. איסור השידול חל גם כאשר עורך הדין פועל ''על ידי אחר''. אם הקליניקה פעלה כזרוע שיווקית של עורך הדין, זה ייחשב לשידול אסור.', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_2, 'ג', 'לא, מכיוון שעורך הדין לא פנה ישירות ללקוח.', false, 'טענה זו אינה נכונה. איסור השידול חל גם על פנייה עקיפה ועל פעולה ''על ידי אחר''.', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_2, 'ד', 'כן, מכיוון שקבלת לקוחות באמצעות הפניה מגוף חיצוני אסורה תמיד.', false, 'טענה זו אינה נכונה. קבלת לקוחות באמצעות הפניה מגוף חיצוני מותרת, כל עוד אין בכך שידול אסור או הפרה של כללים אחרים (כמו סעיף 11ב לכללי האתיקה).', 4);

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_3, v_sq_id, 'ד', 'שימוש בתארים מקצועיים',
    4, 'עורכת דין בעלת תואר דוקטור בחינוך, מעוניינת לציין זאת בכרטיס הביקור שלה. האם היא רשאית לעשות כן, וכיצד?', 'שאלה זו עוסקת בכללים האתיים הנוגעים לשימוש בתארים מקצועיים על ידי עורכי דין, כחלק מהסדרת הפרסומת והצגת עורך הדין לציבור. היא מדגישה את החשיבות במניעת הטעיית הציבור באמצעות ציון ברור של תחום התואר.', 'עורך דין ישתמש לציון מקצועו בתואר "עורך דין" או בתואר לועזי מקביל שנקבע בכללים, ובתואר זה בלבד. נבו - המתמחה אתיקה מקצועית - כללי האתיקה (2026) | סיום חברות והגבלתה עם זאת, קיים חריג המאפשר לעורך דין לעשות שימוש בתואר אקדמי או בתואר שדין אחר מסדיר את השימוש בו (כגון: דיין, שמאי, רואה חשבון או יועץ מס). נבו - המתמחה אתיקה מקצועית - כללי האתיקה (2026) | סיום חברות והגבלתה אולם, אם עורך הדין מחזיק בתואר שאינו במשפטים (למשל, דוקטור לחינוך), עליו לציין באיזה תחום ניתן התואר, וזאת מחשש להטעיית הציבור. נבו - המתמחה אתיקה מקצועית - כללי האתיקה (2026) | סיום חברות והגבלתה',
    'הנחה שגויה כי כל שימוש בתואר שאינו ''עורך דין'' אסור, או לחלופין, שאין צורך לציין את תחום התואר שאינו משפטי.', '["שימוש בתארים", "אתיקה מקצועית", "הטעיית הציבור", "תואר אקדמי", "כללי לשכת עורכי הדין"]'::jsonb, '**וריאציה 1 — תואר ''עורך דין'':** מהו התואר היחיד שעו"ד רשאי להשתמש בו לציון מקצועו? ← ''עורך דין'' או לועזי מקביל (אתיקה מקצועית: 31).
**וריאציה 2 — תואר אקדמי אחר:** האם עו"ד רשאי לציין תואר דוקטור בחינוך? ← כן, אך עליו לציין את תחום התואר (אתיקה מקצועית: 31).
**וריאציה 3 — מניעת הטעיה:** מדוע יש לציין את תחום התואר שאינו משפטי? ← מחשש להטעיית הציבור (אתיקה מקצועית: 31).', 'שימוש בתואר אקדמי שאינו משפטי ← מותר ← בתנאי שמצוין תחום התואר ← למניעת הטעיה.',
    '["נבו - המתמחה אתיקה מקצועית - כללי האתיקה (2026) | סיום חברות והגבלתה"]'::jsonb
  );
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_3, 'א', 'לא, עורך דין רשאי להשתמש רק בתואר ''עורך דין'' או בתואר לועזי מקביל.', false, 'טענה זו אינה נכונה. קיימים חריגים המאפשרים שימוש בתארים אקדמיים או אחרים, בכפוף לתנאים מסוימים.', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_3, 'ב', 'כן, אך עליה לציין במפורש באיזה תחום ניתן התואר, מחשש להטעיית הציבור.', true, 'זוהי התשובה הנכונה. עורך דין רשאי להשתמש בתואר אקדמי שאינו במשפטים, אך עליו לציין את תחום התואר כדי למנוע הטעיה.', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_3, 'ג', 'כן, כל עוד התואר אינו פוגע בכבוד המקצוע.', false, 'טענה זו אינה נכונה. אף שאי-פגיעה בכבוד המקצוע היא עקרון כללי, יש כללים ספציפיים לגבי שימוש בתארים שאינם משפטיים.', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_3, 'ד', 'לא, אלא אם כן התואר קשור באופן ישיר לעיסוקה המשפטי.', false, 'טענה זו אינה נכונה. אין דרישה לקשר ישיר לעיסוק המשפטי, אלא לדרישה לציין את תחום התואר כדי למנוע הטעיה.', 4);

  RAISE NOTICE 'Q% inserted: external_id %', 21, '2022-S-S-Q21';
END
$$;

