-- ============================================================
DO $$
DECLARE
  v_sq_id uuid := '06a75103-6ce0-4439-a11e-77394bf9a4db'::uuid;
  v_group_id uuid := '10d7bc18-8274-40cd-8392-f5782312f07b'::uuid;
  v_chapter_id uuid;
  v_subtopic_id uuid;
  v_existing_id uuid;
  v_ang_0 uuid := 'ba4f9153-854e-4ccd-a5eb-7df6cf54168f'::uuid;
  v_ang_1 uuid := 'e4409c2f-b769-4f45-ba36-4412837dbcb3'::uuid;
  v_ang_2 uuid := '1306d539-36f6-4a68-b739-d0aab1e54ef6'::uuid;
  v_ang_3 uuid := '4785b487-3cb5-45a5-9d10-0b73777baa2b'::uuid;
BEGIN
  SELECT id INTO v_existing_id FROM public.source_questions WHERE external_id = '2022-S-S-Q22';
  IF v_existing_id IS NOT NULL THEN
    RAISE NOTICE 'Q% skipped: external_id % already exists', 22, '2022-S-S-Q22';
    RETURN;
  END IF;

  SELECT id INTO v_chapter_id FROM public.chapters WHERE code = 'contracts';
  IF v_chapter_id IS NULL THEN
    RAISE EXCEPTION 'Chapter code % not found', 'contracts';
  END IF;

  SELECT id INTO v_subtopic_id FROM public.subtopics WHERE code = 'general_part' AND chapter_id = v_chapter_id;
  IF v_subtopic_id IS NULL THEN
    RAISE EXCEPTION 'Subtopic code % not found under chapter %', 'general_part', 'contracts';
  END IF;

  INSERT INTO public.source_questions (
    id, question_group_id, version, is_current, external_id, chapter_id, subtopic_id, question_text, source_metadata, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list, notes_for_admin, status, created_by
  ) VALUES (
    v_sq_id, v_group_id, 1, true,
    '2022-S-S-Q22', v_chapter_id, v_subtopic_id, 'עו"ד אברהם ועו"ד תמר, בני זוג, התמודדו שניהם על משרה אחת במשרדה של עו"ד דפנה. ביום 1.4.22 שלחה עו"ד דפנה לעו"ד אברהם דואר אלקטרוני הכולל חוזה העסקה. בהודעה הדגישה את החשיבות לקבלת תשובה בהקדם לנוכח עומס עבודה והקציבה לו 7 ימים להחזיר את החוזה חתום. עו"ד אברהם אישר את קבלת הודעת הדואר האלקטרוני. עו"ד אברהם טרם השיב להודעה. בתאריך 5.4.22 הודיעה עו"ד דפנה לעו"ד תמר כי היא התקבלה לעבודה. באותו היום חתמו השתיים על הסכם העסקה. במקביל שלחה עו"ד דפנה לעו"ד אברהם עדכון על כך והודעת סיום משא ומתן. עו"ד אברהם פונה אליך באותו היום ומבקש את עצתך. מה הדין?',
    '{"exam_year": 2022, "exam_season": "summer", "exam_part": 2, "exam_question_number": 22}'::jsonb, 'שאלה זו עוסקת בעקרונות כריתת חוזה, ובפרט בהבחנה בין הצעה רגילה להצעה בלתי חוזרת, ובדיני חזרה מהצעה, כפי שמעוגנים בסעיפים 3 ו-4 לחוק החוזים (חלק כללי), תשל"ג-1973. היא בוחנת את תוקפה של הודעת חזרה מהצעה בלתי חוזרת לפני תום מועד הקיבול, ואת השלכותיה על יכולת הניצע לקבל את ההצעה.', 'ההצעה ששלחה עו"ד דפנה לעו"ד אברהם ביום 1.4.22, ובה הקציבה לו 7 ימים להחזיר את החוזה חתום, היא ''הצעה בלתי חוזרת'' כמשמעותה בסעיף 3(ב) לחוק החוזים (חלק כללי), תשל"ג-1973. סעיף זה קובע כי "קבע המציע שהצעתו היא ללא חזרה, או שקבע מועד לקיבולה, אין הוא רשאי לחזור בו ממנה לאחר שנמסרה לניצע". סעיף 3(ב) לחוק החוזים (חלק כללי), תשל"ג-1973 | חזרה מן ההצעה במקרה זה, דפנה קבעה מועד לקיבול (7 ימים), ולכן ההצעה הפכה לבלתי חוזרת מרגע שנמסרה לאברהם (ואברהם אף אישר את קבלתה). פר"ק (מחוזי ת"א) 29379-01-12 דוראה השקעות ופיתוח בע"מ נ'' כונס הנכסים הרשמי (22.01.2015) משמעות הדבר היא שדפנה אינה רשאית לחזור בה מהצעתה לפני תום 7 הימים (קרי, עד 8.4.22). הודעת הביטול ששלחה לאברהם ב-5.4.22, לפני תום מועד הקיבול, אינה תקפה ואין לה נפקות משפטית. גבריאלה שלו ואפי צמח דיני חוזים (2019) | כללי לפיכך, עו"ד אברהם עדיין יכול לקבל את ההצעה בהשבת החוזה חתום עד ליום 8.4.22. ע"א 379/82 נוה-עם ברמת-גן בע"מ (פירוק מרצון) נ'' ד"ר יוסף יעקובסון (28.03.1984) הסכם ההעסקה שנחתם עם עו"ד תמר תקף, שכן הוא נכרת כדין בין דפנה לתמר. העובדה שאברהם עדיין יכול לקבל את הצעתו אינה מבטלת את החוזה עם תמר, אלא עלולה ליצור מצב שבו דפנה תהיה מחויבת לשני חוזים (אם המשרה אינה בלעדית, או אם תפר את אחד מהם).', 'הנחה שגויה כי הודעת ביטול של הצעה בלתי חוזרת תקפה, או בלבול בין הצעה רגילה לבלתי חוזרת, וכן אי-הבנה של השלכות כריתת חוזה עם צד שלישי על הצעה בלתי חוזרת קיימת.',
    '["הצעה בלתי חוזרת", "חזרה מהצעה", "מועד קיבול", "סעיף 3(ב) לחוק החוזים", "תוקף חוזה", "פקיעת הצעה"]'::jsonb, '**וריאציה 1 — הצעה בלתי חוזרת:** האם הצעה עם מועד קיבול היא בלתי חוזרת? ← כן, לפי סעיף 3(ב) לחוק החוזים.
**וריאציה 2 — תוקף הודעת ביטול:** האם דפנה רשאית לחזור בה מההצעה הבלתי חוזרת לפני תום המועד? ← לא, הודעת החזרה אינה תקפה (סעיף 3(ב) לחוק החוזים).
**וריאציה 3 — חוזה עם צד שלישי:** האם החוזה עם תמר תקף? ← כן, הוא נכרת כדין. האם הוא מונע מאברהם לקבל את הצעתו? ← לא, אברהם עדיין יכול לקבל את ההצעה הבלתי חוזרת.', 'הצעה עם מועד קיבול היא בלתי חוזרת ← המציע אינו רשאי לחזור בו לפני תום המועד ← הודעת ביטול אינה תקפה ← הניצע עדיין יכול לקבל ← חוזה עם צד שלישי תקף אך אינו מבטל את זכות הקיבול של הניצע המקורי.', '["חוק החוזים (חלק כללי), תשל\"ג-1973, סעיף 3", "פר\"ק (מחוזי ת\"א) 29379-01-12 דוראה השקעות ופיתוח בע\"מ נ'' כונס הנכסים הרשמי (22.01.2015)", "ע\"א 379/82 נוה-עם ברמת-גן בע\"מ (פירוק מרצון) נ'' ד\"ר יוסף יעקובסון (28.03.1984)", "גבריאלה שלו ואפי צמח דיני חוזים (2019) | כללי"]'::jsonb,
    'classification_review: original chapter=''סדר דין אזרחי'' subtopic=''הליכים'' → mapped chapter=''contracts'' subtopic=''general_part'' | classifier_note: Email employment contract, response deadline — offer-acceptance via electronic means | source_review_note: השאלה עוסקת בדיני חוזים, שהם תחום מהותי במשפט האזרחי. דיני חוזים אינם מופיעים כפרק או תת-נושא מפורש ברשימה הסגורה. בחרתי ב''הליכים'' תחת ''סדר דין אזרחי'' כהצבת מקום, מכיוון שהשאלה עוסקת בשלבי כריתת חוזה ובאפשרות לתבוע (הליך) בגין הפרה, אך יש לשקול הוספת פרק ''דיני חוזים'' או תת-נושא רחב יותר תחת ''סדר דין אזרחי'' שיכלול נושאים מהותיים בעלי השלכות דיוניות.', 'active', 'b9ecdde2-d07e-4761-96ab-05f0ad32d4e3'
  );

  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'א', 'הסכם ההעסקה של עו"ד תמר תקף, ועו"ד אברהם כבר לא יכול לקבל את ההצעה בהשבת הסכם ההעסקה חתום עוד באותו היום.', false, 'טענה זו אינה נכונה. אף שהסכם ההעסקה של תמר תקף, ההצעה לאברהם היא בלתי חוזרת, ולכן הודעת הביטול אינה תקפה ואברהם עדיין יכול לקבל אותה.', 1);
  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'ב', 'הסכם ההעסקה של עו"ד תמר לא תקף, ועו"ד אברהם עדיין יכול לקבל את ההצעה בהשבת הסכם ההעסקה חתום עוד באותו היום למרות הודעת הביטול שקיבל.', false, 'טענה זו אינה נכונה. הסכם ההעסקה של תמר תקף, שכן הוא נכרת כדין. העובדה שאברהם יכול לקבל את הצעתו אינה מבטלת את החוזה עם תמר.', 2);
  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'ג', 'הסכם ההעסקה של עו"ד תמר לא תקף, ועו"ד אברהם כבר לא יכול לקבל את ההצעה בהשבת הסכם ההעסקה חתום עוד באותו היום.', false, 'טענה זו אינה נכונה. הסכם ההעסקה של תמר תקף, והודעת הביטול לאברהם אינה תקפה, ולכן אברהם עדיין יכול לקבל את ההצעה.', 3);
  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'ד', 'הסכם ההעסקה של עו"ד תמר תקף, ועו"ד אברהם עדיין יכול לקבל את ההצעה בהשבת הסכם ההעסקה חתום עוד באותו היום למרות הודעת הביטול שקיבל.', true, 'זוהי התשובה הנכונה. ההצעה לאברהם היא הצעה בלתי חוזרת מכיוון שנקבע לה מועד קיבול. המציע אינו רשאי לחזור בו מהצעה בלתי חוזרת לאחר שנמסרה לניצע ולפני תום מועד הקיבול. לכן, הודעת הביטול ששלחה עו"ד דפנה לאברהם אינה תקפה, ואברהם עדיין יכול לקבל את ההצעה עד תום המועד (8.4.22). הסכם ההעסקה עם תמר תקף, אך אין מניעה עקרונית לכריתת חוזה נוסף עם אברהם, אלא אם כן מדובר במשרה יחידה ובלעדית.', 4);

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_0, v_sq_id, 'א', 'חזרה מהצעה רגילה',
    1, 'עו"ד דפנה שלחה לעו"ד אברהם דואר אלקטרוני הכולל חוזה העסקה, ללא הגבלת זמן לקיבול. עו"ד אברהם אישר את קבלת ההודעה. למחרת, לפני שאברהם השיב, התקשרה דפנה לאברהם והודיעה לו שהיא חוזרת בה מהצעתה. האם דפנה רשאית לחזור בה מההצעה?', 'שאלה זו בוחנת את הכלל הבסיסי בדבר חזרה מהצעה רגילה, כפי שמעוגן בסעיף 3(א) לחוק החוזים (חלק כללי). היא מדגישה את עקרון ''אדנות המציע'' על הצעתו ואת המועד הקריטי שעד אליו רשאי המציע לחזור בו מהצעה שאינה בלתי חוזרת.', 'סעיף 3(א) לחוק החוזים (חלק כללי), תשל"ג-1973, קובע כי "המציע רשאי לחזור בו מן ההצעה בהודעה לניצע, ובלבד שהודעת החזרה נמסרה לניצע לפני שנתן הודעת קיבול". סעיף 3(א) לחוק החוזים (חלק כללי), תשל"ג-1973 | חזרה מן ההצעה במקרה זה, ההצעה ששלחה עו"ד דפנה לאברהם היא הצעה רגילה, שכן לא נקבע בה שהיא ללא חזרה ולא הוגבל מועד לקיבולה. ע"א (מחוזי תל אביב-יפו) 258/93 סופר פארם (ישראל) בע"מ נ'' ברוך חבס (10.04.1994) מאחר שדפנה חזרה בה מהצעתה לפני שאברהם נתן הודעת קיבול, חזרתה תקפה וההצעה פקעה. דניאל פרידמן ונילי כהן חוזים כרך א (2018) | חזרה מהצעה',
    'הנחה שגויה כי אישור קבלת ההודעה מהווה קיבול, או בלבול בין הצעה רגילה להצעה בלתי חוזרת.', '["הצעה רגילה", "חזרה מהצעה", "מועד קיבול", "סעיף 3(א) לחוק החוזים", "אדנות המציע"]'::jsonb, '**וריאציה 1 — הצעה רגילה:** האם הצעה ללא הגבלת זמן היא הצעה רגילה? ← כן.
**וריאציה 2 — מועד חזרה:** עד מתי מציע יכול לחזור בו מהצעה רגילה? ← עד שהניצע נתן הודעת קיבול (סעיף 3(א) לחוק החוזים).
**וריאציה 3 — אישור קבלה:** האם אישור קבלת ההודעה הוא קיבול? ← לא, זה רק אישור שההצעה הגיעה לידי הניצע.', 'הצעה רגילה ← מציע רשאי לחזור בו ← עד מתן הודעת קיבול ← אישור קבלה אינו קיבול.',
    '["חוק החוזים (חלק כללי), תשל\"ג-1973, סעיף 3", "ע\"א (מחוזי תל אביב-יפו) 258/93 סופר פארם (ישראל) בע\"מ נ'' ברוך חבס (10.04.1994)", "דניאל פרידמן ונילי כהן חוזים כרך א (2018) | חזרה מהצעה"]'::jsonb
  );
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_0, 'א', 'לא, מכיוון שאברהם כבר אישר את קבלת ההודעה.', false, 'טענה זו אינה נכונה. אישור קבלת ההודעה אינו מהווה קיבול של ההצעה, אלא רק אישור שההצעה הגיעה לידי הניצע.', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_0, 'ב', 'כן, מכיוון שההצעה לא הוגבלה בזמן, ודפנה חזרה בה לפני שאברהם נתן הודעת קיבול.', true, 'זוהי התשובה הנכונה. לפי סעיף 3(א) לחוק החוזים, מציע רשאי לחזור בו מהצעה רגילה כל עוד הודעת החזרה נמסרה לניצע לפני שזה נתן הודעת קיבול.', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_0, 'ג', 'לא, מכיוון שדפנה פעלה בחוסר תום לב.', false, 'טענה זו אינה נכונה. חזרה מהצעה רגילה לפני קיבול היא זכות המוקנית למציע, ואינה נחשבת כשלעצמה לחוסר תום לב, אלא אם כן נסיבות החזרה חורגות מדרך מקובלת ובתום לב.', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_0, 'ד', 'כן, אך רק אם אברהם לא הסתמך על ההצעה ושינה את מצבו לרעה.', false, 'טענה זו אינה נכונה. הסתמכות ושינוי מצב לרעה רלוונטיים בעיקר לשאלת פיצויים בגין חוסר תום לב במשא ומתן, ולא לעצם הזכות לחזור מהצעה רגילה לפני קיבול.', 4);

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_1, v_sq_id, 'ב', 'תנאים להצעה בלתי חוזרת',
    2, 'מהם התנאים שבהם הצעה נחשבת ל''הצעה בלתי חוזרת'' על פי חוק החוזים (חלק כללי)?', 'שאלה זו מתמקדת בהגדרת ''הצעה בלתי חוזרת'' על פי סעיף 3(ב) לחוק החוזים (חלק כללי). היא בוחנת את שני המקרים המפורשים בחוק, שבהם המציע כובל את עצמו ואינו רשאי לחזור בו מהצעתו לאחר שנמסרה לניצע.', 'סעיף 3(ב) לחוק החוזים (חלק כללי), תשל"ג-1973, קובע כי הצעה נחשבת לבלתי חוזרת בשני מקרים חלופיים: "קבע המציע שהצעתו היא ללא חזרה, או שקבע מועד לקיבולה". סעיף 3(ב) לחוק החוזים (חלק כללי), תשל"ג-1973 | חזרה מן ההצעה במקרים אלו, המציע אינו רשאי לחזור בו מהצעתו לאחר שנמסרה לניצע. גבריאלה שלו ואפי צמח דיני חוזים (2019) | הכרת החוק בהצעה בלתי חוזרת פר"ק (מחוזי ת"א) 29379-01-12 דוראה השקעות ופיתוח בע"מ נ'' כונס הנכסים הרשמי (22.01.2015) חשוב לציין כי אף על פי לשון החוק, הפסיקה והספרות המשפטית מפרשות כל מקרה בהתאם לנסיבותיו, ואין כל קביעת מועד הופכת הצעה לבלתי חוזרת באופן אוטומטי, אלא יש לבחון את אומד דעת הצדדים. גבריאלה שלו ואפי צמח דיני חוזים (2019) | אימתי הצעה היא בלתי חוזרת',
    'הנחה שגויה כי כל הצעה מסוימת דיה היא בלתי חוזרת, או אי-הבחנה בין תנאי ההצעה לבין תנאי הקיבול.', '["הצעה בלתי חוזרת", "סעיף 3(ב) לחוק החוזים", "מועד קיבול", "ללא חזרה", "אומד דעת הצדדים"]'::jsonb, '**וריאציה 1 — תנאי החוק:** מהם שני התנאים להצעה בלתי חוזרת לפי סעיף 3(ב)? ← קביעה שהיא ללא חזרה, או קביעת מועד לקיבולה.
**וריאציה 2 — פרשנות:** האם כל קביעת מועד הופכת הצעה לבלתי חוזרת? ← לא, יש לפרש כל מקרה לפי נסיבותיו (שלו וצמח, דיני חוזים: 14).
**וריאציה 3 — נפקות:** מהי הנפקות של הצעה בלתי חוזרת? ← המציע אינו רשאי לחזור בו ממנה לאחר שנמסרה לניצע (סעיף 3(ב) לחוק החוזים).', 'הצעה בלתי חוזרת ← מוגדרת בסעיף 3(ב) לחוק החוזים ← קביעה מפורשת או מועד קיבול ← המציע כבול.',
    '["חוק החוזים (חלק כללי), תשל\"ג-1973, סעיף 3", "גבריאלה שלו ואפי צמח דיני חוזים (2019) | אימתי הצעה היא בלתי חוזרת", "פר\"ק (מחוזי ת\"א) 29379-01-12 דוראה השקעות ופיתוח בע\"מ נ'' כונס הנכסים הרשמי (22.01.2015)"]'::jsonb
  );
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_1, 'א', 'כאשר המציע קובע שהצעתו היא ללא חזרה, או כאשר הוא קובע מועד לקיבולה.', true, 'זוהי התשובה הנכונה. אלו הם שני המקרים המפורטים בסעיף 3(ב) לחוק החוזים, שבהם הצעה נחשבת לבלתי חוזרת.', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_1, 'ב', 'כאשר המציע קובע שהצעתו היא ללא חזרה, וגם קובע מועד לקיבולה.', false, 'טענה זו אינה נכונה. התנאים הם חלופיים (''או''), ולא מצטברים (''וגם'').', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_1, 'ג', 'כאשר ההצעה מסוימת דיה ומעידה על גמירת דעת של המציע.', false, 'טענה זו אינה נכונה. אלו הם תנאים לקיומה של ''הצעה'' בכלל (סעיף 2 לחוק החוזים), ולא דווקא להצעה בלתי חוזרת.', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_1, 'ד', 'כאשר הניצע מסתמך על ההצעה ומשנה את מצבו לרעה.', false, 'טענה זו אינה נכונה. הסתמכות הניצע היא שיקול חשוב, אך אינה הופכת הצעה לבלתי חוזרת כשלעצמה, אלא עשויה להקים עילה לפיצויים בגין חוסר תום לב במשא ומתן.', 4);

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_2, v_sq_id, 'ג', 'פקיעת הצעה בלתי חוזרת במוות',
    3, 'עו"ד דפנה שלחה לעו"ד אברהם הצעה בלתי חוזרת לחוזה העסקה, עם מועד קיבול של 7 ימים. עו"ד אברהם נפטר ביום ה-3 למניין הימים, לפני שקיבל את ההצעה. האם ההצעה פוקעת?', 'שאלה זו עוסקת בפקיעת הצעה בלתי חוזרת במקרה של מוות הניצע, בהתאם לסעיף 4(2) לחוק החוזים (חלק כללי). היא מדגישה כי הדין הקיים אינו מבחין לעניין זה בין הצעה רגילה לבלתי חוזרת, וכי מוות הניצע לפני קיבול מפקיע את ההצעה.', 'סעיף 4(2) לחוק החוזים (חלק כללי), תשל"ג-1973, קובע כי הצעה פוקעת "כשמת המציע או הניצע או כשנעשה אחד מהם פסול-דין או ניתן נגדו צו לקבלת נכסים או צו פירוק, והכל לפני מתן הודעת הקיבול". סעיף 4(2) לחוק החוזים (חלק כללי), תשל"ג-1973 | פקיעת ההצעה הדין הקיים אינו מבחין לעניין זה בין הצעה רגילה לבין הצעה בלתי חוזרת. גבריאלה שלו ואפי צמח דיני חוזים (2019) | דינה של הצעה בלתי חוזרת לכן, במקרה של מות הניצע (אברהם) לפני מתן הודעת הקיבול, ההצעה פוקעת. יהושע ויסמן דיני קניין: זכויות קדימה ופרקי משכון (2014) | חזרה מן ההצעה יצוין כי קיימת ביקורת על גישה זו בספרות המשפטית, והצעת חוק דיני ממונות מציעה לתקן את החוק בנקודה זו, אך זהו הדין המצוי כיום. גבריאלה שלו ואפי צמח דיני חוזים (2019) | דינה של הצעה בלתי חוזרת',
    'הנחה שגויה כי אופייה הבלתי חוזר של ההצעה גובר על הוראות פקיעת ההצעה במקרה של מוות, או אי-הבחנה בין הדין המצוי לדין הרצוי.', '["פקיעת הצעה", "הצעה בלתי חוזרת", "מוות הניצע", "סעיף 4(2) לחוק החוזים", "דין מצוי מול דין רצוי"]'::jsonb, '**וריאציה 1 — פקיעה במוות:** האם הצעה בלתי חוזרת פוקעת במוות הניצע? ← כן, לפי סעיף 4(2) לחוק החוזים.
**וריאציה 2 — הבחנה בחוק:** האם החוק מבחין בין הצעה רגילה לבלתי חוזרת לעניין פקיעה במוות? ← לא, סעיף 4(2) אינו מבחין (שלו וצמח, דיני חוזים: 29).
**וריאציה 3 — יורשים:** האם יורשי הניצע יכולים לקבל את ההצעה? ← לא, ההצעה פוקעת עם מות הניצע.', 'הצעה בלתי חוזרת ← פוקעת במוות הניצע ← לפי סעיף 4(2) לחוק החוזים.',
    '["חוק החוזים (חלק כללי), תשל\"ג-1973, סעיף 4", "גבריאלה שלו ואפי צמח דיני חוזים (2019) | דינה של הצעה בלתי חוזרת", "יהושע ויסמן דיני קניין: זכויות קדימה ופרקי משכון (2014) | חזרה מן ההצעה"]'::jsonb
  );
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_2, 'א', 'לא, מכיוון שהצעה בלתי חוזרת אינה פוקעת במקרה של מוות לפני תום מועד הקיבול.', false, 'טענה זו אינה נכונה. סעיף 4(2) לחוק החוזים קובע כי הצעה פוקעת במקרה של מוות הניצע לפני מתן הודעת הקיבול, ואינו מבחין בין הצעה רגילה לבלתי חוזרת.', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_2, 'ב', 'כן, מכיוון שסעיף 4(2) לחוק החוזים קובע שהצעה פוקעת כשמת הניצע לפני מתן הודעת הקיבול, ואינו מבחין בין הצעה רגילה לבלתי חוזרת.', true, 'זוהי התשובה הנכונה. לפי סעיף 4(2) לחוק החוזים, הצעה פוקעת כשמת הניצע לפני מתן הודעת הקיבול. החוק אינו מבחין לעניין זה בין הצעה רגילה לבלתי חוזרת, ולכן ההצעה פוקעת.', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_2, 'ג', 'לא, מכיוון שההצעה בלתי חוזרת, ויורשיו של אברהם יכולים לקבל אותה.', false, 'טענה זו אינה נכונה. לפי הדין הקיים, מוות הניצע מפקיע את ההצעה, ואין ליורשים זכות לקבלה, אלא אם כן נקבע אחרת במפורש.', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_2, 'ד', 'כן, אך רק אם דפנה הודיעה על ביטול ההצעה ליורשיו של אברהם.', false, 'טענה זו אינה נכונה. פקיעת ההצעה במקרה של מוות היא אוטומטית מכוח החוק, ואינה דורשת הודעת ביטול נוספת מהמציע.', 4);

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_3, v_sq_id, 'ד', 'קיבול תוך שינוי כהצעה חדשה',
    4, 'עו"ד דפנה הציעה לעו"ד אברהם חוזה העסקה. אברהם השיב שהוא מסכים, אך מבקש שינוי קטן בתנאי השכר. מה דין ההצעה המקורית של דפנה, ומה דין תגובתו של אברהם?', 'שאלה זו עוסקת בכלל ''קיבול תוך שינוי'' הקבוע בסעיף 11 לחוק החוזים (חלק כללי). היא מדגישה כי תגובה של ניצע הכוללת תוספת, הגבלה או שינוי להצעה המקורית, אינה מהווה קיבול אלא הצעה חדשה, המפקיעה את ההצעה המקורית.', 'סעיף 11 לחוק החוזים (חלק כללי), תשל"ג-1973, קובע כי "קיבול שיש בו תוספת, הגבלה או שינוי אחר לעומת ההצעה כמוהו כהצעה חדשה". סעיף 11 לחוק החוזים (חלק כללי), תשל"ג-1973 | קיבול תוך שינוי משמעות הדבר היא שתגובתו של אברהם, המבקשת שינוי בתנאי השכר, אינה מהווה קיבול של הצעתה המקורית של דפנה. במקום זאת, היא נחשבת להצעה חדשה מצדו של אברהם, אשר מפקיעה את ההצעה המקורית של דפנה. ת"א (מחוזי חיפה) 697/02 תחסין חוסייסי נ'' גרהרד מרכוס (20.03.2005) ת"א (מחוזי חי'') 28877-03-16 גידי ברבר נ'' ערן עמור (20.04.2017) כעת, דפנה היא הניצעת להצעה החדשה של אברהם, והיא רשאית לקבלה, לדחותה או להציע הצעה נגדית משלה. ת"א (מחוזי חיפה) 697/02 תחסין חוסייסי נ'' גרהרד מרכוס (20.03.2005)',
    'הנחה שגויה כי שינוי קטן אינו מפקיע את ההצעה המקורית, או בלבול בין קיבול תוך שינוי לבין משא ומתן על הצעה קיימת.', '["קיבול תוך שינוי", "הצעה חדשה", "פקיעת הצעה", "סעיף 11 לחוק החuזים", "משא ומתן"]'::jsonb, '**וריאציה 1 — הגדרת קיבול תוך שינוי:** מהו קיבול תוך שינוי? ← תוספת, הגבלה או שינוי אחר לעומת ההצעה (סעיף 11 לחוק החוזים).
**וריאציה 2 — נפקות:** מהי הנפקות של קיבול תוך שינוי? ← כמוהו כהצעה חדשה, המפקיעה את ההצעה המקורית (סעיף 11 לחוק החוזים).
**וריאציה 3 — המשך מו"מ:** מה קורה לאחר קיבול תוך שינוי? ← הניצע המקורי הופך למציע, והמציע המקורי הופך לניצע להצעה החדשה.', 'קיבול תוך שינוי ← הצעה חדשה ← מפקיע את ההצעה המקורית.',
    '["חוק החוזים (חלק כללי), תשל\"ג-1973, סעיף 11", "ת\"א (מחוזי חיפה) 697/02 תחסין חוסייסי נ'' גרהרד מרכוס (20.03.2005)", "ת\"א (מחוזי חי'') 28877-03-16 גידי ברבר נ'' ערן עמור (20.04.2017)"]'::jsonb
  );
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_3, 'א', 'ההצעה המקורית של דפנה נשארת בתוקף, ותגובתו של אברהם נחשבת לקיבול חלקי.', false, 'טענה זו אינה נכונה. קיבול תוך שינוי מפקיע את ההצעה המקורית, ואינו נחשב לקיבול חלקי.', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_3, 'ב', 'ההצעה המקורית של דפנה פוקעת, ותגובתו של אברהם נחשבת ל''הצעה חדשה''.', true, 'זוהי התשובה הנכונה. לפי סעיף 11 לחוק החוזים, קיבול שיש בו שינוי כמוהו כהצעה חדשה, המפקיעה את ההצעה המקורית.', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_3, 'ג', 'ההצעה המקורית של דפנה פוקעת, ותגובתו של אברהם נחשבת לדחייה מוחלטת.', false, 'טענה זו אינה נכונה. אף שההצעה המקורית פוקעת, תגובתו של אברהם אינה דחייה מוחלטת אלא הצעה חדשה, המאפשרת המשך משא ומתן.', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_3, 'ד', 'ההצעה המקורית של דפנה נשארת בתוקף, ותגובתו של אברהם נחשבת למשא ומתן נוסף.', false, 'טענה זו אינה נכונה. קיבול תוך שינוי מפקיע את ההצעה המקורית, ואינו רק ''משא ומתן נוסף'' על ההצעה הקיימת.', 4);

  RAISE NOTICE 'Q% inserted: external_id %', 22, '2022-S-S-Q22';
END
$$;

