  v_ang_0 uuid := '6dcf1556-16cf-4616-83cc-4338b0ae655f'::uuid;
  v_ang_1 uuid := '676dcc23-6e22-4354-9b70-a3f9e5c71887'::uuid;
  v_ang_2 uuid := '186cd305-156e-447f-8cf6-783ac3220c28'::uuid;
  v_ang_3 uuid := 'bb0881db-13b4-490e-ad9a-44f8336bef65'::uuid;
BEGIN
