  INSERT INTO public.source_questions (
    id, question_group_id, version, is_current, external_id, chapter_id, subtopic_id, question_text, source_metadata, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list, notes_for_admin, status, created_by
  ) VALUES (
    v_sq_id, v_group_id, 1, true,
    '2022-S-S-Q23', v_chapter_id, v_subtopic_id, 'אדם הציג את עצמו כלפי אישה טרם נישואיהם כאדם דתי, אך בפועל, מאחורי גבה של האישה, ניהל אורח חיים חילוני לאחר הנישואין. האישה פונה אליך בטענה שהנישואין מקורם בטעות שהיא תוצאת הטעיה שהטעה אותה בעלה בכך שטרם הנישואין לא גילה לה שהוא חילוני, והיא מבקשת לתבוע אותו בבית המשפט בגין הנזקים הכלכליים והנפשיים שנגרמו במישרין מעניין זה. מה הדין?',
    '{"exam_year": 2022, "exam_season": "summer", "exam_part": 2, "exam_question_number": 23}'::jsonb, 'שאלה זו עוסקת בהיקף חובת הגילוי המשפטית בין בני זוג טרם הנישואין, ובפרט בעניינים הנוגעים לאמונה דתית או נטייה מינית. היא בוחנת את עמדת בית המשפט העליון, כפי שבאה לידי ביטוי בפסק הדין בע"מ 5827/19 פלוני נ'' פלונית, לפיה מטעמי מדיניות משפטית, אין להכיר בחובת גילוי משפטית בעניינים אלו, להבדיל מחובה מוסרית-ערכית.', 'בית המשפט העליון, בבע"מ 5827/19 פלוני נ'' פלונית, קבע כי מטעמי מדיניות משפטית, אין להכיר בקיומה של חובת גילוי משפטית (להבדיל מחובה מוסרית-ערכית) בין בני זוג בטרם הנישואין, לגבי נטייה מינית או אמונה דתית. בע"מ 5827/19 פלוני נ'' פלונית (16.08.2021) השופטת וילנר, בחוות דעתה, סיווגה את טענות המשיבות (האישה ואמה) בדבר הסתרת נטייה מינית ואמונה דתית כנופלות בגדר ''הקשרים אינטימיים ורגשיים'', וקבעה כי אלו אינם עניין לבית המשפט לדון בו. בע"מ 5827/19 פלוני נ'' פלונית (16.08.2021) בע"מ 5827/19 פלוני נ'' פלונית (16.08.2021) שיקולי המדיניות שהובילו למסקנה זו כוללים את השאיפה להימנע מפגיעה בפרטיות, הרצון למנוע הצפה של בתי המשפט בסוגיות אלה, והשאיפה שלא לפגוע באוטונומיה של האדם. בע"מ 5827/19 פלוני נ'' פלונית (16.08.2021) הלכה זו אושרה לאחרונה גם בבע"מ 4181/22. בע"מ 4181/22 פלוני נ'' פלונית (19.05.2024) לפיכך, האישה אינה יכולה לתבוע את בעלה בגין נזקים כלכליים או נפשיים הנובעים מאי-גילוי אמונותיו הדתיות. בני דון-יחייא תורת דיני המשפחה (2022) | האם חלה על בן זוג חובה משפטית לגלות לבן זוגו לפני הנישואין על נטיותיו המיניות?', 'הנחה שגויה כי כל אי-גילוי מהותי במערכת יחסים זוגית מקים עילת תביעה, מבלי להבחין בין חובה מוסרית לחובה משפטית, ובלי להכיר בשיקולי המדיניות המיוחדים של דיני המשפחה.',
    '["חובת גילוי", "אמונה דתית", "נטייה מינית", "מדיניות משפטית", "יחסים אינטימיים-רגשיים", "עילת תביעה", "הטעיה"]'::jsonb, '**וריאציה 1 — חובת גילוי דתית:** האם יש חובת גילוי משפטית לגבי אמונה דתית בין בני זוג? ← לא, מטעמי מדיניות משפטית (בע"מ 5827/19).
**וריאציה 2 — סוגי נזק:** האם ניתן לתבוע פיצויים (כלכליים/נפשיים) בגין אי-גילוי אמונה דתית? ← לא, אין עילת תביעה משפטית (בע"מ 5827/19).
**וריאציה 3 — חובה מוסרית:** האם שלילת חובת גילוי משפטית שוללת חובה מוסרית? ← לא, אין בכך כדי לשלול הכרה בחובה מוסרית-ערכית (בע"מ 5827/19).', 'אין חובת גילוי משפטית בין בני זוג לגבי אמונה דתית או נטייה מינית, ולכן לא ניתן לתבוע בגין אי-גילוי כזה, מטעמי מדיניות משפטית.', '["בע\"מ 5827/19 פלוני נ'' פלונית (16.08.2021)", "בע\"מ 4181/22 פלוני נ'' פלונית (19.05.2024)", "בע\"מ 57929-12-24 פלונית נ'' פלוני (29.01.2026)", "בני דון-יחייא תורת דיני המשפחה (2022) | האם חלה על בן זוג חובה משפטית לגלות לבן זוגו לפני הנישואין על נטיותיו המיניות?", "מיכאל בירנהק פרטיות חוקתית (2023) | 2. מעגל הקשרים הבין-אישיים"]'::jsonb,
    'classification_review: original chapter=''סדר דין אזרחי'' subtopic=''הליכים'' → mapped chapter=''family_inheritance'' subtopic=''marriage_divorce'' | classifier_note: Marriage by misrepresentation (man posed as religious) — marriage invalidity/error grounds | source_review_note: השאלה עוסקת בדיני משפחה, חוזים ונזיקין, שהם תחומי משפט מהותיים. בחרתי ב''הליכים'' תחת ''סדר דין אזרחי'' כהצבת מקום, מכיוון שהשאלה עוסקת ביכולת להגיש תביעה (הליך) וקיומה של עילת תביעה. עם זאת, הנושא המרכזי הוא מהותי ואינו משתלב באופן מושלם באף אחד מתתי-הנושאים הסגורים הקיימים. יש לשקול הוספת פרק ''דיני משפחה'' או ''דיני חוזים/נזיקין'' לרשימה הסגורה.', 'active', 'b9ecdde2-d07e-4761-96ab-05f0ad32d4e3'
  );

  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'א', 'על אדם מוטלת חובת גילוי משפטית לגלות לבן זוגו מהן אמונותיו ואם הוא אדם דתי, חובה היוצרת עילות חוזיות ונזיקיות שניתן לתבוע בגינן בבית המשפט. האישה זכאית לפיצויים בגין הטעות.', false, 'טענה זו אינה נכונה. בית המשפט העליון קבע כי אין להכיר בחובת גילוי משפטית בין בני זוג לגבי אמונה דתית, ולכן לא קיימות עילות תביעה חוזיות או נזיקיות בגין אי-גילוי כזה.', 1);
  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'ב', 'על אדם מוטלת חובת גילוי משפטית לגלות לבן זוגו מהן אמונותיו ואם הוא אדם דתי, חובה היוצרת עילות חוזיות ונזיקיות שניתן לתבוע בגינן בבית המשפט, אולם ניתן לתבוע בגינן פיצויים רק על הנזקים הנפשיים.', false, 'טענה זו אינה נכונה. אין חובת גילוי משפטית כאמור, ובנוסף, המשפט נמנע מלהעניק סעד בגין נזקים נפשיים הנובעים מאכזבות רגשיות במערכת היחסים הזוגית.', 2);
  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'ג', 'על אדם מוטלת חובת גילוי משפטית לגלות לבן זוגו מהן אמונותיו ואם הוא אדם דתי, חובה היוצרת עילות חוזיות ונזיקיות שניתן לתבוע בגינן בבית המשפט, אולם ניתן לתבוע בגינן פיצויים רק על הנזקים הכלכליים.', false, 'טענה זו אינה נכונה. אין חובת גילוי משפטית כאמור, ולכן גם לא קיימת עילה לפיצויים כלכליים בגין אי-גילוי אמונה דתית.', 3);
  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'ד', 'על אדם לא מוטלת חובת גילוי משפטית לגלות לבן זוגו מהן אמונותיו ואם הוא אדם דתי היוצרת עילות חוזיות ונזיקיות שניתן לתבוע בגינן בבית המשפט.', true, 'זוהי התשובה הנכונה. בית המשפט העליון קבע כי מטעמי מדיניות משפטית, אין להכיר בחובת גילוי משפטית בין בני זוג בטרם הנישואין לגבי אמונה דתית או נטייה מינית, להבדיל מחובה מוסרית-ערכית.', 4);

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_0, v_sq_id, 'א', 'חובת גילוי בהקשרים כלכליים',
    1, 'ראובן ולאה עומדים להינשא. ראובן, איש עסקים אמיד, מסתיר מלאה את היקף חובותיו הכספיים טרם חתימה על הסכם ממון. לאחר הנישואין, לאה מגלה את החובות וטוענת להטעיה. האם קיימת חובת גילוי משפטית במקרה זה?', 'שאלה זו בוחנת את ההבחנה שערך בית המשפט העליון בין סוגי חובות הגילוי בין בני זוג. היא מדגישה כי בעוד שאין חובת גילוי משפטית בעניינים אינטימיים-רגשיים, קיימת חובת גילוי בהקשרים כלכליים, במיוחד כאשר מדובר בהסכמי ממון או חלוקת רכוש.', 'בית המשפט העליון בבע"מ 5827/19 פלוני נ'' פלונית, הבחין בין שלושה הקשרים עיקריים לעניין חובת גילוי בין בני זוג: כלכליים, אינטימיים-רגשיים, ומרכיבים מהותיים במיהותו של בן הזוג. בע"מ 5827/19 פלוני נ'' פלונית (16.08.2021) לעמדת השופטת וילנר, שיקולי מדיניות אינם מונעים הכרה בחובת הגילוי בין בני זוג בהקשרים כלכליים, ואף תומכים באכיפתה. בע"מ 5827/19 פלוני נ'' פלונית (16.08.2021) זאת, בניגוד לעניינים אינטימיים ורגשיים. בע"מ 57929-12-24 פלונית נ'' פלוני (29.01.2026) במקרה הנדון, הסתרת היקף החובות הכספיים של ראובן טרם חתימה על הסכם ממון נופלת בגדר הקשרים הכלכליים, ולכן קיימת חובת גילוי משפטית. בני דון-יחייא תורת דיני המשפחה (2022) | האם חובת הגילוי המוגברת בין בני זוג מהווה שיקול בקבלת התביעה?',
    'הכללת כל סוגי המידע תחת אותה קטגוריה של אי-גילוי, מבלי להבחין בין עניינים כלכליים לאינטימיים-רגשיים, ובכך להסיק בטעות שאין חובת גילוי כלל.', '["חובת גילוי", "הקשרים כלכליים", "הסכם ממון", "מדיניות משפטית", "הטעיה"]'::jsonb, '**וריאציה 1 — סוגי גילוי:** אילו סוגי גילוי קיימים בין בני זוג? ← כלכליים, אינטימיים-רגשיים, ומרכיבים מהותיים במיהותו (בע"מ 5827/19).
**וריאציה 2 — חובת גילוי כלכלית:** האם יש חובת גילוי משפטית בהקשרים כלכליים? ← כן, שיקולי מדיניות תומכים בכך (בע"מ 5827/19).
**וריאציה 3 — הסכם ממון:** האם הסתרת חובות לפני הסכם ממון היא הפרת חובת גילוי? ← כן, זהו הקשר כלכלי מובהק (בע"מ 5827/19).', 'חובת גילוי משפטית קיימת בהקשרים כלכליים בין בני זוג, במיוחד לפני הסכם ממון.',
    '["בע\"מ 5827/19 פלוני נ'' פלונית (16.08.2021)", "בע\"מ 57929-12-24 פלונית נ'' פלוני (29.01.2026)", "בני דון-יחייא תורת דיני המשפחה (2022) | האם חובת הגילוי המוגברת בין בני זוג מהווה שיקול בקבלת התביעה?"]'::jsonb
  );
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_0, 'א', 'לא, מכיוון שאין חובת גילוי משפטית בין בני זוג לגבי עניינים אישיים וכלכליים כאחד.', false, 'טענה זו אינה נכונה. הפסיקה מבחינה בין הקשרים אינטימיים-רגשיים לבין הקשרים כלכליים, וקובעת חובת גילוי בהקשרים כלכליים.', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_0, 'ב', 'כן, מכיוון ששיקולי מדיניות משפטית תומכים בהכרה בחובת גילוי בין בני זוג בהקשרים כלכליים.', true, 'זוהי התשובה הנכונה. בית המשפט העליון קבע כי שיקולי מדיניות אינם מונעים הכרה בחובת גילוי בין בני זוג בהקשרים כלכליים, ואף תומכים באכיפתה, במיוחד בסמוך לכריתת הסכם ממון.', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_0, 'ג', 'לא, אלא אם כן לאה הוכיחה שראובן פעל בזדון מוחלט.', false, 'טענה זו אינה נכונה. חובת הגילוי בהקשרים כלכליים אינה תלויה בהוכחת זדון מוחלט, אלא באי-גילוי נתונים רלוונטיים.', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_0, 'ד', 'כן, אך רק אם החובות היו כה גדולים עד שהיו מונעים את הנישואין.', false, 'טענה זו אינה נכונה. אף שמהותיות המידע רלוונטית, חובת הגילוי בהקשרים כלכליים אינה מותנית בהכרח בכך שהמידע היה מונע את הנישואין, אלא בהיותו רלוונטי להסכם הממון.', 4);

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_1, v_sq_id, 'ב', 'שיקולי מדיניות באי-הכרה בחובת גילוי',
    2, 'מהם שיקולי המדיניות המשפטית העיקריים שהובילו את בית המשפט העליון לשלול הכרה בחובת גילוי משפטית לגבי נטיות מיניות ואמונות דתיות בין בני זוג?', 'שאלה זו מתמקדת בשיקולי המדיניות המשפטית המנחים את בית המשפט העליון בהגבלת תחולת דיני החוזים והנזיקין על היבטים מסוימים ביחסים בין בני זוג. היא מדגישה את החשיבות של הגנה על הפרטיות, מניעת הצפת בתי המשפט ושמירה על אוטונומיית הפרט.', 'בית המשפט העליון בבע"מ 5827/19 פלוני נ'' פלונית, קבע כי שורה ארוכה של שיקולי מדיניות מובילים למסקנה שאין להכיר בחובת גילוי משפטית המוטלת על בן זוג לגלות לבן זוגו האחר על נטיותיו המיניות או אמונותיו הדתיות טרם הנישואין או במהלכם. בע"מ 5827/19 פלוני נ'' פלונית (16.08.2021) שיקולים אלו כוללים: השאיפה להימנע מפגיעה בפרטיות על ידי עיסוק משפטי בהיבטים האינטימיים-רגשיים והאישיים ביותר של האדם; הרצון למנוע הצפה של בתי המשפט בסוגיות אלה; והשאיפה שלא לפגוע באוטונומיה של האדם וביכולתו לעצב את סיפור חייו. בע"מ 5827/19 פלוני נ'' פלונית (16.08.2021) בע"מ 4181/22 פלוני נ'' פלונית (19.05.2024)',
    'התמקדות בשיקולים כלליים של דיני נזיקין או חוזים, במקום בשיקולי המדיניות הספציפיים הנוגעים למערכות יחסים אינטימיות בין בני זוג.', '["מדיניות משפטית", "חובת גילוי", "פרטיות", "אוטונומיה", "הצפת בתי המשפט", "יחסים אינטימיים"]'::jsonb, '**וריאציה 1 — שיקולי מדיניות:** מהם השיקולים המרכזיים לשלילת חובת גילוי בעניינים אינטימיים? ← פגיעה בפרטיות, הצפת בתי המשפט, פגיעה באוטונומיה (בע"מ 5827/19).
**וריאציה 2 — תפקיד המשפט:** האם המשפט מתאים לבירור ענייני רגש? ← לא, המשפט אינו המסגרת המתאימה לריפוי כאבי לב או לסגירת חשבונות רגשיים (בע"מ 5827/19).
**וריאציה 3 — חובה מוסרית:** האם שלילת חובת גילוי משפטית שוללת חובה מוסרית? ← לא, אין בכך כדי לשלול הכרה בחובה מוסרית-ערכית (בע"מ 5827/19).', 'שלילת חובת גילוי משפטית בעניינים אינטימיים ← מטעמי מדיניות ← הגנה על פרטיות, מניעת הצפה, אוטונומיה.',
    '["בע\"מ 5827/19 פלוני נ'' פלונית (16.08.2021)", "בע\"מ 4181/22 פלוני נ'' פלונית (19.05.2024)", "מיכאל בירנהק פרטיות חוקתית (2023) | 2. מעגל הקשרים הבין-אישיים"]'::jsonb
  );
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_1, 'א', 'השאיפה למנוע פגיעה בפרטיות, הרצון למנוע הצפת בתי המשפט, והשאיפה שלא לפגוע באוטונומיה של האדם.', true, 'זוהי התשובה הנכונה. אלו הם השיקולים המרכזיים שצוינו בפסק הדין בע"מ 5827/19 כבסיס לשלילת חובת הגילוי המשפטית בעניינים אינטימיים-רגשיים.', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_1, 'ב', 'העדר נזק ממון ממשי, העדר קשר סיבתי בין אי-הגילוי לנזק, והקושי להוכיח כוונת זדון.', false, 'טענה זו אינה נכונה. אלו הם יסודות כלליים בעוולות נזיקיות, אך אינם השיקולים המדיניות הספציפיים שהובילו לשלילת חובת הגילוי בעניינים אינטימיים-רגשיים.', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_1, 'ג', 'ההכרה בכך שדיני החוזים אינם חלים על יחסים משפחתיים, וההכרה בכך שרגשות אינם מצרך סחיר.', false, 'טענה זו אינה נכונה. אף שהמשפט נרתע מלהחיל קני מידה מסחריים על יחסים רגשיים, הפסיקה כן מכירה בתחולת דיני החוזים והנזיקין באופן עקרוני על יחסים בין בני זוג, אך עם סייגים.', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_1, 'ד', 'הקושי להבחין בין אמת לשקר בענייני רגש, והרצון לעודד פיוס בין בני זוג.', false, 'טענה זו אינה נכונה. אף שהקושי להבחין באמת בענייני רגש הוא שיקול, ועידוד פיוס הוא מטרה כללית, אלו אינם השיקולים המרכזיים שצוינו בפסק הדין לשלילת חובת הגילוי המשפטית.', 4);

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_2, v_sq_id, 'ג', 'חובת גילוי במצב רפואי מהותי',
    3, 'אדם הסתיר מבן זוגו טרם הנישואין מצב רפואי מהותי וחריג, אשר יש בו כדי להשפיע באופן ממשי על חיי בני הזוג וילדיהם העתידיים. האם אי-גילוי זה יכול להקים עילת תביעה נזיקית או חוזית?', 'שאלה זו בוחנת את הגבולות המורכבים של חובת הגילוי בין בני זוג, תוך התמקדות בקטגוריה השלישית שהוצעה בפסיקה – ''הקשרים הנוגעים למרכיבים מהותיים בחייו ובמיהותו של בן הזוג''. היא מדגישה את האפשרות להכיר בחובת גילוי במקרים של מצב רפואי מהותי, בניגוד לעניינים אינטימיים-רגשיים.', 'בבע"מ 5827/19 פלוני נ'' פלונית, השופטת וילנר הציעה להבחין בין שלושה הקשרים לעניין חובת גילוי בין בני זוג. הקטגוריה השלישית היא ''הקשרים הנוגעים למרכיבים מהותיים בחייו ובמיהותו של בן הזוג''. בע"מ 5827/19 פלוני נ'' פלונית (16.08.2021) נתונים אלה, על פי רוב, יהיו אובייקטיביים, מדידים או בעלי ביטוי חיצוני. בתוך כך, ניתן למנות אי-גילוי בדבר מצב רפואי מהותי וחריג אשר יש בו כדי להשפיע באופן ממשי על חיי בני הזוג וילדיהם. בע"מ 5827/19 פלוני נ'' פלונית (16.08.2021) במקרים אלו, שאלת קיומה והיקפה של חובת הגילוי היא מורכבת, אך הפסיקה כן הכירה במקרים מסוימים בחובת גילוי לגבי מצב רפואי או נפשי חמור. בני דון-יחייא תורת דיני המשפחה (2022) | האם חובת הגילוי המוגברת בין בני זוג מהווה שיקול בקבלת התביעה?',
    'הנחה שגויה כי כל אי-גילוי בין בני זוג נחשב לעניין אינטימי-רגשי שאינו עילה לתביעה, מבלי להבחין בין סוגי המידע השונים.', '["חובת גילוי", "מצב רפואי מהותי", "מרכיבים מהותיים במיהותו", "מדיניות משפטית", "עילת תביעה"]'::jsonb, '**וריאציה 1 — קטגוריות גילוי:** מהן שלוש קטגוריות הגילוי בין בני זוג? ← כלכליים, אינטימיים-רגשיים, ומרכיבים מהותיים במיהותו (בע"מ 5827/19).
**וריאציה 2 — מצב רפואי:** לאיזו קטגוריה שייך מצב רפואי מהותי? ← לקטגוריה השלישית, של מרכיבים מהותיים במיהותו (בע"מ 5827/19).
**וריאציה 3 — עילת תביעה:** האם אי-גילוי מצב רפואי מהותי יכול להקים עילת תביעה? ← כן, בניגוד לעניינים אינטימיים-רגשיים, ייתכן שתקום חובת גילוי (בע"מ 5827/19, דון-יחייא).', 'אי-גילוי מצב רפואי מהותי ← עשוי להקים חובת גילוי משפטית ← בניגוד לעניינים אינטימיים-רגשיים.',
    '["בע\"מ 5827/19 פלוני נ'' פלונית (16.08.2021)", "בני דון-יחייא תורת דיני המשפחה (2022) | האם חובת הגילוי המוגברת בין בני זוג מהווה שיקול בקבלת התביעה?"]'::jsonb
  );
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_2, 'א', 'לא, מכיוון שכל ענייני הגילוי בין בני זוג נחשבים להקשרים אינטימיים-רגשיים שאינם עניין למשפט.', false, 'טענה זו אינה נכונה. הפסיקה מבחינה בין הקשרים אינטימיים-רגשיים לבין מרכיבים מהותיים במיהותו של בן הזוג, כאשר מצב רפואי מהותי יכול להיכלל בקטגוריה השנייה.', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_2, 'ב', 'כן, מכיוון שמצב רפואי מהותי וחריג נחשב למרכיב מהותי במיהותו של בן הזוג, ואי-גילויו עשוי להקים עילת תביעה.', true, 'זוהי התשובה הנכונה. השופטת וילנר בבע"מ 5827/19 הציעה להבחין בין הקשרים אינטימיים-רגשיים לבין מרכיבים מהותיים במיהותו של בן הזוג, וציינה מצב רפואי מהותי כדוגמה למקרה שבו ייתכן שתקום חובת גילוי.', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_2, 'ג', 'כן, אך רק אם המצב הרפואי היה ידוע למסתיר לפני הנישואין.', false, 'טענה זו אינה נכונה. ידיעת המסתיר היא תנאי הכרחי לכל עילת הטעיה או תרמית, אך אינה השיקול המרכזי בהבחנה בין סוגי חובות הגילוי.', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_2, 'ד', 'לא, אלא אם כן המצב הרפואי גרם לנזק כלכלי בלבד.', false, 'טענה זו אינה נכונה. חובת הגילוי במקרים אלו אינה מוגבלת לנזק כלכלי, אלא נוגעת להשפעה מהותית על חיי בני הזוג וילדיהם.', 4);

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_3, v_sq_id, 'ד', 'ניאוף כעילת תביעה בין בני זוג',
    4, 'אישה מגלה כי בעלה נאף בה במהלך נישואיהם. היא מבקשת לתבוע אותו בגין הנזקים הנפשיים שנגרמו לה כתוצאה מהניאוף, בעילות נזיקיות וחוזיות. מה הדין?', 'שאלה זו עוסקת בהלכה הפסוקה בנוגע לניאוף כעילת תביעה בין בני זוג. היא מדגישה את עמדת בית המשפט העליון, לפיה מטעמי מדיניות משפטית, אין להכיר בניאוף כעילה נזיקית או חוזית, הן בין בני הזוג לבין עצמם והן כלפי צד שלישי, וזאת כדי למנוע התערבות המשפט ביחסים אינטימיים-רגשיים.', 'בית המשפט העליון קבע בע"א 8489/12 פלוני נ'' פלוני (הלכת פלוני), כי מטעמים חזקים של מדיניות משפטית, שוללים הכרה בניאוף כעילה נזיקית או חוזית, הן בין בני הזוג בינם לבין עצמם והן בין מי מבני הזוג לבין צד שלישי. ע"א 8489/12 פלוני נ'' פלוני (29.10.2013) הלכה זו אושרה וחוזקה בפסקי דין מאוחרים יותר, לרבות בבע"מ 5827/19 ובבע"מ 4181/22. בע"מ 4181/22 פלוני נ'' פלונית (19.05.2024) בע"מ 57929-12-24 פלונית נ'' פלוני (29.01.2026) השיקולים לכך כוללים את הרתיעה של המשפט מלהיכנס למערכות יחסים אינטימיות, הקושי להכריע בשאלות רגשיות, והחשש מהצפת בתי המשפט. ע"א 8489/12 פלוני נ'' פלוני (29.10.2013)',
    'הנחה שגויה כי בגידה, בהיותה פגיעה קשה, מקנה אוטומטית עילת תביעה משפטית, מבלי להכיר בשיקולי המדיניות המיוחדים החלים על יחסים זוגיים.', '["ניאוף", "עילת תביעה נזיקית", "עילת תביעה חוזית", "מדיניות משפטית", "יחסים אינטימיים", "הלכת פלוני"]'::jsonb, '**וריאציה 1 — ניאוף כעילה:** האם ניאוף מקים עילת תביעה נזיקית/חוזית בין בני זוג? ← לא, מטעמי מדיניות משפטית (ע"א 8489/12 פלוני).
**וריאציה 2 — שיקולי מדיניות:** מהם השיקולים לשלילת עילה זו? ← רתיעה מהתערבות המשפט ביחסים אינטימיים, קושי בבירור רגשות, חשש מהצפה (ע"א 8489/12 פלוני).
**וריאציה 3 — צד שלישי:** האם ניתן לתבוע צד שלישי בגין ניאוף? ← לא, ההלכה חלה גם על צד שלישי (ע"א 8489/12 פלוני).', 'ניאוף אינו מקים עילת תביעה נזיקית או חוזית בין בני זוג (או כלפי צד שלישי) מטעמי מדיניות משפטית.',
    '["ע\"א 8489/12 פלוני נ'' פלוני (29.10.2013)", "בע\"מ 5827/19 פלוני נ'' פלונית (16.08.2021)", "בע\"מ 4181/22 פלוני נ'' פלונית (19.05.2024)", "ע\"א 5258/98 פלונית נ'' פלוני, נח(6) 209 (14.07.2004)"]'::jsonb
  );
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_3, 'א', 'כן, ניאוף מהווה הפרת חובה חקוקה ופגיעה בתום לב, המקימים עילת תביעה לפיצויים.', false, 'טענה זו אינה נכונה. בית המשפט העליון קבע במפורש כי ניאוף אינו מקים עילת תביעה נזיקית או חוזית בין בני זוג, מטעמי מדיניות משפטית.', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_3, 'ב', 'לא, מכיוון ששיקולי מדיניות משפטית שוללים הכרה בניאוף כעילה נזיקית או חוזית בין בני זוג.', true, 'זוהי התשובה הנכונה. הלכת פלוני (ע"א 8489/12) קבעה כי אין להכיר בניאוף כעילה נזיקית או חוזית בין בני זוג, וזאת מטעמים של מדיניות משפטית, לרבות הרתיעה מהתערבות המשפט ביחסים אינטימיים.', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_3, 'ג', 'כן, אך רק אם הניאוף גרם לנזק כלכלי מוכח.', false, 'טענה זו אינה נכונה. גם אם נגרם נזק כלכלי, הפסיקה שוללת הכרה בניאוף כעילה נזיקית או חוזית בין בני זוג.', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_3, 'ד', 'לא, אלא אם כן הניאוף בוצע עם צד שלישי, שאז ניתן לתבוע את הצד השלישי.', false, 'טענה זו אינה נכונה. הלכת פלוני שוללת הכרה בניאוף כעילה נזיקית או חוזית גם כלפי צד שלישי.', 4);

  RAISE NOTICE 'Q% inserted: external_id %', 23, '2022-S-S-Q23';
END
$$;

-- ============================================================
-- Q24 — 2022-S-S-Q24 — chapter=corporate subtopic=piercing_veil
-- classifier_note: Rami's tile company, 80% cash deal — piercing the corporate veil for personal liability per source review_note
-- ============================================================
DO $$
DECLARE
  v_sq_id uuid := '809f89d7-01d6-4633-852d-71b0f1e3bc0d'::uuid;
  v_group_id uuid := 'aacaf651-d08d-4e90-813b-29da515d49af'::uuid;
  v_chapter_id uuid;
  v_subtopic_id uuid;
  v_existing_id uuid;
  v_ang_0 uuid := '41b2ff16-c892-4cfe-91e5-5eedbdc96162'::uuid;
  v_ang_1 uuid := '7d55c8b5-00f7-4b8e-bc03-3e325b466184'::uuid;
  v_ang_2 uuid := '8aa28030-4ba8-4aef-9d50-af8f45f9a8d8'::uuid;
  v_ang_3 uuid := '4fbd0272-f1a6-4714-9347-e41d2f6684e9'::uuid;
BEGIN
  SELECT id INTO v_existing_id FROM public.source_questions WHERE external_id = '2022-S-S-Q24';
  IF v_existing_id IS NOT NULL THEN
    RAISE NOTICE 'Q% skipped: external_id % already exists', 24, '2022-S-S-Q24';
    RETURN;
  END IF;

  SELECT id INTO v_chapter_id FROM public.chapters WHERE code = 'corporate';
  IF v_chapter_id IS NULL THEN
    RAISE EXCEPTION 'Chapter code % not found', 'corporate';
  END IF;

  SELECT id INTO v_subtopic_id FROM public.subtopics WHERE code = 'piercing_veil' AND chapter_id = v_chapter_id;
  IF v_subtopic_id IS NULL THEN
    RAISE EXCEPTION 'Subtopic code % not found under chapter %', 'piercing_veil', 'corporate';
  END IF;

  INSERT INTO public.source_questions (
    id, question_group_id, version, is_current, external_id, chapter_id, subtopic_id, question_text, source_metadata, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list, notes_for_admin, status, created_by
  ) VALUES (
    v_sq_id, v_group_id, 1, true,
    '2022-S-S-Q24', v_chapter_id, v_subtopic_id, 'רמי ורעייתו הם הבעלים של חברת "אריחים בע"מ" (להלן: החברה). שמשון ורעייתו (להלן: הזוג) הגיעו למשרדי התצוגה של החברה וביקשו לקנות אריחים. רמי התנה את מכירת האריחים בכך ש-80% מהתמורה תשולם במזומן בהתאם להתקשרות מול החברה, וטען שזו הדרך היחידה להבטיח שמחיר האריחים לא יעלה וכי אלה יסופקו לזוג במהרה. כל זאת עשה רמי הגם שכבר באותו מועד ידע כי החברה אינה יכולה לעמוד בהתחייבויותיה, כי זו מרוקנת מכל נכסיה, וכי האריחים לא יסופקו לזוג. שמשון ורעייתו, אנשים ישרים ונאיבים, השתכנעו מדבריו של רמי, חתמו על ההזמנה ושילמו לחברה את שנדרשו. האריחים לא סופקו. בני הזוג הגישו תביעה נגד החברה וכן נגד רמי באופן אישי. מה הדין?',
    '{"exam_year": 2022, "exam_season": "summer", "exam_part": 2, "exam_question_number": 24}'::jsonb, 'שאלה זו עוסקת בדוקטרינת הרמת מסך ההתאגדות, המהווה חריג לעקרון האישיות המשפטית הנפרדת של החברה. היא בוחנת את התנאים להפעלת דוקטרינה זו, ובפרט את העילה של הונאת אדם או קיפוח נושה, ואת דרישת המודעות של בעל המניות, כפי שמעוגנים בסעיף 6 לחוק החברות, תשנ"ט-1999.', 'הכלל הבסיסי בדיני חברות הוא עקרון האישיות המשפטית הנפרדת של החברה, הקבוע בסעיף 4 לחוק החברות, תשנ"ט-1999. עיקרון זה מפריד בין זכויות וחובות החברה לבין אלו של בעלי מניותיה. ע"א 8416/19 עו"ד שלמה נס ורו"ח אלי שפלר מפרקי חברת אגרקסקו חברה לייצור חקלאי בע"מ נ'' מדינת ישראל (22.12.2021) עם זאת, סעיף 6 לחוק החברות קובע חריג לעיקרון זה, המאפשר לבית המשפט "לייחס חוב של חברה לבעל מניה בה, אם מצא כי בנסיבות הענין צודק ונכון לעשות כן, במקרים החריגים שבהם השימוש באישיות המשפטית הנפרדת נעשה באחד מאלה: (א) באופן שיש בו כדי להונות אדם או לקפח נושה של החברה; (ב) באופן הפוגע בתכלית החברה ותוך נטילת סיכון בלתי סביר באשר ליכולתה לפרוע את חובותיה, ובלבד שבעל המניה היה מודע לשימוש כאמור". סעיף 6(א)(1) לחוק החברות, תשנ"ט-1999 | הרמת מסך במקרה הנדון, רמי, כבעל מניות, ידע שהחברה חדלת פירעון, מרוקנת מנכסיה, ושהאריחים לא יסופקו, ובכל זאת התנה תשלום במזומן והבטיח הבטחות שווא. פעולות אלו מהוות שימוש באישיות המשפטית הנפרדת של החברה באופן שיש בו כדי להונות את הזוג, ורמי היה מודע לכך. ת"א (שלום ק"ג) 32527-09-20 יניב דהן נ'' שלום שרלי סילם (26.12.2024) לכן, בית המשפט רשאי להרים את מסך ההתאגדות ולייחס לרמי את חובות החברה כלפי הזוג. ת"א (שלום ת"א) 26503-05-22 ארז שלו נ'' טי.סי.אם דיגיטל בע"מ (26.06.2024)', 'הנחה שגויה כי עקרון האישיות המשפטית הנפרדת הוא מוחלט ואינו ניתן לחריגה, או אי-הבחנה בין אחריות החברה לאחריות אישית של בעל מניות במקרים של שימוש לרעה במסך ההתאגדות.',
    '["הרמת מסך", "אישיות משפטית נפרדת", "חוק החברות", "הונאה", "קיפוח נושה", "מודעות בעל מניה", "שימוש לרעה"]'::jsonb, '**וריאציה 1 — עקרון יסוד:** מהו עקרון האישיות המשפטית הנפרדת? ← החברה נפרדת מבעלי מניותיה (סעיף 4 לחוק החברות).
**וריאציה 2 — עילות להרמת מסך:** מתי ניתן להרים מסך? ← במקרים חריגים של שימוש לרעה, כגון הונאה או קיפוח נושה, ובמודעות בעל המניה (סעיף 6(א) לחוק החברות).
**וריאציה 3 — יישום למקרה:** האם ידיעה על חדלות פירעון והבטחות שווא מהוות הונאה? ← כן, זהו שימוש מודע וחריג באישיות המשפטית של החברה כדי להונות (סעיף 6(א)(1)(א) לחוק החברות).', 'הרמת מסך אפשרית כאשר בעל מניות עושה שימוש מודע וחריג באישיות המשפטית הנפרדת של החברה כדי להונות או לקפח נושה, כפי שקרה במקרה של רמי.', '["חוק החברות, תשנ\"ט-1999, סעיף 6", "ע\"א 8416/19 עו\"ד שלמה נס ורו\"ח אלי שפלר מפרקי חברת אגרקסקו חברה לייצור חקלאי בע\"מ נ'' מדינת ישראל (22.12.2021)", "ת\"א (שלום ק\"ג) 32527-09-20 יניב דהן נ'' שלום שרלי סילם (26.12.2024)", "ת\"א (שלום ת\"א) 26503-05-22 ארז שלו נ'' טי.סי.אם דיגיטל בע\"מ (26.06.2024)"]'::jsonb,
    'classification_review: original chapter=''סדר דין אזרחי'' subtopic=''הליכים'' → mapped chapter=''corporate'' subtopic=''piercing_veil'' | classifier_note: Rami''s tile company, 80% cash deal — piercing the corporate veil for personal liability per source review_note | source_review_note: השאלה עוסקת בדיני חברות, שהם תחום מהותי במשפט האזרחי. בחרתי ב''הליכים'' תחת ''סדר דין אזרחי'' כהצבת מקום, מכיוון שהרמת מסך היא הליך משפטי המאפשר הטלת אחריות. עם זאת, הנושא המרכזי הוא מהותי ואינו משתלב באופן מושלם באף אחד מתתי-הנושאים הסגורים הקיימים. יש לשקול הוספת פרק ''דיני חברות'' או תת-נושא רחב יותר תחת ''סדר דין אזרחי'' שיכלול נושאים מהותיים בעלי השלכות דיוניות.', 'active', 'b9ecdde2-d07e-4761-96ab-05f0ad32d4e3'
  );

  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'א', 'בית המשפט רשאי לייחס לרמי את החוב של החברה היות שרמי עשה שימוש מודע וחריג באישיות המשפטית של החברה כדי להונות את הזוג.', true, 'זוהי התשובה הנכונה. סעיף 6(א)(1)(א) לחוק החברות מאפשר הרמת מסך כאשר נעשה שימוש באישיות המשפטית הנפרדת כדי להונות אדם או לקפח נושה, ובלבד שבעל המניה היה מודע לכך. במקרה זה, רמי ידע שהחברה חדלת פירעון ופעל במרמה.', 1);
  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'ב', 'בית המשפט אינו רשאי לייחס לרמי את החוב של החברה היות שהזוג התקשר עם החברה ולא עם רמי באופן אישי.', false, 'טענה זו אינה נכונה. אף שהכלל הוא הפרדה בין החברה לבעלי מניותיה, דוקטרינת הרמת המסך נועדה בדיוק למקרים חריגים שבהם נעשה שימוש לרעה באישיות המשפטית הנפרדת, כגון הונאה, כדי לאפשר ייחוס חובות לבעל המניות.', 2);
  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'ג', 'בית המשפט רשאי לייחס לרמי את החוב של החברה היות שרמי הוא זה ששכנע את הזוג לבצע את ההתקשרות עם החברה, ורמי, בשונה מהחברה, הוא זה שבפועל התקשר עם הזוג.', false, 'טענה זו אינה מדויקת. עצם השכנוע אינו מספיק להרמת מסך. נדרש שימוש לרעה באישיות המשפטית הנפרדת של החברה, כגון הונאה או קיפוח, בתוספת מודעות של בעל המניות, כפי שמפורט בסעיף 6 לחוק החברות.', 0);
  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'ד', 'בית המשפט אינו רשאי לייחס לרמי את החוב של החברה היות שרמי אינו הבעלים היחיד של החברה.', false, 'טענה זו אינה נכונה. סעיף 6 לחוק החברות אינו דורש שבעל המניות יהיה הבעלים היחיד של החברה כדי להרים מסך. הרמת מסך יכולה להתבצע גם נגד בעל מניות שאינו יחיד, כל עוד מתקיימים התנאים הקבועים בחוק.', 0);

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_0, v_sq_id, 'א', 'הרמת מסך בחברת יחיד/משפחתית',
    1, 'יוסי הוא בעל המניות היחיד ומנהל חברת "יוסי בניה בע"מ". יוסי נוהג לערבב את כספי החברה עם כספיו הפרטיים, ואין הפרדה ברורה בין נכסיו האישיים לנכסי החברה. החברה נקלעה לחובות כבדים. האם בית המשפט ינקוט בגישה ליברלית יותר בהרמת מסך ההתאגדות במקרה זה?', 'שאלה זו בוחנת את הגישה המיוחדת של בתי המשפט להרמת מסך ההתאגדות בחברות יחיד או חברות משפחתיות. היא מדגישה כי במקרים אלו, בשל הקרבה בין בעל המניות לחברה והנטייה לערבוב נכסים, בתי המשפט נוטים לנקוט בגישה ליברלית יותר בהפעלת דוקטרינת הרמת המסך.', 'הכלל הבסיסי בדיני חברות הוא עקרון האישיות המשפטית הנפרדת של החברה (סעיף 4 לחוק החברות). עם זאת, הפסיקה הכירה בכך שכאשר מדובר בחברה פרטית משפחתית או בחברת יחיד, בחינת התנאים להרמת מסך ההתאגדות תהיה פחות נוקשה, ובית המשפט ינקוט בגישה ליברלית יותר. ת"א (שלום ת"א) 13976-08-15 עיריית תל-אביב-יפו נ'' א.מגש אחזקות בע"מ (29.01.2023) ת"א (שלום אשד'') 28463-11-21 עיריית אשדוד נ'' אקזיט גיים ישראל בע"מ (11.01.2026) הסיבה לכך היא שבחברות אלו, לרוב, בעל המניות הוא גם המנהל והרוח החיה, וקיימת נטייה לערבוב נכסים וניהול לא פורמלי, מה שמקל על ניצול לרעה של מסך ההתאגדות. ת"א (שלום אשד'') 28463-11-21 עיריית אשדוד נ'' אקזיט גיים ישראל בע"מ (11.01.2026) ערבוב נכסים של בעלי עניין עם נכסי החברה הוא אחת העילות המקובלות להרמת מסך. ס"ע (אזורי חי'') 44599-05-12 ולדימיר פרידמן - אלעד אחזקות בע"מ (בפירוק) (05.01.2016)',
    'הנחה שגויה כי עקרון האישיות המשפטית הנפרדת חל באופן אחיד ונוקשה על כל סוגי החברות, מבלי להכיר בגישה המקלה כלפי חברות יחיד ומשפחתיות.', '["הרמת מסך", "חברת יחיד", "חברה משפחתית", "אישיות משפטית נפרדת", "ערבוב נכסים", "גישה ליברלית"]'::jsonb, '**וריאציה 1 — חברת יחיד:** האם בחברת יחיד יש גישה ליברלית יותר להרמת מסך? ← כן, הפסיקה נוטה לכך (ת"א (שלום ת"א) 13976-08-15).
**וריאציה 2 — סיבה לליברליות:** מדוע יש גישה ליברלית יותר בחברות יחיד/משפחתיות? ← בשל הקלות שבה מתבצע ערבוב נכסים וניהול לא פורמלי (ת"א (שלום אשד'') 28463-11-21).
**וריאציה 3 — עילות:** האם ערבוב נכסים יכול להצדיק הרמת מסך? ← כן, זו אחת העילות המקובלות (ס"ע (אזורי חי'') 44599-05-12).', 'בחברת יחיד/משפחתית ← גישה ליברלית יותר להרמת מסך ← בשל ערבוב נכסים וניהול לא פורמלי.',
    '["חוק החברות, תשנ\"ט-1999, סעיף 4", "ת\"א (שלום ת\"א) 13976-08-15 עיריית תל-אביב-יפו נ'' א.מגש אחזקות בע\"מ (29.01.2023)", "ת\"א (שלום אשד'') 28463-11-21 עיריית אשדוד נ'' אקזיט גיים ישראל בע\"מ (11.01.2026)", "ס\"ע (אזורי חי'') 44599-05-12 ולדימיר פרידמן - אלעד אחזקות בע\"מ (בפירוק) (05.01.2016)"]'::jsonb
  );
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_0, 'א', 'לא, עקרון האישיות המשפטית הנפרדת חל באופן שווה על כל סוגי החברות.', false, 'טענה זו אינה נכונה. הפסיקה הכירה בגישה ליברלית יותר להרמת מסך בחברות יחיד או חברות משפחתיות, בשל הקלות שבהן מתבצע ערבוב נכסים וניהול לא תקין.', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_0, 'ב', 'כן, כאשר מדובר בחברת יחיד או חברה משפחתית, הפסיקה נוטה לגישה ליברלית יותר בהרמת מסך.', true, 'זוהי התשובה הנכונה. הפסיקה קבעה כי בחברות יחיד או חברות משפחתיות, שבהן לרוב אין הפרדה ברורה בין בעל המניות לחברה, בית המשפט ינקוט בגישה ליברלית יותר בהרמת מסך ההתאגדות.', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_0, 'ג', 'כן, אך רק אם יוסי פעל במרמה מובהקת.', false, 'טענה זו אינה נכונה. אף שמרמה היא עילה מובהקת להרמת מסך, בחברות יחיד/משפחתיות גם ערבוב נכסים או ניהול לא תקין עשויים להצדיק הרמת מסך, גם ללא הוכחת מרמה מובהקת.', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_0, 'ד', 'לא, אלא אם כן החברה הוקמה במטרה מובהקת להונות נושים.', false, 'טענה זו אינה נכונה. אף שהקמת חברה למטרות תרמית היא עילה להרמת מסך, בחברות יחיד/משפחתיות, גם התנהלות שוטפת של ערבוב נכסים עשויה להצדיק הרמת מסך.', 4);

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_1, v_sq_id, 'ב', 'תנאים מצטברים להרמת מסך',
    2, 'מהם התנאים המצטברים הנדרשים להרמת מסך ההתאגדות וייחוס חוב של חברה לבעל מניה בה, לפי סעיף 6(א) לחוק החברות?', 'שאלה זו מתמקדת בתנאים המצטברים הנדרשים להפעלת דוקטרינת הרמת מסך ההתאגדות, כפי שמעוגנים בסעיף 6(א) לחוק החברות. היא מדגישה את הצורך בקיומן של עילות ספציפיות, מודעות של בעל המניות, ושיקול דעת שיפוטי בדבר צדק ונכונות.', 'סעיף 6(א) לחוק החברות, תשנ"ט-1999, קובע את התנאים להרמת מסך ההתאגדות. על מנת שבית המשפט ירים את מסך ההתאגדות, צריכים להתקיים מספר תנאים מצטברים: ראשית, התקיימות אחת העילות המפורטות בסעיף 6(א)(1) לחוק, קרי, שהשימוש באישיות המשפטית הנפרדת של החברה נעשה כדי להונות אדם, או לקפח נושה של החברה, או באופן הפוגע בתכלית החברה ותוך נטילת סיכון בלתי סביר ביחס ליכולתה לפרוע את חובותיה. סעיף 6(א)(1) לחוק החברות, תשנ"ט-1999 | הרמת מסך שנית, נדרשת תשתית ראייתית לכך שבעל המניה היה מודע לשימוש כאמור (או חשד ונמנע מלברר). סעיף 6(א)(1) לחוק החברות, תשנ"ט-1999 | הרמת מסך שלישית, על בית המשפט להשתכנע כי מדובר במקרה חריג שבו צודק ונכון להורות על הרמת המסך. סעיף 6(א)(1) לחוק החברות, תשנ"ט-1999 | הרמת מסך הרמת מסך היא סעד קיצוני וחריג, ושימוש בו ייעשה במשורה. ת"א (שלום ת"א) 26503-05-22 ארז שלו נ'' טי.סי.אם דיגיטל בע"מ (26.06.2024)',
    'התמקדות באחד התנאים בלבד או אי-הבנה של אופיים המצטבר של התנאים הנדרשים להרמת מסך.', '["הרמת מסך", "חוק החברות", "תנאים מצטברים", "הונאה", "קיפוח נושה", "מודעות בעל מניה"]'::jsonb, '**וריאציה 1 — תנאי סף:** מהם תנאי הסף להרמת מסך? ← התקיימות עילה (הונאה/קיפוח/סיכון בלתי סביר), מודעות בעל המניה, וצדק ונכונות (סעיף 6(א) לחוק החברות).
**וריאציה 2 — מודעות:** מהי דרישת המודעות? ← מודעות לשימוש לרעה, או חשד והימנעות מבירור (סעיף 6(א)(2) לחוק החברות).
**וריאציה 3 — אופי הסעד:** האם הרמת מסך היא סעד שגרתי? ← לא, זהו סעד קיצוני וחריג שייעשה בו שימוש במשורה (ת"א (שלום ת"א) 26503-05-22).', 'הרמת מסך דורשת: עילה חריגה, מודעות בעל המניה, וצדק ונכונות, וזהו סעד קיצוני.',
    '["חוק החברות, תשנ\"ט-1999, סעיף 6", "ת\"א (שלום ת\"א) 26503-05-22 ארז שלו נ'' טי.סי.אם דיגיטל בע\"מ (26.06.2024)"]'::jsonb
  );
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_1, 'א', 'התקיימות אחת העילות המפורטות בסעיף 6(א)(1) לחוק, מודעות בעל המניה לשימוש לרעה, וכי בנסיבות העניין צודק ונכון להרים את המסך.', true, 'זוהי התשובה הנכונה. אלו הם שלושת התנאים המצטברים העיקריים שנקבעו בסעיף 6(א) לחוק החברות ובפסיקה להרמת מסך ההתאגדות.', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_1, 'ב', 'הוכחת חדלות פירעון של החברה, וכי בעל המניה הוא בעל השליטה היחיד בחברה.', false, 'טענה זו אינה נכונה. חדלות פירעון אינה תנאי הכרחי להרמת מסך, וגם בעל מניות שאינו יחיד יכול להיות מושא להרמת מסך.', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_1, 'ג', 'הוכחת כוונת זדון של בעל המניה, וכי החברה רוקנה מנכסיה.', false, 'טענה זו אינה נכונה. כוונת זדון היא אחת העילות (הונאה), אך לא תמיד נדרשת. ריקון נכסים הוא דוגמה לשימוש לרעה, אך אינו תנאי מצטבר בפני עצמו.', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_1, 'ד', 'הוכחת נזק לנושה, וכי לא ניתן להיפרע מהחברה.', false, 'טענה זו אינה נכונה. אף שאלו שיקולים רלוונטיים, הם אינם התנאים המצטברים המפורטים בסעיף 6(א) לחוק החברות.', 4);

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_2, v_sq_id, 'ג', 'אחריות אישית של אורגן',
    3, 'מנהל חברה ביצע עוולה נזיקית במסגרת תפקידו בחברה. האם ניתן להטיל עליו אחריות אישית בגין העוולה, ללא צורך בהרמת מסך ההתאגדות?', 'שאלה זו עוסקת בהבחנה חשובה בין דוקטרינת הרמת מסך ההתאגדות לבין הטלת אחריות אישית על אורגן בחברה. היא מדגישה כי אורגן יכול לחוב באחריות אישית בגין מעשיו, גם אם פעל במסגרת תפקידו, אם מעשיו מהווים עוולה לפי המשפט האזרחי, וזאת ללא צורך בהתעלמות מהאישיות המשפטית הנפרדת של החברה.', 'הפסיקה מבחינה בין הרמת מסך ההתאגדות לבין הטלת אחריות אישית על אורגן בחברה. נושא משרה בתאגיד עשוי לחוב באחריות אישית בשל מעשיו, ללא צורך בהרמת מסך ההתאגדות. ת"א (שלום חי'') 33189-09-20 Suzhou Star Materials Co. Ltd נ'' וסילי לושקריוב (01.01.2024) האורגן נושא באחריות לנזק שהוא גרם בהתנהגותו, ככל שזו מגלה עילה לפי המשפט האזרחי. ת"א (שלום חי'') 33189-09-20 Suzhou Star Materials Co. Ltd נ'' וסילי לושקריוב (01.01.2024) עצם העובדה שאדם פועל בכובעו כאורגן, נושא משרה או עובד של החברה אינה מקנה לו חסינות מפני חבות בנזיקין, ככל שמעשיו או מחדליו ממלאים אחר יסודותיה של עוולה נזיקית, אפילו אם הוא מבצע את העוולה לא למען עצמו אלא למען החברה. ת"א (שלום חי'') 33189-09-20 Suzhou Star Materials Co. Ltd נ'' וסילי לושקריוב (01.01.2024) במקרה של אחריות אישית, האורגן יחוב רק בגין הנזק שנגרם כפועל יוצא מפעולתו המזיקה, בניגוד להרמת מסך שבה תחול על בעל המניות החבות בכל חובותיה של החברה. ת"א (מחוזי ת"א) 45944-12-20 הלן טרוויס נ'' גלובל אפ טכנולוגיות (2010) בע"מ (23.06.2025)',
    'בלבול בין הרמת מסך (המתייחסת לחובות החברה) לבין אחריות אישית של אורגן (המתייחסת למעשיו האישיים המהווים עוולה).', '["אחריות אישית של אורגן", "עוולה נזיקית", "אישיות משפטית נפרדת", "חסינות", "חוק החברות"]'::jsonb, '**וריאציה 1 — הבחנה:** מה ההבדל בין הרמת מסך לאחריות אישית של אורגן? ← הרמת מסך מטילה חובות חברה על בעל מניות; אחריות אישית מטילה חבות על אורגן בגין מעשיו המזיקים (ת"א (מחוזי ת"א) 45944-12-20).
**וריאציה 2 — חסינות:** האם אורגן חסין מאחריות אישית אם פעל למען החברה? ← לא, אם מעשיו ממלאים יסודות עוולה נזיקית (ת"א (שלום חי'') 33189-09-20).
**וריאציה 3 — תנאים:** מה נדרש להטלת אחריות אישית על אורגן? ← הוכחת יסודות עוולה נזיקית שבוצעה על ידו (ת"א (שלום ב"ש) 30742-08-10).', 'אחריות אישית של אורגן ← בגין עוולה נזיקית שביצע ← ללא צורך בהרמת מסך ← גם אם פעל למען החברה.',
    '["ת\"א (שלום חי'') 33189-09-20 Suzhou Star Materials Co. Ltd נ'' וסילי לושקריוב (01.01.2024)", "ת\"א (מחוזי ת\"א) 45944-12-20 הלן טרוויס נ'' גלובל אפ טכנולוגיות (2010) בע\"מ (23.06.2025)", "ת\"א (שלום ב\"ש) 30742-08-10 ברנס ניקוי חול וצביעה תעשייתית בע\"מ נ'' ישראל (איזי) אביטוב (26.04.2014)"]'::jsonb
  );
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_2, 'א', 'לא, כל עוד המנהל פעל במסגרת תפקידו בחברה, הוא חסין מאחריות אישית.', false, 'טענה זו אינה נכונה. הפסיקה קבעה כי פעולה בכובע של אורגן אינה מקנה חסינות מפני חבות בנזיקין, אם מעשיו ממלאים אחר יסודות עוולה נזיקית.', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_2, 'ב', 'כן, ניתן להטיל אחריות אישית על אורגן בגין עוולה נזיקית שביצע, אם מעשיו ממלאים את יסודות העוולה, וזאת ללא צורך בהרמת מסך.', true, 'זוהי התשובה הנכונה. הפסיקה מבחינה בין הרמת מסך לאחריות אישית של אורגן. אורגן יכול לחוב באחריות אישית בגין עוולה שגרם, גם אם פעל למען החברה, וזאת ללא צורך בהרמת מסך.', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_2, 'ג', 'כן, אך רק אם המנהל פעל מתוך כוונת זדון אישית ולא למען החברה.', false, 'טענה זו אינה נכונה. אורגן יכול לחוב באחריות אישית גם אם פעל למען החברה, כל עוד מעשיו ממלאים את יסודות העוולה הנזיקית.', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_2, 'ד', 'לא, אלא אם כן החברה חדלת פירעון ואין ממנה ממה להיפרע.', false, 'טענה זו אינה נכונה. אחריות אישית של אורגן אינה תלויה בחדלות פירעון של החברה, אלא במעשיו האישיים המהווים עוולה.', 4);

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_3, v_sq_id, 'ד', 'הדחיית חוב כסעד חלופי',
    4, 'מהי דוקטרינת הדחיית חוב, וכיצד היא שונה מהרמת מסך ההתאגדות?', 'שאלה זו עוסקת בדוקטרינת הדחיית חוב כסעד חלופי ומתון יותר מהרמת מסך ההתאגדות, כפי שמעוגנת בסעיף 6(ג) לחוק החברות. היא מדגישה את ההבדל המהותי בין שני הסעדים ואת המקרים שבהם בית המשפט עשוי להעדיף את הדחיית חוב.', 'דוקטרינת הדחיית חוב (Subordination of Debt) מעוגנת בסעיף 6(ג) לחוק החברות, תשנ"ט-1999. סעיף זה קובע כי "בית משפט רשאי להשעות זכותו של בעל מניה לפירעון חובו מאת החברה עד לאחר שהחברה פרעה במלואן את כל התחייבויותיה כלפי נושים אחרים של החברה, אם מצא כי התקיימו התנאים לייחוס חוב של החברה לבעל המניה כאמור בסעיף קטן (א)". סעיף 6(ג) לחוק החברות, תשנ"ט-1999 | הרמת מסך הדחיית חוב מהווה אמצעי מתון יותר מ"הרמת מסך", שכן היא אינה מטילה את חובות החברה על בעל המניות באופן ישיר, אלא רק משעה את זכותו להיפרע מהחברה עד לאחר שכל יתר הנושים נפרעו. ע"א 8416/19 עו"ד שלמה נס ורו"ח אלי שפלר מפרקי חברת אגרקסקו חברה לייצור חקלאי בע"מ נ'' מדינת ישראל (22.12.2021) הדחיית חוב רלוונטית במיוחד במצבים של "מימון דק" (Under-capitalization), כאשר החברה ממומנת באופן בלתי מספק על ידי בעלי מניותיה, מה שמחצין את הסיכונים על הנושים החיצוניים. ע"א 8416/19 עו"ד שלמה נס ורו"ח אלי שפלר מפרקי חברת אגרקסקו חברה לייצור חקלאי בע"מ נ'' מדינת ישראל (22.12.2021)',
    'בלבול בין הדחיית חוב להרמת מסך, או אי-הבנה של אופיו המתון יותר של סעד הדחיית חוב והמקרים שבהם הוא מופעל.', '["הדחיית חוב", "הרמת מסך", "סעיף 6(ג) לחוק החברות", "מימון דק", "נושים", "סעד מתון"]'::jsonb, '**וריאציה 1 — הגדרה:** מהי הדחיית חוב? ← השעיית זכותו של בעל מניה להיפרע מהחברה עד לאחר שכל יתר הנושים נפרעו (סעיף 6(ג) לחוק החברות).
**וריאציה 2 — הבדל מהרמת מסך:** האם הדחיית חוב קיצונית כמו הרמת מסך? ← לא, היא סעד מתון יותר (ע"א 8416/19).
**וריאציה 3 — מתי מופעל:** מתי מופעלת דוקטרינת הדחיית חוב? ← במצבים של ''מימון דק'' או כאשר מתקיימים התנאים לייחוס חוב (סעיף 6(ג) לחוק החברות, ע"א 8416/19).', 'הדחיית חוב ← סעד מתון מהרמת מסך ← משעה זכות בעל מניה להיפרע ← מופעל במצבי ''מימון דק''.',
    '["חוק החברות, תשנ\"ט-1999, סעיף 6", "ע\"א 8416/19 עו\"ד שלמה נס ורו\"ח אלי שפלר מפרקי חברת אגרקסקו חברה לייצור חקלאי בע\"מ נ'' מדינת ישראל (22.12.2021)"]'::jsonb
  );
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_3, 'א', 'הדחיית חוב היא סעד קיצוני יותר מהרמת מסך, המטיל את כל חובות החברה על בעל המניה.', false, 'טענה זו אינה נכונה. הדחיית חוב היא סעד מתון יותר מהרמת מסך, ואינה מטילה את כל חובות החברה על בעל המניה.', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_3, 'ב', 'הדחיית חוב משעה את זכותו של בעל מניה להיפרע את חובו מהחברה עד לאחר שכל יתר הנושים נפרעו, והיא סעד מתון יותר מהרמת מסך.', true, 'זוהי התשובה הנכונה. סעיף 6(ג) לחוק החברות מאפשר הדחיית חוב, שהיא סעד מתון יותר מהרמת מסך, ומשמעותה השעיית זכותו של בעל מניה להיפרע מהחברה.', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_3, 'ג', 'הדחיית חוב חלה רק במקרים של חדלות פירעון, בעוד הרמת מסך חלה גם בחברה פעילה.', false, 'טענה זו אינה נכונה. הרמת מסך אינה מחייבת חדלות פירעון, והדחיית חוב רלוונטית בעיקר במצבי קושי כלכלי של החברה.', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_3, 'ד', 'הדחיית חוב היא סעד שנועד להגן על בעלי המניות, בעוד הרמת מסך נועדה להגן על נושים.', false, 'טענה זו אינה נכונה. הדחיית חוב, כמו הרמת מסך, נועדה להגן על נושי החברה, אך בדרך פחות דרסטית.', 4);

  RAISE NOTICE 'Q% inserted: external_id %', 24, '2022-S-S-Q24';
END
$$;

-- ============================================================
-- Q25 — 2022-S-S-Q25 — chapter=corporate subtopic=companies_formation
-- classifier_note: Shareholder Roni absent abroad, notice timing for general meeting — meeting procedure rules
-- ============================================================
DO $$
DECLARE
  v_sq_id uuid := '87b481cb-1a77-4a55-bf28-2ddfebec4df9'::uuid;
  v_group_id uuid := 'afb191af-e576-422b-b4cd-32f95403f1d3'::uuid;
  v_chapter_id uuid;
  v_subtopic_id uuid;
  v_existing_id uuid;
  v_ang_0 uuid := 'f3f3cbeb-dcd0-4042-8db5-40f1198cf195'::uuid;
  v_ang_1 uuid := 'cc345120-c032-4a3e-b02b-4ef8d7919b6c'::uuid;
  v_ang_2 uuid := '993ee14c-fe38-4bc5-aa38-c42714dad964'::uuid;
  v_ang_3 uuid := '7fc7320f-4eaa-45fd-a539-cfa2cf951517'::uuid;
BEGIN
  SELECT id INTO v_existing_id FROM public.source_questions WHERE external_id = '2022-S-S-Q25';
  IF v_existing_id IS NOT NULL THEN
    RAISE NOTICE 'Q% skipped: external_id % already exists', 25, '2022-S-S-Q25';
    RETURN;
  END IF;

  SELECT id INTO v_chapter_id FROM public.chapters WHERE code = 'corporate';
  IF v_chapter_id IS NULL THEN
    RAISE EXCEPTION 'Chapter code % not found', 'corporate';
  END IF;

  SELECT id INTO v_subtopic_id FROM public.subtopics WHERE code = 'companies_formation' AND chapter_id = v_chapter_id;
  IF v_subtopic_id IS NULL THEN
    RAISE EXCEPTION 'Subtopic code % not found under chapter %', 'companies_formation', 'corporate';
  END IF;

  INSERT INTO public.source_questions (
    id, question_group_id, version, is_current, external_id, chapter_id, subtopic_id, question_text, source_metadata, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list, notes_for_admin, status, created_by
  ) VALUES (
    v_sq_id, v_group_id, 1, true,
    '2022-S-S-Q25', v_chapter_id, v_subtopic_id, 'בחברה פרטית הוחלט לזמן את בעלי המניות לדיון של האסיפה הכללית שיתקיים בתאריך 18.8.2022. ההזמנות נמסרו לבעלי המניות ביום 1.8.2022, למעט בעל מניות אחד (רני) ששהה בחו"ל באותו המועד ועם שובו מחו"ל, ביום 15.8.2022, נמסרה לו ההזמנה. רני אמנם הגיע לאסיפה, ואולם נתקבלו בה כמה החלטות שהתנגד להן. רני מעוניין לעתור לבית המשפט בבקשה לבטל את אותן ההחלטות מהטעם שלא זומן לאסיפה במועד הנדרש לפי החוק וכי בשל ההתראה הקצרה שניתנה לו אף לא הספיק להתכונן כראוי לאסיפה. מה הדין?',
    '{"exam_year": 2022, "exam_season": "summer", "exam_part": 2, "exam_question_number": 25}'::jsonb, 'שאלה זו עוסקת בפגמים בזימון אסיפה כללית בחברה פרטית ובהשלכותיהם על תוקף ההחלטות שהתקבלו בה. היא מתמקדת בסעיפים 67 ו-91 לחוק החברות, תשנ"ט-1999, ובפרט בעקרון הוויתור על טענת פגם בזימון כאשר בעל המניות השתתף באסיפה, ובמבחן הקיפוח המהותי הנדרש לביטול החלטות.', 'הכלל הבסיסי בדיני חברות הוא שעל החברה לזמן את בעלי המניות לאסיפה כללית בהתאם להוראות החוק והתקנון. סעיף 67(א) לחוק החברות, תשנ"ט-1999, קובע כי זימון לאסיפה כללית יישלח לפחות 14 ימים לפני מועד האסיפה. במקרה הנדון, רני קיבל את ההזמנה ב-15.8.2022 לאסיפה שהתקיימה ב-18.8.2022, כלומר 3 ימים בלבד לפני האסיפה, וזהו פגם בזימון. סעיף 67(א) לחוק החברות, תשנ"ט-1999 | מועד הזימון עם זאת, סעיף 67(ב) לחוק החברות קובע חריג חשוב: "בעל מניה שהשתתף באסיפה כללית, רואים אותו כמי שויתר על טענת פגם בזימון האסיפה, אלא אם כן הודיע על התנגדותו לכינוס האסיפה בתחילת הדיון". סעיף 67(ב) לחוק החברות, תשנ"ט-1999 | מועד הזימון במקרה זה, רני אמנם זומן באיחור, אך הוא השתתף באסיפה ולא הודיע על התנגדותו לכינוסה בתחילת הדיון. לכן, רואים אותו כמי שויתר על טענת הפגם בזימון. ע"א 8489/12 פלוני נ'' פלוני (29.10.2013) הפסיקה מדגישה כי מטרת סעיף 67(ב) היא למנוע מבעלי מניות ''לשבת על הגדר'' ולטעון לפגם רק לאחר שההחלטות אינן לרוחם. דניאל פרידמן ונילי כהן חוזים כרך א (2018) | חזרה מהצעה לפיכך, רני אינו רשאי לדרוש את ביטול ההחלטות על בסיס הפגם בזימון. ע"א 8489/12 פלוני נ'' פלוני (29.10.2013)', 'הנחה שגויה כי כל פגם בזימון מוביל לביטול החלטות, מבלי להבחין בין מצב שבו בעל המניות השתתף באסיפה לבין מצב שבו לא השתתף, ומבלי להכיר בעקרון הוויתור המשתמע.',
    '["פגם בזימון", "אסיפה כללית", "סעיף 67 לחוק החברות", "ויתור על טענה", "תוקף החלטות", "דיני חברות"]'::jsonb, '**וריאציה 1 — פגם בזימון:** האם זימון 3 ימים מראש לאסיפה הוא פגם? ← כן, החוק דורש 14 ימים לפחות (סעיף 67(א) לחוק החברות).
**וריאציה 2 — השתתפות:** מה קורה אם בעל מניות השתתף באסיפה למרות פגם בזימון? ← רואים אותו כמי שויתר על טענת הפגם (סעיף 67(ב) לחוק החברות).
**וריאציה 3 — מטרת החוק:** מדוע החוק קובע ויתור כזה? ← למנוע מבעלי מניות ''לשבת על הגדר'' ולטעון לפגם רק בדיעבד (פרידמן וכהן).', 'פגם בזימון אסיפה כללית ← אם בעל המניות השתתף ולא התנגד ← רואים אותו כמי שויתר על טענת הפגם (סעיף 67(ב) לחוק החברות).', '["חוק החברות, תשנ\"ט-1999, סעיפים 67, 91", "ע\"א 8489/12 פלוני נ'' פלוני (29.10.2013)", "דניאל פרידמן ונילי כהן חוזים כרך א (2018) | חזרה מהצעה"]'::jsonb,
    'classification_review: original chapter=''סדר דין אזרחי'' subtopic=''הליכים'' → mapped chapter=''corporate'' subtopic=''companies_formation'' | classifier_note: Shareholder Roni absent abroad, notice timing for general meeting — meeting procedure rules | source_review_note: השאלה עוסקת בדיני חברות, שהם תחום מהותי במשפט האזרחי. בחרתי ב''הליכים'' תחת ''סדר דין אזרחי'' כהצבת מקום, מכיוון שהשאלה עוסקת בהליכים פנימיים בחברה וביכולת לעתור לבית המשפט. עם זאת, הנושא המרכזי הוא מהותי ואינו משתלב באופן מושלם באף אחד מתתי-הנושאים הסגורים הקיימים. יש לשקול הוספת פרק ''דיני חברות'' או תת-נושא רחב יותר תחת ''סדר דין אזרחי'' שיכלול נושאים מהותיים בעלי השלכות דיוניות.', 'active', 'b9ecdde2-d07e-4761-96ab-05f0ad32d4e3'
  );

  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'א', 'בית המשפט רשאי להורות על ביטול ההחלטות.', false, 'טענה זו אינה נכונה. השתתפותו של רני באסיפה, למרות הפגם בזימון, מונעת ממנו לטעון לביטול ההחלטות על בסיס פגם זה, אלא אם הוכח נזק מהותי שאינו ניתן לתיקון.', 1);
  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'ב', 'בית המשפט אינו רשאי להורות על ביטול בדיעבד של החלטות שקיבלה האסיפה הכללית.', false, 'טענה זו אינה נכונה. בית המשפט רשאי לבטל החלטות אסיפה כללית במקרים מסוימים, כגון פגם מהותי בזימון שגרם לקיפוח, אך לא במקרה זה בשל השתתפותו של רני.', 2);
  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'ג', 'בית המשפט רשאי להורות על ביטול ההחלטות, ובלבד שרני מחזיק לפחות 15% מההון המונפק של החברה.', false, 'טענה זו אינה נכונה. אחוז ההחזקה של רני אינו התנאי המכריע לביטול החלטות במקרה של פגם בזימון, במיוחד כאשר הוא השתתף באסיפה.', 3);
  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'ד', 'היות שרני השתתף באסיפה ומדובר בפגם שנוגע למועד כינוסה, רני אינו רשאי לדרוש את ביטולן של ההחלטות.', true, 'זוהי התשובה הנכונה. סעיף 67(ב) לחוק החברות קובע כי פגם בזימון אסיפה כללית אינו פוגע בתוקף ההחלטות שהתקבלו בה, אם בעל המניות השתתף באסיפה. הפסיקה מפרשת זאת כוויתור על טענת הפגם בזימון.', 4);

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_0, v_sq_id, 'א', 'פגם בזימון ללא השתתפות',
    1, 'בחברה פרטית הוחלט לזמן את בעלי המניות לאסיפה כללית. ההזמנות נמסרו לבעלי המניות ביום 1.8.2022, למעט בעל מניות אחד (רני) ששהה בחו"ל באותו המועד. עם שובו מחו"ל, ביום 15.8.2022, נמסרה לו ההזמנה. רני לא הספיק להתכונן כראוי לאסיפה ולכן לא השתתף בה. האסיפה התקיימה ב-18.8.2022 ונתקבלו בה החלטות מהותיות. רני מעוניין לעתור לבית המשפט בבקשה לבטל את ההחלטות. מה הדין?', 'שאלה זו בוחנת את ההשלכות של פגם בזימון אסיפה כללית כאשר בעל המניות לא השתתף בה. היא מדגישה את החשיבות של מבחן הקיפוח המהותי הקבוע בסעיף 91 לחוק החברות, כתנאי לביטול החלטות שהתקבלו באסיפה.', 'סעיף 67(א) לחוק החברות, תשנ"ט-1999, קובע את מועדי הזימון לאסיפה כללית. סעיף 91 לחוק החברות קובע כי "פגם בזימון אסיפה כללית, בכינוסה, בניהולה או בקבלת החלטות בה, לרבות פגם הנוגע לכינוס אסיפה כללית שלא כדין, לא יבטל החלטה שהתקבלה בה, אלא אם כן קבע בית המשפט כי הפגם גרם לקיפוח מהותי של בעל מניה". סעיף 91 לחוק החברות, תשנ"ט-1999 | פגם בזימון, בכינוס, בניהול או בקבלת החלטות במקרה זה, רני לא זומן כדין (קיבל את ההזמנה 3 ימים לפני האסיפה במקום 14 ימים לפחות לפי סעיף 67(א) לחוק החברות), ולא השתתף באסיפה. לכן, הוא לא ויתר על טענת הפגם. בית המשפט יבחן האם הפגם בזימון גרם לקיפוח מהותי של רני. אם רני יוכיח כי בשל ההתראה הקצרה לא הספיק להתכונן כראוי, וכי הדבר מנע ממנו להשפיע על ההחלטות או להגן על זכויותיו באופן מהותי, ייתכן שבית המשפט יורה על ביטול ההחלטות. ע"א 8489/12 פלוני נ'' פלוני (29.10.2013)',
    'הנחה שגויה כי כל פגם בזימון מוביל אוטומטית לביטול החלטות, מבלי להבחין בין פגם שגרם לקיפוח מהותי לבין פגם טכני.', '["פגם בזימון", "אסיפה כללית", "קיפוח מהותי", "סעיף 91 לחוק החברות", "ביטול החלטות"]'::jsonb, '**וריאציה 1 — פגם בזימון:** האם אי-זימון כדין מבטל החלטות אסיפה? ← לא אוטומטית, רק אם גרם לקיפוח מהותי (סעיף 91 לחוק החברות).
**וריאציה 2 — השתתפות:** מה קורה אם בעל מניות לא זומן כדין ולא השתתף? ← הוא יכול לטעון לקיפוח מהותי (סעיף 91 לחוק החברות).
**וריאציה 3 — נזק:** האם אי-הספקה להתכונן היא קיפוח מהותי? ← כן, אם הדבר מנע ממנו להשפיע על ההחלטות או להגן על זכויותיו באופן מהותי.', 'פגם בזימון ללא השתתפות ← ביטול החלטות מותנה בקיפוח מהותי (סעיף 91 לחוק החברות).',
    '["חוק החברות, תשנ\"ט-1999, סעיפים 67, 91", "ע\"א 8489/12 פלוני נ'' פלוני (29.10.2013)"]'::jsonb
  );
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_0, 'א', 'בית המשפט יבטל את ההחלטות רק אם רני יוכיח שהפגם בזימון גרם לו קיפוח מהותי.', true, 'זוהי התשובה הנכונה. לפי סעיף 91 לחוק החברות, פגם בזימון אינו מבטל החלטות אלא אם כן נגרם קיפוח מהותי לבעל המניות, ורני לא השתתף באסיפה ולכן לא ויתר על טענת הפגם.', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_0, 'ב', 'בית המשפט יבטל את ההחלטות באופן אוטומטי, שכן רני לא זומן כדין ולא השתתף באסיפה.', false, 'טענה זו אינה נכונה. ביטול החלטות אינו אוטומטי, אלא מותנה בהוכחת קיפוח מהותי, בהתאם לסעיף 91 לחוק החברות.', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_0, 'ג', 'בית המשפט לא יבטל את ההחלטות, שכן רני היה צריך לדאוג לזימונו מבעוד מועד.', false, 'טענה זו אינה נכונה. החובה לזמן כדין מוטלת על החברה, ושהייתו של רני בחו"ל אינה פוטרת את החברה מחובה זו.', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_0, 'ד', 'בית המשפט יבטל את ההחלטות רק אם רני מחזיק ברוב מניות החברה.', false, 'טענה זו אינה נכונה. סעיף 91 לחוק החברות אינו מתנה את ביטול ההחלטות באחוז החזקה מסוים, אלא בקיפוח מהותי.', 4);

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_1, v_sq_id, 'ב', 'מבחן המהותיות בפגמים בזימון',
    2, 'מהו המבחן המרכזי שבית המשפט מיישם כדי לקבוע האם פגם בזימון אסיפה כללית מצדיק את ביטול ההחלטות שהתקבלו בה?', 'שאלה זו מתמקדת במבחן המשפטי המרכזי לקביעת תוקפן של החלטות אסיפה כללית שנפלו בהן פגמים פרוצדורליים. היא מדגישה את חשיבותו של מבחן הקיפוח המהותי, כפי שמעוגן בסעיף 91 לחוק החברות, המאזן בין הצורך ביציבות החלטות החברה לבין הגנה על זכויות בעלי המניות.', 'סעיף 91 לחוק החברות, תשנ"ט-1999, קובע במפורש כי פגם בזימון אסיפה כללית, בכינוסה, בניהולה או בקבלת החלטות בה, לא יבטל החלטה שהתקבלה בה, "אלא אם כן קבע בית המשפט כי הפגם גרם לקיפוח מהותי של בעל מניה". סעיף 91 לחוק החברות, תשנ"ט-1999 | פגם בזימון, בכינוס, בניהול או בקבלת החלטות מבחן זה נועד לאזן בין הצורך ביציבות וודאות משפטית בהחלטות החברה לבין ההגנה על זכויות בעלי המניות. ע"א 8489/12 פלוני נ'' פלוני (29.10.2013) קיפוח מהותי אינו מתייחס רק לפגיעה כלכלית ישירה, אלא גם לפגיעה ביכולתו של בעל המניות להשפיע על ההחלטות, להציג את עמדתו, או להגן על זכויותיו באופן אפקטיבי. דניאל פרידמן ונילי כהן חוזים כרך א (2018) | חזרה מהצעה',
    'התמקדות בפגמים טכניים או פרוצדורליים בלבד, מבלי לבחון את השפעתם המהותית על זכויות בעלי המניות.', '["מבחן הקיפוח המהותי", "סעיף 91 לחוק החברות", "פגם בזימון", "אסיפה כללית", "יציבות החלטות", "הגנה על בעלי מניות"]'::jsonb, '**וריאציה 1 — מבחן מרכזי:** מהו המבחן המרכזי לביטול החלטות אסיפה בשל פגם בזימון? ← מבחן הקיפוח המהותי (סעיף 91 לחוק החברות).
**וריאציה 2 — מהות הקיפוח:** מה כולל קיפוח מהותי? ← לא רק נזק כלכלי, אלא גם פגיעה ביכולת להשפיע או להגן על זכויות (פרידמן וכהן).
**וריאציה 3 — איזון:** מה המבחן מנסה לאזן? ← יציבות החלטות החברה מול הגנה על זכויות בעלי המניות.', 'ביטול החלטות אסיפה בשל פגם בזימון ← רק אם נגרם קיפוח מהותי לבעל מניה (סעיף 91 לחוק החברות).',
    '["חוק החברות, תשנ\"ט-1999, סעיף 91", "ע\"א 8489/12 פלוני נ'' פלוני (29.10.2013)", "דניאל פרידמן ונילי כהן חוזים כרך א (2018) | חזרה מהצעה"]'::jsonb
  );
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_1, 'א', 'מבחן הקיפוח המהותי – האם הפגם גרם לקיפוח מהותי של בעל מניה.', true, 'זוהי התשובה הנכונה. סעיף 91 לחוק החברות קובע במפורש כי פגם בזימון לא יבטל החלטה אלא אם כן גרם לקיפוח מהותי של בעל מניה.', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_1, 'ב', 'מבחן תום הלב – האם הפגם נגרם בחוסר תום לב מצד החברה או הדירקטוריון.', false, 'טענה זו אינה נכונה. אף שתום לב הוא עקרון יסוד, המבחן הספציפי לביטול החלטות בשל פגם בזימון הוא מבחן הקיפוח המהותי, ולא רק חוסר תום לב.', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_1, 'ג', 'מבחן הסיבתיות – האם הפגם בזימון השפיע ישירות על תוצאות ההצבעה באסיפה.', false, 'טענה זו אינה נכונה. מבחן הקיפוח המהותי רחב יותר ממבחן סיבתיות ישירה לתוצאות ההצבעה, וכולל גם פגיעה ביכולת להשפיע או להגן על זכויות.', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_1, 'ד', 'מבחן אחוז ההחזקה – האם בעל המניה הנפגע מחזיק באחוז מסוים מהון המניות.', false, 'טענה זו אינה נכונה. אחוז ההחזקה אינו תנאי לביטול החלטות לפי סעיף 91 לחוק החברות.', 4);

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_2, v_sq_id, 'ג', 'ויתור מראש על זכות זימון',
    3, 'בעל מניות בחברה חתם על הסכם עם החברה, בו הוא מוותר מראש על זכותו לקבל הודעת זימון לאסיפות כלליות, ומסכים כי כל החלטה שתתקבל באסיפה תהיה תקפה כלפיו. האם ויתור כזה תקף?', 'שאלה זו עוסקת באפשרות של בעל מניות לוותר על זכויותיו הפרוצדורליות, ובפרט על זכות הזימון לאסיפה כללית. היא בוחנת את עקרון חופש החוזים אל מול הוראות חוק קוגנטיות, ומדגישה כי ויתור על זכות כזו אפשרי, כל עוד הוא נעשה מדעת ומרצון חופשי ואינו נוגד את תקנת הציבור.', 'הכלל הוא שבעל מניות רשאי לוותר על זכויותיו, לרבות זכויות פרוצדורליות כגון זכות הזימון לאסיפה כללית, ובלבד שהוויתור נעשה מדעת ומרצון חופשי, ואינו נוגד הוראת חוק קוגנטית או את תקנת הציבור. דניאל פרידמן ונילי כהן חוזים כרך א (2018) | חזרה מהצעה סעיף 67(ב) לחוק החברות, תשנ"ט-1999, קובע כי "בעל מניה שהשתתף באסיפה כללית, רואים אותו כמי שויתר על טענת פגם בזימון האסיפה, אלא אם כן הודיע על התנגדותו לכינוס האסיפה בתחילת הדיון". סעיף 67(ב) לחוק החברות, תשנ"ט-1999 | מועד הזימון הוראה זו מלמדת כי המחוקק מכיר באפשרות של ויתור על זכות הזימון, גם אם הוא משתמע מהתנהגות (השתתפות באסיפה). ויתור מפורש מראש, אם כן, יהיה תקף, כל עוד הוא עומד בעקרונות הכלליים של דיני החוזים והחברות. ע"א 8489/12 פלוני נ'' פלוני (29.10.2013)',
    'הנחה שגויה כי כל זכויות בעלי המניות הן קוגנטיות ואינן ניתנות לויתור, או אי-הבחנה בין ויתור מפורש לויתור משתמע.', '["ויתור על זכות", "זכות זימון", "אסיפה כללית", "חופש החוזים", "הוראה קוגנטית", "תקנת הציבור"]'::jsonb, '**וריאציה 1 — ויתור מפורש:** האם בעל מניות יכול לוותר מראש על זכות הזימון? ← כן, אם נעשה מדעת ומרצון חופשי ואינו נוגד חוק קוגנטי (פרידמן וכהן).
**וריאציה 2 — ויתור משתמע:** האם השתתפות באסיפה היא ויתור על פגם בזימון? ← כן, אלא אם הודיע על התנגדותו (סעיף 67(ב) לחוק החברות).
**וריאציה 3 — גבולות הוויתור:** מהם הגבולות לוויתור על זכויות? ← לא ינוגד חוק קוגנטי או תקנת הציבור.', 'בעל מניות רשאי לוותר על זכות הזימון לאסיפה, מפורשות או במשתמע, בכפוף לעקרונות דיני החוזים והחברות.',
    '["חוק החברות, תשנ\"ט-1999, סעיף 67", "ע\"א 8489/12 פלוני נ'' פלוני (29.10.2013)", "דניאל פרידמן ונילי כהן חוזים כרך א (2018) | חזרה מהצעה"]'::jsonb
  );
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_2, 'א', 'כן, בעל מניות רשאי לוותר על זכויותיו, ובלבד שהוויתור נעשה מדעת ומרצון חופשי.', true, 'זוהי התשובה הנכונה. בעל מניות רשאי לוותר על זכויותיו, כולל זכות הזימון, ובלבד שהוויתור נעשה מדעת ומרצון חופשי, ואינו נוגד את תקנת הציבור או הוראת חוק קוגנטית.', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_2, 'ב', 'לא, זכות הזימון לאסיפה כללית היא זכות קוגנטית שאינה ניתנת לויתור מראש.', false, 'טענה זו אינה נכונה. זכות הזימון אינה נחשבת לזכות קוגנטית שאינה ניתנת לויתור, אלא לזכות שניתן לוותר עליה, בכפוף לתנאים מסוימים.', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_2, 'ג', 'כן, אך רק אם הוויתור אושר על ידי כלל בעלי המניות האחרים בחברה.', false, 'טענה זו אינה נכונה. ויתור על זכות אישית אינו דורש אישור של בעלי מניות אחרים, אלא אם כן הוא משפיע על זכויותיהם.', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_2, 'ד', 'לא, מכיוון שוויתור מראש על זכות כזו פוגע בעקרון השוויון בין בעלי המניות.', false, 'טענה זו אינה נכונה. אף ששוויון הוא עקרון חשוב, ויתור על זכות אישית אינו פוגע בהכרח בעקרון השוויון, כל עוד הוא נעשה מדעת ומרצון חופשי.', 4);

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_3, v_sq_id, 'ד', 'סעד חלופי לביטול החלטה',
    4, 'בעל מניות נפגע מפגם בזימון אסיפה כללית, אך בית המשפט קבע כי הפגם אינו מהותי דיו כדי לבטל את ההחלטות שהתקבלו בה. האם עומד לרשותו סעד חלופי?', 'שאלה זו בוחנת את מגוון הסעדים העומדים לרשות בעל מניות שנפגע מפגם פרוצדורלי באסיפה כללית, כאשר בית המשפט אינו מוצא לנכון לבטל את ההחלטות. היא מדגישה את האפשרות לתבוע פיצויים בגין נזקים שנגרמו, כסעד חלופי או משלים לביטול ההחלטה.', 'גם אם בית המשפט קובע כי פגם בזימון אסיפה כללית אינו מהותי דיו כדי לבטל את ההחלטות שהתקבלו בה (בהתאם לסעיף 91 לחוק החברות), עדיין עשוי לעמוד לרשות בעל המניות שנפגע סעד חלופי. סעד זה יכול להיות תביעת פיצויים בגין נזקים שנגרמו לו כתוצאה מהפגם. ע"א 8489/12 פלוני נ'' פלוני (29.10.2013) הפסיקה הכירה באפשרות להעניק סעד של פיצויים במקרים בהם נגרם נזק לבעל מניות כתוצאה מהתנהלות לא תקינה של החברה, גם אם לא הוכח קיפוח מהותי המצדיק ביטול החלטה. דניאל פרידמן ונילי כהן חוזים כרך א (2018) | חזרה מהצעה סעד זה נועד להגן על בעל המניות מפני נזקים שנגרמו לו עקב הפרת חובות החברה כלפיו, גם אם ההפרה לא הגיעה לרמה של קיפוח מהותי המצדיק התערבות בהחלטות החברה. ע"א 8489/12 פלוני נ'' פלוני (29.10.2013)',
    'הנחה שגויה כי ביטול החלטה הוא הסעד היחיד האפשרי במקרה של פגם פרוצדורלי, מבלי לשקול סעדים כספיים.', '["סעד חלופי", "פיצויים", "פגם בזימון", "קיפוח מהותי", "חוק החברות", "הגנה על בעלי מניות"]'::jsonb, '**וריאציה 1 — סעד עיקרי:** מהו הסעד העיקרי לפגם בזימון אסיפה? ← ביטול ההחלטות, אם נגרם קיפוח מהותי (סעיף 91 לחוק החברות).
**וריאציה 2 — סעד חלופי:** אם אין ביטול, האם יש סעד אחר? ← כן, תביעת פיצויים בגין נזקים שנגרמו (ע"א 8489/12).
**וריאציה 3 — תנאי לפיצויים:** מה נדרש לתביעת פיצויים? ← הוכחת נזק שנגרם כתוצאה מהפגם, גם אם הפגם אינו מהותי לביטול ההחלטה.', 'פגם בזימון שאינו מצדיק ביטול החלטה ← עדיין יכול להקים זכות לפיצויים בגין נזקים שנגרמו.',
    '["חוק החברות, תשנ\"ט-1999, סעיף 91", "ע\"א 8489/12 פלוני נ'' פלוני (29.10.2013)", "דניאל פרידמן ונילי כהן חוזים כרך א (2018) | חזרה מהצעה"]'::jsonb
  );
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_3, 'א', 'לא, אם בית המשפט לא ביטל את ההחלטות, אין סעד אחר לבעל המניות.', false, 'טענה זו אינה נכונה. ייתכנו סעדים חלופיים גם אם ההחלטה עצמה לא בוטלה.', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_3, 'ב', 'כן, בעל המניות רשאי לתבוע פיצויים בגין נזקים שנגרמו לו כתוצאה מהפגם, גם אם ההחלטות נותרו בתוקף.', true, 'זוהי התשובה הנכונה. הפסיקה הכירה באפשרות של תביעת פיצויים בגין נזקים שנגרמו לבעל מניות כתוצאה מפגם, גם אם הפגם אינו מצדיק את ביטול ההחלטה.', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_3, 'ג', 'כן, בעל המניות רשאי לדרוש כינוס אסיפה כללית חדשה לדון מחדש באותן החלטות.', false, 'טענה זו אינה נכונה. כינוס אסיפה חדשה אינו סעד אוטומטי, ובמיוחד לא כאשר ההחלטות כבר נכנסו לתוקף.', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_3, 'ד', 'לא, אלא אם כן הפגם נגרם בזדון על ידי הדירקטוריון.', false, 'טענה זו אינה נכונה. תביעת פיצויים אינה מותנית בהוכחת זדון, אלא בנזק שנגרם כתוצאה מהפגם.', 4);

  RAISE NOTICE 'Q% inserted: external_id %', 25, '2022-S-S-Q25';
END
$$;

-- ============================================================
-- Q26 — 2022-S-S-Q26 — chapter=corporate subtopic=fiduciary_duties  [needs_review]
-- classifier_note: Auditor (רו"ח מבקרת) immediate termination by shareholders — closest subtopic is fiduciary_duties; auditor-removal procedure isn't dedicated
-- ============================================================
DO $$
DECLARE
  v_sq_id uuid := 'b0c7fcec-42d6-4857-b6ce-dd848781bad5'::uuid;
  v_group_id uuid := 'de1439b8-bc93-4b76-be42-1fa2e41c2218'::uuid;
  v_chapter_id uuid;
  v_subtopic_id uuid;
  v_existing_id uuid;
  v_ang_0 uuid := '6091255c-ac08-4533-b988-9f0923215409'::uuid;
  v_ang_1 uuid := '6eb40266-e92c-4a3d-888c-28ceb6d1e164'::uuid;
  v_ang_2 uuid := 'c324465e-caf4-42df-befa-48640efc9c0c'::uuid;
  v_ang_3 uuid := '6c53946a-93ef-41a7-9c29-4ed6bf043ccc'::uuid;
BEGIN
  SELECT id INTO v_existing_id FROM public.source_questions WHERE external_id = '2022-S-S-Q26';
  IF v_existing_id IS NOT NULL THEN
    RAISE NOTICE 'Q% skipped: external_id % already exists', 26, '2022-S-S-Q26';
    RETURN;
  END IF;

  SELECT id INTO v_chapter_id FROM public.chapters WHERE code = 'corporate';
  IF v_chapter_id IS NULL THEN
    RAISE EXCEPTION 'Chapter code % not found', 'corporate';
  END IF;

  SELECT id INTO v_subtopic_id FROM public.subtopics WHERE code = 'fiduciary_duties' AND chapter_id = v_chapter_id;
  IF v_subtopic_id IS NULL THEN
    RAISE EXCEPTION 'Subtopic code % not found under chapter %', 'fiduciary_duties', 'corporate';
  END IF;

  INSERT INTO public.source_questions (
    id, question_group_id, version, is_current, external_id, chapter_id, subtopic_id, question_text, source_metadata, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list, notes_for_admin, status, created_by
  ) VALUES (
    v_sq_id, v_group_id, 1, true,
    '2022-S-S-Q26', v_chapter_id, v_subtopic_id, 'רו"ח מליסה מכהנת כרואת חשבון מבקרת של חברה ציבורית. בעלי המניות בחברה החליטו לסיים את העסקתה בחברה באופן מיידי. מה הדין?',
    '{"exam_year": 2022, "exam_season": "summer", "exam_part": 2, "exam_question_number": 26}'::jsonb, 'שאלה זו עוסקת בסמכות האסיפה הכללית לסיים את כהונתו של רואה חשבון מבקר בחברה ציבורית, ובפרט בתנאים המיוחדים החלים על הליך זה. היא מתמקדת בסעיפים 57(3) ו-162 לחוק החברות, תשנ"ט-1999, המבחינים בין חברה פרטית לציבורית לעניין מעורבות ועדת הביקורת בהליך סיום הכהונה.', 'הסמכות למינוי רואה חשבון מבקר, תנאי העסקתו והפסקת העסקתו נתונה לאסיפה הכללית של החברה, כפי שקובע סעיף 57(3) לחוק החברות, תשנ"ט-1999. סעיף 57(3) לחוק החברות, תשנ"ט-1999 | הסמכויות המוקנות לאסיפה הכללית סעיף 162 לחוק החברות מפרט את הכללים לסיום כהונה זו. סעיף 162(א) קובע כי "האסיפה הכללית רשאית לסיים את כהונתו של רואה החשבון המבקר". סעיף 162(א) לחוק החברות, תשנ"ט-1999 | סיום כהונה אולם, כאשר מדובר בחברה ציבורית (או בחברה פרטית שהיא חברת איגרות חוב), סעיף 162(ב) מוסיף דרישה מיוחדת: "בחברה ציבורית או בחברה פרטית שהיא חברת איגרות חוב שעל סדר יומה סיום כהונתו של רואה חשבון מבקר או אי חידוש הכהונה, תובא עמדתה של ועדת הביקורת בפני האסיפה הכללית, לאחר שנתנה לרואה החשבון המבקר הזדמנות סבירה להביא את עמדתו בפניה". סעיף 162(ב) לחוק החברות, תשנ"ט-1999 | סיום כהונה במקרה של רו"ח מליסה, המכהנת בחברה ציבורית, האסיפה הכללית אכן מוסמכת לסיים את העסקתה, אך זאת רק לאחר שוועדת הביקורת תמסור את עמדתה לאסיפה, וזאת לאחר שניתנה למליסה הזדמנות סבירה להציג את עמדתה בפני הוועדה. ת"א (מחוזי מרכז) 57041-12-17 רחמים נגר נ'' וואן שירותי תוכנה (1997) בע"מ (04.05.2025)', 'התעלמות מהדרישות הפרוצדורליות המיוחדות החלות על חברות ציבוריות בעת סיום כהונת רואה חשבון מבקר, ובפרט תפקידה של ועדת הביקורת וחובת השימוע.',
    '["רואה חשבון מבקר", "חברה ציבורית", "אסיפה כללית", "ועדת ביקורת", "סיום כהונה", "חובת שימוע", "חוק החברות"]'::jsonb, '**וריאציה 1 — סמכות סיום:** מי מוסמך לסיים כהונת רואה חשבון מבקר בחברה ציבורית? ← האסיפה הכללית (סעיף 57(3) ו-162(א) לחוק החברות).
**וריאציה 2 — תנאי מיוחד:** מהו התנאי המיוחד לסיום כהונה בחברה ציבורית? ← הבאת עמדת ועדת הביקורת לאסיפה, לאחר שימוע לרואה החשבון (סעיף 162(ב) לחוק החברות).
**וריאציה 3 — חשיבות התנאי:** מדוע קיים תנאי זה? ← להבטיח הליך הוגן ושקול, ולהגן על עצמאות רואה החשבון המבקר.', 'בחברה ציבורית, האסיפה הכללית רשאית לסיים כהונת רואה חשבון מבקר, אך רק לאחר שוועדת הביקורת הציגה את עמדתה לאסיפה, וזאת לאחר שימוע לרואה החשבון.', '["חוק החברות, תשנ\"ט-1999, סעיפים 57, 162", "ת\"א (מחוזי מרכז) 57041-12-17 רחמים נגר נ'' וואן שירותי תוכנה (1997) בע\"מ (04.05.2025)"]'::jsonb,
    'needs_review=true | classification_review: original chapter=''סדר דין אזרחי'' subtopic=''הליכים'' → mapped chapter=''corporate'' subtopic=''fiduciary_duties'' | classifier_note: Auditor (רו"ח מבקרת) immediate termination by shareholders — closest subtopic is fiduciary_duties; auditor-removal procedure isn''t dedicated | source_review_note: השאלה עוסקת בדיני חברות, שהם תחום מהותי במשפט האזרחי. בחרתי ב''הליכים'' תחת ''סדר דין אזרחי'' כהצבת מקום, מכיוון שהשאלה עוסקת בהליכים פנימיים בחברה וביכולת לעתור לבית המשפט. עם זאת, הנושא המרכזי הוא מהותי ואינו משתלב באופן מושלם באף אחד מתתי-הנושאים הסגורים הקיימים. יש לשקול הוספת פרק ''דיני חברות'' או תת-נושא רחב יותר תחת ''סדר דין אזרחי'' שיכלול נושאים מהותיים בעלי השלכות דיוניות.', 'active', 'b9ecdde2-d07e-4761-96ab-05f0ad32d4e3'
  );

  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'א', 'ככלל, לאסיפה הכללית לא נתונה הסמכות לקבל החלטה בדבר סיום העסקתה של מליסה.', false, 'טענה זו אינה נכונה. הסמכות לסיים את כהונתו של רואה חשבון מבקר נתונה לאסיפה הכללית, כפי שקובע סעיף 162(א) לחוק החברות.', 1);
  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'ב', 'לאסיפה הכללית נתונה הסמכות לקבל החלטה בדבר סיום העסקתה של מליסה במקרה שבו ניתנה למליסה הזדמנות להופיע לשימוע בפני ועדת הביקורת, וזו מסרה את עמדתה בעניין לאסיפה הכללית.', true, 'זוהי התשובה הנכונה. סעיף 162(ב) לחוק החברות קובע כי בחברה ציבורית, סיום כהונת רואה חשבון מבקר טעון הבאת עמדת ועדת הביקורת בפני האסיפה הכללית, לאחר שניתנה לרואה החשבון הזדמנות סבירה להביא את עמדתו בפניה.', 2);
  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'ג', 'לאסיפה הכללית לא נתונה הסמכות לקבל החלטה בדבר סיום העסקתה של מליסה למעט במקרה שבו דירקטוריון החברה נמנע מלקבל החלטה כאמור.', false, 'טענה זו אינה נכונה. הסמכות לסיים כהונת רואה חשבון מבקר נתונה לאסיפה הכללית, ולא לדירקטוריון, ואינה תלויה בהימנעות הדירקטוריון מפעולה.', 3);
  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'ד', 'לאסיפה הכללית נתונה הסמכות לקבל החלטה בדבר סיום העסקתה של מליסה, ובלבד שקודם לכן אושר הדבר גם על ידי דירקטוריון החברה.', false, 'טענה זו אינה נכונה. בחברה ציבורית, נדרשת עמדת ועדת הביקורת, ולא אישור הדירקטוריון, כתנאי לסיום כהונת רואה חשבון מבקר על ידי האסיפה הכללית.', 4);

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_0, v_sq_id, 'א', 'סיום כהונת רואה חשבון בחברה פרטית',
    1, 'רו"ח דוד מכהן כרואה חשבון מבקר של חברה פרטית. בעלי המניות בחברה החליטו לסיים את העסקתו בחברה באופן מיידי. מה הדין?', 'שאלה זו בוחנת את ההבדל בין סיום כהונת רואה חשבון מבקר בחברה ציבורית לבין חברה פרטית. היא מדגישה כי הדרישה להבאת עמדת ועדת הביקורת בפני האסיפה הכללית, הקבועה בסעיף 162(ב) לחוק החברות, חלה רק על חברות ציבוריות או חברות איגרות חוב, ולא על חברות פרטיות רגילות.', 'סעיף 162(א) לחוק החברות, תשנ"ט-1999, קובע באופן כללי כי "האסיפה הכללית רשאית לסיים את כהונתו של רואה החשבון המבקר". סעיף 162(א) לחוק החברות, תשנ"ט-1999 | סיום כהונה סעיף 162(ב) מוסיף דרישה מיוחדת: "בחברה ציבורית או בחברה פרטית שהיא חברת איגרות חוב שעל סדר יומה סיום כהונתו של רואה חשבון מבקר או אי חידוש הכהונה, תובא עמדתה של ועדת הביקורת בפני האסיפה הכללית, לאחר שנתנה לרואה החשבון המבקר הזדמנות סבירה להביא את עמדתו בפניה". סעיף 162(ב) לחוק החברות, תשנ"ט-1999 | סיום כהונה מכיוון שהשאלה עוסקת בחברה פרטית שאינה חברת איגרות חוב, הדרישה המיוחדת שבסעיף 162(ב) אינה חלה. לכן, האסיפה הכללית של החברה הפרטית מוסמכת לסיים את כהונת רואה החשבון המבקר ללא צורך בהתייעצות עם ועדת ביקורת. ת"א (מחוזי מרכז) 57041-12-17 רחמים נגר נ'' וואן שירותי תוכנה (1997) בע"מ (04.05.2025)',
    'הכללת הדרישות המיוחדות החלות על חברות ציבוריות גם על חברות פרטיות, מבלי להבחין בין סוגי החברות.', '["רואה חשבון מבקר", "חברה פרטית", "חברה ציבורית", "אסיפה כללית", "סיום כהונה", "חוק החברות"]'::jsonb, '**וריאציה 1 — סמכות כללית:** מי מוסמך לסיים כהונת רואה חשבון מבקר? ← האסיפה הכללית (סעיף 162(א) לחוק החברות).
**וריאציה 2 — חברה פרטית:** האם בחברה פרטית נדרשת ועדת ביקורת לסיום כהונת רואה חשבון? ← לא, הדרישה בסעיף 162(ב) חלה רק על חברות ציבוריות או חברות איגרות חוב.
**וריאציה 3 — תנאים:** מהם התנאים לסיום כהונת רואה חשבון בחברה פרטית? ← החלטת האסיפה הכללית בלבד, ללא תנאים נוספים הקבועים בסעיף 162(ב).', 'בחברה פרטית, האסיפה הכללית מוסמכת לסיים כהונת רואה חשבון מבקר ללא מעורבות ועדת ביקורת.',
    '["חוק החברות, תשנ\"ט-1999, סעיף 162", "ת\"א (מחוזי מרכז) 57041-12-17 רחמים נגר נ'' וואן שירותי תוכנה (1997) בע\"מ (04.05.2025)"]'::jsonb
  );
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_0, 'א', 'לאסיפה הכללית נתונה הסמכות לסיים את כהונתו של רואה החשבון המבקר, ללא צורך בהתייעצות עם ועדת ביקורת.', true, 'זוהי התשובה הנכונה. סעיף 162(א) לחוק החברות מקנה לאסיפה הכללית סמכות לסיים את כהונת רואה החשבון המבקר. סעיף 162(ב), הדורש התייעצות עם ועדת ביקורת, חל רק על חברות ציבוריות או חברות איגרות חוב.', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_0, 'ב', 'החלטה כזו טעונה אישור של דירקטוריון החברה, ורק לאחר מכן תוכל האסיפה הכללית לאשרה.', false, 'טענה זו אינה נכונה. הסמכות לסיים כהונת רואה חשבון מבקר נתונה לאסיפה הכללית, ואינה טעונה אישור מוקדם של הדירקטוריון.', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_0, 'ג', 'החלטה כזו טעונה אישור של ועדת הביקורת של החברה, ורק לאחר מכן תוכל האסיפה הכללית לאשרה.', false, 'טענה זו אינה נכונה. הדרישה להתייעצות עם ועדת ביקורת חלה רק על חברות ציבוריות או חברות איגרות חוב, ולא על חברה פרטית רגילה.', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_0, 'ד', 'לא ניתן לסיים את כהונתו של רואה חשבון מבקר בחברה פרטית לפני תום תקופת כהונתו.', false, 'טענה זו אינה נכונה. האסיפה הכללית רשאית לסיים את כהונת רואה החשבון המבקר בכל עת, בכפוף להוראות החוק.', 4);

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_1, v_sq_id, 'ב', 'הזדמנות סבירה לרואה החשבון',
    2, 'מה כוללת הדרישה ל"הזדמנות סבירה להביא את עמדתו" של רואה החשבון המבקר בפני ועדת הביקורת, לפי סעיף 162(ב) לחוק החברות?', 'שאלה זו מתמקדת בפרשנות המונח ''הזדמנות סבירה להביא את עמדתו'' בהקשר של סיום כהונת רואה חשבון מבקר בחברה ציבורית. היא מדגישה את עקרונות השימוע ההוגן, הכוללים את הזכות לדעת את הטענות, להגיב עליהן, ולהציג את עמדתו באופן אפקטיבי, כחלק מהגנה על זכויותיו של רואה החשבון.', 'הדרישה ל"הזדמנות סבירה להביא את עמדתו" של רואה החשבון המבקר בפני ועדת הביקורת, הקבועה בסעיף 162(ב) לחוק החברות, משקפת את עקרונות השימוע ההוגן. עקרונות אלו כוללים את הזכות של רואה החשבון לקבל הודעה מפורטת על הטענות נגדו, הזכות להופיע בפני ועדת הביקורת, להציג את טיעוניו, להגיש מסמכים רלוונטיים, ולהשיב לשאלות. בש"א (מחוזי תל אביב-יפו) 25541/06 פרופ'' גדעון דורון נ'' אנשל אשכנזי (19.12.2006) מטרת השימוע היא לאפשר לרואה החשבון להתגונן ביעילות ולשכנע את הוועדה שלא לסיים את כהונתו, או לפחות להציג את עמדתו באופן מלא לפני שהוועדה מגבשת את המלצתה לאסיפה הכללית. סעיף 162(ב) לחוק החברות, תשנ"ט-1999 | סיום כהונה',
    'הבנה מצומצמת של המונח ''הזדמנות סבירה'' כהליך פורמלי בלבד, מבלי להתייחס למהות הזכות להתגונן.', '["הזדמנות סבירה", "שימוע הוגן", "ועדת ביקורת", "רואה חשבון מבקר", "חוק החברות", "זכות התגוננות"]'::jsonb, '**וריאציה 1 — מהות השימוע:** מהי ''הזדמנות סבירה'' לרואה חשבון? ← הזכות לדעת טענות, להגיב, להציג מסמכים ולהופיע (בש"א (מחוזי תל אביב-יפו) 25541/06).
**וריאציה 2 — מטרת השימוע:** למה נועד השימוע? ← לאפשר לרואה החשבון להתגונן ביעילות לפני גיבוש המלצת הוועדה (סעיף 162(ב) לחוק החברות).
**וריאציה 3 — היקף:** האם מספיק להגיש מסמכים בכתב? ← לרוב לא, נדרשת גם אפשרות להופיע בעל פה.', 'הזדמנות סבירה לרואה חשבון ← כוללת שימוע הוגן ← זכות לדעת טענות, להגיב, להציג עמדה (סעיף 162(ב) לחוק החברות).',
    '["חוק החברות, תשנ\"ט-1999, סעיף 162", "בש\"א (מחוזי תל אביב-יפו) 25541/06 פרופ'' גדעון דורון נ'' אנשל אשכנזי (19.12.2006)"]'::jsonb
  );
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_1, 'א', 'הזכות להופיע בפני הוועדה, להציג מסמכים, ולהשיב לשאלות, וכן לקבל הודעה מפורטת על הטענות נגדו מראש.', true, 'זוהי התשובה הנכונה. ''הזדמנות סבירה'' כוללת את עקרונות השימוע ההוגן, המאפשרים לרואה החשבון להתגונן ביעילות.', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_1, 'ב', 'הזכות להגיש מסמכים בכתב בלבד, ללא צורך בהופעה אישית בפני הוועדה.', false, 'טענה זו אינה נכונה. ''הזדמנות סבירה'' לרוב כוללת גם זכות להופיע ולהציג את העמדה בעל פה, ולא רק בכתב.', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_1, 'ג', 'הזכות לקבל את החלטת הוועדה בכתב, אך לא את נימוקיה.', false, 'טענה זו אינה נכונה. ''הזדמנות סבירה'' מתייחסת לשלב שלפני קבלת ההחלטה, וכוללת את היכולת להתגונן, ולא רק קבלת ההחלטה עצמה.', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_1, 'ד', 'הזכות לערער על החלטת הוועדה בפני האסיפה הכללית, אך לא בפני בית המשפט.', false, 'טענה זו אינה נכונה. ''הזדמנות סבירה'' מתייחסת להליך השימוע עצמו, ולא לאפשרויות ערעור לאחר קבלת ההחלטה.', 4);

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_2, v_sq_id, 'ג', 'מינוי רואה חשבון מבקר',
    3, 'מי מוסמך למנות רואה חשבון מבקר לחברה, ומהי תקופת כהונתו?', 'שאלה זו עוסקת בסמכות המינוי של רואה חשבון מבקר בחברה ובתקופת כהונתו, כפי שנקבע בחוק החברות. היא מדגישה את תפקידה המרכזי של האסיפה הכללית בעניין זה, ואת העיקרון של מינוי שנתי.', 'סעיף 57(3) לחוק החברות, תשנ"ט-1999, קובע כי "החלטות החברה בענינים האלה יתקבלו באסיפה הכללית: ... (3) מינוי רואה החשבון המבקר של החברה, תנאי העסקתו והפסקת העסקתו בהתאם להוראות סעיפים 154 עד 167". סעיף 57(3) לחוק החברות, תשנ"ט-1999 | הסמכויות המוקנות לאסיפה הכללית כלומר, הסמכות למנות רואה חשבון מבקר נתונה לאסיפה הכללית. אשר לתקופת כהונתו, סעיף 154(ב) לחוק החברות קובע כי "רואה חשבון מבקר יתמנה בכל אסיפה שנתית וישמש בתפקידו עד תום האסיפה השנתית שלאחריה". ת"א (מחוזי י-ם) 34835-01-16 יצחק לוי נ'' מיכה לוי (07.01.2021) מכאן, שרואה חשבון מבקר ממונה על ידי האסיפה הכללית וכהונתו היא לשנה אחת, עד לאסיפה השנתית הבאה.',
    'בלבול בין סמכויות האורגנים השונים בחברה (אסיפה כללית, דירקטוריון, ועדת ביקורת) בנוגע למינוי רואה חשבון מבקר.', '["רואה חשבון מבקר", "אסיפה כללית", "סמכות מינוי", "תקופת כהונה", "חוק החברות", "אסיפה שנתית"]'::jsonb, '**וריאציה 1 — מינוי:** מי ממנה רואה חשבון מבקר? ← האסיפה הכללית (סעיף 57(3) לחוק החברות).
**וריאציה 2 — תקופת כהונה:** כמה זמן מכהן רואה חשבון מבקר? ← עד תום האסיפה השנתית שלאחריה (סעיף 154(ב) לחוק החברות).
**וריאציה 3 — סיום כהונה:** האם ניתן לסיים כהונה לפני תום התקופה? ← כן, על ידי האסיפה הכללית (סעיף 162(א) לחוק החברות).', 'רואה חשבון מבקר ממונה על ידי האסיפה הכללית לכהונה שנתית, וניתן לסיים את כהונתו על ידי האסיפה.',
    '["חוק החברות, תשנ\"ט-1999, סעיפים 57, 154, 162", "ת\"א (מחוזי י-ם) 34835-01-16 יצחק לוי נ'' מיכה לוי (07.01.2021)"]'::jsonb
  );
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_2, 'א', 'הדירקטוריון מוסמך למנות רואה חשבון מבקר, וכהונתו היא לשנה אחת.', false, 'טענה זו אינה נכונה. הסמכות למינוי רואה חשבון מבקר נתונה לאסיפה הכללית, ולא לדירקטוריון.', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_2, 'ב', 'האסיפה הכללית מוסמכת למנות רואה חשבון מבקר, וכהונתו היא עד תום האסיפה השנתית שלאחריה.', true, 'זוהי התשובה הנכונה. סעיף 57(3) לחוק החברות קובע כי מינוי רואה חשבון מבקר הוא בסמכות האסיפה הכללית, וסעיף 154(ב) קובע את תקופת כהונתו.', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_2, 'ג', 'ועדת הביקורת מוסמכת למנות רואה חשבון מבקר, וכהונתו היא לשלוש שנים.', false, 'טענה זו אינה נכונה. ועדת הביקורת אינה מוסמכת למנות רואה חשבון מבקר, ואין קביעה גורפת לתקופת כהונה של שלוש שנים.', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_2, 'ד', 'בעל השליטה בחברה מוסמך למנות רואה חשבון מבקר, וכהונתו היא ללא הגבלת זמן.', false, 'טענה זו אינה נכונה. מינוי רואה חשבון מבקר הוא בסמכות האסיפה הכללית, ולא בסמכות בעל השליטה באופן ישיר, וכהונתו מוגבלת בזמן.', 4);

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_3, v_sq_id, 'ד', 'התערבות בית המשפט בהחלטות אסיפה כללית',
    4, 'באילו נסיבות רשאי בית המשפט להתערב בהחלטה של אסיפה כללית לסיים את כהונתו של רואה חשבון מבקר?', 'שאלה זו עוסקת בגבולות התערבותו של בית המשפט בהחלטות אסיפה כללית, ובפרט בהחלטות הנוגעות לסיום כהונת רואה חשבון מבקר. היא מדגישה את האיזון העדין בין עקרון אי-ההתערבות בענייני ניהול פנימי של חברה לבין הצורך להגן על זכויות בעלי מניות ועל תקינות ההליכים התאגידיים.', 'בית המשפט אינו נוטה להתערב בהחלטות אסיפה כללית, מתוך כיבוד עקרון האוטונומיה התאגידית. עם זאת, התערבות כזו אפשרית במקרים חריגים וקיצוניים, כגון כאשר ההחלטה התקבלה בחוסר סמכות, בניגוד לחוק, או כאשר היא גורמת לקיפוח מהותי של בעל מניות. ת"א (מחוזי י-ם) 34835-01-16 יצחק לוי נ'' מיכה לוי (07.01.2021) סעיף 91 לחוק החברות קובע כי פגם בזימון, בכינוס, בניהול או בקבלת החלטות באסיפה כללית לא יבטל החלטה, אלא אם כן קבע בית המשפט כי הפגם גרם לקיפוח מהותי של בעל מניה. סעיף 91 לחוק החברות, תשנ"ט-1999 | פגם בזימון, בכינוס, בניהול או בקבלת החלטות בנוסף, בית המשפט יכול להתערב מכוח סמכויותיו הכלליות לפי סעיף 191 לחוק החברות, המאפשר לו לתת הוראות שונות במקרים של קיפוח בעלי מניות. ת"א (מחוזי חיפה) 4806-06-22 פנדה יישומי מסחר בע"מ נ'' מאור להב (18.09.2023)',
    'הנחה שגויה כי בית המשפט יתערב בקלות בהחלטות אסיפה כללית, או לחלופין, כי אין לו כל סמכות להתערב.', '["התערבות בית המשפט", "אסיפה כללית", "קיפוח מהותי", "חוסר סמכות", "אי-חוקיות", "סעיף 91 לחוק החברות", "סעיף 191 לחוק החברות"]'::jsonb, '**וריאציה 1 — עקרון יסוד:** האם בית המשפט מתערב בקלות בהחלטות אסיפה כללית? ← לא, מתוך כיבוד אוטונומיה תאגידית (ת"א (מחוזי י-ם) 34835-01-16).
**וריאציה 2 — עילות התערבות:** מתי בית המשפט יתערב? ← חוסר סמכות, אי-חוקיות, או קיפוח מהותי (סעיף 91 לחוק החברות).
**וריאציה 3 — סמכויות:** אילו סמכויות יש לבית המשפט? ← סמכויות נרחבות לפי סעיף 191 לחוק החברות, כולל מתן הוראות שונות.', 'בית המשפט יתערב בהחלטות אסיפה כללית רק במקרים חריגים של חוסר סמכות, אי-חוקיות או קיפוח מהותי.',
    '["חוק החברות, תשנ\"ט-1999, סעיפים 91, 191", "ת\"א (מחוזי י-ם) 34835-01-16 יצחק לוי נ'' מיכה לוי (07.01.2021)", "ת\"א (מחוזי חיפה) 4806-06-22 פנדה יישומי מסחר בע\"מ נ'' מאור להב (18.09.2023)"]'::jsonb
  );
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_3, 'א', 'בית המשפט יתערב רק אם ההחלטה התקבלה בחוסר סמכות או בניגוד לחוק, או אם נגרם קיפוח מהותי לרואה החשבון או לבעלי המניות.', true, 'זוהי התשובה הנכונה. בית המשפט מתערב בהחלטות אסיפה כללית במקרים חריגים של חוסר סמכות, אי-חוקיות, או קיפוח מהותי, תוך איזון בין עקרון אי-ההתערבות לבין הצורך בהגנה על זכויות.', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_3, 'ב', 'בית המשפט יתערב בכל מקרה שבו רואה החשבון המבקר מתנגד לסיום כהונתו.', false, 'טענה זו אינה נכונה. התנגדות רואה החשבון לבדה אינה עילה להתערבות בית המשפט, אלא אם היא מבוססת על פגם מהותי בהליך או קיפוח.', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_3, 'ג', 'בית המשפט יתערב רק אם ההחלטה פוגעת בטובת החברה באופן כלכלי משמעותי.', false, 'טענה זו אינה נכונה. פגיעה בטובת החברה היא שיקול, אך בית המשפט מתערב גם מטעמים של פגמים פרוצדורליים או קיפוח, גם אם לא הוכחה פגיעה כלכלית ישירה.', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_3, 'ד', 'בית המשפט אינו רשאי להתערב בהחלטות אסיפה כללית, שכן זו סמכותה הבלעדית של האסיפה.', false, 'טענה זו אינה נכונה. עקרון אי-ההתערבות אינו מוחלט, ובית המשפט רשאי להתערב במקרים חריגים, כפי שנקבע בפסיקה ובחוק החברות (למשל, סעיף 91).', 4);

  RAISE NOTICE 'Q% inserted: external_id %', 26, '2022-S-S-Q26';
END
$$;

-- ============================================================
-- Q27 — 2022-S-S-Q27 — chapter=corporate subtopic=fiduciary_duties
-- classifier_note: Profit test + solvency test for distributions — directors' duties under חוק החברות
-- ============================================================
DO $$
DECLARE
  v_sq_id uuid := '01d33c27-d99f-4970-aac2-43bc75035f54'::uuid;
  v_group_id uuid := 'ceb727ec-d33d-4463-8980-28a7dad4c651'::uuid;
  v_chapter_id uuid;
  v_subtopic_id uuid;
  v_existing_id uuid;
  v_ang_0 uuid := 'f4b1b8e0-1c68-4f9c-a429-89611e3ea296'::uuid;
  v_ang_1 uuid := 'ad73461d-615f-414b-9c06-4e7a1ef01ec1'::uuid;
  v_ang_2 uuid := 'e6598389-4dd2-45ce-9e5c-d3f5cad91102'::uuid;
  v_ang_3 uuid := '97b1d355-5452-4bd6-a130-37008e3da9c6'::uuid;
BEGIN
  SELECT id INTO v_existing_id FROM public.source_questions WHERE external_id = '2022-S-S-Q27';
  IF v_existing_id IS NOT NULL THEN
    RAISE NOTICE 'Q% skipped: external_id % already exists', 27, '2022-S-S-Q27';
    RETURN;
  END IF;

  SELECT id INTO v_chapter_id FROM public.chapters WHERE code = 'corporate';
  IF v_chapter_id IS NULL THEN
    RAISE EXCEPTION 'Chapter code % not found', 'corporate';
  END IF;

  SELECT id INTO v_subtopic_id FROM public.subtopics WHERE code = 'fiduciary_duties' AND chapter_id = v_chapter_id;
  IF v_subtopic_id IS NULL THEN
    RAISE EXCEPTION 'Subtopic code % not found under chapter %', 'fiduciary_duties', 'corporate';
  END IF;

  INSERT INTO public.source_questions (
    id, question_group_id, version, is_current, external_id, chapter_id, subtopic_id, question_text, source_metadata, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list, notes_for_admin, status, created_by
  ) VALUES (
    v_sq_id, v_group_id, 1, true,
    '2022-S-S-Q27', v_chapter_id, v_subtopic_id, 'איזה מההיגדים הבאים מתאר נכונה את מהותם של מבחן הרווח ומבחן יכולת הפירעון?',
    '{"exam_year": 2022, "exam_season": "summer", "exam_part": 2, "exam_question_number": 27}'::jsonb, 'שאלה זו עוסקת בהבחנה המהותית בין שני המבחנים העיקריים לחלוקת דיבידנד בחברה: מבחן הרווח ומבחן יכולת הפירעון, כפי שמעוגנים בסעיפים 302 ו-303 לחוק החברות, תשנ"ט-1999. היא מדגישה את אופיים השונה של המבחנים (טכני מול מהותי, צופה עבר מול צופה עתיד) ואת חשיבותו העליונה של מבחן יכולת הפירעון בהגנה על נושי החברה.', 'סעיף 302(א) לחוק החברות, תשנ"ט-1999, קובע שני מבחנים מצטברים לצורך חלוקת דיבידנד מותרת: מבחן הרווח ומבחן יכולת הפירעון. הפסיקה, ובפרט פסק הדין בעניין ע"א 1734/21 אמיר ברוט נ'' חברת השקעות דיסקונט בע"מ (27.04.2023), הבהירה את מהותם: מבחן הרווח הוא מבחן טכני, חשבונאי, צופה פני עבר, שאינו כרוך בהפעלת שיקול דעת מהותי, ובגדרו נבחנת יתרת העודפים של החברה כפי שבא לידי ביטוי בדוחות הכספיים המותאמים האחרונים. ע"א 1734/21 אמיר ברוט נ'' חברת השקעות דיסקונט בע"מ (27.04.2023) לעומת זאת, מבחן יכולת הפירעון הוא המבחן העיקרי והמהותי, כלכלי, צופה פני עתיד, המצריך הפעלת שיקול דעת וניתוח נתונים ותחזיות באשר ליכולתה של החברה לעמוד בהתחייבויותיה הקיימות והצפויות. ע"א 1734/21 אמיר ברוט נ'' חברת השקעות דיסקונט בע"מ (27.04.2023) מבחן יכולת הפירעון הוא מבחן הסתברותי הבוחן את קיומו או העדרו של חשש סביר לאי-קיום התחייבויות החברה כתוצאה מהחלוקה. ת"א (מחוזי תל אביב-יפו) 46948-11-21 פסגות קרנות נאמנות בע"מ נ'' משרד המשפטים - רשם החברות (04.04.2022)', 'בלבול בין אופיים של שני המבחנים, או אי-הבנה של חשיבותו העליונה של מבחן יכולת הפירעון כהגנה על נושי החברה.',
    '["מבחן הרווח", "מבחן יכולת הפירעון", "חלוקת דיבידנד", "חוק החברות", "מבחן טכני", "מבחן מהותי", "צופה פני עבר", "צופה פני עתיד"]'::jsonb, '**וריאציה 1 — מבחן הרווח:** מהו מבחן הרווח? ← מבחן חשבונאי-טכני, צופה פני עבר, אינדיקטיבי (ע"א 1734/21).
**וריאציה 2 — מבחן יכולת הפירעון:** מהו מבחן יכולת הפירעון? ← מבחן כלכלי מהותי, צופה פני עתיד, הסתברותי, עיקרי (ע"א 1734/21).
**וריאציה 3 — יחס בין המבחנים:** איזה מבחן הוא העיקרי? ← מבחן יכולת הפירעון הוא העיקרי, מבחן הרווח משני (תנ"ג (כלכלית) 47621-07-16).', 'מבחן הרווח ← טכני, עבר, משני. מבחן יכולת הפירעון ← מהותי, עתיד, עיקרי.', '["חוק החברות, תשנ\"ט-1999, סעיפים 302, 303", "ע\"א 1734/21 אמיר ברוט נ'' חברת השקעות דיסקונט בע\"מ (27.04.2023)", "תנ\"ג (כלכלית ) 47621-07-16 אמוץ חורב נ'' בי קומיוניקיישנס בע\"מ (18.07.2019)", "ת\"א (כלכלית ) 48631-06-17 סאני תקשורת סלולרית בע\"מ נ'' אילן בן דב (22.03.2021)", "פר\"ק (מחוזי ת\"א) 3421-01-15 עו\"ד רענן קליר מתוקף תפקידו על-פי סעיף 17 להסדר הנושים למיצוי זכויות של החברה והנושים נ'' ד\"ר שמחה סדן (17.12.2016)", "ת\"א (מחוזי תל אביב-יפו) 15304-06-23 אגד חברה לתחבורה בע\"מ נ'' רשם החברות (28.03.2024)", "ת\"א (מחוזי תל אביב-יפו) 46948-11-21 פסגות קרנות נאמנות בע\"מ נ'' משרד המשפטים - רשם החברות (04.04.2022)"]'::jsonb,
    'classification_review: original chapter=''סדר דין אזרחי'' subtopic=''הליכים'' → mapped chapter=''corporate'' subtopic=''fiduciary_duties'' | classifier_note: Profit test + solvency test for distributions — directors'' duties under חוק החברות | source_review_note: השאלה עוסקת בדיני חברות, שהם תחום מהותי במשפט האזרחי. בחרתי ב''הליכים'' תחת ''סדר דין אזרחי'' כהצבת מקום, מכיוון שהשאלה עוסקת בהליכים פנימיים בחברה וביכולת לעתור לבית המשפט. עם זאת, הנושא המרכזי הוא מהותי ואינו משתלב באופן מושלם באף אחד מתתי-הנושאים הסגורים הקיימים. יש לשקול הוספת פרק ''דיני חברות'' או תת-נושא רחב יותר תחת ''סדר דין אזרחי'' שיכלול נושאים מהותיים בעלי השלכות דיוניות.', 'active', 'b9ecdde2-d07e-4761-96ab-05f0ad32d4e3'
  );

  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'א', 'מבחן הרווח הוא מבחן משני חשבונאי-טכני, ואילו מבחן יכולת הפירעון הוא מבחן עיקרי הסתברותי ומהותי, המתבסס על הערכה ועל אומדן של יכולת החברה לפרוע את חובותיה כלפי העתיד.', true, 'זוהי התשובה הנכונה. הפסיקה קבעה כי מבחן הרווח הוא מבחן משני, טכני וצופה פני עבר, בעוד שמבחן יכולת הפירעון הוא המבחן העיקרי, מהותי, הסתברותי וצופה פני עתיד, שמטרתו להגן על נושי החברה.', 1);
  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'ב', 'מבחן הרווח הוא מבחן עיקרי הסתברותי ומהותי, המתבסס על הערכה ועל אומדן של יכולת החברה להשיא רווחים בעתיד, ואילו מבחן יכולת הפירעון הוא מבחן משני חשבונאי-טכני וצופה פני העבר.', false, 'טענה זו הפוכה מהמצב המשפטי הנכון. מבחן הרווח הוא משני וטכני, ומבחן יכולת הפירעון הוא עיקרי ומהותי, ומתייחס ליכולת החברה לפרוע חובותיה, לא להשאת רווחים.', 2);
  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'ג', 'מבחן הרווח הוא מבחן עיקרי חשבונאי-טכני וצופה פני עתיד, ואילו מבחן יכולת הפירעון הוא מבחן משני הסתברותי ומהותי, המתבסס על הערכה ועל אומדן של יכולת החברה לפרוע את חובותיה בעבר.', false, 'טענה זו שגויה במספר היבטים: מבחן הרווח אינו עיקרי ואינו צופה פני עתיד, ומבחן יכולת הפירעון אינו משני ואינו צופה פני עבר.', 3);
  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'ד', 'מבחן הרווח הוא מבחן משני הסתברותי ומהותי, המתבסס על הערכה ועל אומדן של יכולת החברה לפרוע את חובותיה בעבר, ואילו מבחן יכולת הפירעון הוא מבחן עיקרי חשבונאי-טכני וצופה פני עתיד.', false, 'טענה זו שגויה. מבחן הרווח אינו הסתברותי ואינו צופה פני עבר בהקשר של יכולת פירעון, ומבחן יכולת הפירעון אינו טכני ואינו חשבונאי.', 4);

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_0, v_sq_id, 'א', 'חלוקה באישור בית משפט',
    1, 'חברת ''אלפא בע"מ'' מעוניינת לחלק דיבידנד לבעלי מניותיה, אך אינה עומדת במבחן הרווח כהגדרתו בסעיף 302(ב) לחוק החברות. עם זאת, החברה סבורה כי היא עומדת במבחן יכולת הפירעון. מהי הדרך העומדת בפני החברה לביצוע החלוקה?', 'שאלה זו בוחנת את המנגנון הקבוע בסעיף 303 לחוק החברות, המאפשר לחברה לבצע חלוקת דיבידנד גם אם אינה עומדת במבחן הרווח, וזאת בכפוף לאישור בית המשפט. היא מדגישה את עליונותו של מבחן יכולת הפירעון כקריטריון המכריע לאישור החלוקה במקרים אלו.', 'סעיף 302(א) לחוק החברות, תשנ"ט-1999, קובע כי חברה רשאית לבצע חלוקה מתוך רווחיה (מבחן הרווח), ובלבד שלא קיים חשש סביר שהחלוקה תמנע ממנה לעמוד בחבויותיה (מבחן יכולת הפירעון). סעיף 303(א) לחוק משלים הוראות אלה וקובע כי אי-עמידה במבחן הרווח אינה סותמת את הגולל על אפשרות החברה לבצע חלוקה. בית המשפט רשאי, לבקשת חברה, לאשר לה לבצע חלוקה שלא מקיימת את מבחן הרווח, ובלבד ששוכנע שמתקיים מבחן יכולת הפירעון. סעיף 303(א) לחוק החברות, תשנ"ט-1999 | חלוקה באישור בית משפט במקרה כזה, החברה תודיע לנושיה על הגשת הבקשה, ולנושים תהיה הזדמנות להתנגד (סעיף 303(ב)-(ד) לחוק). ת"א (מחוזי תל אביב-יפו) 15304-06-23 אגד חברה לתחבורה בע"מ נ'' רשם החברות (28.03.2024)',
    'הנחה שגויה כי אי-עמידה במבחן הרווח מונעת לחלוטין חלוקת דיבידנד, מבלי להכיר באפשרות של אישור בית משפט.', '["חלוקה באישור בית משפט", "מבחן הרווח", "מבחן יכולת הפירעון", "סעיף 303 לחוק החברות", "נושים", "הגנה על נושים"]'::jsonb, '**וריאציה 1 — אי-עמידה במבחן הרווח:** האם חברה שלא עומדת במבחן הרווח יכולה לחלק דיבידנד? ← כן, באישור בית משפט, אם עומדת במבחן יכולת הפירעון (סעיף 303(א) לחוק החברות).
**וריאציה 2 — תפקיד בית המשפט:** מה תפקיד בית המשפט באישור חלוקה כזו? ← לוודא שהחברה עומדת במבחן יכולת הפירעון ולשמוע את התנגדויות הנושים (סעיף 303(א), (ד) לחוק החברות).
**וריאציה 3 — זכויות נושים:** האם לנושים יש זכות להתנגד? ← כן, נושה רשאי לפנות לבית המשפט ולהתנגד (סעיף 303(ג) לחוק החברות).', 'חלוקה ללא מבחן רווח ← אפשרית באישור ביהמ"ש ← אם עומדת במבחן יכולת פירעון ← נושים יכולים להתנגד.',
    '["חוק החברות, תשנ\"ט-1999, סעיף 303", "ע\"א 1734/21 אמיר ברוט נ'' חברת השקעות דיסקונט בע\"מ (27.04.2023)", "תנ\"ג (כלכלית) 47621-07-16 אמוץ חורב נ'' בי קומיוניקיישנס בע\"מ (18.07.2019)", "ת\"א (מחוזי תל אביב-יפו) 15304-06-23 אגד חברה לתחבורה בע\"מ נ'' רשם החברות (28.03.2024)"]'::jsonb
  );
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_0, 'א', 'החברה אינה רשאית לבצע את החלוקה בשום אופן, שכן אי-עמידה במבחן הרווח מונעת כל חלוקה.', false, 'טענה זו אינה נכונה. סעיף 303 לחוק החברות מאפשר לחברה לבצע חלוקה גם אם אינה עומדת במבחן הרווח, בכפוף לאישור בית המשפט.', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_0, 'ב', 'החברה רשאית לפנות לבית המשפט בבקשה לאשר את החלוקה, ובלבד שבית המשפט ישתכנע כי מתקיים מבחן יכולת הפירעון.', true, 'זוהי התשובה הנכונה. סעיף 303(א) לחוק החברות קובע כי בית המשפט רשאי לאשר חלוקה שלא מקיימת את מבחן הרווח, אם שוכנע שמתקיים מבחן יכולת הפירעון.', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_0, 'ג', 'החברה רשאית לבצע את החלוקה ללא אישור בית המשפט, שכן מבחן יכולת הפירעון הוא המבחן העיקרי.', false, 'טענה זו אינה נכונה. אף שמבחן יכולת הפירעון הוא העיקרי, אי-עמידה במבחן הרווח מחייבת פנייה לבית המשפט לקבלת אישור, בהתאם לסעיף 303 לחוק החברות.', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_0, 'ד', 'החברה רשאית לבצע את החלוקה, ובלבד שתקבל את הסכמת כל נושיה מראש.', false, 'טענה זו אינה נכונה. הסכמת הנושים אינה תחליף לאישור בית המשפט במקרה של אי-עמידה במבחן הרווח, אם כי לנושים יש זכות להתנגד לבקשה בבית המשפט.', 4);

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_1, v_sq_id, 'ב', 'הגדרת "רווחים" במבחן הרווח',
    2, 'מהם "רווחים" לעניין מבחן הרווח, כהגדרתם בסעיף 302(ב) לחוק החברות?', 'שאלה זו מתמקדת בהגדרה המדויקת של המונח "רווחים" לצורך מבחן הרווח, כפי שמעוגנת בסעיף 302(ב) לחוק החברות. היא מדגישה את אופיו הטכני והחשבונאי של מבחן זה, המבוסס על נתונים מוגדרים ומוגבלים בזמן מדוחות כספיים.', 'סעיף 302(ב) לחוק החברות, תשנ"ט-1999, מגדיר את המונח "רווחים" לעניין מבחן הרווח. לפי הסעיף, "רווחים" הם "יתרת עודפים או עודפים שנצברו בשנתיים האחרונות, לפי הגבוה מבין השניים, והכל על פי הדוחות הכספיים המותאמים האחרונים, המבוקרים או הסקורים, שערכה החברה, תוך הפחתת חלוקות קודמות אם לא הופחתו כבר מן העודפים, ובלבד שהמועד שלגביו נערכו הדוחות אינו מוקדם ביותר משישה חודשים ממועד החלוקה". סעיף 302(ב) לחוק החברות, תשנ"ט-1999 | חלוקה מותרת הגדרה זו מדגישה את אופיו הטכני והחשבונאי של מבחן הרווח, המבוסס על נתונים קשיחים מדוחות כספיים קיימים. ע"א 1734/21 אמיר ברוט נ'' חברת השקעות דיסקונט בע"מ (27.04.2023)',
    'אי-הכרת ההגדרה המדויקת של "רווחים" בסעיף 302(ב) לחוק החברות, או בלבול בינה לבין הגדרות אחרות של רווחים או עודפים.', '["רווחים", "מבחן הרווח", "סעיף 302(ב) לחוק החברות", "יתרת עודפים", "עודפים שנצברו בשנתיים האחרונות", "דוחות כספיים מותאמים", "דוחות מבוקרים/סקורים"]'::jsonb, '**וריאציה 1 — הגדרת רווחים:** מהם ''רווחים'' למבחן הרווח? ← יתרת עודפים או עודפים שנצברו בשנתיים האחרונות, לפי הגבוה (סעיף 302(ב) לחוק החברות).
**וריאציה 2 — בסיס חישוב:** על בסיס אילו דוחות מחושבים הרווחים? ← דוחות כספיים מותאמים אחרונים, מבוקרים או סקורים (סעיף 302(ב) לחוק החברות).
**וריאציה 3 — מגבלת זמן:** מהי מגבלת הזמן לדוחות הכספיים? ← המועד שלגביו נערכו הדוחות אינו מוקדם ביותר משישה חודשים ממועד החלוקה (סעיף 302(ב) לחוק החברות).', 'רווחים למבחן הרווח ← הגבוה מיתרת עודפים או שנתיים אחרונות ← לפי דוחות מבוקרים/סקורים ← עד 6 חודשים לפני החלוקה.',
    '["חוק החברות, תשנ\"ט-1999, סעיף 302", "ע\"א 1734/21 אמיר ברוט נ'' חברת השקעות דיסקונט בע\"מ (27.04.2023)", "תנ\"ג (כלכלית) 16519-05-19 אמיר ברוט נ'' חברת השקעות דיסקונט בע\"מ (12.01.2021)", "ע\"א 2515/18 חברת אם.סי.אל קניון דרורים בע\"מ נ'' פקיד שומה פתח תקווה (17.06.2020)"]'::jsonb
  );
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_1, 'א', 'יתרת עודפים או עודפים שנצברו בשנתיים האחרונות, לפי הגבוה מבין השניים, על פי הדוחות הכספיים המותאמים האחרונים, המבוקרים או הסקורים, שמועדם אינו מוקדם ביותר משישה חודשים ממועד החלוקה.', true, 'זוהי התשובה הנכונה. סעיף 302(ב) לחוק החברות מגדיר במדויק את המונח ''רווחים'' לצורך מבחן הרווח, כולל את החלופות, סוג הדוחות הכספיים ומגבלת הזמן.', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_1, 'ב', 'כל סכום הכלול בהון העצמי של החברה, ובלבד שאינו הון מניות או פרמיה.', false, 'טענה זו מתארת את הגדרת ''עודפים'' באופן חלקי, אך לא את הגדרת ''רווחים'' למבחן הרווח, הכוללת גם את יתרת העודפים או עודפים שנצברו בשנתיים האחרונות.', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_1, 'ג', 'הרווח הנקי של החברה כפי שנקבע לפי כללי חשבונאות מקובלים, ללא קשר ליתרת עודפים קודמת.', false, 'טענה זו מתייחסת רק לחלק מהגדרת ''עודפים'' ומתעלמת מהחלופות של יתרת עודפים או עודפים שנצברו בשנתיים האחרונות.', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_1, 'ד', 'כל סכום שהדירקטוריון קבע כי הוא רווח, ובלבד שהחברה עומדת במבחן יכולת הפירעון.', false, 'טענה זו אינה נכונה. הגדרת ''רווחים'' היא אובייקטיבית וחשבונאית, ואינה נתונה לשיקול דעת הדירקטוריון, ואינה תלויה במבחן יכולת הפירעון.', 4);

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_2, v_sq_id, 'ג', 'אחריות דירקטורים לחלוקה אסורה',
    3, 'חברת ''בטא בע"מ'' ביצעה חלוקת דיבידנד אסורה. מהי אחריותם של הדירקטורים בחברה בגין חלוקה זו?', 'שאלה זו עוסקת באחריותם האישית של דירקטורים בחברה בגין ביצוע חלוקת דיבידנד אסורה. היא מתמקדת בסעיף 311 לחוק החברות, המטיל חזקה סטטוטורית של הפרת חובות על דירקטורים במקרה של חלוקה אסורה, ומפרט את ההגנות העומדות לרשותם.', 'סעיף 311 לחוק החברות, תשנ"ט-1999, קובע כי "בוצעה בחברה חלוקה אסורה יראו כל מי שהיה דירקטור במועד החלוקה כמי שהפר בכך את חובותיו לפי סעיפים 252, 253 או 254, לפי העניין, לחברה, אלא אם כן הוכיח אחד מאלה: (1) שהתנגד לחלוקה האסורה ונקט את כל האמצעים הסבירים כדי למנעה; (2) שהסתמך בתום לב הסתמכות סבירה על מידע שאלולא היה מטעה היתה החלוקה מותרת; (3) שבנסיבות העניין, לא ידע ולא היה עליו לדעת על החלוקה". ת"א (כלכלית ) 30851-01-16 חבס השקעות (1960) בע"מ נ'' ברוך חבס ייזום (2005) בע"מ (30.07.2020) הוראה זו מטילה אחריות כבדה על הדירקטורים, שכן היא קובעת חזקה להפרת חובותיהם, ומעבירה אליהם את נטל ההוכחה כי עמדו באחת ההגנות המנויות בחוק. ע"א 1734/21 אמיר ברוט נ'' חברת השקעות דיסקונט בע"מ (27.04.2023)',
    'הנחה שגויה כי אחריות דירקטורים לחלוקה אסורה דורשת הוכחת יסוד נפשי של זדון, או בלבול בין אחריות דירקטורים לאחריות בעלי מניות.', '["אחריות דירקטורים", "חלוקה אסורה", "סעיף 311 לחוק החברות", "הפרת חובות", "חובת זהירות", "חובת אמונים", "הגנות דירקטורים"]'::jsonb, '**וריאציה 1 — חזקה סטטוטורית:** מהי החזקה לגבי דירקטורים בחלוקה אסורה? ← יראו כל דירקטור כמי שהפר את חובותיו לחברה (סעיף 311 לחוק החברות).
**וריאציה 2 — הגנות:** אילו הגנות עומדות לדירקטור? ← התנגדות לחלוקה, הסתמכות בתום לב על מידע מטעה, או אי-ידיעה על החלוקה (סעיף 311(1)-(3) לחוק החברות).
**וריאציה 3 — נטל ההוכחה:** על מי מוטל נטל ההוכחה? ← על הדירקטור להוכיח את קיום אחת ההגנות (סעיף 311 לחוק החברות).', 'חלוקה אסורה ← חזקה להפרת חובות דירקטורים ← נטל הוכחה על הדירקטור להגנות (סעיף 311 לחוק החברות).',
    '["חוק החברות, תשנ\"ט-1999, סעיף 311", "ע\"א 1734/21 אמיר ברוט נ'' חברת השקעות דיסקונט בע\"מ (27.04.2023)", "ת\"א (כלכלית ) 30851-01-16 חבס השקעות (1960) בע\"מ נ'' ברוך חבס ייזום (2005) בע\"מ (30.07.2020)", "פר\"ק (מחוזי ת\"א) 3421-01-15 עו\"ד רענן קליר מתוקף תפקידו על-פי סעיף 17 להסדר הנושים למיצוי זכויות של החברה והנושים נ'' ד\"ר שמחה סדן (17.12.2016)"]'::jsonb
  );
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_2, 'א', 'הדירקטורים אינם נושאים באחריות אישית, שכן החלוקה היא פעולה של החברה כאישיות משפטית נפרדת.', false, 'טענה זו אינה נכונה. סעיף 311 לחוק החברות מטיל אחריות אישית על דירקטורים בגין חלוקה אסורה, אלא אם כן מתקיימות הגנות מסוימות.', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_2, 'ב', 'יראו כל דירקטור כמי שהפר את חובותיו לחברה, אלא אם כן הוכיח שהתנגד לחלוקה, הסתמך בתום לב על מידע מטעה, או לא ידע ולא היה עליו לדעת על החלוקה.', true, 'זוהי התשובה הנכונה. סעיף 311 לחוק החברות קובע חזקה סטטוטורית להפרת חובות דירקטורים במקרה של חלוקה אסורה, ומפרט את ההגנות האפשריות.', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_2, 'ג', 'הדירקטורים נושאים באחריות אישית רק אם הוכח שפעלו בזדון או בחוסר תום לב מובהק.', false, 'טענה זו אינה נכונה. סעיף 311 לחוק החברות קובע חזקה להפרת חובות, ואינו דורש הוכחת זדון או חוסר תום לב מובהק, אלא אם כן הדירקטור עומד באחת ההגנות.', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_2, 'ד', 'הדירקטורים נושאים באחריות אישית רק אם החברה נקלעה לחדלות פירעון בעקבות החלוקה האסורה.', false, 'טענה זו אינה נכונה. אחריות הדירקטורים לפי סעיף 311 לחוק החברות אינה מותנית בחדלות פירעון של החברה, אלא בעצם ביצוע החלוקה האסורה.', 4);

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_3, v_sq_id, 'ד', 'תכלית מבחני החלוקה',
    4, 'מהי התכלית העיקרית של מבחן הרווח ומבחן יכולת הפירעון בחוק החברות?', 'שאלה זו בוחנת את הרציונל והתכלית העומדים בבסיס מבחני החלוקה הקבועים בחוק החברות. היא מדגישה את האיזון העדין בין האינטרסים המנוגדים של בעלי המניות, המעוניינים ליהנות מרווחי החברה, לבין האינטרסים של הנושים, המבקשים להבטיח את פירעון חובותיהם.', 'התכלית העיקרית של מבחן הרווח ומבחן יכולת הפירעון, המעוגנים בסעיפים 302 ו-303 לחוק החברות, היא ליצור איזון בין זכויות בעלי המניות בחברה למקסם את תשואתם ממנה ולממשה בדרך של חלוקת דיבידנדים, לבין ההגנה על זכויותיהם הלגיטימיות של נושי החברה מפני כרסום גורף ובלתי מידתי בהון החברה. ת"א (כלכלית ) 48631-06-17 סאני תקשורת סלולרית בע"מ נ'' אילן בן דב (22.03.2021) מבחנים אלו נועדו להבטיח כי החלוקה לא תפגע ביכולתה של החברה לעמוד בחיובים כלפי נושיה, ובכך לשמש "כרית ביטחון" לנושים. ת"א (כלכלית ) 30851-01-16 חבס השקעות (1960) בע"מ נ'' ברוך חבס ייזום (2005) בע"מ (30.07.2020)',
    'התמקדות באינטרס אחד בלבד (בעלי מניות או נושים) במקום בהבנת האיזון העדין שמבחני החלוקה מנסים להשיג.', '["תכלית מבחני החלוקה", "הגנה על נושים", "זכויות בעלי מניות", "איזון אינטרסים", "כרית ביטחון", "חוק החברות"]'::jsonb, '**וריאציה 1 — אינטרסים מנוגדים:** אילו אינטרסים מנוגדים מבקשים מבחני החלוקה לאזן? ← זכויות בעלי המניות לדיבידנד מול זכויות הנושים לפירעון חוב (ת"א (כלכלית) 48631-06-17).
**וריאציה 2 — הגנה על נושים:** כיצד מבחני החלוקה מגנים על נושים? ← מבטיחים שהחלוקה לא תפגע ביכולת החברה לעמוד בחובותיה (ת"א (כלכלית) 30851-01-16).
**וריאציה 3 — כרית ביטחון:** מה תפקיד הון החברה בהקשר זה? ← לשמש כרית ביטחון לנושים, שלא תדולדל שלא כדין (ת"א (כלכלית) 30851-01-16).', 'מבחני החלוקה ← איזון בין בעלי מניות לנושים ← הגנה על נושים ← שמירה על כרית ביטחון.',
    '["חוק החברות, תשנ\"ט-1999, סעיפים 302, 303", "ע\"א 1734/21 אמיר ברוט נ'' חברת השקעות דיסקונט בע\"מ (27.04.2023)", "ת\"א (כלכלית ) 48631-06-17 סאני תקשורת סלולרית בע\"מ נ'' אילן בן דב (22.03.2021)", "ת\"א (כלכלית ) 30851-01-16 חבס השקעות (1960) בע\"מ נ'' ברוך חבס ייזום (2005) בע\"מ (30.07.2020)", "ת\"א (מחוזי תל אביב-יפו) 15304-06-23 אגד חברה לתחבורה בע\"מ נ'' רשם החברות (28.03.2024)"]'::jsonb
  );
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_3, 'א', 'להגן על בעלי המניות מפני דילול הונם ולהבטיח את רווחיות החברה.', false, 'טענה זו אינה נכונה. אף שבעלי המניות נהנים מהחלוקה, התכלית העיקרית של המבחנים היא הגנה על נושי החברה.', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_3, 'ב', 'לאזן בין זכויות בעלי המניות ליהנות מרווחי החברה לבין ההגנה על זכויות הנושים מפני דילול הון החברה.', true, 'זוהי התשובה הנכונה. מבחני החלוקה נועדו לאזן בין האינטרסים המנוגדים של בעלי המניות (לקבל דיבידנד) ושל הנושים (לשמור על כרית ביטחון לפירעון חובות).', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_3, 'ג', 'להבטיח את יציבות שוק ההון ולמנוע תנודתיות במחירי מניות החברה.', false, 'טענה זו אינה נכונה. אף שיש למבחנים השפעה עקיפה על שוק ההון, זו אינה תכליתם העיקרית והישירה.', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_3, 'ד', 'לשמור על עקרון האישיות המשפטית הנפרדת של החברה בכל מחיר.', false, 'טענה זו אינה נכונה. מבחני החלוקה הם חריג לעקרון האישיות המשפטית הנפרדת, שכן הם מגבילים את יכולת החברה לחלק נכסים לבעלי מניותיה.', 4);

  RAISE NOTICE 'Q% inserted: external_id %', 27, '2022-S-S-Q27';
END
$$;

