-- classifier_note: Powers normally vested in board vs general meeting — corporate governance structure
-- ============================================================
DO $$
DECLARE
  v_sq_id uuid := '4d3a1aad-814a-4bb6-a2d1-7f3604a68c06'::uuid;
  v_group_id uuid := '2ec3a17d-8f40-4005-a5f3-f0b0014ede93'::uuid;
  v_chapter_id uuid;
  v_subtopic_id uuid;
  v_existing_id uuid;
  v_ang_0 uuid := 'c19271d1-63de-43aa-81d7-e47c6df84b20'::uuid;
  v_ang_1 uuid := '975ccd75-381c-4736-a505-94d69f5ee0e0'::uuid;
  v_ang_2 uuid := 'e0afbf6e-9d48-4517-b4fb-972bf0cd3e52'::uuid;
  v_ang_3 uuid := '7da52902-9915-4eba-be62-3eb2cf31b183'::uuid;
BEGIN
  SELECT id INTO v_existing_id FROM public.source_questions WHERE external_id = '2022-S-S-Q28';
