  INSERT INTO public.source_questions (
    id, question_group_id, version, is_current, external_id, chapter_id, subtopic_id, question_text, source_metadata, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list, notes_for_admin, status, created_by
  ) VALUES (
    v_sq_id, v_group_id, 1, true,
    '2022-S-S-Q28', v_chapter_id, v_subtopic_id, 'איזה מההיגדים הבאים מתאר נכונה את הסמכויות הנתונות באופן רגיל בידי דירקטוריון החברה והאסיפה הכללית?',
    '{"exam_year": 2022, "exam_season": "summer", "exam_part": 2, "exam_question_number": 28}'::jsonb, 'שאלה זו עוסקת בחלוקת הסמכויות בין האורגנים המרכזיים בחברה – האסיפה הכללית והדירקטוריון – כפי שנקבע בחוק החברות, תשנ"ט-1999. היא בוחנת את סמכויות הליבה של כל אחד מהאורגנים, תוך התייחסות לעקרון הפרדת הסמכויות ולחריגים לו, כגון יכולת האסיפה הכללית להפעיל סמכויות דירקטוריון במקרים מסוימים.', 'חוק החברות קובע הפרדת סמכויות ברורה בין האסיפה הכללית לדירקטוריון. האסיפה הכללית, המורכבת מבעלי המניות, מוסמכת לקבל החלטות בענייני יסוד של החברה, כגון שינוי תקנון, מינוי דירקטורים (למעט חיצוניים), אישור עסקאות הטעונות אישור מיוחד, והגדלת או הפחתת הון המניות הרשום. סעיף 57 לחוק החברות, תשנ"ט-1999 | הסמכויות המוקנות לאסיפה הכללית הדירקטוריון, לעומת זאת, הוא האורגן המנהל את החברה וקובע את מדיניותה, מפקח על ביצועיה, קובע תוכניות פעולה, בודק את מצבה הכספי, ממנה ומפטר את המנכ"ל, ואחראי לעריכת הדוחות הכספיים. סעיף 92 לחוק החברות, תשנ"ט-1999 | סמכויות הדירקטוריון ותפקידיו במקרים חריגים של אי-תפקוד הדירקטוריון, האסיפה הכללית רשאית להפעיל את סמכויותיו, וזאת בהחלטה שתתקבל ברוב מיוחד של בעלי המניות. סעיף 250 לחוק החברות, תשנ"ט-1999 | מינוי ופיטורים של מנהל כללי', 'בלבול בין סמכויות האסיפה הכללית לדירקטוריון, והנחה שגויה כי אחד האורגנים כפוף באופן מוחלט לשני, במקום הבנת הפרדת הסמכויות והחריגים לה.',
    '["אסיפה כללית", "דירקטוריון", "הפרדת סמכויות", "סמכויות יסוד", "ניהול שוטף", "דירקטורים חיצוניים", "מנכ\"ל", "חוק החברות"]'::jsonb, '**וריאציה 1 — סמכויות אסיפה כללית:** מהן סמכויות האסיפה הכללית? ← שינוי תקנון, מינוי דירקטורים חיצוניים, הגדלת הון מניות (סעיף 57 לחוק החברות).
**וריאציה 2 — סמכויות דירקטוריון:** מהן סמכויות הדירקטוריון? ← קביעת תוכניות פעולה, פיטורי ומינוי מנכ"ל, בדיקת מצב כספי (סעיף 92 לחוק החברות).
**וריאציה 3 — חריג להפרדה:** מתי האסיפה הכללית יכולה להפעיל סמכויות דירקטוריון? ← אם הדירקטוריון אינו מתפקד, ברוב מיוחד (סעיף 250 לחוק החברות).', 'האסיפה הכללית עוסקת בענייני יסוד ושינויים מבניים, הדירקטוריון בניהול השוטף, עם חריג בסעיף 250 לחוק החברות.', '["חוק החברות, תשנ\"ט-1999, סעיפים 57, 92, 250", "ת\"א (כלכלית ) 17401-05-16 צפורה מרקוביץ נ'' רבקה כהנמן (20.03.2019)", "ת\"פ (שלום ת\"א) 3933-08-10 מדינת ישראל נ'' טי.אר.די אינסטרומ. בע\"מ (16.05.2019)", "ה\"פ (כלכלית ) 64660-12-17 מגדל השעון ביפו בע\"מ נ'' רו\"ח עופר רפאל (08.12.2019)", "ה\"פ (כלכלית ) 11472-05-18 בצלאל מזרחי נ'' בית עזרת אחים חברה להקמת הבנין בע\"מ (11.12.2019)", "ת\"א (מחוזי מרכז) 11845-08-18 בי.אס.די קראון בע\"מ נ'' גרגורי גורטובוי (30.05.2019)", "ת\"א (כלכלית ) 68338-10-18 בזק החברה הישראלית לתקשורת בע\"מ נ'' ע.א.ד.א. ליעד אחזקות (2006) בע\"מ (01.12.2019)"]'::jsonb,
    'classification_review: original chapter=''סדר דין אזרחי'' subtopic=''הליכים'' → mapped chapter=''corporate'' subtopic=''companies_formation'' | classifier_note: Powers normally vested in board vs general meeting — corporate governance structure | source_review_note: השאלה עוסקת בדיני חברות, שהם תחום מהותי במשפט האזרחי. בחרתי ב''הליכים'' תחת ''סדר דין אזרחי'' כהצבת מקום, מכיוון שהשאלה עוסקת בהליכים פנימיים בחברה וביכולת לעתור לבית המשפט. עם זאת, הנושא המרכזי הוא מהותי ואינו משתלב באופן מושלם באף אחד מתתי-הנושאים הסגורים הקיימים. יש לשקול הוספת פרק ''דיני חברות'' או תת-נושא רחב יותר תחת ''סדר דין אזרחי'' שיכלול נושאים מהותיים בעלי השלכות דיוניות.', 'active', 'b9ecdde2-d07e-4761-96ab-05f0ad32d4e3'
  );

  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'א', 'בסמכות האסיפה הכללית לקבל החלטות, בין היתר, בדבר העברת סמכותה הקבועה בחוק לאחד מהאורגנים האחרים בחברה, ביצוע שינויים בתקנון ומינוי דירקטורים חיצוניים, ובסמכות דירקטוריון החברה לקבל החלטות, בין היתר, בדבר פיטוריו ומינויו של מנכ"ל החברה, בדיקת מצבה הכספי של החברה ושינוי התקנון של החברה.', false, 'טענה זו אינה נכונה בחלקה. האסיפה הכללית אינה מוסמכת להעביר סמכותה הקבועה בחוק באופן גורף. שינוי תקנון הוא בסמכות האסיפה הכללית, לא הדירקטוריון.', 1);
  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'ב', 'בסמכות האסיפה הכללית לקבל החלטות, בין היתר, בדבר ביצוע שינויים בתקנון החברה, הפעלת סמכויות הדירקטוריון ומינוי דירקטורים חיצוניים, ובסמכות דירקטוריון החברה לקבל החלטות, בין היתר, בדבר קביעת תוכניות הפעולה של החברה ופיטוריו ומינויו של מנכ"ל החברה.', true, 'זוהי התשובה הנכונה. סעיף 57 לחוק החברות קובע את סמכויות האסיפה הכללית, וסעיף 92 קובע את סמכויות הדירקטוריון. סעיף 250 מאפשר לאסיפה הכללית להפעיל סמכויות הדירקטוריון במקרים חריגים.', 2);
  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'ג', 'בסמכות האסיפה הכללית לקבל החלטות, בין היתר, בדבר פיטוריו ומינויו של מנכ"ל החברה, בדיקת מצבה הכספי של החברה ושינוי התקנון של החברה, ובסמכות דירקטוריון החברה לקבל החלטות, בין היתר, בדבר העברת סמכותו הקבועה בחוק לאחד מהאורגנים האחרים בחברה, ביצוע שינויים בתקנון ומינוי דירקטורים חיצוניים.', false, 'טענה זו אינה נכונה. פיטורי ומינוי מנכ"ל הם בסמכות הדירקטוריון, לא האסיפה הכללית. העברת סמכות הדירקטוריון לאורגן אחר אינה בסמכות הדירקטוריון באופן גורף.', 3);
  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'ד', 'בסמכות האסיפה הכללית לקבל החלטות, בין היתר, בדבר הגדלת הון המניות הרשום והפחתתו, פיטוריו ומינויו של מנכ"ל החברה וקביעת תוכניות הפעולה של החברה, ובסמכות דירקטוריון החברה לקבל החלטות, בין היתר, בדבר שינוי תקנון החברה, מינוי דירקטורים חיצוניים והנפקה של סדרות חוב.', false, 'טענה זו אינה נכונה. פיטורי ומינוי מנכ"ל וקביעת תוכניות פעולה הם בסמכות הדירקטוריון. שינוי תקנון ומינוי דירקטורים חיצוניים הם בסמכות האסיפה הכללית.', 4);

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_0, v_sq_id, 'א', 'הפעלת סמכויות הדירקטוריון על ידי האסיפה הכללית',
    1, 'חברת ''אלפא בע"מ'' נמצאת במשבר ניהולי חמור, ודירקטוריון החברה אינו מתפקד ואינו מסוגל לקבל החלטות חיוניות להמשך פעילותה. בעלי המניות מעוניינים שהאסיפה הכללית תקבל החלטות ניהוליות דחופות שבאופן רגיל נתונות לסמכות הדירקטוריון. מה הדין?', 'שאלה זו בוחנת את החריג לעקרון הפרדת הסמכויות בין האסיפה הכללית לדירקטוריון, כפי שמעוגן בסעיף 250 לחוק החברות. היא מתמקדת במצב שבו הדירקטוריון אינו מתפקד, ומאפשרת לאסיפה הכללית להתערב בענייני ניהול החברה.', 'סעיף 250 לחוק החברות, תשנ"ט-1999, קובע חריג לעקרון הפרדת הסמכויות בין האסיפה הכללית לדירקטוריון. הסעיף קובע כי "האסיפה הכללית רשאית להפעיל את סמכויות הדירקטוריון, אם הדירקטוריון אינו מתפקד, וזאת בהחלטה שתתקבל ברוב מיוחד של בעלי המניות". סעיף 250 לחוק החברות, תשנ"ט-1999 | הפעלת סמכויות הדירקטוריון על ידי האסיפה הכללית מצב של אי-תפקוד הדירקטוריון יכול להתקיים במגוון נסיבות, כגון שיתוק הדירקטוריון עקב סכסוכים פנימיים, חוסר יכולת לקבל החלטות, או היעדר דירקטורים מספקים. במקרים אלו, המחוקק מאפשר לאורגן העליון של החברה, האסיפה הכללית, להתערב כדי להבטיח את המשך פעילותה התקינה של החברה. ת"א (כלכלית ) 17401-05-16 צפורה מרקוביץ נ'' רבקה כהנמן (20.03.2019)',
    'הנחה שגויה כי הפרדת הסמכויות היא מוחלטת ואינה מאפשרת גמישות במצבי חירום או אי-תפקוד.', '["הפעלת סמכויות דירקטוריון", "אסיפה כללית", "אי-תפקוד דירקטוריון", "סעיף 250 לחוק החברות", "רוב מיוחד", "משבר ניהולי"]'::jsonb, '**וריאציה 1 — אי-תפקוד דירקטוריון:** מה קורה כשהדירקטוריון לא מתפקד? ← האסיפה הכללית יכולה להפעיל את סמכויותיו (סעיף 250 לחוק החברות).
**וריאציה 2 — תנאי להפעלה:** באיזה רוב נדרשת החלטה כזו? ← ברוב מיוחד של בעלי המניות (סעיף 250 לחוק החברות).
**וריאציה 3 — תכלית הסעיף:** מה מטרת סעיף 250? ← למנוע שיתוק בחברה ולאפשר המשך פעילותה במצבי משבר (ת"א (כלכלית ) 17401-05-16).', 'דירקטוריון לא מתפקד ← אסיפה כללית יכולה להפעיל סמכויותיו ← ברוב מיוחד (סעיף 250 לחוק החברות).',
    '["חוק החברות, תשנ\"ט-1999, סעיף 250", "ת\"א (כלכלית ) 17401-05-16 צפורה מרקוביץ נ'' רבקה כהנמן (20.03.2019)"]'::jsonb
  );
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_0, 'א', 'האסיפה הכללית אינה מוסמכת לקבל החלטות ניהוליות, שכן סמכויות אלו שמורות באופן בלעדי לדירקטוריון.', false, 'טענה זו אינה נכונה. סעיף 250 לחוק החברות מאפשר לאסיפה הכללית להפעיל סמכויות דירקטוריון במקרים חריגים, כגון אי-תפקוד הדירקטוריון.', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_0, 'ב', 'האסיפה הכללית רשאית להפעיל את סמכויות הדירקטוריון במקרה של אי-תפקוד הדירקטוריון, ובלבד שההחלטה מתקבלת ברוב מיוחד.', true, 'זוהי התשובה הנכונה. סעיף 250 לחוק החברות קובע כי האסיפה הכללית רשאית להפעיל את סמכויות הדירקטוריון אם הדירקטוריון אינו מתפקד, וזאת בהחלטה שתתקבל ברוב מיוחד של בעלי המניות.', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_0, 'ג', 'האסיפה הכללית רשאית להפעיל את סמכויות הדירקטוריון רק אם הדבר נקבע במפורש בתקנון החברה.', false, 'טענה זו אינה נכונה. סעיף 250 לחוק החברות מקנה סמכות זו לאסיפה הכללית גם ללא הוראה מפורשת בתקנון, במקרים של אי-תפקוד הדירקטוריון.', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_0, 'ד', 'רק בית המשפט מוסמך להורות על העברת סמכויות הדירקטוריון לאסיפה הכללית במקרה של אי-תפקוד.', false, 'טענה זו אינה נכונה. סעיף 250 לחוק החברות מאפשר לאסיפה הכללית עצמה להפעיל סמכויות אלו, ללא צורך באישור בית המשפט, במקרים מסוימים.', 4);

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_1, v_sq_id, 'ב', 'עקרון הפרדת הסמכויות בין אורגנים',
    2, 'מהו העיקרון המנחה את חלוקת הסמכויות בין האסיפה הכללית לדירקטוריון בחברה?', 'שאלה זו עוסקת בעקרון הפרדת הסמכויות המבני בין האורגנים המרכזיים בחברה – האסיפה הכללית והדירקטוריון. היא מדגישה את התפקידים השונים של כל אורגן: האסיפה הכללית כגוף המחליט בענייני יסוד ומבנה, והדירקטוריון כגוף המנהל את ענייני החברה השוטפים.', 'חוק החברות, תשנ"ט-1999, מבסס עקרון של הפרדת סמכויות בין האסיפה הכללית לדירקטוריון. האסיפה הכללית, המורכבת מבעלי המניות, מוסמכת לקבל החלטות בענייני יסוד של החברה, כגון שינוי תקנון (סעיף 57(1)), מינוי דירקטורים (סעיף 57(4)), אישור עסקאות מסוימות (סעיף 57(א)(1)), ומינוי רואה חשבון מבקר (סעיף 57(3)). סעיף 57 לחוק החברות, תשנ"ט-1999 | הסמכויות המוקנות לאסיפה הכללית הדירקטוריון, לעומת זאת, הוא האורגן המנהל את החברה וקובע את מדיניותה, מפקח על ביצועיה וממנה את המנכ"ל (סעיף 92). סעיף 92 לחוק החברות, תשנ"ט-1999 | סמכויות הדירקטוריון ותפקידיו',
    'הבנה שגויה של היחסים בין האורגנים, תוך ייחוס סמכויות ניהוליות לאסיפה הכללית או סמכויות יסוד לדירקטוריון.', '["הפרדת סמכויות", "אסיפה כללית", "דירקטוריון", "סמכויות יסוד", "ניהול שוטף", "חוק החברות"]'::jsonb, '**וריאציה 1 — סמכויות אסיפה כללית:** מהן סמכויות האסיפה הכללית? ← ענייני יסוד ושינויים מבניים (סעיף 57 לחוק החברות).
**וריאציה 2 — סמכויות דירקטוריון:** מהן סמכויות הדירקטוריון? ← ניהול שוטף, קביעת מדיניות ופיקוח (סעיף 92 לחוק החברות).
**וריאציה 3 — עקרון מנחה:** מהו העיקרון המנחה? ← הפרדת סמכויות בין אורגנים, עם חריגים מוגדרים.', 'אסיפה כללית ← ענייני יסוד. דירקטוריון ← ניהול שוטף. עקרון הפרדת סמכויות.',
    '["חוק החברות, תשנ\"ט-1999, סעיפים 57, 92", "ה\"פ (כלכלית ) 64660-12-17 מגדל השעון ביפו בע\"מ נ'' רו\"ח עופר רפאל (08.12.2019)", "ת\"א (כלכלית ) 68338-10-18 בזק החברה הישראלית לתקשורת בע\"מ נ'' ע.א.ד.א. ליעד אחזקות (2006) בע\"מ (01.12.2019)", "ת\"א (כלכלית ) 17401-05-16 צפורה מרקוביץ נ'' רבקה כהנמן (20.03.2019)"]'::jsonb
  );
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_1, 'א', 'האסיפה הכללית היא האורגן העליון המוסמך לקבל כל החלטה, והדירקטוריון כפוף לה באופן מלא.', false, 'טענה זו אינה נכונה. אף שהאסיפה הכללית היא האורגן העליון, קיימת הפרדת סמכויות ברורה, והדירקטוריון אינו כפוף לה באופן מלא בענייני ניהול שוטף.', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_1, 'ב', 'האסיפה הכללית מוסמכת לענייני יסוד ושינויים מבניים, ואילו הדירקטוריון מוסמך לניהול השוטף של החברה.', true, 'זוהי התשובה הנכונה. זהו עקרון הפרדת הסמכויות המרכזי בחוק החברות, המבחין בין סמכויות האסיפה הכללית (סעיף 57) לבין סמכויות הדירקטוריון (סעיף 92).', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_1, 'ג', 'הדירקטוריון מוסמך לקבל את כל ההחלטות, למעט אלו שהועברו במפורש לאסיפה הכללית בתקנון.', false, 'טענה זו אינה נכונה. חוק החברות קובע במפורש סמכויות ייחודיות לאסיפה הכללית שאינן ניתנות להעברה, גם ללא הוראה בתקנון.', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_1, 'ד', 'חלוקת הסמכויות נקבעת באופן בלעדי על ידי תקנון החברה, ואין לה כללים קבועים בחוק.', false, 'טענה זו אינה נכונה. חוק החברות קובע חלוקת סמכויות בסיסית, ורק במידה מסוימת ניתן לשנותה באמצעות התקנון, בכפוף להוראות החוק.', 4);

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_2, v_sq_id, 'ג', 'סמכות מינוי רואה חשבון מבקר',
    3, 'מי מוסמך למנות רואה חשבון מבקר לחברה, ומהי תקופת כהונתו?', 'שאלה זו עוסקת בסמכות המינוי של רואה חשבון מבקר בחברה ובתקופת כהונתו, כפי שנקבע בחוק החברות. היא מדגישה את תפקידה המרכזי של האסיפה הכללית בעניין זה, ואת העיקרון של מינוי שנתי.', 'סעיף 57(3) לחוק החברות, תשנ"ט-1999, קובע כי "החלטות החברה בענינים האלה יתקבלו באסיפה הכללית: ... (3) מינוי רואה החשבון המבקר של החברה, תנאי העסקתו והפסקת העסקתו בהתאם להוראות סעיפים 154 עד 167". סעיף 57(3) לחוק החברות, תשנ"ט-1999 | הסמכויות המוקנות לאסיפה הכללית כלומר, הסמכות למנות רואה חשבון מבקר נתונה לאסיפה הכללית. אשר לתקופת כהונתו, סעיף 154(ב) לחוק החברות קובע כי "רואה חשבון מבקר יתמנה בכל אסיפה שנתית וישמש בתפקידו עד תום האסיפה השנתית שלאחריה". ה"פ (כלכלית ) 64660-12-17 מגדל השעון ביפו בע"מ נ'' רו"ח עופר רפאל (08.12.2019) מכאן, שרואה חשבון מבקר ממונה על ידי האסיפה הכללית וכהונתו היא לשנה אחת, עד לאסיפה השנתית הבאה. ה"פ (כלכלית ) 11472-05-18 בצלאל מזרחי נ'' בית עזרת אחים חברה להקמת הבנין בע"מ (11.12.2019)',
    'בלבול בין סמכויות האורגנים השונים בחברה (אסיפה כללית, דירקטוריון, ועדת ביקורת) בנוגע למינוי רואה חשבון מבקר.', '["רואה חשבון מבקר", "אסיפה כללית", "סמכות מינוי", "תקופת כהונה", "חוק החברות", "אסיפה שנתית"]'::jsonb, '**וריאציה 1 — מינוי:** מי ממנה רואה חשבון מבקר? ← האסיפה הכללית (סעיף 57(3) לחוק החברות).
**וריאציה 2 — תקופת כהונה:** כמה זמן מכהן רואה חשבון מבקר? ← עד תום האסיפה השנתית שלאחריה (סעיף 154(ב) לחוק החברות).
**וריאציה 3 — סמכות דירקטוריון:** האם הדירקטוריון יכול למנות רואה חשבון? ← לא, זו סמכות האסיפה הכללית (ה"פ (כלכלית ) 11472-05-18).', 'רואה חשבון מבקר ממונה על ידי האסיפה הכללית לכהונה שנתית.',
    '["חוק החברות, תשנ\"ט-1999, סעיפים 57, 154", "ה\"פ (כלכלית ) 64660-12-17 מגדל השעון ביפו בע\"מ נ'' רו\"ח עופר רפאל (08.12.2019)", "ה\"פ (כלכלית ) 11472-05-18 בצלאל מזרחי נ'' בית עזרת אחים חברה להקמת הבנין בע\"מ (11.12.2019)"]'::jsonb
  );
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_2, 'א', 'האסיפה הכללית מוסמכת למנות רואה חשבון מבקר, וכהונתו היא עד תום האסיפה השנתית שלאחריה.', true, 'זוהי התשובה הנכונה. סעיף 57(3) לחוק החברות קובע כי מינוי רואה חשבון מבקר הוא בסמכות האסיפה הכללית, וסעיף 154(ב) קובע את תקופת כהונתו.', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_2, 'ב', 'הדירקטוריון מוסמך למנות רואה חשבון מבקר, וכהונתו היא לשנה אחת.', false, 'טענה זו אינה נכונה. הסמכות למינוי רואה חשבון מבקר נתונה לאסיפה הכללית, ולא לדירקטוריון.', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_2, 'ג', 'ועדת הביקורת מוסמכת למנות רואה חשבון מבקר, וכהונתו היא לשלוש שנים.', false, 'טענה זו אינה נכונה. ועדת הביקורת אינה מוסמכת למנות רואה חשבון מבקר, ואין קביעה גורפת לתקופת כהונה של שלוש שנים.', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_2, 'ד', 'בעל השליטה בחברה מוסמך למנות רואה חשבון מבקר, וכהונתו היא ללא הגבלת זמן.', false, 'טענה זו אינה נכונה. מינוי רואה חשבון מבקר הוא בסמכות האסיפה הכללית, ולא בסמכות בעל השליטה באופן ישיר, וכהונתו מוגבלת בזמן.', 4);

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_3, v_sq_id, 'ד', 'תוקף החלטות אסיפה כללית שהתקבלה שלא כדין',
    4, 'חברת ''גמא בע"מ'' קיימה אסיפה כללית שבה התקבלה החלטה מהותית, אך התברר כי האסיפה זומנה שלא כדין, ללא מתן הודעה מספקת לכל בעלי המניות. מהו תוקף ההחלטה שהתקבלה באסיפה זו?', 'שאלה זו עוסקת בתוקפן של החלטות אסיפה כללית שהתקבלו בפגם פרוצדורלי, ובפרט בפגם בזימון. היא מתייחסת לסעיף 91 לחוק החברות, המאזן בין הצורך ביציבות החלטות החברה לבין ההגנה על זכויות בעלי המניות מפני קיפוח.', 'חוק החברות קובע כללים ברורים לזימון אסיפה כללית (סעיפים 61-63). פגם בזימון אסיפה כללית עלול להשפיע על תוקף ההחלטות שהתקבלו בה. סעיף 91 לחוק החברות, תשנ"ט-1999, קובע כי "פגם בזימון אסיפה כללית, בכינוסה, בניהולה או בקבלת החלטות בה, לרבות פגם הנוגע לכינוס אסיפה כללית שלא כדין, לא יבטל החלטה שהתקבלה בה, אלא אם כן קבע בית המשפט כי הפגם גרם לקיפוח מהותי של בעל מניה". ה"פ (כלכלית ) 64660-12-17 מגדל השעון ביפו בע"מ נ'' רו"ח עופר רפאל (08.12.2019) כלומר, פגם פרוצדורלי אינו מבטל אוטומטית את ההחלטה, אלא נדרשת התערבות שיפוטית וקביעה כי הפגם גרם לקיפוח מהותי. בית המשפט בוחן את מהות הפגם ואת השפעתו על זכויות בעלי המניות. ה"פ (כלכלית ) 11472-05-18 בצלאל מזרחי נ'' בית עזרת אחים חברה להקמת הבנין בע"מ (11.12.2019)',
    'הנחה שגויה כי כל פגם פרוצדורלי באסיפה כללית מבטל את החלטותיה, או לחלופין, שפגמים כאלה אינם משפיעים כלל על תוקף ההחלטות.', '["פגם בזימון", "אסיפה כללית", "תוקף החלטות", "קיפוח מהותי", "סעיף 91 לחוק החברות", "התערבות בית המשפט"]'::jsonb, '**וריאציה 1 — פגם בזימון:** האם פגם בזימון מבטל החלטה? ← לא אוטומטית, רק אם בית המשפט קבע קיפוח מהותי (סעיף 91 לחוק החברות).
**וריאציה 2 — תפקיד בית המשפט:** מה תפקיד בית המשפט? ← לבחון אם הפגם גרם לקיפוח מהותי של בעל מניה.
**וריאציה 3 — דרישות זימון:** מהן דרישות הזימון? ← יש לזמן את כל בעלי המניות כדין, אחרת עלולות להיות השלכות על תוקף ההחלטות (ה"פ (כלכלית ) 64660-12-17).', 'פגם בזימון אסיפה כללית ← לא מבטל החלטה אוטומטית ← רק אם ביהמ"ש קבע קיפוח מהותי (סעיף 91 לחוק החברות).',
    '["חוק החברות, תשנ\"ט-1999, סעיף 91", "ה\"פ (כלכלית ) 64660-12-17 מגדל השעון ביפו בע\"מ נ'' רו\"ח עופר רפאל (08.12.2019)", "ה\"פ (כלכלית ) 11472-05-18 בצלאל מזרחי נ'' בית עזרת אחים חברה להקמת הבנין בע\"מ (11.12.2019)"]'::jsonb
  );
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_3, 'א', 'ההחלטה בטלה מעיקרה, שכן פגם בזימון אסיפה כללית מבטל אוטומטית כל החלטה שהתקבלה בה.', false, 'טענה זו אינה נכונה. פגם בזימון אינו מבטל אוטומטית החלטה, אלא אם כן גרם לקיפוח מהותי של בעל מניה, כפי שקובע סעיף 91 לחוק החברות.', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_3, 'ב', 'ההחלטה אינה בטלה אלא אם כן קבע בית המשפט כי הפגם בזימון גרם לקיפוח מהותי של בעל מניה.', true, 'זוהי התשובה הנכונה. סעיף 91 לחוק החברות קובע כי פגם בזימון אסיפה כללית לא יבטל החלטה, אלא אם כן קבע בית המשפט כי הפגם גרם לקיפוח מהותי של בעל מניה.', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_3, 'ג', 'ההחלטה תקפה, שכן בעלי המניות שהשתתפו באסיפה ויתרו על הפגם בזימון.', false, 'טענה זו אינה נכונה. ויתור של חלק מבעלי המניות אינו מכשיר פגם מהותי בזימון שפגע בזכויות אחרים, במיוחד אם נגרם קיפוח מהותי.', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_3, 'ד', 'ההחלטה תקפה רק אם אושרה פה אחד על ידי כל בעלי המניות, כולל אלה שלא זומנו כדין.', false, 'טענה זו אינה נכונה. אישור פה אחד יכול לרפא פגמים, אך אינו תנאי הכרחי לתוקף ההחלטה אם לא נגרם קיפוח מהותי, ואינו רלוונטי אם לא ניתן לזמן את כולם.', 4);

  RAISE NOTICE 'Q% inserted: external_id %', 28, '2022-S-S-Q28';
END
$$;

