DO $$
DECLARE
  v_sq_id uuid := '3f8d548c-05a8-4359-9360-9d3a9bdec5df'::uuid;
  v_group_id uuid := 'c442d88b-ec46-424c-9444-78fd163c7223'::uuid;
  v_chapter_id uuid;
  v_subtopic_id uuid;
  v_existing_id uuid;
  v_ang_0 uuid := '3869b5ca-1e69-4f68-897d-33963d3fb626'::uuid;
  v_ang_1 uuid := '612aa2ce-40ff-4a99-9ce7-c9403eaa34cd'::uuid;
  v_ang_2 uuid := '8ee3586f-04f3-4d52-9800-e48182d34ef7'::uuid;
  v_ang_3 uuid := '0a02e04d-a94d-43e7-8a36-79117ef3dead'::uuid;
BEGIN
