  INSERT INTO public.source_questions (
    id, question_group_id, version, is_current, external_id, chapter_id, subtopic_id, question_text, source_metadata, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list, notes_for_admin, status, created_by
  ) VALUES (
    v_sq_id, v_group_id, 1, true,
    '2022-S-S-Q29', v_chapter_id, v_subtopic_id, 'נתונות העבירות הבאות שנחקקו ביום 1.1.1988:
עבירה 1: הגורם בכוונה חבלה לאדם, דינו – מאסר עשר שנים.
עבירה 2: הגורם במזיד חבלה לאדם, דינו – מאסר שבע שנים.
עבירה 3: הגורם בהתרשלות חבלה לאדם, דינו – מאסר ארבע שנים.
עבירה 4: על אף האמור בעבירה 3, הגורם בהתרשלות חבלה לבן-זוגו, דינו – מאסר חמש שנים.
יוסף גרם חבלה ברשלנות לבת זוגו דינה ביום 1.7.2021. ביום 1.9.2021 הושלמו הליכי הגירושין ביניהם והם אינם בני זוג עוד. ביום 1.11.2021 נידון יוסף בגין מעשיו. בית המשפט קבע כי יוסף אכן גרם חבלה ברשלנות לדינה. מהו העונש המרבי שניתן לגזור על יוסף?',
    '{"exam_year": 2022, "exam_season": "summer", "exam_part": 2, "exam_question_number": 29}'::jsonb, 'שאלה זו עוסקת בעקרונות תחולת הדין הפלילי בזמן, ובפרט ביישום כלל הדין המקל (סעיף 90א לחוק העונשין) במצבים בהם חל שינוי בנסיבות העובדתיות (כגון סטטוס משפחתי) בין מועד ביצוע העבירה למועד מתן פסק הדין. היא מדגישה את ההבחנה בין הדין שהיה בתוקף בעת ביצוע העבירה לבין הדין המקל יותר שניתן להחילו במועד הדיון, תוך התייחסות לדין הכללי של חבלה ברשלנות (סעיף 341 לחוק העונשין).', 'השאלה בוחנת את עקרון תחולת הדין הפלילי בזמן, המעוגן בסעיף 90א לחוק העונשין, התשל"ז-1977. סעיף זה קובע כי ''נעברה עבירה ובטרם ניתן פסק דין חל שינוי בדין, יחול על הענין הדין שהיה קיים בעת עשיית העבירה, זולת אם קבע החוק החדש עונש קל יותר, שאז יחול הדין החדש''. סעיף 90א לחוק העונשין, התשל"ז-1977 | תחולת דין פלילי בזמן במקרה הנדון, יוסף גרם חבלה ברשלנות לדינה ביום 1.7.2021, כשהיו בני זוג. לפי עבירה 4, העונש המרבי היה 5 שנות מאסר. ביום 1.9.2021 הם התגרשו, וביום 1.11.2021 נידון יוסף. במועד הדיון, הם כבר אינם בני זוג, ולכן עבירה 4 אינה חלה עוד. במקומה, חלה עבירה 3, שדינה מאסר 4 שנים. אולם, חוק העונשין קובע בסעיף 341 עונש מרבי של 3 שנות מאסר על עבירת חבלה ברשלנות. סעיף 341 לחוק העונשין, התשל"ז-1977 | חבלה ברשלנות מאחר שבין מועד ביצוע העבירה (5 שנות מאסר) למועד מתן פסק הדין (4 שנות מאסר לפי עבירה 3, או 3 שנות מאסר לפי סעיף 341), הדין המקל ביותר הוא 3 שנות מאסר, יש להחיל את הדין המקל ביותר על פי סעיף 90א לחוק העונשין. ע"פ 4764223/16 פלוני נ'' מדינת ישראל (20.03.2019)', 'הבלבול בין הדין שהיה בתוקף בעת ביצוע העבירה לבין הדין המקל ביותר שניתן להחיל במועד מתן פסק הדין, במיוחד כאשר שינוי עובדתי (כמו גירושין) משפיע על תחולת הוראת חוק ספציפית.',
    '["תחולת דין פלילי בזמן", "דין מקל", "סעיף 90א לחוק העונשין", "חבלה ברשלנות", "שינוי סטטוס", "עונש מרבי", "דין כללי מול דין ספציפי"]'::jsonb, '**וריאציה 1 — דין מקל עקב שינוי סטטוס:** יוסף גרם חבלה ברשלנות לבת זוגו (5 שנים), התגרש, ונידון. מה העונש המרבי? ← 3 שנות מאסר, כי הדין המקל (סעיף 341 לחוק העונשין) חל לאחר שהסטטוס השתנה והדין הספציפי (עבירה 4) אינו רלוונטי עוד (סעיף 90א לחוק העונשין).
**וריאציה 2 — מועד קביעת הדין:** מתי בוחנים את הדין המקל? ← במועד מתן פסק הדין, תוך השוואה לדין שהיה בעת ביצוע העבירה.
**וריאציה 3 — דין כללי מול ספציפי:** אם הדין הספציפי (עבירה 4) אינו חל, לאיזה דין פונים? ← לדין הכללי הרלוונטי (עבירה 3 או סעיף 341 לחוק העונשין), ובוחרים את המקל מביניהם.', 'שינוי סטטוס ← בחינת הדין המקל ביותר במועד הדיון ← סעיף 90א לחוק העונשין ← 3 שנות מאסר (סעיף 341 לחוק העונשין).', '["חוק העונשין, התשל\"ז-1977, סעיפים 90א, 90ב, 341", "ע\"פ 4764223/16 פלוני נ'' מדינת ישראל (20.03.2019)"]'::jsonb,
    'classification_review: original chapter=''סדר דין פלילי'' subtopic=''הליכים'' → mapped chapter=''criminal_substantive'' subtopic=''general_part_elements'' | classifier_note: Transitional law in criminal offenses, lighter-law rule, status change — תחולת דין בזמן | source_review_note: השאלה עוסקת בדיני עונשין מהותיים (תחולת דין בזמן, דין מקל, שינוי סטטוס). בחרתי ב''הליכים'' תחת ''סדר דין פלילי'' כהצבת מקום, מכיוון שאין קטגוריה מתאימה יותר לנושאים מהותיים בדין הפלילי ברשימה הסגורה. יש לשקול הוספת פרק ''דיני עונשין'' או תת-נושא רחב יותר תחת ''סדר דין פלילי'' שיכלול נושאים מהותיים בעלי השלכות דיוניות.', 'active', 'b9ecdde2-d07e-4761-96ab-05f0ad32d4e3'
  );

  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'א', '7 שנות מאסר.', false, 'עונש זה מתייחס לעבירה שבוצעה במזיד (עבירה 2), אך יוסף גרם חבלה ברשלנות.', 1);
  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'ב', '3 שנות מאסר.', true, 'זוהי התשובה הנכונה. אף שהמעשה בוצע כשהיו בני זוג (עונש מרבי 5 שנים), וביום הדיון הם כבר לא בני זוג (עונש מרבי 4 שנים), סעיף 90א לחוק העונשין קובע כי אם חל שינוי בדין לאחר ביצוע העבירה ולפני מתן פסק הדין, יחול הדין המקל. במקרה זה, הדין המקל הוא 3 שנות מאסר, כפי שנקבע בסעיף 341 לחוק העונשין לעבירת חבלה ברשלנות, שהוא הדין הכללי המקל יותר מהדינים הספציפיים שניתנו בשאלה.', 2);
  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'ג', '4 שנות מאסר.', false, 'עונש זה מתייחס לעבירה 3 (חבלה ברשלנות לאדם שאינו בן זוג). אף שביום הדיון יוסף ודינה אינם בני זוג, ישנו דין מקל יותר (3 שנות מאסר) שחל על פי סעיף 90א לחוק העונשין.', 3);
  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'ד', '5 שנות מאסר.', false, 'עונש זה מתייחס לעבירה 4 (חבלה ברשלנות לבן זוג). עונש זה היה רלוונטי במועד ביצוע העבירה, אך במועד הדיון הם כבר אינם בני זוג, ועל פי סעיף 90א לחוק העונשין, יש להחיל את הדין המקל.', 4);

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_0, v_sq_id, 'א', 'שינוי דין מחמיר לאחר ביצוע העבירה',
    1, 'ראובן ביצע עבירה ביום 1.1.2020, שדינה היה מאסר 5 שנים. ביום 1.7.2020 נכנס לתוקף תיקון לחוק שהחמיר את העונש על אותה עבירה ל-7 שנות מאסר. ביום 1.1.2021 נידון ראובן בגין מעשיו. מהו העונש המרבי שניתן לגזור על ראובן?', 'שאלה זו בוחנת את עקרון אי-הרטרואקטיביות של דין פלילי מחמיר, כפי שמעוגן בסעיף 90א לחוק העונשין. היא מדגישה את ההגנה על הנאשם מפני החמרת עונש לאחר ביצוע העבירה.', 'סעיף 90א לחוק העונשין, התשל"ז-1977, קובע את הכלל לגבי תחולת דין פלילי בזמן. על פי הסעיף, ''נעברה עבירה ובטרם ניתן פסק דין חל שינוי בדין, יחול על הענין הדין שהיה קיים בעת עשיית העבירה, זולת אם קבע החוק החדש עונש קל יותר, שאז יחול הדין החדש''. סעיף 90א לחוק העונשין, התשל"ז-1977 | תחולת דין פלילי בזמן במקרה זה, הדין השתנה לחומרה (מ-5 ל-7 שנות מאסר). לכן, על פי הכלל, יחול הדין שהיה קיים בעת ביצוע העבירה, כלומר 5 שנות מאסר. ע"פ 4764223/16 פלוני נ'' מדינת ישראל (20.03.2019)',
    'הנחה שגויה כי הדין התקף ביום מתן פסק הדין הוא תמיד הקובע, ללא התחשבות בעקרון הדין המקל או אי-הרטרואקטיביות של דין מחמיר.', '["תחולת דין פלילי בזמן", "דין מחמיר", "אי-רטרואקטיביות", "סעיף 90א לחוק העונשין", "lex temporis acti", "עונש מרבי"]'::jsonb, '**וריאציה 1 — דין מחמיר:** אם הדין השתנה לחומרה לאחר העבירה? ← יחול הדין שהיה בעת ביצוע העבירה (סעיף 90א לחוק העונשין).
**וריאציה 2 — דין מקל:** אם הדין השתנה לקולא לאחר העבירה? ← יחול הדין החדש המקל (סעיף 90א לחוק העונשין).
**וריאציה 3 — עקרון כללי:** מהו העיקרון המנחה? ← הדין החל הוא הדין בעת ביצוע העבירה, אלא אם הדין החדש מקל (ע"פ 4764223/16).', 'דין מחמיר ← דין בעת העבירה. דין מקל ← דין חדש. (סעיף 90א לחוק העונשין).',
    '["חוק העונשין, התשל\"ז-1977, סעיף 90א", "ע\"פ 4764223/16 פלוני נ'' מדינת ישראל (20.03.2019)"]'::jsonb
  );
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_0, 'א', '7 שנות מאסר, שכן זהו הדין התקף ביום מתן פסק הדין.', false, 'טענה זו אינה נכונה. סעיף 90א לחוק העונשין קובע כי אם הדין השתנה לחומרה, יחול הדין שהיה קיים בעת ביצוע העבירה.', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_0, 'ב', '5 שנות מאסר, שכן זהו הדין שהיה קיים בעת ביצוע העבירה.', true, 'זוהי התשובה הנכונה. על פי סעיף 90א לחוק העונשין, במקרה של שינוי דין לחומרה לאחר ביצוע העבירה, יחול הדין שהיה קיים בעת ביצוע העבירה, כלומר 5 שנות מאסר.', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_0, 'ג', 'העונש ייקבע לפי שיקול דעת בית המשפט, בין 5 ל-7 שנות מאסר.', false, 'טענה זו אינה נכונה. סעיף 90א קובע כלל ברור לגבי הדין שיחול, ואינו מותיר שיקול דעת לבית המשפט לבחור בין הדינים.', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_0, 'ד', 'העבירה בטלה, שכן לא ניתן להחיל דין מחמיר רטרואקטיבית.', false, 'טענה זו אינה נכונה. העבירה אינה בטלה, אלא שעל פי סעיף 90א, לא יחול הדין המחמיר החדש, אלא הדין שהיה קיים בעת ביצוע העבירה.', 4);

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_1, v_sq_id, 'ב', 'הגדרת "חוק שעה" ותחולתו',
    2, 'חוק חדש קבע עונש מאסר של 10 שנים על עבירה מסוימת, וצוין בו כי תוקפו לשנה אחת בלבד. ראובן ביצע את העבירה במהלך תקופה זו. לאחר תום השנה, החוק פקע והעונש המקורי על העבירה חזר להיות 5 שנות מאסר. מהו העונש המרבי שניתן לגזור על ראובן?', 'שאלה זו בוחנת את עקרון תחולתו של ''חוק שעה'' (חוק זמני) בדין הפלילי, כפי שמעוגן בסעיף 90ב לחוק העונשין. היא מדגישה את הכלל לפיו חוק שעה חל על עבירות שבוצעו בתקופת תוקפו, גם אם פקע לאחר מכן.', 'סעיף 90ב לחוק העונשין, התשל"ז-1977, קובע כי ''נעברה עבירה בתקופת תוקפו של חוק שעה, יחול חוק השעה, זולת אם נקבע בו אחרת''. סעיף 90ב לחוק העונשין, התשל"ז-1977 | תחולת דין פלילי בזמן חוק שעה הוא חוק בעל תוקף מוגבל בזמן, והכלל הוא שהוא ממשיך לחול על עבירות שבוצעו בתקופת תוקפו, גם אם פקע לפני מתן פסק הדין. זאת בניגוד לכלל הכללי של הדין המקל שבסעיף 90א, שאינו חל על חוקי שעה, אלא אם נקבע אחרת בחוק השעה עצמו. ע"פ 4764223/16 פלוני נ'' מדינת ישראל (20.03.2019)',
    'בלבול בין הכלל של הדין המקל (סעיף 90א) לבין הכלל הייחודי של חוק שעה (סעיף 90ב), והנחה שגויה כי הדין המקל יחול גם במקרה של חוק שעה שפקע.', '["חוק שעה", "תחולת דין פלילי בזמן", "סעיף 90ב לחוק העונשין", "פקיעת חוק", "דין מקל", "עונש מרבי"]'::jsonb, '**וריאציה 1 — חוק שעה ופקיעה:** האם חוק שעה שפקע עדיין חל על עבירה שבוצעה בתקופת תוקפו? ← כן, אלא אם נקבע אחרת בחוק השעה (סעיף 90ב לחוק העונשין).
**וריאציה 2 — חוק שעה מול דין מקל:** האם עקרון הדין המקל חל על חוק שעה? ← לא, סעיף 90ב הוא חריג לכלל הדין המקל (ע"פ 4764223/16).
**וריאציה 3 — תכלית חוק שעה:** מהי תכלית חוק שעה? ← להתמודד עם מצבים זמניים הדורשים תגובה עונשית חריגה, תוך שמירה על תחולתו לגבי מעשים שבוצעו בתקופתו.', 'חוק שעה ← חל על עבירות שבוצעו בתקופתו ← גם אם פקע (סעיף 90ב לחוק העונשין).',
    '["חוק העונשין, התשל\"ז-1977, סעיף 90ב", "ע\"פ 4764223/16 פלוני נ'' מדינת ישראל (20.03.2019)"]'::jsonb
  );
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_1, 'א', '5 שנות מאסר, שכן זהו הדין המקל החל לאחר פקיעת חוק השעה.', false, 'טענה זו אינה נכונה. סעיף 90ב לחוק העונשין קובע כי חוק שעה חל על עבירות שבוצעו בתקופת תוקפו, גם אם פקע לאחר מכן.', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_1, 'ב', '10 שנות מאסר, שכן חוק שעה חל על עבירות שבוצעו בתקופת תוקפו.', true, 'זוהי התשובה הנכונה. על פי סעיף 90ב לחוק העונשין, ''נעברה עבירה בתקופת תוקפו של חוק שעה, יחול חוק השעה, זולת אם נקבע בו אחרת''. לכן, העונש המרבי הוא 10 שנות מאסר.', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_1, 'ג', 'העונש ייקבע לפי שיקול דעת בית המשפט, בין 5 ל-10 שנות מאסר.', false, 'טענה זו אינה נכונה. סעיף 90ב קובע כלל ברור לגבי תחולת חוק שעה, ואינו מותיר שיקול דעת לבית המשפט לבחור בין הדינים.', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_1, 'ד', 'העבירה בטלה, שכן חוק שעה אינו יכול להחיל עונש מחמיר לאחר פקיעתו.', false, 'טענה זו אינה נכונה. חוק שעה חל על עבירות שבוצעו בתקופת תוקפו, ואינו בטל רטרואקטיבית.', 4);

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_2, v_sq_id, 'ג', 'שינוי סטטוס משפטי והשפעתו על העונש',
    3, 'שרה גרמה חבלה חמורה בכוונה לאביה ביום 1.3.2022, עבירה שדינה מאסר 10 שנים. ביום 1.5.2022 נכנס לתוקף תיקון לחוק העונשין שקבע כי עבירה זו, אם בוצעה כלפי הורה, דינה מאסר 15 שנים. ביום 1.7.2022 נפטרה האם, ושרה הפכה ליתומה. ביום 1.9.2022 נידונה שרה בגין מעשיה. מהו העונש המרבי שניתן לגזור על שרה?', 'שאלה זו בוחנת את עקרון תחולת הדין הפלילי בזמן במקרה של שינוי דין מחמיר, תוך התייחסות לשינוי בסטטוס המשפטי של הנאשם או הקורבן. היא מדגישה כי הדין הקובע הוא זה שהיה בתוקף בעת ביצוע העבירה, וכי שינוי סטטוס מאוחר אינו משנה את אופי העבירה שבוצעה.', 'על פי סעיף 90א לחוק העונשין, התשל"ז-1977, אם חל שינוי בדין לאחר ביצוע העבירה ולפני מתן פסק הדין, יחול הדין שהיה קיים בעת עשיית העבירה, זולת אם קבע החוק החדש עונש קל יותר. במקרה זה, הדין החדש מחמיר את העונש מ-10 ל-15 שנות מאסר כאשר העבירה בוצעה כלפי הורה. לכן, יחול הדין שהיה קיים בעת ביצוע העבירה, כלומר 10 שנות מאסר. הסטטוס של ''הורה'' נבחן במועד ביצוע העבירה, ופטירת האם לאחר מכן אינה משנה את העובדה שהעבירה בוצעה כלפי הורה באותו מועד. ע"פ 4764223/16 פלוני נ'' מדינת ישראל (20.03.2019)',
    'הנחה שגויה כי שינוי בסטטוס המשפחתי או האישי של הנאשם או הקורבן לאחר ביצוע העבירה משפיע על תחולת הדין הפלילי, במיוחד כאשר הדין החדש מחמיר.', '["תחולת דין פלילי בזמן", "דין מחמיר", "אי-רטרואקטיביות", "סעיף 90א לחוק העונשין", "סטטוס משפטי", "עונש מרבי"]'::jsonb, '**וריאציה 1 — דין מחמיר וסטטוס:** האם דין מחמיר חל רטרואקטיבית גם אם הסטטוס השתנה? ← לא, יחול הדין שהיה בעת ביצוע העבירה (סעיף 90א לחוק העונשין).
**וריאציה 2 — מועד קביעת הסטטוס:** מתי נקבע הסטטוס הרלוונטי לעבירה? ← במועד ביצוע העבירה.
**וריאציה 3 — עקרון הדין המקל:** האם שינוי סטטוס יכול להפוך דין למקל? ← לא, עקרון הדין המקל מתייחס לשינוי בחוק עצמו, לא לשינוי עובדתי בסטטוס.', 'דין מחמיר ← דין בעת העבירה. סטטוס ← נקבע בעת העבירה. (סעיף 90א לחוק העונשין).',
    '["חוק העונשין, התשל\"ז-1977, סעיף 90א", "ע\"פ 4764223/16 פלוני נ'' מדינת ישראל (20.03.2019)"]'::jsonb
  );
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_2, 'א', '10 שנות מאסר, שכן זהו הדין שהיה קיים בעת ביצוע העבירה, והדין החדש מחמיר.', true, 'זוהי התשובה הנכונה. הדין החדש (15 שנות מאסר) מחמיר, ולכן על פי סעיף 90א לחוק העונשין, יחול הדין שהיה קיים בעת ביצוע העבירה, כלומר 10 שנות מאסר. שינוי הסטטוס של שרה ליתומה אינו משנה את העובדה שהעבירה בוצעה כלפי הורה.', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_2, 'ב', '15 שנות מאסר, שכן זהו הדין התקף ביום מתן פסק הדין, והעבירה בוצעה כלפי הורה.', false, 'טענה זו אינה נכונה. אף שהדין החדש קובע 15 שנות מאסר, הוא מחמיר, ולכן לא יחול רטרואקטיבית על פי סעיף 90א לחוק העונשין.', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_2, 'ג', 'העונש ייקבע לפי שיקול דעת בית המשפט, בין 10 ל-15 שנות מאסר.', false, 'טענה זו אינה נכונה. סעיף 90א קובע כלל ברור לגבי הדין שיחול, ואינו מותיר שיקול דעת לבית המשפט לבחור בין הדינים.', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_2, 'ד', 'העבירה בטלה, שכן הסטטוס של ''הורה'' אינו קיים עוד ביום הדיון.', false, 'טענה זו אינה נכונה. הסטטוס של ''הורה'' נבחן במועד ביצוע העבירה. פטירת האם לאחר מכן אינה מבטלת את העבירה או את העובדה שהיא בוצעה כלפי הורה.', 4);

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_3, v_sq_id, 'ד', 'הבחנה בין דין ספציפי לדין כללי',
    4, 'חוק העונשין קובע בסעיף 341 עונש מרבי של 3 שנות מאסר על עבירת חבלה ברשלנות. נניח כי חוק ספציפי אחר, שנחקק מאוחר יותר, קובע עונש מרבי של 4 שנות מאסר על ''חבלה ברשלנות שנגרמה תוך כדי נהיגה''. ראובן גרם חבלה ברשלנות תוך כדי נהיגה. מהו העונש המרבי שניתן לגזור עליו?', 'שאלה זו בוחנת את כלל הפרשנות המשפטית של ''דין ספציפי גובר על דין כללי'' (lex specialis derogat legi generali). היא מדגישה כי כאשר קיימים שני חוקים המתייחסים לאותו עניין, החוק הספציפי יותר הוא שיחול, גם אם הוא מחמיר יותר מהחוק הכללי.', 'הכלל המשפטי המנחה במקרה של התנגשות בין דין כללי לדין ספציפי הוא ש''דין ספציפי גובר על דין כללי'' (lex specialis derogat legi generali). כלל זה קובע כי כאשר קיימת הוראת חוק כללית והוראת חוק ספציפית המתייחסות לאותו עניין, ההוראה הספציפית היא שתחול. במקרה זה, סעיף 341 לחוק העונשין הוא דין כללי לעבירת חבלה ברשלנות (3 שנות מאסר), ואילו החוק הספציפי קובע עונש של 4 שנות מאסר על ''חבלה ברשלנות שנגרמה תוך כדי נהיגה''. מאחר שהמעשה של ראובן נופל בגדר ההגדרה הספציפית, יחול הדין הספציפי, כלומר 4 שנות מאסר. ע"פ 4764223/16 פלוני נ'' מדינת ישראל (20.03.2019)',
    'הנחה שגויה כי הדין המקל תמיד גובר, גם במקרה של התנגשות בין דין כללי לספציפי, או אי-הכרת כלל ה-lex specialis.', '["דין ספציפי", "דין כללי", "lex specialis", "התנגשות דינים", "חבלה ברשלנות", "עונש מרבי"]'::jsonb, '**וריאציה 1 — כלל ההתנגשות:** מה קורה כשיש דין כללי ודין ספציפי? ← הדין הספציפי גובר על הדין הכללי (lex specialis).
**וריאציה 2 — דין ספציפי מחמיר:** האם דין ספציפי מחמיר גובר על דין כללי מקל? ← כן, אלא אם נקבע אחרת במפורש (ע"פ 4764223/16).
**וריאציה 3 — יישום:** ראובן גרם חבלה ברשלנות בנהיגה (4 שנים) מול חבלה ברשלנות כללית (3 שנים)? ← 4 שנות מאסר, כי הדין הספציפי גובר.', 'דין ספציפי גובר על דין כללי ← גם אם מחמיר.',
    '["חוק העונשין, התשל\"ז-1977, סעיף 341", "ע\"פ 4764223/16 פלוני נ'' מדינת ישראל (20.03.2019)"]'::jsonb
  );
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_3, 'א', '3 שנות מאסר, שכן זהו הדין הכללי המקל יותר.', false, 'טענה זו אינה נכונה. במקרה של התנגשות בין דין כללי לדין ספציפי, הדין הספציפי גובר, אלא אם כן יש הוראה מפורשת אחרת.', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_3, 'ב', '4 שנות מאסר, שכן זהו הדין הספציפי הגובר על הדין הכללי.', true, 'זוהי התשובה הנכונה. הכלל הוא שדין ספציפי גובר על דין כללי (lex specialis derogat legi generali). במקרה זה, החוק הספציפי קובע עונש מחמיר יותר עבור חבלה ברשלנות תוך כדי נהיגה, ולכן הוא יחול.', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_3, 'ג', 'העונש ייקבע לפי שיקול דעת בית המשפט, בין 3 ל-4 שנות מאסר.', false, 'טענה זו אינה נכונה. קיימים כללים ברורים ליישוב התנגשויות בין דינים, ואין זה נתון לשיקול דעת בית המשפט לבחור ביניהם באופן חופשי.', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_3, 'ד', 'העבירה בטלה, שכן קיימת סתירה בין שני חוקים.', false, 'טענה זו אינה נכונה. קיומם של שני חוקים המתייחסים לאותה עבירה אינו מבטל את העבירה, אלא מחייב יישוב ההתנגשות ביניהם על פי כללי פרשנות מקובלים.', 4);

  RAISE NOTICE 'Q% inserted: external_id %', 29, '2022-S-S-Q29';
END
$$;

