-- classifier_note: Co-conspirators in robbery, Reuven's bodily harm beyond Leah & Shimon's agreement — accomplice liability for additional offense
-- ============================================================
DO $$
DECLARE
  v_sq_id uuid := 'af66447d-acba-4039-8a45-f4c5bf8f2469'::uuid;
  v_group_id uuid := 'e1d41d0d-0f55-48f2-a15d-96bbec0f87d7'::uuid;
  v_chapter_id uuid;
  v_subtopic_id uuid;
  v_existing_id uuid;
  v_ang_0 uuid := 'ebf1e8a9-8301-4a5d-a78a-4de352eb14c1'::uuid;
  v_ang_1 uuid := '7836d9a8-420a-48b1-989d-bef820504dc5'::uuid;
  v_ang_2 uuid := 'f1392bfd-deb0-4212-962e-d102dc2893e9'::uuid;
  v_ang_3 uuid := '86419103-acb4-4704-8750-b15da0623791'::uuid;
BEGIN
  SELECT id INTO v_existing_id FROM public.source_questions WHERE external_id = '2022-S-S-Q31';
  IF v_existing_id IS NOT NULL THEN
    RAISE NOTICE 'Q% skipped: external_id % already exists', 31, '2022-S-S-Q31';
    RETURN;
  END IF;

  SELECT id INTO v_chapter_id FROM public.chapters WHERE code = 'criminal_substantive';
  IF v_chapter_id IS NULL THEN
    RAISE EXCEPTION 'Chapter code % not found', 'criminal_substantive';
  END IF;

  SELECT id INTO v_subtopic_id FROM public.subtopics WHERE code = 'general_part_elements' AND chapter_id = v_chapter_id;
  IF v_subtopic_id IS NULL THEN
    RAISE EXCEPTION 'Subtopic code % not found under chapter %', 'general_part_elements', 'criminal_substantive';
  END IF;

  INSERT INTO public.source_questions (
    id, question_group_id, version, is_current, external_id, chapter_id, subtopic_id, question_text, source_metadata, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list, notes_for_admin, status, created_by
  ) VALUES (
    v_sq_id, v_group_id, 1, true,
    '2022-S-S-Q31', v_chapter_id, v_subtopic_id, 'לאה שידלה את ראובן ואת שמעון לבצע בצוותא שוד. במהלך השוד גרם ראובן בכוונה חבלה למאבטח שניסה למנוע את השוד, וזאת בלי ידיעה או הסכמה של שמעון או של לאה. אדם סביר יכול היה להיות מודע בנסיבות העניין שראובן יחבול במאבטח. לשמעון וללאה נודע על חבלתו של המאבטח רק לאחר שהשוד הסתיים. מהי האחריות הפלילית של לאה לחבלת המאבטח?',
    '{"exam_year": 2022, "exam_season": "summer", "exam_part": 2, "exam_question_number": 31}'::jsonb, 'שאלה זו עוסקת באחריות פלילית של משדל לעבירה שונה או נוספת שבוצעה על ידי אחד המבצעים, על פי סעיף 34א לחוק העונשין. היא בוחנת את התנאים להטלת אחריות זו, ובפרט את היסוד הנפשי המיוחס למשדל (רשלנות) כאשר העבירה הנוספת בוצעה בכוונה, ואת מבחן הצפיות האובייקטיבי של ''אדם מן היישוב''.', 'סעיף 34א לחוק העונשין, שכותרתו ''עבירה שונה או נוספת'', מרחיב את גבולות האחריות הפלילית של שותפים לעבירה. הסעיף קובע כי אם מבצע עבר עבירה שונה ממנה או נוספת לה אגב עשיית העבירה המקורית, כאשר בנסיבות העניין אדם מן היישוב יכול היה להיות מודע לאפשרות עשייתה, יישאו באחריות לה גם המבצעים בצוותא הנותרים. סעיף 34א(א)(1) לחוק העונשין, תשל"ז-1977 | עבירה שונה או נוספת יחד עם זאת, הסיפה של סעיף 34א(א)(1) קובעת כי אם העבירה השונה או הנוספת נעברה בכוונה, יישאו המבצעים הנותרים באחריות לה כעל עבירה של אדישות בלבד. סעיף 34א(א)(1) לחוק העונשין, תשל"ז-1977 | עבירה שונה או נוספת סעיף 34א(א)(2) קובע כי אם העבירה השונה או הנוספת נעברה בכוונה, יישאו המשדל או המסייע באחריות לה כעל עבירה של רשלנות בלבד. סעיף 34א(א)(2) לחוק העונשין, תשל"ז-1977 | עבירה שונה או נוספת במקרה הנדון, ראובן גרם חבלה בכוונה (עבירה 1). לאה שידלה את השוד, ואדם מן היישוב יכול היה לצפות את החבלה. לכן, לאה, כמשדלת, תישא באחריות לחבלה כעל עבירה של רשלנות. מבין העבירות הנתונות, עבירה 3 (''הגורם בהתרשלות חבלה לאדם, דינו – מאסר ארבע שנים'') היא המתאימה ביותר ליסוד נפשי של רשלנות בהקשר זה. ע"פ 1639/98 משה דהן נ'' מדינת ישראל (18.06.2001)', 'הבלבול בין היסוד הנפשי הנדרש לעבירה המקורית לבין היסוד הנפשי המיוחס לשותפים לעבירה שונה או נוספת, ובפרט אי-ההבחנה בין כוונה לאדישות או רשלנות בהקשר של סעיף 34א.',
    '["עבירה שונה או נוספת", "משדל", "מבצע בצוותא", "אחריות נגררת", "אדישות", "רשלנות", "כוונה", "סעיף 34א לחוק העונשין", "יסוד נפשי"]'::jsonb, '**וריאציה 1 — אחריות משדל לעבירה נוספת בכוונה:** לאה שידלה שוד, ראובן חבל בכוונה. מה אחריות לאה? ← אחריות כעל עבירה של רשלנות (סעיף 34א(א)(2) לחוק העונשין).
**וריאציה 2 — התאמת עבירה:** איזו עבירה מתאימה לרשלנות מבין הנתונות? ← עבירה 3 (חבלה בהתרשלות), שדינה 4 שנות מאסר.
**וריאציה 3 — תנאי הצפיות:** האם נדרשת מודעות בפועל של לאה? ← לא, מספיקה צפיות בכוח של ''אדם מן היישוב'' (ע"פ 1639/98).', 'משדל ← עבירה שונה/נוספת בכוונה ← אחריות ברשלנות (סעיף 34א(א)(2)) ← עונש לפי עבירת רשלנות קיימת.', '["חוק העונשין, תשל\"ז-1977, סעיף 34א", "ע\"פ 1639/98 משה דהן נ'' מדינת ישראל (18.06.2001)", "ע\"פ 2917335 פלוני נ'' מדינת ישראל (09.10.2013)", "יורם רבין, יניב ואקי דיני עונשין - כרך א (2014) | פרק 18 - צדדים לעבירה", "נבו - המתמחה דיני עונשין ודרכי ענישה (2026) | חוק העונשין, התשל\"ז-1977"]'::jsonb,
    'classification_review: original chapter=''סדר דין פלילי'' subtopic=''הליכים'' → mapped chapter=''criminal_substantive'' subtopic=''general_part_elements'' | classifier_note: Co-conspirators in robbery, Reuven''s bodily harm beyond Leah & Shimon''s agreement — accomplice liability for additional offense | source_review_note: השאלה עוסקת בדיני עונשין מהותיים (אחריות שותפים לעבירה שונה או נוספת). בחרתי ב''הליכים'' תחת ''סדר דין פלילי'' כהצבת מקום, מכיוון שאין קטגוריה מתאימה יותר לנושאים מהותיים בדין הפלילי ברשימה הסגורה. יש לשקול הוספת פרק ''דיני עונשין'' או תת-נושא רחב יותר תחת ''סדר דין פלילי'' שיכלול נושאים מהותיים בעלי השלכות דיוניות.', 'active', 'b9ecdde2-d07e-4761-96ab-05f0ad32d4e3'
  );

  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'א', 'אין ללאה אחריות פלילית בגין חבלת המאבטח.', false, 'טענה זו אינה נכונה. סעיף 34א(א)(2) לחוק העונשין מרחיב את האחריות הפלילית של משדל לעבירה שונה או נוספת שבוצעה על ידי מבצע, גם אם לא היה מודע בפועל, ובלבד שאדם מן היישוב יכול היה לצפות זאת.', 1);
  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'ב', 'לאה תישא באחריות פלילית בעבירה 1 בגין חבלת המאבטח.', false, 'עבירה 1 היא חבלה בכוונה. סעיף 34א(א)(2) לחוק העונשין קובע כי משדל יישא באחריות לעבירה שונה או נוספת שבוצעה בכוונה כעל עבירה של רשלנות בלבד, ולא כעל עבירת כוונה.', 0);
  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'ג', 'לאה תישא באחריות פלילית בעבירה 2 בגין חבלת המאבטח.', false, 'עבירה 2 היא חבלה במזיד/אדישות. סעיף 34א(א)(2) לחוק העונשין קובע כי משדל יישא באחריות לעבירה שונה או נוספת שבוצעה בכוונה כעל עבירה של רשלנות בלבד, שהיא יסוד נפשי קל יותר מאדישות.', 0);
  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'ד', 'לאה תישא באחריות פלילית בעבירה 3 בגין חבלת המאבטח.', true, 'זוהי התשובה הנכונה. ראובן ביצע עבירה של חבלה בכוונה (עבירה 1). מאחר שלאה שידלה את השוד, אדם מן היישוב יכול היה לצפות את החבלה, הרי שלפי סעיף 34א(א)(2) לחוק העונשין, לאה תישא באחריות כעל עבירה של רשלנות בלבד. עבירה 3, ''הגורם בהתרשלות חבלה לאדם'', מתאימה ליסוד נפשי של רשלנות.', 0);

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_0, v_sq_id, 'א', 'אחריות מסייע לעבירה שונה או נוספת',
    1, 'לאה שידלה את ראובן ואת שמעון לבצע בצוותא שוד. במהלך השוד גרם ראובן בכוונה חבלה למאבטח שניסה למנוע את השוד, וזאת בלי ידיעה או הסכמה של שמעון או של לאה. אדם סביר יכול היה להיות מודע בנסיבות העניין שראובן יחבול במאבטח. לשמעון וללאה נודע על חבלתו של המאבטח רק לאחר שהשוד הסתיים. מהי האחריות הפלילית של שמעון לחבלת המאבטח, אם תפקידו היה לסייע בלבד?', 'שאלה זו בוחנת את אחריותו הפלילית של מסייע לעבירה שונה או נוספת שבוצעה על ידי המבצע, על פי סעיף 34א(א)(2) לחוק העונשין. היא מדגישה כי ההוראה חלה באופן זהה על משדל ומסייע, ומייחסת להם יסוד נפשי של רשלנות כאשר העבירה הנוספת בוצעה בכוונה.', 'סעיף 34א לחוק העונשין, שכותרתו ''עבירה שונה או נוספת'', מרחיב את גבולות האחריות הפלילית של שותפים לעבירה. סעיף 34א(א)(2) קובע כי אם מבצע עבר עבירה שונה או נוספת אגב עשיית העבירה המקורית, כאשר אדם מן היישוב יכול היה להיות מודע לאפשרות עשייתה, יישא באחריות לה גם המשדל או המסייע, כעל עבירה של רשלנות, אם קיימת עבירה כזאת באותו יסוד עובדתי. סעיף 34א(א)(2) לחוק העונשין, תשל"ז-1977 | עבירה שונה או נוספת במקרה זה, ראובן ביצע חבלה בכוונה (עבירה 1). שמעון סייע לשוד, ואדם מן היישוב יכול היה לצפות את החבלה. לכן, שמעון, כמסייע, יישא באחריות כעל עבירה של רשלנות. מבין העבירות הנתונות, עבירה 3 (''הגורם בהתרשלות חבלה לאדם, דינו – מאסר ארבע שנים'') היא עבירת רשלנות המתאימה. ע"פ 6365/12 פלוני נ'' מדינת ישראל (09.10.2013)',
    'הנחה שגויה כי אחריות מסייע שונה מאחריות משדל לעניין סעיף 34א, או בלבול בין היסוד הנפשי המיוחס למסייע (רשלנות) לבין זה המיוחס למבצע בצוותא (אדישות).', '["עבירה שונה או נוספת", "מסייע", "אחריות נגררת", "רשלנות", "סעיף 34א לחוק העונשין", "יסוד נפשי"]'::jsonb, '**וריאציה 1 — אחריות מסייע:** מהי אחריות מסייע לעבירה שונה או נוספת שבוצעה בכוונה? ← רשלנות (סעיף 34א(א)(2) לחוק העונשין).
**וריאציה 2 — עונש מרבי למסייע:** מה העונש המרבי לשמעון כמסייע? ← 4 שנות מאסר (עבירה 3).
**וריאציה 3 — השוואה למשדל:** האם אחריות מסייע זהה לאחריות משדל לפי סעיף 34א(א)(2)? ← כן, שניהם נושאים באחריות כעל עבירת רשלנות.', 'מסייע ← עבירה שונה/נוספת בכוונה ← אחריות ברשלנות (סעיף 34א(א)(2)) ← עונש לפי עבירת רשלנות קיימת.',
    '["חוק העונשין, תשל\"ז-1977, סעיף 34א", "ע\"פ 6365/12 פלוני נ'' מדינת ישראל (09.10.2013)", "אסף הרדוף, אשמים: טרילוגיה של משפט פלילי ‏- כרך ‏I דיני עונשין (2025) | פרק 42: צדדים לעבירה"]'::jsonb
  );
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_0, 'א', 'שמעון יישא באחריות פלילית בעבירה 1 בגין חבלת המאבטח.', false, 'עבירה 1 היא חבלה בכוונה. סעיף 34א(א)(2) לחוק העונשין קובע כי מסייע יישא באחריות לעבירה שונה או נוספת שבוצעה בכוונה כעל עבירה של רשלנות בלבד, ולא כעל עבירת כוונה.', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_0, 'ב', 'שמעון יישא באחריות פלילית בעבירה 2 בגין חבלת המאבטח.', false, 'עבירה 2 היא חבלה במזיד/אדישות. סעיף 34א(א)(2) לחוק העונשין קובע כי מסייע יישא באחריות לעבירה שונה או נוספת שבוצעה בכוונה כעל עבירה של רשלנות בלבד, שהיא יסוד נפשי קל יותר מאדישות.', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_0, 'ג', 'שמעון יישא באחריות פלילית בעבירה 3 בגין חבלת המאבטח.', true, 'זוהי התשובה הנכונה. ראובן ביצע עבירה של חבלה בכוונה (עבירה 1). מאחר ששמעון סייע לשוד, אדם מן היישוב יכול היה לצפות את החבלה, הרי שלפי סעיף 34א(א)(2) לחוק העונשין, שמעון יישא באחריות כעל עבירה של רשלנות בלבד. עבירה 3, ''הגורם בהתרשלות חבלה לאדם'', מתאימה ליסוד נפשי של רשלנות.', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_0, 'ד', 'אין לשמעון אחריות פלילית בגין חבלת המאבטח.', false, 'טענה זו אינה נכונה. סעיף 34א(א)(2) לחוק העונשין מרחיב את האחריות הפלילית של מסייע לעבירה שונה או נוספת שבוצעה על ידי מבצע, גם אם לא היה מודע בפועל, ובלבד שאדם מן היישוב יכול היה לצפות זאת.', 4);

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_1, v_sq_id, 'ב', 'היסוד הנפשי המיוחס לשותפים בעבירה שונה או נוספת',
    2, 'מהו היסוד הנפשי המיוחס למבצע בצוותא ולמשדל/מסייע, בהתאמה, לעבירה שונה או נוספת שבוצעה בכוונה על ידי אחד המבצעים, לפי סעיף 34א לחוק העונשין?', 'שאלה זו מתמקדת בהבחנה הקריטית ביסוד הנפשי המיוחס לסוגי השותפים השונים (מבצע בצוותא מול משדל/מסייע) כאשר מדובר באחריות לעבירה שונה או נוספת שבוצעה בכוונה על ידי אחד המבצעים, על פי סעיף 34א לחוק העונשין.', 'סעיף 34א לחוק העונשין מבחין בין היסוד הנפשי המיוחס למבצע בצוותא לבין זה המיוחס למשדל או מסייע, כאשר העבירה השונה או הנוספת בוצעה בכוונה על ידי אחד המבצעים. סעיף 34א(א)(1) קובע כי אם העבירה השונה או הנוספת נעברה בכוונה, יישאו המבצעים בצוותא הנותרים באחריות לה כעל עבירה של אדישות בלבד. סעיף 34א(א)(1) לחוק העונשין, תשל"ז-1977 | עבירה שונה או נוספת לעומת זאת, סעיף 34א(א)(2) קובע כי אם העבירה השונה או הנוספת נעברה בכוונה, יישאו המשדל או המסייע באחריות לה כעל עבירה של רשלנות בלבד. סעיף 34א(א)(2) לחוק העונשין, תשל"ז-1977 | עבירה שונה או נוספת',
    'בלבול בין היסוד הנפשי המיוחס למבצע בצוותא (אדישות) לבין זה המיוחס למשדל/מסייע (רשלנות) במקרה של עבירה שונה או נוספת שבוצעה בכוונה.', '["יסוד נפשי", "עבירה שונה או נוספת", "מבצע בצוותא", "משדל", "מסייע", "אדישות", "רשלנות", "סעיף 34א לחוק העונשין"]'::jsonb, '**וריאציה 1 — יסוד נפשי למבצע בצוותא:** מהו היסוד הנפשי המיוחס למבצע בצוותא לעבירה נוספת בכוונה? ← אדישות (סעיף 34א(א)(1) לחוק העונשין).
**וריאציה 2 — יסוד נפשי למשדל/מסייע:** מהו היסוד הנפשי המיוחס למשדל/מסייע לעבירה נוספת בכוונה? ← רשלנות (סעיף 34א(א)(2) לחוק העונשין).
**וריאציה 3 — הבחנה:** מדוע יש הבחנה ביסוד הנפשי בין סוגי השותפים? ← ההבחנה משקפת את מידת הקרבה והשליטה של כל שותף לביצוע העבירה הנוספת.', 'עבירה נוספת בכוונה ← מבצע בצוותא: אדישות. משדל/מסייע: רשלנות (סעיף 34א לחוק העונשין).',
    '["חוק העונשין, תשל\"ז-1977, סעיף 34א", "אסף הרדוף, אשמים: טרילוגיה של משפט פלילי ‏- כרך ‏I דיני עונשין (2025) | פרק 42: צדדים לעבירה"]'::jsonb
  );
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_1, 'א', 'למבצע בצוותא - כוונה; למשדל/מסייע - אדישות.', false, 'טענה זו אינה נכונה. למבצע בצוותא מיוחס יסוד נפשי של אדישות, ולא כוונה, כאשר העבירה הנוספת בוצעה בכוונה על ידי שותפו.', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_1, 'ב', 'למבצע בצוותא - אדישות; למשדל/מסייע - רשלנות.', true, 'זוהי התשובה הנכונה. סעיף 34א(א)(1) לחוק העונשין קובע כי למבצע בצוותא מיוחס יסוד נפשי של אדישות, וסעיף 34א(א)(2) קובע כי למשדל/מסייע מיוחס יסוד נפשי של רשלנות, כאשר העבירה הנוספת בוצעה בכוונה.', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_1, 'ג', 'למבצע בצוותא - רשלנות; למשדל/מסייע - כוונה.', false, 'טענה זו אינה נכונה. היסודות הנפשיים המיוחסים הפוכים מהקבוע בחוק, ואינם תואמים את ההבחנה בין סוגי השותפים.', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_1, 'ד', 'לשניהם - רשלנות.', false, 'טענה זו אינה נכונה. ישנה הבחנה ברורה ביסוד הנפשי המיוחס למבצע בצוותא (אדישות) לבין זה המיוחס למשדל/מסייע (רשלנות).', 4);

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_2, v_sq_id, 'ג', 'עבירה שונה או נוספת שלא ניתן היה לצפות',
    3, 'לאה שידלה את ראובן ואת שמעון לבצע בצוותא שוד. במהלך השוד, ראובן, ללא כל סימן מוקדם או צפיות סבירה, החליט לפתע לרצוח את המאבטח. אדם סביר לא יכול היה להיות מודע בנסיבות העניין שראובן ירצח את המאבטח. מהי האחריות הפלילית של לאה לרצח המאבטח?', 'שאלה זו בוחנת את הגבולות של אחריות נגררת לפי סעיף 34א לחוק העונשין, ובפרט את חשיבותו של תנאי הצפיות בכוח (''אדם מן היישוב יכול היה להיות מודע לאפשרות עשייתה''). היא מדגימה מצב שבו סטייה קיצונית מהתכנון המקורי, שאינה ניתנת לצפייה סבירה, מנתקת את הקשר לאחריות נגררת.', 'סעיף 34א לחוק העונשין מטיל אחריות נגררת על שותפים לעבירה שונה או נוספת שבוצעה על ידי אחד המבצעים, אך זאת רק בתנאי ש''בנסיבות העניין, אדם מן היישוב יכול היה להיות מודע לאפשרות עשייתה''. סעיף 34א(א) לחוק העונשין, תשל"ז-1977 | עבירה שונה או נוספת תנאי זה הוא מהותי, ובלעדיו לא תוטל אחריות נגררת. במקרה זה, אם אדם סביר לא יכול היה לצפות את מעשה הרצח, הרי שלא מתקיים התנאי של צפיות בכוח, ולכן לאה לא תישא באחריות פלילית לרצח המאבטח מכוח סעיף 34א. ע"פ 517/08 סעדיה בינייב נ'' מדינת ישראל (29.06.2009)',
    'הנחה שגויה כי כל עבירה שבוצעה במהלך אירוע עברייני משותף תגרור אחריות נגררת, ללא בחינת תנאי הצפיות בכוח.', '["עבירה שונה או נוספת", "צפיות בכוח", "אדם מן היישוב", "סעיף 34א לחוק העונשין", "אחריות נגררת", "סטייה מהתכנון"]'::jsonb, '**וריאציה 1 — אי-צפיות:** אם עבירה נוספת לא הייתה צפויה על ידי אדם סביר? ← אין אחריות נגררת לפי סעיף 34א לחוק העונשין.
**וריאציה 2 — תנאי הכרחי:** מהו התנאי ההכרחי להטלת אחריות לפי סעיף 34א? ← צפיות בכוח של ''אדם מן היישוב''.
**וריאציה 3 — גבולות האחריות:** מהם גבולות האחריות הנגררת? ← היא אינה בלתי מוגבלת, ומוגבלת למקרים שבהם העבירה הנוספת הייתה ניתנת לצפייה סבירה.', 'עבירה נוספת לא צפויה ← אין אחריות נגררת (סעיף 34א לחוק העונשין).',
    '["חוק העונשין, תשל\"ז-1977, סעיף 34א", "ע\"פ 517/08 סעדיה בינייב נ'' מדינת ישראל (29.06.2009)"]'::jsonb
  );
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_2, 'א', 'לאה תישא באחריות פלילית לרצח המאבטח, שכן היא שידלה את השוד שבמהלכו בוצע הרצח.', false, 'טענה זו אינה נכונה. סעיף 34א לחוק העונשין דורש צפיות בכוח של ''אדם מן היישוב'' כתנאי להטלת אחריות לעבירה שונה או נוספת.', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_2, 'ב', 'לאה תישא באחריות פלילית לרצח המאבטח כעל עבירה של רשלנות בלבד.', false, 'טענה זו אינה נכונה. היסוד הנפשי של רשלנות מיוחס למשדל רק אם התקיים תנאי הצפיות בכוח, אשר לא התקיים במקרה זה.', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_2, 'ג', 'אין ללאה אחריות פלילית לרצח המאבטח, שכן הרצח לא היה צפוי על ידי אדם סביר.', true, 'זוהי התשובה הנכונה. סעיף 34א לחוק העונשין קובע כי תנאי להטלת אחריות לעבירה שונה או נוספת הוא ש''אדם מן היישוב יכול היה להיות מודע לאפשרות עשייתה''. אם תנאי זה אינו מתקיים, לא תוטל אחריות נגררת.', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_2, 'ד', 'לאה תישא באחריות פלילית לרצח המאבטח רק אם הייתה מודעת בפועל לאפשרות הרצח.', false, 'טענה זו אינה נכונה. אם הייתה מודעות בפועל, לאה הייתה נושאת באחריות ישירה לרצח, אך השאלה מניחה שלא הייתה מודעות כזו וכי הרצח לא היה צפוי.', 4);

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_3, v_sq_id, 'ד', 'אחריות לעבירה שונה או נוספת בתכנון מראש',
    4, 'לאה שידלה את ראובן ואת שמעון לבצע בצוותא שוד. במהלך תכנון השוד, שלושתם הסכימו במפורש שאם המאבטח יתנגד, ראובן יחבול בו בכוונה. במהלך השוד, ראובן אכן גרם בכוונה חבלה למאבטח. מהי האחריות הפלילית של לאה לחבלת המאבטח?', 'שאלה זו בוחנת את ההבחנה בין אחריות נגררת לפי סעיף 34א לחוק העונשין לבין אחריות ישירה לפי דיני השותפות הרגילים (סעיף 29 לחוק העונשין). היא מדגישה כי סעיף 34א חל רק כאשר העבירה השונה או הנוספת לא הייתה חלק מהתכנון המקורי, ואילו אם הייתה הסכמה מראש, האחריות היא ישירה.', 'סעיף 34א לחוק העונשין חל רק במקרים שבהם העבירה הנוספת לא הייתה חלק מהתכנון המקורי, ולא הייתה לגביה מודעות בפועל, אך אדם מן היישוב יכול היה להיות מודע לאפשרות עשייתה (צפיות בכוח). ע"פ 4389/93 יוסף מרדכי נ'' מדינת ישראל (04.08.1996) במקרה שבו העבירה הנוספת (חבלה בכוונה) הייתה חלק מהתכנון המקורי ובוצעה בהסכמה של כל השותפים, לא חל סעיף 34א. במקום זאת, האחריות נקבעת על פי דיני השותפות הרגילים, ובפרט סעיף 29 לחוק העונשין, הקובע כי ''המשדל, המסייע והמבצע בצוותא, דינם כדין מבצע העבירה''. יורם רבין, יניב ואקי דיני עונשין - כרך א (2014) | פרק 18 - צדדים לעבירה לכן, לאה, כמשדלת, תישא באחריות ישירה לעבירה 1 (חבלה בכוונה), שדינה מאסר עשר שנים. ע"פ 1102/22 דאהר ראדי נ'' מדינת ישראל (23.04.2023)',
    'הנחה שגויה כי סעיף 34א חל בכל מקרה של עבירה נוספת, ללא הבחנה בין עבירה שתוכננה מראש לבין עבירה שלא תוכננה אך הייתה צפויה.', '["תכנון מראש", "עבירה שונה או נוספת", "דיני שותפות רגילים", "סעיף 29 לחוק העונשין", "סעיף 34א לחוק העונשין", "אחריות ישירה", "משדל"]'::jsonb, '**וריאציה 1 — תכנון מראש:** אם עבירה נוספת תוכננה מראש? ← חלים דיני השותפות הרגילים (סעיף 29 לחוק העונשין), לא סעיף 34א (ע"פ 4389/93).
**וריאציה 2 — אחריות משדל בתכנון:** מהי אחריות משדל לעבירה שתוכננה מראש? ← אחריות ישירה כמבצע העבירה (עבירה 1), שדינה מאסר עשר שנים.
**וריאציה 3 — מתי 34א לא חל:** מתי אין צורך בהרחבת אחריות לפי סעיף 34א? ← כאשר העבירה הייתה חלק מהתכנון המקורי או הייתה מודעות בפועל (ע"פ 1102/22).', 'עבירה נוספת בתכנון מראש ← אחריות ישירה לפי סעיף 29 לחוק העונשין ← לא סעיף 34א.',
    '["חוק העונשין, תשל\"ז-1977, סעיפים 29, 34א", "ע\"פ 4389/93 יוסף מרדכי נ'' מדינת ישראל (04.08.1996)", "ע\"פ 1102/22 דאהר ראדי נ'' מדינת ישראל (23.04.2023)", "יורם רבין, יניב ואקי דיני עונשין - כרך א (2014) | פרק 18 - צדדים לעבירה"]'::jsonb
  );
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_3, 'א', 'לאה תישא באחריות פלילית בעבירה 1 בגין חבלת המאבטח.', true, 'זוהי התשובה הנכונה. כאשר העבירה הנוספת (חבלה בכוונה) הייתה חלק מהתכנון המקורי ובוצעה בהסכמה, לא חל סעיף 34א, אלא דיני השותפות הרגילים (סעיף 29 לחוק העונשין). לאה, כמשדלת, תישא באחריות ישירה לעבירה 1 (חבלה בכוונה).', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_3, 'ב', 'לאה תישא באחריות פלילית בעבירה 2 בגין חבלת המאבטח.', false, 'עבירה 2 היא חבלה במזיד/אדישות. אחריות זו מיוחסת למבצע בצוותא לפי סעיף 34א כאשר העבירה הנוספת בוצעה בכוונה אך לא הייתה מודעות בפועל. במקרה של תכנון מראש, האחריות היא ישירה לעבירת הכוונה.', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_3, 'ג', 'לאה תישא באחריות פלילית בעבירה 3 בגין חבלת המאבטח.', false, 'עבירה 3 היא חבלה בהתרשלות. אחריות זו מיוחסת למשדל/מסייע לפי סעיף 34א כאשר העבירה הנוספת בוצעה בכוונה אך לא הייתה מודעות בפועל. במקרה של תכנון מראש, האחריות היא ישירה לעבירת הכוונה.', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_3, 'ד', 'אין ללאה אחריות פלילית בגין חבלת המאבטח, שכן היא רק שידלה את השוד.', false, 'טענה זו אינה נכונה. הסכמה מראש לביצוע עבירה נוספת מטילה אחריות פלילית ישירה על כל השותפים, כולל המשדל.', 4);

  RAISE NOTICE 'Q% inserted: external_id %', 31, '2022-S-S-Q31';
END
$$;

