-- ============================================================
DO $$
DECLARE
  v_sq_id uuid := '824a2d4c-21cb-41f3-8326-ab6d464a7c07'::uuid;
  v_group_id uuid := '285913a4-8297-4375-b049-1ed30c175d33'::uuid;
  v_chapter_id uuid;
  v_subtopic_id uuid;
  v_existing_id uuid;
  v_ang_0 uuid := '70076621-6294-481d-aa1a-236cd8ff0154'::uuid;
  v_ang_1 uuid := '1c41bec4-1b40-4a84-a51f-91e6a745fa29'::uuid;
  v_ang_2 uuid := '1bc95840-9e58-4903-9912-9c8004dd70cc'::uuid;
  v_ang_3 uuid := '7db2421b-06dc-4c75-9b1d-19fd649b8244'::uuid;
BEGIN
  SELECT id INTO v_existing_id FROM public.source_questions WHERE external_id = '2022-S-S-Q33';
  IF v_existing_id IS NOT NULL THEN
    RAISE NOTICE 'Q% skipped: external_id % already exists', 33, '2022-S-S-Q33';
    RETURN;
  END IF;

  SELECT id INTO v_chapter_id FROM public.chapters WHERE code = 'criminal_substantive';
  IF v_chapter_id IS NULL THEN
    RAISE EXCEPTION 'Chapter code % not found', 'criminal_substantive';
  END IF;

  SELECT id INTO v_subtopic_id FROM public.subtopics WHERE code = 'general_part_elements' AND chapter_id = v_chapter_id;
  IF v_subtopic_id IS NULL THEN
    RAISE EXCEPTION 'Subtopic code % not found under chapter %', 'general_part_elements', 'criminal_substantive';
  END IF;

  INSERT INTO public.source_questions (
    id, question_group_id, version, is_current, external_id, chapter_id, subtopic_id, question_text, source_metadata, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list, notes_for_admin, status, created_by
  ) VALUES (
    v_sq_id, v_group_id, 1, true,
    '2022-S-S-Q33', v_chapter_id, v_subtopic_id, 'עבירת זיהום המים קבעה: "המזהם מים, דינו – קנס 1,000 ש"ח". ביום 1.2.2022 עדכן המחוקק את שיעור הקנס, כך שהעבירה קובעת: "המזהם מים, דינו – קנס 2,000 ש"ח". הנוסח המעודכן פורסם ביום 1.3.2022. יריב זיהם מים ביום 1.1.2022, יצחק זיהם מים ביום 15.2.2022, ושניהם נשפטו על כך והורשעו. מהו העונש המרבי שניתן לגזור על כל אחד מהם?',
    '{"exam_year": 2022, "exam_season": "summer", "exam_part": 2, "exam_question_number": 33}'::jsonb, 'השאלה עוסקת בתחולת דיני העונשין בזמן, ובפרט בפרשנות הסייג שבסעיף 3(ב) סיפא לחוק העונשין, הקובע כי "אין רואים בעדכון שיעורו של קנס החמרה בעונש". היא בוחנת האם עדכון קנס על ידי המחוקק נכלל בסייג זה, ומכאן האם הקנס המעודכן חל רטרואקטיבית על עבירות שבוצעו לפני פרסום התיקון.', 'סעיף 3(ב) לחוק העונשין, התשל"ז-1977, קובע כי חיקוק הקובע לעבירה עונש חמור מזה שנקבע לה בשעת ביצוע העבירה, לא יחול על מעשה שנעשה לפני פרסומו כדין או לפני תחילתו. עם זאת, הסיפא של הסעיף קובעת חריג: "אך אין רואים בעדכון שיעורו של קנס החמרה בעונש". פרשנות מקובלת בספרות המשפטית ובפסיקה (כמו בפסק הדין ת"פ (שלום ראשל"צ) 70781-04-25) היא שסייג זה מתייחס באופן ספציפי לעדכון קנסות על ידי שר המשפטים מכוח סעיף 64 לחוק העונשין, בהתאם לשינויים במדד המחירים לצרכן. עדכון כזה אינו נחשב החמרה, ולכן הקנס המעודכן חל גם על מעשים שבוצעו לפני פרסומו. במקרה הנדון, אף שהשאלה מציינת "עדכן המחוקק", התשובה הנכונה (ב'') לפיה הקנס המעודכן חל על שניהם, מחייבת לפרש את ה"עדכון" ככזה שאינו נחשב החמרה בעונש לפי סעיף 3(ב) סיפא. לפיכך, הקנס המעודכן בסך 2,000 ש"ח יחול הן על יריב והן על יצחק, אף שביצעו את העבירה לפני פרסום התיקון.', 'הטעות הנפוצה היא להניח שכל הגדלה של קנס, גם אם היא על ידי המחוקק ולא רק עדכון מדדי, נחשבת "עדכון שיעורו של קנס" שאינו החמרה, ובכך להחיל אותה רטרואקטיבית. הפרשנות המדויקת יותר, כפי שעולה מהספרות והפסיקה, היא שרק עדכון מדדי על ידי שר המשפטים אינו נחשב החמרה.',
    '["אין עונשין למפרע", "תחולה בזמן", "חוק העונשין", "עדכון קנס", "החמרה בעונש"]'::jsonb, '**וריאציה 1 — עבירה לפני עדכון, גזר דין אחרי:** אדם ביצע עבירה לפני עדכון קנס שאינו החמרה, ונגזר דינו לאחר העדכון. איזה קנס יוטל? ← הקנס המעודכן, שכן עדכון קנס אינו נחשב החמרה, לפי סעיף 3(ב) סיפא לחוק העונשין.
**וריאציה 2 — עבירה לפני עדכון, פסק דין חלוט לפני:** אדם ביצע עבירה, נגזר דינו ופסק הדין חלוט, ורק אז עודכן הקנס (שאינו החמרה). האם הקנס המעודכן חל? ← כן, סעיף 5(ב) לחוק העונשין קובע כי דין מקל חל גם לאחר פסק דין חלוט, ועדכון קנס נחשב דין מקל בהקשר זה.
**וריאציה 3 — שינוי חקיקתי מהותי של קנס:** המחוקק הגדיל קנס בתיקון חוק שאינו עדכון מדדי. האם הקנס המוגדל חל למפרע? ← לא, הגדלה כזו נחשבת החמרה בעונש ואינה חלה למפרע, לפי הפרשנות המקובלת לסעיף 3(ב) סיפא לחוק העונשין.', 'עדכון שיעורו של קנס אינו נחשב החמרה בעונש לפי סעיף 3(ב) סיפא לחוק העונשין, ולכן הקנס המעודכן יחול רטרואקטיבית גם על עבירות שבוצעו לפני פרסומו, אלא אם מדובר בשינוי חקיקתי מהותי שאינו עדכון מדדי.', '["סעיף 3 לחוק העונשין, תשל\"ז-1977", "סעיף 64 לחוק העונשין, תשל\"ז-1977", "יורם רבין, יניב ואקי דיני עונשין - כרך א (2014) | פרק 5 - עקרון החוקיות | 3. האיסור על ענישה למפרע", "ת\"פ (שלום ראשל\"צ) 70781-04-25 מדינת ישראל נ'' מחמוד אבו רידה (28.09.2025)", "עפ\"א (ארצי ) 17950-06-13 מדינת ישראל - בוני טיב חברה לבניין ופיתוח בע\"מ (07.08.2016)"]'::jsonb,
    'classification_review: original chapter=''סדר דין פלילי'' subtopic=''משפט חוזר'' → mapped chapter=''criminal_substantive'' subtopic=''general_part_elements'' | classifier_note: Water-pollution fine increase mid-act — application of lighter law (סעיף 3(ב) חוק העונשין) | source_review_note: השאלה עוסקת בתחולת דיני העונשין בזמן, ובפרט בפרשנות הסייג שבסעיף 3(ב) סיפא לחוק העונשין. התשובה הנכונה שסופקה (ב'') סותרת את הפרשנות המקובלת בספרות המשפטית ובפסיקה העדכנית (כמו ת"פ (שלום ראשל"צ) 70781-04-25), לפיה "עדכון שיעורו של קנס" שאינו נחשב החמרה מתייחס רק לעדכון מדדי על ידי שר המשפטים לפי סעיף 64, ולא ל"עדכון המחוקק" כפי שמתואר בשאלה. אם מדובר ב"עדכון המחוקק" שאינו מדדי, הוא נחשב החמרה בעונש ואינו חל למפרע. לפיכך, התשובה הנכונה לפי הדין המפורש הייתה צריכה להיות 1,000 ש"ח לשניהם (א''). יש לבדוק את מקור השאלה והתשובה המקורית.', 'active', 'b9ecdde2-d07e-4761-96ab-05f0ad32d4e3'
  );

  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'א', 'על שניהם קנס בסך 1,000 ש"ח.', false, 'בחירה זו שגויה, שכן לפי סעיף 3(ב) סיפא לחוק העונשין, עדכון שיעורו של קנס אינו נחשב החמרה בעונש, ולכן הקנס המעודכן חל על שניהם.', 1);
  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'ב', 'על שניהם קנס בסך 2,000 ש"ח.', true, 'סעיף 3(ב) סיפא לחוק העונשין קובע כי "אין רואים בעדכון שיעורו של קנס החמרה בעונש". משמעות הדבר היא שהקנס המעודכן חל גם על מעשים שבוצעו לפני פרסומו, ולכן על שניהם יוטל הקנס המעודכן.', 2);
  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'ג', 'על יריב קנס בסך 1,000 ש"ח, ועל יצחק קנס בסך 2,000 ש"ח.', false, 'בחירה זו שגויה, שכן אם עדכון הקנס אינו נחשב החמרה בעונש, הוא חל על שניהם. אם היה נחשב החמרה, הוא לא היה חל על אף אחד מהם, שכן שניהם ביצעו את העבירה לפני פרסום התיקון.', 3);
  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'ד', 'על יצחק קנס בסך 1,000 ש"ח, ועל יריב קנס בסך 2,000 ש"ח.', false, 'בחירה זו שגויה, שכן היא הופכת את סכומי הקנס בין יריב ליצחק, ואינה עולה בקנה אחד עם הכלל המשפטי לפיו עדכון קנס אינו נחשב החמרה בעונש.', 4);

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_0, v_sq_id, 'א', 'ביטול עבירה לאחר ביצועה',
    1, 'ראובן ביצע עבירה של "החזקת מכשיר פקס ללא רישיון" ביום 1.1.2023. ביום 1.3.2023 נכנס לתוקף חוק חדש שביטל לחלוטין את האיסור על החזקת מכשיר פקס. ראובן נתפס ביום 1.4.2023. מה הדין הפלילי לגבי ראובן?', 'שאלה זו עוסקת בתחולת דיני העונשין בזמן במקרה של ביטול מוחלט של עבירה. היא בוחנת את הכלל הקבוע בסעיף 4 לחוק העונשין, לפיו ביטול איסור פלילי מביא לביטול רטרואקטיבי של האחריות הפלילית והפסקת ההליכים, גם אם העבירה בוצעה לפני הביטול.', 'סעיף 4 לחוק העונשין, התשל"ז-1977, קובע כי "נעברה עבירה ובוטל בחיקוק האיסור עליה - תתבטל האחריות הפלילית לעשייתה; ההליכים שהוחל בהם - יופסקו; ניתן גזר-דין - יופסק ביצועו; ולא יהיו בעתיד עוד תוצאות נובעות מן ההרשעה". כלל זה מבטא את העיקרון לפיו אם החברה אינה רואה עוד במעשה מסוים עבירה, אין טעם להמשיך ולהעניש עליו. לכן, במקרה של ראובן, אף שביצע את העבירה לפני ביטול האיסור, האחריות הפלילית שלו תתבטל וההליכים נגדו יופסקו.',
    'טעות נפוצה היא לחשוב שביטול איסור פלילי חל רק על מעשים עתידיים, או שהוא מהווה רק נסיבה מקלה בעונש, ולא ביטול מוחלט של האחריות הפלילית.', '["ביטול עבירה", "תחולה בזמן", "חוק העונשין", "אחריות פלילית", "הפסקת הליכים"]'::jsonb, '**וריאציה 1 — ביטול איסור לאחר הרשעה חלוטה:** אדם הורשע בעבירה, ופסק הדין הפך חלוט. לאחר מכן, האיסור על העבירה בוטל. מה הדין? ← ביצוע גזר הדין יופסק, ולא יהיו תוצאות נוספות מההרשעה, לפי סעיף 4 לחוק העונשין.
**וריאציה 2 — ביטול איסור לפני הגשת כתב אישום:** אדם ביצע עבירה, ולפני שהוגש נגדו כתב אישום, האיסור בוטל. מה הדין? ← האחריות הפלילית תתבטל ולא יוגש כתב אישום, לפי סעיף 4 לחוק העונשין.
**וריאציה 3 — ביטול איסור עם הוראת מעבר:** חוק חדש מבטל איסור, אך קובע בהוראת מעבר שהביטול לא יחול על עבירות שבוצעו לפני כן. מה הדין? ← הוראת המעבר הספציפית גוברת על הכלל שבסעיף 4, שכן סעיף 4 הוא כלל כללי שניתן לסייג בחקיקה ספציפית.', 'ביטול איסור פלילי בחיקוק חדש מביא לביטול רטרואקטיבי של האחריות הפלילית, הפסקת הליכים וביצוע גזר דין, גם אם העבירה בוצעה לפני הביטול ← סעיף 4 לחוק העונשין.',
    '["סעיף 4 לחוק העונשין, תשל\"ז-1977", "ע\"פ 6834/14 רעות מליאנקר נ'' מדינת ישראל (26.02.2015)", "בג\"ץ 1618/97 יצחק סצ''י נ'' עיריית תל-אביב-יפו, נב(2) 542 (16.06.1998)"]'::jsonb
  );
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_0, 'א', 'ראובן יועמד לדין ויוכל לטעון להגנתו כי האיסור בוטל.', false, 'בחירה זו שגויה, שכן ביטול האיסור מוביל לביטול מוחלט של האחריות הפלילית ולהפסקת ההליכים, ולא רק לטענת הגנה.', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_0, 'ב', 'האחריות הפלילית של ראובן תתבטל וההליכים נגדו יופסקו.', true, 'סעיף 4 לחוק העונשין קובע כי אם נעברה עבירה ובוטל בחיקוק האיסור עליה, תתבטל האחריות הפלילית לעשייתה וההליכים שהוחל בהם יופסקו.', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_0, 'ג', 'ראובן יורשע, אך בית המשפט יתחשב בביטול האיסור לקולא בעונש.', false, 'בחירה זו שגויה, שכן ביטול האיסור מביא לביטול האחריות הפלילית כולה, ולא רק להקלה בעונש.', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_0, 'ד', 'האיסור בוטל, אך מאחר שהעבירה בוצעה לפני הביטול, ראובן עדיין יישא באחריות פלילית.', false, 'בחירה זו שגויה, שכן סעיף 4 לחוק העונשין קובע במפורש כי ביטול האיסור מבטל את האחריות הפלילית גם על מעשים שנעשו לפני הביטול.', 4);

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_1, v_sq_id, 'ב', 'שינוי מקל בעונש לפני פסק דין חלוט',
    2, 'שמעון ביצע עבירה של גניבה ביום 1.1.2023, שהעונש המרבי עליה היה 5 שנות מאסר. ביום 1.3.2023, לפני שניתן פסק דין חלוט בעניינו, נכנס לתוקף תיקון לחוק שהפחית את העונש המרבי על גניבה ל-3 שנות מאסר. מהו העונש המרבי שניתן לגזור על שמעון?', 'שאלה זו בוחנת את הכלל בדבר תחולת דין מקל בזמן, כאשר השינוי מתרחש לפני מתן פסק דין חלוט. היא מדגישה את העיקרון לפיו דין פלילי מקל חל למפרע, מתוך תפיסה של צדק והוגנות כלפי הנאשם.', 'סעיף 5(א) לחוק העונשין, התשל"ז-1977, קובע כי "נעברה עבירה ובטרם ניתן פסק-דין חלוט לגביה, חל שינוי בנוגע להגדרתה או לאחריות לה, או בנוגע לעונש שנקבע לה, יחול על הענין החיקוק המקל עם העושה". כלל זה מבטא את הרציונל לפיו אם המחוקק סבור שהעונש הראוי לעבירה מסוימת קל יותר, יש להחיל את ההקלה גם על מי שטרם נגזר דינו באופן סופי. במקרה של שמעון, מאחר שהעונש המרבי הופחת ל-3 שנות מאסר לפני שפסק הדין הפך חלוט, זהו העונש המרבי שניתן לגזור עליו.',
    'הבלבול בין הכלל של איסור ענישה למפרע (לגבי דין מחמיר) לבין הכלל של תחולת דין מקל למפרע (לגבי דין מקל).', '["דין מקל", "תחולה בזמן", "חוק העונשין", "פסק דין חלוט", "עונש מרבי"]'::jsonb, '**וריאציה 1 — שינוי בהגדרת העבירה:** עבירה בוצעה, ולפני פסק דין חלוט שונתה הגדרת העבירה באופן שמקל עם הנאשם. האם הדין המקל חל? ← כן, לפי סעיף 5(א) לחוק העונשין.
**וריאציה 2 — שינוי בסייג לאחריות פלילית:** עבירה בוצעה, ולפני פסק דין חלוט שונה סייג לאחריות פלילית באופן שמקל עם הנאשם. האם הדין המקל חל? ← כן, לפי סעיף 5(א) לחוק העונשין, הכולל "אחריות לה" - לרבות תחולת סייגים לאחריות הפלילית.
**וריאציה 3 — שינוי מחמיר בעונש לפני פסק דין חלוט:** עבירה בוצעה, ולפני פסק דין חלוט הוחמר העונש. האם הדין המחמיר חל? ← לא, לפי סעיף 3(ב) לחוק העונשין, חיקוק הקובע עונש חמור לא יחול למפרע.', 'כאשר דין פלילי מקל (בהגדרת עבירה, אחריות או עונש) נכנס לתוקף לפני פסק דין חלוט, הוא יחול למפרע על העושה ← סעיף 5(א) לחוק העונשין.',
    '["סעיף 5 לחוק העונשין, תשל\"ז-1977", "ע\"פ 7853/05 פנחס רחמיאן נ'' מדינת ישראל (27.11.2006)", "מ\"ת (מחוזי י-ם) 55629-11-14 אהרון שלמה ליסון נ'' מדינת ישראל (13.09.2016)"]'::jsonb
  );
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_1, 'א', '5 שנות מאסר, שכן זהו העונש שהיה בתוקף בעת ביצוע העבירה.', false, 'בחירה זו שגויה, שכן במקרה של שינוי מקל בעונש לפני פסק דין חלוט, חל הדין המקל.', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_1, 'ב', '3 שנות מאסר, שכן חל עליו הדין המקל.', true, 'סעיף 5(א) לחוק העונשין קובע כי אם נעברה עבירה ובטרם ניתן פסק דין חלוט לגביה, וחל שינוי בנוגע לעונש שנקבע לה, יחול על העניין החיקוק המקל עם העושה.', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_1, 'ג', 'בית המשפט יבחר בין 3 ל-5 שנות מאסר, לפי שיקול דעתו.', false, 'בחירה זו שגויה, שכן בית המשפט כפוף לעונש המרבי הקבוע בחוק המקל, ואינו יכול להטיל עונש חמור יותר מהקבוע בו.', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_1, 'ד', 'העונש ייקבע לפי הדין שהיה בתוקף ביום מתן גזר הדין, ללא קשר למועד ביצוע העבירה.', false, 'בחירה זו שגויה, שכן הכלל הוא שהדין המקל חל, ולא בהכרח הדין שהיה בתוקף ביום גזר הדין אם הוא חמור יותר.', 4);

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_2, v_sq_id, 'ג', 'שינוי מקל בעונש לאחר פסק דין חלוט',
    3, 'דוד הורשע בעבירה של שוד ביום 1.1.2020, ונגזר עליו עונש של 10 שנות מאסר. פסק הדין הפך חלוט. ביום 1.3.2023 נכנס לתוקף תיקון לחוק שהפחית את העונש המרבי על שוד ל-7 שנות מאסר. מה הדין לגבי עונשו של דוד?', 'שאלה זו עוסקת בחריג לעקרון סופיות הדיון, המאפשר החלה רטרואקטיבית של דין פלילי מקל גם לאחר שפסק הדין הפך חלוט. היא בוחנת את הוראת סעיף 5(ב) לחוק העונשין ואת האיזון בין סופיות הדיון לבין עשיית צדק.', 'סעיף 5(ב) לחוק העונשין, התשל"ז-1977, קובע כי "הורשע אדם בעבירה בפסק דין חלוט ולאחר מכן נקבע לאותה עבירה בחיקוק עונש, שלפי מידתו או סוגו הוא קל מזה שהוטל עליו - יהיה עונשו העונש המרבי שנקבע בחיקוק, כאילו הוטל מלכתחילה". הוראה זו מאזנת בין עקרון סופיות הדיון לבין הרצון שלא להעניש אדם בעונש חמור יותר מזה שהחברה רואה כראוי כיום. במקרה של דוד, מאחר שהעונש המרבי על שוד הופחת ל-7 שנות מאסר לאחר שפסק דינו הפך חלוט, עונשו יופחת בהתאם לדין המקל.',
    'הנחה שגויה כי פסק דין חלוט הוא סוף פסוק בכל מקרה, והתעלמות מהחריג המפורש בסעיף 5(ב) לחוק העונשין.', '["דין מקל", "פסק דין חלוט", "סופיות הדיון", "חוק העונשין", "הפחתת עונש"]'::jsonb, '**וריאציה 1 — שינוי מחמיר לאחר פסק דין חלוט:** אדם הורשע בעבירה, ופסק הדין חלוט. לאחר מכן, הוחמר העונש על העבירה. האם העונש המחמיר חל? ← לא, סעיף 5(ב) חל רק על דין מקל, ולא על דין מחמיר.
**וריאציה 2 — שינוי הדורש שיקול דעת:** תיקון חוק לאחר פסק דין חלוט מאפשר הפחתת עונש, אך דורש שיקול דעת שיפוטי. האם סעיף 5(ב) חל? ← הפסיקה (ע"פ 2928/20 חיים ביטון) קבעה כי סעיף 5(ב) חל במקרים שבהם ניתן לקבוע נחרצות, באופן מנהלי גרידא, כי יש להפחית בעונש ומהי מידת ההפחתה, ולא כאשר נדרש שיקול דעת שיפוטי רחב.
**וריאציה 3 — ביטול עבירה לאחר פסק דין חלוט:** אדם הורשע בעבירה, ופסק הדין חלוט. לאחר מכן, האיסור על העבירה בוטל. מה הדין? ← ביצוע גזר הדין יופסק, לפי סעיף 4 לחוק העונשין, שהוא כלל רחב יותר מסעיף 5(ב).', 'דין פלילי מקל שנכנס לתוקף לאחר פסק דין חלוט, יביא להפחתת העונש שהוטל על הנאשם, כאילו הוטל מלכתחילה ← סעיף 5(ב) לחוק העונשין.',
    '["סעיף 5 לחוק העונשין, תשל\"ז-1977", "ע\"פ 7853/05 פנחס רחמיאן נ'' מדינת ישראל (27.11.2006)", "ע\"פ 2928/20 חיים ביטון נ'' מדינת ישראל (24.11.2020)", "מ\"ת (מחוזי י-ם) 55629-11-14 אהרון שלמה ליסון נ'' מדינת ישראל (13.09.2016)"]'::jsonb
  );
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_2, 'א', 'עונשו של דוד יישאר 10 שנות מאסר, שכן פסק הדין חלוט.', false, 'בחירה זו שגויה, שכן סעיף 5(ב) לחוק העונשין קובע חריג לעקרון סופיות הדיון במקרה של דין מקל לאחר פסק דין חלוט.', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_2, 'ב', 'עונשו של דוד יופחת ל-7 שנות מאסר, שכן חל עליו הדין המקל.', true, 'סעיף 5(ב) לחוק העונשין קובע כי אם הורשע אדם בפסק דין חלוט ולאחר מכן נקבע לאותה עבירה עונש קל יותר, יהיה עונשו העונש המרבי שנקבע בחיקוק החדש, כאילו הוטל מלכתחילה.', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_2, 'ג', 'דוד יוכל לבקש משפט חוזר על בסיס הדין החדש.', false, 'בחירה זו שגויה, שכן סעיף 5(ב) לחוק העונשין מספק מנגנון ישיר להפחתת העונש במקרה כזה, ואין צורך במשפט חוזר.', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_2, 'ד', 'העונש יופחת רק אם ההפחתה היא "טכנית-אדמיניסטרטיבית" ואינה דורשת שיקול דעת שיפוטי.', false, 'בחירה זו שגויה, שכן סעיף 5(ב) חל גם על הפחתות עונש מהותיות, כל עוד הן קלות יותר, ואינו מוגבל רק לשינויים טכניים-אדמיניסטרטיביים.', 4);

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_3, v_sq_id, 'ד', 'עדכון קנס על ידי שר המשפטים',
    4, 'עבירת "השלכת פסולת ברשות הרבים" קבעה קנס בסך 500 ש"ח. ביום 1.1.2023, שר המשפטים, מכוח סמכותו בסעיף 64 לחוק העונשין, עדכן את שיעור הקנס ל-700 ש"ח, בהתאם לשינויים במדד המחירים לצרכן. העדכון פורסם ביום 1.2.2023. משה השליך פסולת ביום 15.1.2023. מהו הקנס המרבי שניתן לגזור על משה?', 'שאלה זו מתמקדת בהבחנה בין עדכון קנס על ידי שר המשפטים מכוח סעיף 64 לחוק העונשין, לבין שינוי קנס על ידי המחוקק. היא מדגישה כי רק עדכון קנס על בסיס מדד אינו נחשב החמרה בעונש לפי סעיף 3(ב) סיפא, ולכן חל למפרע.', 'סעיף 3(ב) סיפא לחוק העונשין, התשל"ז-1977, קובע כי "אין רואים בעדכון שיעורו של קנס החמרה בעונש". ספרות משפטית ופסיקה (כמו ת"פ (שלום ראשל"צ) 70781-04-25) מפרשות סייג זה כמתייחס באופן ספציפי לסמכות שר המשפטים לעדכן את שיעורי הקנסות הקבועים בחוקים שונים, על פי שינויים במדד המחירים לצרכן, בהתאם לסעיף 64(א) לחוק העונשין. עדכון כזה אינו נחשב החמרה, ולכן הקנס המעודכן חל גם על מעשים שבוצעו לפני פרסומו. במקרה של משה, הקנס עודכן על ידי שר המשפטים לפי סעיף 64, ולכן הקנס המרבי שניתן לגזור עליו הוא 700 ש"ח.',
    'הכללה שגויה של כל שינוי בסכום קנס כ"עדכון שיעורו של קנס" שאינו החמרה, מבלי להבחין בין עדכון מדדי על ידי שר המשפטים לבין שינוי חקיקתי מהותי על ידי המחוקק.', '["עדכון קנס", "סעיף 64 לחוק העונשין", "סעיף 3(ב) לחוק העונשין", "תחולה בזמן", "מדד המחירים לצרכן"]'::jsonb, '**וריאציה 1 — עדכון קנס על ידי שר המשפטים לפני ביצוע עבירה:** שר המשפטים עדכן קנס, ולאחר מכן בוצעה עבירה. איזה קנס יוטל? ← הקנס המעודכן, שכן הוא הדין בתוקף בעת ביצוע העבירה.
**וריאציה 2 — שינוי חקיקתי של קנס על ידי המחוקק:** המחוקק הגדיל קנס בתיקון חוק, ולא כעדכון מדדי. האם הקנס המוגדל חל למפרע? ← לא, הגדלה כזו נחשבת החמרה בעונש ואינה חלה למפרע, לפי הפרשנות המקובלת לסעיף 3(ב) סיפא לחוק העונשין.
**וריאציה 3 — קנס מינהלי:** קנס מינהלי עודכן. האם הקנס המעודכן חל למפרע? ← סעיף 3(ב) לחוק העונשין חל על הליכים פליליים. לגבי קנס מינהלי, סעיף 3(ב) לחוק העבירות המינהליות קובע שהטלת הקנס תהיה לפי שיעורו המעודכן ביום הטלתו, גם אם הוא גבוה יותר.', 'עדכון קנס על ידי שר המשפטים לפי סעיף 64 לחוק העונשין (בהתאם למדד) אינו נחשב החמרה בעונש, ולכן הקנס המעודכן חל למפרע גם על עבירות שבוצעו לפני פרסומו ← סעיף 3(ב) סיפא לחוק העונשין.',
    '["סעיף 3 לחוק העונשין, תשל\"ז-1977", "סעיף 64 לחוק העונשין, תשל\"ז-1977", "יורם רבין, יניב ואקי דיני עונשין - כרך א (2014) | פרק 5 - עקרון החוקיות | 3. האיסור על ענישה למפרע", "ת\"פ (שלום ראשל\"צ) 70781-04-25 מדינת ישראל נ'' מחמוד אבו רידה (28.09.2025)", "עפ\"א (ארצי ) 17950-06-13 מדינת ישראל - בוני טיב חברה לבניין ופיתוח בע\"מ (07.08.2016)"]'::jsonb
  );
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_3, 'א', '500 ש"ח, שכן העבירה בוצעה לפני פרסום העדכון.', false, 'בחירה זו שגויה, שכן עדכון קנס על ידי שר המשפטים לפי סעיף 64 אינו נחשב החמרה בעונש, ולכן הקנס המעודכן חל גם על מעשים שבוצעו לפני פרסומו.', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_3, 'ב', '700 ש"ח, שכן עדכון שיעורו של קנס אינו נחשב החמרה בעונש.', true, 'סעיף 3(ב) סיפא לחוק העונשין קובע כי "אין רואים בעדכון שיעורו של קנס החמרה בעונש". עדכון קנס על ידי שר המשפטים לפי סעיף 64 הוא דוגמה מובהקת לכך, ולכן הקנס המעודכן חל על משה.', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_3, 'ג', 'בית המשפט יבחר בין 500 ל-700 ש"ח, לפי שיקול דעתו.', false, 'בחירה זו שגויה, שכן במקרה של עדכון קנס שאינו נחשב החמרה, הקנס המעודכן הוא הקנס המרבי שניתן להטיל.', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_3, 'ד', 'הקנס ייקבע לפי הדין שהיה בתוקף ביום מתן גזר הדין, רק אם הוא נמוך יותר.', false, 'בחירה זו שגויה, שכן הכלל לגבי עדכון קנס הוא שהוא אינו נחשב החמרה, ולכן הקנס המעודכן חל גם אם הוא גבוה יותר.', 4);

  RAISE NOTICE 'Q% inserted: external_id %', 33, '2022-S-S-Q33';
END
$$;

