  v_existing_id uuid;
  v_ang_0 uuid := '8bf489d6-84ea-48ed-9595-c04bafab7783'::uuid;
  v_ang_1 uuid := '20d82c65-3c91-4993-b48f-3b57e43095a7'::uuid;
  v_ang_2 uuid := '281a2f49-dea3-41d3-99c6-9d7ecd618aaa'::uuid;
