  INSERT INTO public.source_questions (
    id, question_group_id, version, is_current, external_id, chapter_id, subtopic_id, question_text, source_metadata, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list, notes_for_admin, status, created_by
  ) VALUES (
    v_sq_id, v_group_id, 1, true,
    '2022-S-S-Q34', v_chapter_id, v_subtopic_id, 'עו"ד פלוני מייצג חייב (להלן: חייב 1) בהליך התנגדות בתיק הוצאה לפועל שפתחה חברה להשכרת אופניים חשמליים (להלן: החברה) כלפי שני חייבים. בסמוך לאחר תחילת ייצוגו של חייב 1, פנה אל עו"ד פלוני החייב האחר (להלן: החייב האחר) וביקש ממנו לייצג גם אותו במסגרת ההליך שפתחה החברה נגד שני החייבים. עו"ד פלוני פנה לחייב 1 כדי לברר אם קיימת בעייתיות מבחינתו שהוא (עורך הדין) ייצג גם את החייב האחר, וחייב 1 מסר כי מבחינתו אין כל בעיה. לאחר שעו"ד פלוני הבין שטענותיה של החברה כלפי שני החייבים הן זהות וכי הוא לא צופה שבייצוגו את שני החייבים בהליך עשוי להתעורר קושי כלשהו או בעיה של ניגוד עניינים, הסכים עו"ד פלוני לייצג גם את החייב האחר. מה הדין?',
    '{"exam_year": 2022, "exam_season": "summer", "exam_part": 2, "exam_question_number": 34}'::jsonb, 'השאלה עוסקת בתחולת דיני האתיקה המקצועית על עורכי דין, ובפרט בכללי ניגוד העניינים כפי שנקבעו בכלל 14 לכללי לשכת עורכי הדין (אתיקה מקצועית). היא בוחנת מצב של ייצוג משותף של מספר לקוחות באותו עניין, כאשר האינטרסים שלהם אינם מנוגדים, וניתנה הסכמת אחד הלקוחות לייצוג המשותף.', 'כלל 14 לכללי לשכת עורכי הדין (אתיקה מקצועית), התשמ"ו-1986, קובע את האיסורים על ניגוד עניינים. כלל 14(ב) אוסר על עורך דין לייצג צדדים בעלי אינטרסים מנוגדים באותו עניין. אולם, במקרה הנדון, עורך הדין ייצג שני חייבים נגד חברה אחת, כאשר טענותיה של החברה כלפי שני החייבים היו זהות, ועורך הדין לא צפה קושי או ניגוד עניינים. בנוסף, חייב 1 נתן את הסכמתו לייצוג המשותף. הפסיקה קובעת כי ייצוג מספר תובעים או נתבעים נגד צד אחד, כאשר אין ניגוד אינטרסים ביניהם, אינו מהווה ניגוד עניינים אסור (ראו: עמל"ע (מחוזי י-ם) 26185-08-16 לשכת עורכי הדין - מחוז תל אביב נ'' קטי ברדה). כלל 14(ד) אף מאפשר ייצוג צדדים בעלי אינטרסים מנוגדים בעריכת הסכם, אם הסכימו בכתב, אך כאן אין אינטרסים מנוגדים בין החייבים. לכן, בהיעדר חשש לניגוד עניינים בפועל או בכוח בין שני החייבים, ועם הסכמת חייב 1, הייצוג המשותף אינו מהווה עבירה אתית.', 'טעות נפוצה היא להניח שכל ייצוג של יותר מלקוח אחד באותו הליך, גם אם האינטרסים שלהם אינם מנוגדים, מהווה ניגוד עניינים אסור, תוך התעלמות מהדרישה לקיומם של אינטרסים מנוגדים או חשש לניגוד כזה.',
    '["ניגוד עניינים", "כללי אתיקה מקצועית", "ייצוג משותף", "חובת נאמנות", "הסכמת לקוח"]'::jsonb, '**וריאציה 1 — ייצוג שני תובעים נגד נתבע אחד:** עורך דין מייצג שני דיירים בתביעת ליקויי בנייה נגד קבלן אחד. האם זה ניגוד עניינים? ← לא, אם אין ניגוד אינטרסים בין הדיירים, וגם אם הקבלן יגיע לפשיטת רגל, אין בכך ניגוד עניינים אסור (עמל"ע (מחוזי י-ם) 26185-08-16).
**וריאציה 2 — ייצוג שני חייבים עם טענות הגנה שונות:** עורך דין מייצג שני חייבים באותו תיק הוצאה לפועל, אך לכל אחד מהם טענות הגנה שונות ואף סותרות. האם זה ניגוד עניינים? ← כן, קיים חשש לניגוד אינטרסים בין החייבים, ולכן הייצוג המשותף אסור לפי כלל 14(ב) לכללי האתיקה.

**וריאציה 3 — ייצוג שני צדדים לעסקה עם הסכמה בכתב:** עורך דין מייצג מוכר וקונה בעסקת מקרקעין, ושניהם הסכימו בכתב לייצוג המשותף. האם זה מותר? ← כן, כלל 14(ד) לכללי האתיקה מאפשר זאת בעריכת הסכם, בתנאי שהצדדים הסכימו בכתב.', 'ייצוג משותף של מספר לקוחות באותו עניין מותר, כל עוד אין חשש לניגוד אינטרסים ביניהם, ורצוי לקבל את הסכמתם ← כלל 14 לכללי האתיקה.', '["כללי לשכת עורכי הדין (אתיקה מקצועית), תשמ\"ו-1986, כלל 14", "עמל\"ע (מחוזי י-ם) 26185-08-16 לשכת עורכי הדין - מחוז תל אביב נ'' קטי ברדה (23.01.2017)", "עת\"מ (מינהליים י-ם) 45297-09-22 סתיו חנס נ'' לשכת עורכי הדין בישראל (15.11.2022)"]'::jsonb,
    'classification_review: original chapter=''סדר דין פלילי'' subtopic=''משמעת עורכי דין'' → mapped chapter=''ethics'' subtopic=''fiduciary_privilege_conflict'' | classifier_note: Joint-defense / second debtor approaching the lawyer of debtor 1 — conflict of interest | source_review_note: סיווג תת-הנושא ''משמעת עורכי דין'' תחת ''סדר דין פלילי'' אינו מדויק לחלוטין עבור שאלה העוסקת בכללי אתיקה בייצוג אזרחי. הנושא מתאים יותר ל''אתיקה מקצועית'' תחת פרק נפרד או ''סדר דין אזרחי'' אם כי אין תת-נושא ספציפי. נבחר ''משמעת עורכי דין'' כברירת מחדל הקרובה ביותר מתוך הרשימה הסגורה.', 'active', 'b9ecdde2-d07e-4761-96ab-05f0ad32d4e3'
  );

  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'א', 'עו"ד פלוני עשוי להיחשב כמי שעבר עבירה אתית היות שהוא מנוע מלייצג גם את החייב האחר באותו הליך, אם קודם לכן כבר החל לייצג את חייב 1.', false, 'בחירה זו שגויה, שכן ייצוג משותף של מספר לקוחות באותו עניין מותר אם אין ניגוד אינטרסים ביניהם, ואין כלל גורף האוסר על ייצוג חייב נוסף באותו הליך.', 1);
  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'ב', 'עו"ד פלוני לא עשוי להיחשב כמי שעבר עבירה אתית אך מהטעם שחייב 1 נתן את הסכמתו שעו"ד פלוני ייצג גם את החייב האחר, ולפיכך אין גם כל רלוונטיות לסוגיית ניגוד העניינים.', false, 'בחירה זו שגויה, שכן הסכמת לקוח היא תנאי חשוב אך לא יחיד. יש לבחון גם את קיומו של חשש לניגוד עניינים אובייקטיבי, שכן הסכמה לבדה אינה מאיינת ניגוד עניינים מהותי.', 2);
  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'ג', 'עו"ד פלוני עשוי להיחשב כמי שעבר עבירה אתית היות שהוא מנוע מלייצג גם את החייב האחר באותו ההליך אם לא דאג לקבל משני החייבים הסכמה בכתב לייצוגם המשותף בהליך מול החברה.', false, 'בחירה זו שגויה, שכן דרישת הסכמה בכתב לייצוג משותף של צדדים בעלי אינטרסים מנוגדים חלה בעיקר על עריכת הסכם (כלל 14(ד)), ולא על ייצוג בהליך משפטי כאשר אין ניגוד אינטרסים בפועל בין הלקוחות.', 3);
  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'ד', 'עו"ד פלוני לא עשוי להיחשב כמי שעבר עבירה אתית היות שחייב 1 נתן את הסכמתו שעו"ד פלוני ייצג גם את החייב האחר, וכן לא קיים חשש בדבר ניגוד עניינים בייצוג המשותף.', true, 'כלל 14(ב) לכללי לשכת עורכי הדין (אתיקה מקצועית) אוסר ייצוג צדדים בעלי אינטרסים מנוגדים באותו עניין. במקרה זה, עורך הדין קבע שאין חשש לניגוד עניינים בין החייבים, וקיבל את הסכמת חייב 1, ולכן הייצוג המשותף אינו מהווה עבירה אתית.', 4);

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_0, v_sq_id, 'א', 'ייצוג גרושות נגד אותו גרוש',
    1, 'עו"ד שרה ייצגה את מיכל, גרושתו הראשונה של אמנון, בתביעת מזונות. שנים לאחר מכן, פנתה יעל, גרושתו השנייה של אמנון, לעו"ד שרה בבקשה לייצגה בתביעת מזונות נגד אמנון. עו"ד שרה קיבלה את הסכמת מיכל לייצוג יעל. האם עו"ד שרה רשאית לייצג את יעל?', 'שאלה זו בוחנת את גבולות האיסור על ניגוד עניינים בייצוג עורכי דין, במיוחד במקרים של ייצוג לקוחות שונים נגד אותו צד שלישי, אך בעניינים נפרדים או במועדים שונים. היא מתייחסת לפרשנות כלל 14(א) ו-14(ב) לכללי לשכת עורכי הדין (אתיקה מקצועית).', 'כלל 14(ב) לכללי לשכת עורכי הדין (אתיקה מקצועית) אוסר על עורך דין לייצג צדדים בעלי אינטרסים מנוגדים באותו עניין. עם זאת, הפסיקה קבעה כי ייצוג שתי גרושות של אותו אדם, גם אם מדובר בתביעות מזונות, אינו יוצר בהכרח ניגוד עניינים אסור. בית המשפט המחוזי בעמל"ע (מחוזי י-ם) 26185-08-16 לשכת עורכי הדין - מחוז תל אביב נ'' קטי ברדה, דן במקרה דומה וקבע כי עצם העובדה ששתי גרושות מנהלות משפטים נגד אדם אחד אינו יוצר ניגוד אינטרסים. גם הטענה ל"קופה אחת" של הנתבע אינה מספיקה כדי לקבוע איסור ייצוג. במקרה זה, ההליכים הכלכליים של הגרושה הראשונה הסתיימו שנים רבות קודם לכן, וגם הסכמתה לייצוג המשותף מחזקת את המסקנה שאין ניגוד עניינים.',
    'טעות נפוצה היא להניח שכל ייצוג של מספר לקוחות נגד אותו צד שלישי, גם אם האינטרסים שלהם אינם מנוגדים בפועל או שהעניינים שונים, מהווה ניגוד עניינים אסור.', '["ניגוד עניינים", "כללי אתיקה מקצועית", "ייצוג משותף", "חובת נאמנות", "הסכמת לקוח"]'::jsonb, '**וריאציה 1 — ייצוג מספר דיירים נגד קבלן:** עורך דין מייצג מספר דיירים בתביעת ליקויי בנייה נגד קבלן אחד. האם זה ניגוד עניינים? ← לא, אם אין ניגוד אינטרסים בין הדיירים, גם אם הקבלן יגיע לפשיטת רגל (עמל"ע (מחוזי י-ם) 26185-08-16).
**וריאציה 2 — ייצוג שני צדדים לעסקה עם אינטרסים מנוגדים:** עורך דין מייצג מוכר וקונה בעסקת מקרקעין, כאשר יש להם אינטרסים מנוגדים. האם זה מותר? ← כן, אם הצדדים הסכימו בכתב לייצוג המשותף בעריכת ההסכם, לפי כלל 14(ד) לכללי האתיקה.
**וריאציה 3 — ייצוג שותפים נגד שותף אחר:** עורך דין ייצג בעבר שותפות. כעת הוא מייצג את אחד השותפים נגד שותף אחר באותו עניין. האם זה מותר? ← לא, אם קיבל מידע רלוונטי מהשותפות שעלול לשמש נגד הלקוח לשעבר, לפי כלל 16 לכללי האתיקה (בד"מ (ועדת משמעת לשכת עוה"ד ארצי) 37/16).', 'ייצוג לקוחות שונים נגד אותו צד שלישי, בעניינים נפרדים או במועדים שונים, אינו בהכרח ניגוד עניינים אסור, במיוחד אם אין חשש לניגוד אינטרסים בפועל וניתנה הסכמת הלקוחות ← עמל"ע (מחוזי י-ם) 26185-08-16.',
    '["כללי לשכת עורכי הדין (אתיקה מקצועית), תשמ\"ו-1986, כלל 14", "עמל\"ע (מחוזי י-ם) 26185-08-16 לשכת עורכי הדין - מחוז תל אביב נ'' קטי ברדה (23.01.2017)", "בד\"מ (ועדת משמעת לשכת עוה\"ד ארצי) 37/16 עו\"ד קטי ברדה נ'' ועדת האתיקה של לשכת עורכי הדין (07.07.2016)"]'::jsonb
  );
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_0, 'א', 'לא, שכן קיים ניגוד עניינים אינהרנטי בייצוג שתי גרושות נגד אותו אדם, גם אם במועדים שונים.', false, 'בחירה זו שגויה. הפסיקה קבעה כי עצם העובדה ששתי גרושות מנהלות משפטים נגד אדם אחד אינו יוצר ניגוד עניינים אינהרנטי, במיוחד אם מדובר בעניינים שונים או במועדים שונים.', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_0, 'ב', 'כן, שכן ייצוג שתי גרושות נגד אותו אדם אינו יוצר ניגוד עניינים אסור, במיוחד אם ההליכים הכלכליים של הגרושה הראשונה הסתיימו.', true, 'החלטה זו נכונה. בית המשפט קבע כי ייצוג שתי גרושות של אותו אדם אינו יוצר ניגוד עניינים או חשש לניגוד כזה, במיוחד כאשר ההליכים הקודמים הסתיימו ואין עניין משותף או לקוח משותף (עמל"ע (מחוזי י-ם) 26185-08-16).', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_0, 'ג', 'לא, אלא אם כן קיבלה עו"ד שרה הסכמה בכתב מאמנון לייצוג המשותף.', false, 'בחירה זו שגויה. אמנון הוא הצד שכנגד, ולא לקוח של עו"ד שרה, ולכן הסכמתו אינה רלוונטית לעניין ניגוד עניינים בין לקוחותיה.', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_0, 'ד', 'כן, אך רק אם בית הדין המשמעתי של לשכת עורכי הדין אישר את הייצוג המשותף.', false, 'בחירה זו שגויה. אין דרישה לאישור מוסדות האתיקה מראש במקרה כזה, אלא אם כן מתעורר חשש ממשי לניגוד עניינים המצדיק פנייה אליהם.', 4);

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_1, v_sq_id, 'ב', 'מבחן החשש לניגוד עניינים',
    2, 'מהו המבחן לקיומו של ניגוד עניינים לפי כלל 14(א) לכללי לשכת עורכי הדין (אתיקה מקצועית)?', 'שאלה זו בוחנת את המבחן המשפטי לקיומו של ניגוד עניינים לפי כלל 14(א) לכללי לשכת עורכי הדין (אתיקה מקצועית). היא מדגישה את אופיו האובייקטיבי וההתנהגותי של האיסור, ואת העובדה שדי בחשש לניגוד עניינים כדי להקים עבירה אתית.', 'כלל 14(א) לכללי לשכת עורכי הדין (אתיקה מקצועית) קובע כי "לא ייצג עורך דין לקוח... אם קיים חשש שלא יוכל למלא את חובתו המקצועית כלפיו, בשל עניין אישי שלו, או בשל התחייבות או חובת נאמנות שיש לו כלפי אחר או בשל עומס עבודה או בשל סיבה דומה אחרת". הפסיקה מפרשת איסור זה כעבירה התנהגותית ולא תוצאתית, כלומר, אין רלוונטיות לשאלה אם בפועל נגרם נזק או הוענקה טובה. המבחן לקיומו של החשש הוא אובייקטיבי, ודי בקיומו של חשש כזה, גם אם עורך הדין סבור שלא יגרום לתוצאה מזיקה. נורמת ההתנהגות הנדרשת מעורך דין מחמירה מזו הנדרשת מעובד ציבור, ואינה דורשת "אפשרות ממשית" אלא די ב"חשש" (ראו: עמל"ע (מחוזי י-ם) 53280-05-17 פודים נ'' לשכת עורכי הדין - בית הדין הארצי, וכן ת"א (מחוזי נצרת) 61096-10-25 זוהר כמיסה נ'' כרמית גיגי, רפרנס 11).',
    'הבלבול בין המבחן האובייקטיבי וההתנהגותי החל על עורכי דין לבין מבחנים אחרים (סובייקטיביים או תוצאתיים) או המבחן המקל יותר החל על עובדי ציבור.', '["ניגוד עניינים", "כלל 14(א)", "עבירה התנהגותית", "מבחן אובייקטיבי", "חשש לניגוד עניינים"]'::jsonb, '**וריאציה 1 — עורך דין מייצג את עצמו:** עורך דין מייצג את עצמו בתביעה, וגם לקוח אחר באותו עניין. האם זה ניגוד עניינים? ← כן, קיים חשש לניגוד עניינים בשל עניין אישי שלו, לפי כלל 14(א) לכללי האתיקה.
**וריאציה 2 — עורך דין עם עומס עבודה:** עורך דין מקבל לקוח חדש למרות עומס עבודה כבד, וקיים חשש שלא יוכל לטפל בו כראוי. האם זה ניגוד עניינים? ← כן, עומס עבודה הוא אחת הסיבות המנויות בכלל 14(א) להקמת חשש לניגוד עניינים.
**וריאציה 3 — הסכמת לקוח לניגוד עניינים אישי:** עורך דין מייצג לקוח בעניין שיש לו בו עניין אישי, והלקוח מסכים. האם ההסכמה מכשירה? ← לא, הסכמת הלקוח אינה משנה דבר ביחס לחובת עורך הדין להימנע מניגוד עניינים אישי לפי כלל 14(א) (עמל"ע (מחוזי י-ם) 53280-05-17, רפרנס 14).', 'ניגוד עניינים לפי כלל 14(א) הוא עבירה התנהגותית הנבחנת במבחן אובייקטיבי של חשש, ואין רלוונטיות לתוצאה בפועל או להסכמת הלקוח במקרה של עניין אישי ← עמל"ע (מחוזי י-ם) 53280-05-17.',
    '["כללי לשכת עורכי הדין (אתיקה מקצועית), תשמ\"ו-1986, כלל 14(א)", "עמל\"ע (מחוזי י-ם) 53280-05-17 גדעון פודים נ'' לשכת עורכי הדין - בית הדין הארצי (21.12.2017)", "ת\"א (מחוזי נצרת) 61096-10-25 זוהר כמיסה נ'' כרמית גיגי (27.04.2026)", "בד\"מ (ועדת משמעת לשכת עוה\"ד תל אביב-יפו) 56/24 ועדת האתיקה המחוזית של לשכת עורכי הדין מחוז ת\"א נ'' אדמית רוזנצוייט (25.01.2026)"]'::jsonb
  );
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_1, 'א', 'מבחן סובייקטיבי, הבוחן אם עורך הדין סבור שיוכל למלא את חובתו המקצועית.', false, 'בחירה זו שגויה. הפסיקה קבעה כי המבחן לקיומו של חשש לניגוד עניינים הוא אובייקטיבי, ולא סובייקטיבי התלוי בתחושתו של עורך הדין (בד"מ (ת"א) 56/01 הועד המחוזי של לשכת עורכי הדין בת"א יפו נ'' פלוני).', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_1, 'ב', 'מבחן אובייקטיבי, הבוחן אם קיים חשש שעורך הדין לא יוכל למלא את חובתו המקצועית, והעבירה היא התנהגותית ולא תוצאתית.', true, 'החלטה זו נכונה. הפסיקה קובעת כי האיסור המוטל על עורך דין לפעול מתוך חשש לניגוד עניינים לפי כלל 14(א) הוא עבירה התנהגותית ולא תוצאתית, ודי בקיומו של חשש אובייקטיבי, גם אם בפועל לא נגרם נזק (עמל"ע (מחוזי י-ם) 53280-05-17 פודים נ'' לשכת עורכי הדין - בית הדין הארצי).', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_1, 'ג', 'מבחן תוצאתי, הבוחן אם בפועל נגרם נזק ללקוח כתוצאה מניגוד העניינים.', false, 'בחירה זו שגויה. האיסור על ניגוד עניינים הוא עבירה התנהגותית, ואין רלוונטיות לשאלה אם בפועל נגרם נזק (עמל"ע (מחוזי י-ם) 53280-05-17).', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_1, 'ד', 'מבחן של אפשרות ממשית לניגוד עניינים, בדומה לעובדי ציבור.', false, 'בחירה זו שגויה. נורמת ההתנהגות הנדרשת מעורך דין מחמירה מזו הנדרשת מעובד ציבור, ודי בקיומו של חשש בלבד, ולא אפשרות ממשית (ת"א (מחוזי נצרת) 61096-10-25 זוהר כמיסה נ'' כרמית גיגי, רפרנס 11).', 4);

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_2, v_sq_id, 'ג', 'הסכמת לקוח לניגוד עניינים',
    3, 'עו"ד דניאל מייצג לקוח בעסקת מכר מקרקעין. לעו"ד דניאל יש עניין אישי בעסקה (לדוגמה, הוא רוכש חלק מהנכס). הלקוח מסכים בכתב לייצוג זה, לאחר שעו"ד דניאל גילה לו את מלוא פרטי העניין האישי. האם הסכמת הלקוח מכשירה את הייצוג?', 'שאלה זו עוסקת בחריגים לכלל ניגוד העניינים, ובפרט בשאלת תוקפה של הסכמת הלקוח לייצוג במצב של ניגוד עניינים. היא מבחינה בין סוגי ניגודי עניינים שונים (עניין אישי לעומת אינטרסים מנוגדים בין לקוחות) וכיצד הסכמת הלקוח משפיעה על כל אחד מהם, בהתאם לכלל 14 לכללי האתיקה.', 'כלל 14(א) לכללי לשכת עורכי הדין (אתיקה מקצועית) אוסר על עורך דין לייצג לקוח אם קיים חשש שלא יוכל למלא את חובתו המקצועית כלפיו, בשל עניין אישי שלו. הפסיקה קובעת כי חובה זו היא קוגנטית ואינה ניתנת להתניה, ולכן הסכמת הלקוח אינה מכשירה ייצוג במצב של עניין אישי של עורך הדין (ע"א 3640/22 עו"ד יורם ל. כהן נ'' רבקה בוכמן, רפרנס 39; ת"א (מחוזי ירושלים) 3324/01 אלמוני נ'' עזבון המנוח עו"ד פלוני ז"ל, רפרנס 61). זאת בניגוד לכלל 14(ב) ו-14(ג), המאפשרים ייצוג צדדים בעלי אינטרסים מנוגדים באותו עניין או ייצוג נגד לקוח קבוע, אם הצדדים הסכימו בכתב (כלל 14(ד)). הרציונל הוא שפער הכוחות בין עורך הדין ללקוח, והחשש לניצול לרעה של האמון, מצדיקים איסור מוחלט על ייצוג במצב של עניין אישי של עורך הדין.',
    'הנחה שגויה כי הסכמת לקוח, גם אם ניתנה בכתב ובידיעה מלאה, מכשירה כל סוג של ניגוד עניינים, תוך התעלמות מההבחנה בין כלל 14(א) לבין כלל 14(ד).', '["ניגוד עניינים", "כלל 14(א)", "כלל 14(ד)", "עניין אישי", "הסכמת לקוח", "חובת נאמנות קוגנטית"]'::jsonb, '**וריאציה 1 — ייצוג שני צדדים לעסקת מכר עם הסכמה בכתב:** עורך דין מייצג מוכר וקונה בעסקת מקרקעין, ושניהם הסכימו בכתב. האם זה מותר? ← כן, כלל 14(ד) לכללי האתיקה מאפשר זאת בעריכת הסכם, בתנאי שהצדדים הסכימו בכתב.
**וריאציה 2 — עורך דין רוכש נכס מלקוחו:** עורך דין רוכש נכס מלקוחו ומייצג אותו בעסקה. האם זה מותר בהסכמת הלקוח? ← לא, זהו ניגוד עניינים אישי לפי כלל 14(א), והסכמת הלקוח אינה מכשירה זאת (ת"א (מחוזי ת"א) 2272/04 בר נ'' פרנקל, עו"ד, רפרנס 67).
**וריאציה 3 — תיחום שירות מקצועי:** עורך דין ולקוח מסכימים בכתב לתחום את השירות המקצועי כדי למנוע התנגשות עם ייצוג לקוח אחר. האם זה מותר? ← כן, כלל 14(ה) לכללי האתיקה מאפשר זאת, בתנאי שהצמצום סביר ואינו פוגע בחובת הנאמנות.', 'הסכמת לקוח אינה מכשירה ניגוד עניינים הנובע מעניין אישי של עורך הדין (כלל 14(א)), שכן חובת הנאמנות במקרה זה קוגנטית. הסכמה בכתב יכולה להכשיר רק ניגוד עניינים בין לקוחות באותו עניין או נגד לקוח קבוע (כלל 14(ד)).',
    '["כללי לשכת עורכי הדין (אתיקה מקצועית), תשמ\"ו-1986, כלל 14", "ע\"א 3640/22 עו\"ד יורם ל. כהן נ'' רבקה בוכמן (01.09.2024)", "ת\"א (מחוזי ירושלים) 3324/01 אלמוני נ'' עזבון המנוח עו\"ד פלוני ז\"ל (16.04.2007)", "ת\"א (מחוזי ת\"א) 2272/04 עמנואל (דוד) בר נ'' מנחם פרנקל, עו\"ד (04.12.2008)"]'::jsonb
  );
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_2, 'א', 'כן, הסכמה בכתב לאחר גילוי מלא מכשירה כל ניגוד עניינים.', false, 'בחירה זו שגויה. הסכמה בכתב מכשירה ניגוד עניינים רק במקרים ספציפיים המנויים בכלל 14(ד) (ייצוג צדדים בעלי אינטרסים מנוגדים באותו עניין או לקוח קבוע), אך לא במקרה של עניין אישי של עורך הדין לפי כלל 14(א).', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_2, 'ב', 'לא, הסכמת הלקוח אינה מכשירה ניגוד עניינים הנובע מעניין אישי של עורך הדין, שכן חובת הנאמנות במקרה זה היא קוגנטית.', true, 'החלטה זו נכונה. הפסיקה קובעת כי חובת הנאמנות של עורך הדין לפי כלל 14(א) (עניין אישי) היא קוגנטית ולא דיספוזיטיבית, ולכן הסכמת הלקוח אינה משנה דבר ואינה מאפשרת לעורך הדין לפעול במצב של ניגוד עניינים אישי (ע"א 3640/22 עו"ד יורם ל. כהן נ'' רבקה בוכמן, רפרנס 39; ת"א (מחוזי ירושלים) 3324/01 אלמוני נ'' עזבון המנוח עו"ד פלוני ז"ל, רפרנס 61).', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_2, 'ג', 'כן, בתנאי שהייצוג המשותף סביר בנסיבות העניין ואינו פוגע בחובת הנאמנות.', false, 'בחירה זו שגויה. תנאי זה מתייחס לתיחום שירות מקצועי לפי כלל 14(ה), ולא לעניין אישי של עורך הדין לפי כלל 14(א), לגביו הסכמת הלקוח אינה מכשירה את הייצוג.', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_2, 'ד', 'לא, אלא אם כן הלקוח קיבל ייעוץ משפטי עצמאי לפני מתן הסכמתו.', false, 'בחירה זו שגויה. אף שייעוץ משפטי עצמאי הוא תנאי חשוב להכשרת הסכמים מסוימים בין עורך דין ללקוחו במצב של ניגוד עניינים (ע"א 3640/22), הוא אינו מאיין את האיסור הקוגנטי על ניגוד עניינים הנובע מעניין אישי של עורך הדין לפי כלל 14(א).', 4);

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_3, v_sq_id, 'ד', 'סמכות בית המשפט לפסול ייצוג',
    4, 'צד להליך אזרחי טוען כי עורך הדין של הצד שכנגד מצוי בניגוד עניינים. האם בית המשפט האזרחי מוסמך לפסול את הייצוג, או שזו סמכות בלעדית של מוסדות לשכת עורכי הדין?', 'שאלה זו עוסקת בסמכותו של בית המשפט האזרחי להתערב בסוגיות אתיות של עורכי דין, ובפרט להורות על פסילת ייצוג עקב ניגוד עניינים. היא מדגישה את העיקרון לפיו אף שהאכסניה הטבעית לבירור סוגיות אלו היא מוסדות לשכת עורכי הדין, לבית המשפט סמכות להתערב במקרים חריגים.', 'לבית המשפט האזרחי קיימת סמכות עקרונית לדון בטענות הנוגעות להפרת כללי האתיקה של עורכי דין ולתת צווים או סעדים בגין הפרות אלו, לרבות הוראה על הפסקת ייצוג. סמכות זו נובעת מסמכותו הכללית המעוגנת בסעיף 75 לחוק בתי המשפט. עם זאת, האכסניה הטבעית והרגילה לבירור שאלות אתיות היא מוסדות לשכת עורכי הדין, ובית המשפט יפעיל את סמכותו זו רק במקרים חריגים. הוא יפעיל את סמכותו לדון בסוגיה אתית ולהורות על הפסקת ייצוג רק כאשר ההפרה הנטענת עלולה לפגוע באינטרסים לגיטימיים של בעל הדין שהעלה אותה, ולא רק בטהרת המקצוע או כבודו (ראו: ת"א (מחוזי נצרת) 61096-10-25 זוהר כמיסה נ'' כרמית גיגי, רפרנס 7; ת"א (מחוזי נצרת) 36506-04-25 יהושוע רובין עו"ד נ'' יואן סורינקה, רפרנס 27; תמ"ש (משפחה אשדוד) 43572-01-21 פלוני נ'' פלונית, רפרנס 47).',
    'הנחה שגויה כי סוגיות אתיות הן בסמכות בלעדית של לשכת עורכי הדין, תוך התעלמות מהסמכות השיורית של בית המשפט האזרחי להגן על הגינות ההליך וזכויות בעלי הדין.', '["סמכות בית המשפט", "פסילת ייצוג", "ניגוד עניינים", "הגינות ההליך", "כללי אתיקה מקצועית"]'::jsonb, '**וריאציה 1 — פגיעה בטהרת המקצוע בלבד:** צד טוען לניגוד עניינים הפוגע בטהרת המקצוע בלבד. האם בית המשפט יפסול ייצוג? ← לא, בית המשפט יטה לפסול ייצוג רק אם יש פגיעה באינטרסים לגיטימיים של בעל הדין ובהגינות ההליך (ת"א (מחוזי נצרת) 61096-10-25, רפרנס 7).
**וריאציה 2 — שיהוי בטיפול ועדת האתיקה:** צד פנה לוועדת האתיקה, אך יש שיהוי ניכר בטיפול. האם בית המשפט יתערב? ← כן, במקרים של שיהוי ניכר בטיפול ועדת האתיקה, בית המשפט עשוי להכריע בעצמו בסוגיה (תמ"ש (משפחה אשדוד) 43572-01-21, רפרנס 48).
**וריאציה 3 — עורך דין מייצג את עצמו ואת לקוחו:** עורך דין נתבע יחד עם לקוחו, ומייצג את שניהם. האם בית המשפט יפסול ייצוג? ← כן, אם קיים חשש ממשי לפגיעה בהגינות ההליך או בזכויות דיוניות של הצד המבקש את הפסילה (ת"א (מחוזי נצרת) 61096-10-25, רפרנס 7).', 'בית המשפט האזרחי מוסמך לפסול ייצוג עורך דין במקרים חריגים, כאשר קיימת פגיעה מהותית באינטרסים לגיטימיים של בעל הדין ובהגינות ההליך, ולא רק בטהרת המקצוע ← סעיף 75 לחוק בתי המשפט ופסיקה רלוונטית.',
    '["חוק בתי המשפט [נוסח משולב], תשמ\"ד-1984, סעיף 75", "ת\"א (מחוזי נצרת) 61096-10-25 זוהר כמיסה נ'' כרמית גיגי (27.04.2026)", "ת\"א (מחוזי נצרת) 36506-04-25 יהושוע רובין עו\"ד נ'' יואן סורינקה (15.03.2026)", "תמ\"ש (משפחה אשדוד) 43572-01-21 פלוני נ'' פלונית (06.01.2022)"]'::jsonb
  );
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_3, 'א', 'זו סמכות בלעדית של מוסדות לשכת עורכי הדין, ובית המשפט האזרחי אינו מוסמך להתערב.', false, 'בחירה זו שגויה. אף שהאכסניה הטבעית לבירור שאלות אתיות היא מוסדות לשכת עורכי הדין, לבית המשפט האזרחי יש סמכות עקרונית להתערב במקרים חריגים (ת"א (מחוזי נצרת) 61096-10-25 זוהר כמיסה נ'' כרמית גיגי, רפרנס 7).', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_3, 'ב', 'בית המשפט האזרחי מוסמך לפסול ייצוג במקרים חריגים, כאשר הפגיעה היא באינטרסים לגיטימיים של בעל הדין ובהגינות ההליך.', true, 'החלטה זו נכונה. הפסיקה קובעת כי לבית המשפט האזרחי סמכות עקרונית לפסול ייצוג עורך דין במקרים חריגים, כאשר הסוגיה האתית פוגעת באופן ישיר ומהותי באינטרסים הלגיטימיים של הצד המבקש את הפסילה ובהגינות ההליך, ולא רק בטהרת המקצוע (ת"א (מחוזי נצרת) 61096-10-25 זוהר כמיסה נ'' כרמית גיגי, רפרנס 7).', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_3, 'ג', 'בית המשפט האזרחי מוסמך לפסול ייצוג רק לאחר קבלת חוות דעת ממוסדות האתיקה של לשכת עורכי הדין.', false, 'בחירה זו שגויה. בית המשפט יכול לפנות למוסדות האתיקה לקבלת חוות דעת, אך אינו חייב לעשות זאת, ובמקרים מסוימים יכול להכריע בעצמו, במיוחד אם יש שיהוי בקבלת החלטה (תמ"ש (משפחה אשדוד) 43572-01-21 פלוני נ'' פלונית, רפרנס 48).', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_3, 'ד', 'בית המשפט האזרחי מוסמך לפסול ייצוג רק אם עורך הדין הודה בקיומו של ניגוד עניינים.', false, 'בחירה זו שגויה. סמכות בית המשפט אינה תלויה בהודאת עורך הדין, אלא בקיומה של תשתית עובדתית המצביעה על פגיעה באינטרסים לגיטימיים ובהגינות ההליך.', 4);

  RAISE NOTICE 'Q% inserted: external_id %', 34, '2022-S-S-Q34';
END
$$;

