-- Q35 — 2022-S-S-Q35 — chapter=ethics subtopic=fees_client_funds_advertising
-- classifier_note: Lawyer identifying as such for non-legal volunteer fundraising — advertising/identification rules
-- ============================================================
DO $$
DECLARE
  v_sq_id uuid := '525dd5ac-3fc8-46ee-a9a0-dd5aa82a5160'::uuid;
  v_group_id uuid := 'd48029e4-ab76-4f7d-877d-13355550f108'::uuid;
  v_chapter_id uuid;
  v_subtopic_id uuid;
  v_existing_id uuid;
  v_ang_0 uuid := '46e111ae-611c-4b8a-9bf6-e79fea4c5b5c'::uuid;
  v_ang_1 uuid := '9bcae532-1fd1-4884-b2ce-b73f15d3e000'::uuid;
  v_ang_2 uuid := '56f7369b-1399-4b9b-a179-3dee6ab86a0d'::uuid;
  v_ang_3 uuid := 'ba8b2e67-daa1-4828-96e4-882e4ba99922'::uuid;
BEGIN
  SELECT id INTO v_existing_id FROM public.source_questions WHERE external_id = '2022-S-S-Q35';
  IF v_existing_id IS NOT NULL THEN
    RAISE NOTICE 'Q% skipped: external_id % already exists', 35, '2022-S-S-Q35';
    RETURN;
  END IF;

  SELECT id INTO v_chapter_id FROM public.chapters WHERE code = 'ethics';
  IF v_chapter_id IS NULL THEN
    RAISE EXCEPTION 'Chapter code % not found', 'ethics';
  END IF;

  SELECT id INTO v_subtopic_id FROM public.subtopics WHERE code = 'fees_client_funds_advertising' AND chapter_id = v_chapter_id;
  IF v_subtopic_id IS NULL THEN
    RAISE EXCEPTION 'Subtopic code % not found under chapter %', 'fees_client_funds_advertising', 'ethics';
  END IF;

  INSERT INTO public.source_questions (
    id, question_group_id, version, is_current, external_id, chapter_id, subtopic_id, question_text, source_metadata, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list, notes_for_admin, status, created_by
  ) VALUES (
    v_sq_id, v_group_id, 1, true,
    '2022-S-S-Q35', v_chapter_id, v_subtopic_id, 'עו"ד כהן הזדהה כעורך דין לצורך קבלת תרומות לתמיכה בפעילות ציבורית התנדבותית (שאינה נושאת אופי של עיסוק או ייעוץ משפטי) ולצורך פרסום ערוץ לקבלת תרומות וקישורו של הפרסום לאתר האינטרנט שלו ולדפי פרופיל שלו ברשתות החברתיות (להלן: הקישור). מה הדין?',
    '{"exam_year": 2022, "exam_season": "summer", "exam_part": 2, "exam_question_number": 35}'::jsonb, 'השאלה עוסקת בכללי האתיקה המקצועית החלים על עורכי דין לעניין פרסומת, ובפרט בהיתר לציין את התואר ''עורך דין'' ובמגבלות על קישור לאתרים חיצוניים. היא מתבססת על סעיפים 1 ו-3 לכללי לשכת עורכי הדין (פרסומת), תשס"א-2001.', 'סעיף 1 לכללי לשכת עורכי הדין (פרסומת), תשס"א-2001, קובע כי "עורך דין רשאי לציין, בעל פה או בכתב, את דבר היותו עורך דין". כלל זה מאפשר לעו"ד כהן להזדהות כעורך דין לצורך פעילות ציבורית התנדבותית, גם אם אינה נושאת אופי של עיסוק או ייעוץ משפטי. עם זאת, סעיף 3(ו) לכללים (בנוסח תשע"ח-2018) קובע כי עורך דין רשאי להוסיף באתר האינטרנט שלו או בדף האישי שלו ברשת החברתית קישור לאתר אינטרנט אחר, "ובלבד שהקישור נוגע באופן ישיר לעיסוקו המקצועי של עורך הדין". במקרה הנדון, הקישור הוא לפעילות ציבורית התנדבותית שאינה נושאת אופי של עיסוק או ייעוץ משפטי, ולכן אינו נוגע באופן ישיר לעיסוקו המקצועי כעורך דין. לפיכך, עו"ד כהן אינו רשאי להוסיף את הקישור לאתר האינטרנט שלו ולדפי הפרופיל שלו ברשתות החברתיות.', 'הנחה שגויה כי כל פעילות ציבורית של עורך דין, גם אם אינה מקצועית, מאפשרת קישור לאתר המקצועי שלו, תוך התעלמות מהדרישה שהקישור יגע באופן ישיר לעיסוקו המקצועי.',
    '["כללי פרסומת", "אתיקה מקצועית", "ציון תואר עורך דין", "קישור לאתר אינטרנט", "פעילות ציבורית"]'::jsonb, '**וריאציה 1 — קישור לאתר משפטי אחר:** עורך דין מפרסם באתר שלו קישור לאתר של פסקי דין. האם מותר? ← כן, הקישור נוגע באופן ישיר לעיסוקו המקצועי, לפי סעיף 3(ו) לכללי הפרסומת.
**וריאציה 2 — קישור לאתר אישי שאינו מקצועי:** עורך דין מפרסם באתר שלו קישור לבלוג אישי על תחביביו. האם מותר? ← לא, הקישור אינו נוגע באופן ישיר לעיסוקו המקצועי, ולכן אסור לפי סעיף 3(ו) לכללי הפרסומת.
**וריאציה 3 — הזדהות כעורך דין בכנס מקצועי:** עורך דין מזדהה כעורך דין בכנס מקצועי שאינו קשור ישירות לתחום עיסוקו. האם מותר? ← כן, סעיף 1 לכללי הפרסומת מתיר לציין את התואר בעל פה או בכתב באופן כללי.', 'עורך דין רשאי לציין את תוארו בעל פה או בכתב בכל הקשר. עם זאת, קישור לאתר אינטרנט אחר מותר רק אם הוא נוגע באופן ישיר לעיסוקו המקצועי ← סעיפים 1 ו-3(ו) לכללי לשכת עורכי הדין (פרסומת).', '["כללי לשכת עורכי הדין (פרסומת), תשס\"א-2001, כלל 1", "כללי לשכת עורכי הדין (פרסומת), תשס\"א-2001, כלל 3(ו)", "בג\"ץ 6250/05 איציק לוי נ'' לשכת עורכי הדין בישראל (20.10.2005)"]'::jsonb,
    'classification_review: original chapter=''סדר דין פלילי'' subtopic=''משמעת עורכי דין'' → mapped chapter=''ethics'' subtopic=''fees_client_funds_advertising'' | classifier_note: Lawyer identifying as such for non-legal volunteer fundraising — advertising/identification rules | source_review_note: סיווג תת-הנושא ''משמעת עורכי דין'' תחת ''סדר דין פלילי'' אינו מדויק לחלוטין עבור שאלה העוסקת בכללי אתיקה בייצוג אזרחי. הנושא מתאים יותר ל''אתיקה מקצועית'' תחת פרק נפרד או ''סדר דין אזרחי'' אם כי אין תת-נושא ספציפי. נבחר ''משמעת עורכי דין'' כברירת מחדל הקרובה ביותר מתוך הרשימה הסגורה.', 'active', 'b9ecdde2-d07e-4761-96ab-05f0ad32d4e3'
  );

  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'א', 'עו"ד כהן רשאי לציין בכתב או בעל פה את דבר היותו עו"ד, אך לא להוסיף את הקישור לאתר האינטרנט שלו ולדפי הפרופיל שלו ברשתות החברתיות.', true, 'סעיף 1 לכללי לשכת עורכי הדין (פרסומת) מתיר לעורך דין לציין את תוארו בעל פה או בכתב. סעיף 3(ו) לכללים מתיר קישור לאתר אחר רק אם הוא נוגע באופן ישיר לעיסוקו המקצועי, מה שלא מתקיים בפעילות ציבורית התנדבותית שאינה משפטית.', 1);
  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'ב', 'עו"ד כהן אינו רשאי להזדהות כעורך דין במסגרת פעילות ציבורית כלשהי שאינה נוגעת למקצוע עריכת הדין, וכן אינו רשאי להוסיף את הקישור לאתר האינטרנט שלו ולדפי הפרופיל שלו ברשתות החברתיות.', false, 'בחירה זו שגויה בחלקה הראשון. סעיף 1 לכללי הפרסומת מתיר לעורך דין לציין את תוארו בעל פה או בכתב, ללא הגבלה לפעילות מקצועית בלבד.', 2);
  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'ג', 'עו"ד כהן רשאי לציין בעל פה אך לא בכתב את דבר היות עורך דין, וקישור כאמור צריך לגעת באופן ישיר לעיסוקו המקצועי של עו"ד כהן כעורך דין.', false, 'בחירה זו שגויה בחלקה הראשון. סעיף 1 לכללי הפרסומת מתיר לציין את התואר גם בעל פה וגם בכתב. החלק השני נכון אך אינו הופך את כל התשובה לנכונה.', 3);
  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'ד', 'עו"ד כהן אינו רשאי להזדהות כעורך דין במסגרת פעילות ציבורית כלשהי שאינה נוגעת למקצוע עריכת הדין, אך רשאי להוסיף קישור כאמור לאתר המקצועי שלו כעורך דין לצורך קבלת תרומות לאותה פעילות ציבורית.', false, 'בחירה זו שגויה בחלקה הראשון. סעיף 1 לכללי הפרסומת מתיר לעורך דין לציין את תוארו בעל פה או בכתב. שגויה גם בחלקה השני, שכן הקישור צריך לגעת באופן ישיר לעיסוקו המקצועי, ולא לפעילות ציבורית שאינה כזו.', 4);

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_0, v_sq_id, 'א', 'פרסום תחומי עיסוק ותפקידים',
    1, 'עו"ד דנה מפרסמת בעיתון יומי שתי מודעות פרסומת. במודעות היא מציינת שהיא עוסקת בדיני משפחה, שהיא יו"ר הוועדה לענייני משפחה בלשכה, ומבטיחה הנחה של 10% לעשרת הפונים הראשונים. מה הדין?', 'שאלה זו בוחנת את ההגבלות על תוכן וצורת פרסומת של עורכי דין בעיתונות, כפי שנקבעו בכללי לשכת עורכי הדין (פרסומת). היא מתמקדת באיסורים על פרסום הנחות, ציון תפקידים בלשכה, ומספר המודעות המותרות בגיליון אחד.', 'כללי לשכת עורכי הדין (פרסומת), תשס"א-2001, קובעים מגבלות על פרסומת של עורכי דין. סעיף 3(ג) (בנוסח תשע"ח-2018) קובע כי עורך דין רשאי לפרסם מודעת פרסומת אחת באותו גיליון של עיתון. סעיף 3(ב)(17) (בנוסח תשע"ח-2018) מתיר ציון תפקידים וחברות בלשכה בכפוף לסעיף 3(ב)(18), אך בנוסח הכללים שקדם לתיקון תשע"ח-2018, ציון תפקידים בלשכה היה אסור (כפי שעולה מבג"ץ 6250/05, רפרנס 5). בנוסף, ועדת הייעוץ לענייני פרסומות קבעה כי לא ניתן לפרסם הנחות במתן שירותים משפטיים (בג"ץ 6250/05, רפרנס 5). לכן, עו"ד דנה הפרה את הכללים בכך שפרסמה שתי מודעות, ציינה תפקיד בלשכה והבטיחה הנחה.',
    'הנחה שגויה כי כל פרט המעיד על מקצועיות או ניסיון מותר לפרסום, תוך התעלמות מהאיסורים הספציפיים על פרסום הנחות, תפקידים בלשכה ומגבלות על כמות הפרסום.', '["כללי פרסומת", "אתיקה מקצועית", "הבטחת הנחה", "תפקידים בלשכה", "מגבלות פרסום"]'::jsonb, '**וריאציה 1 — פרסום תחומי עיסוק בלבד:** עורך דין מפרסם בעיתון את תחומי עיסוקו. האם מותר? ← כן, סעיף 3(ב)(10) לכללי הפרסומת מתיר זאת.
**וריאציה 2 — פרסום תואר אקדמי:** עורך דין מפרסם בעיתון את תוארו האקדמי. האם מותר? ← כן, סעיף 3(ב)(4) לכללי הפרסומת מתיר זאת.
**וריאציה 3 — פרסום המלצות באתר אינטרנט:** עורך דין מפרסם באתר האינטרנט שלו המלצות מלקוחות. האם מותר? ← כן, סעיף 3(יא) לכללי הפרסומת מתיר זאת, ובלבד שאין רושם מטעה.', 'פרסומת עורכי דין בעיתונות מוגבלת למודעה אחת בגיליון, אסור לפרסם הנחות, וציון תפקידים בלשכה היה אסור (בנוסח הישן) ← כלל 3 לכללי הפרסומת ובג"ץ 6250/05.',
    '["כללי לשכת עורכי הדין (פרסומת), תשס\"א-2001, כלל 3", "בג\"ץ 6250/05 איציק לוי נ'' לשכת עורכי הדין בישראל (20.10.2005)"]'::jsonb
  );
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_0, 'א', 'הפרסום מותר במלואו, שכן הוא כולל פרטים רלוונטיים לעיסוקה המקצועי.', false, 'בחירה זו שגויה. חלקים מהפרסום אסורים לפי כללי הפרסומת, כגון פרסום הנחה, ציון תפקיד בלשכה ופרסום יותר ממודעה אחת באותו גיליון.', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_0, 'ב', 'הפרסום אסור, שכן אסור לפרסם יותר ממודעה אחת באותו גיליון, אסור לציין תפקידים בלשכה ואסור להבטיח הנחות.', true, 'סעיף 3(ג) לכללי הפרסומת מתיר מודעת פרסומת אחת בלבד באותו גיליון. סעיף 3(ב)(17) מתיר ציון תפקידים בלשכה בכפוף לסעיף 3(ב)(18), אך סעיף 3(ג)(3) (בנוסח הישן) אסר זאת. בנוסף, הפסיקה קבעה כי אסור לפרסם הנחות (בג"ץ 6250/05, רפרנס 5).', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_0, 'ג', 'הפרסום מותר, למעט ציון תפקידה כיו"ר הוועדה לענייני משפחה בלשכה.', false, 'בחירה זו שגויה. בנוסף לאיסור על ציון התפקיד, אסור גם לפרסם הנחות ואסור לפרסם יותר ממודעה אחת באותו גיליון.', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_0, 'ד', 'הפרסום מותר, למעט הבטחת הנחה לעשרת הפונים הראשונים.', false, 'בחירה זו שגויה. בנוסף לאיסור על פרסום הנחה, אסור גם לציין תפקיד בלשכה ואסור לפרסם יותר ממודעה אחת באותו גיליון.', 4);

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_1, v_sq_id, 'ב', 'אחריות עורך דין לפרסומת של חברה',
    2, 'עו"ד ירון הוא שותף בחברת עורכי דין. החברה פרסמה בעיתון פרסומת המפרה את כללי לשכת עורכי הדין (פרסומת). עו"ד ירון טוען כי האחריות לפרסומת היא של החברה בלבד, וכי הוא אינו חב באחריות משמעתית אישית. מה הדין?', 'שאלה זו עוסקת באחריות המשמעתית של עורך דין הפועל במסגרת חברת עורכי דין, ובפרט לעניין הפרת כללי הפרסומת. היא בוחנת את סעיף 59ו לחוק לשכת עורכי הדין, המדגיש את אחריותו האישית של עורך הדין גם כאשר הפעולה נעשית באמצעות חברה.', 'סעיף 59ו לחוק לשכת עורכי הדין, תשכ"א-1961, קובע מפורשות כי "אין בקיומה של חברת עורכי דין ובחירת עורך דין חבר בה כדי לגרוע: (1) מאחריותו האישית של עורך הדין כפי שהיתה קיימת לולא החברה או חברותו בה; (2) מתחולת חוק זה על עורך הדין". פסיקת בית המשפט העליון (בר"ש 4660/12 עו"ד אברהם עזריאלנט נ'' לשכת עורכי הדין בישראל) הדגישה כי חברת עורכי דין אינה "כביש עוקף" המשחרר את עורך הדין מאחריותו המשמעתית. לכן, עו"ד ירון חב באחריות אישית לפרסומת האסורה, גם אם פורמלית היא נעשתה על ידי החברה.',
    'הנחה שגויה כי התאגדות כחברת עורכי דין מעניקה חסינות מפני אחריות משמעתית אישית, בדומה לאחריות מוגבלת בתאגידים אחרים.', '["אחריות משמעתית", "חברת עורכי דין", "חוק לשכת עורכי הדין", "כללי פרסומת", "אחריות אישית"]'::jsonb, '**וריאציה 1 — עורך דין שכיר בחברה:** עורך דין שכיר בחברת עורכי דין ביצע עבירה משמעתית. האם הוא חב באחריות אישית? ← כן, סעיף 59ו לחוק לשכת עורכי הדין חל על כל עורך דין חבר בחברה, לרבות שכיר.
**וריאציה 2 — פרסומת של חברה ללא ידיעת השותף:** חברת עורכי דין פרסמה פרסומת אסורה ללא ידיעת אחד השותפים. האם השותף חב באחריות? ← כן, האחריות היא אישית ואינה תלויה בידיעה ספציפית, אלא בעצם היותו שותף בחברה (בר"ש 4660/12, רפרנס 9).
**וריאציה 3 — אחריות אזרחית של חברת עורכי דין:** חברת עורכי דין התרשלה בייצוג לקוח. האם החברה חבה באחריות אזרחית? ← כן, החברה היא אישיות משפטית נפרדת וחבה באחריות אזרחית, בנוסף לאחריות האישית של עורך הדין המתרשל.', 'עורך דין הפועל במסגרת חברת עורכי דין נותר אחראי באופן אישי לכללי האתיקה ולדין המשמעתי, וקיומה של החברה אינו גורע מאחריותו זו ← סעיף 59ו לחוק לשכת עורכי הדין ובר"ש 4660/12.',
    '["חוק לשכת עורכי הדין, תשכ\"א-1961, סעיף 59ו", "בר\"ש 4660/12 עו\"ד אברהם עזריאלנט נ'' לשכת עורכי הדין בישראל (12.07.2012)"]'::jsonb
  );
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_1, 'א', 'עו"ד ירון צודק, שכן חברת עורכי דין היא אישיות משפטית נפרדת, והאחריות מוטלת עליה.', false, 'בחירה זו שגויה. סעיף 59ו לחוק לשכת עורכי הדין קובע במפורש כי קיומה של חברת עורכי דין אינו גורע מאחריותו האישית של עורך הדין.', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_1, 'ב', 'עו"ד ירון אינו צודק, שכן סעיף 59ו לחוק לשכת עורכי הדין קובע כי קיומה של חברת עורכי דין אינו גורע מאחריותו האישית של עורך הדין.', true, 'סעיף 59ו לחוק לשכת עורכי הדין קובע כי אין בקיומה של חברת עורכי דין כדי לגרוע מאחריותו האישית של עורך הדין כפי שהייתה קיימת לולא החברה. לכן, עורך דין ירון חב באחריות משמעתית אישית.', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_1, 'ג', 'האחריות מוטלת על החברה, אלא אם כן הוכח כי עו"ד ירון ידע על הפרסומת האסורה ואישר אותה.', false, 'בחירה זו שגויה. האחריות האישית של עורך הדין אינה תלויה בידיעתו או אישורו הספציפי לפרסומת, אלא נובעת מעצם היותו שותף בחברה המפרסמת (בר"ש 4660/12, רפרנס 9).', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_1, 'ד', 'האחריות מוטלת על החברה, אך ניתן להרים מסך ולהטיל אחריות על עו"ד ירון במקרים חריגים.', false, 'בחירה זו שגויה. אין צורך ב"הרמת מסך" כדי להטיל אחריות על עורך הדין, שכן סעיף 59ו לחוק קובע אחריות אישית ישירה (בר"ש 4660/12, רפרנס 13).', 4);

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_2, v_sq_id, 'ג', 'פרסום המלצות ודירוגים',
    3, 'עו"ד שירן מפרסמת באתר האינטרנט של משרדה המלצות מלקוחות מרוצים וכן את דירוג משרדה במדריך דירוג מקצועי. האם פרסום זה מותר?', 'שאלה זו עוסקת בהיתר לפרסום המלצות ודירוגים על ידי עורכי דין, כפי שנקבע בכללי לשכת עורכי הדין (פרסומת). היא מדגישה את התנאי המרכזי לפיו הפרסום לא יצור רושם מטעה.', 'סעיף 3(יא) לכללי לשכת עורכי הדין (פרסומת), תשס"א-2001, קובע כי "בפרסומת כאמור בסעיף קטן (א) רשאי עורך דין לפרסם המלצות, מכתבי תודה ודירוג במדריכי דירוג; המידע יימסר באופן שאין בו כדי ליצור רושם מטעה על אודות עורך הדין". כלל זה מאפשר לעורכי דין לפרסם מידע מסוג זה, בכפוף לחובה כללית שלא ליצור רושם מטעה. לכן, פרסום המלצות ודירוגים על ידי עו"ד שירן מותר, כל עוד הוא עומד בתנאי זה.',
    'הנחה שגויה כי פרסום המלצות ודירוגים אסור באופן גורף, או שהדבר דורש תנאים נוספים שאינם מנויים במפורש בכללים.', '["כללי פרסומת", "המלצות לקוחות", "דירוג מקצועי", "רושם מטעה", "אתיקה מקצועית"]'::jsonb, '**וריאציה 1 — פרסום המלצות בכתב יד:** עורך דין מפרסם באתר המשרד המלצות בכתב יד של לקוחות. האם מותר? ← כן, כל עוד אין רושם מטעה, לפי סעיף 3(יא) לכללי הפרסומת.
**וריאציה 2 — פרסום דירוג שאינו עדכני:** עורך דין מפרסם דירוג ממדריך מקצועי מלפני 5 שנים. האם מותר? ← לא, פרסום דירוג שאינו עדכני עלול ליצור רושם מטעה, ולכן אסור לפי סעיף 3(יא) לכללי הפרסומת.
**וריאציה 3 — פרסום המלצות תוך ציון שמות לקוחות:** עורך דין מפרסם המלצות תוך ציון שמות מלאים של לקוחות. האם מותר? ← כן, אם הלקוחות הצהירו בכתב כי הבינו שהם חופשיים לסרב וכי מתן השירות לא הותנה בפרסום שמם, לפי סעיף 3(ט) לכללי הפרסומת.', 'פרסום המלצות ודירוגים על ידי עורך דין מותר, ובלבד שאין בו כדי ליצור רושם מטעה ← סעיף 3(יא) לכללי לשכת עורכי הדין (פרסומת).',
    '["כללי לשכת עורכי הדין (פרסומת), תשס\"א-2001, כלל 3(יא)", "כללי לשכת עורכי הדין (פרסומת), תשס\"א-2001, כלל 3(ט)"]'::jsonb
  );
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_2, 'א', 'לא, פרסום המלצות ודירוגים אסור על פי כללי הפרסומת, שכן הוא עלול ליצור רושם מטעה.', false, 'בחירה זו שגויה. סעיף 3(יא) לכללי הפרסומת מתיר פרסום המלצות ודירוגים, ובלבד שאין בהם כדי ליצור רושם מטעה.', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_2, 'ב', 'כן, פרסום המלצות ודירוגים מותר, ובלבד שאין בו כדי ליצור רושם מטעה על אודות עורך הדין.', true, 'סעיף 3(יא) לכללי לשכת עורכי הדין (פרסומת) קובע כי עורך דין רשאי לפרסם המלצות, מכתבי תודה ודירוג במדריכי דירוג, ובלבד שהמידע יימסר באופן שאין בו כדי ליצור רושם מטעה.', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_2, 'ג', 'כן, אך רק אם הלקוחות נתנו הסכמתם בכתב לפרסום ההמלצות.', false, 'בחירה זו שגויה. סעיף 3(יא) אינו דורש הסכמה בכתב של הלקוחות לפרסום המלצות, בניגוד לסעיף 3(ט) הדורש הסכמה לפרסום שמות לקוחות.', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_2, 'ד', 'לא, אלא אם כן הדירוג ניתן על ידי גוף רשמי של לשכת עורכי הדין.', false, 'בחירה זו שגויה. סעיף 3(יא) אינו מגביל את מקור הדירוג לגוף רשמי של הלשכה, אלא מתייחס ל"מדריכי דירוג" באופן כללי.', 4);

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_3, v_sq_id, 'ד', 'פרסום מאמרים בתשלום',
    4, 'עו"ד איתי משלם לעיתון מקומי עבור פרסום מאמר מקצועי שכתב. במאמר הוא מציג את מומחיותו בתחום דיני העבודה. האם פרסום זה מותר?', 'שאלה זו עוסקת בהיתר לעורכי דין לפרסם מאמרים מקצועיים בתשלום, ובתנאי המרכזי לכך. היא בוחנת את הוראת סעיף 3(י)(2) לכללי לשכת עורכי הדין (פרסומת), המאפשרת פרסום כזה בכפוף לגילוי נאות.', 'סעיף 3(י)(2) לכללי לשכת עורכי הדין (פרסומת), תשס"א-2001, קובע כי עורך דין רשאי "לשלם בעד פרסום מאמרים מקצועיים, ראיונות וניהול פורומים ובלבד שייכתב מפורשות במקום הפרסום כי מדובר בפרסומת". תנאי זה נועד להבטיח שקיפות כלפי הציבור, כך שהקוראים ידעו כי מדובר בתוכן ממומן ולא בתוכן מערכתי אובייקטיבי. לכן, עו"ד איתי רשאי לפרסם את מאמרו בתשלום, ובלבד שיציין מפורשות שמדובר בפרסומת.',
    'הנחה שגויה כי כל פרסום בתשלום אסור, או התעלמות מהדרישה הספציפית לגילוי נאות במקרה של מאמרים מקצועיים ממומנים.', '["כללי פרסומת", "מאמר מקצועי", "פרסום בתשלום", "גילוי נאות", "אתיקה מקצועית"]'::jsonb, '**וריאציה 1 — פרסום מאמר ללא תשלום:** עורך דין מפרסם מאמר מקצועי בעיתון ללא תשלום. האם מותר? ← כן, סעיף 3(י)(1) לכללי הפרסומת מתיר זאת ללא תנאי.
**וריאציה 2 — פרסום ראיון בתשלום:** עורך דין משלם עבור פרסום ראיון עמו בעיתון. האם מותר? ← כן, אם יצוין מפורשות שמדובר בפרסומת, לפי סעיף 3(י)(2) לכללי הפרסומת.
**וריאציה 3 — פרסום מאמר בתשלום ללא ציון פרסומת:** עורך דין משלם עבור פרסום מאמר מקצועי, אך לא מציין שמדובר בפרסומת. האם מותר? ← לא, הפרסום אסור, שכן הוא מפר את התנאי המפורש בסעיף 3(י)(2) לכללי הפרסומת.', 'פרסום מאמרים מקצועיים בתשלום על ידי עורך דין מותר, ובלבד שיצוין מפורשות במקום הפרסום כי מדובר בפרסומת ← סעיף 3(י)(2) לכללי לשכת עורכי הדין (פרסומת).',
    '["כללי לשכת עורכי הדין (פרסומת), תשס\"א-2001, כלל 3(י)"]'::jsonb
  );
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_3, 'א', 'לא, אסור לעורך דין לשלם עבור פרסום מאמרים מקצועיים.', false, 'בחירה זו שגויה. סעיף 3(י)(2) לכללי הפרסומת מתיר תשלום עבור פרסום מאמרים מקצועיים, בתנאי שמצוין כי מדובר בפרסומת.', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_3, 'ב', 'כן, אך רק אם יצוין מפורשות במקום הפרסום כי מדובר בפרסומת.', true, 'סעיף 3(י)(2) לכללי לשכת עורכי הדין (פרסומת) קובע כי עורך דין רשאי לשלם בעד פרסום מאמרים מקצועיים, ובלבד שייכתב מפורשות במקום הפרסום כי מדובר בפרסומת.', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_3, 'ג', 'כן, ללא כל תנאי, שכן מדובר בפרסום מקצועי לגיטימי.', false, 'בחירה זו שגויה. קיים תנאי מפורש בסעיף 3(י)(2) לכללי הפרסומת, לפיו יש לציין שמדובר בפרסומת.', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_3, 'ד', 'לא, אלא אם כן המאמר פורסם באתר האינטרנט של עורך הדין בלבד.', false, 'בחירה זו שגויה. סעיף 3(י)(2) מתייחס לפרסום מאמרים באופן כללי, ולא מגביל זאת לאתר האינטרנט של עורך הדין.', 4);

  RAISE NOTICE 'Q% inserted: external_id %', 35, '2022-S-S-Q35';
END
$$;

