-- Q36 — 2022-S-S-Q36 — chapter=contracts subtopic=limitation  [needs_review]
-- classifier_note: Miriam claiming title in 2022 against 1990 judgment — statute of limitations on judgment enforcement; property dimension noted
-- ============================================================
DO $$
DECLARE
  v_sq_id uuid := 'dcad3ffd-ff4e-44ba-bb26-105c9bdaf9cd'::uuid;
  v_group_id uuid := 'a1caef07-2a55-43ba-bbba-e99ab57a90ab'::uuid;
  v_chapter_id uuid;
  v_subtopic_id uuid;
  v_existing_id uuid;
  v_ang_0 uuid := '91bbf26e-9f5c-478a-8c32-1decfc8719c8'::uuid;
  v_ang_1 uuid := '3abdef9a-e326-4b35-9cdd-02e29af4cb00'::uuid;
  v_ang_2 uuid := '0906dda7-c5a4-46af-bb9a-1de055961e0b'::uuid;
  v_ang_3 uuid := '9b7c597c-bc6f-45fd-b371-7cfe5df8e93b'::uuid;
BEGIN
  SELECT id INTO v_existing_id FROM public.source_questions WHERE external_id = '2022-S-S-Q36';
  IF v_existing_id IS NOT NULL THEN
    RAISE NOTICE 'Q% skipped: external_id % already exists', 36, '2022-S-S-Q36';
    RETURN;
  END IF;

  SELECT id INTO v_chapter_id FROM public.chapters WHERE code = 'contracts';
  IF v_chapter_id IS NULL THEN
    RAISE EXCEPTION 'Chapter code % not found', 'contracts';
  END IF;

  SELECT id INTO v_subtopic_id FROM public.subtopics WHERE code = 'limitation' AND chapter_id = v_chapter_id;
  IF v_subtopic_id IS NULL THEN
    RAISE EXCEPTION 'Subtopic code % not found under chapter %', 'limitation', 'contracts';
  END IF;

  INSERT INTO public.source_questions (
    id, question_group_id, version, is_current, external_id, chapter_id, subtopic_id, question_text, source_metadata, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list, notes_for_admin, status, created_by
  ) VALUES (
    v_sq_id, v_group_id, 1, true,
    '2022-S-S-Q36', v_chapter_id, v_subtopic_id, 'בשנת 1990, בתום דיונים ארוכים בעניין, ניתן בבית המשפט המחוזי בתל אביב פסק דין הקובע שהבעלים של המקרקעין הידועים כגוש 5500 חלקה 210 הם משה ואהרן. ביום 1.1.2022 הגישה מרים תובענה להצהרה עליה כבעלים של אותם מקרקעין. משה ואהרן מעוניינים להגיש את פסק הדין במסגרת התובענה. מה הדין?',
    '{"exam_year": 2022, "exam_season": "summer", "exam_part": 2, "exam_question_number": 36}'::jsonb, 'השאלה עוסקת בהתיישנות פסקי דין, ובפרט בהבחנה בין פסק דין ''טעון ביצוע'' לבין פסק דין ''שאינו טעון ביצוע'', כפי שנקבע בסעיף 21 לחוק ההתיישנות, תשי"ח-1958. היא בוחנת את מהותו של פסק דין המצהיר על בעלות במקרקעין והאם הוא נתון להתיישנות.', 'סעיף 21 לחוק ההתיישנות, תשי"ח-1958, קובע כי "פסק דין בתובענה שעברו עליו עשרים וחמש שנה בלי שהזכאי לפיו עשה פעולה כל שהיא כדי לבצעו, רשאי החייב לטעון טענת התיישנות; ואולם פסק דין בתובענה שלפי תכנו אינו טעון ביצוע אינו נתון להתיישנות". פסק דין הקובע שהבעלים של מקרקעין הם פלוני, הוא פסק דין הצהרתי במהותו. פסק דין הצהרתי אינו מחייב את הצדדים לעשות פעולה אקטיבית, אלא רק קובע מצב משפטי קיים. לכן, הוא נחשב כפסק דין שאינו ''טעון ביצוע'' ואינו נתון להתיישנות כלל. הלכת לחאם (ע"א 288/95, רפרנס 13, 15, 31, 47) דנה בהרחבה בסוגיה זו וקבעה כי יש לבחון את מהות ותוכן פסק הדין. במקרה הנדון, פסק הדין רק קבע את הבעלות, ולכן הוא אינו מתיישן. (ראו גם תל"א (מחוזי ת"א) 7969-10-15, רפרנס 9, 10, 11, 12).', 'הטעות הנפוצה היא להניח שכל פסק דין, ללא קשר למהותו, נתון לתקופת התיישנות של 25 שנים, תוך התעלמות מהחריג המפורש בסעיף 21 לחוק ההתיישנות לגבי פסקי דין שאינם טעונים ביצוע.',
    '["התיישנות פסק דין", "פסק דין הצהרתי", "פסק דין טעון ביצוע", "חוק ההתיישנות", "מקרקעין"]'::jsonb, '**וריאציה 1 — פסק דין המורה על העברת בעלות במקרקעין:** פסק דין מ-1990 הורה על העברת בעלות במקרקעין. האם הוא מתיישן? ← כן, זהו פסק דין טעון ביצוע, ויתיישן בחלוף 25 שנה אם לא נעשתה פעולה לביצועו (סעיף 21 לחוק ההתיישנות והלכת לחאם, רפרנס 15, 31, 47).
**וריאציה 2 — פסק דין המצהיר על זכות קניינית:** פסק דין מ-1990 הצהיר על זכות קניינית במקרקעין. האם הוא מתיישן? ← לא, זהו פסק דין הצהרתי שאינו טעון ביצוע, ולכן אינו מתיישן (סעיף 21 לחוק ההתיישנות, רפרנס 9, 10, 11, 12).
**וריאציה 3 — פסק דין המאשר הסכם פשרה הכולל חיובים אופרטיביים:** פסק דין מ-1990 אישר הסכם פשרה שכלל חיובים אופרטיביים לביצוע פעולות במקרקעין. האם הוא מתיישן? ← כן, אם פסק הדין כולל חיובים אופרטיביים, הוא ייחשב כטעון ביצוע ויתיישן בחלוף 25 שנה אם לא נעשתה פעולה לביצועו (הלכת לחאם, רפרנס 15, 31, 47).', 'פסק דין המצהיר על בעלות במקרקעין הוא פסק דין שאינו טעון ביצוע, ולכן אינו נתון להתיישנות כלל, בניגוד לפסק דין אופרטיבי המחייב פעולה אקטיבית, שמתיישן בחלוף 25 שנה ← סעיף 21 לחוק ההתיישנות והלכת לחאם.', '["חוק ההתיישנות, תשי\"ח-1958, סעיף 21", "ע\"א 288/95 ג''ורג''ט נקולא סארגי לחאם נ'' נימר סלים אל-זארובי, נד(2) 598 (2000)", "תל\"א (מחוזי ת\"א) 7969-10-15 עו\"ד חיה אזולאי- כונסת נכסים נ'' יורשי-יורשיו של המנוח זכריה הברי ז\"ל (2016)"]'::jsonb,
    'needs_review=true | classification_review: original chapter=''סדר דין אזרחי'' subtopic=''הליכים'' → mapped chapter=''contracts'' subtopic=''limitation'' | classifier_note: Miriam claiming title in 2022 against 1990 judgment — statute of limitations on judgment enforcement; property dimension noted | source_review_note: הסיווג תחת תת-הנושא ''הליכים'' הוא הכללי ביותר מבין האפשרויות הקיימות ברשימה הסגורה, אך אינו ספציפי מספיק לנושא ''התיישנות פסק דין''. נושא זה הוא בעל חשיבות רבה וראוי לתת-נושא ייעודי.', 'active', 'b9ecdde2-d07e-4761-96ab-05f0ad32d4e3'
  );

  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'א', 'פסק הדין התיישן בשנת 1997.', false, 'בחירה זו שגויה, שכן תקופת ההתיישנות של פסק דין הטעון ביצוע היא 25 שנה, ולא 7 שנים, ופסק דין הצהרתי אינו מתיישן כלל.', 1);
  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'ב', 'פסק הדין התיישן בשנת 2000.', false, 'בחירה זו שגויה, שכן פסק דין הצהרתי אינו נתון להתיישנות, ולכן לא חלה עליו תקופת התיישנות כלל.', 2);
  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'ג', 'פסק הדין התיישן בשנת 2015.', false, 'בחירה זו שגויה, שכן פסק דין הצהרתי אינו נתון להתיישנות, ולכן לא חלה עליו תקופת התיישנות כלל, גם לא תקופת 25 השנים.', 3);
  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'ד', 'פסק הדין טרם התיישן.', true, 'סעיף 21 לחוק ההתיישנות קובע כי פסק דין שאינו טעון ביצוע אינו נתון להתיישנות. פסק דין הקובע בעלות הוא פסק דין הצהרתי במהותו, שאינו טעון ביצוע, ולכן אינו מתיישן.', 4);

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_0, v_sq_id, 'א', 'התיישנות פסק דין הצהרתי',
    1, 'בשנת 1995, ניתן פסק דין בבית המשפט המחוזי שהצהיר כי ראובן הוא הבעלים של דירה מסוימת. בשנת 2023, ראובן מעוניין לרשום את בעלותו על הדירה בלשכת רישום המקרקעין בהתבסס על פסק הדין. האם פסק הדין התיישן?', 'שאלה זו בוחנת את ההבחנה המהותית בין פסק דין ''טעון ביצוע'' לבין פסק דין ''שאינו טעון ביצוע'' לעניין סעיף 21 לחוק ההתיישנות. היא מדגישה כי פסק דין הצהרתי, המצהיר על זכות קיימת, אינו נתון להתיישנות כלל, בניגוד לפסק דין אופרטיבי המחייב פעולה אקטיבית.', 'סעיף 21 לחוק ההתיישנות, תשי"ח-1958, קובע כי "פסק דין בתובענה שעברו עליו עשרים וחמש שנה בלי שהזכאי לפיו עשה פעולה כל שהיא כדי לבצעו, רשאי החייב לטעון טענת התיישנות; ואולם פסק דין בתובענה שלפי תכנו אינו טעון ביצוע אינו נתון להתיישנות". פסק דין המצהיר על בעלות במקרקעין הוא פסק דין הצהרתי במהותו, שאינו טעון ביצוע, שכן הוא אינו מחייב את הצדדים לעשות פעולה אקטיבית אלא רק קובע מצב משפטי קיים. הלכת ''לחאם'' (ע"א 288/95) דנה בהרחבה בסוגיה זו, וקבעה כי יש לבחון את מהות ותוכן פסק הדין. במקרה זה, פסק הדין רק קבע שראובן הוא הבעלים, ולכן הוא אינו מתיישן. (ראו גם ת"א (מחוזי ת"א) 7969-10-15, רפרנס 9, 10, 11, 12).',
    'טעות נפוצה היא להחיל את תקופת ההתיישנות של 25 שנים על כל פסק דין, מבלי להבחין בין פסק דין אופרטיבי לפסק דין הצהרתי.', '["התיישנות פסק דין", "פסק דין הצהרתי", "פסק דין טעון ביצוע", "חוק ההתיישנות", "מקרקעין"]'::jsonb, '**וריאציה 1 — פסק דין המורה על פינוי:** פסק דין מ-1990 הורה על פינוי פולש ממקרקעין. האם הוא מתיישן? ← כן, זהו פסק דין טעון ביצוע, ויתיישן בחלוף 25 שנה אם לא נעשתה פעולה לביצועו (סעיף 21 לחוק ההתיישנות).
**וריאציה 2 — פסק דין המורה על תשלום כספי:** פסק דין מ-1990 חייב נתבע בתשלום כספי. האם הוא מתיישן? ← כן, זהו פסק דין טעון ביצוע, ויתיישן בחלוף 25 שנה אם לא נעשתה פעולה לביצועו (סעיף 21 לחוק ההתיישנות).
**וריאציה 3 — פסק דין המאשר הסכם פשרה:** פסק דין מ-1990 אישר הסכם פשרה שכלל סעיפים הצהרתיים וסעיפים אופרטיביים. האם הוא מתיישן? ← יש לבחון את מהות פסק הדין. אם הוא כולל חיובים אופרטיביים, הוא ייחשב כטעון ביצוע ויתיישן (ע"א 288/95 לחאם, רפרנס 15, 31, 47).', 'פסק דין הצהרתי, שאינו טעון ביצוע, אינו נתון להתיישנות כלל, בניגוד לפסק דין אופרטיבי הטעון ביצוע, שמתיישן בחלוף 25 שנה אם לא נעשתה פעולה לביצועו ← סעיף 21 לחוק ההתיישנות והלכת לחאם.',
    '["חוק ההתיישנות, תשי\"ח-1958, סעיף 21", "ע\"א 288/95 ג''ורג''ט נקולא סארגי לחאם נ'' נימר סלים אל-זארובי, נד(2) 598 (2000)", "תל\"א (מחוזי ת\"א) 7969-10-15 עו\"ד חיה אזולאי- כונסת נכסים נ'' יורשי-יורשיו של המנוח זכריה הברי ז\"ל (2016)"]'::jsonb
  );
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_0, 'א', 'כן, פסק הדין התיישן בחלוף 25 שנים ממועד נתינתו.', false, 'בחירה זו שגויה, שכן פסק דין הצהרתי אינו נתון להתיישנות, ולכן תקופת 25 השנים אינה חלה עליו.', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_0, 'ב', 'לא, פסק דין הצהרתי אינו נתון להתיישנות.', true, 'סעיף 21 לחוק ההתיישנות קובע במפורש כי פסק דין בתובענה שלפי תוכנו אינו טעון ביצוע אינו נתון להתיישנות. פסק דין המצהיר על בעלות הוא פסק דין הצהרתי שאינו טעון ביצוע.', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_0, 'ג', 'כן, פסק הדין התיישן בחלוף 7 שנים ממועד נתינתו, שכן מדובר בזכות שאינה במקרקעין.', false, 'בחירה זו שגויה. מדובר בזכות במקרקעין, אך גם אם לא, פסק דין הצהרתי אינו מתיישן כלל, ותקופת 7 השנים חלה על עילות תביעה רגילות, לא על פסקי דין.', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_0, 'ד', 'לא, אלא אם כן ראובן לא עשה כל פעולה לביצועו במשך 25 שנים.', false, 'בחירה זו שגויה. התנאי של ''פעולה כלשהי'' רלוונטי לפסק דין הטעון ביצוע. פסק דין הצהרתי אינו טעון ביצוע ולכן אינו מתיישן ללא קשר לפעולות שנעשו.', 4);

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_1, v_sq_id, 'ב', 'מבחן פסק דין "טעון ביצוע"',
    2, 'מהו המבחן העיקרי שנקבע בפסיקה לקביעה האם פסק דין הוא "טעון ביצוע" או "אינו טעון ביצוע" לעניין סעיף 21 לחוק ההתיישנות?', 'שאלה זו מתמקדת במבחן המהותי שנקבע בפסיקה, בעיקר בהלכת לחאם, לצורך סיווג פסק דין כ''טעון ביצוע'' או ''שאינו טעון ביצוע''. ההבחנה קריטית לקביעת תחולת תקופת ההתיישנות של 25 שנים הקבועה בסעיף 21 לחוק ההתיישנות.', 'הלכת לחאם (ע"א 288/95, רפרנס 15, 31, 47) קבעה כי יש לקבוע את סיווגו של פסק דין כ''טעון ביצוע'' או ''שאינו טעון ביצוע'' על פי תוכנו, מהותו ומאפייניו. פסק דין המטיל חיוב אקטיבי על צד (כגון תשלום כספי, העברת בעלות במקרקעין, פינוי) הוא פסק דין טעון ביצוע. לעומת זאת, פסק דין המצהיר על זכות קיימת (כגון בעלות) הוא פסק דין שאינו טעון ביצוע. דעת הרוב בלחאם הדגישה כי גם פסק דין הכולל הצהרה על זכות, אך מחייב פעולות נוספות למימושה (כמו רישום במקרקעין), ייחשב כטעון ביצוע. (ראו גם עע"מ 8832/12 עיריית חיפה נ'' יצחק סלומון בע"מ, רפרנס 37, 38).',
    'הבלבול בין פסק דין הכולל רכיבים הצהרתיים לבין פסק דין הצהרתי צרוף. גם פסק דין אופרטיבי יכול לכלול הצהרה, אך אם הוא מחייב פעולה, הוא טעון ביצוע.', '["פסק דין טעון ביצוע", "פסק דין הצהרתי", "הלכת לחאם", "סעיף 21 לחוק ההתיישנות", "מהות פסק הדין"]'::jsonb, '**וריאציה 1 — פסק דין המורה על רישום זכויות במקרקעין:** פסק דין מורה לרשם המקרקעין לרשום זכויות. האם הוא טעון ביצוע? ← כן, הוא מחייב פעולה אקטיבית של רישום (ע"א 288/95 לחאם, רפרנס 15, 31, 47).
**וריאציה 2 — פסק דין המצהיר על גיל:** פסק דין מצהיר על גילו של אדם. האם הוא טעון ביצוע? ← לא, זהו פסק דין הצהרתי צרוף שאינו מחייב פעולה אקטיבית (ת"א (מחוזי חי'') 35036-07-20, רפרנס 32).
**וריאציה 3 — פסק דין המאשר הסכם פשרה להעברת מקרקעין:** פסק דין מאשר הסכם פשרה להעברת בעלות במקרקעין. האם הוא טעון ביצוע? ← כן, דעת הרוב בלחאם קבעה שפסק דין לאכיפת התחייבות אובליגטורית של הסכם למכירת מקרקעין הוא פסק דין טעון ביצוע (ע"א 288/95 לחאם, רפרנס 15, 31, 47).', 'פסק דין "טעון ביצוע" הוא פסק דין שמחייב פעולה אקטיבית, גם אם הוא כולל רכיבים הצהרתיים. פסק דין "שאינו טעון ביצוע" רק מצהיר על זכות קיימת. הסיווג נקבע לפי תוכן, מהות ומאפייני פסק הדין ← סעיף 21 לחוק ההתיישנות והלכת לחאם.',
    '["חוק ההתיישנות, תשי\"ח-1958, סעיף 21", "ע\"א 288/95 ג''ורג''ט נקולא סארגי לחאם נ'' נימר סלים אל-זארובי, נד(2) 598 (2000)", "עע\"מ 8832/12 עיריית חיפה נ'' יצחק סלומון בע\"מ (2015)", "ת\"א (מחוזי חי'') 35036-07-20 ראדי אסעד נ'' מדינת ישראל (2021)"]'::jsonb
  );
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_1, 'א', 'האם פסק הדין ניתן בהליך אזרחי או בהליך מינהלי.', false, 'בחירה זו שגויה. סעיף 21 לחוק ההתיישנות מתייחס ל"פסק דין בתובענה", המוגדרת כהליך אזרחי. השאלה היא מהות פסק הדין בתוך ההליך האזרחי, ולא סוג ההליך.', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_1, 'ב', 'האם פסק הדין מחייב את הצדדים לעשות פעולה אקטיבית או רק מצהיר על זכות קיימת.', true, 'הפסיקה, ובראשה הלכת לחאם, קבעה כי יש לקבוע את סיווגו של פסק הדין על פי תוכנו, מהותו ומאפייניו. פסק דין המחייב פעולה אקטיבית הוא טעון ביצוע, בעוד שפסק דין המצהיר על זכות קיימת אינו טעון ביצוע (ע"א 288/95 לחאם, רפרנס 15, 31, 47).', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_1, 'ג', 'האם פסק הדין ניתן בהסכמה או לאחר שמיעת ראיות.', false, 'בחירה זו שגויה. אופן מתן פסק הדין (בהסכמה או לאחר דיון) אינו משנה את מהותו לעניין סיווגו כטעון ביצוע או לא (ת"א (מחוזי חי'') 4044400, רפרנס 22).', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_1, 'ד', 'האם פסק הדין עוסק במקרקעין או בזכויות שאינן במקרקעין.', false, 'בחירה זו שגויה. סוג הנכס (מקרקעין או לא) אינו הקריטריון המכריע לסיווג פסק הדין כטעון ביצוע או לא, אלא מהות הסעד שניתן בו (ת"א (מחוזי חי'') 48049-12-19, רפרנס 58).', 4);

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_2, v_sq_id, 'ג', 'פעולה לביצוע פסק דין',
    3, 'בשנת 1990, ניתן פסק דין שחייב את ראובן לשלם לשמעון 100,000 ש"ח. בשנת 2000, שמעון שלח לראובן מכתב דרישה לתשלום. בשנת 2010, שמעון פתח תיק הוצאה לפועל לביצוע פסק הדין. בשנת 2023, ראובן טוען כי פסק הדין התיישן. מהו הדין לגבי השפעת פעולותיו של שמעון על תקופת ההתיישנות?', 'שאלה זו בוחנת את השפעת ''פעולה כלשהי'' לביצוע פסק דין על מרוץ ההתיישנות, כפי שנקבע בסעיף 21 לחוק ההתיישנות. היא מתייחסת למחלוקת שהתגלעה בהלכת לחאם בין דעת הרוב לדעת המיעוט, ומדגישה את ההלכה המחייבת לפיה פעולה כזו מאפסת את מרוץ ההתיישנות.', 'סעיף 21 לחוק ההתיישנות קובע כי פסק דין מתיישן בחלוף 25 שנה "בלי שהזכאי לפיו עשה פעולה כל שהיא כדי לבצעו". הפסיקה, ובראשה דעת הרוב בהלכת לחאם (ע"א 288/95, השופטת שטרסברג-כהן, רפרנס 16, 34, 35, 36), קבעה כי "פעולה כל שהיא" לביצוע פסק דין אינה מבטלת את ההתיישנות לחלוטין, אלא מאפסת את מרוץ ההתיישנות, כך שהוא מתחיל להימנות מחדש ממועד ביצוע הפעולה. הפרשנות ל"פעולה כל שהיא" היא רחבה ואינה מוגבלת לפתיחת תיק הוצאה לפועל בלבד, אלא כוללת גם משא ומתן, מכתבי דרישה וכל גילוי דעת ברור של הזוכה כי הוא עומד על ביצוע פסק הדין (ע"א 8301/98 אנואר, רפרנס 53, 54; (רשם ההוצאה לפועל רמלה) 509667-12-23, רפרנס 34, 35, 36). במקרה זה, הן מכתב הדרישה והן פתיחת תיק ההוצאה לפועל נחשבים כפעולות המאפסות את מרוץ ההתיישנות.',
    'הבלבול בין דעת הרוב לדעת המיעוט בהלכת לחאם לגבי השפעת פעולה לביצוע פסק דין על מרוץ ההתיישנות (ביטול מול איפוס).', '["התיישנות פסק דין", "פעולה לביצוע פסק דין", "איפוס מרוץ התיישנות", "הלכת לחאם", "סעיף 21 לחוק ההתיישנות"]'::jsonb, '**וריאציה 1 — משא ומתן לביצוע פסק דין:** זוכה מנהל משא ומתן עם החייב לביצוע פסק דין. האם זה נחשב פעולה לביצוע? ← כן, משא ומתן המעיד על עמידה על ביצוע פסק הדין נחשב פעולה המאפסת את מרוץ ההתיישנות (ע"א 8301/98 אנואר, רפרנס 53, 54).
**וריאציה 2 — רישום הערת אזהרה:** זוכה רשם הערת אזהרה לטובתו מכוח פסק דין. האם זה נחשב פעולה לביצוע? ← כן, רישום הערת אזהרה נחשב פעולה לביצוע פסק הדין (ת"א (מחוזי נצ'') 47787-12-18, רפרנס 18; ת"א (מחוזי חי'') 4044400, רפרנס 23).
**וריאציה 3 — פסק דין שאינו טעון ביצוע:** פסק דין הצהרתי שאינו טעון ביצוע. האם פעולה כלשהי משפיעה על התיישנותו? ← לא, פסק דין שאינו טעון ביצוע אינו נתון להתיישנות כלל, ללא קשר לפעולות שנעשו (סעיף 21 לחוק ההתיישנות).', 'פעולה לביצוע פסק דין (כגון מכתב דרישה, משא ומתן, פתיחת תיק הוצל"פ) מאפסת את מרוץ ההתיישנות של 25 שנים, והוא מתחיל להימנות מחדש ממועד הפעולה ← סעיף 21 לחוק ההתיישנות והלכת לחאם (דעת הרוב).',
    '["חוק ההתיישנות, תשי\"ח-1958, סעיף 21", "ע\"א 288/95 ג''ורג''ט נקולא סארגי לחאם נ'' נימר סלים אל-זארובי, נד(2) 598 (2000)", "ע\"א 8301/98 הדסה אנואר נ'' ש.א.פ. בע\"מ, נו(3) 345 (2002)", "ת\"א (מחוזי חי'') 47787-12-18 קרן קיימת לישראל נ'' עז'' המנוח אחמד נאיף סלאמה ז\"ל (2023)", "(רשם ההוצאה לפועל רמלה) 509667-12-23 החייב נ'' (2025)"]'::jsonb
  );
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_2, 'א', 'פעולותיו של שמעון ביטלו לחלוטין את תקופת ההתיישנות, ופסק הדין אינו מתיישן עוד.', false, 'בחירה זו משקפת את דעת המיעוט בהלכת לחאם (השופט טירקל), אך אינה ההלכה המחייבת. דעת הרוב קבעה כי פעולה לביצוע פסק דין מאפסת את מרוץ ההתיישנות, אך אינה מבטלת אותו לחלוטין.', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_2, 'ב', 'כל פעולה שנקט שמעון לביצוע פסק הדין, לרבות מכתב דרישה ופתיחת תיק הוצאה לפועל, מאפסת את מרוץ ההתיישנות של 25 שנים מחדש.', true, 'הלכת לחאם (דעת הרוב) קבעה כי פעולה לביצוע פסק דין מאפסת את מרוץ ההתיישנות, כך שהוא מתחיל להימנות מחדש ממועד הפעולה. ''פעולה כלשהי'' כוללת גם משא ומתן וגילוי דעת ברור (ע"א 8301/98 אנואר, רפרנס 53, 54; (רשם ההוצאה לפועל רמלה) 509667-12-23, רפרנס 34, 35, 36).', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_2, 'ג', 'רק פתיחת תיק הוצאה לפועל מאפסת את מרוץ ההתיישנות, אך מכתב דרישה אינו נחשב פעולה כזו.', false, 'בחירה זו שגויה. הפסיקה הרחיבה את הפרשנות ל"פעולה כל שהיא" וקבעה כי היא אינה מוגבלת לפתיחת תיק הוצאה לפועל בלבד, אלא כוללת גם פעולות אחרות המעידות על עמידה על ביצוע פסק הדין, כגון משא ומתן (ע"א 8301/98 אנואר, רפרנס 53, 54).', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_2, 'ד', 'פעולותיו של שמעון רק עיכבו את מרוץ ההתיישנות, אך לא אפסו אותו, ולכן פסק הדין התיישן בשנת 2015.', false, 'בחירה זו שגויה. הפסיקה קבעה כי פעולה לביצוע פסק דין מאפסת את מרוץ ההתיישנות, ולא רק מעכבת אותו (ע"א 288/95 לחאם, רפרנס 16, 34, 35, 36).', 4);

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_3, v_sq_id, 'ד', 'התיישנות חוב ארנונה חלוט',
    4, 'חוב ארנונה של ראובן לעיריית תל אביב הפך חלוט בשנת 2010, לאחר שחלף המועד להגשת השגה. העירייה הגישה תביעה לגביית החוב בשנת 2020. ראובן טוען כי החוב התיישן. מהי תקופת ההתיישנות החלה על חוב זה?', 'שאלה זו בוחנת את ההבחנה בין "פסק דין בתובענה" לבין "חוב פסוק" שאינו תוצאה של הליך שיפוטי, לעניין תחולת תקופת ההתיישנות. היא מדגישה כי חוב ארנונה חלוט, אף שהוא בעל תוקף מחייב, אינו נחשב פסק דין לצורך סעיף 21 לחוק ההתיישנות, ולכן חלה עליו תקופת ההתיישנות הכללית.', 'סעיף 21 לחוק ההתיישנות קובע תקופת התיישנות של 25 שנים ל"פסק דין בתובענה". סעיף 1 לחוק ההתיישנות מגדיר "תובענה" כ"הליך אזרחי לפני בית משפט". הפסיקה, ובראשה עע"מ 8832/12 עיריית חיפה נ'' יצחק סלומון בע"מ (רפרנס 37, 38, 51, 52), קבעה כי חוב ארנונה שהפך חלוט בהיעדר השגה, אף שהוא "חוב פסוק" וניתן לגבותו בהליכים מינהליים, אינו נחשב "פסק דין בתובענה" במובן סעיף 21 לחוק ההתיישנות. לכן, תקופת ההתיישנות החלה עליו היא התקופה הכללית לתביעה שאינה במקרקעין, שהיא 7 שנים לפי סעיף 5(1) לחוק ההתיישנות. (ראו גם פש"ר (מחוזי חי'') 44129-11-15, רפרנס 70).',
    'הנחה שגויה כי כל חוב בעל תוקף מחייב, גם אם מקורו בהליך מינהלי, נחשב "פסק דין" לעניין תקופת ההתיישנות הארוכה יותר.', '["התיישנות חוב", "חוב ארנונה חלוט", "פסק דין בתובענה", "חוק ההתיישנות", "הליך מינהלי"]'::jsonb, '**וריאציה 1 — חוב ארנונה חלוט שטרם התיישן:** חוב ארנונה חלוט מ-2018, העירייה הגישה תביעה ב-2023. האם התיישן? ← לא, חלפו 5 שנים, פחות מ-7 שנות ההתיישנות (עע"מ 8832/12, רפרנס 37, 38).
**וריאציה 2 — חוב ארנונה חלוט במקרקעין מוסדרים:** חוב ארנונה חלוט הקשור למקרקעין מוסדרים. האם חלה עליו התיישנות של 25 שנה? ← לא, סעיף 159(ב) לחוק המקרקעין אינו חל על חובות כספיים, ועל חוב ארנונה חלוט חלה התיישנות של 7 שנים (עע"מ 8832/12, רפרנס 37, 38).
**וריאציה 3 — חוב ארנונה שניתן לגביו פסק דין:** חוב ארנונה שהוגשה לגביו תביעה לבית משפט וניתן פסק דין. מהי תקופת ההתיישנות? ← 25 שנים, שכן זהו "פסק דין בתובענה" (סעיף 21 לחוק ההתיישנות).', 'חוב ארנונה חלוט אינו נחשב "פסק דין בתובענה" לעניין סעיף 21 לחוק ההתיישנות, ולכן חלה עליו תקופת התיישנות כללית של 7 שנים, ולא 25 שנים ← עע"מ 8832/12 עיריית חיפה נ'' יצחק סלומון בע"מ.',
    '["חוק ההתיישנות, תשי\"ח-1958, סעיף 5(1)", "חוק ההתיישנות, תשי\"ח-1958, סעיף 21", "עע\"מ 8832/12 עיריית חיפה נ'' יצחק סלומון בע\"מ (2015)", "עת\"מ (מינהליים ת\"א) 39434-10-23 שירלי לידזי כהן נ'' עיריית בת ים (2025)", "פש\"ר (מחוזי חי'') 44129-11-15 חוסין סלים נ'' עו\"ד אביב רונן, הנאמן (2016)"]'::jsonb
  );
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_3, 'א', '25 שנים, שכן חוב ארנונה חלוט נחשב כ"פסק דין בתובענה".', false, 'בחירה זו שגויה. הפסיקה קבעה כי חוב ארנונה חלוט אינו נחשב "פסק דין בתובענה" לעניין סעיף 21 לחוק ההתיישנות, ולכן תקופת ההתיישנות אינה 25 שנים (עע"מ 8832/12 עיריית חיפה נ'' יצחק סלומון בע"מ, רפרנס 37, 38).', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_3, 'ב', '7 שנים, שכן חוב ארנונה חלוט נחשב כחוב "רגיל" שאינו במקרקעין.', true, 'הפסיקה קבעה כי חוב ארנונה חלוט, אף שהוא "חוב פסוק", אינו נחשב "פסק דין בתובענה" כהגדרתו בסעיף 21 לחוק ההתיישנות. לכן, חלה עליו תקופת ההתיישנות הכללית של 7 שנים לתביעה שאינה במקרקעין, לפי סעיף 5(1) לחוק ההתיישנות (עע"מ 8832/12 עיריית חיפה נ'' יצחק סלומון בע"מ, רפרנס 37, 38, 51, 52).', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_3, 'ג', '15 שנים, שכן מדובר בחוב הקשור למקרקעין לא מוסדרים.', false, 'בחירה זו שגויה. תקופת 15 השנים חלה על תביעות במקרקעין לא מוסדרים, ולא על חובות כספיים הקשורים למקרקעין (סעיף 5(2) לחוק ההתיישנות).', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_3, 'ד', 'אין התיישנות על חובות לרשות מקומית.', false, 'בחירה זו שגויה. חובות לרשות מקומית, לרבות ארנונה, נתונים להתיישנות, אלא אם כן נקבע אחרת בחוק ספציפי (עע"מ 8832/12 עיריית חיפה נ'' יצחק סלומון בע"מ, רפרנס 37, 38).', 4);

  RAISE NOTICE 'Q% inserted: external_id %', 36, '2022-S-S-Q36';
END
$$;

