  v_ang_0 uuid := 'bedb4bd5-d751-4a5a-80d7-1eec918a7e3b'::uuid;
  v_ang_1 uuid := 'b1c55d6a-9f3f-478e-954f-74666cf76bd4'::uuid;
  v_ang_2 uuid := 'c6278152-0c10-4641-82f4-4d0aab9ce6fb'::uuid;
  v_ang_3 uuid := '303d0860-a913-4ef4-81f8-32a2c20fb9c1'::uuid;
BEGIN
