  INSERT INTO public.source_questions (
    id, question_group_id, version, is_current, external_id, chapter_id, subtopic_id, question_text, source_metadata, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list, notes_for_admin, status, created_by
  ) VALUES (
    v_sq_id, v_group_id, 1, true,
    '2022-S-S-Q37', v_chapter_id, v_subtopic_id, 'ציונה היא אישה בת 75 המתגוררת בדירה ששטחה 70 מ"ר למעלה מ-20 שנה. שווי הדירה המוערך הוא 1,000,000 ש"ח. אבי הוא יזם שהתקשר עימה בעסקת "פינוי-בינוי", ובכוונתו להקים בניין של דירות סטודיו קטנות במקום. לציונה הובטח לקבל שתי דירות. שוויין של הדירות בבניין שייבנה אחיד, והוא עומד על 600,000 ש"ח ליחידה. מה הדין?',
    '{"exam_year": 2022, "exam_season": "summer", "exam_part": 2, "exam_question_number": 37}'::jsonb, 'השאלה עוסקת בפטור ממס שבח במכירת דירת מגורים במסגרת פרויקט פינוי-בינוי, תוך התמקדות בתנאים המיוחדים החלים על ''קשיש'' המקבל שתי יחידות מגורים חלופיות. היא בוחנת את הוראות סעיף 49כב לחוק מיסוי מקרקעין (שבח ורכישה), התשכ"ג-1963, ואת תכליות הפטור הסוציאליות.', 'סעיף 49כב(א2) לחוק מיסוי מקרקעין (שבח ורכישה), התשכ"ג-1963, קובע כי "קשיש המוכר ליזם את כל הזכויות שיש לו ביחידת המגורים הנמכרת במתחם, שתמורתה ניתנו לו שתי יחידות מגורים חלופיות, זכאי בשל המכירה לפטור ממס לפי הוראות סעיף קטן (א), בתנאים הקבועים בו, ויחולו על שתי היחידות החלופיות ההוראות החלות על יחידת מגורים חלופית". ''קשיש'' מוגדר בסעיף 49יט(א) לחוק, בין היתר, כמי שמלאו לו 70 שנים והתגורר ביחידת המגורים הנמכרת שנתיים רצופות לפחות. ציונה עומדת בהגדרה זו (בת 75, גרה 20+ שנה). הפטור לפי סעיף 49כב(א) מוגבל בתקרת שווי, שהיא הגבוה מבין 150% משווי היחידה הנמכרת או שווי דירת מגורים בשטח 120 מ"ר באותו מתחם. במקרה זה, שווי הדירה הנמכרת הוא 1,000,000 ש"ח, ולכן תקרת השווי היא 1,500,000 ש"ח (150% מ-1,000,000 ש"ח). ציונה מקבלת שתי דירות ששווי כל אחת 600,000 ש"ח, כלומר סך של 1,200,000 ש"ח. מכיוון שסך שווי הדירות החלופיות (1,200,000 ש"ח) אינו עולה על תקרת השווי (1,500,000 ש"ח), ציונה זכאית לפטור מלא ממס שבח בגין המכירה. תכלית הפטור היא סוציאלית, ומטרתה לאפשר לבעלי דירות, ובמיוחד לקשישים, לשפר את תנאי מגוריהם מבלי שנטל המס יכביד עליהם (ע"א 10742/03 חדד נ'' מנהל מיסוי מקרקעין נתניה, רפרנס 1; ע"א 6486/02 להב נ'' מנהל מס שבח מקרקעין, רפרנס 12, 14).', 'הנחה שגויה כי קבלת יותר מיחידת מגורים חלופית אחת תמיד שוללת את הפטור ממס שבח, תוך התעלמות מהחריג המיוחד לקשישים בפרק פינוי-בינוי.',
    '["פינוי-בינוי", "פטור ממס שבח", "קשיש", "יחידת מגורים חלופית", "תקרת שווי", "סעיף 49כב(א2)"]'::jsonb, '**וריאציה 1 — קשיש המקבל שתי דירות העולות על התקרה:** קשיש קיבל שתי דירות חלופיות בשווי כולל של 1,800,000 ש"ח, כאשר תקרת השווי היא 1,500,000 ש"ח. מה הדין? ← הקשיש יחויב במס על ההפרש של 300,000 ש"ח, שכן סך התמורה עלה על התקרה (סעיף 49כב(א2) ו-49כב(א)(2) לחוק).
**וריאציה 2 — קשיש המקבל יחידה חלופית אחת ותמורה כספית:** קשיש קיבל יחידה חלופית אחת ותמורה כספית, וסך התמורה אינו עולה על תקרת השווי. מה הדין? ← הקשיש פטור ממס שבח לחלוטין, שכן הוא עומד בתנאי סעיף 49כב(א3) לחוק.
**וריאציה 3 — קשיש שאינו עומד בתנאי המגורים:** אדם בן 75 שרכש את הדירה לפני שנה בלבד. האם הוא נחשב ''קשיש'' לצורך הפטור? ← לא, הוא אינו עומד בתנאי המגורים של שנתיים רצופות לפני צו ההכרזה, ולכן אינו ''קשיש'' לעניין זה (סעיף 49יט(א) לחוק).', 'קשיש המוכר דירה בפינוי-בינוי ומקבל שתי יחידות חלופיות, פטור ממס שבח לחלוטין, ובלבד ששווי שתי היחידות יחד אינו עולה על תקרת השווי (150% משווי הדירה הנמכרת או שווי דירה 120 מ"ר, הגבוה מביניהם) ← סעיף 49כב(א2) לחוק מיסוי מקרקעין.', '["חוק מיסוי מקרקעין (שבח ורכישה), תשכ\"ג-1963, סעיף 49כב(א2)", "חוק מיסוי מקרקעין (שבח ורכישה), תשכ\"ג-1963, סעיף 49יט(א)", "אבי גורמן, שי אהרונוביץ'' מיסוי מקרקעין – פרשנות, הלכה ומעשה (2017) | 8.8.2 סעיף 49כב(א) לחוק מיסוי מקרקעין - פטור ממסים, עמ'' 39", "ע\"א 10742/03 יוסף חדד נ'' מנהל מיסוי מקרקעין נתניה, ס(2) 23 (23.06.2005)", "ע\"א 6486/02 רחל להב נ'' מנהל מס שבח מקרקעין (09.10.2005)"]'::jsonb,
    'classification_review: original chapter=''סדר דין אזרחי'' subtopic=''הליכים'' → mapped chapter=''tax'' subtopic=''real_estate_tax'' | classifier_note: Tziyona (75) in pinui-binui deal — tax treatment of evacuation-reconstruction transactions | source_review_note: הסיווג תחת תת-הנושא ''הליכים'' הוא הכללי ביותר מבין האפשרויות הקיימות ברשימה הסגורה, אך אינו ספציפי מספיק לנושא ''מיסוי מקרקעין - פינוי-בינוי''. נושא זה הוא בעל חשיבות רבה וראוי לתת-נושא ייעודי.', 'active', 'b9ecdde2-d07e-4761-96ab-05f0ad32d4e3'
  );

  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'א', 'ציונה חבה במס בגין המכירה בגין ההפרש בין הדירה שמכרה לדירות שתקבל.', false, 'בחירה זו שגויה, שכן ציונה עומדת בתנאי הפטור המלא לקשיש המקבל שתי דירות חלופיות, ושווי הדירות החלופיות אינו עולה על תקרת הפטור.', 1);
  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'ב', 'ציונה חבה במס בגין המכירה בגין ההפרש בין הדירה שמכרה לאחת הדירות שתקבל.', false, 'בחירה זו שגויה, שכן ציונה זכאית לפטור מלא עבור שתי הדירות החלופיות שקיבלה, בהיותה קשישה העומדת בתנאי הסעיף.', 2);
  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'ג', 'ציונה פטורה ממס בגין המכירה בגין שווייה של הדירה הראשונה שתקבל בלבד.', false, 'בחירה זו שגויה. אף שמוכר רגיל זכאי לפטור עבור יחידת מגורים חלופית אחת, קשיש זכאי לפטור עבור שתי יחידות מגורים חלופיות, בכפוף לתקרת השווי.', 3);
  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'ד', 'ציונה פטורה ממס לחלוטין בגין המכירה.', true, 'ציונה היא ''קשיש'' כהגדרתה בסעיף 49יט(א) לחוק מיסוי מקרקעין, שכן היא בת 75 והתגוררה בדירה למעלה מ-20 שנה. לפי סעיף 49כב(א2) לחוק, קשיש המוכר את זכויותיו ביחידת מגורים במתחם פינוי-בינוי, שתמורתה ניתנו לו שתי יחידות מגורים חלופיות, זכאי לפטור ממס, ובלבד ששווי שתי היחידות החלופיות אינו עולה על תקרת השווי. במקרה זה, שווי הדירה הנמכרת הוא 1,000,000 ש"ח, ותקרת השווי היא 150% משווי זה, כלומר 1,500,000 ש"ח. שווי שתי הדירות החלופיות הוא 1,200,000 ש"ח (600,000 * 2), שאינו עולה על התקרה, ולכן ציונה פטורה ממס לחלוטין.', 4);

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_0, v_sq_id, 'א', 'פטור בפינוי-בינוי למוכר רגיל',
    1, 'ראובן, שאינו קשיש, מכר את יחידת המגורים שלו במתחם פינוי-בינוי. תמורת המכירה קיבל יחידת מגורים חלופית אחת בשווי 1,000,000 ש"ח ותמורה כספית בסך 200,000 ש"ח. שווי יחידת המגורים הנמכרת היה 800,000 ש"ח. מה הדין לעניין מס שבח?', 'שאלה זו בוחנת את תנאי הפטור ממס שבח למוכר יחיד (שאינו קשיש) בעסקת פינוי-בינוי, כאשר הוא מקבל יחידת מגורים חלופית ותמורה כספית. היא מתמקדת בחישוב תקרת השווי ובהחלת הפטור על סך התמורה, בהתאם לסעיף 49כב(א) לחוק מיסוי מקרקעין.', 'סעיף 49כב(א) לחוק מיסוי מקרקעין (שבח ורכישה) קובע כי מוכר יחיד זכאי לפטור ממס שבח במכירת זכויותיו ביחידת מגורים במתחם פינוי-בינוי, שתמורתה ניתנה לו יחידת מגורים חלופית אחת וגם תמורה כספית, ובלבד ששווי הזכות ביחידת המגורים החלופית והתמורה הכספית יחד לא עלו על תקרת השווי. תקרת השווי היא הגבוה מבין 150% משווי יחידת המגורים הנמכרת, או שווי דירת מגורים בשטח 120 מ"ר באותו מתחם. במקרה זה, שווי היחידה הנמכרת היה 800,000 ש"ח. תקרת השווי היא 150% מ-800,000 ש"ח, כלומר 1,200,000 ש"ח. סך התמורה שקיבל ראובן הוא 1,000,000 ש"ח (יחידה חלופית) + 200,000 ש"ח (כסף) = 1,200,000 ש"ח. מכיוון שסך התמורה אינו עולה על תקרת השווי, ראובן פטור ממס שבח לחלוטין. (ראו גם נבו - המתמחה מיסוי מקרקעין (2026) | סעיפים 49כב(א)-(ב), עמ'' 54).',
    'הנחה שגויה כי כל תמורה כספית בעסקת פינוי-בינוי חייבת במס, מבלי לבחון את עמידתה בתקרת השווי הכוללת.', '["פינוי-בינוי", "פטור ממס שבח", "תקרת שווי", "תמורה כספית", "סעיף 49כב(א)"]'::jsonb, '**וריאציה 1 — תמורה כוללת העולה על התקרה:** ראובן קיבל יחידה חלופית בשווי 1,200,000 ש"ח ו-300,000 ש"ח במזומן. שווי יחידתו הנמכרת היה 800,000 ש"ח. מה הדין? ← תקרת השווי היא 1,200,000 ש"ח. סך התמורה הוא 1,500,000 ש"ח. ראובן יחויב במס על ההפרש של 300,000 ש"ח (סעיף 49כב(א)(2) לחוק).
**וריאציה 2 — קבלת שתי יחידות למוכר רגיל:** ראובן קיבל שתי יחידות חלופיות. האם הוא פטור? ← לא, מוכר שאינו קשיש זכאי לפטור רק עבור יחידת מגורים חלופית אחת, אלא אם כן מדובר באזור מוטב (סעיף 49כב(א)(1) לחוק וסעיף 49לג1(ג)(1) לחוק).
**וריאציה 3 — קבלת יחידה חלופית ללא תמורה כספית:** ראובן קיבל רק יחידת מגורים חלופית אחת בשווי 1,000,000 ש"ח. שווי יחידתו הנמכרת היה 800,000 ש"ח. מה הדין? ← ראובן פטור ממס שבח לחלוטין, שכן שווי היחידה החלופית אינו עולה על תקרת השווי (1,200,000 ש"ח) (סעיף 49כב(א)(1) לחוק).', 'מוכר יחיד בפינוי-בינוי המקבל יחידה חלופית ותמורה כספית פטור ממס שבח, כל עוד סך התמורה אינו עולה על תקרת השווי (150% משווי היחידה הנמכרת או שווי דירה 120 מ"ר, הגבוה מביניהם) ← סעיף 49כב(א) לחוק מיסוי מקרקעין.',
    '["חוק מיסוי מקרקעין (שבח ורכישה), תשכ\"ג-1963, סעיף 49כב(א)", "נבו - המתמחה מיסוי מקרקעין (2026) | סעיפים 49כב(א)-(ב), עמ'' 54"]'::jsonb
  );
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_0, 'א', 'ראובן פטור ממס שבח לחלוטין.', true, 'החלטה זו נכונה. לפי סעיף 49כב(א) לחוק מיסוי מקרקעין, מוכר יחיד (שאינו קשיש) זכאי לפטור ממס שבח עבור יחידת מגורים חלופית אחת, גם אם ניתנה תמורה כספית, ובלבד ששווי היחידה החלופית והתמורה הכספית יחד אינם עולים על תקרת השווי. במקרה זה, תקרת השווי היא 150% משווי היחידה הנמכרת (800,000 ש"ח), כלומר 1,200,000 ש"ח. סך התמורה שקיבל ראובן (1,000,000 ש"ח + 200,000 ש"ח = 1,200,000 ש"ח) אינו עולה על התקרה, ולכן הוא פטור ממס שבח לחלוטין.', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_0, 'ב', 'ראובן חב במס שבח על התמורה הכספית בלבד.', false, 'בחירה זו שגויה. התמורה הכספית נכללת בחישוב תקרת השווי, ורק אם סך התמורה (יחידה חלופית + כסף) עולה על התקרה, יחול מס על ההפרש.', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_0, 'ג', 'ראובן חב במס שבח על ההפרש בין שווי היחידה החלופית לתקרת השווי.', false, 'בחירה זו שגויה. המס מוטל על ההפרש בין סך התמורה (יחידה חלופית + כסף) לבין תקרת השווי, אם סך התמורה עולה על התקרה.', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_0, 'ד', 'ראובן חב במס שבח על כל שווי היחידה החלופית והתמורה הכספית.', false, 'בחירה זו שגויה. סעיף 49כב(א) מעניק פטור ממס שבח למוכר יחיד בפינוי-בינוי, בכפוף לתקרת השווי.', 4);

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_1, v_sq_id, 'ב', 'הגדרת "יחידת מגורים" בפינוי-בינוי',
    2, 'מהם התנאים העיקריים להגדרת "יחידת מגורים" לצורך פטור ממס שבח בפרק פינוי-בינוי בחוק מיסוי מקרקעין?', 'שאלה זו בוחנת את ההגדרה הספציפית של ''יחידת מגורים'' בפרק פינוי-בינוי בחוק מיסוי מקרקעין, השונה מההגדרה הכללית של ''דירת מגורים'' בחוק. היא מדגישה את דרישת השימוש בפועל למגורים ואת תקופת המגורים הנדרשת, וכן את העובדה שגם תאגיד יכול ליהנות מהפטור.', 'סעיף 49יט(א) לחוק מיסוי מקרקעין (שבח ורכישה) מגדיר ''יחידת מגורים'' לצורך פרק פינוי-בינוי כ''דירה או חלק מדירה המשמשת למגורים לרבות למגורי המחזיק בה ואשר שימשה למגורים כאמור במשך תקופה של שנתיים רצופות לפחות, סמוך לפני מתן צו ההכרזה על המתחם''. הגדרה זו שונה מהגדרת ''דירת מגורים'' הכללית בסעיף 1 לחוק בכך שאינה דורשת בעלות יחיד (ולכן גם תאגיד יכול ליהנות מהפטור) ואינה מוציאה דירה שהיא מלאי עסקי. כמו כן, היא דורשת שימוש בפועל למגורים במשך שנתיים רצופות לפני צו ההכרזה, בניגוד להגדרה הכללית שיכולה לכלול גם דירה המיועדת למגורים לפי טיבה (אבי גורמן, שי אהרונוביץ'' מיסוי מקרקעין – פרשנות, הלכה ומעשה (2017) | 8.5 סעיף 49יט לחוק מיסוי מקרקעין - הגדרות וחזקות, עמ'' 19).',
    'הבלבול בין הגדרת ''דירת מגורים'' הכללית בסעיף 1 לחוק לבין הגדרת ''יחידת מגורים'' הספציפית לפרק פינוי-בינוי בסעיף 49יט(א).', '["יחידת מגורים", "פינוי-בינוי", "סעיף 49יט(א)", "שימוש למגורים", "תקופת מגורים"]'::jsonb, '**וריאציה 1 — דירה בבעלות תאגיד:** חברה בעלת דירה במתחם פינוי-בינוי. האם הדירה יכולה להיחשב ''יחידת מגורים''? ← כן, הגדרת ''יחידת מגורים'' בפרק פינוי-בינוי אינה דורשת בעלות יחיד (אבי גורמן, שי אהרונוביץ'' מיסוי מקרקעין – פרשנות, הלכה ומעשה (2017) | 8.5 סעיף 49יט לחוק מיסוי מקרקעין - הגדרות וחזקות, עמ'' 19).
**וריאציה 2 — דירה ששימשה למגורים שנה אחת:** דירה ששימשה למגורים שנה אחת לפני צו ההכרזה. האם היא ''יחידת מגורים''? ← לא, נדרשת תקופת מגורים של שנתיים רצופות לפחות (סעיף 49יט(א) לחוק).
**וריאציה 3 — דירה שהיא מלאי עסקי:** דירה המוחזקת כמלאי עסקי על ידי קבלן. האם היא ''יחידת מגורים''? ← כן, הגדרת ''יחידת מגורים'' בפרק פינוי-בינוי אינה שוללת מלאי עסקי (אבי גורמן, שי אהרונוביץ'' מיסוי מקרקעין – פרשנות, הלכה ומעשה (2017) | 8.5 סעיף 49יט לחוק מיסוי מקרקעין - הגדרות וחזקות, עמ'' 19).', '''יחידת מגורים'' בפרק פינוי-בינוי היא דירה ששימשה למגורים שנתיים רצופות לפני צו ההכרזה. היא אינה מוגבלת לבעלות יחיד ואינה מוציאה מלאי עסקי ← סעיף 49יט(א) לחוק מיסוי מקרקעין.',
    '["חוק מיסוי מקרקעין (שבח ורכישה), תשכ\"ג-1963, סעיף 49יט(א)", "אבי גורמן, שי אהרונוביץ'' מיסוי מקרקעין – פרשנות, הלכה ומעשה (2017) | 8.5 סעיף 49יט לחוק מיסוי מקרקעין - הגדרות וחזקות, עמ'' 19"]'::jsonb
  );
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_1, 'א', 'דירה או חלק מדירה המשמשת למגורים, בבעלות יחיד, ואינה מלאי עסקי.', false, 'בחירה זו מתארת את הגדרת ''דירת מגורים'' הכללית בסעיף 1 לחוק, אך לא את ההגדרה הספציפית ל''יחידת מגורים'' בפרק פינוי-בינוי, שאינה דורשת בעלות יחיד ואינה מוציאה מלאי עסקי.', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_1, 'ב', 'דירה או חלק מדירה המשמשת למגורים, לרבות למגורי המחזיק בה, ושימשה למגורים שנתיים רצופות לפני צו ההכרזה על המתחם.', true, 'החלטה זו נכונה. סעיף 49יט(א) לחוק מיסוי מקרקעין מגדיר ''יחידת מגורים'' כ''דירה או חלק מדירה המשמשת למגורים לרבות למגורי המחזיק בה ואשר שימשה למגורים כאמור במשך תקופה של שנתיים רצופות לפחות, סמוך לפני מתן צו ההכרזה על המתחם''.', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_1, 'ג', 'דירה או חלק מדירה המיועדת למגורים לפי טיבה, ללא דרישת שימוש בפועל.', false, 'בחירה זו שגויה. הגדרת ''יחידת מגורים'' בפרק פינוי-בינוי דורשת שימוש בפועל למגורים במשך שנתיים רצופות, בניגוד להגדרה הכללית של ''דירת מגורים'' בסעיף 1 לחוק, שיכולה להיות גם ''מיועדת למגורים לפי טיבה''.', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_1, 'ד', 'דירה או חלק מדירה, ללא דרישת שימוש בפועל, ובלבד שהיא בבעלות יחיד.', false, 'בחירה זו שגויה. הגדרת ''יחידת מגורים'' בפרק פינוי-בינוי דורשת שימוש בפועל למגורים ואינה דורשת בעלות יחיד, כך שגם תאגיד יכול ליהנות מהפטור (אבי גורמן, שי אהרונוביץ'' מיסוי מקרקעין – פרשנות, הלכה ומעשה (2017) | 8.5 סעיף 49יט לחוק מיסוי מקרקעין - הגדרות וחזקות, עמ'' 19).', 4);

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_2, v_sq_id, 'ג', 'העברת יחידה לקרוב בפינוי-בינוי',
    3, 'יוסי העביר את יחידת המגורים שלו במתנה לבתו, שירה, בחודש ינואר 2026. בחודש יוני 2026, נחתם הסכם פינוי-בינוי עם יזם במתחם שבו נמצאת הדירה. שירה מעוניינת למכור את הדירה ליזם ולקבל פטור ממס שבח. מה הדין?', 'שאלה זו עוסקת בהוראה אנטי-תכנונית בפרק פינוי-בינוי בחוק מיסוי מקרקעין, שמטרתה למנוע ניצול לרעה של הפטור על ידי העברת יחידות לקרובים. היא בוחנת את סעיף 49כב(ג) לחוק, הקובע כי העברה לקרוב בפטור ממס בתוך תקופת המיזם תגרום לכך שהמעביר והקרוב ייחשבו למוכר אחד.', 'סעיף 49כב(ג) לחוק מיסוי מקרקעין (שבח ורכישה) קובע כי "הועברה יחידה לקרוב בפטור ממס לפי חוק זה בתקופת המיזם, יראו את המעביר ואת קרובו כמוכר אחד לעניין אותן יחידות". ''תקופת המיזם'' מוגדרת בסעיף 49כב(ג) כ"התקופה המתחילה 24 חודשים לפני מועד החתימה על ההסכם למכירת הזכות הנמכרת, וסופה ביום המכירה". במקרה זה, יוסי העביר את הדירה לשירה (קרובה) בינואר 2026, וההסכם עם היזם נחתם ביוני 2026. מכיוון שההעברה בוצעה בתוך תקופת המיזם (פחות מ-24 חודשים לפני חתימת ההסכם עם היזם), יוסי ושירה ייחשבו למוכר אחד. המשמעות היא שהם יוכלו ליהנות מפטור אחד בלבד עבור הדירה, ולא מפטור נפרד לכל אחד מהם. הוראה זו נועדה למנוע תכנוני מס שבהם נישום בעל מספר יחידות במתחם פינוי-בינוי יעביר אותן לקרוביו כדי לזכות במספר פטורים (אבי גורמן, שי אהרונוביץ'' מיסוי מקרקעין – פרשנות, הלכה ומעשה (2017) | 8.8.4 סעיף 49כב(ב) לחוק מיסוי מקרקעין, עמ'' 46).',
    'התעלמות מתקופת הצינון של 24 חודשים להעברת יחידות לקרובים בפרק פינוי-בינוי, והנחה שכל העברה במתנה מקנה פטור נפרד.', '["פינוי-בינוי", "פטור ממס שבח", "העברה לקרוב", "תקופת צינון", "תכנון מס", "סעיף 49כב(ג)"]'::jsonb, '**וריאציה 1 — העברה לקרוב מחוץ לתקופת המיזם:** יוסי העביר את הדירה לשירה 3 שנים לפני חתימת ההסכם עם היזם. האם הפטור יחול? ← כן, מכיוון שההעברה בוצעה מחוץ לתקופת המיזם, יוסי ושירה לא ייחשבו למוכר אחד (סעיף 49כב(ג) לחוק).
**וריאציה 2 — העברה לקרוב בתמורה:** יוסי מכר את הדירה לשירה בתמורה מלאה, ולא בפטור ממס. האם סעיף 49כב(ג) יחול? ← לא, הסעיף חל רק אם היחידה הועברה לקרוב "בפטור ממס לפי חוק זה" (סעיף 49כב(ג) לחוק).
**וריאציה 3 — קשיש המעביר לקרוב:** קשיש העביר יחידה לקרוב בתוך תקופת המיזם. האם הקשיש עדיין זכאי לפטור עבור שתי יחידות? ← לא, גם במקרה של קשיש, אם ההעברה לקרוב נעשתה בתוך תקופת המיזם, המעביר והקרוב ייחשבו למוכר אחד, והפטור יוגבל בהתאם (סעיף 49כב(ג) לחוק).', 'העברת יחידת מגורים לקרוב בפטור ממס בתוך 24 חודשים לפני חתימת הסכם פינוי-בינוי עם יזם, תגרום לכך שהמעביר והקרוב ייחשבו למוכר אחד, ותשלול את הפטור הנפרד ← סעיף 49כב(ג) לחוק מיסוי מקרקעין.',
    '["חוק מיסוי מקרקעין (שבח ורכישה), תשכ\"ג-1963, סעיף 49כב(ג)", "אבי גורמן, שי אהרונוביץ'' מיסוי מקרקעין – פרשנות, הלכה ומעשה (2017) | 8.8.4 סעיף 49כב(ב) לחוק מיסוי מקרקעין, עמ'' 46", "נבו - המתמחה מיסוי מקרקעין (2026) | סעיף 49כב(ג), עמ'' 55"]'::jsonb
  );
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_2, 'א', 'שירה זכאית לפטור ממס שבח, שכן היא קיבלה את הדירה במתנה ולא מכרה אותה בתוך תקופת צינון.', false, 'בחירה זו שגויה. סעיף 49כב(ג) לחוק מיסוי מקרקעין קובע תקופת צינון של 24 חודשים להעברה לקרוב, שבמהלכה המעביר והקרוב נחשבים למוכר אחד.', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_2, 'ב', 'יוסי ושירה ייחשבו למוכר אחד לעניין הדירה, ולכן לא יחול פטור ממס שבח במכירתה ליזם.', true, 'החלטה זו נכונה. סעיף 49כב(ג) לחוק מיסוי מקרקעין קובע כי אם יחידת מגורים הועברה לקרוב בפטור ממס לפי חוק זה, בתקופת המיזם (24 חודשים לפני מועד החתימה על ההסכם למכירה), יראו את המעביר ואת קרובו כמוכר אחד לעניין אותה יחידה. מכיוון שההעברה בוצעה בתוך 24 חודשים לפני חתימת ההסכם עם היזם, יוסי ושירה ייחשבו למוכר אחד, והפטור לא יחול במכירתה ליזם (אבי גורמן, שי אהרונוביץ'' מיסוי מקרקעין – פרשנות, הלכה ומעשה (2017) | 8.8.4 סעיף 49כב(ב) לחוק מיסוי מקרקעין, עמ'' 46).', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_2, 'ג', 'שירה זכאית לפטור ממס שבח, אך רק אם יוסי לא ניצל פטור דומה ב-24 החודשים האחרונים.', false, 'בחירה זו שגויה. הכלל בסעיף 49כב(ג) אינו תלוי בניצול פטור קודם של המעביר, אלא בעצם העברת היחידה לקרוב בתוך תקופת הצינון.', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_2, 'ד', 'הפטור יחול, אך שירה תצטרך לשלם מס רכישה על קבלת הדירה במתנה.', false, 'בחירה זו שגויה. השאלה עוסקת בפטור ממס שבח במכירה ליזם, ולא במס רכישה על קבלת המתנה. בנוסף, הפטור ממס שבח לא יחול במקרה זה.', 4);

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_3, v_sq_id, 'ד', 'פטור ממס רכישה בפינוי-בינוי',
    4, 'שמעון מכר את יחידת המגורים שלו ליזם במסגרת פרויקט פינוי-בינוי, וקיבל יחידת מגורים חלופית. האם שמעון יהיה חייב במס רכישה על קבלת היחידה החלופית?', 'שאלה זו עוסקת בפטור ממס רכישה הניתן למוכרים בפרויקטים של פינוי-בינוי, על קבלת יחידת מגורים חלופית. היא בוחנת את הוראת סעיף 49כד לחוק מיסוי מקרקעין, המהווה הקלה משמעותית לעידוד התחדשות עירונית.', 'סעיף 49כד לחוק מיסוי מקרקעין (שבח ורכישה) קובע פטור מפורש ממס רכישה למוכר יחידת מגורים במסגרת פרויקט פינוי-בינוי, על קבלת יחידת המגורים החלופית. הוראה זו נועדה להקל על בעלי זכויות במתחמי פינוי-בינוי ולעודד את הפרויקטים הללו, שכן ללא פטור זה, קבלת הדירה החלופית מהיזם הייתה מתחייבת במס רכישה. הפטור חל על אף הוראות סעיף 9 לחוק, העוסק במס רכישה באופן כללי (אבי גורמן, שי אהרונוביץ'' מיסוי מקרקעין – פרשנות, הלכה ומעשה (2017) | 8.10 סעיף 49כד לחוק מיסוי מקרקעין - פטור ממס רכישה, עמ'' 54).',
    'הנחה שגויה כי כל רכישת זכות במקרקעין חייבת במס רכישה, מבלי להתייחס לחריגים הספציפיים הקבועים בחוק, כגון הפטור בפינוי-בינוי.', '["מס רכישה", "פינוי-בינוי", "פטור ממס רכישה", "יחידת מגורים חלופית", "סעיף 49כד"]'::jsonb, '**וריאציה 1 — פטור ממס רכישה בחיזוק מבנים (תמ"א 38/1):** מוכר קיבל שירותי בנייה בתמורה לזכויות בחיזוק מבנה. האם הוא חייב במס רכישה? ← לא, בעסקת חיזוק מבנים המוכר נחשב כמי שקיבל שירותי בנייה, וקבלת שירותי בנייה אינה נחשבת לרכישת זכות במקרקעין, ולכן אינו חייב במס רכישה (נבו - המתמחה מיסוי מקרקעין (2026) | מס רכישה, עמ'' 62).
**וריאציה 2 — קבלת יחידה חלופית העולה על תקרת השווי:** שמעון קיבל יחידה חלופית ששוויה עולה על תקרת השווי. האם הוא פטור ממס רכישה? ← כן, הפטור ממס רכישה לפי סעיף 49כד חל על קבלת היחידה החלופית, גם אם שוויה עולה על התקרה (אבי גורמן, שי אהרונוביץ'' מיסוי מקרקעין – פרשנות, הלכה ומעשה (2017) | 8.10 סעיף 49כד לחוק מיסוי מקרקעין - פטור ממס רכישה, עמ'' 54).
**וריאציה 3 — קשיש המוכר יחידה חלופית ליזם:** קשיש מכר יחידת מגורים חלופית שקיבל ליזם. האם הוא פטור ממס רכישה? ← כן, מכירה כזו פטורה ממס וממס רכישה, בכפוף לתנאים מסוימים (סעיף 49כב2(א) לחוק).', 'מוכר יחידת מגורים בפרויקט פינוי-בינוי פטור ממס רכישה על קבלת יחידת המגורים החלופית ← סעיף 49כד לחוק מיסוי מקרקעין.',
    '["חוק מיסוי מקרקעין (שבח ורכישה), תשכ\"ג-1963, סעיף 49כד", "נבו - המתמחה מיסוי מקרקעין (2026) | מס רכישה, עמ'' 62", "אבי גורמן, שי אהרונוביץ'' מיסוי מקרקעין – פרשנות, הלכה ומעשה (2017) | 8.10 סעיף 49כד לחוק מיסוי מקרקעין - פטור ממס רכישה, עמ'' 54", "חוק מיסוי מקרקעין (שבח ורכישה), תשכ\"ג-1963, סעיף 49כב2(א)"]'::jsonb
  );
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_3, 'א', 'כן, שמעון יהיה חייב במס רכישה מלא על שווי היחידה החלופית.', false, 'בחירה זו שגויה. סעיף 49כד לחוק מיסוי מקרקעין מעניק פטור ממס רכישה על קבלת יחידת מגורים חלופית בפרויקט פינוי-בינוי.', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_3, 'ב', 'לא, שמעון פטור ממס רכישה על קבלת היחידה החלופית.', true, 'החלטה זו נכונה. סעיף 49כד לחוק מיסוי מקרקעין (שבח ורכישה) קובע במפורש כי ''על אף הוראות סעיף 9, במכירת יחידת מגורים כאמור בסעיף 49כב, פטור המוכר ממס רכישה ברכישת יחידת המגורים החלופית''.', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_3, 'ג', 'כן, אך בשיעור מופחת המיועד לדירות מגורים יחידות.', false, 'בחירה זו שגויה. אין חיוב במס רכישה כלל על היחידה החלופית בפרויקט פינוי-בינוי, ולא רק שיעור מופחת.', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_3, 'ד', 'לא, אלא אם כן קיבל גם תמורה כספית בנוסף ליחידה החלופית.', false, 'בחירה זו שגויה. הפטור ממס רכישה חל על קבלת היחידה החלופית, ללא קשר לשאלה אם ניתנה תמורה כספית נוספת (אבי גורמן, שי אהרונוביץ'' מיסוי מקרקעין – פרשנות, הלכה ומעשה (2017) | 8.10 סעיף 49כד לחוק מיסוי מקרקעין - פטור ממס רכישה, עמ'' 54).', 4);

  RAISE NOTICE 'Q% inserted: external_id %', 37, '2022-S-S-Q37';
END
$$;

