  v_ang_0 uuid := '6f667f81-36ce-4e81-84c3-3731caef01d5'::uuid;
  v_ang_1 uuid := '52ada9a6-5792-4a59-bcd3-1e5912a2f1cc'::uuid;
  v_ang_2 uuid := 'eb6be42f-7a6e-41ee-8619-79b430cd9056'::uuid;
  v_ang_3 uuid := 'f7536293-e9b7-4346-ac16-0191b45cb688'::uuid;
