  INSERT INTO public.source_questions (
    id, question_group_id, version, is_current, external_id, chapter_id, subtopic_id, question_text, source_metadata, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list, notes_for_admin, status, created_by
  ) VALUES (
    v_sq_id, v_group_id, 1, true,
    '2022-S-S-Q38', v_chapter_id, v_subtopic_id, 'ועדת הבחירות המרכזית לכנסת החליטה על פסילת רשימת מועמדים פלונית מהשתתפות בבחירות לכנסת, בנימוק כי רשימת המועמדים שואפת לשלול את קיומה של מדינת ישראל כמדינה יהודית ודמוקרטית. מה הדין?',
    '{"exam_year": 2022, "exam_season": "summer", "exam_part": 2, "exam_question_number": 38}'::jsonb, 'השאלה עוסקת בסמכותה של ועדת הבחירות המרכזית לפסול רשימות מועמדים מלהתמודד בבחירות לכנסת, ובפרט בעילת הפסילה של שלילת קיומה של מדינת ישראל כמדינה יהודית ודמוקרטית. היא מתמקדת בתנאים המהותיים והראייתיים המחמירים שנקבעו בפסיקה להפעלת עילה זו, בהתאם לסעיף 7א לחוק-יסוד: הכנסת.', 'סעיף 7א(א)(1) לחוק-יסוד: הכנסת קובע כי רשימת מועמדים לא תשתתף בבחירות לכנסת אם יש במטרותיה או במעשיה, במפורש או במשתמע, משום שלילת קיומה של מדינת ישראל כמדינה יהודית ודמוקרטית. הפסיקה, ובראשה פסקי הדין בעניין ירדור, ניימן, כסיף, יזבק ובל"ד, קבעה כי יש לפרש עילות פסילה אלו בצמצום רב ולהפעילן רק במקרים קיצוניים ומובהקים ביותר, תוך שמירה על מעמדן הרם של הזכויות לבחור ולהיבחר (א"ב 1806/19 כסיף, רפרנס 1, 4; א"ב 852/20 יזבק, רפרנס 5, 6; ע"ב 6668/22 בל"ד, רפרנס 7, 8, 11, 12). על מנת לבסס עילת פסילה, נדרש להראות כי השאיפה לשלול את קיומה של המדינה כמדינה יהודית ודמוקרטית היא מטרה מרכזית ודומיננטית בפרוגרמה הפוליטית של הרשימה, כי היא נלמדת מהצהרות מפורשות או ממסקנות ברורות וחד-משמעיות, וכי הרשימה פועלת באופן אקטיבי ושיטתי להגשמתה. בנוסף, הראיות המבססות זאת צריכות לעלות כדי ''מסה קריטית'' של ראיות ברורות, חד-משמעיות ומשכנעות. כל ספק המתעורר פועל נגד הפסילה (א"ב 852/20 יזבק, רפרנס 5; ע"ב 6668/22 בל"ד, רפרנס 7, 8, 10, 11, 12).', 'הנחה שגויה כי די בהבעת עמדה כללית במצע הרשימה כדי להצדיק פסילה, מבלי להתחשב בדרישות הפסיקה לדומיננטיות, אקטיביות ורף ראייתי מחמיר.',
    '["פסילת רשימת מועמדים", "מדינה יהודית ודמוקרטית", "חוק-יסוד: הכנסת", "רף ראייתי מחמיר", "שאיפה דומיננטית", "פעילות אקטיבית"]'::jsonb, '**וריאציה 1 — קריאה ל''מדינת כל אזרחיה'':** רשימה קוראת לכינונה של מדינת ישראל כ''מדינת כל אזרחיה''. האם תיפסל? ← לא בהכרח. הפסיקה קבעה כי קריאה זו כשלעצמה אינה משמיעה שלילת קיומה של מדינת ישראל כמדינה יהודית (ע"ב 6668/22 בל"ד, רפרנס 10, 12).
**וריאציה 2 — שלילת מאפיינים גרעיניים:** רשימה פועלת באופן אקטיבי לביטול חוק השבות וביטול מעמדה של העברית כשפה רשמית. האם תיפסל? ← כן, אלו נחשבים מאפיינים גרעיניים של המדינה היהודית, ופעילות אקטיבית לשלילתם יכולה להוביל לפסילה (ע"ב 6668/22 בל"ד, רפרנס 11; נבו - המתמחה, חוקי יסוד, עמ'' 27).
**וריאציה 3 — התבטאויות ישנות וספורדיות:** בקשת פסילה נסמכת על התבטאויות ישנות וספורדיות של חברי הרשימה. האם תיפסל? ← לא, נדרשת פעילות שאינה ספורדית וראיות עדכניות המעידות על שאיפה דומיננטית (א"ב 852/20 יזבק, רפרנס 5; א"ב 1156/21 מראענה, רפרנס 14).', 'ועדת הבחירות המרכזית מוסמכת לפסול רשימת מועמדים אם היא שוללת את קיומה של ישראל כמדינה יהודית ודמוקרטית. הפסילה דורשת רף ראייתי מחמיר, הוכחת שאיפה דומיננטית ופעילות אקטיבית למימושה, ואינה טעונה אישור בית המשפט העליון (אך ניתנת לערעור) ← סעיף 7א לחוק-יסוד: הכנסת והפסיקה בעניין כסיף, יזבק ובל"ד.', '["חוק-יסוד: הכנסת, סעיף 7א(א)(1)", "א\"ב 1806/19 ועדת הבחירות המרכזית לכנסת ה-21 נ'' ד\"ר עופר כסיף (2019)", "א\"ב 852/20 ועדת הבחירות המרכזית לכנסת ה-23 נ'' ח\"כ היבא יזבק (2020)", "ע\"ב 6668/22 בל\"ד ברית לאומית דמוקרטית נ'' ועדת הבחירות המרכזית לבחירות לכנסת ה-25 (2022)", "נבו - המתמחה חוקי יסוד (2026) | הבחירות לכנסת, עמ'' 27"]'::jsonb,
    'classification_review: original chapter=''חוקתי + בינלאומי פרטי'' subtopic=''ביטול סמכות בג"ץ'' → mapped chapter=''administrative'' subtopic=''constitutional_rights'' | classifier_note: CEC disqualifying a candidate list (denial of Israel as Jewish & democratic) — election disqualification grounds, constitutional democratic principle | source_review_note: הסיווג תחת תת-הנושא ''ביטול סמכות בג"ץ'' אינו מדויק לחלוטין עבור שאלה העוסקת בעילות פסילה של רשימות ומועמדים. הנושא מתאים יותר ל''בחירות לכנסת'' או ''זכות לבחור ולהיבחר'' תחת פרק ''משפט חוקתי'', אך אלו אינם תת-נושאים ברשימה הסגורה. נבחר ''ביטול סמכות בג"ץ'' כברירת מחדל הקרובה ביותר מתוך הרשימה הסגורה, בהתחשב בכך שבית המשפט העליון הוא הגורם המאשר/מערער על החלטות הפסילה.', 'active', 'b9ecdde2-d07e-4761-96ab-05f0ad32d4e3'
  );

  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'א', 'לוועדת הבחירות לכנסת אין סמכות להורות על פסילת רשימת מועמדים לכנסת.', false, 'בחירה זו שגויה. סעיף 7א לחוק-יסוד: הכנסת מעניק לוועדת הבחירות המרכזית סמכות לפסול רשימות ומועמדים, בכפוף לתנאים הקבועים בחוק.', 1);
  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'ב', 'סמכות ועדת הבחירות לכנסת להורות על פסילת רשימת מועמדים לכנסת טעונה אישור של בית המשפט העליון.', false, 'בחירה זו שגויה. החלטת ועדת הבחירות לפסול *מועמד* טעונה אישור בית המשפט העליון, אך החלטה לפסול *רשימה* אינה טעונה אישור, אלא ניתנת לערעור (נבו - המתמחה, חוקי יסוד, עמ'' 28).', 2);
  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'ג', 'לוועדת הבחירות לכנסת יש סמכות להורות על פסילת רשימת מועמדים לכנסת בתנאי שפעילות הרשימה מעידה על מרכזיות השאיפה האמורה ועל כוונה לממשה ולהביא להגשמתה.', true, 'החלטה זו נכונה. הפסיקה קבעה כי על מנת לבסס עילת פסילה לפי סעיף 7א לחוק-יסוד: הכנסת, יש להראות כי מדובר בשאיפה דומיננטית המהווה חלק מהפרוגרמה הפוליטית של הרשימה, וכי הרשימה פועלת באופן אקטיבי להגשמתה, תוך עמידה ברף ראייתי מחמיר (א"ב 852/20 יזבק, רפרנס 5; ע"ב 6668/22 בל"ד, רפרנס 7).', 3);
  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'ד', 'סמכות ועדת הבחירות לכנסת להורות על פסילת רשימת מועמדים לכנסת אינה טעונה אישור של בית המשפט העליון, ודי בכך ששאיפת הרשימה האמורה הובעה באופן כללי במצעה.', false, 'בחירה זו שגויה בחלקה השני. אף שהחלטה לפסול רשימה אינה טעונה אישור, אין די בהבעה כללית במצע. נדרש רף ראייתי מחמיר המעיד על מרכזיות השאיפה ופעילות אקטיבית למימושה (ע"ב 6668/22 בל"ד, רפרנס 7).', 4);

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_0, v_sq_id, 'א', 'פסילת מועמד בגין הסתה לגזענות',
    1, 'ועדת הבחירות המרכזית החליטה לפסול מועמד לכנסת בטענה של הסתה לגזענות. המועמד פרסם מספר פוסטים ברשתות החברתיות המכילים אמירות קשות נגד קבוצת מיעוט בישראל. מה הדין?', 'שאלה זו בוחנת את עילת הפסילה של הסתה לגזענות לפי סעיף 7א(א)(2) לחוק-יסוד: הכנסת. היא מדגישה את הרף הראייתי המחמיר הנדרש ואת הצורך באישור בית המשפט העליון לפסילת מועמד, תוך איזון בין הזכות לבחור ולהיבחר לבין הגנה על ערכי הדמוקרטיה.', 'סעיף 7א(א)(2) לחוק-יסוד: הכנסת קובע כי רשימת מועמדים לא תשתתף בבחירות לכנסת ולא יהיה אדם מועמד בבחירות לכנסת, אם יש במטרותיה או במעשיה של הרשימה או במעשיו של האדם, לרבות בהתבטאויותיו, במפורש או במשתמע, משום הסתה לגזענות. הפסיקה קבעה כי יש לפרש עילות פסילה אלו בצמצום ולהפעילן במקרים קיצוניים ביותר, תוך דרישה לרף ראייתי מחמיר. נדרש להראות כי מדובר בשאיפה דומיננטית המהווה חלק מהפרוגרמה הפוליטית של המועמד, כי הוא פועל באופן אקטיבי להגשמתה, וכי הראיות לכך הן ''מסה קריטית'' של ראיות ברורות, חד-משמעיות ומשכנעות (א"ב 1806/19 כסיף, רפרנס 1, 4; א"ב 852/20 יזבק, רפרנס 5, 6). בנוסף, החלטת ועדת הבחירות המרכזית לפסול מועמד טעונה אישור של בית המשפט העליון (סעיף 7א(ב) לחוק-יסוד: הכנסת, נבו - המתמחה, חוקי יסוד, עמ'' 28).',
    'הנחה שגויה כי כל אמירה גזענית, גם אם היא חמורה, מספיקה לפסילת מועמד, מבלי להתחשב ברף הראייתי המחמיר ובדרישת הדומיננטיות והאקטיביות.', '["הסתה לגזענות", "פסילת מועמד", "חוק-יסוד: הכנסת", "רף ראייתי מחמיר", "אישור בית המשפט העליון"]'::jsonb, '**וריאציה 1 — התבטאויות ישנות שהמועמד התנער מהן:** מועמד פרסם בעבר התבטאויות גזעניות אך התנער מהן והתנצל. האם ייפסל? ← לא, הפסיקה מתחשבת בהתנערות והתנצלות, ודורשת מסה קריטית של ראיות עדכניות (א"ב 1156/21 מראענה, רפרנס 14).
**וריאציה 2 — התבטאויות גזעניות של חבר רשימה זוטר:** חבר רשימה זוטר פרסם התבטאויות גזעניות. האם הרשימה כולה תיפסל? ← לא, נדרש שהשאיפה תהיה דומיננטית בפרוגרמה הפוליטית של הרשימה כולה, ולא רק של חבר בודד (א"ב 852/20 יזבק, רפרנס 5).
**וריאציה 3 — הסתה לגזענות ללא פעילות אקטיבית:** מועמד הביע עמדות גזעניות אך לא פעל באופן אקטיבי למימושן. האם ייפסל? ← לא, נדרשת פעילות אקטיבית ושיטתית להגשמת המטרה הפסולה (א"ב 852/20 יזבק, רפרנס 5).', 'פסילת מועמד בגין הסתה לגזענות דורשת רף ראייתי מחמיר, שאיפה דומיננטית ופעילות אקטיבית, ואישור בית המשפט העליון ← סעיף 7א(א)(2) ו-7א(ב) לחוק-יסוד: הכנסת והפסיקה בעניין כסיף ויזבק.',
    '["חוק-יסוד: הכנסת, סעיף 7א(א)(2)", "חוק-יסוד: הכנסת, סעיף 7א(ב)", "א\"ב 1806/19 ועדת הבחירות המרכזית לכנסת ה-21 נ'' ד\"ר עופר כסיף (2019)", "א\"ב 852/20 ועדת הבחירות המרכזית לכנסת ה-23 נ'' ח\"כ היבא יזבק (2020)", "א\"ב 1156/21 ועדת הבחירות המרכזית לכנסת ה-24 נ'' אבתיסאם מראענה (2021)", "נבו - המתמחה חוקי יסוד (2026) | הבחירות לכנסת, עמ'' 28"]'::jsonb
  );
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_0, 'א', 'המועמד ייפסל אם התבטאויותיו מהוות הסתה לגזענות, וזאת ללא צורך באישור בית המשפט העליון.', false, 'בחירה זו שגויה. החלטת ועדת הבחירות לפסול מועמד טעונה אישור של בית המשפט העליון (סעיף 7א(ב) לחוק-יסוד: הכנסת).', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_0, 'ב', 'המועמד ייפסל רק אם התבטאויותיו מהוות הסתה לגזענות, והוכח כי מדובר בשאיפה דומיננטית ופעילות אקטיבית, וזאת באישור בית המשפט העליון.', true, 'החלטה זו נכונה. עילת הפסילה של הסתה לגזענות קבועה בסעיף 7א(א)(2) לחוק-יסוד: הכנסת. הפסיקה דורשת רף ראייתי מחמיר, הכולל שאיפה דומיננטית, פעילות אקטיבית, ומסה קריטית של ראיות ברורות וחד-משמעיות. בנוסף, פסילת מועמד טעונה אישור בית המשפט העליון (א"ב 1806/19 כסיף, רפרנס 1; א"ב 852/20 יזבק, רפרנס 5).', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_0, 'ג', 'המועמד לא ייפסל, שכן חופש הביטוי הפוליטי גובר על עילת הפסילה של הסתה לגזענות.', false, 'בחירה זו שגויה. חופש הביטוי אינו מוחלט, ועילת הסתה לגזענות היא חריג לגיטימי לזכות לבחור ולהיבחר, המאזנת בין זכויות יסוד לבין הגנה על אופייה הדמוקרטי של המדינה (א"ב 1806/19 כסיף, רפרנס 1).', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_0, 'ד', 'המועמד ייפסל אם התבטאויותיו פורסמו ברשתות החברתיות, ללא קשר לתוכנן המדויק.', false, 'בחירה זו שגויה. הפסילה תלויה בתוכן ההתבטאויות ובהיותן עולות כדי הסתה לגזענות, ולא בעצם פרסומן ברשתות החברתיות (א"ב 1156/21 מראענה, רפרנס 13, 14).', 4);

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_1, v_sq_id, 'ב', 'הרף הראייתי לפסילת מועמדים',
    2, 'מהו הרף הראייתי הנדרש על מנת לפסול רשימת מועמדים או מועמד מלהתמודד בבחירות לכנסת, לפי סעיף 7א לחוק-יסוד: הכנסת?', 'שאלה זו מתמקדת באמות המידה הראייתיות המחמירות שנקבעו בפסיקת בית המשפט העליון לצורך הפעלת עילות הפסילה שבסעיף 7א לחוק-יסוד: הכנסת. היא מדגישה את הצורך ב''מסה קריטית'' של ראיות ברורות, חד-משמעיות ומשכנעות, ואת הדרישה לשאיפה דומיננטית ופעילות אקטיבית.', 'הפסיקה, ובראשה פסקי הדין בעניין כסיף, יזבק ובל"ד, קבעה כי הרף הראייתי הנדרש לביסוס עילת פסילה לפי סעיף 7א לחוק-יסוד: הכנסת הוא רף מחמיר וקפדני. אמות המידה שהותוו מאפשרות לפסול רשימה או מועמד רק במקרים ''מובהקים וקיצוניים''. נדרש להצביע על שאיפה דומיננטית המהווה חלק מהפרוגרמה הפוליטית של הרשימה או המועמד, הנלמדת מהצהרות מפורשות או ממסקנות מסתברות שמשמעותן ברורה וחד-משמעית. בנוסף, הרשימה או המועמד צריכים לפעול באופן אקטיבי ושיטתי להגשמת המטרות האמורות, וכי הראיות המבססות זאת עולות כדי ''מסה קריטית'' של ראיות ''ברורות, חד-משמעיות ומשכנעות''. כל ספק המתעורר לגבי דיות המסכת הראייתית פועל נגד הפסילה (א"ב 1806/19 כסיף, רפרנס 4; א"ב 852/20 יזבק, רפרנס 5, 6; ע"ב 6668/22 בל"ד, רפרנס 7, 8, 10, 11, 12).',
    'התעלמות מהדרישה ל''מסה קריטית'' של ראיות ומהצורך להוכיח פעילות אקטיבית ודומיננטית, והסתפקות בראיות חלשות או בהצהרות כלליות.', '["רף ראייתי", "מסה קריטית", "שאיפה דומיננטית", "פעילות אקטיבית", "עילות פסילה", "חוק-יסוד: הכנסת"]'::jsonb, '**וריאציה 1 — ראיות דלות:** בקשת פסילה נסמכת על תשתית ראייתית דלה ביותר. האם תתקבל? ← לא, בקשת פסילה כזו אינה עומדת ברף הראייתי הנדרש (ע"ב 6668/22 בל"ד, רפרנס 8, 10, 12).
**וריאציה 2 — ספק בדיות הראיות:** לאחר עיון בחומר הראייתי, נותר ספק אם יש די בראיות. האם תתבצע פסילה? ← לא, כל ספק פועל לטובת הזכות לבחור ולהיבחר (א"ב 852/20 יזבק, רפרנס 5; א"ב 1806/19 כסיף, רפרנס 6).
**וריאציה 3 — התבטאויות מקוממות אך לא מסה קריטית:** מועמד התבטא באופן מקומם וראוי לגינוי, אך אין בכך כדי לבסס מסה ראייתית קריטית. האם ייפסל? ← לא, אין די בהתבטאויות מקוממות אם אינן עולות כדי מסה ראייתית קריטית (ע"ב 6668/22 בל"ד, רפרנס 12).', 'פסילת מועמד/רשימה דורשת רף ראייתי מחמיר: מסה קריטית של ראיות ברורות, חד-משמעיות ומשכנעות, המעידות על שאיפה דומיננטית ופעילות אקטיבית להגשמת המטרה הפסולה. כל ספק פועל נגד הפסילה ← סעיף 7א לחוק-יסוד: הכנסת והפסיקה בעניין כסיף, יזבק ובל"ד.',
    '["חוק-יסוד: הכנסת, סעיף 7א", "א\"ב 1806/19 ועדת הבחירות המרכזית לכנסת ה-21 נ'' ד\"ר עופר כסיף (2019)", "א\"ב 852/20 ועדת הבחירות המרכזית לכנסת ה-23 נ'' ח\"כ היבא יזבק (2020)", "ע\"ב 6668/22 בל\"ד ברית לאומית דמוקרטית נ'' ועדת הבחירות המרכזית לבחירות לכנסת ה-25 (2022)"]'::jsonb
  );
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_1, 'א', 'ראיות המקימות חשד סביר להתקיימות אחת מעילות הפסילה.', false, 'בחירה זו שגויה. הפסיקה קבעה רף ראייתי מחמיר בהרבה מחשד סביר, הדורש ''מסה קריטית'' של ראיות ברורות, חד-משמעיות ומשכנעות (א"ב 852/20 יזבק, רפרנס 5).', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_1, 'ב', 'ראיות ברורות, חד-משמעיות ומשכנעות המעידות על שאיפה דומיננטית ופעילות אקטיבית להגשמת המטרה הפסולה.', true, 'החלטה זו נכונה. הפסיקה קבעה רף ראייתי מחמיר וקפדני, הדורש ''מסה קריטית'' של ראיות ברורות, חד-משמעיות ומשכנעות, המעידות על שאיפה דומיננטית המהווה חלק מהפרוגרמה הפוליטית של הרשימה או המועמד, ופעילות אקטיבית ושיטתית להגשמתה (א"ב 1806/19 כסיף, רפרנס 4; א"ב 852/20 יזבק, רפרנס 5, 6; ע"ב 6668/22 בל"ד, רפרנס 7).', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_1, 'ג', 'הצהרות מפורשות במצע הרשימה, גם אם אינן מלוות בפעילות אקטיבית.', false, 'בחירה זו שגויה. אין די בהצהרות תיאורטיות במצע. נדרשת גם פעילות אקטיבית ושיטתית להגשמת המטרות הפסולות (א"ב 852/20 יזבק, רפרנס 5; ע"ב 6668/22 בל"ד, רפרנס 7).', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_1, 'ד', 'הוכחה כי המועמד או הרשימה שוללים את קיומה של מדינת ישראל כמדינה יהודית ודמוקרטית, ללא דרישה לרף ראייתי ספציפי.', false, 'בחירה זו שגויה. אף שהוכחת שלילת קיומה של המדינה היא עילת פסילה, הפסיקה קבעה במפורש רף ראייתי ספציפי ומחמיר ביותר (א"ב 1806/19 כסיף, רפרנס 4; ע"ב 6668/22 בל"ד, רפרנס 7).', 4);

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_2, v_sq_id, 'ג', 'פסילת מועמד בגין שהייה במדינת אויב',
    3, 'מועמד לכנסת שהה במדינת אויב שלא כדין בשש השנים שקדמו למועד הגשת רשימת המועמדים. ועדת הבחירות המרכזית מבקשת לפסול את מועמדותו. מה הדין?', 'שאלה זו עוסקת בעילת הפסילה הספציפית הקבועה בסעיף 7א(א1) לחוק-יסוד: הכנסת, העוסקת במועמד ששהה במדינת אויב. היא בוחנת את החזקה הראייתית הניתנת לסתירה, לפיה שהייה כזו נחשבת כתמיכה במאבק מזוין, שהיא אחת מעילות הפסילה המנויות בסעיף 7א(א)(3).', 'סעיף 7א(א1) לחוק-יסוד: הכנסת קובע כי "לעניין סעיף זה, יראו מועמד ששהה במדינת אויב שלא כדין בשבע השנים שקדמו למועד הגשת רשימת המועמדים כמי שיש במעשיו משום תמיכה במאבק מזוין נגד מדינת ישראל, כל עוד לא הוכיח אחרת". כלומר, שהייה במדינת אויב שלא כדין בתוך תקופת שבע השנים מקימה חזקה משפטית, הניתנת לסתירה, כי המועמד תומך במאבק מזוין נגד מדינת ישראל. תמיכה במאבק מזוין היא עילת פסילה לפי סעיף 7א(א)(3) לחוק-יסוד: הכנסת. לכן, במקרה הנדון, המועמד ייפסל אלא אם כן יצליח לסתור את החזקה ולהוכיח כי שהייתו לא הייתה כרוכה בתמיכה במאבק מזוין (נבו - המתמחה, חוקי יסוד, עמ'' 27).',
    'הבלבול בין שהייה במדינת אויב כעילת פסילה מוחלטת לבין חזקה הניתנת לסתירה, והתעלמות מהאפשרות של המועמד להוכיח אחרת.', '["שהייה במדינת אויב", "חזקה משפטית", "תמיכה במאבק מזוין", "עילת פסילה", "חוק-יסוד: הכנסת"]'::jsonb, '**וריאציה 1 — שהייה במדינת אויב כדין:** מועמד שהה במדינת אויב כדין (למשל, בשליחות רשמית). האם החזקה חלה עליו? ← לא, החזקה חלה רק על שהייה "שלא כדין" (סעיף 7א(א1) לחוק-יסוד: הכנסת).
**וריאציה 2 — שהייה במדינת אויב לפני 8 שנים:** מועמד שהה במדינת אויב שלא כדין לפני 8 שנים. האם החזקה חלה עליו? ← לא, החזקה חלה רק על שהייה "בשבע השנים שקדמו למועד הגשת רשימת המועמדים" (סעיף 7א(א1) לחוק-יסוד: הכנסת).
**וריאציה 3 — מועמד שהוכיח שלא תמך במאבק מזוין:** מועמד שהה במדינת אויב שלא כדין, אך הוכיח באופן חד-משמעי שלא תמך במאבק מזוין. האם ייפסל? ← לא, הוא סתר את החזקה ולכן לא ייפסל על בסיס עילה זו (סעיף 7א(א1) לחוק-יסוד: הכנסת).', 'מועמד ששהה במדינת אויב שלא כדין ב-7 השנים שקדמו לבחירות, ייחשב כתומך במאבק מזוין נגד ישראל (עילת פסילה), אלא אם כן הוכיח אחרת ← סעיף 7א(א1) לחוק-יסוד: הכנסת.',
    '["חוק-יסוד: הכנסת, סעיף 7א(א1)", "חוק-יסוד: הכנסת, סעיף 7א(א)(3)", "נבו - המתמחה חוקי יסוד (2026) | הבחירות לכנסת, עמ'' 27"]'::jsonb
  );
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_2, 'א', 'המועמד ייפסל אוטומטית, שכן שהייה במדינת אויב היא עילת פסילה מוחלטת.', false, 'בחירה זו שגויה. סעיף 7א(א1) לחוק-יסוד: הכנסת קובע חזקה הניתנת לסתירה, ולא עילת פסילה מוחלטת.', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_2, 'ב', 'המועמד ייפסל, אלא אם כן יוכיח שלא הייתה במעשיו תמיכה במאבק מזוין נגד מדינת ישראל.', true, 'החלטה זו נכונה. סעיף 7א(א1) לחוק-יסוד: הכנסת קובע חזקה לפיה מועמד ששהה במדינת אויב שלא כדין בשבע השנים שקדמו למועד הגשת רשימת המועמדים, יראו אותו כמי שיש במעשיו משום תמיכה במאבק מזוין נגד מדינת ישראל, אלא אם כן הוכיח אחרת. במקרה זה, המועמד שהה 6 שנים, ולכן החזקה חלה עליו והוא צריך לסתור אותה.', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_2, 'ג', 'המועמד לא ייפסל, שכן עילת הפסילה חלה רק על שהייה של שבע שנים ומעלה.', false, 'בחירה זו שגויה. סעיף 7א(א1) קובע ''בשבע השנים שקדמו'', כלומר, גם שהייה קצרה יותר בתוך תקופה זו יכולה להקים את החזקה, אם כי לשון הסעיף היא ''בשבע השנים'' ולא ''לפחות שבע שנים''. עם זאת, הפרשנות המקובלת היא ששהייה בתוך תקופה זו מקימה את החזקה. (נבו - המתמחה, חוקי יסוד, עמ'' 27).', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_2, 'ד', 'המועמד לא ייפסל, שכן שהייה במדינת אויב אינה עילת פסילה בפני עצמה, אלא רק אינדיקציה.', false, 'בחירה זו שגויה. שהייה במדינת אויב מקימה חזקה חוקית לתמיכה במאבק מזוין, שהיא עילת פסילה, אלא אם כן נסתרה (סעיף 7א(א1) לחוק-יסוד: הכנסת).', 4);

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_3, v_sq_id, 'ד', 'סמכות אישור פסילת מועמד מול רשימה',
    4, 'ועדת הבחירות המרכזית החליטה לפסול את רשימת ''התקווה'' מלהתמודד בבחירות לכנסת, וכן החליטה לפסול את מועמד מס'' 2 ברשימת ''התקווה'', מר דוד כהן. מהו ההליך המשפטי הנדרש לאישור או לביטול החלטות אלו?', 'שאלה זו בוחנת את ההבחנה הפרוצדורלית בין פסילת מועמד לפסילת רשימה על ידי ועדת הבחירות המרכזית, כפי שנקבע בסעיף 7א(ב) לחוק-יסוד: הכנסת. היא מדגישה את הדרישה לאישור בית המשפט העליון במקרה של פסילת מועמד, לעומת האפשרות לערער על פסילת רשימה.', 'סעיף 7א(ב) לחוק-יסוד: הכנסת קובע מפורשות כי "החלטת ועדת הבחירות המרכזית כי מועמד מנוע מלהשתתף בבחירות טעונה אישור בית המשפט העליון". כלומר, פסילת מועמד אינה נכנסת לתוקף ללא אישור אקטיבי של בית המשפט העליון. לעומת זאת, החלטת ועדת הבחירות המרכזית לפסול רשימה אינה טעונה אישור כזה, אלא ניתנת לערעור בפני בית המשפט העליון לפי חוק הבחירות לכנסת (נבו - המתמחה, חוקי יסוד, עמ'' 28; ע"ב 6615/22 שיקלי, רפרנס 19). הבחנה זו משקפת את הרצון להגן באופן מיוחד על זכותו של אדם ספציפי להיבחר, תוך הכרה בכך שפסילת רשימה משפיעה על קבוצה רחבה יותר של מועמדים ובוחרים.',
    'הבלבול בין המונחים ''אישור'' ו''ערעור'' והחלתם באופן שגוי על פסילת מועמד ורשימה.', '["פסילת מועמד", "פסילת רשימה", "אישור בית המשפט העליון", "ערעור", "חוק-יסוד: הכנסת", "ועדת הבחירות המרכזית"]'::jsonb, '**וריאציה 1 — ועדת הבחירות פסלה מועמד ובית המשפט לא אישר:** ועדת הבחירות פסלה מועמד, אך בית המשפט העליון לא אישר את ההחלטה. האם המועמד ייפסל? ← לא, פסילת מועמד טעונה אישור בית המשפט העליון (סעיף 7א(ב) לחוק-יסוד: הכנסת).
**וריאציה 2 — ועדת הבחירות פסלה רשימה והרשימה לא ערערה:** ועדת הבחירות פסלה רשימה, והרשימה לא הגישה ערעור. האם הרשימה תיפסל? ← כן, החלטת ועדת הבחירות לפסול רשימה תקפה אלא אם כן בוטלה בערעור (נבו - המתמחה, חוקי יסוד, עמ'' 28).
**וריאציה 3 — סמכות בית המשפט העליון לפסול מיוזמתו:** האם בית המשפט העליון יכול לפסול מועמד או רשימה מיוזמתו? ← לא, סמכותו היא לבחון החלטות של ועדת הבחירות המרכזית, בין בדרך של אישור ובין בדרך של ערעור (סעיף 7א(ב) לחוק-יסוד: הכנסת).', 'פסילת מועמד על ידי ועדת הבחירות המרכזית טעונה אישור בית המשפט העליון. פסילת רשימה על ידי הוועדה אינה טעונה אישור, אך ניתנת לערעור בפני בית המשפט העליון ← סעיף 7א(ב) לחוק-יסוד: הכנסת.',
    '["חוק-יסוד: הכנסת, סעיף 7א(ב)", "ע\"ב 6615/22 עמיחי שיקלי נ'' יושב ראש ועדת הבחירות המרכזית לכנסת ה-25, יצחק עמית (2022)", "נבו - המתמחה חוקי יסוד (2026) | הבחירות לכנסת, עמ'' 28"]'::jsonb
  );
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_3, 'א', 'החלטת הפסילה של הרשימה טעונה אישור בית המשפט העליון, ואילו החלטת הפסילה של המועמד ניתנת לערעור בפניו.', false, 'בחירה זו שגויה. הסדר הפוך: פסילת מועמד טעונה אישור, ופסילת רשימה ניתנת לערעור (סעיף 7א(ב) לחוק-יסוד: הכנסת, נבו - המתמחה, חוקי יסוד, עמ'' 28).', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_3, 'ב', 'החלטת הפסילה של הרשימה ניתנת לערעור בפני בית המשפט העליון, ואילו החלטת הפסילה של המועמד טעונה אישור בית המשפט העליון.', true, 'החלטה זו נכונה. סעיף 7א(ב) לחוק-יסוד: הכנסת קובע כי החלטת ועדת הבחירות המרכזית כי מועמד מנוע מלהשתתף בבחירות טעונה אישור בית המשפט העליון. לעומת זאת, החלטת ועדת הבחירות המרכזית לפסול רשימה אינה טעונה אישור, אולם ניתן להגיש עליה ערעור לבית המשפט העליון לפי חוק הבחירות לכנסת (נבו - המתמחה, חוקי יסוד, עמ'' 28).', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_3, 'ג', 'שתי ההחלטות טעונות אישור של בית המשפט העליון.', false, 'בחירה זו שגויה. רק פסילת מועמד טעונה אישור. פסילת רשימה ניתנת לערעור (סעיף 7א(ב) לחוק-יסוד: הכנסת, נבו - המתמחה, חוקי יסוד, עמ'' 28).', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_3, 'ד', 'שתי ההחלטות ניתנות לערעור בפני בית המשפט העליון.', false, 'בחירה זו שגויה. רק פסילת רשימה ניתנת לערעור. פסילת מועמד טעונה אישור (סעיף 7א(ב) לחוק-יסוד: הכנסת, נבו - המתמחה, חוקי יסוד, עמ'' 28).', 4);

  RAISE NOTICE 'Q% inserted: external_id %', 38, '2022-S-S-Q38';
END
$$;

