-- classifier_note: Car pledge + garage's possessory lien (זכות עיכבון) — priority between secured creditor and possessory lien. Pledge chapter; no dedicated lien subtopic
-- ============================================================
DO $$
DECLARE
  v_sq_id uuid := '21a87a8e-8f3b-4af9-b743-2e8391bff70d'::uuid;
  v_group_id uuid := '4e82c5bd-a7c5-485c-b97f-697cc18b2b38'::uuid;
  v_chapter_id uuid;
  v_subtopic_id uuid;
  v_existing_id uuid;
  v_ang_0 uuid := 'eae0557c-2dae-4370-a0d9-184d9d4c5f50'::uuid;
  v_ang_1 uuid := 'f3fd3c29-2200-4077-bcb5-7a19b00e1c1b'::uuid;
  v_ang_2 uuid := 'd1e343e3-c650-400f-8507-eda0808cf906'::uuid;
  v_ang_3 uuid := 'f6410d07-48dc-4096-a5bc-df4273ab649e'::uuid;
BEGIN
  SELECT id INTO v_existing_id FROM public.source_questions WHERE external_id = '2022-S-S-Q39';
  IF v_existing_id IS NOT NULL THEN
    RAISE NOTICE 'Q% skipped: external_id % already exists', 39, '2022-S-S-Q39';
    RETURN;
  END IF;

  SELECT id INTO v_chapter_id FROM public.chapters WHERE code = 'property';
  IF v_chapter_id IS NULL THEN
    RAISE EXCEPTION 'Chapter code % not found', 'property';
  END IF;

  SELECT id INTO v_subtopic_id FROM public.subtopics WHERE code = 'pledge' AND chapter_id = v_chapter_id;
  IF v_subtopic_id IS NULL THEN
    RAISE EXCEPTION 'Subtopic code % not found under chapter %', 'pledge', 'property';
  END IF;

  INSERT INTO public.source_questions (
    id, question_group_id, version, is_current, external_id, chapter_id, subtopic_id, question_text, source_metadata, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list, notes_for_admin, status, created_by
  ) VALUES (
    v_sq_id, v_group_id, 1, true,
    '2022-S-S-Q39', v_chapter_id, v_subtopic_id, 'פלוני לקח מגוף פיננסי הלוואה לשם רכישת רכב. הרכב מושכן כדין להבטחת חובו של פלוני לגוף הפיננסי והמשכון נרשם. פלוני מתקן את הרכב במוסך קבוע. לאחרונה ביצע המוסך טיפול שוטף ברכבו של פלוני. במהלך הטיפול התגלתה תקלה המחייבת תיקון נפרד, ופלוני סיכם עם בעלי המוסך שיכניס את הרכב בעוד כמה ימים לשם תיקון התקלה. לפיכך לא שילם פלוני על הטיפול השוטף שבוצע ולקח את הרכב. לאחר כמה ימים החזיר את הרכב למוסך לשם תיקון התקלה. מאחר שפלוני לא עמד בהחזרי ההלוואה פעל הגוף הפיננסי למימוש המשכון. מה הדין?',
    '{"exam_year": 2022, "exam_season": "summer", "exam_part": 2, "exam_question_number": 39}'::jsonb, 'השאלה עוסקת בתחרות זכויות בין משכון רשום קודם בזמן לבין זכות עיכבון מאוחרת בזמן, ובפרט בהבחנה בין עיכבון ''רגיל'' לבין ''עיכבון משביח''. היא בוחנת את השפעת אובדן החזקה על זכות העיכבון ואת היקף העדיפות של עיכבון קבלן על פני משכון, בהתאם לסעיף 11 לחוק המיטלטלין, סעיף 5 לחוק חוזה קבלנות והלכת רשות שדות התעופה.', 'סעיף 11(ד) לחוק המיטלטלין, התשל"א-1971, קובע כי "הוציא הנושה ברצונו את המיטלטלין המעוכבים משליטתו, יפקע העיכבון". במקרה הנדון, המוסך שחרר את הרכב לאחר הטיפול השוטף, ולכן זכות העיכבון בגין חוב זה פקעה ולא קמה לתחייה גם כאשר הרכב חזר למוסך (ע"א 6492/00 שלדות מפעלי מתכת בע"מ נ'' מאזן אמין שחיבר, רפרנס 5, 7, 21). לעומת זאת, בגין תיקון התקלה, קמה למוסך זכות עיכבון חדשה מכוח סעיף 5 לחוק חוזה קבלנות, התשל"ד-1974. הפסיקה, ובראשה הלכת *ע"א 790/85 רשות שדות התעופה בישראל נ'' גרוס, כונס הנכסים* (רפרנס 1, 2, 3, 4, 15, 16, 25, 26, 31, 32, 35, 38, 39, 41, 44, 48, 49, 50, 53, 54, 55, 56, 57, 58, 59, 61, 62, 64, 65, 66, 67, 68, 69, 70, 71, 72, 73, 74) והלכת *ע"א 4588/06 אלוניאל בע"מ נ'' כונס הנכסים עו"ד שי גרנות* (רפרנס 1, 4, 31, 39, 49, 50, 70), קבעה כי זכות עיכבון של קבלן, הנובעת ממעשים שהביאו להשבחת הנכס (עיכבון משביח), גוברת על זכות משכון קודמת בזמן, וזאת כהיקף ההשבחה. תיקון תקלה ברכב נחשב כהשבחה. לכן, זכותו של המוסך להיפרע את חובו עבור תיקון התקלה בלבד גוברת על זכות הגוף הפיננסי. (ראו גם *פש"ר (מחוזי י-ם) 39913-07-13 משה גמרו נ'' המנהל המיוחד גיל אפרתי*, רפרנס 20, 21, 22).', 'הטעות הנפוצה היא להחיל את כלל ''ראשון בזמן - ראשון בזכות'' באופן גורף, מבלי להכיר בחריג של העיכבון המשביח, או להתעלם מהשפעת אובדן החזקה על פקיעת זכות העיכבון.',
    '["זכות עיכבון", "משכון", "עדיפות נושים", "עיכבון משביח", "חוק המיטלטלין", "חוק חוזה קבלנות", "אובדן חזקה", "הפרה צפויה"]'::jsonb, '**וריאציה 1 — עיכבון על נכס שלא הושבח:** קבלן עיכב נכס בגין חוב על שירותי שמירה שלא השביחו את הנכס. האם גובר על משכון קודם? ← לא, עיכבון שאינו משביח אינו גובר על משכון קודם (ע"א 4588/06 אלוניאל, רפרנס 1, 4).
**וריאציה 2 — עיכבון שפקע וחזר:** מוסך ביצע תיקון, שחרר את הרכב, ואז קיבל אותו שוב לתיקון אחר. האם זכות העיכבון על התיקון הראשון קמה לתחייה? ← לא, זכות העיכבון פקעה עם שחרור הרכב ולא קמה לתחייה (ע"א 6492/00 שלדות מפעלי מתכת, רפרנס 5, 7, 21).
**וריאציה 3 — עיכבון על חוב שנוי במחלוקת:** מוסך עיכב רכב בגין חוב שגובהו שנוי במחלוקת. האם העיכבון תקף? ← כן, מחלוקת על גובה החוב אינה גורעת מזכות העיכבון, אך על המעכב להמציא פרטים לקציבת הסכום ולפעול בתום לב (רע"א 5095/93 פ.א. ארבן, רפרנס 51, 43).', 'עיכבון קבלן משביח על נכס גובר על משכון קודם, אך רק כהיקף ההשבחה. אובדן חזקה מרצון מפקיע את העיכבון, והוא אינו קם לתחייה על חוב קודם גם אם הנכס חוזר לידי הנושה ← סעיף 11 לחוק המיטלטלין, חוק חוזה קבלנות והלכת רשות שדות התעופה ואלוניאל.', '["חוק המיטלטלין, תשל\"א-1971, סעיף 11", "חוק חוזה קבלנות, תשל\"ד-1974, סעיף 5", "ע\"א 790/85 רשות שדות התעופה בישראל נ'' ד\"ר י'' גרוס, עורך דין, כונס נכסים, מד(3) 185 (1990)", "ע\"א 4588/06 אלוניאל בע\"מ נ'' כונס הנכסים עו\"ד שי גרנות (2009)", "ע\"א 6492/00 שלדות מפעלי מתכת בע\"מ נ'' מאזן אמין שחיבר, נו(5) 925 (2002)", "רע\"א 5095/93 פ.א. ארבן בע\"מ נ'' גבי א.ג.ר. שותפות לבנין ופיתוח, מט(1) 730 (1995)", "פש\"ר (מחוזי י-ם) 39913-07-13 משה גמרו נ'' המנהל המיוחד גיל אפרתי (2015)"]'::jsonb,
    'needs_review=true | classification_review: original chapter=''הוצאה לפועל'' subtopic=''עיקול נכסים'' → mapped chapter=''property'' subtopic=''pledge'' | classifier_note: Car pledge + garage''s possessory lien (זכות עיכבון) — priority between secured creditor and possessory lien. Pledge chapter; no dedicated lien subtopic | source_review_note: הסיווג תחת תת-הנושא ''עיקול נכסים'' הוא הכללי ביותר מבין האפשרויות הקיימות ברשימה הסגורה, אך אינו ספציפי מספיק לנושא ''זכות עיכבון'' ותחרות זכויות. נושא זה הוא בעל חשיבות רבה וראוי לתת-נושא ייעודי תחת דיני קניין/בטוחות.', 'active', 'b9ecdde2-d07e-4761-96ab-05f0ad32d4e3'
  );

  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'א', 'זכותו של המוסך להיפרע את חובו הן עבור הטיפול השוטף הן עבור תיקון התקלה גוברת על זכות הגוף הפיננסי.', false, 'בחירה זו שגויה. זכות העיכבון בגין הטיפול השוטף פקעה כאשר הרכב נלקח מהמוסך, שכן אובדן החזקה מרצון מפקיע את העיכבון.', 1);
  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'ב', 'זכותו של הגוף הפיננסי להיפרע את חובו גוברת על זכות המוסך להיפרע את חובו עבור תיקון התקלה בלבד, שכן רישום המשכון קדם לטיפולים ברכב.', false, 'בחירה זו שגויה. זכות העיכבון בגין תיקון התקלה, בהיותה עיכבון משביח, גוברת על המשכון הקודם בזמן, וזאת בניגוד לכלל ''ראשון בזמן - ראשון בזכות''.', 2);
  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'ג', 'זכותו של המוסך להיפרע את חובו עבור תיקון התקלה בלבד גוברת על זכות הגוף הפיננסי.', true, 'החלטה זו נכונה. זכות העיכבון בגין הטיפול השוטף פקעה עם שחרור הרכב. אולם, זכות העיכבון בגין תיקון התקלה, בהיותה עיכבון משביח, גוברת על המשכון הקודם בזמן, וזאת כהיקף ההשבחה.', 3);
  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'ד', 'זכותו של הגוף הפיננסי להיפרע את חובו הן עבור הטיפול השוטף הן עבור תיקון התקלה, שכן רישום המשכון קדם לטיפולים ברכב.', false, 'בחירה זו שגויה. אף שרישום המשכון קדם, עיכבון משביח גובר על משכון קודם בזמן, וזאת עבור החוב שנוצר בגין ההשבחה.', 4);

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_0, v_sq_id, 'א', 'עיכבון קבלן על מספר עסקאות',
    1, 'קבלן ביצע עבור מזמין עבודות צביעה במסגרת פרויקט בנייה גדול. המזמין לא שילם עבור שלב א'' של העבודות. לאחר מכן, המזמין מסר לקבלן ציוד נוסף לביצוע שלב ב'' של אותו פרויקט. הקבלן עיכב את הציוד החדש עד לתשלום החוב עבור שלב א'' ושלב ב''. מה הדין?', 'שאלה זו בוחנת את היקף זכות העיכבון של קבלן לפי סעיף 5 לחוק חוזה קבלנות, כאשר מערכת היחסים עם המזמין כוללת מספר פעולות או שלבים. היא מתמקדת בשאלה מתי רואים מספר פעולות כ''עסקה אחת'' המקימה זכות עיכבון כוללת, ומתי כ''עסקאות נפרדות'' המקימות זכויות עיכבון נפרדות.', 'סעיף 5 לחוק חוזה קבלנות, התשל"ד-1974, קובע כי "לקבלן תהא זכות עכבון על נכס שמסר לו המזמין לביצוע מלאכתו או למתן שירותו, כדי תשלום הסכומים המגיעים לו מן המזמין עקב עסקת הקבלנות". הפסיקה, ובראשה עניין *ע"א 1776/97 אאורליה ליבוביץ – בית מלאכה לתפירה נ'' גדעון אוברזון – תעשיות אופנה (1976) בע"מ* (רפרנס 37, 38), קבעה כי יש לבחון את מהות ה''עסקה'' בין הצדדים. לא מספר ההסכמים הוא הקובע, אלא האם מדובר במערכת יחסים עסקית כוללת אחת, גם אם היא מבוצעת בשלבים. במקרה כזה, הקבלן זכאי לעכב נכס בגין כל החובות הנובעים מאותה עסקה כוללת. לעומת זאת, אם מדובר בעסקאות נפרדות לחלוטין, זכות העיכבון תקום רק בגין החוב הספציפי לאותו נכס באותה עסקה (ראו גם *פר"ק (מחוזי חי'') 5526-04-15 מפעלי האומן אדן-בכר (1990) בע"מ נ'' כונס הנכסים הרשמי*, רפרנס 23, 25, 36). במקרה הנדון, עבודות הצביעה בשלב א'' ושלב ב'' הן חלק מפרויקט בנייה גדול אחד, ולכן ניתן לראות בהן ''עסקה אחת כוללת'' לעניין זכות העיכבון.',
    'הנחה שגויה כי כל שלב בביצוע עבודה מהווה עסקה נפרדת, מבלי לבחון את הקשר הכולל בין הפעולות ואת מהות העסקה.', '["זכות עיכבון", "חוק חוזה קבלנות", "עסקה אחת כוללת", "עסקאות נפרדות", "היקף העיכבון"]'::jsonb, '**וריאציה 1 — תיקונים שונים באותו רכב:** מוסך תיקן רכב, שחרר אותו, ואז קיבל אותו שוב לתיקון אחר. האם יכול לעכב את הרכב בגין התיקון הראשון? ← לא, אובדן החזקה מפקיע את העיכבון, וכל תיקון נחשב עסקה נפרדת (ע"א 6492/00 שלדות מפעלי מתכת, רפרנס 5, 7, 21).
**וריאציה 2 — שירותי אחסנה מתמשכים:** חברת אחסנה מספקת שירותים ללקוח באופן שוטף. האם יכולה לעכב סחורה חדשה בגין חובות אחסנה קודמים? ← כן, אם מדובר במערכת יחסים עסקית מתמשכת וכוללת, ניתן לראות בכך עסקה אחת (ע"א 1776/97 ליבוביץ, רפרנס 37, 38).
**וריאציה 3 — חובות שונים ללא קשר:** קבלן ביצע עבודות בנכס אחד, והמזמין חייב לו כסף. לאחר מכן, המזמין מסר לקבלן נכס אחר לביצוע עבודה שאינה קשורה. האם הקבלן יכול לעכב את הנכס השני בגין החוב על הנכס הראשון? ← לא, נדרשת זיקה בין הנכס המעוכב לחוב, והיא אינה מתקיימת בעסקאות נפרדות (תא"מ (שלום קריות) 63904-05-17 עמאד אבו ריא, רפרנס 17, 19).', 'קבלן זכאי לעיכבון על נכס בגין כל החובות הנובעים מעסקה אחת כוללת, גם אם היא מבוצעת בשלבים. יש לבחון את מהות העסקה ולא רק את מספר ההסכמים ← סעיף 5 לחוק חוזה קבלנות והלכת ליבוביץ.',
    '["חוק חוזה קבלנות, תשל\"ד-1974, סעיף 5", "ע\"א 1776/97 אאורליה ליבוביץ – בית מלאכה לתפירה נ'' גדעון אוברזון – תעשיות אופנה (1976) בע\"מ, נד(3) 49 (2000)", "פר\"ק (מחוזי חי'') 5526-04-15 מפעלי האומן אדן-בכר (1990) בע\"מ נ'' כונס הנכסים הרשמי (2015)", "ע\"א 6492/00 שלדות מפעלי מתכת בע\"מ נ'' מאזן אמין שחיבר, נו(5) 925 (2002)", "תא\"מ (שלום קריות) 63904-05-17 עמאד אבו ריא נ'' ע.מ. גינון ופיתוח בע\"מ (2018)"]'::jsonb
  );
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_0, 'א', 'הקבלן זכאי לעכב את הציוד החדש רק בגין החוב עבור שלב ב'', שכן מדובר בעסקאות נפרדות.', false, 'בחירה זו שגויה. אם מדובר בעסקה אחת כוללת, הקבלן זכאי לעכב את הנכס בגין כל החובות הנובעים מאותה עסקה, גם אם היא מבוצעת בשלבים.', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_0, 'ב', 'הקבלן זכאי לעכב את הציוד החדש בגין החוב עבור שלב א'' ושלב ב'', שכן מדובר בעסקה אחת כוללת המבוצעת בשלבים.', true, 'החלטה זו נכונה. הפסיקה קבעה כי כאשר מדובר במערכת יחסים עסקית אחת כוללת, גם אם היא מבוצעת בשלבים, הקבלן זכאי לעכב נכס בגין כל החובות הנובעים מאותה עסקה. יש לבחון את מהות העסקה ולא רק את מספר ההסכמים (ע"א 1776/97 ליבוביץ, רפרנס 37, 38; פר"ק (מחוזי חי'') 5526-04-15 מפעלי האומן, רפרנס 23, 25, 36).', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_0, 'ג', 'הקבלן אינו זכאי לעכב את הציוד החדש בגין חובות קודמים, שכן זכות העיכבון חלה רק על חובות שנוצרו בגין הנכס הספציפי המעוכב.', false, 'בחירה זו שגויה. אף שנדרשת זיקה בין הנכס לחוב, כאשר מדובר בעסקה אחת כוללת, הזיקה מתקיימת גם לחובות קודמים באותה עסקה.', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_0, 'ד', 'הקבלן זכאי לעכב את הציוד החדש בגין החוב עבור שלב ב'' בלבד, אלא אם כן הוסכם אחרת בכתב.', false, 'בחירה זו שגויה. ההכרעה תלויה בפרשנות מהות העסקה (האם היא אחת או מספר עסקאות נפרדות), ולא רק בהסכמה כתובה.', 4);

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_1, v_sq_id, 'ב', 'תנאי קיום זכות העיכבון',
    2, 'מהם התנאים המצטברים הנדרשים לקיומה של זכות עיכבון כדין?', 'שאלה זו מתמקדת בתנאים הבסיסיים והמצטברים הנדרשים על פי הדין הישראלי לקיומה של זכות עיכבון. היא מדגישה את הצורך במקור נורמטיבי לזכות, קיומו של חוב בר-פירעון, והחזקה פיזית בנכס, תוך הבחנה בין תנאי קיום לתנאי הפעלה.', 'זכות העיכבון אינה קמה באופן אוטומטי, אלא דורשת עמידה במספר תנאים מצטברים. ראשית, נדרש קיומו של חוב שהגיע מועד פירעונו וטרם נפרע (רע"א 5095/93 פ.א. ארבן בע"מ נ'' גבי א.ג.ר. שותפות לבנין ופיתוח, רפרנס 51, 43). שנית, על הנושה להחזיק בנכס כדין, שכן לזכות העיכבון אופי פוססורי, והיא מותנית בהחזקה רצופה של הנושה בנכס (סעיף 11(ד) לחוק המיטלטלין, רפרנס 7, 12, 14, 16, 26, 42, 44, 45, 52, 53, 56, 62, 63, 68, 69, 71; ע"א 6492/00 שלדות מפעלי מתכת בע"מ נ'' מאזן אמין שחיבר, רפרנס 5, 7). שלישית, נדרש מקור נורמטיבי (חוקי או הסכמי) המקים את זכות העיכבון, שכן סעיף 11 לחוק המיטלטלין אינו יוצר זכות עיכבון אלא רק מסדיר את אופן הפעלתה (פש"ר (מחוזי ת"א) 1710-09 אשיש דיאמונדס בע"מ, רפרנס 9, 11, 15; ת"א (שלום ת"א) 23877-08-21 ליאת בגם, רפרנס 66, 67). תום לב, אף שהוא עקרון יסוד בשימוש בזכויות, אינו תנאי לקיום הזכות אלא לאופן הפעלתה (ת"א (שלום נת'') 50923-01-19 ע.ר.ד. מור בע"מ, רפרנס 42, 43, 48).',
    'הבלבול בין תנאי קיום זכות העיכבון לבין תנאי הפעלתה, או הנחה שגויה כי השבחת הנכס היא תמיד תנאי הכרחי לקיום העיכבון.', '["זכות עיכבון", "חוב בר-פירעון", "החזקה בנכס", "מקור חוקי/הסכמי", "סעיף 11 לחוק המיטלטלין"]'::jsonb, '**וריאציה 1 — חוב שטרם הגיע מועד פירעונו:** קבלן עיכב נכס בגין חוב שמועד פירעונו טרם הגיע. האם העיכבון תקף? ← לא, נדרש חוב שהגיע מועד פירעונו (רע"א 5095/93 פ.א. ארבן, רפרנס 51, 43).
**וריאציה 2 — נכס שהושג שלא כדין:** נושה עיכב נכס שהגיע לידיו שלא כדין. האם העיכבון תקף? ← לא, נדרשת החזקה כדין בנכס (ת"א (שלום ת"א) 56938-12-19 כהן צבי, רפרנס 26).
**וריאציה 3 — עיכבון ללא מקור חוקי/הסכמי:** אדם עיכב נכס של חייב ללא כל הוראת חוק או הסכם המקנה לו זכות עיכבון. האם העיכבון תקף? ← לא, סעיף 11 לחוק המיטלטלין אינו מקנה זכות עיכבון אלא רק מסדיר את הפעלתה, ונדרש מקור נורמטיבי (פש"ר (מחוזי ת"א) 1710-09 אשיש דיאמונדס, רפרנס 9, 11, 15).', 'זכות עיכבון קמה רק אם מתקיימים שלושה תנאים מצטברים: חוב שהגיע מועד פירעונו, החזקה כדין בנכס, ומקור חוקי או הסכמי המקים את הזכות ← סעיף 11 לחוק המיטלטלין והפסיקה בעניין אשיש דיאמונדס וכהן צבי.',
    '["חוק המיטלטלין, תשל\"א-1971, סעיף 11", "רע\"א 5095/93 פ.א. ארבן בע\"מ נ'' גבי א.ג.ר. שותפות לבנין ופיתוח, מט(1) 730 (1995)", "ע\"א 6492/00 שלדות מפעלי מתכת בע\"מ נ'' מאזן אמין שחיבר, נו(5) 925 (2002)", "פש\"ר (מחוזי ת\"א) 1710-09 אשיש דיאמונדס בע\"מ נ'' כונס נכסים רשמי תל אביב (2016)", "ת\"א (שלום ת\"א) 56938-12-19 כהן צבי יזמות והשקעות בע\"מ נ'' אליהו נדל (2024)", "ת\"א (שלום ת\"א) 23877-08-21 ליאת בגם נ'' ירון סקלי (2024)"]'::jsonb
  );
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_1, 'א', 'קיומו של חוב שהגיע מועד פירעונו, החזקה בנכס, והשבחת הנכס על ידי הנושה.', false, 'בחירה זו שגויה. השבחת הנכס אינה תנאי הכרחי לקיום זכות עיכבון, אלא רלוונטית בעיקר לעדיפות העיכבון בתחרות מול נושים מובטחים אחרים.', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_1, 'ב', 'קיומו של חוב שהגיע מועד פירעונו, החזקה בנכס, ומקור חוקי או הסכמי לזכות העיכבון.', true, 'החלטה זו נכונה. הפסיקה קבעה כי תנאי יסוד לקיומה של זכות עיכבון הם קיומו של חוב שהגיע מועד פירעונו, החזקה כדין בנכס, ומקור נורמטיבי (חוקי או הסכמי) המקים את הזכות (ת"א (שלום ת"א) 56938-12-19 כהן צבי, רפרנס 26, 27; פש"ר (מחוזי ת"א) 1710-09 אשיש דיאמונדס, רפרנס 9, 11, 15).', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_1, 'ג', 'החזקה בנכס, תום לב של הנושה, ואישור בית משפט להפעלת העיכבון.', false, 'בחירה זו שגויה. אישור בית משפט אינו נדרש להפעלת העיכבון, שכן הוא סעד עצמי. תום לב הוא תנאי לשימוש בזכות, לא לקיומה.', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_1, 'ד', 'קיומו של חוב קצוב, החזקה בנכס, וזיקה ישירה בין החוב לנכס.', false, 'בחירה זו שגויה. החוב אינו חייב להיות קצוב, ונדרש מקור חוקי/הסכמי לזכות, לא רק זיקה ישירה (רע"א 5095/93 פ.א. ארבן, רפרנס 51; ת"א (שלום ת"א) 23877-08-21 ליאת בגם, רפרנס 66, 67).', 4);

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_2, v_sq_id, 'ג', 'עיכבון על נכס שאינו מוחשי',
    3, 'עורך דין מחזיק במסמכים המגולמים בזכויות חוזיות של לקוחו. הלקוח חייב לעורך הדין שכר טרחה. האם עורך הדין יכול לעכב את המסמכים הללו?', 'שאלה זו בוחנת את תחולת זכות העיכבון על נכסים שאינם מוחשיים באופן ישיר, אלא מגולמים במסמכים פיזיים. היא מתייחסת לזכות העיכבון הספציפית של עורך דין לפי חוק לשכת עורכי הדין, ומדגישה את הפרשנות המרחיבה של הפסיקה לגבי ''נכס'' לעניין עיכבון.', 'סעיף 88 לחוק לשכת עורכי הדין, תשכ"א-1961, מקנה לעורך דין זכות עיכבון על מסמכי לקוחו להבטחת שכר טרחתו והוצאותיו. סעיף 11(א) לחוק המיטלטלין, תשל"א-1971, מגדיר עיכבון כזכות לעכב ''מיטלטלין''. אף ש''מיטלטלין'' מוגדרים בסעיף 1 לחוק כ''נכסים מוחשיים חוץ ממקרקעין'', הפסיקה הרחיבה את הפרשנות. בעניין *ע"א 6365/03 ביז''אן טיזאבי נ'' קיומרס (תומס) טיזאבי* (רפרנס 44, 45), נקבע כי אף שעיכבון דורש החזקה פיזית, ניתן לעכב נכס ערטילאי המגולם במסמך מוחשי, כגון שטר מטען או שטר למביא. בדומה, מסמכים המגלמים זכויות חוזיות, אף שהזכויות עצמן אינן מוחשיות, נחשבים כנכס שניתן לעכב, שכן המסמכים עצמם הם מוחשיים ומגלמים את הזכות (ראו גם *ת"א (שלום ת"א) 56938-12-19 כהן צבי יזמות והשקעות בע"מ נ'' אליהו נדל*, רפרנס 26, 82; *ת"א (מחוזי ת"א) 62867-12-16 SMET Groundwater Technics נ'' ליאור כהן*, רפרנס 58).',
    'הנחה שגויה כי זכות עיכבון חלה רק על נכסים מוחשיים ''טהורים'', מבלי להכיר באפשרות לעכב מסמכים המגלמים זכויות לא מוחשיות.', '["זכות עיכבון", "נכסים מוחשיים", "נכסים ערטילאיים", "מסמכים", "חוק לשכת עורכי הדין", "חוק המיטלטלין"]'::jsonb, '**וריאציה 1 — עיכוב כספים בחשבון בנק:** האם בנק יכול לעכב כספים בחשבון לקוח מכוח זכות עיכבון? ← כן, הפסיקה הכירה ב''עיכבון בנקאי'' על כספים בחשבון, שהוא עיכבון הסכמי כללי (בש"פ 8470/22 בנק לאומי לישראל נ'' מדינת ישראל, רפרנס 33, 36).
**וריאציה 2 — עיכוב זכות יוצרים:** האם ניתן לעכב זכות יוצרים של לקוח? ← לא, זכות יוצרים היא זכות ערטילאית שאינה מגולמת במסמך פיזי, ולכן אינה יכולה להיות מושא לעיכבון (ע"א 6365/03 טיזאבי, רפרנס 44).
**וריאציה 3 — עיכוב מקרקעין:** האם ניתן לעכב מקרקעין? ← כן, סעיף 11(ה) לחוק המיטלטלין מחיל את הוראות העיכבון גם על מקרקעין, ובלבד שיש החזקה פיזית בנכס (ע"א 6365/03 טיזאבי, רפרנס 44, 45; בש"א (מחוזי ירושלים) 5992/04 בנק לאומי למשכנתאות, רפרנס 13, 14).', 'זכות עיכבון יכולה לחול על מסמכים פיזיים המגלמים זכויות לא מוחשיות, כגון מסמכים המגולמים בזכויות חוזיות, וזאת מכוח החזקה הפיזית במסמך ← סעיף 88 לחוק לשכת עורכי הדין והלכת טיזאבי.',
    '["חוק לשכת עורכי הדין, תשכ\"א-1961, סעיף 88", "חוק המיטלטלין, תשל\"א-1971, סעיף 11", "ע\"א 6365/03 ביז''אן טיזאבי נ'' קיומרס (תומס) טיזאבי, נט(2) 391 (2004)", "ת\"א (שלום ת\"א) 56938-12-19 כהן צבי יזמות והשקעות בע\"מ נ'' אליהו נדל (2024)", "ת\"א (מחוזי ת\"א) 62867-12-16 SMET Groundwater Technics נ'' ליאור כהן (2019)", "בש\"פ 8470/22 בנק לאומי לישראל נ'' מדינת ישראל (2023)", "בש\"א (מחוזי ירושלים) 5992/04 בנק לאומי למשכנתאות בע\"מ נ'' בן אבו חברה לבנין ולפיתוח בע\"מ (2006)"]'::jsonb
  );
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_2, 'א', 'לא, זכות העיכבון חלה רק על נכסים מוחשיים בעלי ישות פיזית.', false, 'בחירה זו שגויה. אף שעיכבון דורש החזקה פיזית, הפסיקה הכירה באפשרות לעכב מסמכים המגלמים זכויות, גם אם הזכויות עצמן אינן מוחשיות.', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_2, 'ב', 'כן, עורך דין זכאי לעכב מסמכים המגולמים בזכויות חוזיות של לקוחו, להבטחת שכר טרחתו, שכן המסמכים הם נכס מוחשי המגלם את הזכות.', true, 'החלטה זו נכונה. סעיף 88 לחוק לשכת עורכי הדין מקנה לעורך דין זכות עיכבון על מסמכי לקוחו. הפסיקה הכירה בכך שניתן לעכב נכסים לא מוחשיים המגולמים במסמכים פיזיים, כגון זכויות חוזיות (ע"א 6365/03 טיזאבי, רפרנס 44, 45; ת"א (שלום ת"א) 56938-12-19 כהן צבי, רפרנס 26, 82).', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_2, 'ג', 'כן, אך רק אם המסמכים עצמם הם בעלי ערך כספי עצמאי, ולא רק מגלמים זכויות.', false, 'בחירה זו שגויה. העיכבון חל על המסמכים המגלמים את הזכויות, ואינו מותנה בערך כספי עצמאי של המסמכים עצמם.', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_2, 'ד', 'לא, אלא אם כן הוסכם במפורש בין עורך הדין ללקוח על זכות עיכבון ספציפית למסמכים אלו.', false, 'בחירה זו שגויה. סעיף 88 לחוק לשכת עורכי הדין מקנה זכות עיכבון סטטוטורית לעורך דין, ללא צורך בהסכמה מפורשת.', 4);

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_3, v_sq_id, 'ד', 'מימוש זכות העיכבון',
    4, 'ראובן, בעל מוסך, עיכב רכב של שמעון בגין חוב תיקונים. שמעון מסרב לשלם את החוב. האם ראובן רשאי למכור את הרכב כדי להיפרע מהחוב?', 'שאלה זו עוסקת במהותה של זכות העיכבון כסעד עצמי, ובמגבלות המוטלות על הנושה בעל העיכבון בכל הנוגע למימוש הנכס המעוכב. היא מדגישה את ההבחנה בין זכות להחזיק בנכס כאמצעי לחץ לבין זכות להיפרע ממנו בדרך של מכירה, ומצביעה על השינויים המוצעים בחוק דיני ממונות.', 'זכות העיכבון היא במהותה זכות פוססורית (החזקתית) המהווה סעד עצמי (Self Help) ואמצעי לחץ על החייב, אך אינה מקנה לנושה זכות להיפרע מהנכס המעוכב בדרך של מכירה. הנושה רשאי להחזיק בנכס עד שיסולק החוב, אך אינו רשאי להשתמש בו להנאתו או לממשו (ע"א 790/85 רשות שדות התעופה נ'' גרוס, רפרנס 54, 59, 64; תא"ק (שלום אשד'') 37367-02-20 אפרים מיכל קריין, רפרנס 46; תא"ח (שלום צפת) 2366-05-16 ירדן ב.ש.י.י. נדל"ן, רפרנס 57). עם זאת, בעל עיכבון נחשב לנושה מובטח בהליכי חדלות פירעון (סעיף 1 לפקודת פשיטת הרגל וסעיף 253 לחוק חדלות פירעון ושיקום כלכלי, רפרנס 35, 36, 39, 41, 74), מה שמקנה לו עדיפות על פני נושים כלליים. הצעת חוק דיני ממונות, התשע"א-2011 (''הקודקס האזרחי''), מציעה לחזק את כוחו של העיכבון ולאפשר גם את מימוש הנכס המעוכב בדומה למשכון, אך זו אינה ההלכה המצויה כיום (בש"פ 8470/22 בנק לאומי לישראל נ'' מדינת ישראל, רפרנס 33, 35).',
    'הבלבול בין זכות עיכבון לזכות משכון, והנחה שגויה כי שתיהן מקנות זכות מימוש זהה.', '["זכות עיכבון", "מימוש נכס", "סעד עצמי", "נושה מובטח", "חוק המיטלטלין", "חוק המשכון"]'::jsonb, '**וריאציה 1 — מימוש עיכבון בהסכמה:** ראובן ושמעון הסכימו בכתב שראובן יוכל למכור את הרכב אם שמעון לא ישלם. האם ראובן רשאי למכור? ← כן, עיכבון יכול להיווצר גם מכוח הסכם, והסכם יכול לקבוע הוראות מימוש (סעיף 11(ה) לחוק המיטלטלין, רפרנס 12, 14, 15, 16, 35, 40, 49, 53, 55, 66, 67, 74).
**וריאציה 2 — שימוש בנכס המעוכב:** ראובן השתמש ברכב המעוכב לצורך נסיעותיו הפרטיות. האם מותר לו? ← לא, הנושה אינו רשאי להשתמש בנכס המעוכב להנאתו או להפיק ממנו פירות (תא"ח (שלום צפת) 2366-05-16 ירדן ב.ש.י.י. נדל"ן, רפרנס 57).
**וריאציה 3 — שחרור נכס כנגד ערובה:** שמעון הציע לראובן ערובה בנקאית מספקת לסילוק החוב. האם ראובן חייב לשחרר את הרכב? ← כן, החייב זכאי לשחרר את המיטלטלין מן העיכבון במתן ערובה מספקת אחרת לסילוק החיוב (סעיף 11(ג) לחוק המיטלטלין, רפרנס 12, 14, 15, 16, 26, 41, 43, 48, 51, 52, 53, 61).', 'זכות העיכבון היא בעיקרה זכות להחזיק בנכס כאמצעי לחץ, ואינה מקנה זכות לממשו בדרך של מכירה, אלא אם כן נקבע אחרת בחוק ספציפי או בהסכם. החייב יכול לשחרר את הנכס כנגד ערובה מספקת ← סעיף 11 לחוק המיטלטלין והלכת רשות שדות התעופה.',
    '["חוק המיטלטלין, תשל\"א-1971, סעיף 11", "ע\"א 790/85 רשות שדות התעופה בישראל נ'' ד\"ר י'' גרוס, עורך דין, כונס נכסים, מד(3) 185 (1990)", "בש\"פ 8470/22 בנק לאומי לישראל נ'' מדינת ישראל (2023)", "פקודת פשיטת הרגל [נוסח חדש], תש\"ם-1980, סעיף 1", "חוק חדלות פירעון ושיקום כלכלי, תשע\"ח-2018, סעיף 253", "תא\"ק (שלום אשד'') 37367-02-20 אפרים מיכל קריין נ'' רוי גוילי (2021)", "תא\"ח (שלום צפת) 2366-05-16 ירדן ב.ש.י.י. נדל\"ן והשקעות בע\"מ נ'' חיים בוקובסקי (2016)"]'::jsonb
  );
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_3, 'א', 'כן, זכות העיכבון מקנה לנושה זכות להיפרע מהנכס המעוכב בדרך של מכירה, בדומה למשכון.', false, 'בחירה זו שגויה. זכות העיכבון, ככלל, אינה מקנה לנושה זכות להיפרע מהנכס בדרך של מכירה, אלא רק להחזיק בו כאמצעי לחץ.', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_3, 'ב', 'לא, זכות העיכבון היא זכות להחזיק בנכס בלבד כאמצעי לחץ, ואינה מקנה לנושה זכות לממשו בדרך של מכירה, אלא אם כן נקבע אחרת בחוק ספציפי או בהסכם.', true, 'החלטה זו נכונה. זכות העיכבון היא במהותה זכות פוססורית (החזקתית) המהווה סעד עצמי ואמצעי לחץ על החייב, אך אינה מקנה לנושה זכות להיפרע מהנכס המעוכב בדרך של מכירה, אלא אם כן קיימת הוראה חוקית או הסכמית מפורשת המאפשרת זאת (ע"א 790/85 רשות שדות התעופה, רפרנס 54, 59, 64; בש"פ 8470/22 בנק לאומי לישראל נ'' מדינת ישראל, רפרנס 33, 35).', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_3, 'ג', 'כן, אך רק באישור בית משפט, ובכפוף לכך ששווי הרכב אינו עולה במידה בלתי סבירה על שווי החוב.', false, 'בחירה זו שגויה. אף שבית משפט יכול לאשר מימוש במקרים מסוימים (כגון חדלות פירעון), זה אינו הכלל הרגיל, והיחס בין שווי הנכס לחוב רלוונטי לשחרור חלק מהנכס או מתן ערובה, לא לזכות המימוש.', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_3, 'ד', 'לא, אלא אם כן שמעון נקלע להליכי חדלות פירעון, שאז ראובן ייחשב לנושה מובטח.', false, 'בחירה זו שגויה. אף שבחדלות פירעון ראובן ייחשב לנושה מובטח, עצם מעמדו כנושה מובטח אינו מקנה לו אוטומטית זכות לממש את הנכס בדרך של מכירה, אלא רק עדיפות בנשייה.', 4);

  RAISE NOTICE 'Q% inserted: external_id %', 39, '2022-S-S-Q39';
END
$$;

