-- classifier_note: Innkeeper liability for stolen items under חוק השומרים — bailment/safekeeping law. Closest substantive home is lease_bailment
-- ============================================================
DO $$
DECLARE
  v_sq_id uuid := '71cab5d3-d28f-4741-893c-00a3a74dc234'::uuid;
  v_group_id uuid := 'e6d1766d-fded-44ad-b1ce-a2ce4a9d002f'::uuid;
