  v_existing_id uuid;
  v_ang_0 uuid := 'd3727524-b98a-435a-b9dd-4cbb9d41e209'::uuid;
  v_ang_1 uuid := '5eb525ec-a9ec-4d23-b81c-111f1a53f89a'::uuid;
  v_ang_2 uuid := 'e4a434e5-1dba-4e71-a804-58f27ac13b4a'::uuid;
  v_ang_3 uuid := 'a236c166-5213-4639-b318-d0c67a52a439'::uuid;
BEGIN
