  INSERT INTO public.source_questions (
    id, question_group_id, version, is_current, external_id, chapter_id, subtopic_id, question_text, source_metadata, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list, notes_for_admin, status, created_by
  ) VALUES (
    v_sq_id, v_group_id, 1, true,
    '2022-S-S-Q40', v_chapter_id, v_subtopic_id, 'בני הזוג כהן שהו בחופשה בבית מלון. בני הזוג שבו לחדרם לאחר שנעדרו ממנו לכמה שעות וגילו כי נגנבו מהם תכשיטים יקרים, חליפה של מר כהן, נעליים חדשות של גב'' כהן ובשמים. בני הזוג מבקשים לתבוע את בית המלון. מה הדין?',
    '{"exam_year": 2022, "exam_season": "summer", "exam_part": 2, "exam_question_number": 40}'::jsonb, 'השאלה עוסקת באחריות בעל מלון לנכסי אורחיו שנגנבו מחדרם, בהתאם לחוק השומרים. היא בוחנת את מעמד המלון כ''שומר שכר עיקרי'' לנכסים רגילים, ואת החריג הקבוע בחוק לגבי ''חפצי ערך'' הדורשים הודעה ומסירה ספציפית למלון, תוך התייחסות לנטל ההוכחה המוטל על המלון.', 'סעיף 12(ב) לחוק השומרים, תשכ"ז-1967, קובע כי "לעניין נכסים של אורח הנמצאים במלון, דין בעל המלון כדין שומר שכר". הפסיקה המקובלת מפרשת הוראה זו כקובעת כי המלון הוא ''שומר שכר עיקרי'' (ת"א (שלום אש'') 28281-07-18 רינה ג''ורי נ'' מלון רויאל ביץ'', רפרנס 1, 3; ת"א (שלום ת"א) 66029-07 דנוך מרים נ'' ישרוטל בע"מ, רפרנס 5, 6; ת"א (שלום חי'') 17748-02-24 ירון בן שושן נ'' אחוזות בגליל בע"מ, רפרנס 7, 8, 13, 14, 15, 18, 20). אחריותו של שומר שכר עיקרי היא מוגברת: הוא אחראי לאובדן הנכס או לנזקו, זולת אם נגרמו עקב נסיבות שלא היה עליו לחזותן מראש ולא יכול היה למנוע תוצאותיהן (סעיף 2(ב) רישא לחוק השומרים). כלומר, נטל ההוכחה לפטור מוטל על המלון. עם זאת, סעיף 12(ג) לחוק השומרים קובע חריג מיוחד ל"כספים, ניירות ערך או חפצי ערך אחרים". לגבי נכסים אלו, המלון אינו אחראי אלא אם האורח הודיע עליהם ומסרם, לפי דרישתו, להחזקתו. תכשיטים יקרים נחשבים לחפצי ערך (ת"א 28281-07-18 ג''ורי, רפרנס 4). מכיוון שבני הזוג לא הודיעו למלון על התכשיטים ולא מסרו אותם, המלון פטור מאחריות לגביהם. לגבי החליפה, הנעליים והבשמים, אלו נחשבים לנכסים רגילים, ולכן המלון יהיה אחראי לגניבתם אלא אם יוכיח שהגניבה אירעה בנסיבות שלא ניתן היה לצפות או למנוע.', 'הטעות הנפוצה היא להחיל את אחריות המלון באופן אחיד על כל סוגי הנכסים, מבלי להבחין בין נכסים רגילים ל''חפצי ערך'' ומבלי להתייחס לדרישות הספציפיות של סעיף 12(ג) לחוק השומרים.',
    '["חוק השומרים", "אחריות מלון", "שומר שכר עיקרי", "חפצי ערך", "נכסים רגילים", "נטל הוכחה", "סעיף 12(ב)", "סעיף 12(ג)"]'::jsonb, '**וריאציה 1 — גניבת כסף מזומן:** נגנב כסף מזומן מהחדר. האם המלון אחראי? ← לא, כסף מזומן נחשב ''כספים'' לפי סעיף 12(ג), והמלון פטור ללא הודעה ומסירה (ת"א 28281-07-18 ג''ורי, רפרנס 4).
**וריאציה 2 — גניבת מחשב נייד:** נגנב מחשב נייד מהחדר. האם המלון אחראי? ← מחשב נייד נחשב בדרך כלל לנכס רגיל, ולכן המלון אחראי כ''שומר שכר עיקרי'' אלא אם יוכיח נסיבות בלתי צפויות/נמנעות (נבו - המתמחה, חוק השומרים, עמ'' 121).
**וריאציה 3 — המלון התרשל:** המלון התרשל באופן חמור בשמירה. האם הוא עדיין פטור מחפצי ערך שלא נמסרו? ← כן, הפטור לפי סעיף 12(ג) הוא מוחלט ללא הודעה ומסירה, ואינו תלוי ברשלנות המלון (ת"א 28281-07-18 ג''ורי, רפרנס 2, 4).', 'מלון אחראי כשומר שכר עיקרי לנכסים רגילים (חליפה, נעליים, בשמים), וייפטר רק אם יוכיח נסיבות בלתי צפויות/נמנעות. לגבי חפצי ערך (תכשיטים יקרים), המלון פטור מאחריות אלא אם האורח הודיע ומסרם להחזקתו ← סעיפים 2(ב), 12(ב) ו-12(ג) לחוק השומרים.', '["חוק השומרים, תשכ\"ז-1967, סעיף 2(ב)", "חוק השומרים, תשכ\"ז-1967, סעיף 12(ב)", "חוק השומרים, תשכ\"ז-1967, סעיף 12(ג)", "ת\"א (שלום אש'') 28281-07-18 רינה ג''ורי נ'' מלון רויאל ביץ'' (2022)", "ת\"א (שלום ת\"א) 66029-07 דנוך מרים נ'' ישרוטל בע\"מ (2013)", "ת\"א (שלום חי'') 17748-02-24 ירון בן שושן נ'' אחוזות בגליל בע\"מ (2025)", "נבו - המתמחה דיני קניין (2026) | חוק השומרים, התשכ\"ז-1967, עמ'' 121"]'::jsonb,
    'needs_review=true | classification_review: original chapter=''סדר דין אזרחי'' subtopic=''הליכים'' → mapped chapter=''contracts'' subtopic=''lease_bailment'' | classifier_note: Innkeeper liability for stolen items under חוק השומרים — bailment/safekeeping law. Closest substantive home is lease_bailment | source_review_note: השאלה עוסקת באחריות בעל מלון לפי חוק השומרים, שהוא דין מהותי. הסיווג תחת ''סדר דין אזרחי'' ותת-הנושא ''הליכים'' אינו מדויק, שכן השאלה אינה עוסקת בפרוצדורה אלא במהות האחריות. נושא זה מתאים יותר לתחום ''דיני קניין'' או ''דיני חיובים'' (בפרט ''דיני שמירה''), אך אלו אינם תת-נושאים ברשימה הסגורה. נבחר ''הליכים'' כברירת מחדל הקרובה ביותר מתוך הרשימה הסגורה, בהתחשב בכך שמדובר בתביעה אזרחית.', 'active', 'b9ecdde2-d07e-4761-96ab-05f0ad32d4e3'
  );

  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'א', 'בית המלון אחראי לפצות את בני הזוג על כל מה שנגנב, אלא אם כן יוכח כי לא התרשל בדבר.', false, 'בחירה זו שגויה. אחריות המלון לנכסים רגילים היא אחריות מוגברת של שומר שכר עיקרי, הפוטרת אותו רק אם יוכיח שהנזק נגרם בנסיבות שלא יכול היה לחזות או למנוע, ולא רק שלא התרשל. בנוסף, היא מתעלמת מהחריג לחפצי ערך.', 1);
  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'ב', 'בית המלון אחראי לפצות את בני הזוג על כל מה שנגנב, אלא אם כן יוכח כי הגנבה אירעה בנסיבות שלא ניתן היה לצפות או למנוע.', false, 'בחירה זו שגויה. אף שהיא מתארת נכון את אחריות המלון לנכסים רגילים, היא מתעלמת מהחריג הקבוע בסעיף 12(ג) לחוק השומרים לגבי חפצי ערך, עליהם המלון אינו אחראי ללא הודעה ומסירה.', 2);
  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'ג', 'בית המלון אחראי לפצות את בני הזוג על כל מה שנגנב למעט התכשיטים, אלא אם כן יוכח כי לא התרשל בדבר.', false, 'בחירה זו שגויה. אחריות המלון לנכסים רגילים היא אחריות מוגברת של שומר שכר עיקרי, הפוטרת אותו רק אם יוכיח שהנזק נגרם בנסיבות שלא יכול היה לחזות או למנוע, ולא רק שלא התרשל.', 3);
  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'ד', 'בית המלון אחראי לפצות את בני הזוג על כל מה שנגנב למעט התכשיטים, אלא אם כן יוכח כי הגנבה אירעה בנסיבות שלא ניתן היה לצפות או למנוע.', true, 'החלטה זו נכונה. לפי סעיף 12(ב) לחוק השומרים, דין בעל המלון כדין שומר שכר. הפסיקה קבעה כי המלון הוא שומר שכר עיקרי לנכסים רגילים, ואחריותו מוגברת – הוא פטור רק אם יוכיח שהנזק נגרם בנסיבות שלא יכול היה לחזות או למנוע (סעיף 2(ב) רישא). לגבי תכשיטים יקרים, שהם ''חפצי ערך'', סעיף 12(ג) קובע פטור למלון מאחריות אלא אם כן האורח הודיע עליהם ומסרם להחזקתו, דבר שלא צוין בשאלה.', 4);

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_0, v_sq_id, 'א', 'אחריות מלון לגניבת רכב מחניון',
    1, 'אורח במלון החנה את רכבו בחניון המלון, שהיה מגודר ומרושת במצלמות אבטחה. במהלך שהותו, רכבו נגנב מהחניון. האם המלון אחראי לגניבת הרכב?', 'שאלה זו בוחנת את אחריות בעל מלון לגניבת רכב מחניון המלון, בהתאם לסעיף 12 לחוק השומרים. היא מתמקדת בפרשנות המונח ''נכסים הנמצאים במלון'' ובסוג אחריותו של המלון (שומר שכר עיקרי), תוך התייחסות למאפייני החניון.', 'סעיף 12(ב) לחוק השומרים, תשכ"ז-1967, קובע כי "לעניין נכסים של אורח הנמצאים במלון, דין בעל המלון כדין שומר שכר". הפסיקה הרחיבה את הפרשנות לתיבה "נכסים הנמצאים במלון" וקבעה כי היא כוללת גם רכב המוחנה בחניון המלון, במיוחד כאשר מדובר בחניון מגודר, סגור ומפוקח (ת"א (שלום חי'') 17748-02-24 ירון בן שושן נ'' אחוזות בגליל בע"מ, רפרנס 7, 8, 14, 15, 18, 20). הגישה הרווחת בפסיקה היא לראות בבעל מלון ''שומר שכר עיקרי'' לנכסים אלו (ת"א 17748-02-24 בן שושן, רפרנס 7, 8, 13, 14, 15, 18, 20; ת"א (שלום ת"א) 66029-07 דנוך מרים נ'' ישרוטל בע"מ, רפרנס 5, 6). אחריותו של שומר שכר עיקרי היא מוגברת, והוא פטור מאחריות רק אם יוכיח שהנזק נגרם עקב נסיבות שלא היה עליו לחזותן מראש ולא יכול היה למנוע את תוצאותיהן (סעיף 2(ב) רישא לחוק השומרים).',
    'הנחה שגויה כי אחריות המלון מוגבלת לחדרי האירוח בלבד, או כי חניון אינו חלק מ''שטח המלון'' לעניין חוק השומרים.', '["חוק השומרים", "אחריות מלון", "שומר שכר עיקרי", "נכסים הנמצאים במלון", "גניבת רכב", "חניון"]'::jsonb, '**וריאציה 1 — חניון פתוח לציבור:** רכב נגנב מחניון מלון פתוח לציבור הרחב. האם המלון אחראי? ← ייתכן שהאחריות תהיה פחותה או שלא תוטל כלל, שכן היעדר פיקוח ושליטה מפחית את מעמד המלון כשומר (ת"א 17748-02-24 בן שושן, רפרנס 10, 17).
**וריאציה 2 — רכב שהוצת בזדון:** רכב הוצת בזדון בחניון המלון. האם המלון פטור? ← לא בהכרח. המלון ייפטר רק אם יוכיח שההצתה היא נסיבה שלא יכול היה לחזות או למנוע, ונטל ההוכחה עליו (ת"א 17748-02-24 בן שושן, רפרנס 7, 20).
**וריאציה 3 — תניית פטור בחניון:** שלט בחניון המלון קובע שהמלון אינו אחראי לגניבות. האם השלט פוטר את המלון? ← לא, תניית פטור כללית אינה גוברת על הוראות חוק השומרים, במיוחד לאור אחריותו המוגברת של המלון (ת"א 17748-02-24 בן שושן, רפרנס 9).', 'מלון אחראי כשומר שכר עיקרי לגניבת רכב מחניון המלון (במיוחד אם מפוקח), וייפטר רק אם יוכיח נסיבות בלתי צפויות/נמנעות. ''נכסים הנמצאים במלון'' כולל חניון ← סעיף 12(ב) לחוק השומרים והלכת בן שושן.',
    '["חוק השומרים, תשכ\"ז-1967, סעיף 12(ב)", "חוק השומרים, תשכ\"ז-1967, סעיף 2(ב)", "ת\"א (שלום חי'') 17748-02-24 ירון בן שושן נ'' אחוזות בגליל בע\"מ (2025)", "ת\"א (שלום ת\"א) 66029-07 דנוך מרים נ'' ישרוטל בע\"מ (2013)", "ת\"ק (תביעות קטנות ב\"ש) 22879-07-12 עמיחי שלום נ'' ישרוטל בע\"מ (2013)"]'::jsonb
  );
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_0, 'א', 'לא, המלון אינו אחראי, שכן חניון אינו נחשב ''נמצא במלון'' לעניין חוק השומרים.', false, 'בחירה זו שגויה. הפסיקה הרחיבה את הפרשנות ל''נמצאים במלון'' וקבעה כי היא כוללת גם חניון, במיוחד חניון מגודר ומפוקח (ת"א 17748-02-24 בן שושן, רפרנס 7, 8).', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_0, 'ב', 'כן, המלון אחראי כ''שומר שכר עיקרי'', וייפטר מאחריות רק אם יוכיח שהגניבה אירעה בנסיבות שלא יכול היה לחזות או למנוע.', true, 'החלטה זו נכונה. הפסיקה קבעה כי התיבה ''נכסים הנמצאים במלון'' בסעיף 12(ב) לחוק השומרים כוללת גם רכב המוחנה בחניון המלון, במיוחד אם הוא מגודר ומפוקח. במקרים אלו, המלון נחשב ל''שומר שכר עיקרי'' ואחריותו מוגברת, כלומר הוא פטור רק אם יוכיח שהנזק נגרם בנסיבות שלא יכול היה לחזות או למנוע (ת"א 17748-02-24 בן שושן, רפרנס 7, 8, 9, 10, 14, 15, 18, 20).', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_0, 'ג', 'כן, המלון אחראי כ''שומר שכר טפל'', וייפטר מאחריות אם יוכיח שלא התרשל.', false, 'בחירה זו שגויה. אף שקיימת דעה בפסיקה הרואה במלון שומר שכר טפל במקרים מסוימים (ת"ק 22879-07-12 שלום, רפרנס 16, 17), הגישה הרווחת, במיוחד לגבי חניונים מפוקחים, היא לראות בו שומר שכר עיקרי (ת"א 17748-02-24 בן שושן, רפרנס 7, 8, 13, 14, 15, 18, 20).', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_0, 'ד', 'לא, אלא אם כן האורח מסר את מפתחות הרכב לעובד המלון.', false, 'בחירה זו שגויה. אף שמסירת מפתחות מחזקת את אחריות המלון, היא אינה תנאי הכרחי להטלת אחריות, שכן סעיף 12 לחוק השומרים מטיל אחריות גם כאשר הנכס נשאר בחזקת האורח (ת"א 17748-02-24 בן שושן, רפרנס 12, 13).', 4);

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_1, v_sq_id, 'ב', 'הבחנה בין שומר שכר עיקרי לטפל',
    2, 'מהו המבחן המבחין בין ''שומר שכר עיקרי'' ל''שומר שכר טפל'' לפי חוק השומרים, ומהי נפקות ההבחנה לעניין אחריותם?', 'שאלה זו עוסקת בהבחנה המרכזית בחוק השומרים בין שומר שכר ''עיקרי'' ל''טפל'', ובנפקותה לעניין היקף אחריותם. היא בוחנת את המבחן שנקבע בסעיף 2(ב) לחוק ואת נטל ההוכחה המוטל על כל אחד מסוגי השומרים.', 'סעיף 2(ב) לחוק השומרים, תשכ"ז-1967, מבחין בין שני סוגים של שומרי שכר לעניין היקף אחריותם. המבחן המרכזי הוא האם "המטרה לשמור על הנכס היתה טפלה למטרה העיקרית של החזקתו". אם השמירה אינה טפלה למטרה העיקרית (כלומר, השומר הוא ''שומר שכר עיקרי''), אחריותו מוגברת: הוא אחראי לאובדן הנכס או לנזקו, זולת אם נגרמו עקב נסיבות שלא היה עליו לחזותן מראש ולא יכול היה למנוע תוצאותיהן. לעומת זאת, אם המטרה לשמור על הנכס הייתה טפלה למטרה העיקרית של החזקתו (כלומר, השומר הוא ''שומר שכר טפל''), אחריותו מצומצמת יותר: הוא פטור אם אובדן הנכס או נזקו נגרמו שלא ברשלנותו (שירלי רנר, חוק השומרים, עמ'' 18; נבו - המתמחה, חוק השומרים, עמ'' 118; ת"א (שלום ת"א) 66029-07 דנוך מרים נ'' ישרוטל בע"מ, רפרנס 5, 6).',
    'הבלבול בין אחריות שומר שכר עיקרי לאחריות שומר שכר טפל, והחלת נטל הוכחה שגוי על אחד מהם.', '["שומר שכר עיקרי", "שומר שכר טפל", "חוק השומרים", "אחריות מוגברת", "נטל הוכחה", "מטרת השמירה"]'::jsonb, '**וריאציה 1 — שוכר רכב:** שוכר רכב. האם הוא שומר שכר עיקרי או טפל? ← שוכר נחשב לשומר שכר טפל, שכן מטרת השמירה טפלה למטרת השימוש ברכב (סעיף 24 לחוק השכירות והשאילה).
**וריאציה 2 — חברת אבטחה:** חברת אבטחה ששכרה חברה אחרת לשמור על ציוד יקר. האם היא שומר שכר עיקרי או טפל? ← חברת אבטחה היא שומר שכר עיקרי, שכן מטרתה העיקרית היא השמירה (שירלי רנר, חוק השומרים, עמ'' 18).
**וריאציה 3 — קבלן המבצע עבודה בנכס:** קבלן שמבצע עבודה בנכס של מזמין. האם הוא שומר שכר עיקרי או טפל? ← קבלן נחשב לשומר שכר עיקרי, שכן שמירת הנכס אינה טפלה למטרת ביצוע העבודה (סעיף 6(ב)(1) לחוק חוזה קבלנות).', 'שומר שכר עיקרי (שמירה אינה טפלה) פטור רק מנסיבות בלתי צפויות/נמנעות. שומר שכר טפל (שמירה טפלה) פטור אם לא התרשל ← סעיף 2(ב) לחוק השומרים.',
    '["חוק השומרים, תשכ\"ז-1967, סעיף 2(ב)", "חוק השומרים, תשכ\"ז-1967, סעיף 1(ג)", "חוק השכירות והשאילה, תשל\"א-1971, סעיף 24", "חוק חוזה קבלנות, תשל\"ד-1974, סעיף 6(ב)(1)", "שירלי רנר חוק השומרים, תשכ״ז - 1967 - פירוש לחוקי החוזים (1998) | סעיף 2 – אחריות שומרים, עמ'' 18", "נבו - המתמחה דיני קניין (2026) | חוק השומרים, התשכ\"ז-1967, עמ'' 118", "ת\"א (שלום ת\"א) 66029-07 דנוך מרים נ'' ישרוטל בע\"מ (2013)"]'::jsonb
  );
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_1, 'א', 'שומר שכר עיקרי מקבל תמורה כספית, ואילו שומר שכר טפל מקבל טובת הנאה אחרת. אחריותם זהה.', false, 'בחירה זו שגויה. ההבחנה אינה בתמורה אלא במטרת השמירה. שניהם מקבלים תמורה או טובת הנאה, אך אחריותם שונה (סעיף 1(ג) ו-2(ב) לחוק השומרים).', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_1, 'ב', 'המבחן הוא האם המטרה לשמור על הנכס הייתה טפלה למטרה העיקרית של החזקתו. שומר שכר עיקרי פטור רק אם הנזק נגרם בנסיבות בלתי צפויות/נמנעות, ואילו שומר שכר טפל פטור אם יוכיח שלא התרשל.', true, 'החלטה זו נכונה. סעיף 2(ב) לחוק השומרים קובע את המבחן ואת נפקותו. שומר שכר עיקרי (כאשר השמירה אינה טפלה) אחראי אלא אם הנזק נגרם עקב נסיבות שלא היה עליו לחזותן מראש ולא יכול היה למנוע תוצאותיהן. שומר שכר טפל (כאשר השמירה טפלה) פטור אם יוכיח שלא התרשל (שירלי רנר, חוק השומרים, עמ'' 18; נבו - המתמחה, חוק השומרים, עמ'' 118).', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_1, 'ג', 'המבחן הוא האם השומר מחזיק בנכס כדין. שומר שכר עיקרי מחזיק כדין, ואילו שומר שכר טפל אינו מחזיק כדין. אחריותם זהה.', false, 'בחירה זו שגויה. שניהם מחזיקים בנכס כדין. ההבחנה היא במטרת השמירה, לא בעצם ההחזקה (סעיף 1(א) ו-2(ב) לחוק השומרים).', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_1, 'ד', 'שומר שכר עיקרי אחראי באחריות מוחלטת, ואילו שומר שכר טפל אחראי רק אם התרשל. המבחן הוא האם הנכס הושבח על ידי השומר.', false, 'בחירה זו שגויה. אחריות שומר שכר עיקרי אינה מוחלטת אלא מוגברת. המבחן אינו השבחת הנכס, אלא האם השמירה טפלה למטרה העיקרית של ההחזקה (סעיף 2(ב) לחוק השומרים).', 4);

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_2, v_sq_id, 'ג', 'תניית פטור של מלון מאחריות',
    3, 'בני הזוג לוי התארחו במלון. בטופס קבלת האורח עליו חתמו, נכתב במפורש כי ''הנהלת המלון אינה אחראית לאובדן דברי ערך, ולרשות האורחים כספת בחדרים''. בני הזוג לא השתמשו בכספת, ונגנבו מהם תכשיטים יקרים. האם תניית הפטור פוטרת את המלון מאחריות?', 'שאלה זו בוחנת את תוקפן של תניות פטור מאחריות בבתי מלון, בהקשר של גניבת חפצי ערך. היא מתמקדת בסעיף 12(ג) לחוק השומרים, הדורש הודעה ומסירה של חפצי ערך למלון, ובהשלכות אי-עמידה בדרישה זו על אחריות המלון.', 'סעיף 12(ג) לחוק השומרים, תשכ"ז-1967, קובע חריג לאחריות המלון: "היו הנכסים כספים, ניירות ערך או חפצי ערך אחרים, לא יחול סעיף קטן (ב) אלא אם הודיע עליהם האורח לבעל המלון ומסרם, לפי דרישתו, להחזקתו". הפסיקה קבעה כי הצבת כספת בחדר והודעה לאורח על קיומה, יחד עם אי-שימוש בה על ידי האורח לאחסון חפצי ערך, מהווה אשם תורם מכריע של האורחים, המצדיק שלילת פיצוי בגין גניבת חפצי ערך אלו (ת"א (שלום אש'') 28281-07-18 רינה ג''ורי נ'' מלון רויאל ביץ'', רפרנס 2, 4). במקרים אלו, המלון פטור מאחריות לחפצי הערך, לא מכוח תניית הפטור החוזית כשלעצמה, אלא מכוח הוראת החוק הספציפית בסעיף 12(ג) והתנהלות האורח (ת"א (שלום ת"א) 66029-07 דנוך מרים נ'' ישרוטל בע"מ, רפרנס 5, 6).',
    'הנחה שגויה כי תניית פטור כללית פוטרת את המלון מאחריות באופן גורף, מבלי להבחין בין נכסים רגילים לחפצי ערך, ומבלי להתייחס לדרישות הספציפיות של סעיף 12(ג).', '["חוק השומרים", "חפצי ערך", "תניית פטור", "אשם תורם", "אחריות מלון", "כספת"]'::jsonb, '**וריאציה 1 — גניבת נכסים רגילים למרות תניית פטור:** נגנבו בגדים רגילים למרות תניית פטור. האם המלון פטור? ← לא, תניית פטור כללית אינה פוטרת את המלון מאחריותו המוגברת לנכסים רגילים (ת"א 28281-07-18 ג''ורי, רפרנס 2, 4).

**וריאציה 2 — הודעה ומסירה של חפצי ערך:** האורח הודיע למלון על התכשיטים ומסר אותם לכספת המלון. האם המלון אחראי לגניבתם? ← כן, במקרה כזה המלון אחראי כ''שומר שכר עיקרי'' (נבו - המתמחה, חוק השומרים, עמ'' 121).
**וריאציה 3 — תניית פטור ספציפית בחוק:** האם סעיף 12(ג) לחוק השומרים הוא תניית פטור? ← כן, הוא מהווה פטור סטטוטורי לאחריות המלון לחפצי ערך, אלא אם האורח עמד בתנאים (ת"א 28281-07-18 ג''ורי, רפרנס 2, 4).', 'תניית פטור כללית של מלון אינה פוטרת מאחריות לנכסים רגילים. לגבי חפצי ערך, המלון פטור אם האורח לא הודיע ומסרם להחזקתו, גם אם הייתה כספת בחדר ← סעיף 12(ג) לחוק השומרים והלכת ג''ורי.',
    '["חוק השומרים, תשכ\"ז-1967, סעיף 12(ג)", "ת\"א (שלום אש'') 28281-07-18 רינה ג''ורי נ'' מלון רויאל ביץ'' (2022)", "ת\"א (שלום ת\"א) 66029-07 דנוך מרים נ'' ישרוטל בע\"מ (2013)", "נבו - המתמחה דיני קניין (2026) | חוק השומרים, התשכ\"ז-1967, עמ'' 121"]'::jsonb
  );
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_2, 'א', 'כן, תניית הפטור תקפה, שכן היא הוצגה לאורחים והם חתמו עליה.', false, 'בחירה זו שגויה. תניית פטור כללית אינה גוברת על הוראות חוק השומרים, במיוחד לאור סעיף 12(ג) הדורש הודעה ומסירה ספציפית לחפצי ערך, ולא רק הצבת כספת.', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_2, 'ב', 'לא, תניית הפטור אינה תקפה, שכן היא סותרת את אחריותו המוגברת של המלון כשומר שכר עיקרי.', false, 'בחירה זו שגויה. אף שתניית פטור כללית אינה תקפה לנכסים רגילים, לגבי חפצי ערך, סעיף 12(ג) קובע חריג ספציפי המפחית את אחריות המלון, ואינו נסמך על תניית פטור חוזית (ת"א 28281-07-18 ג''ורי, רפרנס 2, 4).', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_2, 'ג', 'כן, תניית הפטור תקפה, שכן היא מהווה הודעה לאורחים על קיומה של כספת, ואי שימוש בה מהווה אשם תורם מלא של האורחים לגניבת חפצי הערך.', true, 'החלטה זו נכונה. סעיף 12(ג) לחוק השומרים קובע כי המלון פטור מאחריות לחפצי ערך אלא אם האורח הודיע עליהם ומסרם להחזקתו. הצבת כספת והודעה על כך, יחד עם אי שימוש בה על ידי האורח, נחשבת לאשם תורם מכריע של האורחים, המצדיק שלילת פיצוי בגין חפצי ערך (ת"א 28281-07-18 ג''ורי, רפרנס 2, 4; ת"א 66029-07 דנוך, רפרנס 5, 6).', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_2, 'ד', 'לא, תניית הפטור אינה תקפה, שכן היא תנאי מקפח בחוזה אחיד.', false, 'בחירה זו שגויה. אף שתניית פטור יכולה להיחשב תנאי מקפח, במקרה של חפצי ערך, הפטור של המלון נובע מהוראת חוק ספציפית (סעיף 12(ג)), ולא רק מתניית הפטור החוזית (ת"א 28281-07-18 ג''ורי, רפרנס 2, 4).', 4);

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text, legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills, quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_3, v_sq_id, 'ד', 'חובת הודעה על נזק לבעל מלון',
    4, 'אורח במלון גילה שנגנבו ממנו חפצים מהחדר. הוא המתין יומיים לפני שדיווח על כך להנהלת המלון. האם המלון יכול להיפטר מאחריות בגין איחור בדיווח?', 'שאלה זו עוסקת בחובת האורח להודיע למלון על אובדן או נזק לנכסיו, ובהשלכות אי-עמידה בחובה זו על אחריות המלון. היא מתמקדת בסעיף 12(ד) לחוק השומרים, הקובע פטור למלון במקרה של איחור בדיווח.', 'סעיף 12(ד) לחוק השומרים, תשכ"ז-1967, קובע כי "בעל מלון פטור מאחריותו לפי סעיף זה, אם לא ניתנה לו הודעה על אבדן הנכס או על נזקו תוך זמן סביר לאחר שנודע על כך לאורח או שהיה עליו לדעת על כך". הוראה זו מטילה חובה על האורח לדווח למלון על אובדן או נזק לנכסיו ב''זמן סביר''. אי-עמידה בחובה זו, כגון המתנה של יומיים, יכולה להוביל לפטור של המלון מאחריות, שכן היא פוגעת ביכולת המלון לחקור את האירוע ולנקוט צעדים מתאימים (נבו - המתמחה, חוק השומרים, עמ'' 121; ת"א (שלום חי'') 17748-02-24 ירון בן שושן נ'' אחוזות בגליל בע"מ, רפרנס 11, 15).',
    'התעלמות מחובת הדיווח המוטלת על האורח, והנחה שגויה כי אחריות המלון היא מוחלטת ללא כל תנאי.', '["חוק השומרים", "חובת הודעה", "זמן סביר", "פטור מאחריות", "אחריות מלון"]'::jsonb, '**וריאציה 1 — דיווח מיידי:** האורח דיווח למלון מיד עם גילוי הגניבה. האם המלון פטור? ← לא, במקרה כזה חובת הדיווח קוימה, והמלון לא ייהנה מהפטור שבסעיף 12(ד) (סעיף 12(ד) לחוק השומרים).
**וריאציה 2 — אי-ידיעה על הגניבה:** האורח לא ידע על הגניבה במשך שבוע, ורק אז דיווח. האם המלון פטור? ← המלון פטור אם האורח ''היה עליו לדעת'' על הגניבה במועד מוקדם יותר, וזהו מבחן אובייקטיבי (סעיף 12(ד) לחוק השומרים).
**וריאציה 3 — דיווח למשטרה בלבד:** האורח דיווח למשטרה אך לא למלון. האם המלון פטור? ← כן, סעיף 12(ד) דורש הודעה ל''בעל המלון'', ולא רק לרשויות (סעיף 12(ד) לחוק השומרים).', 'מלון פטור מאחריות אם לא קיבל הודעה על אובדן/נזק לנכס תוך זמן סביר לאחר שהאורח ידע או היה עליו לדעת ← סעיף 12(ד) לחוק השומרים.',
    '["חוק השומרים, תשכ\"ז-1967, סעיף 12(ד)", "נבו - המתמחה דיני קניין (2026) | חוק השומרים, התשכ\"ז-1967, עמ'' 121", "ת\"א (שלום חי'') 17748-02-24 ירון בן שושן נ'' אחוזות בגליל בע\"מ (2025)"]'::jsonb
  );
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_3, 'א', 'לא, חובת הדיווח חלה רק על חפצי ערך, ולא על נכסים רגילים.', false, 'בחירה זו שגויה. סעיף 12(ד) לחוק השומרים קובע חובת הודעה כללית על אובדן או נזק, ללא הבחנה בין סוגי נכסים.', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_3, 'ב', 'כן, המלון פטור מאחריות אם לא ניתנה לו הודעה על אובדן הנכס או נזקו תוך זמן סביר לאחר שהאורח ידע או היה עליו לדעת על כך.', true, 'החלטה זו נכונה. סעיף 12(ד) לחוק השומרים קובע במפורש כי "בעל מלון פטור מאחריותו לפי סעיף זה, אם לא ניתנה לו הודעה על אבדן הנכס או על נזקו תוך זמן סביר לאחר שנודע על כך לאורח או שהיה עליו לדעת על כך".', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_3, 'ג', 'לא, חובת הדיווח חלה רק אם המלון הוכיח שהאיחור בדיווח גרם לו נזק.', false, 'בחירה זו שגויה. סעיף 12(ד) קובע פטור למלון ללא דרישה להוכחת נזק שנגרם לו מהאיחור, אלא רק את עצם האיחור מעבר ל''זמן סביר''.', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_3, 'ד', 'כן, אך רק אם האיחור בדיווח מנע מהמלון לאתר את הגנב.', false, 'בחירה זו שגויה. הפטור לפי סעיף 12(ד) אינו מותנה בהוכחה שהאיחור מנע את איתור הגנב, אלא בעצם אי-הדיווח ב''זמן סביר''.', 4);

